INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(1, 1, 'Чудное имя открылось нам люди', 30, 'Куплет 1\nЧудное имя открылось нам люди,\nВ Нем воплотилась святая любов.\nДвадцать веков всем, кому трудно\nМир находили в Нем.\nСколько проблем в этом мире бывает,\nИх не решить тебе самому,\nС Именем этим тебя призиваю\nИ с ним я к тебе иду.\n\nПрипев:\nЯ так хочу Твоё имя Иисус постоянно твердить,\nВ любой беде Твое имя Иисус – мне жизнь дарит.\nКогда я с Тобой, в моём сердце покой,\nЯ хочу быть с Тобой, постоянно с Тобой\nИ я счастлив, Господь, что я Твой!\n\nКуплет 2\nСчастье земное так кратко бывает,\nПлатим за счастье мы горькой ценой.\nМиг удовольствий обязательно скажет\nЧас на вернешь бедой.\nНо с Иисусом так не бывает,\nЕсли Он дал, то навсегда!\nЕсли ты Имя это не знаєшь,\nТебе угрожает беда!\n\nКуплет 3\nИзбранны Богом на дело святое,\nНа небесах взяты мы Им\nЧудное счастье, совсем не земное\nНам Иисус подарил.\nС новою жизнью, новым сердцем\nНовые мысли и новое всё\nИ неужели на свете ты знаєшь.\nЛучшее имя еще?', '', '', 'ua', NULL, 0, NULL, NULL),
(2, 2, 'Ты ярче чем солнца свет', 0, 'Куплет 1\nТы ярче, чем солнца свет,\nТы- бездна святой любви,\nНет, знаю, другого нет,\nЕсть, знаю, есть только Ты.\n\nПрипев\nСвят Господь, Свят Господь! Славит Господа земля. \nСвят Господь, Свят Господь! Славит вся Вселенная.\nСвят Господь, Свят Господь! Все приклонимся пред Ним!\nСвят Господь, Свят Господь! Свят Господь наш Элохим!\n\nКуплет 2\nТы славою облечен.\nТы вечно превознесен,\nТы - начало и Ты конец,\nТы, Бог мой, Ты - мой Отец.\n\nКуплет 3\nТы - жизнь, Ты - сама Любовь,\nТы - Агнец, проливший кровь.\nТы славный Спаситель мой,\nИисус, Ты – мой Господь Живой!', '', '', 'ua', NULL, 1, '2020-07-26', NULL),
(3, 3, 'Скоро рассвет нового дня', 0, 'Куплет 1\nСкоро рассвет нового дня, приходит весна,\nУвидим Его таким, как Он есть, \nДа Он встретит меня.\nПридет во славе, мы ждем Его,\nМы ждем, Господь, прихода Твоего.\n\nПриспів\nГряди! Мы – Твой народ и позади\nОставили все и впереди\nНа облаках Ты встретишь нас.\nС Тобой взайдем на небо и в покой,\nОткроешь двери как домой\nВернемся в Отчий дом родной.\nГряди!\n\nКуплет 2\nБудем хвалить Господа мы в наших сердцах,\nБудем петь новою песнь там с Ним в небесах.\nПридет во славе, мы ждем Его\nМы ждем, Господь, прихода Твоего.', '', '', 'ua', NULL, 0, NULL, NULL),
(4, 4, 'Оставил дом забыл Отца', 0, 'Куплет 1\nОставил дом, забыл Отца, ушел далеко,\nУшел в края, где счастья нет, где одиноко.\nЗа каплю, счастья променял свою свободу,\nЗаблудшим сыном стал влачить ты годы.\n\nПрипев\nВернись домой, вернись домой, уж близко к ночи,\nВернись домой, вернись домой, вернись в дом Отчий.\nВернись домой, тебя там ждут и не забыли,\nВернись, вернись, вернись, домой, сын мой.\n\nКуплет 2\nТы в жалких робищах своих обремененный,\nПасешь стада и ешь рожки ведь ты наемный,\nА вспомни прежние года в Отцовском доме,\nНевольно скатится слеза, как вспомнишь.\n\nКуплет 3\nПойду домой, вернусь к отцу, а может, вспомнят,\nПаду к ногам, буду просить, а может примут.\nХотя бы быть в числе прислуг, но рядом с домом,\nПойду домой вернусь к Отцу родному.\n\nКуплет 4\nМой сын пришел, пусть знают все он не заблуший,\nНашелся он, вернулся он, он самый лучший.\nМой дом - его, и все мое его пусть будет\nИ горе жизни пусть он все забудет.', '', '', 'ua', NULL, 0, NULL, NULL),
(5, 5, 'Если устал ты в земном пути', 0, 'Куплет 1\nЕсли устал ты в земном пути,\nВ сердце обиду носишь,\nПодумай, что ждет тебя впереди,\nЧем оправдатся хочешь?\n\nПрипев\nОстановись, оглянись назад,\nДни - словно листья, нас кружат\nКружат, кружат они над землей\nВдаль унося над собой.\nДумай, думай, что делал ты,\nКак направлял свои шаги.\nЗнай,что за каждый поступок твой\nБог на суд приведет!\n\nКуплет 2\nВспомни, как ты ходил по земле...\nО, ка мы тогда блуждали!\nТолько Христос дарует тебе\nВечность блаженного рая.\n\nКуплет 3\nРазве людям дана судьба\nЛишь сверкнуть на мгновенье,\nКак догоревшая звезда,\nВспыхнуть и падать в забвенье', '', '', 'ua', NULL, 0, NULL, NULL),
(6, 6, 'С днем рожденья', 0, 'Куплет 1\nС днем рожденья поздравить хотим,\nПожелать благословения в пути.\nПусть побольше будет в жизни радостных дней,\nПусть любовь Христа горит в тебе сильней.\nА еще я пожелать тебе хочу,\nЧтоб по жизни с Господом был твой путь, \nВолю Божью исполнять до конца\nИ прославить Имя Господа Христа.\n\nПрипев:\nС днем рождения, 2р\nБудь благословен(на) ты и вся жизнь твоя.\nС днем рождения, 2 р.\nПусть сбываются мечты в твой день рождения!!\n\nКуплет 2\nЖизнь твоя пусть будет светом для людей.\nИ пускай не будет боли и скорбей.\nБудь всегда благословением для всех,\nИ во всем пускай придет к тебе успех.\nА еще я пожелать тебе хочу,\nЧтоб по жизни с Господом был твой путь, \nВолю Божью исполнять до конца\nИ прославить Имя Господа Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(7, 7, 'Ты возлюбил этот мир', 30, 'Куплет 1\nТы возлюбил этот мир, чтоб мы любили Тебя,\nЧтоб брат на брата никогда руки не поднимал.\nИ в этот час, о Иисус, мы воздаем Тебе хвалу,\nЗа всё, что сделал Ты для нас, хвала Тебе!\n\nПрипев\nХвала Тебе, Иисус мой,\nЧто Ты пришел на землю для нас,\nХранишь нас в жизни каждый час!\nХвала Тебе, Иисус мой,\nЧто Ты распоряжаешься судьбой,\nВедешь нас в небо, в край родной!\n\nКуплет 2\nМы благодарны Тебе, что научил Ты нас, Иисус,\nЛюбить друг друга как себя, врагов не проклинать.\nИ где б мы не были, Иисус, мы знаем с нами Ты всегда!\nЗа всё, что сделал Ты для нас, хвала Тебе!\n\nКуплет 3\nИ в этот час, о Иисус, мы воздаем Тебе хвалу\nЗа то, что сделал Ты для нас хвала Тебе.', '', '', 'ua', NULL, 0, NULL, NULL),
(8, 8, 'Вічні небеса Бог дарує нам', 0, 'Куплет 1\nВічні небеса Бог дарує нам,\nВірою в Христа будем жити там.\nПісля днів сумних, після днів земних\nЗ радістю ввійдемо до небес Святих!\n\nПриспів\nСонячні висоти Йордан ріки,\nТам-весняний подих на вічні віки!\nТам-наше майбутнє,\nТам-наш вічний дім –\nНовий і могутній Єрусалим!\n\nКуплет 2\nСестри і брати, як одна сім’я,\nВеличайте всі Господа ім’я.\nЗ радістю в серцях, з піснею в устах\nВище піднімайте свій надії стяг.\n\nКуплет 3\nСлухайте усі, Бог говорить нам:\n“Вірним у Христі – землю нову дам.”\nВічні небеса, де свята весна\nБуйним цвітом квітне неземна краса!', '', '', 'ua', NULL, 1, '2020-08-16', NULL),
(9, 9, 'Мій Цар мій Бог', 0, 'Куплет 1\nМій Цар мій Бог /2р. Ти один /2р. \nДаєш мені життя любов і любиш.\nТвоя рука /2р. Веде мене /2р. \nМій кращий друг завжди з Тобою буду.\n\nПриспів\nТільки Ти даруєш серцю радість,\nТільки Ти моє життя змінив.\nТільки Ти лиш освятив мій розум,\nТільки Ти потішив і простив!\n\nКуплет 2\nТи один /2р. Ведеш мене /2р. \nПодав мені нове життя з Тобою.\nТи любиш нас /2р. Дітей своїх /2р.\nВедеш у рай дорогою святою.', '', '', 'ua', NULL, 1, '2020-06-21', NULL),
(10, 10, 'День за днем проходять роки в нікуда', 0, 'Куплет 1\nДень за днем проходять роки в нікуда\nІ ніяк їх не вернути більш назад.\nХай твою стежину сам Бог береже, \nІ до неба вічного приведе.\n\nКуплет 2\nХай дощем краплистим Бог благословить!\nСонечком яскравим душу звеселить!\nПлід рясний для Бога в житті принеси,\nРадість, щастя, мир, хай буде у житті.\n\nКуплет 3\nПісня не змовкає в День народження, \nДзвінко хай лунає ця мелодія.\nВ день ясний і в день сумний\nВ Божих ти руках завжди.\nПам’ятай, що цінний ти!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(11, 11, 'Бог меня отыскал среди холодных скал', 30, 'Куплет 1\n(Но) Бог меня отыскал среди холодных скал,\nСреди заблудших дорог, где я погибнуть мог / 2р.\n\nКуплет 2\n(Но) Он дал мне жизнь Свою, освободил от оков,\nСлаву Ему пою, славу вовеки веков / 2р.\n\nКуплет 3\n(Но) Он есть мой лучший друг, с Ним мне не страшен путь,\nЯ все скажу не тая: любит Иисус меня / 2р.\n\nКуплет 4\n(Но) Даже если беда - рядом Христос всегда,\nЛюбовью меня хранит, мое упованье и щит / 2р.', '', '', 'ua', NULL, 0, NULL, NULL),
(12, 12, 'Al mundo Paz nació Jesús', 0, 'Куплет 1\nAl mundo Paz, nació Jesús,\nnació ya nuestro Rey.\nNació el Salvador,\nÉl es nuestro Señor,\nJesucristo nació,\nJesucristo nació,\ny paz al mundo Él nos dio.\n\nКуплет 2\nAl mundo Paz, el salvador\nen Tierra reinará.\nA cada pecador\nJesús le da perdón,\nJesús le da perdón\nJesús, Jesús le da perdón.\n\nКуплет 3\nAl mundo Paz, gobernará\ncon Gracia y poder:\nnaciones probará\nsu amor y su poder\nsu amor y su poder\nsu amor, su amor y su poder.', '', '', 'ua', NULL, 0, NULL, NULL),
(13, 13, 'Amarte solo a Ti Señor Любить только Тебя ', 0, 'Куплет  1\n/// Amarte solo a Ti Señor, ///\nY no mirar atrás.\n\nКуплет 2\n//Seguir tu caminar Señor,\nSeguir sin desmayar Señor, \nPostrada ante Tu altar Señor, \nY no mirar atrás. //\n\nКуплет 3\n/// Любить только Тебя Господь, ///\nИ не смотреть назад.\n\nКуплет 4\n// Идти только с Тобой Господь,\nИдти не уставать Господь,\nИ преклонятся пред Тобой,\nИ не смотреть назад. //\n\nКуплет\n///Служить только тебе господь/// \nИ не смотреть на зад\nИскать только тебя Господь\nИ жить только для Тебя Господь\nЗа всё благодарю Тебя\nИ не смотреть на зад!!!', '', '', 'ua', NULL, 5, '2020-12-27', NULL),
(14, 14, 'Esta es la gran noticia que llegó', 0, 'Куплет 1\nEsta es la gran noticia que llegó.\nA través de muchos siglos hasta hoy.\n// Y a los pastores despertó,\nA sabios del Oriente guió\nEn esta Nochebuena Él nació,\nnació Jesús.//\n\nКуплет 2\nJesús, lo más valioso para mí\nJesús, es Esperanza para ti\n//Una nueva estrella apareció,\nlos ángeles cantan al Señor\nesta alegría llega hoy al corazón//\n\nКуплет 3\nEn la cruz, la gran victoria Él logró.\nY abrió la puerta a la salvación.\n//Acostado humilde en e pesebre,\nel Hijo de Dios, Gran Rey de Reyes\nLleno de pueza y amor, Jesús.//', '', '', 'ua', NULL, 0, NULL, NULL),
(15, 15, 'Hoy levanto mis manos al cielo', 0, 'Куплет 1\nHoy levanto mis manos al cielo , adorandote Dios Eterno\nTu eres digno de alabanza, Te adora mi corazón.\nYo ya no quiero ser como antes, mas en tu Gloria cambiar anhelo\nMas en Tu amor abundar yo quiero, contigo caminar.\nProclamaré: Jesus me llenas con tu amor\nProclamaré: Jesus te necesito\n\nКуплет 2\nTan solo en Ti puedo encontrar la paz\nTu dulce voz anhelo escuchar\nJesus, Oh Jesus, cambiame, renuevame.\n\nКуплет 3\nВозношу мои руки к небу прославляя Творца Вселенной\nПусть прольется в небеса прославленье из сердца моего\nЯ не хочу быть таким как прежде, но в Твою славу хочу меняться\nВ Твоей любви я хочу купаться, Твоими путями ходить.\nЯ говорю Иисус Твоя любовь во мне, я говорю Иисус Ты нужен мне.\n\nКуплет 4\nВ Тебе одном я нахожу покой, хочу я слышать нежный голос Твой\nИисус, о Иисус будь со мной.', '', '', 'ua', NULL, 0, NULL, NULL),
(16, 16, 'Oh Luz del mundo bajaste a la oscuridad', 0, 'Куплет 1\nOh, Luz del mundo, bajaste a la oscuridad\nMis ojos abriste, pude ver.\nBelleza que causa que mi ser te adore,\nEsperanza de vida en Ti.\n\nПрипев\nVengo a adorarte, vengo a postrarme\nVengo a decirte eres mi Dios.\nEres simplemente bello, simplemente digno\nTan maravilloso para mí.\n\nКуплет 2\nOh Rey eterno, tan alto y exaltado,\nGlorioso en el cielo eres Tu.\nAl mundo que hiciste, humilde viniste,\nPobre te hiciste por amor.\n\nКуплет 3\n//Nunca sabré cuanto costó,\nVer mi pecado en la cruz.//', '', '', 'ua', NULL, 0, NULL, NULL),
(17, 17, 'Señor mi Dios al contemplar los cielos', 0, 'Куплет 1\nSeñor mi Dios, al contemplar los cielos\nEl firmamento y las estrellas mil\nAl oir Tu voz en los potentes truenos\nY ver brillar el sol en su cenit.\n\nКуплет 2\nMi corazón entona la canción\nCuan grande es El,\nСuan grande es El', '', '', 'ua', NULL, 0, NULL, NULL),
(18, 18, 'А ты не думай что тебе тяжело', 0, 'Куплет 1\nА ты не думай, что тебе тяжело,\nА ты не думай, что тебе лишь темно,\nА ты забудь, что на сердце печаль,\nТы помни лишь о том:\n\nКуплет 2\nВ жизни надо успеть на небо посмотреть,\nДруг другу улыбнуться, сказать: “Прости”\nВ жизни надо успеть хоть одну песню спеть,\nМиру радости раздать, руку помощи подать.\n\nКуплет 3\nПомни, тебе надо любить! \nПомни, обиды надо все простить!\nПомни, что другому тяжело,\nТы подставь ему свое плече.\n\nКуплет 4\nПокажи любовь всем, покажи.\nС нежностью на мир ты посмотри.\nПоддержи и словом подскажи,\nТы роздай тепло своей души.\n\nКуплет 5\nПомни тебе надо любить…..', '', '', 'ua', NULL, 0, NULL, NULL),
(19, 19, 'Бачу Бога кожен день', 0, 'Куплет 1\nБачу Бога кожен день,\nяк відкрию вранці свої очі\nВ дивнім небі голубім,\n в перевеслі золотім, як промінь сонця\n\nПриспів\nВсюди Ти, нескінченний Бог Творець,\nНескінченний Бог Отець\nТа незмінний у любові.\nТи милосердний і святий, будь на небі й на землі благословен!\nВсюди Ти Бог благий, слава Тобі, навіки слава!!!\n\nКуплет 3\nБачу Бога кожен день,\nВ райдузі у небі та в дощеві\nВ пелюстках троянде у росі,\nУ птахах що в осені летять у вирій\n\nКуплет 4\nБачу Бога кожен день,\nНа шляху моїм що йде до неба\nВ серці Духом Ти живеш,\nТі пісні, що Ти даєш співать для Тебе', '', '', 'ua', NULL, 2, '2021-01-17', NULL),
(20, 20, 'Благодарю Господь за хлеб насущный', 0, 'Куплет 1\nБлагодарю Господь, за хлеб насущный\nЗа лунный свет в ночи, за раннюю зорю,\nЗа день ушедший и за день грядущий\nТебя, Господь, благодарю.\nБлагодарю за радость обновленья,\nЗа то, что Дух Святой во мне теперь живет\nЩит веры Ты мне дал и шлем спасенья\nХвала Тебе, хвала, Господь\n\nПриспів\nАллилуйя! Аллилуйя!\nСлавлю имя я, что всех имен светлей\nПред Тобой склоняюсь я\nТы один достоин быть Царем Царей.\n\nКуплет 2\nБлагодарю, Господь за кров святую,\nЗа то, что я с Тобой в молитве говорю,\nЗа то, что дал Ты верю мне живую\nТебя, Господь благодарю.\nИ в дивную небесную обитель\nМеня Твоя любовь по жизни проведет\nПрославлен будь вовек Ты мой Спаситель,\nХвала, Тебе, хвала Господь.', '', '', 'ua', NULL, 0, NULL, NULL),
(21, 21, 'Бог призвал нас из разных народов', 0, 'Куплет 1\nБог призвал нас из разных народов\nДал нам имя Свое,\nБог призвал нас из разных племен\nИ дал нам сердце одно.\n\nПрипев\nКогда мы вместе мы сильны\nКогда мы вместе Господь среди нас.\nКогда мы вместе, потоки Божьей любви\nЛьются с небес на нас.\n\nКуплет 2\nМы есть Церковь, мы есть Тело Христа\nМы искуплены кровью Его\nВрата ада нас не одолеют\nПотому что не победимы мы!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(22, 22, 'Бога легко искать Бога легко найти', 0, 'Куплет 1\nБога легко искать, Бога легко найти,\nБог - это благодать, Бог - это свет в пути.\nЭто любовь моя, это добро твое,\nЭто средь бурь маяк ,отдых в конце боев.\n\nКуплет 2\nБог - это первый вздох, первый ребенка крик.\nВ новую жизнь порог, в вечность манящий миг.\nБог - это наш судья, истины вечный страж,\nБог - это суть моя, совести голос наш.\n\nКуплет 3\nБог - это в сотах мед, Бог - это хлеб и соль,\nТот, кто нам мир дает, Тот, кто врачует боль.\nЭто любовь людей, это - прощенье зла,\nЭто в душе моей мощный родник тепла.\n\nКуплет 4\nЭто весенний гром, это осенний дождь,\nЭто по телу дрожь, в храме Его святом.\nЭто молитвы стон, гимнов хваленья звук,\nЭто земной поклон, это скрещенье рук.\n\nКуплет 5\nБог - это вечный дух, это стихий закон.\nБог - это лучший друг, в бедах помощник Он.\nЭто воскресный день, это Голгофский крест,\nЭто благая весть, крыльев могучих сень.', '', '', 'ua', NULL, 0, NULL, NULL),
(23, 23, 'Божа любов велика Божа любов свята', 0, 'Куплет 1\nБожа любов велика, Божа любов свята,\nБожа любов навіки, хто полюбив Христа.\nБожа любов відкрила для вірних небеса,\nБожа любов – це сила, Божа любов – краса.\n\nПрипев\nЛюди, шануйте Бога, Сина любіть Його,\nВ Ньому життя дорога для серця кожного.\nВ Ньому велика радість є для усіх людей,\nВ Ньому і мир, і святість кожна душа знайде.\n\nКуплет 1\nБожа любов зігріє у найскрутнішу мить,\nНаші гріхи покриє , провини всі простить.\nБожа любов нікому не принесла жалю –\nЗ душі знімає втому слово святе: “Люблю.”\n\nКуплет 1\nБожа любов навчає, як в цьому світі жить,\nЛаскою обіймає людей у кожну мить.\nБожа любов хай буде вашим провідником,\nЗ нею душа здобуде вічне життя з Христом.', '', '', 'ua', NULL, 0, NULL, NULL),
(24, 24, 'Боже вічний і праведний ми до тебе звертаємось', 0, 'Куплет 1\\nБоже вічний і праведний, ми до тебе звертаємось,\\nТвоє ім’я прославити серцем чистим бажаємо.\\nЛиш на тебе надіємось, лиш тобі довіряємо,\\nЛиш до тебе, Спасителю, у молитві схиляємось.\\n\\nПриспів\\nБлагослови нас, Господи, хліба пошли щоденного,\\nСвітлом проміння сонячним землю усю зігрій.\\nВся слава тобі Спасителю, подяка тобі Спасителю, \\nЗа вічну любов безмежную, що з неба даруєш всім.\\n\\nКуплет 2\\nМилосердям небесним ти країну голубиш,\\nЗемлю росами чистими омиваєш, бо любиш.\\nІ від подиху ніжного хліб на полі колоситься,\\nІ до неба блакитного ця молитва підноситься.', '[{\"nombre\":\"Куплет 1\",\"veces\":1},{\"nombre\":\"Приспів\",\"veces\":2},{\"nombre\":\"Куплет 2\",\"veces\":3}]', '', 'ukr', '', 0, NULL, '2025-08-01'),
(25, 25, 'Боже предстали по воле Твоей', 0, 'Куплет 1\nБоже, предстали по воле Твоей\nНыне с невестой жених пред Тобой;\nВместе решают пройти путь земной,\nБлагослови Ты союз их святой.\n\nКуплет 2\nЖизни совместной для них будет путь,\nБлиже, о Боже, всегда к ним пребудь;\nВ радости, скорби, печали, труде.\nПусть мысли, чувства их будут одни.\n\nКуплет 3\nО Боже, дай, чтобы в жизни сердца\nБыли друг другу верны до конца;\nЧтоб не прервался союз их святой,\nСам Ты веди их до цели благой.\n\nКуплет 4\nО, возложи, Боже, руку на них,\nВ жизни держаться путей дай Твоих;\nО Боже, мы их приносим в мольбе,\nСам Ты пребудь с ними в жизни везде.', '', '', 'ua', NULL, 0, NULL, NULL),
(26, 26, 'Буду петь Господу во всю жизнь мою', 0, 'Куплет 1\nБуду петь Господу во всю жизнь мою!\nБуду я петь ему доколе я жив!\nДа будет благоприятная песнь моя!\nВозрадуюсь, возвеселюсь я в Господе!\n\nКуплет 2\nБлагослови Господа, душа моя! (4р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(27, 27, 'Буду співати славу складати', 0, 'Куплет 1\nБуду співати, славу складати, \nТому, хто на хресті за мене вмер.\nХто на Голгофі, там був розп´ятий\nВічне життя і щастя мені дав.\n\nПрипев\nЯ співаю Алілуя, хай звучить Тобі хвала\nАлілуя, алілуя, Тебе славить вічно буду я.\n\nКуплет 2\nТобі Одному, Богу Святому\nМоя пісня слави і хвали.\nТи мій Учитель, Творець і Хранитель\nЗа вічну любов я дякую Тобі.\n\nКуплет 3\nХай не змовкає, завжди лунає\nПісня хваління Тобі в наших серцях\nДай Боже сили вірно служити,\nЩоб Тебе славить вічно в небесах.', '[{\"nombre\":\"Куплет 1\",\"veces\":1},{\"nombre\":\"Припев\",\"veces\":2},{\"nombre\":\"Куплет 2\",\"veces\":1},{\"nombre\":\"Припев\",\"veces\":3},{\"nombre\":\"Куплет 3\",\"veces\":1},{\"nombre\":\"Припев\",\"veces\":4},{\"nombre\":\"Куплет 1\",\"veces\":1},{\"nombre\":\"Припев\",\"veces\":4}]', '', 'ua', '', 2, '2020-12-20', '2025-07-24'),
(28, 28, 'В Вифлиємі сталася новина', 0, 'Куплет 1\nВ Віфлеємі сталася новина,\nЗасіяла нова зоря.\nТам пречиста діва Марія\nСина Божого сповила.\n\nПриспів\nОсанна! Осанна! За Сина, що родився нам.\nОсанна! о слава! Для Нього віддаєм свої серця.\n\nКуплет 2\nХори ангелів прославляють\nБога в вишині, мир на землі,\nРазом з ними я заспіваю:\nБог послав спасіння мені!\n\nКуплет 3\nЗ пастухами я прийду до ясел\nІ схилюся низько перед Тим,\nХто звільнив мене від зла й темряви,\nХто моє життя знов засвітив.', '', '', 'ua', NULL, 3, '2021-01-17', NULL),
(29, 29, 'В Иисусе нашел я счастье в Нем одном знаю я покой', 0, 'Куплет 1\nВ Иисусе нашел я счастье, в\n Нем одном знаю я покой.\nИисус, Ты мой искупитель, \nТы - мой Бог, я навеки твой.\n\nПрипев\nИисус, Ты моя защита,\nИисус, Ты мой щит и меч,\nИисус, Ты моя победа,\nТы - мой Бог, Ты - мой Царь вовек.\n\nКуплет 2\nНу, а если бывает в жизни \nнелегко по пути идти,\nТогда я говорю в молитве: \n“Иисус, Ты меня защити.”\n\nКуплет 3\nС Иисусом пойду я смело, \nзнаю, Он меня поведет\nПо дороге к святой Отчизне, \nв Царство света и мир красот.', '', '', 'ua', NULL, 0, NULL, NULL),
(30, 30, 'В кровавой мгле заката созвездье крест зажглось', 0, 'Куплет 1\nВ кровавом мгле заката созвездья крест зажглось,\nСтоял перед Пилатом поруганный Христос.\nЛишь слово в оправданье и снова будешь жить,\nНо можно лишь молчаньем Голгофу заслужить.\n\nКуплет 2\nСкажи, что все неправда, скажи, что Ты - святой\nИ будешь Ты оправдан Пилатом пред толпой.\nХристос, промолви слово кровавым палачам,\nА Он в венце терновом молчал, молчал, молчал.\n\nКуплет 3\nМолчанье - знак согласья, молчанье - это крест.\nС неправдой со участьем для Сына Бога грех,\nА Он покрытый кровью в безмолвии застыл,\nАх, только б до Голгофы дойти хватило сил.\n\nКуплет 4\nБезбожник Он и грешник, распни Его! Распни!\nУдары и насмешки, насмешки и плевки.\nСияет лик прощенья, бессмертие в очах,\nДо славы воскресенья молчать, молчать, молчать.', '', '', 'ua', NULL, 0, NULL, NULL),
(31, 31, 'В останні хвилини земного життя', 0, 'Куплет 1\nВ останні хвилини земного життя\nСпаситель на гору зійшов.\nВознісся туди, де живе майбуття,\nДе вічно свята є любов.\n\nКуплет 2\n“Я вас не покину”- сказав Він в той час.\nІ нині радіємо ми,\nСпаситель дав Духа Святого для нас\nІ вірю, що будемо з Ним.\n\nПрипев\nБілі крила, білі крила, учні бачили тоді,\nНаче голуб Божа сила, Дух Святий - Дух доброти.\nБілі крила, білі крила, вірним всім дарує Спас.\nБілі крила, білі крила, в небеса піднімуть нас.\n\nКуплет 4\nНебесні оселі чекають давно\nІ місця там хватить для всіх.\nХай сіється всюди насіння зерно,\nЩоб був переможений гріх.\n\nКуплет 5\nВід світу гріховного, від марноти,\nДо сонця, до нових небес.\nДух Божий, утомлені душі веди\nМи просимо щиро Тебе.', '', '', 'ua', NULL, 0, NULL, NULL),
(32, 32, 'В Палестині народився', 0, 'Куплет 1\nВ Палестині народився \nЦар любов і життя\nБог на землю нам з\'явився, \nзасвітилася зоря.\nПастухи, що пасли стадо,\nпромінь сонця засіяв\nІ тоді в стаєнку йдучи \nкожен Бога прославив\n\nПриспів\nГори зоря, завжди гори\nІ світлом правди освіти\nВсіх хто блукає в темноті \nХай знайдуть щастя у Христі.\n\nКуплет 2\nМудреці на небосхилі \nЗірку нову віднайшли \nІ дари з собою взявши,\nПоклін дасть Христу пішли\nІ тепер вона сіяє\nВіфлеємська та зоря\nЛюдям всім вона звіщає\nПро спасіння, про Царя\n\nКуплет 3\nЗір багато в небі світить,\nТа яскріш за всіх одна\nТа що людям сповістила\nПро народження Царя\nІ коли печаль на серці\nТи поглянь на небеса\nДе палає вічним світлом\nВифлиємськая зоря.', '', '', 'ua', NULL, 3, '2021-01-17', NULL),
(33, 33, 'В цей чудовий день зимовий хочем ми вам побажать', 0, 'Куплет 1\nВ цей чудовий день зимовий, хочем ми вам побажать\nЩастя, радості, любові з Господом лиш крокувать\n\nПрипев\nНехай щастить вам навесні, улітку, взимку, восени\nХай допоможе вам в усім Спаситель наш.\n\nКуплет 2\nВ Слові завжди пробувайте, і кріпіться в вірі ви\nІ в молитві відчувайте дотик Божої руки.\n\nКуплет 3\nІ в домівках ваших буде милість і любов Христа\nХай живе завжди із вами невмираюча весна.', '', '', 'ua', NULL, 0, NULL, NULL),
(34, 34, 'В цьому світі Ти надія вся', 0, 'Куплет 1\nВ цьому світі я живу, \nТа коротке в ньому життя,\nТа надію маю вічно жить.\n\nПриспів\nТи - надія вся моя, Ти - моя весна,\nТи - надія в серці, Христе мій!\n\nКуплет 2\nЦя надія є наш Христос. \nВін пролив за нас свою кров,\nЧерез Нього маєм вічне життя.\n\nКуплет 3\nЦю надію буду нести,\nВ своєму серці аж до мети.\nІ дістану в небі вічне життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(35, 35, 'Велики и чудны дела Твои', 0, 'Куплет 1\nВелики и чудны дела Твои,\nГосподи Боже, Вседержитель.\nПраведны и истинны пути Твои,\nЦарь Святый.\n\nКуплет 2\nКто не убоится и не прославит Тебя,\nИбо Ты Един Свят, все народы поклонятся!\nПред Тобой, ибо Ты Един Свят!\nСвят! Свят! Ты Един Свят!', '', '', 'ua', NULL, 5, '2021-04-11', NULL),
(36, 36, 'Вже чекають мене небеса', 0, 'Куплет 1\nВже чекають мене небеса, вічна радість і вічна краса.\nБуде зустріч з Ісусом Христом, Святим Духом, Небесним Отцем\n\nПрипев\nІ вінець, ну, звичайно, вінець, \nЩо для мене призначив Отець _ 2р.\nАлілуя!\n\nКуплет 2\nМісто там неземної краси, всюди квіти у краплях роси,\nЛиця друзів і рідних моїх, мій Спаситель стоїть серед них.\n\nКуплет 3\nБуде зустріч з Іваном, Петром, і святих без числа цілий сонм.\nПідійдуть і обнімуть мене, радість вічна для всіх там буде.', '', '', 'ua', NULL, 0, NULL, NULL),
(37, 37, 'Винограднії плоди грона спілії', 0, 'Куплет 1\nВинограднії плоди, грона спілії\nПоклади Ісусу ти в руки білії\nВиноградная Лоза Він правдивая\nТи лиш гілочка одна незрадливая!\n\nКуплет 2\nКогда в Твои слова вникаю\nХристос Спаситель дивный мой\nТогда все глубже понимаю\nЧто без Тебя я прах земной\nТы есть лоза моя святая\nА я лишь веточка Твоя\nИ сок для жизни получаю\nЯ, мой Спаситель, от Тебя.\n\nКуплет 3\nТвой свет во мне все оживляет\nДает мне радость и покой\nДуша так близко ощущает\nТебя Господь, Спаситель мой.\nКогда случается порою\nНе пребываю я с Тобой\nТогда терзаюсь я душою\nНе находя ни в чем покой\n\nКуплет 4\nО, как Твои слова правдивы,\nЧто без Тебя ничтожны мы\nИ на дела у нас нет силы\nВ греховном мире суеты.\nИ потому мое желанье\nВ Тебе Христос мой пребывать,\nЧтоб в жизни все мои деянья\nТвоею силой совершать.\n\nКуплет 5\nХристос Ты жизнь и Путь для жизни\nДающий смысл для бытия\nЦеною жизни в дверь Отчизны\nОткрыл Ты грешникам как я\nТы есть Лоза моя святая\nА я лишь веточка Твоя\nИ сок для жизни получаю\nЯ, мой Спаситель, от Тебя.', '', '', 'ua', NULL, 0, NULL, NULL),
(38, 38, 'Відчуваєш що душа вже змучилась', 0, 'Куплет 1\nВідчуваєш, що душа вже змучилась, \nа життя тривожить і гнітить.                                           \nВсе минулось, щастя мить закінчилась\n і не знаєш ти як далі жить.\n\nПрипев\nПодивись хоч  раз ти на Голгофу,\nДе невинна пролилася кров.\nВ муках там за Тебе ллються сльози\nВ них горить батьківськая любов.\n\nКуплет 2\nСил так мало, щоб навік лишити гріх, \nа душа тривожить і гнітить.\nДо Ісуса поспішай, Він прийме всіх, \nперевяже рани, все простить\n\nПрипев\nПодивись хоч  раз ти на Голгофу,\nДе невинна пролилася кров.\nВ муках там за Тебе ллються сльози\nВ них горить батьківська любов.\n\nКуплет 3\nІ якщо і друзі і твоя сім´я залишили всі на самоті\nТи прошепочи Ісусове ім´я і простягне руки Він святі.', '', '', 'ua', NULL, 0, NULL, NULL),
(39, 39, 'Він воскрес щоб весь світ оживити', 0, 'Куплет 1\nВін воскрес, щоб весь світ оживити.\nВін воскрес, щоб ми з вами жили,\nЩоб покірні словам Його діти\nВ Ньому вічне життя досягли.\n\nКуплет 2\nВін воскрес, щоб гріховне коріння\nСпопелити в тобі назавжди,\nЩоб зросло у серцях те насіння,\nЩо приносить лиш добрі плоди.\n\nКуплет 3\nВоскресіння Христа – радість вічна, свята\nНа землі для людей і на небі.\nВоскресіння Христа – то спасіння людства,\nБог любові дарує для тебе.\n\nКуплет 4\nВін воскрес, щоб як поле пшеничне,\nБула вибрана Церква Його,\nВін воскрес, щоб життя дати вічне\nВ небесах для насліддя Свого.\n\nКуплет 5\nВін воскрес і вознісся на небо,\nЩоб нас всіх живить Духом Святим.\nВін зробив це для тебе і мене,\nТож подумаєм, друзі, над тим.', '', '', 'ua', NULL, 0, NULL, NULL),
(40, 40, 'Він так любить всіх нас що покинув небо', 0, 'Куплет 1\nВін так любить всіх нас, що покинув небо,\nІ прийшов у грішний світ цей, щоб людей спасти,\nІ щоб кожен грішник, яким не був би грішним,\nЗамість смерті життя вічне міг собі знайти.\n\nПрипев\nВін родився, щоби гріх твій на Себе прийнять,\nБув розп`ятий на Голгофі, за тебе вмирав.\nІ тобі Він дав всю славу і любов Свою,\nНазавжди вернув в Країну неземну.\n\nКуплет 2\nО, невже ж сьогодні ти Христа не приймеш?\nЧом не можеш зрозуміти ту святу любов?\nО, невже даремно на хресті вмирав Він?\nПроливав за тебе там Свою невинну кров.\n\nКуплет 3\nВін так любить всіх нас, що покинув небо,\nІ прийшов у грішний світ цей, щоб людей спасти,\nТож прийди сьогодні на поклик Господній!\nВідчини сердечні двері і Христа впусти.', '', '', 'ua', NULL, 0, NULL, NULL),
(41, 41, 'Він так любить всіх нас що покинув небо', 0, 'Куплет 1\nВін так любить всіх нас, що покинув небо,\nІ прийшов у грішний світ цей, щоб людей спасти,\nІ щоб кожен грішник, яким не був би грішним,\nЗамість смерті життя вічне міг собі знайти.\n\nПрипев\nВін родився щоби гріх твій на Себе прийнять,\nБув розп`ятий на Голгофі, за тебе вмирав.\nІ тобі Він дав всю славу і любов Свою,\nНазавжди вернув в Країну неземну.\n\nКуплет 2\nО, невже ж сьогодні ти Христа не приймеш?\nЧом не можеш зрозуіти ту святу любов?\nО, невже даремно на христі вмирав Він?\nПроливав за тебе там Свою невину кров.\n\nКуплет 3\nВін так любить всіх нас, що покинув небо,\nІ прийшов у грішний світ цей, щоб людей спасти,\nТож прийди сьогодні на поклик Господній!\nВідчини сердечні двері і Христа впусти.', '', '', 'ua', NULL, 0, NULL, NULL),
(42, 42, 'Возвысьте голос в пении и слейтесь во хвале', 0, 'Куплет 1\nВозвысьте голос в пении и слейтесь во хвале:\nНаш Бог - Всемогущий Бог.\nЧтоб вторил хор небесный, восторг был на земле: \nНаш Бог - Всемогущий Бог.\nХвалите, пламенея, Того, Кто жизнь дарит,\nПусть песней юбилея Евангелие звучит,\nИ расскажите миру о том, каков наш Бог:\nНаш Бог - Всемогущий Бог.\n\nПрипев\nНаш Бог Всемогущий царствует\nНа небе во славе.\nМудрый, сильньій, любящий \nВсемогущий Бог.\n\nКуплет 2\nНастанет, братья, славный финал в борьбе земной:\nНаш Бог - Всемогущий Бог.\nПобеду Вождь державный свершит над силой злой:\nНаш Бог - Всемогущий Бог.\nНаш дух надеждой силен, а Вождь наш - Сын Творца,\nИ наш трофей обилен - спасенные сердца.\nМы возвещаем миру о том, каков наш Бог:\nНаш Бог - Всемогущий Бог.', '', '', 'ua', NULL, 2, '2020-12-28', NULL),
(43, 43, 'Возношу мои руки к небу прославляя Творца Вселенной', 0, 'Куплет 1\nВозношу мои руки к небу, прославляя Творца Вселенной,\nПусть прольется в небеса прославленье из сердца моего.\nЯ не хочу быть таким как прежде, но в Твою славу хочу меняться\nВ Твоей любви я хочу купаться, Твоими путями ходить.\nЯ говорю Иисус Твоя любовь во мне, я говорю Иисус Ты нужен мне.\n\nКуплет 2\nВ Тебе одном я нахожу покой, хочу я слышать нежный голос Твой\nИисус, о Иисус будь со мной.', '', '', 'ua', NULL, 0, NULL, NULL),
(44, 44, 'Вся земля так довго на цей день чекала', 0, 'Куплет 1\nВся земля так довго на цей день чекала\nКоли лине з неба, теплий, чистий дощ.\nКоли сонце правди, розжене всі хмари\nКоли пісню щастя, заспіває хтось\nІ цей день нарешті, до нас увірвався\nВін приніс нам віру в світле майбуття\nЧерез свого Сина, Всемогутній Батько\nНам дарує ріки, Вічного Життя.\n\nКуплет 2\nІсусу слава, Ісусу слава\nЛунає пісня над схилами Дніпра.\nІсусу слава, Ісусу слава\nСпіває вільна Україна.\n\nКуплет 3\nОсь і ми сьогодні у цей день святковий\nПрославляєм в піснях вічного Христа\nВін зійшов із неба, щоб любов нам дати\nІ тепер Він з нами, кличе в небеса.\nГолос Його ніжно, ще тепер лунає\nІсус бажає щастя всім й добра\nДруже не вагайся до нас приєднайся\nВідкриваймо серця, двері в небеса.\n\nКуплет 4\nІсусу слава, Він наш Спаситель\nВоскрес із мертвих, і смерть Він подолав.\nСвоєю кровю гріхи омив нам\nХристос Воскрес і радість вічну дав!!!', '', '', 'ua', NULL, 1, '2020-06-19', NULL),
(45, 45, 'Глянь в небеса там хвалу співають', 0, 'Куплет 1\nГлянь в небеса, там хвалу співають,\nАнгели славлять Різдво Христа\nМир і любов людям сповіщають,\nРадість всім серцям!\nДивна новина Христос родився,\nЯсла і хлів ради нас обрав.\nВ тілі сам Бог до людей з´явився\nЩоб я радість мав!\n\nПрипев\nЗемле, радій! Радійте люди!\nЗ неба зійшов, Спаситель сам\nСлава Христу, завжди хай буде!\nНа землі і в небесах!\n\nКуплет 2\nВістку чудову усі приймають\nЧерез Христа Бог любов явив.\nДвері спасіння Своїм стражданням\nБожий Син відкрив!\nЯсна зоря світові засяла \nВсі заспіваймо Рожденному!\nМир на землі, Богу в небі слава\nЧесть, хвала Христу!', '', '', 'ua', NULL, 7, '2021-01-06', NULL),
(46, 46, 'Господи на небосклоне тучи Господи', 0, 'Куплет 1\nГосподи, на небосклоне тучи Господи,\nСплошной стеной осенние дожди\nСтучась в окно ко мне пришли.\nГосподи, исчезли солнца добрые лучи\nНа сердце каменной тоской легли,\nКуда идти, и как идти.\n\nПрипев\nГосподи, я знаю Ты не человек\nГосподи, не изменяющийся в век\nГосподи, я говорю душе в ответ: «Будет свет»!\nЕще увижу небо я, без туч осенних и дождя\nНе унывай душа моя, Бог твой скала!\n\nКуплет 2\nГосподи, чрез бури все и испытания\nЗа все грехи чрез раскаяние\nИду к Тебе, иду к Тебе.\nГосподи, звучат в набат с креста Твои слова:\n« Не за здоровых умираю я»!\nБольным нужна любовь Твоя.\n\nКуплет 3\nГосподи, и пусть бушует море бьет волной\nБезумный ветер гонит их стеной\nНо я с Тобой, ведь я с Тобой\nГосподи, вдали я вижу светоч маяка\nЯ знаю ето есть любовь Твоя \nПлыви ладья, моя ладья.', '', '', 'ua', NULL, 0, NULL, NULL),
(47, 47, 'Господи який чудовий Ти', 0, 'Куплет 1\nГосподи, який чудовий Ти,\nГосподи, який чудовий Ти.\n\nКуплет 2\nТебе одного люблю і лиш Тобі життя я віддаю,\nІсусе, який прекрасний Ти (-2р.)\n\nКуплет 3\nГосподи, який чудовий Ти,\nГосподи, який чудовий Ти.\n\nКуплет 4\nНебеса Твоя оселя, і Тобі весь Всесвіт віддає хвалу.\nТи є Святий, Бог неба і землі. (-2р.)\n\nКуплет 5\nГосподи, який чудовий Ти,\nГосподи, який чудовий Ти.\n\nКуплет 6\nБог чудес, Володар неба, все творіння поклоняється Тобі,\nІсусе, який прекрасний Ти. (-2р.)', '', '', 'ua', NULL, 3, '2020-08-02', NULL),
(48, 48, 'Господь – моя сила и щит', 0, 'Куплет  1\nГосподь – моя сила и щит! (2р.)\nГосподь – упованье мое и помощь мне.\n\nПриспів\nИ потому я ликую и сердце мое ликует,\nИ песнь моя славит Господа (Господа)!\n\nКуплет 2\nИисус – моя радость и мир!\nИисус – искупленье мое жизнь моя.', '', '', 'ua', NULL, 1, '2021-04-01', NULL),
(49, 49, 'Господь я славлю Тебе за все що Ти зробив', 0, 'Куплет 1\nГосподь, я славлю Тебе за все, що Ти зробив.\nЯ дякую за Твій хрест,  за кров, що Ти пролив!\nЯ за Тобою піду, куди б Ти не вказав мені.\nЯ славлю Тебе, і лиш Тебе люблю !\n\nПриспів\nХай Твій вогонь все спалить, що для Тебе зайве, \nХай Дух Святий дощем проллє в життя моє!\nЯ славлю Тебе, Тобі життя я довіряю, \nО, мій Господь Ісус!\n\nКуплет 2\nІ буду славить  Тебе всім серцем я своїм\nЗвіщати про діла рук Твоїх на цій землі,\nГоворить серце моє до Тебе в тишині:\nГосподь, я славлю Тебе, і лиш Тебе люблю!\n\nКуплет 3\nГосподь, Ти - скеля моя,спасіння Ти для нас,\nПрийшов до нас Ти з небес, любов´ю осіяв,\nЯ за Тобою піду, куди б Ти не вказав мені,\nЯ славлю Тебе, і лиш Тебе люблю!', '', '', 'ua', NULL, 5, '2021-03-26', NULL),
(50, 50, 'Граждане неба небо для вас', 0, 'Приспів\nГраждане неба, небо для вас,\nИ где бы ты ни был, вспомни сейчас.\n\nКуплет 1\nТого, Кто кровь Свою пролил,\nЗа грех земной унижен был,\nТого, Кто жизнь Свою отдал,\nЧтоб каждый напевал:\n\nКуплет 2\nЧто смертью смерть Он победил,\nКлючи от неба подарил,\nЛюбовь Он в сердце поселил\nИ души воскресил!', '', '', 'ua', NULL, 1, '2020-11-16', NULL),
(51, 51, 'Да это тайна для меня', 0, 'Куплет 1\nДа, это тайна для меня\nКак вечный Божий Сын младенцем стал\nЧто этот кроха может изменить?\nЛикуют небеса, Там знают Он свершит!\n\nПрипев\nАллилуйя! Аллилуйя!\nЛюбовь Отца с небес сошла, чтоб мир спасти!\nАллилуйя! Аллилуйя! \nБожий Сын стал слугой, чтоб с нами быть.\nЗдесь с нами быть…\n\nКуплет 2\nДа, это тайна для меня\nОн видел все века, Он знает все сердца\nЭму подвластно все, земля и небеса\nА Он младенцем стал у мамы на руках.\n\nКуплет 3\nИисус Христос рожден для всех людей\nМладенец знает, как помочь твоей душе!!!', '', '', 'ua', NULL, 2, '2020-12-18', NULL),
(52, 52, 'Давайте взір свій в небо піднесем', 0, 'Куплет 1\nДавайте взір свій в небо піднесем, залишимо свої земні турботи\nІ Богові подяку щиру принесем, за кров пролиту Сином на Голгофі.\nПідіймем свої руки до небес, і голос свій до Божого престолу\nТому, Хто вмер за нас, але на третій день Воскрес!\nХвалу віддаймо Богові Живому!\n\nКуплет 2\nАлілуя, Тобі навіки слава, \nТи могутній , сильний, Ти святий!\nАлілуя, Бог істинний і правий, \nТи незмінний, добрий, Ти Живий!\nАлілуя, Господь наш Бог єдиний, \nТи премудрий Всесвіту Творець,\nАлілуя, возносим Твоє ім´я -\nДух Святий, Бог Син і Бог Отець!', '', '', 'ua', NULL, 2, '2020-12-06', NULL),
(53, 53, 'Две руки пред Богом ныне съединились навсегда', 43, 'Куплет 1\nДве руки пред Богом ныне съединились навсегда,\nДля пути в земной долине, для совместного труда.\nДля поддержки обоюдной в начинаниях благих.\nРуку милостей, о Чудный, возложи теперь на них.-2р.\n\nКуплет 2\nДвое уст теперь сказали пред Отцом святое “Да”\nОбещанье Богу дали на всю жизнь и навсегда.\nЧтобы с каждым днем дороже и светлее был обет-\nПусть Твои уста, о Боже, “Да” скрепят на много лет.-2р.', '', '', 'ru', NULL, 0, NULL, NULL),
(54, 54, 'Две тысячи лет почти', 30, 'Куплет 1\nДве тысячи лет почти, как на землю Мессия Иисус приходил\nПриход Его ждали святые пророки. Исаия о Нем говорил.\nОт девы Марии рожден в Вифлееме, Спаситель Всевышнего Сын\nОн ночью и днем стучал в твои двери, Иерусалим.\n\nКуплет 2\nИерусалим, ты надежда моя, Я снова забрать хочу тебя,\nКак птица птенцов под крылья Мои, от края до края земли\nЯ северу скажу: \"А ну-ка отдай!\", югу прикажу: \" Не удерживай\"!\nОтдай сыновей, дочерей моих, отдай их в объятья Мои.\n\nКуплет 3\nСтряхни з себя рабские путы, лохмотья, и с плена ко Мне приходи\nЯ цепи твои разорву, и проклятья омою в Моей крови\nА вместо пепла унылого духа, виссон тебе радости дам\nВернись же в объятья любимого Друга Невеста Царя\n\nКуплет 4\nИерусалим город Вечного Царя, Иерусалим на востоке звезда\nИерусалим утро нового дня, любовь и надежда моя\nЗабудет ли мать грудное дитя, но если бы даже забыла она\nЛюбовью Вечной люблю Я тебя, и не забуду никогда тебя\n\nКуплет 5\nРожденный от Бога, сходящий от неба Новый Иерусалим\nОн будет, как невеста для милого мужа украшенный Богом самим\nСвети над землею, ночною порою, святой Мой Иерусалим\nМой свет над тобою, хоть тьма над землею, Иерусалим\n\nКуплет 6\nГрядущий твой Царь на облаках, грядущий Мессия Израиля\nИерусалим невеста Царя, себя приготовила\nЦарю Царей украшена она, Царю Царей она обручена\nЦарю Царей навечно отдана, любимая Невеста Царя\n\nКуплет 7\nЛикует небо и Новая Земля, идет на землю вечная весна\nВ саду смоковница расцвела, Невеста приготовила себя\nЦарю Царей украшена она, Царю Царей она обручена\nЦарю Царей навечно отдана, любимая Невеста Царя!!!', '', '', 'ua', NULL, 4, '2021-02-28', NULL),
(55, 55, 'Дві руки з’єднались нині перед Господом Святим', 43, 'Куплет 1\nДві руки з’єднались нині перед Господом Святим,\nЩоб у цій земній країні разом в радості іти.\nДві руки зеднались міцно для життя й надій живих\nТвою руку Боже вічний поклади тепер на них.\n\nКуплет 2\nДвоє уст тепер сказали перед Богом «Так» святе,\nЖити вірно обіцяли на усе життя своє\nБоже наш, Тебе благаєм дай їм світла у житті.\nІ для щастя хай з´єднає  їх свята рука Твоя.', '', '', 'ua', NULL, 0, NULL, NULL),
(56, 56, 'Для тебя о человек Бог создал небо и поля', 0, 'Куплет 1\nДля тебя, о человек, Бог создал небо и поля.\nДля тебя цветут: сады и плод дает земля.\nДля тебя моря и горы, все живое, для тебя\nДля тебя все это создала Его рука.\n\nПрипев\nЧто отдал ты Ему за эту красоту?\nЧто отдал ты, Творцу, за эти чудеса?\nПодумай, человек, ведь твой недолгий век.\nОтдай Ему себя, отдай Христу себя.\n\nКуплет 2\nДля тебя звучит мелодия в небесной вышине\nДля тебя роса на травах, на заре.\nДля тебя на небе звезды и луна,\nДля тебя все это создала Его рука.', '', '', 'ua', NULL, 0, NULL, NULL),
(57, 57, 'Дух Святой Ты Тот в ком я нуждаюсь', 0, 'Куплет 1\nДух Святой , Ты Тот, в ком я нуждаюсь.\nДух Святой, Ты Тот, кем я дышу.\nДух Святой, меня Ты наполняешь \nИ Тобою я живу.\n\nПриспів\nДух Святой, небесный голубь,\nДух Святой, огонь и ветер,\nДух Святой, Ты так мне дорог,\nТы дороже всех на свете.\n\nКуплет 2\nДух Святой, Ты Дух усыновленья,\nДух Святой, Ты радуешь сердца,\nДух Святой, даешь Ты вдохновенье \nИ любовь от Отца.\n\nКуплет 3\nСлава Богу Слава \nСлава і Хвала!(2р.)', '', '', 'ua', NULL, 8, '2021-03-12', NULL),
(58, 58, 'Дух Святой прикоснись ко мне Своим теплом', 0, 'Куплет 1\nДух Святой, прикоснись ко мне Своим теплом,\nДух Святой, освети мой разум Своим лучом,\nНаполняй мое сердце Божьей добротой,\nДай напиться мне Твоей воды живой.\n\nКуплет 2\nАллилуйя, аллилуйя, аллилуйя, аллилуйя! (2р. )\n\nКуплет 3\nСлава, слава Тебе, мой Бог, за Дух Святой, (3р.)\nСлава Тебе, слава Тебе, мой Бог.', '', '', 'ua', NULL, 4, '2021-03-17', NULL),
(59, 59, 'Если ждет тебя дорога в неизвестный край', 0, 'Куплет 1\nЕсли ждет тебя дорога в неизвестный край,\nНа прощанье у порога думу не гадай.\nСлово доброе послушай и совет прими,\nВ этом мире гибнут души, ты свою храни,\nТы свою - храни.\n\nКуплет 2\nЕсли ждет тебя дорога в неизвестный край,\nСпутником себе тревогу ты не выбирай.\nВ жизни с ней одна забота и тоска в груди,\nВ звездном небе, будто кто-то потушил огни,\nПотушил огни.\n\nКуплет 3\nЕсли ждет тебя дорога в неизвестный край,\nНе суди упавших строго, лучше подымай,\nМожет стать и сам в бессилье, где-то упадешь,\nОслабеют сердца крылья, веру надорвешь,\nВеру надорвешь.\n\nКуплет 4\nЖизнь кипит вокруг, как море, бьет тебя волной\nИ в твоем огромном горе ты для всех чужой.\nПомощь есть для всех у Бога, ты к нему взывай,\nЕсли ждет тебя дорога в неизвестный край,\nВ неизвестный край.', '', '', 'ua', NULL, 0, NULL, NULL),
(60, 60, 'Если мой народ смирится пред Мной', 0, 'Куплет  1\nЕсли мой народ смирится пред Мной,\nМолитвы вознесет, если взыщет   лица Моего,\nОставив путь свой злой,-\nЯ услышу с неба и прощу их грех,\nИсцелю их землю, утешу  всех.\n\nПриспів\nО, исцели нашу землю!\nО, Господь, народ наш обрати к Себе!\nО, исцели! Отче, услышь нас, исцели!\nПрости наш грех и мир Свой нам верни!\n\nКуплет 2\nПеред Тобой, Господь, смиряемся мы,\nМолимся день и ночь. Ищем искренно лица Твоего,\nВсе злое отвернув прочь.\nТы услышь нас с неба и прости наш грех,\nИсцели нам землю, утешь нас всех!', '', '', 'ua', NULL, 0, NULL, NULL),
(61, 61, 'Євангеліє Тоді бери цю книгу в руки', 0, 'Припев\nЄвангеліє. Тоді бери цю книгу в руки.\nЄвангеліє. В словах діяльних та живих.\nЄвангеліє. Знайдеш розраду від розпуки.\nЄвангеліє. Спасіння ти знайдеш у них.\n\nКуплет 1\nКоли надія в тобі згасне, або охопить суєта, \nКоли прийдуть випробування, і за бідою йде біда.\n\nКуплет 2\nВ ці книзі голос відізветься, і заговорить Дух Святий,\nВін над тобою пронесеться: страждай, терпи, люби, живи!\n\nКуплет 3\nТой голос ніжний і ласкавий на душу діє як бальзам.\nСкоріш відкрий для Нього серце, Ісус знайде оселю там.', '', '', 'ua', NULL, 2, '2020-08-23', NULL),
(62, 62, 'Жениху и невесте жить в любви', 0, 'Куплет 1\nЖениху и невесте жить в любви, только вместе\nНе грустить и не плакать никогда.\nНа Исуса взирая и Его прославляя\nПроводить жизни радостно года.\n\nКуплет 2\nЕсли даст Бог вам деток - вы любите их крепко,\nДаже можно чу-чуть их наказать.\nЕсли вдруг непослушны, но учить все же нужно\nИ пример вы должны им показать.\n\nКуплет 3\nБудьте людям примером и в молитве, и в вере,\nСлово Божье читайте каждый день.\nБогу вы доверяйте и Его прославляйте\nИ печали исчезнут словно тень.', '', '', 'ua', NULL, 0, NULL, NULL),
(63, 63, 'Живий живий живий Він назавжди', 0, 'Куплет 1\nЖивий, живий, живий Він назавжди!\nІсус мій є живий, живий Він назавжди!\nЖивий, живий, живий Він назавжди.\nІсус мій є живий!\n\nКуплет 2\nО, алілуя, о, алілуя!\nІсус мій є живий, живий Він назавжди!\nО, алілуя, о, алілуя! Ісус мій є живий!', '', '', 'ua', NULL, 1, '2021-04-04', NULL),
(64, 64, 'За все Тебя Господь я благодарю', 0, 'Куплет 1\nЗа все Тебя Господь я благодарю\nТы искупил от смерти душу мою\nИ буду возвещать я по всей земле\nО том как милостив и благ Ты ко мне.\n\nПрипев\nВся слава Тебе, мой Иисус спасенье дал мне, мой Иисус\nИ сердце во мне, мой Иисус, поет о Тебе всегда, Иисус.\n\nКуплет 2\nС креста стекала кровь святая Твоя\nГрехи смывая, очищала меня.\nОдежду правды мне Иисус подарил,\nПростил, очистил и меня искупил.\n\nКуплет 3\nЯ посвящаю жызнь свою лишь Тебе\nИ благодать Твоя сегодня на мне\nПусть знает каждый слыша из моих уст\nО том, что жыв Господь, Спаситель Иисус!', '', '', 'ua', NULL, 0, NULL, NULL),
(65, 65, 'За Голгофу за кровь Благодарю Тебя Иисус', 0, 'Куплет 1\nЗа Голгофу, за кровь, я Тебя благодарю.\nЗа воскресенье Твое, за победу Твою.\n\nПриспів:\nБлагодарю Тебя Иисус!\nПросто я благодарю!!!\n\nКуплет 1\nЗа Голгофу, за кровь, я Тебя благодарю.\nЗа искупленье мое, за прощенье грехов.', '', '', 'ua', NULL, 3, '2021-04-02', NULL),
(66, 66, 'Заспіваймо пісню разом всі', 0, 'Куплет 1\nЗаспіваймо пісню разом всі, хай вона злетить в небесну даль\nХай Господь прийде сльози утре, забере всю журбу і печаль\n\nКуплет 2\nХай співає небо і земля, і весь світ,  Алілуя\nХристос з мертвих встав, смерть подолав, і нам дав нове життя\n\nКуплет 3\nЗаспіваймо пісню разом всі, хвалу Богу вознесім\nНе шукайте дарма, в світі цьому нема, бо життя і щастя лиш у Нім!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(67, 67, 'Знову серцем ми на Голгофі', 0, 'Куплет 1\nЗнову серцем ми на Голгофі\nЧорний хрест серед інших двох\nО, Ісус, у вінку терновім\nТи - Людина, Ти – Цар ,Ти – Бог.\n\nПрипев\nТи зайняв наше місце, Спасе\nЩоби жили повіки ми\nТи воскрес, щоб у небі разом\nМи співали пісні хвали.\n\nКуплет 2\nЗнову серцем ми коло гробу\nВін пустий, там нема Христа.\nО, Ісус, ми воскресли в Тобі \nІ душа вже моя жива.\n\nКуплет 3\nЗнову серцем ми в Царстві Божім\nТільки там ми спокій знайшли.\nО, Ісус, Тебе щиро просимо\nСили дай, щоб вперед ми йшли.', '', '', 'ua', NULL, 0, NULL, NULL),
(68, 68, 'Из глубин души моей льется песня о Тебе', 0, 'Куплет 1\nИз глубин души моей льется песня о Тебе,\nТы Господь кто всех милей в судьбе моей.\nВек проходит, время мчится в сердце Божья благодать,\nНу а песню словно птицу невозможно удержать.\n\nПриспів\nТы с нами Бог, Ты с нами Бог.\nСлавим Имя Христа, нашей веры исток.\nТы с нами Бог, Ты с нами Бог \nПусть же в сердце наша вера, \nПрорастёт как колосок.\nТы с нами Бог!\n\nКуплет 2\nВоздух песнею наполнен, отовсюду голоса,\nПусть ее нам подпоют поля, леса,\nЭто песня о спасенье, о любви на всей земле.\nО великом искупленье, о тебе и обо мне.\n\nКуплет 3\nВ нашем сердце Бог и в песне, и в росинке, и в слезе,\nВ счастье, в горе, с нами вместе, в солнце и в грозе. \nПойте реки, пойте горы, и равнины и моря\nИмя Господа и веру снова прославляю я.', '', '', 'ua', NULL, 6, '2021-03-14', NULL),
(69, 70, 'Иисус как Ты дорог для меня', 0, 'Куплет 1\nИисус, как Ты дорог для меня,\nИисус, внемлешь Ты мольбе моей.\nО, Иисус, поднимешь Ты, коль упаду,\nКак Ты дорог, дорог для меня.\n\nКуплет 2\nИисус, Тебя люблю я восхвалять,\nИисус, Ты без начала, без конца.\nО, Иисус, Ты умер и простил мой грех,\nКак Ты дорог, дорог для меня.\n\nКуплет 3\nИисус, Ты обещал прийти сюда,\nИисус, мы ждем Тебя открыв сердца.\nО, Иисус, услышь Ты наши голоса,\nКак Ты дорог, дорог для меня.', '', '', 'ua', NULL, 0, NULL, NULL),
(70, 71, 'Иисус Ты мой хлеб', 0, 'Куплет 1\nИисус, Ты - мой хлеб, Иисус, Ты - мое вино,\nИисус, Ты - мой покой, моя радость и сила моя.\n\nКуплет 2\nИисус, Ты - мой путь, Иисус, Ты - мой свет,\nИисус, Ты - мой Господь, моя жизнь и надежда моя.', '', '', 'ua', NULL, 0, NULL, NULL),
(71, 72, 'Із ран Спасителя текла струмком пречиста кров', 0, 'Куплет 1\nІз ран Спасителя текла, струмком пречиста кров,\nІ грішним всім вона несла спасіння і любов.\nКоли розбійник на хресті розп´ятий умирав,\nТо від Христа в крові святій свободу одержав.\n\nПрипев\nБез Господа і я блукав і гинув в марноті\nМені Христос спасіння дав в Своїй крові святій (2р).\n\nКуплет 2\nСтрумок предивний я знайшов, і з ним святу Любов\nТо кров Спасителя мого стікала на землю знов,\nВона омиє і тебе, відродить до Життя\nІ ти з Христом в краю небес одержиш майбуття!', '', '', 'ua', NULL, 0, NULL, NULL),
(72, 73, 'Ісус Спаситель світу Як легко з Богом житть', 0, 'Куплет 1\nІсус - Спаситель світу, \nСлава Тобі навіки!\nСлава завжди хай ллється\nЗ наших сердець Тобі!\n\nПриспів\nЯк легко з Богом жить, \nЛиш Йому служить\nВ цьому світі марноти і зла. \nВсім людям розкажу\n Про любов Твою\nІ про всі Твої діла!\n\nКуплет 2\nХочем з Тобою жити\nІ лиш Тобі служити,\nСлаву Тобі складати\n За ласку і любов.', '', '', 'ua', NULL, 0, NULL, NULL),
(73, 74, 'Как земля без дождя в знойное лето', 0, 'Куплет 1\nКак земля без дождя в знойное лето,\nКак весна без цветов и рассвет без росы,\nБез Тебя мой Господь нету жизни и света.\nЯ нуждаюсь в Тебе, о Иисус, приходи.\n\nПрипев\nЯ жду Тебя, рассвет предваряя.\nЯ жду Тебя, склоняясь в тиши,\nЯ жду Тебя, всем сердцем взывая,\nЯ жду Тебя, - о Иисус, приходи.\n\nКуплет 2\nНа кресте Ты страдал, кровь свою проливая,\nЧтоб омыть и простить все людские грехи.\nТак приди же к Христу, Он тебя призывает,\nВ Нем спасение найдешь и прощенье грехов.', '', '', 'ua', NULL, 0, NULL, NULL),
(74, 75, 'Как прекрасно все то', 0, 'Куплет 1\nКак прекрасно все то, что Твое, мне повсюду Твой слышится голос:\nВетром в листьях звенит и поет, в сердце шепчет, как зреющий колос.\nЭти горы, покрытые мхом, эти волны покрытые пеной,\nЭтот берег с горячим песком, это солнце в бескрайной Вселенной.\n\nПрипев\nБоже мой, это – Ты, это – Ты!\nЯ с Тобою повсюду встречаюсь:\nКогда рву мимоходом цветы\nИль на чей-то поклон отвечаю.\n\nКуплет 2\nМне повсюду видна Твоя кисть, Твой резец и Твой почерк с размахом:\nВ детском взоре, что светел и чист, и в цветущих на поле ромашках.\nЭто Ты нам даруешь друзей, это Ты научил нас трудится,\nПотому я хочу все сильней и все чаще, усердней молится.\n\nКуплет 3\nЭто Ты меня петь научил, потому моя песнь не смолкает.\nЭто Ты в меня свет свой пролил, он и в вечности не угасает.\nКак прекрасно все то, что Твое, пред величьем Твоим я немею.\nЭто Ты нам, Спаситель, даешь, все то доброе что я имею.', '', '', 'ua', NULL, 2, '2021-03-21', NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(75, 76, 'Когда мне тоскливо я слышу крик чайки', 0, 'Куплет 1\nКогда мне тоскливо - я слышу крик чайки /\nГлаза поднимаю вверх. /2р.\nЯ знаю, что скоро придет мой Спаситель, /\nВозьмет Он меня к себе. /2р.\n\nПрипев\nЧайка, чайка, кричи, кричи,\nМеня глаза вверх поднять зови,\nЧтоб мы смотрели чаще в небеса,\nЧтоб в них мы видели Христа.\n\nКуплет 2\nКогда я обижен - я слышу крик чайки, /\nГлаза поднимаю вверх. /2р.\nЯ знаю, что скоро придет мой Спаситель,/ \nВозьмет Он меня к Себе. /2р\n\nКуплет 3\nКогда одинок я - я слышу крик чайки, /\nГлаза поднимаю вверх. /2р.\nЯ знаю, что скоро придет мой Спаситель/\nВозьмет Он меня к себе/2р.', '', '', 'ua', NULL, 0, NULL, NULL),
(76, 77, 'Коли Дух Господній наповняє мене', 0, 'Куплет 1\nКоли Дух Господній наповняє мене, співаю як Давид\nСпіваю, співаю, співаю як Давид.\nSi el Espiritu de Dios esta en mi corazón, yo canto como David\nYo canto, yo canto, yo canto como David.\n\nКуплет 2\nКоли Дух Господній наповняє мене, молюся як Давид\nМолюся, молюся, молюся як Давид.\nSi el Espiritu de Dios esta en mi corazón, yo oro como David\nYo oro, yo oro, yo oro como David.\n\nКуплет 3\nКоли Дух Господній наповняє мене я плачу як Давид\nЯ плачу, я плачу, я плачу як Давид.\nSi el Espiritu de Dios esta en mi corazón yo lloro como David\nYo lloro, yo lloro, yo lloro como David.\n\nКуплет 4\nКоли Дух Господній наповняє мене, співаю як Давид\nКоли Дух Господній наповняє мене, молюся як Давид\nСпіваю, молюся і плачу як Давид.\nSi el Espiritu de Dios esta en mi corazón yo canto como David\nSi el Espiritu de Dios esta en mi corazón yo oro como David\nYo canto, yo oro, yo lloro como David.', '', '', 'ua', NULL, 1, '2021-03-19', NULL),
(77, 78, 'Колись як я молився то мені Господь послав', 0, 'Куплет 1\nКолись, як я молився, то мені  Господь послав,-\nЩедро в серце моє Свого Духа Святого зілляв.\nІ з цієї же хвилини відійшли мої сумніви\nІ тепер я є щасливий, радісний назавжди вже.\n\nПриспів\nО любов, любов, любов  з’явилась  для людей.\nСпасти мене прийшов Ісус Спаситель мій.\nУ любві Себе віддав, за нас Він постраждав.\nІ через ту любов тоді хрестив Духом мене.\n\nКуплет 2\nНіколи не лишаймо глибини любві знайти,\nЩоб гріх світа покинуть і за Господом все йти.\nУповаймо і молімося та пильнуймо ми завжди,\nІ тоді усі побачим, як Духа Святого зіллє.', '', '', 'ua', NULL, 0, NULL, NULL),
(78, 79, 'Кругом тут на землі питають люди всі', 0, 'Куплет 1\nКругом тут на землі питають люди всі:\nЯк можна в Бога вірити коли не бачиш ти?\nЧи дійсно є Господь, чому печаль тоді?\nЯкби поглянуть міг хоч навіть іздалік,\nТоді повірив би…\n\nПрипев\nСвою любов Господь на небі написав,\nУ всесвіті зірками підписав.\nІ славу для людей Він показав\nІ життя вічне нам дарував,\nІ тому як не віддатися Йому - \nВсевишньому Спасителю Христу,\nЯк створіння поклоняюся Йому\nЗа ним піду.\n\nКуплет 2\nПоглянь кругом себе, на землю, зорі все,\nЧи випадково це з’явилось без Творця руки?\nВелике чи мале - накреслив Бог усе,\nА що сказав Він про життя твоє, що в грудях б’є,\nТоді початок де?', '', '', 'ua', NULL, 0, NULL, NULL),
(79, 80, 'Любимый Иисус как Ты прекрасен', 0, 'Куплет 1\nЛюбимый Иисус как Ты прекрасен\nЛюбимый Господь нет Тебя мне милей\n\nКуплет 2\nНа земле и на небе нет Тебя прекрасней \nНа земле и на небе нет Тебя милей … любимый Иисус.', '', '', 'ua', NULL, 0, NULL, NULL),
(80, 81, 'Мама прекрасное слово ближе всех для меня', 0, 'Куплет 1\nМама - прекрасное слово, ближе всех для меня.\nМамино сердце за мною следует всюду, в любые края.\nМамин голос я слышу, нежно меня зовет\nИ под родною крышей, молитву Исусу шлет.\n\nПрипев\nМама - милая мама, близкий, родной человек.\nМама, добрая мама, ты со мной останься на век.\nЗа меня ты молилась и в молитве своей \nСколько ты провела бессонных ночей.\n\nКуплет 2\nМамины теплые руки нежно обнимут, прижмут,\nСердце от счастья забьется, а в сердце - покой и уют.\nМама любить ты умеешь и за любовь твою\nЗа доброту и терпенье Бога благодарю.', '', '', 'ua', NULL, 0, NULL, NULL),
(81, 83, 'Между небом и землею крест стоит', 0, 'Куплет 1\nМежду небом и землею крест стоит, \nА на нем смиренно Божий Сын висит.\nМежду небом и землею роспъяли Христа,\nМежду небом и землею кровь Его текла.\n\nКуплет 2\nМежду небом и землею крест стоит,\nА на нем смиренно Божий Сын висит.\nСо креста Спаситель мира тихо говорит тебе:\n“О, остановись Прохожий, слышишь,этот зов к тебе!”\n\nКуплет 3\nМежду небом и землею крест стоит,\nА на нем смиренно Божий Сын висит.\nМежду небом и землею роспъяли Христа,\nМежду небом и землею жизнь Христом тебе дана!', '', '', 'ua', NULL, 0, NULL, NULL),
(82, 84, 'Ми в Господні брами Він дарує радість', 0, 'Куплет 1\nМи в Господні брами входим, славословлячи,\nІ подвір’ями Його з хвалою йдем.\nДля народу Він Свого подарував цей день, -\nЗаспіваймо вдячних, радісних пісень.\n\nПриспів\nВін дарує радість, Ісус дарує радість -\nІ радіють в Господі серця. \nВін дарує радість, Ісус дарує радість,\nТож хай славлять Господа Христа.\n\nКуплет 2\nУ житті земному будем Господу служить\nІ пісні хвали співати кожну мить.\nВеличати Його вічне і святе ім’я,\nАлілуя - хай полине до Творця.\n\nКуплет 4\nЯкщо, друже, ти у житті ще не пізнав Христа,\nПоспіши у Його обійми у цей час.\nХай хвала із уст твоїх полиється в небеса,\nХай пізнають всі що ти - Його дитя.', '', '', 'ua', NULL, 4, '2020-10-21', NULL),
(83, 85, 'Милости Твоей полна вся земля', 0, 'Куплет 1\nМилости Твоей полна вся земля.\nМилости Твоей полна жизнь моя.\nМилость Свою Ты превознес над судом,\nВозлюбил меня и ввел в Свой дом.\n\nПриспів\nТы спас меня и оправдал,\nОсвободил от вины\n- Благодарю Тебя!!!', '', '', 'ua', NULL, 13, '2021-03-14', NULL),
(84, 86, 'Мій Ісус пішов на небо', 0, 'Куплет 1\nМій Ісус пішов на небо, і на хмарах дуже скоро Він прийде,\nІ на хмарах Він прийде, і на хмарах Він прийде\nІ на хмарах дуже скоро Він прийде.\n\nКуплет 2\nМій Ісус пішов на небо і на хмарах дуже скоро Він прийде\nСлово Боже лишив нам , Слово Боже лишив нам\nІ сказав, щоб ми йшли по Його слідам.\n\nКуплет 3\nМій Ісус пішов на небо і на хмарах дуже скоро Він прийде\nХочем вірно ми іти, хочем вірно ми іти\nІ щоб свято все життя своє пройти.\n\nКуплет 4\nМій Ісус пішов на небо і на хмарах дуже скоро Він прийде\nВсіх спасенних Він візьме, всіх спасенних Він візьме\nВсіх спасенних в своє Царство забере.\n\nКуплет 5\nМій Ісус пішов на небо і на хмарах дуже скоро Він прийде\nЧи готовий ти ввійти, чи готовий ти ввійти\nЧи готовий ти до Господа прийти?\n\nКуплет 6\nАлілуя, Алілуя\nАлілуя, честь і слава Господу!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(85, 87, 'Мій Спаситель мій Учитель', 0, 'Куплет 1\nМій Спаситель, мій Учитель\nВін віддав Своє життя,\nЩоб могли ми свято жити\nВ повній радості життя.\n\nПрипев\nСлава Йому, Слава Христу!\nАлілуя Йому з поміж нас!\n\nКуплет 2\nВін боронить, Він хоронить\nХто прийме Його любов,\nХто повірить в воскресіння\nНа хресті пролиту кров.', '', '', 'ua', NULL, 3, '2021-04-02', NULL),
(86, 88, 'Мне хорошо в Доме Твоем', 0, 'Куплет 1\nМне хорошо в Доме Твоем, искать Твое лицо.\nТы праведность и святость, молю Тебя мой Бог\nВозьми меня в вечность Свою, возьми чтобы всегда,\nТвое лицо святое во свете видел я.\n\nКуплет 2\nВозьми меня Отец в Свою святость,\nВозьми меня как зерно и посей.\nВозьми меня Отец в Свою святость,\nВозьми как жертву моя жизнь в Тебе.\n\nКуплет 3\nПроведи сквозь внешний двор\nНа Твое святое место,\nЯ хочу Твоё видеть лицо, Господь,\nЯ ищу Тебя всем сердцем.\nОт толпы людской возьми меня\nКо святым, поющим песни,\nЖажду праведности Твоей, мой Бог,\nЗдесь единственное место.\n\nКуплет 4\nПроведи во святое святых\nЧерез Агнца кровь проведи!\nПроведи во святое святых,\nИ уста мои очисть, вот я!', '', '', 'ua', NULL, 6, '2021-03-10', NULL),
(87, 89, 'Мудрецы под вечер вышли на дорогу', 0, 'Куплет 1\nМудрецы под вечер вышли на дорогу\nТаяли как свечи звезды понемногу\nВеяли просторы ароматом хлеба\nОбращали взоры путники на небо.\n\nПрипев\nАнгелов хоралы слышны были всеми\nСкоро предстояло быть им в Вифлиеме\nВсе благоговели радостно ликуя\nВ вышыне запели Богу: «АЛИЛУЯ»!\n\nКуплет 2\nМудрецы под вечер вишли на дорогу\nТаяли как свечи звезды понемногу\nКаждый ощущает, плотью стало Слово,\nВ новый день вступает Рождество Христово!', '', '', 'ua', NULL, 0, NULL, NULL),
(88, 90, 'Мы каждый день встречаемся вновь', 0, 'Куплет 1\nМы каждый день встречаемся вновь,\nС прекрасным словом - словом “Любовь”,\nМы каждый день за ней летим в  мечтах своих.\nНо настоящей любви, увы, нам в этом мире не найти.\nНа ваш вопрос один ответ - любви без Бога нет.\n\nПрипев\nЛюбовь Христа верна и чиста,\nОна и ласкова, и нежна,\nОна объемлет всех людей\nИ покорит силой своей.\nДержитесь этой вы любви, \nОна вас к небу приведет,\nГде Иисус, спасенных ждет.\n\nКуплет 2\nНо настоящая любовь приходит с синих облаков,\nЕе дарует вечный Бог - Творец миров.\nОна несется и парит, и каждый может получить\nБез денег, злата, серебра любовь Христа.', '', '', 'ua', NULL, 1, '2020-11-16', NULL),
(89, 91, 'Над землею ніч Хваліте Христа', 0, 'Куплет 1\nНад землею ніч нависла, зорі в небі як кришталь,\nЧас настав зійшлися числа, Сина Свого Бог нам дав.\nВін прийшов в людській подобі, це є вічності буття,\nВ Ньому радість всепрощення, знає хай про це земля.\n\nПрипев\nХваліте Христа, хваліте Христа, радійте люди всі,\nВін радість приніс, Він радість приніс, роджений Божий Син\nАЛІЛУЯ!!!\nХай славить земля, хай славить земля, родженого Царя!\nхваліте, хваліте Господа Христа!\n\nКуплет 2\nІ пізнали всі народи, що містечко Вифлеєм - \nЦе колиска Заповіту, бо в Христі лиш мир знайдем.\nНад землею ніч нависла, зорі в небі як кришталь,\nЧас прийшов, зійшлися числа, Бог Спасителя нам дав.', '', '', 'ua', NULL, 0, NULL, NULL),
(90, 92, 'Наче сніг наче сніг', 0, 'Куплет 1\nНаче сніг, наче сніг,\nХоч гріхи, як багряниця\nБоже мій, знаю я,\nЩо спасенний я Тобою.\n\nКуплет 2\nЧерез кров Твою й любов\nМилість я Твою знайшов.\nЧерез віру в Тебе\nМожу бути я – (наче сніг).\n\nКуплет 3 \nНаче сніг,наче сніг\nБог твої гріхи обмиє\nКоли ти, друже мій,\nСерце Господу відкриєш.\n\nКуплет 4\nТи прийми Його в життя\nБуде радість без кінця\nВін тебе очистить\nІ вже будеш ти – наче сніг.', '', '', 'ua', NULL, 1, '2020-11-29', NULL),
(91, 93, 'Наш Спаситель воскрес', 0, 'Куплет 1\nНаш Спаситель воскрес!\nЗло і тьму переміг.\nЧесть Йому до небес,\nНебо Він для нас відкрив.\n\nПрипев\nВін воскрес, Христос воскрес! - 2рази\nСлав Його, земле вся! Він воістину воскрес!\nЦе є чудо із чудес, друг, воскрес\nВін для тебе.\n\nКуплет 2\nЛюдям радість приніс,\nНаш Господь, наш Христос,\nНам життя подарив\nСвітлом правди освітив.\n\nКуплет 3\nНе вагайся прийди,\nУ цей час поспіши,\nДвері серця відкрить,\nЩоб у нім Христос міг жить.', '', '', 'ua', NULL, 0, NULL, NULL),
(92, 94, 'Наша надія – Ти Христос', 0, 'Куплет 1\nНаша надія – Ти, Христос.\nТи наша радість, наша любов,\nТи наше щастя і життя,\nТи наше світле майбуття.\n\nПриспів\nЛиш на Тебе ми вповаєм,\nВгору руки підіймаєм,\nЛиш на Тебе споглядаєм\nВ вись до небес.\n\nКуплет 2\nТи постраждав за нас, Христос,\nТи на хресті пролив Свою кров\nІ нам спасіння вічне приніс,\nВикупив нас від горя і сліз.', '', '', 'ua', NULL, 2, '2021-03-12', NULL),
(93, 95, 'Наші дні немов птах пролітають так швидко', 0, 'Куплет 1\nНаші дні немов птах пролітають так швидко,\nНе вернути тепер їх назад.\nСкільки горя і сліз пережив ти, мій друже,\nБез Ісуса у світі ти йдеш.\n\nПрипев\nТа Ісус простягнув Свою руку до тебе,\nПоміч дасть Він тобі на земному шляху\nТи схилися до Нього, мій друже, в молитві,\nБуде радість і спокій у серці завжди.\n\nКуплет 2\nПодивись на чоло, воно вкрите лиш терном, \nКраплі крові течуть по лиці.\nСкільки болі терпів на горі тій Голгофі,\nЩоб тобі двері раю відкрить.\n\nКуплет 3\nДруже мій, що даси ти за подвиг той хресний?\nЗа ту кров, що текла за твій гріх?\nТи схилися до Нього в сердечній молитві,\nСпокій вічний тобі Він приніс.', '', '', 'ua', NULL, 0, NULL, NULL),
(94, 96, 'Не забуду я Ісуса очі', 0, 'Куплет 1\nНе забуду я Ісуса очі, коли в муках Він поглянув вгору\nІ промовив тихо: «Пити хочу», не забуду голос той ніколи.\n\nПриспів\nА сьогодні хто ще прагне, у Христі Вода Жива,\nТож приходьте і приймайте в серця Божії слова.\nІ згадайте як в годину муки, наш Христос хотів води краплину\nЦе ж для того, щоб в оцю хвилину простягнули ви до Нього руки.\n\nКуплет 2\nНе знайшлося жодної людини, щоб подать Христу води хоч трошки\nБо забули всі, що в ту хвилину, на хресті вмирав Ісус Син Божий.', '', '', 'ua', NULL, 1, '2021-01-31', NULL),
(95, 97, 'Не сравнивай свой путь с другими путями каждому свое дано', 0, 'Куплет 1\nНе сравнивай свой путь с другими путями каждому свое дано\nВремя вставать и время падать, но помни всегда одно!\n\nПрипев\nБог живой, держит жребий твой, чаша в Его руке это твоя судьба\nВерь и знай, золото не сгорит только через смерть снова приходит жизнь\n\nКуплет 2\nНе надо вспоминать старые раны, прощены все грехи\nЧтобы тебе люди не сказали с Голгофы не уходи\n\nКуплет 3\nКак диадема в Его короне однажды засияешь ты\nЕсли до конца Его дорогой захочешь мой друг идти.', '', '', 'ua', NULL, 0, NULL, NULL),
(96, 98, 'Небо красивое небо родное', 0, 'Куплет 1\nНебо красивое, небо родное, нежное небо и голубое\nКак хорошо, что ты как елей, в трудный час утешаешь людей.\n\nПрипев\nНебо для нас, это дом родной, с очень большой и мирной семьей\nКуда б не уехал везде оно, для утешенья людям дано.\n\nКуплет 2\nЧасто бывает, трудно идти, нас постигает горе в пути\nНежно глядят на нас небеса, словно глаза Иисуса Христа.\n\nКуплет 3\nМногие люди живут на земле не замечая неба нигде,\nА небо красивое, небо родное, будет оно навеки такое.', '', '', 'ua', NULL, 0, NULL, NULL),
(97, 99, 'Невеста встаньпостой чутьчуть', 0, 'Куплет 1\nНевеста встань,постой чуть-чуть\nНаверно ты уже устала.\nПриготовленья в брачный путь\nНесли забот с собой немало.\n\nКуплет 2\n// Ты долго думала о том,\nУкрасить как себя нарядно,\nЧтоб пред заветным женихом\nСтоять красивой и приятной.// 2 раза.\n\nКуплет 3\nО чём задумался жених,\nНе трудно нам себе представить,\nНо в результате для двоих,\nОн смог всех на ноги поставить.\n\nКуплет 4\n//Теперь ты тоже чуть постой,\nПостой немножко перед нами,\nПосмотрим мы кто ты такой\nТеперь, придирчиво глазами// 2 р.\n\nКуплет 5\nНе хорошо быть одному,\nЕщё трудней бывает вместе.\nСедеют реже потому,\nЛишь кто остался без невесты!\n\nКуплет6\n//Теперь вам поздно говорить,\nА многим здесь ещё не поздно.\nИ прежде чем совместно жить\nДрузья подумайте серьёзно// 3р', '', '', 'ua', NULL, 0, NULL, NULL),
(98, 100, 'Нема Бога більшого як наш', 0, 'Куплет  1\nНема  Бога більшого, як наш, нема, нема (2p)\nНема такого Бога, як наш Великий Бог! (2p)\n\nКуплет 2 \nНе нашою силою, не нашою мудрістю,\nЛиш тільки Духом Святим -  \nА ми все горе пережевем (3p)\nСилою, Духом Святим.\n\nКуплет 3\nNo hay Dios tan grande como Tu\nNo lo hay no lo hay. (2v)\nNo ha Dios que pueda hacer las obras \nComo las que haces Tu. (2v)\n\nКуплет 4\nNo es con espada ni con ejercitos \nMas con su Santo Espiritu. (2v)\nY esas almas se salvarán (3v)\nCon su Santo Espiritu.', '', '', 'ua', NULL, 4, '2021-03-28', NULL),
(99, 101, 'Немає проблеми в житті щоб Бог не міг рішати', 0, 'Куплет 1\nНемає проблеми в житті, щоб Бог не міг рішити\nЧи гір високих таких, щоб їх не міг здвигати.\nНемає бурі й вітрів, щоб не вгамувати,\nНемає смутку й журби, щоб Бог не міг втішати.\n\nПрипев\nЯк поніс на плечах тягар цілого світу,\nТягар твій, мій брате і сестро, Він понесе.\n\nКуплет 2\nНемає хвороби в житті, щоб Бог не міг зцілити\nЧи болю такого й біди, щоб Бог не міг змінити\nКоли тягар твоєї душі, почне так гнітити\nЗвернись до Бога і вір, Він може зміцнити.', '', '', 'ua', NULL, 5, '2020-07-26', NULL),
(100, 102, 'Ночных небес распахнутая вечность', 0, 'Куплет 1\nНочных небес распахнутая вечность\nСквозь зыбкий свет далеких вечных звезд\nДуша глядит в Твои глаза Спаситель\nНе пряча слез, не пряча слез.\n\nПрипев\nТы помнишь, Боже горький привкус этой боли\nСлова бессильны горечь передать\nИ знает серце как звучит Твой взгляд и голос\nКак Ты умеешь в скорби сострадать.\n\nКуплет 2\nС высот течет распахнутая вечность\nСквозь зыбкий свет далеких вечных звезд\nИ Бог глядит с небес в сердца людские\nНе пряча слез, не пряча слез.\n\nКуплет 3\nКак искры гаснут тихие минуты\nИ невесомым стал печали гнет\nСтремится дух в бескрайние высоты\nГде слезы наши Бог отрет.', '', '', 'ua', NULL, 0, NULL, NULL),
(101, 103, 'О как прекрасный белый свет', 0, 'Куплет 1\nО как прекрасный белый свет,\nВзгляни на высь, лазурь небес.\nНа зелень, травы, синь морей\nИ улыбнись скорей - скорей.\n\nКуплет 2\nНу что же ты так хмуришься?\nТы посмотри какое небо ясное.\nНу что же ты так хмуришься? \nТы посмотри как все прекрасно.\n\nКуплет 3\nНу что же ты так хмуришься? \nНеужто, белый свет тебя не радует.\nНу что же ты так хмуришься?\nВедь Бог тебя так любит, ну и радуйся.\n\nКуплет 4\nВедь наш Господь все так создал, \nЧтоб я и ты не унывал.\nНо увидав всю красоту\nТы Господу воспел хвалу.\n\nКуплет 5\nИ хоть печали на земле\nНас не проходят стороной,\nМы все ж стремимся к той стране,\nНа небе ждет наш дом родной.', '', '', 'ua', NULL, 0, NULL, NULL),
(102, 104, 'О алілуя амінь Царство Боже близько', 0, 'Куплет 1\nО, алілуя, амінь! Царство Боже близько.\nО, алілуя, амінь! Схиліться в дусі низько.\nО, алілуя, амінь! Складіть всі славу Богу.\n\nПриспів\nАлілуя, алілуя, слава Богу\nАлілуя, алілуя, Дух Святий.\n\nКуплет 2\nО, алілуя, амінь! Живе Отець на небі.\nО, алілуя, амінь! Куди прийдуть всі діти.\nО, алілуя, амінь! В Його ми будем світлі.\n\nКуплет 3\nО, алілуя, амінь! Співайте пісню в дусі.\nО, алілуя, амінь! Немає місця смутку.\nО, алілуя, амінь! Візьміться всі за руки.', '', '', 'ua', NULL, 0, NULL, NULL),
(103, 105, 'Одна листва одна листва от всех твоих трудов', 0, 'Куплет 1\nОдна листва, одна листва, от всех твоих трудов.\nГде плод посева твоего? - Спаситель ждет его давно. / \nТы не принес плода, одна листва…. /2р.\n\nКуплет 2\nОдна листва, одна листва, как любишь ты Христа?\nТебя до смерти возлюбил, чем ты Исусу заплатил? /\nТы не принес плода, одна листва… /2р.\n\nКуплет 3\nОдна листва, одна листва, ты не принес плода.\nКаким предстанешь пред судом и что ответишь пред Христом?/\nПогибнешь навсегда, одна листва… /2р.\n\nКуплет 4\nОдна листва, одна листва, и лишь одни слова:\nГосподь грядет! А ты все спишь, “еще успею”- говоришь. /\nГосподь зовет:”вставай Я жду плода”. /2р.\n\nКуплет 5\nОдна листва, одна листва, но можно жить с плодом.\nЯ буду жить лишь для Христа, я буду радостным всегда,\nТогда на небеса приду с плодом.\nМы будем жить лишь для Христа, мы будем радостны всегда,\nТогда на небеса придем с плодом!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(104, 106, 'Одного ранку ще до світанку', 0, 'Куплет 1\nОдного ранку, ще до світанку\nЖінки до гробу разом прийшли,\nТа гріб порожній, так, як сказав Він,\nНа третій день Він смерть переміг.\n\nПриспів\nЯк не воскрес би Ісус Спаситель,\nТо де ж надія була б моя?\nСмерть подолав Він, воскрес із мертвих\nІ життя вічне нам дарував!\n\nКуплет 2\nЖиву надію Христос подав нам,\nТаку надію хто міг би дать?\nНа третій день Він воскрес із мертвих,\nКайдани смерті Він розірвав!\n\nКуплет 3\nВін обіцав нам, що скоро прийде\nЗабрати нас до осель Своїх.\nЯк річку смерті ми перейдемо,-\nНа березі нас чекає Він', '', '', 'ua', NULL, 2, '2021-04-04', NULL),
(105, 107, 'Осанна осанна осанна Тобі Цар царів', 0, 'Куплет 1\nОсанна, осанна, осанна Тобі, Цар царів! (2р.)\n\nПриспів:\nМи підносим Тебе серцем повним хвали,\nДухом ми піднесем Тебе. Осанна Тобі, Цар царів!\n\nКуплет 2\nМи любим (3р.) Тебе, Цар царів! (2р.)\n\nКуплет 3\nМи славим (3р.) Тебе, Цар царів! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(106, 108, 'Ось знову день як мить пробіг минає так життя', 0, 'Куплет1\nОсь  знову день, як мить, пробіг, минає так життя,\nТі сірі будні суєти, в яких Христа нема.\nКоли ж приходить Він в тиші\nХоч в дощ, хоч в град, хоч в сніг –\nВсе оживає у мені, і сум зникає вмить.\n\nПриспів:\nІсус, о Ісус! Тебе побачу я колись. \nІсус, о Ісус! З Тобою хочу буть завжди.\n\nКуплет2\nДо Тебе я прийшов в мольбі, нічого не скривав.\nСказав: «Ісус, пробач мені». Мені Ти руку дав.\nІ з того часу у житті\nЧи в дощ, чи в град, чи в сніг ,\nТак тихо й вільно на душі, коли Ти поруч є.\n\nКуплет3\n І не забуть мені любві  Твоїх пробитих рук,\nЩо дарували і мені спасіння від всіх мук.\nЯ вірю : зустріч близька ця.\nТуди всім серцем рвусь.\nТам мрія збудеться моя, з Тобою  я зіллюсь.', '', '', 'ua', NULL, 0, NULL, NULL),
(107, 109, 'Отец и Сын и Дух Святой', 0, 'Куплет 1\nОтец и Сын и Дух Святой\nСвятая Троица\nПризри с небес в стране родной\nНарод Твой молится\n\nПрипев \nТебе мы молимся, О Дух Святой\nТебя мы славим в этот час, Святая Троица\nДай силы верными быть до конца\nХоть мало сильных среди нас, но Церковь строится\n\nКуплет 2\nТы силу в церкви прояви \nКак в дни начальные.\nИ радостью благослови\nСердца печальные.\n\nКуплет 3\nИз года в год, то тут, то там\nНам ямы роются,\nНо Церковь даже среди ям\nЕдина строится.\n\nКуплет 4\nО помоги благую весть\nЧто нам предана\nПод знаменен Твоим пронесь \nОхотно, предано!', '', '', 'ua', NULL, 1, '2020-10-25', NULL),
(108, 110, 'Побажаєм тобі удачі щоб побачить зірки як тануть', 0, 'Куплет 1\nПобажаєм тобі удачі, щоб побачить зірки як тануть,\nЩоб почути як люди плачуть, коли їх задарма ображають.\n\nКуплет 2\nПобажаєм тобі дороги крізь вітри, сніги, буревії\nПобажаєм тобі тривоги, щоб завжди міг людиною бути.\n\nКуплет 3\nПобажаєм тобі печалі, щоб побачив чуже ти горе,\nЩоб почув ти як плачуть чайки, коли хвилі бурлять у морі.\n\nКуплет 4\nПобажаєм тобі удачі, в кожнім слові і в кожнім ділі,\nЯкщо з Господом йдеш ти поряд значить вірно обрав ти цілі!', '', '', 'ua', NULL, 0, NULL, NULL),
(109, 111, 'Поглянь кругом на діло рук Творця', 0, 'Куплет 1\nПоглянь кругом на діло рук Творця:\nНа небо й землю, що Господь створив.\nНайбільше чудо сталось на хресті - \nДе Бог від пекла нас звільнив.\n\nПрипев\nСтворив Бог небо, землю, поле і ліси,\nЛишив Він неба славу, у цей світ прийшов.\nЦього часу ти не гай, прийди до Господа\nВ Нім спасіння ти знайдеш.\n\nКуплет 2\nО, любий друже, поглянь на себе\nЯк скоро роки,час твій біжить.\nЖиття твоє, мов сон той промине...\nДе будеш в вічності ти жить?\n\nКуплет 3\nЯкщо ти приймеш Господа Христа - \nТебе спасе Він від твого гріха.\nВін приведе тебе в той вічний край - \nДе горя й сліз вже більш нема.', '', '', 'ua', NULL, 0, NULL, NULL),
(110, 112, 'Под кровом Всевышнего и Всемогущего Бога', 0, 'Куплет 1\nПод кровом Всевышнего и Всемогущего Бога\nНе испугает меня никогда темнота.\nНа гору святую ведет меня жизни дорога,\nДорога оплачена кровью Иисуса Христа.\n\nПрипев\nВ крови Иисуса: победа и жизнь!\nТы за Иисуса держись!\nВ крови Иисуса: свобода и жизнь\nТы за Иисуса держись!\n\nКуплет 2\nПод кровом Всевышнего и Всемогущего Бога\nЛьва и дракона ты будешь ногой попирать.\nНа гору святую ведет тебя жизни дорога,\nДорога оплачена кровью Иисуса Христа', '', '', 'ua', NULL, 2, '2020-08-16', NULL),
(111, 113, 'Подивись на зграї журавлів як курличуть пісню свою', 0, 'Куплет 1\nПодивись на зграї журавлів, як курличуть пісню свою\nДружно як вони піднялись, в синє небо разом понеслись\nІ летять в блакить вони, вище вище від землі\nВ небо направляють свій взір, їм відкритий неба простір.\n\nКуплет 2\nНеможливо їх зупинить, шлях до неба загородить\nЯкщо навіть захочеш спіймать і біднягу в клітці тримать\nТо за небом тужить він, прагнуть буде в небес височінь\nПісня щастя змовкне тоді, від журби, від журби.\n\nКуплет 3\nІ коли побачить він знов, ключ летячих над ним журавлів\nБуде рватись він в небеса, там де простір і воля свята\nВін покине печаль земну і полине до них в висоту\nВ вишині голубій неземній, воля там, радість там і спокій.\n\nКуплет 4\nВсі ми люди птахи земні, справляймо крила свої\nБо той час вже скоро прийде, Ісус нас в небо візьме\nТи готовий в політ в небеса, чи в кайданах твоя ще душа?\nТи звернися до Бога в мольбі, розірве Він кайдани твої\n\nКуплет 5\nПрийде щастя до тебе тоді, ти радітимеш серцем усім\nІ звільнившись від марноти інших зватимеш в Божі краї\nТи покинеш печаль земну і полинеш в небес висоту\nВ вишині голубій, неземній щастя там, радість там і спокій.', '', '', 'ua', NULL, 0, NULL, NULL),
(112, 114, 'Пожелаю тебе удачи', 0, 'Куплет 1\nПожелаю тебе удачи,\nЧтобы видеть, как звезды гаснут,\nЧтобы слышать, как люди плачут,\nКогда их обижают напрасно.\n\nКуплет 2\nПожелаю тебе в дороге\nИ снегов, и ветра, и вьюгу.\nПожелаю тебе тревоги,\nЧтобы был ты всегда человеком.\n\nКуплет 3\nПожелаю тебе печали,\nЧтобы видеть чужое горе,\nЧтобы слышать, как стонут чайки,\nКогда шторм закипает в море.\n\nКуплет 4\nПожелаю тебе удачи,\nВ каждом слове, и в каждом деле.\nЕсли с Господом путь твой начат - \nЗначит: к верной идешь ты цели.', '', '', 'ua', NULL, 0, NULL, NULL),
(113, 115, 'Поздравляем с Днем рожденья', 0, 'Куплет 1\nПоздравляем с Днем рожденья,\nСветлым праздником в году,\nДолгожданным днем веселья,\nПриходящим раз в году.\n\nПрипев\nА года проходят быстро,\nНаправляя в вечность нас,\nОтдаляя нас от детства\nКаждый миг и каждый час.\n\nКуплет 2\nТы становишься взрослее -\nС днем рожденья очередным!\nНо ты в Боге пребывая,\nБудешь вечно молодым.\n\nКуплет 3\nНо с годами не стареет.\nХристианская душа.\nОна в Боге пребывая,\nПрославляет век Христа!', '', '', 'ua', NULL, 0, NULL, NULL),
(114, 116, 'Пой Господу вся земля о спасении Его говори', 0, 'Куплет 1\nПой Господу вся земля, о спасении Его говори. \nЕго чудеса и слава возвещаются по всей земле. \nГосподь, Ты велик, силой и могуществом , \nЛикуй, ликуй, ибо Господь царствует.\n\nКуплет 2\nБудем праздновать день Спасения с новой песней на устах,\nБог нас воскресил, Бог нас посадил во Христе на небесах.\nБудем славить Господа в наших сердцах\nБудем славить с новой песней на устах.\n\nКуплет 3\nАлилуя (Алилуя) Алилуя (Алилуя) Алилуя Алилуя - 2р.\nГосподь, Ты велик силой и могуществом \nЛикуй, ликуй, ибо Господь царствует\nВовек!', '', '', 'ua', NULL, 0, NULL, NULL),
(115, 117, 'Порою тяжко йти дорогою вузькою', 0, 'Куплет 1\nПорою тяжко йти дорогою вузькою\nПорою гріх на душу натиска.\nТоді до Тебе йду з сердечною мольбою:\nТримай мене, Ісус не відпускай.\n\nПрипев\nТримай тоді, коли, можливо, і не встояв\nКоли гріхом образив я Тебе\nІ знов до Тебе я з молитвою простою\nНаправлю погляд віри до небес.\n\nКуплет 2\nНемає часто сил, покірним буть слугою\nНе в змозі я страждать, любить, прощать.\nЯ знов до Тебе йду з гарячою мольбою:\nДопоможи по Слову поступать.\n\nКуплет 3\nТоді, коли навкруги буря неспокою\nТривожить душу, вітром б’є в лице.\nЛише з Тобою у молитві заспокоюсь, \nМій милостивий, лагідний Отець!', '', '', 'ua', NULL, 0, NULL, NULL),
(116, 118, 'Прийди Дух Святий прийди', 0, 'Куплет 1\n//Прийди, Дух Святий, прийди \nНаповни мене Силою Своєю //\n\nКуплет 2\nВіднови мене, омий мене,\nОчисть мене і освяти, Господь,\nСилою Своєю!\n(до Тебе прагну я).\n\nКуплет 3\n//Ven, Espíritu Ven\nY lléname Señor con Tu preciosa unción//\n\nКуплет 4\nPurifícame y lávame, renuévame,\nRestáurame Señor, con Tu poder.\nTe quiero conocer!', '', '', 'ua', NULL, 6, '2021-01-31', NULL),
(117, 119, 'Прикоснись ко мне Дух Святой', 0, 'Куплет 1\nПрикоснись ко мне Дух Святой.\nПрикоснись ко мне Дух Святой.\nПодними меня подними,\n Над землей, над землей, над землей.\n\nКуплет 2\nЛишь в ладонях Твоих ощущаю любовь,\nЛишь в ладонях Твоих ощущаю тепло.\nЛюбимый Отец, любимый Отец.\n\nКуплет 3 \nОкружи меня Дух Святой.\nОкружи меня Дух Святой.\nПодними меня подними, \nНад землей, над землей, над землей.\n\nКуплет 4\nЛишь в ладонях Твоих ощущаю любовь,\nЛишь в ладонях Твоих ощущаю тепло.\nЛюбимый Отец, любимый Отец.', '', '', 'ua', NULL, 0, NULL, NULL),
(118, 120, 'Прихожу к Тебе я с хвалою', 0, 'Куплет 1\nПрихожу к Тебе я с хвалою,\nЧудеса Твои велики и любовь Твоя сильна!\n\nПрипев\nО, Ты велик, Ты прекрасен, Ты велик!\nИ другого нет, как Ты! (2р.)\n\nКуплет 2\nБуду петь Тебе я славу вечно \nЗа Твою любовь и милость, что даришь Ты нам с небес.\n\nКуплет 3\nТы один достоин всей хвалы!\nМы возносим к небу руки, в Тебе радуемся мы.\n\nКуплет4\nQueremos darte gloria, y alabanza,\nLevantamos nuestras manos, exaltándote Señor.\n\nПрипев:\nGrande eres Tú, grandes Tus milagros son\nNo hay otro como Tú, no hay otro como Tú.', '', '', 'ua', NULL, 2, '2021-02-26', NULL),
(119, 121, 'Пусть в сердце твоем нет места пустого', 0, 'Куплет 1\nПусть в сердце твоем, нет места пустого\nКогда в нем любовь, когда любишь много\nТы можешь сейчас любовью делиться\nОна ведь не раз к тебе возвратится\n\nПрипев\nОт сердца к сердцу любовь может путь проложить\nОт сердца к сердцу весь мир обретешь\nОт сердца к сердцу, чтоб всех людей обьеденить\nЛюбовь идет, от сердца к сердцу\n\nКуплет 2\nСветлее вокруг и легче дорога\nКогда рядом друг, когда друзей много\nИ если один, продолжишь ты путь свой\nТо смело иди с любовью Иисуса!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(120, 122, 'Раскрутились часы на обратный отсчет', 0, 'Куплет 1\nРаскрутились часы, на обратный отсчет,\nЯ совсем потерялся в годах\nВремя помнит и знает, ведет пересчет, \nДень за днем, от сейчас , до тогда.\nЛет мне тридцать, пятнадцать и я совсем юн\nВсе часы прокрутили назад\nИ как хочется мне, заменить черед струн\nЧтобы радость была вся подряд.\n\nКуплет 2\nСердце чистое не плачет, но слеза бежит и пусть\nЯ был слеп, хотя и зрячий, знал я радость, знал и грусть\nСердце чистое не плачет, Иисус мой верный Друг\nЯ пою живу иначе, это в сердце веры стук.\n\nКуплет 3\nЗаменить хочу жизнь, где прожил без Христа,\nТолько время имеет свой ход\nВсе стереть и забыть, где немели уста\nА душа все искала обход.\n\nКуплет 4\nРаскрутились часы, на обратный отсчет\nЯ совсем потерялся в годах.\nБог судья знает все и ведет пересчет\nДень за днем, от сейчас, до тогда.', '', '', 'ua', NULL, 0, NULL, NULL),
(121, 123, 'Світлом засяй мій Господь у темряві', 0, 'Куплет 1\nСвітлом засяй, мій Господь, у темряві,\nОчі мої просвіти.\nДай, щоб побачив красу Твою в славі,\nНадію в житті укріпи.\n\nПриспів\nОсь я, щоб схилитись, ось я, щоб вклонитись,\nОсь я, щоб сказати: «Ти – мій Бог».\nТи – моя твердиня, Ти – моє спасіння,\nТи – моє натхнення, мій Господь.\n\nКуплет 2\nВічності Цар, Ти безмежно величний,\nВищий за славу небес.\nВ світ Ти прийшов, як той Агнець покірний,\nРади людей йшов на хрест.\n\nКуплет 3\nНіколи я не осягну мого відкуплення ціну!\nТи поклич Бога в серце своє - Він спасе тебе!', '', '', 'ua', NULL, 2, '2021-04-02', NULL),
(122, 125, 'Свят Свят Свят Господь', 0, 'Куплет 1\nСвят! Свят! Свят Господь!\nСвято имя Твое.\nСвят! Свят! Свят Господь!\nСвято имя Твое.\n\nКуплет 2\nВоздеваю свои руки \nКо святому храму Твоему,\nПоклоняюсь я Тебе \nВо благолепии святыни.\n\nRefrain\nДа святится имя Твое,\nДа святится имя Твое, \nДа святится имя Твое,\nО, Господь!\n\nКуплет4\nСвят! Свят! Свят Господь!\nСвято имя Твое!', '', '', 'ua', NULL, 5, '2021-03-21', NULL),
(123, 126, 'Скажи ну что тебя сюда ведет', 0, 'Куплет 1\nСкажи, ну что тебя сюда ведет?\nОтветь, ну что тебя сюда влечет?\nИ от чего твои глаза горят,\nТакой счастливый и открытый взгляд.\n\nПрипев\nЭто любовь, Божья любовь, она зальет все, заполнит все.\nЭто любовь, Божья любовь, все в мире пройдет, кроме нее.\n\nКуплет 2\nЯ возвожу к Иисусу сердца взгляд.\nИ знаю: мой Господь мне очень рад.\nВ ответ с престола льется на меня\nВода живая, свет Его огня.', '', '', 'ua', NULL, 1, '2020-08-23', NULL),
(124, 128, 'Скоро скоро вже ми побачимо Христа', 0, 'Куплет 1\nСкоро,  скоро вже ми побачимо Христа (3р.)\nАлілуя ! Алілуя ! Побачимо Христа.\n\nКуплет 2\nСльози Він зітре, як побачимо Христа  (3р.)\nАлілуя ! Алілуя ! Побачимо Христа.\n\nКуплет 3\nРадість буде там – Ми побачимо Христа. (3р.)\nАлілуя! Алілуя! Побачимо Христа.\n\nКуплет 4\nСмерті там нема – ми побачимо Христа. (3р.)\nАлілуя! Алілуя! Побачимо Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(125, 129, 'Скоро скоро придет наш Спаситель', 0, 'Куплет 1\nСкоро, скоро придет наш Спаситель\nВот уж время Его настает\nОн возьмет нас тогда в ту обитель\nГде не будет ни слез ни забот.\n\nПрипев\nТам, за горизонтом, Родина нас ждет\nТам, за горизонтом, встретимся с Христом.\n\nКуплет 2\nТы ведь здесь только временный житель \nДом твой там далеко в небеса \nЗаберет всех своих наш Спаситель\nИ останемся там навсегда.\n\nКуплет 3\nБудет там вечной славой наполнен\nКаждый взгляд и все наши сердца\nНо в Христову обитель войдет тот\nКто был верен Ему до конца.', '', '', 'ua', NULL, 0, NULL, NULL),
(126, 130, 'Скрой меня Своим крылом', 0, 'Куплет 1\nСкрой меня Своим крылом,\nСохрани под сильною рукой.\n\nПрипев\nПусть бушует шторм и гром гремит,\nНад бурей буду я с Тобой парить.\nМой Отец, Ты - Царь над всей землей,\nЯ не боюсь, мой Бог со мной!\n\nКуплет 2\nНайду покой в Тебе Христос,\nВерю я в могущество Твое.', '', '', 'ua', NULL, 2, '2020-10-16', NULL),
(127, 131, 'Славлю славлю я Тебе Господь', 0, 'Куплет 1\nСлавлю, славлю я Тебе Господь, прославляю Твою благодать\nТобі співаю я Алілуя, Тобі співаю я Алілуя!\n\nКуплет 2\nСлавлю, славлю я Тебе Господь, прославляю ласку я Твою\nТобі співаю я Алілуя, Тобі співаю я Алілуя!\n\nКуплет 3\nСлавлю, славлю я тебе Господь, прославляю я Твою любов\nТобі співаю я Алілуя, Тобі співаю я Алілуя!\n\nКуплет 4\nСлавлю, славлю я Тебе Господь прославляю милість я Твою\nТобі співаю я Алілуя, Тобі співаю я Алілуя!', '', '', 'ua', NULL, 0, NULL, NULL),
(128, 132, 'Совершенство Твое не имеет границ', 0, 'Куплет 1\nСовершенство Твое не имеет границ,\nЯ ценю каждый миг жизни с Тобою.\nТы бессилье мое утираешь с ресниц,\nНаполняешь меня верой живою!\n\nКуплет 2\nЯ предвкушаю красоту поклонения,\nЯ воздеваю руки к Тебе, без страха и сомнения!\n\nПриспів \nСовершенный Бог, поклоняюсь я, \nСвятостью Своей осени меня,\nТеплотой согрей, силой одари.\nНичего нет ценнее Твоей совершенной любви!!!\n\nКуплет 4\nЯ наслаждаюсь глубинной поклонения,\nЯ воздеваю руки к Тебе, без страха и сомнения!\n\nКуплет 3\nСовершенный Бог, поклоняюсь я, \nСвятостью Своей осени меня,\nТеплотой согрей, силой одари.\nНичего нет ценнее Твоей совершенной любви!!!', '', '', 'ua', NULL, 6, '2021-03-07', NULL),
(129, 133, 'Спасителю дозволь мені', 0, 'Куплет 1\nСпасителю, дозволь мені \nЗ Тобою йти всі дні.\nНавчай мене, як маю я \nТерпіти всі турботи дня.\n\nКуплет 2\nМені в журбі розраду дай\nІ радощами світ сповняй.\nНе дай піти на манівець-\nВеди додому навпростець.\n\nКуплет 3\nНадії промені пішли,\nСпасіння стежку освіти,\nСпокій моєму серцю дай,\nІти до неба помагай.\n\nКуплет 4\nНести мій хрест мене навчай,\nМене самого не лишай.\nУ певності провадь у ціль,\nЩо Спасе Ти рятунок мій.', '', '', 'ua', NULL, 0, NULL, NULL),
(130, 134, 'Спішу до тебе дні і ночі несу життя земного хрест', 0, 'Куплет 1\nСпішу до Тебе дні і ночі,\nНесу життя земного хрест,\nМені Ти дивишся у очі\nЛаскавим сонцем із небес.\nІ вже душа дзвінка, як жайвір,\nЇї теплом зігріта плоть.\nЯк до землі дощі врожайні, \nСпішу до Тебе, мій Господь.\n\nПрипев:\nГолос Твій далекий \nМені про вічність нагадав,\nСпішу до Тебе, як лелеки \nСпішать до рідного гнізда.\n\nКуплет 2\nКрізь ватру днів, що не згасити,\nЗелену тишу яворів,\nСпішу до Тебе, мій Спаситель, \nОтак, як ріки до морів.\nІ серце повниться любов’ю, \nПриймає радість каяття:\nХто прагне зустрічі з Тобою \nНе кане в прірву забуття.', '', '', 'ua', NULL, 0, NULL, NULL),
(131, 135, 'Струиться свет переливаясь радугой', 0, 'Куплет 1\nСтруиться свет переливаясь радугой\nЗвезда сияет в вышыне маня\nИ безконечность ее света радует\nИ освещает дальние меры\n\nПрипев\nДобрый мир ето Он, чудный свет ето Он\nИ любовь ето Он, между мной и тобой\nВсе простит, только Он, исцелит только Он\nЗащитит нас с тобой, только Он.\n\nКуплет 2\nО как нам хочеться порой дотронутся\nКоснуться сердца теплоты Его\nМы как младенцы перед Ним безпомощны\nИ уповаем только на Него.\n\nКуплет 3\nНа нас лежит непережитое страдание\nИ кровь Его над нами словно щит.\nИ открывая доброе Евангелие\nСливаясь с Ним мы учимся любить.', '', '', 'ua', NULL, 0, NULL, NULL),
(132, 136, 'Сын мой как долго Я ждал', 0, 'Куплет 1\nСын мой, как долго Я ждал, зимы и весны, Я годы считал\nНочью и днем за порог выбегал, Я ждал\nЯ знал твои терзанья души, Я видел слезы в полночной тишы\nТам за стеной в беспроссветной глуши, годы шли.\n\nПрипев\nЯ не хочу жить за завесой, Я не хочу жить за стеною глухой,\nМое сердце с тобой, мой сын дорогой. \nЯ для тебя не чужой и не отчим, Я добрый Отец, Я Авва Отче, родной\nМое сердце с тобой, мой сын дорогой.\n\nКуплет 2\nГрех барьер глухая стена, грех это бездна и пропасть без дна\nНебо без звезд, а ночь так темна без сна.\nГрех произвел непреступнейшый вал, ты уходил когда Я взывал\nРуки Свои к тебе простирал, Я звал.\n\nКуплет 3\nВ небо открыт единственный путь, Отец через Сына желает вернуть\nПотеряный рай для тебя и меня, вот в чем суть.\nИисус спасенье открытая дверь, входи человек и живи без потерь\nВ Царстве Моем нет страданья и зла, о поверь!\n\nКуплет 4\nСын мой, так долго Я жду\nЛюбовью вечной Тебя Я люблю\nИ встречи с тобой в Царстве Моем Я жду!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(133, 137, 'Сьогодні ясна зіронька небесна появилась', 0, 'Куплет 1\nСьогодні ясна зіронька небесна появилась,\nІ ясним сяєвом своїм світ темний освітила.\n\nПриспів\nОтож славімо Бога враз, \nЗа те що нас від смерті спас. \nОсанна! Осанна! Осанна вічна Богу честь!\n\nКуплет 2\nСьогодні співи ангельські по світі скрізь лунають,\nЩо Бог змінив, послав людям, про це усім звіщають.\n\nКуплет 3\nГосподь любов свою для нас спішить нині відкрити, \nЩоби спасти нас від гріха і з Богом примирити.\n\nКуплет 4\nСьогодні вістка ця бринить, щоб час пророцтв сповнився \nІ Бог Спасителя нам дав в вертепі народився.\n\nКуплет 5\nХай нині дружно кожен з нас радіє і співає, \nЩо Бог на ласку гнів змінив і нас благословляє.', '', '', 'ua', NULL, 0, NULL, NULL),
(134, 138, 'Так долго так долго искал', 0, 'Куплет 1\nТак долго, так долго искал\nСокровищ на этой земле.\nКое-что находил, а что потерял –\nТак было в жизни моей.\n\nКуплет 2\nСокровища я так ценил \nВсе те, что я приобрел.\nПока драгоценную чудо- жемчужину\nЯ наконец не нашел.\n\nКуплет 3\nТы - моя жемчужина Иисус, самая большая\nВсе сейчас свое я продаю, Тебя приобретая.\nБольше мне не нужен этот груз,\nТы - моя жемчужина Иисус\nСамая большая, самая большая\n\nКуплет 4\nТы - моя жемчужина Иисус, сердце замирает \nВсе сейчас свое я продаю, Тебя приобретая.\nНо ведь это Ты меня нашел,\nИ Своею кровью приобрел на кресте страдая.', '', '', 'ua', NULL, 0, NULL, NULL),
(135, 139, 'Там далеко за облаками встретит меня Иисус', 0, 'Куплет 1\nТам далеко, за облаками, встретит меня Иисус,\nНежно обнимет своими руками, с Ним я навеки сольюсь.\n\nПрипев\nА пока живу я в мире странником \nИ с тоской смотрю я в небеса.\nС небом связаны мои желания,\nС небом связана моя судьба.\n\nКуплет 2\nМне распахнут райские двери, радостно скажут:” входи”\nВсе это будет, твердо я верю, но это лишь впереди.\n\nКуплет 3\nТам навсегда скорби забуду, в небе улыбка царит,\nТам с Иисусом вечно я буду в сладком общении жить.', '', '', 'ua', NULL, 0, NULL, NULL),
(136, 140, 'Твоїм я спасінням радію о Боже', 0, 'Куплет 1\nТвоїм я спасінням радію, о Боже,\nІ славлю Тебе за святую любов.\nНіхто тої радості вкрасти не зможе,\nБо Ти і за мене пролив свою кров. 2р.\n\nПрипев\nДо тої країни душею я лину,\nЧекаю коли та хвилина прийде,\nКоли Тебе в славі на хмарах зустріну\nКоли Твоє царство повіки буде.\n\nКуплет 2\nІ славлю Тебе я піснями хваління\nІ пісня підноситься ген до небес.\nДля тих, що прийняли від смерті спасіння\nВведеш Ти в країну спокою й чудес. 2р.', '', '', 'ua', NULL, 0, NULL, NULL),
(137, 141, 'Тебе я величаю о Господь', 0, 'Куплет 1\nТебе я величаю, о Господь!\nБог Єдиний на небі і на землі! (2р.)\n\nПриспів\nТи Один достойний всю славу прийнять,\nВоскреслий із мертвих, Агнець Господній.\nНародам усім, Ти дарував спасіння.\nІ тепер ми приносим 3р. \nСлаву Тобі!', '', '', 'ua', NULL, 0, NULL, NULL),
(138, 142, 'Ти мій притулок є моєму серцю Ти даєш', 0, 'Куплет 1\nТи -  мій притулок є,\nМоєму серцю Ти даєш\nСилу, Божий Дух, \nЯк тільки я засмучусь...\nВ Тебе вірю я!!!\n\nКуплет 2\nВ Тебе вірю я,\nВ Тебе, мій Господи, \nДаєш силу, Господь!!!', '', '', 'ua', NULL, 2, '2020-11-15', NULL),
(139, 143, 'Ти непохитна скеля в морі зла', 0, 'Куплет 1\nТи непохитна скеля в морі зла,\nДе відпочину від штормів життєвих я.\nТи мій притулок серед горя і тривог,\nНадія, радість, пісня - Ти мій Бог!\n\nКуплет2\nБез тебе в світі я не проживу\nТи віру дай мені велику і живу.\nМені без Тебе, як в пустелі без води\nУсі мої джерела Господи в Тобі!\n\nПрипев\nБез Тебе так душа моя болить,\nБез Тебе пісня в серці не бринить.\nБез Тебе ні надії, ні життя,\nНі віри у щасливе майбуття.\n\nКуплет 3\nНе відпусти мене із Своїх сильних рук,\nБо найстрашніша із усіх розлук, - \nРозлука з Тобою, Батьку мій,\nБез тебе не прожити на землі.\n\nКуплет4\nЗ Тобою зникнуть болі всі мої\nІ знову пісня в серці забринить.\nВ Тобі моя надія і життя, \nІ віра у щасливе майбуття!!!', '', '', 'ua', NULL, 4, '2021-02-28', NULL),
(140, 144, 'Тихо погас в ночи закат', 0, 'Куплет 1\nТихо погас в ночи закат,\nСад Гефсиманский сном обьят\nВсеми оставлен и забыт, Сын Божий там душой скорбит.\nНет рядом с Ним учеников,\nИ пот багряный словно кровь\nС лица Его на камень тек, поверить трудно что Он Бог\nПоверить что Он Бог!\n\nПриспів\nКто Ты, чтобы так страдать?\nКто Ты, как же нам понять?\nТы Бог, молишься, скорбишь\nТвой час настал, за всех умирать.\n\nКуплет 2\nЛишь только камни видя кровь\nСмогли понять, что есть любовь\nНо только сердце у людей, куда холоднее камней,\nХолоднее камней.', '', '', 'ua', NULL, 1, '2021-01-31', NULL),
(141, 145, 'Тобі хочу я співать “Алілуя”', 0, 'Куплет 1\nТобі хочу я співать “Алілуя”!\nО, мій Господь, я Тобою живу.\nЗа радість спасіння Тебе прославляю\nІ “Алілуя “співаю.\n\nКуплет 2\nСила Твоя – і смерть влади не має,\nТвоя любов – серце добрим стає.\nВічний мій Бог, я Тебе прославляю,\nІ “Алілуя” співаю.\n\nКуплет 3\nЯ прагну так скрізь Тобі бути вірним,\nЖити з Тобою, співати Тобі.\nЧашу страждання з Христом поділяю\nІ “Алілуя” співаю.', '', '', 'ua', NULL, 4, '2021-03-21', NULL),
(142, 146, 'Ту важку перемогу Агнець Божий придбав', 0, 'Куплет 1\nТу важку перемогу Агнець Божий придбав.\nЛюди криком кричали:” розіпніть ви Христа!”\nТа Христос із любов’ю до Отця Він сказав:\n“Прости їм, о Боже, бо мене ти послав.”\n\nПрипев\nА Він взяв ті гріхи і поніс,\nДе люди кричали розпніть.\nПо дорозі ішов нелегкій,\nАле Він за тебе повір.\n\nКуплет 2\nСонце схилилось низько - відчувало усе,\nСмерть Христова близько, чути кроки, іде.\nНебо помітно чорніє, відвернув Бог лице...\nЛюди, зупиніться і подумайте ще.\n\nКуплет 3\nА Він був ранений за наші гріхи, \nЗа наші провини Він мучений був.\nКара на ньому була за наш мир. \nЙого ж ранами нас оздоровлено.', '', '', 'ua', NULL, 0, NULL, NULL),
(143, 147, 'Ты искупил мир от греха Ты дал ему любовь и свет', 0, 'Куплет 1\nТы искупил мир от греха, Ты дал ему любовь и свет,\nЗажег потухшие сердца и дал надежду.\nМы пред Тобою предстоим и каждый дорог для Тебя.\nЗа все, Отец, благодарим и превозносим.\n\nКуплет 2\nСлава Тебе и величье, Слава в веках и народах!\nСила Твоя – безгранична, Милость Твоя - во все роды.', '', '', 'ua', NULL, 0, NULL, NULL),
(144, 148, 'Ты мне сказал и я ответил', 0, 'Куплет 1\nТы мне сказал - и я ответил,\nТы постучал - и я открыл.\nТвой образ был так свят и светел,\nЧто серце счастьем озарил.\n\nКуплет 2\nТвоя любовь, как небо вечна, /\nА милостей твоих не счесть. /\nЯ благодарна бесконечно, / 2разы\nЧто для меня Господь, Ты есть. /\n\nКуплет 3\nТы заповедал - я исполнил\nИ заключил с тобой завет.\nИ Дух Святой меня наполнил,\nКак полдень наполняет свет.\n\nКуплет 4\nВ душе нет места для печали, /\nЯ песни радости пою . /\nТебе, пою Бог безначальный. / 2разы\nТебя, Христос, благодарю. /', '', '', 'ua', NULL, 0, NULL, NULL),
(145, 149, 'Хай радіє твоє серце і ніколи не сумує', 0, 'Куплет 1\nХай радіє твоє серце і ніколи не сумує\nХай радіє твоє серце і співає: \"Алілуя\".\n...                                           ...\nХай душа твоя співає, вдень і звечора й до ранку\nПрославляй Христа Святого, Він твоє життя й дорога.\n\nПриспів\nБо Ім´я Господнє вічне, дивне славне і величне\nТи віддай Йому за все хвалу!\n\nКуплет 2\nТи склади Йому подяку. За хліб, за воду й теплу хату\nЗа мир, спокій, за кожну днину, і за нашу Україну.\n...                                           ...\nБо сильно Він тебе кохає, береже й охороняє\nЗнає всі твої потреби, сам веде тебе до неба.', '', '', 'ua', NULL, 0, NULL, NULL),
(146, 150, 'Хвала Тобі наш Господь', 0, 'Куплет 1\nХвала Тобі наш Господь, \nХвала, Тобі Бог Святий \nХвала за Ісуса, Сина Твойого.\n\nПриспів\nТепер слабий скаже: “Сильний я” ,\nБідний скаже: “Я багач“ ,\nЗавдячуючи тому, що \nБог дав. Хвала!', '', '', 'ua', NULL, 0, NULL, NULL),
(147, 151, 'Хвалите Господа с небес хвалите Бога', 0, 'Припев\nХвалите Господа с небес, хвалите Бога! (2p.)\n\nКуплет 1\nХвалите, море и река, хвалите, горы и поля!\nХвалите, ветер и туман, хвалите, струны и орган!\nХвалите, море и река,  хвалите, горы и поля!\nХвалите, ветер и туман,  хвалите Бога!\n\nКуплет 2\nХвалите, ангелы Его, хвалите, воинства Его!\nХвалите, небо и земля, хвалите, солнце и луна!\nХвалите, ангелы Его, хвалите, воинства Его!\nХвалите, небо и земля, хвалите Бога!\n\nКуплет 3\nХвалите, суша и вода, хвалите, бездна, высота!\nХвалите, птицы, облака, хвалите, люди племена! \nХвалите, суша и вода, хвалите, бездна, высота!\nХвалите, птицы, облака, хвалите Бога!', '', '', 'ua', NULL, 1, '2020-11-08', NULL),
(148, 152, 'Хорошо мне с Тобою быть', 0, 'Куплет 1\nХорошо мне с Тобою быть, Тебе верить, Тебя любить\nХорошо в тихий час ночной Иисус пребывать с Тобой.\n\nПрипев\nХорошо мне с Тобой везде, даже в горе, в любой беде\nДаже если темно вокруг, Ты мой самый надежный Друг.\n\nКуплет 2\nРазве можно с Тобой скучать, я часами могу молчать\nСознавая, что рядом Ты охраняешь мои мечты.\n\nКуплет 3\nХорошо мне с Тобой дружить, все заботы Тебе сложить\nХорошо все вручить Тебе, все что будет в моей судьбе.', '', '', 'ua', NULL, 0, NULL, NULL),
(149, 153, 'Христа – Творця святих чудес', 0, 'Куплет 1\nХриста – Творця святих чудес\n Прославте всі сердечним співом.\nРадійте всі! Звершилось диво:\n | Христос Воскрес! (2р.)\n\nКуплет 2\nХвала, хвала! Христос Воскрес! \n Життя! У грудях серце б´ється...\nТепер усюди пісня ллєтся:\n | Христос Воскрес! (2р.)\n\nКуплет 3\nПо всьому світу до небес\n Хвала Творцеві щира льється.\nСпів радісний нехай несеться:\n | Христос Воскрес! (2р.)\n\nКуплет 4\nТобі, Спасител – Божий Син,\n Тобі і слава, і хваління,\n  Подяка, честь і поклоніння повіки вічнії! Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(150, 154, 'Церковь Божия семья моя верная', 0, 'Куплет 1\nЦерковь Божия - семья моя верная,\nЦерковь Божия - любовь моя первая,\nЦерковь Божия - святая и чистая,\nЦерковь Божия - родная и близкая.\n\nПриспів\nДавайте мы простим друг другу все обиды,\nВсе наши горести, печали и разлуки.\nБлагословляйте и молитесь друг за друга,\nДавайте мы пожмем друг другу крепче руки.\n\nКуплет 2\nЦерковь Божия - это слово священное,\nЦерковь Божия - это семя нетленное,\nЦерковь Божия - ты сила могучая,\nЦерковь Божия - ты самая лучшая.\n\nКуплет 3\nЦерковь Божия - невеста невинная,\nЦерковь Божия, ты - самая дивная.\nМоя церковь! Люблю всей душой тебя,\nВо Христе ты надежда и жизнь моя!', '', '', 'ua', NULL, 0, NULL, NULL),
(151, 155, 'Цінуй випробування що послав тобі Господь', 0, 'Куплет 1\nЦінуй випробування що послав тобі Господь\nІ через всі страждання, сам сміливо ти проходь\nТебе Він проведе і сили дасть перенести\nВсе що трапиться в житті.\n\nПрипев\nЯкщо у серці віра, не страшні печалі\nІ самотнє серце не болить ночами\nІ що б в життєвім морі ви не зустрічали\nГоловне, що є любов.\n\nКуплет 2\nБудь з Богом в світі цьому, це найкраще для людей\nБо скривдити ніколи Він не дасть Своїх дітей\nЖиття твоє як промінь хай не згасне у пітьмі\nТак як сам Господь хотів.\n\nКуплет 3\nПильнуй Завіт Його і з того шляху не звертай\nЦю істину велику зрозумій, запам’ятай\nБо всі твої надії на майбутнє у житті\nЗдійснить Він будь певен ти!', '', '', 'ua', NULL, 0, NULL, NULL),
(152, 157, 'Чи ти знаєш той шлях на Голгофу', 0, 'Куплет 1\nЧи ти знаєш той шлях на Голгофу\nПо якому Син Божий пройшов?\nВін гріхів чашу ніс всього світу\nЩоби кожен спасіння знайшов.\n\nПрипев\nО невже ж тобі зовсім байдуже\nЗадля чого Ісус в світ прийшов\nВін тебе полюбив милий друже \nСвого Сина у жертву віддав,\nСвого сина у жертву віддав!\n\nКуплет 2\nЧи ти знаєш ту біль, що Ісус Христос\nПереміг Він темряву і зло\nВсе чинив Він з любовю до тебе\nЩоб у ньому спасіння ти мав.', '', '', 'ua', NULL, 0, NULL, NULL),
(153, 158, 'Эта ночь таинственна молчаньем', 0, 'Куплет 1\nЭта ночь таинственна молчаньем,\nЭта ночь рождения Его.\nИ земля и небо в ожыданьи,\nВоплощеньям Бога Своего.\n\nКуплет 2\nНаречен Он первым и последним,\nОн Альфа и Омега, начало и конец.\nОн для нас пришел на эту землю,\nОн любит человека, так любит лишь Отец!\n\nКуплет 3\nНаходясь в плену своих пороков,\nСхоронив любовь под толщей льда.\nЛюди шли не слушая пророков ,\nЛюди шли дорогой в никуда.\n\nКуплет 4\nИх Мессия первый и последний,\nОн Альфа и Омега, начало и конец.\nОн для нас пришел на эту землю,\nОн любит человека, так любит лишь Отец.\n\nКуплет 5\nНаречен Он первым и последним\nОн Альфа и Омега, начало и конец…!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(154, 159, 'Эта песня любви \\ Океан Божьей', 0, 'Куплет 1\nЭта песня любви,\nСловно птица парит в небесах,\nТвоя жизнь, как река в моем сердце течет,\nИ душа поет для Тебя. \nЭта песня любви, как весенний родник, \nКак любви водопад,\nТвоя жизнь, как река, в моем сердце течет\nЯ вдыхаю любви аромат.\n\nКуплет 2\nОкеан Божьей любви,\nНет начало в нем и нет конца.\nОкеан Божьей любви,\nБезусловной любви Отца.\n\nКуплет 3\nСлава, аллилуя, слава!', '', '', 'ua', NULL, 8, '2021-03-26', NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(155, 160, 'Я без Тебе нічого не значу', 0, 'Куплет 1\nЯ без Тебе нічого не значу,\nМов билинка у чистому полі,\nА з Тобою, здається, неначе\nНайщасливішу маю я долю.\nА з Тобою і темні ночі\nЯ без страху в житті долаю,\nБо Твої наді мною очі,\nНаче зорі, завжди, я знаю.\n\nПриспів\nІ я знаю, що я без Тебе,\nМов весна, що прийшла без цвіту,\nА з Тобою відкрите небо,\nА з Тобою я буду жити.\n\nКуплет 2\nТвої руки в глибоких ранах\nШлях до неба мені вказали.\nСлід кривавий горить вогнисто\nТам, де ноги Твої ступали.\nНаче маки червоні  в житі,\nБачу я Твій вінок терновий.\nВін для мене, як сонце, світить,\nВ ньому бачу життя я нове.', '', '', 'ua', NULL, 2, '2021-04-01', NULL),
(156, 161, 'Я дякую Тобі мій Бог за очі', 0, 'Куплет 1\nЯ дякую Тобі, мій Бог, за очі,\nЯкими бачу все, що Ти створив.\nЯ знаю тих, для кого дні, як ночі, \nХто бачить світло тільки в хвилях снів.\nЯ дякую Тобі, мій Бог, за руки,\nЯкими можу я тримати хліб, \nВтирать сльозу печальний час розлуки\nІ працювати можу на землі.\n\nПриспів\nЯ дякую Тобі, (2р.) прийми, Господь, подяку.\nЯ радуюсь в Тобі,(2p.) прийми, Господь, подяку!\n\nКуплет 2\nЯ дякую Тобі, мій Бог, за ноги, \nЯкими я проходжу всі путі.\nЯ знаю тих людей, чиї дороги\nНе пройдені лишились на землі.\nЯ дякую Тобі, мій Бог, за голос.\nТебе я можу завжди славить ним.\nЯ знаю тих, кому весь світ навколо\nЯк і вони, здається все німим.\n\nКуплет 3\nЯ дякую Тобі за хліб насушний,\nЗа те, що вдосталь маєм на столі.\nБули часи тяжкі і неминучі,\nЯк люди помирали на зимлі\nЯк крихту хліба золотом вважали\nШматочок той ділили багатьом.\nЯкби вони його тоді так мали,\nЯк ми сьогодні маєм за столом.', '', '', 'ua', NULL, 6, '2020-06-21', NULL),
(157, 162, 'Я жажду близости Твоей Спаситель мой', 0, 'Куплет 1\nЯ жажду близости Твоей, Спаситель мой,\nСпаситель мой, пребудь со мной.\nВо всякий час даренных дней\nПребудь со мной, Спаситель мой, пребудь со мной.\n\nКуплет 2\nВсегда во всем яви Ты мне свою любоь,\nСвою любовь яви Ты мне.\nДай больше рвения к Тебе, дай кротость вновь.\nСвою любовь дай мне - любовь.\n\nКуплет 3\nДух Святой сошел, Дух Святой нашел,\nДух Святой поднял, Дух Святой обнял.\n\nКуплет 4\nДай серцем чистым вознестись к Тебе мой Бог,\nМой дивный Бог, Ты - мой покой ,с Тобою вечно жажду жить.\nВеди сейчас - отрада мне во всякий час.\nКто я пред Тобой, что узрел Ты меня\nДал мне вечную жизнь, дал мне вечный покой?\n\nКуплет 5\nДух Святой сошел, Дух Святой нашел,\nДух Святой поднял, Дух Святой обнял.\n\nКуплет6\nКто я пред Тобой, что узрел Ты меня\nДал мне вечную жизнь, дал мне вечный покой?', '', '', 'ua', NULL, 0, NULL, NULL),
(158, 163, 'Я пойду за Тобой куда Мой Бог', 0, 'Куплет 1\nЯ пойду за Тобой, куда бы Ты не повел меня\nЯ исполню все для чего Ты меня призвал\nМоя радость в Тебе, всю свою жизнь Тебе отдам\nМои слезы, боль, поглотила Твоя любовь.\n\nКуплет 2\nМой Бог, мой Бог, большая скала\nСтена из камня, защита моя\nСпасенье мое крепость жизни моей\nКого мне бояться тепер?', '', '', 'ua', NULL, 0, NULL, NULL),
(159, 164, 'Я постигаю сквозь слезы и боль', 0, 'Куплет 1\nЯ постигаю сквозь слезы и боль\nРадости встреч и горечь разлуки.\nПью эту чашу, где сладость и соль\nПеремешались с надеждой и мукой.\n\nПрипев\nТы не печалься, не беспокойся: \nЕсли Бог с нами - кого бояться?\nТы не печалься, не беспокойся, \nЕсли Бог с нами.\n\nКуплет 2\nСвободу ищу от житейских оков,\nТех, что зовутся житейское счастье.\nВся моя жизнь - это несколько слов\nВ тихой молитве перед причастьем.\n\nКуплет 3\nРядом с Христом я спокойно иду,\nВидя, как катится мир к катастрофе.\nВерю в мной избранный истинный путь,\nВ тайну распятой любви на Голгофе.', '', '', 'ua', NULL, 0, NULL, NULL),
(160, 165, 'Я Тебя буду ждать на рассвете дня в тиши', 0, 'Куплет 1\nЯ Тебя буду ждать на рассвете дня в тиши,\nЯ хочу рассказать всю печаль моей души.\n\nПриспів\nЯ буду ждать Господи Тебя,\nБуду ждать Тебя с самого утра.\nВерю, Ты придёшь, снимешь боль мою,\nЗнаю всё поймёшь, я Тебя люблю.\n\nКуплет 2\nЯ устал дальше жить среди мрака и тревог\nТо, что некому открыть, раскажу Тебе, мой Бог.\n\nКуплет 3\nЯ Тебя буду ждать, эта встреча всех милей,\nТолько Ты можешь дать мир покой душе моей.', '', '', 'ua', NULL, 0, NULL, NULL),
(161, 167, 'Як весняні струмки плинуть наші роки', 0, 'Куплет 1\nЯк весняні струмки плинуть наші роки і збігають в русло віковічне,\nВ слід за ними ідуть всі діла і думки, і слова пише теж перо вічне.\n\nПрипев\nНе губи своїх днів у потоках земних,\nДе весняний розлив є темніший від ночі.\nУ Христі джерело для людей всіх віків,\nКличе Він до себе - спасти хоче.\n\nКуплет 2\nВиправить помилки за минулі роки той, хто любить і все нам прощає.\nТож хай кожна душа поспішить до Христа, до Христа хай життя направляє.\n\nКуплет 3\nТож хай плинуть роки як весняні струмки, як струмки від весни неземної,\nХай зіллються вони з джерелом вічних днів і несуть до землі нас святої.', '', '', 'ua', NULL, 0, NULL, NULL),
(162, 168, 'Я вижу пятна на тропе кровавые', 30, 'Куплет1\nЯ вижу пятна на тропе кровавые\nКогда-то шел по ней Христос израненный.\nОн шел, искал меня, а я утерянный,\nА я лежал во рву, грехом истерзанный.\n\nКуплет2\nЗаботясь нежно обо мне порой ночной,\nОн шел, искал меня среди вражды людской.\nА я беспечен был, не знал Его любви,\nНе знал Его забот, тонул в пучине злой.\n\nКуплет3\nГлаза лучистые меня увидели.\nСтонал от боли я, не зная радости,\nНо вдруг Христос пришел, как добрый Пастырь мой,\nЯ лик Его узнал, смотрел с любовью Он.\n\nКуплет4\nПодал Он руки мне Свои пронзенные,\nСказал, что я теперь навек, спасенный Им.\nИ было столько сил в Его святых руках,\nОн взял меня с Собой, понес к другим овцам.\n\nКуплет5\nМне видны пятна на тропе кровавые-\nКогда-то шел Спаситель мой израненный.\nИ свет Его очей мне будет освещать,\nТе пятна мир людской не сможет затоптать.', '', '', 'ua', NULL, 0, NULL, NULL),
(163, 169, 'Схилилося колосся до землі', 30, 'Куплет1\nСхилилося колосся до землі, а в небі вже кружляють журавлі.\nЖнива і близький птахів переліт нагадують: Життя – коротка мить.\n\nПрипев:\nЧи думав ти - життя пройде як день,\nЧи думав ти, що є земля пісень,\nЧи думав ти, що є вогонь жалю,\nЧи думаєш про душу ти свою?\n\nКуплет2\nЗемні роки як річечка збіжать, земні роки словами не здержать.\nВже колосом біліють дні твої, а у душі змовкають солов’ї.\n\nКуплет3\nВ Ім’я Господнє просимо усіх, Покайтеся, жнива йдуть на поріг.\nСпаситель простить, душу пригорне, спів солов’їний до душі верне.', '', '', 'ua', NULL, 0, NULL, NULL),
(164, 170, 'Муж галилеянин мимо не пройдет', 0, 'Куплет1\nМуж Галилеянин мимо не пройдет\n\nКуплет2\nИ если  ты позволишь, Он Сам придёт любя\nИ силою своею коснется тебя\n\nКуплет3\nДругого пути нет\nИ не найдешь нет, нет\n\nКуплет4\nЛишь только, Иисус спасет тебя.\n\nКуплет5\nМоя победа, победа в Боге,\nПобеда в имени Иисуса Господа.\n\nКуплет6\nИ никогда мои враги не смогут победить меня!\nМоя победа, победа в Боге,\nПобеда в имени Иисуса Господа!\n\nКуплет7\nМуж Галилеянин мимо не прошёл\n\nКуплет8\nИ я Ему позволил, Он Сам пришёл любя,\nИ силою своею коснулся меня.\n\nКуплет9\nДругого пути нет\nИ не найдешь нет, нет!\n\nКуплет10\nЛишь только, Иисус спасает меня.\n\nКуплет11\nМоя победа, победа в Боге,\nПобеда в имени Иисуса Господа\n\nКуплет12\nИ никогда мои враги не смогут победить меня!\nМоя победа, победа в Боге,\nПобеда в имени Иисуса Господа!', '', '', 'ua', NULL, 2, '2021-02-28', NULL),
(165, 171, 'Какой сегодня день чудесный', 30, 'Куплет1\nКакой сегодня день чудесный\nС друзьями встретились мы вновь,\nДавайте в этот час все вместе\nПрославим Божую любовь.\n\nПрипев:\nСлава Христу за дивную встречу,\nУвидеть снова лица друг друга\nБог нам даровал.\n\nКуплет2\nКакой сегодня день прекрасный,\nКак раньше, снова вместе мы\nИ пусть сегодня солнце ясно\nСияет после краткой тьми.\n\nКуплет3\nКакой сегодня день счастливый\nО нем мечтали мы давно\nИ даже если он дождливый\nЗачем? Ведь это все ровно.', '', '', 'ua', NULL, 0, NULL, NULL),
(166, 172, 'Эту песню небо ангелы поют', 0, 'Куплет1\nЭту песню небо ангелы поют,\nСлава Агнцу Божьему.\nЭту песню небо ангелы поют,\nСлава Агнцу Божьему.\n\nПрипев:\nАлилуя, (алилуя)\nАлилуя, (алилуя)\nАлилуя.\nСлава Христу!\n\nКуплет 2\nСлава вовеки Ему!', '', '', 'ua', NULL, 0, NULL, NULL),
(167, 173, 'Мне хорошо и приятно быть рядом с Тобой', 30, 'Куплет1\nМне хорошо и приятно быть рядом с Тобой\nИ любовь Твоя пусть течет рекой, \nИ пусть воды ее наполняют жизнь мою\nО, Господь, дай мне спеть Тебе песню свою.\n\nПрипев:\nТы пришел мой Господь, освятил меня\nТы пришел мой Иисус, и простил меня.\nТы задел струны сердца моего\nНе уйду никуда от лица Твоего.\n\nКуплет2\nО Мой Господь, чтобы было если б не Ты,\nМоя прошлая жизнь, отголосок пустоты.\nЯ никогда бы не был, так счастлив, так свят,\nИ не спел бы Тебе песню, о, как же я рад! Что…\n\nКуплет3\nВеликий Бог, дай прожить свято жизнь свою,\nЧтоб навеки с Тобою быть в раю.\nДай верно путь пройти испытания,\nЧтоб жить как петь, во все старания!', '', '', 'ua', NULL, 0, NULL, NULL),
(168, 174, 'Я иду по земной тропе время вышло', 0, 'Куплет1\nЯ иду по земной тропе, время вышло\nОчень быстро кончается день, очень быстро\nРядом смерть в ожидании минут проходящих\nА из глаз моих слезы текут, слезы счастья.\n\nКуплет2\nЯ на Божию чашу ложу только крохи\nНо я верю что не окажусь очень легким\nПокаянье мое на весах стрелку движет\nНебеса, небеса, небеса я увижу!\n\nКуплет3\nНа земле меня ждет лишь земля, телу тленье\nА на небе, на небе меня, ждет спасенье.\nСмерть стучит мне рукой по плечу торжествуя\nА душа Аллилуйя поет, Аллилуйя.\n\n\nКуплет4\nСмерть ты можешь забрать \nтолько прах но не больше\nЯ в Господних надежных руках, я не брошен\nЗря доносится сквозь темноту вой шакала\nСмерть давно ты Иисусу Христу проиграла.\n\nКуплет5\nПоднимаю я к небу глаза без печали\nВижу веры спасенных святых в вечной славе\nВесь мой прожитий прежний удел мне простится\nВедь я главное с Богом успел примирится\n\nКуплет6\nСмерть ты можеш забрать только прах, но не больше\nЯ в Господних надежных руках, я не брошен\nЗря доносится сквозь темноту вой шакала\nСмерть давно ты Исусу Христу проиграла.\n\nКуплет7\nЯ на Божию чашу ложу только крохи\nНо я верю, что не окажусь очень легким\nПокаяние мое на весах стрелку движет\nНебеса, небеса, небеса я увижу!', '', '', 'ua', NULL, 2, '2021-04-01', NULL),
(169, 175, 'Хвалу Тобі складаю Боже', 30, 'Куплет1\nХвалу Тобі складаю, Боже,\nЗа те, що любиш Ти мене.\nУ світі цьому все негоже\nКолись безслідно промине,\nАле Твоє воскресіння\nЧудово сяє навкруги.\nТи дав душі моїй спасіння,\nЩоб ми його берегли.\n\nПрипев:\nХристос показує дорогу,\nВирівнює нерівний шлях.\nТому хвала лунає Богу!\nПостійно на моїх устах!\n\nКуплет2\nНічого вічного немає\nО тут, в дочасному житті,\nУсе проходить, проминає\nВ природі й людському житті,\nАле Твоє воскресіння\nЧудово сяє навкруги.\nТи дав душі моїй спасіння,\nЩоб ми його берегли.\n\nКуплет3\nТак часто це життя земнеє,\nЗло нам спокою не дає,\nАле Ісус допомагає,\nТож будем жить, бо Він живе,\nАле Твоє воскресіння\nЧудово сяє навкруги.\nТи дав душі моїй спасіння,\nЩоб ми його берегли.', '', '', 'ua', NULL, 0, NULL, NULL),
(170, 176, 'В часи тривог зневiри і сумнівів', 0, 'Куплет 1.\nВ часи тривог,  зневiри і сумнівів,\nНе бачу свiтла в світі я ніде\nДуша горить i бореться в сумнівах,\nСпішу Христе, в молитві до Тебе.\n\nПрипев.\nЩасливий я що Друга в світі маю\nЩасливий я: Він завжди при мені.\nЖиву я з Ним, і в Ньому пробуваю\nВін став найкращим Другом на землі\n\nКуплет 2.\nТвій образ дивний лагідний смиренний\nІсусе Ти живи в мені всі дні\nІ будь в моему серці Ти щоденно\nВпасти не дай під тягарем мені\n\nКуплет 3.\nМені порою важко так буває\nЗдаеться вже Сам Бог лишив мене\nТоді в душі слова Твої лунають\n\"Я не покину Я люблю тебе!\"', '', '', 'ua', NULL, 0, NULL, NULL),
(171, 177, 'Боже ты мой Бог', 0, 'Куплет 1\nБоже, Ты - мой Бог\nТебя от ранней зори ищу.\nТебя жаждет душа моя, Аллилуя!\n\nПрипев\nЯ вспоминаю о Тебе,\nРазмышляю ночью о Тебе,\nТы помощь моя, Аллилуя!\n\nКуплет 2\nМилость Твоя лучше, чем жизнь,\nБлагословлю Тебя в жизни моей.\nУста мои восхваляют Тебя: Аллилуя!', '', '', 'ua', NULL, 0, NULL, NULL),
(172, 178, 'Христос для многих Ты людей легенда', 30, 'Куплет1\nХристос, для многих Ты людей- легенда,               \nА для моей Ты жизни- Идеал,\nМне дорога священная минута,                                \nВ которой для меня Ты другом стал.\n\nКуплет2\nТы жизнь моя, и больше жизни нету,                          \nЯ без Тебя давно б уже не жил,\nТебе доверив жизнь, пришёл я к свету,                  \nВ Тебе нашёл существованья смысл.\n\nКуплет3\nДержаться за Тебя хочу я крепко,                           \nВедь Ты для грешников стал постижим,\nА дьявол часто ранит в сердце метко,                    \nО Ты, Иисус, мне так необходим.\n\nКуплет4\nПрости меня, Иисус, что сил так мало,                   \nВ борьбе с грехом теряю я Тебя,\nНо всёж найду, во что бы то ни стало,                 \nТы только лишь не покидай меня.\n\nКуплет5\nПорой мне грустно, больно, одиноко,              \nКогда Тебя не вижу впереди,\nПрошу, Иисус, не уходи далёко,                           \nТы для меня, что сердца стук в груди.\n\nКуплет6\nТы – Жизнь, я жить одним Тобой желаю,           \nВсем сердцем научи Тебя любить,\nСлужить Тебе до смерти обещаю,                          \nИ посреди неверья верным быть.', '', '', 'ua', NULL, 0, NULL, NULL),
(173, 179, 'Cristo te necesita para amar', 0, 'Куплет 1\nCristo Te necesita para amar////\n\nПрипев\nNo importa la raza \nNi el color de la piel\nAma a todos como hermanos\nY haz el bien\n\nКуплет 2\nAl que no te saluda dale amor ////\n\nКуплет 3\nAl que está a tu paso dale amor ////', '', '', 'ua', NULL, 3, '2021-01-17', NULL),
(174, 181, 'Jerusalen que preciosa eres', 30, 'Куплет 1\nJerusalen, que preciosa eres\nCalles de oro, mar de cristal\nDel Trono sale el rio de la vida\nPuertas de perla como un portal.\n\nПрипев\nPor esas calles yo voy a caminar\nCalles de oro, mar de cristal.\n\nКуплет 2\nJerusalen, ciudad eterna\nQue fue creada por mi Dios fiel\nQuien sed tenga, que venga y beba\nAguas de vida brotan de el.\n\nКуплет3\nJerusalén, cuanto te amo\nEn ti abunda eterno amor,\nNaciones todas han de reunirse\nA darle gloria al Salvador.', '', '', 'ua', NULL, 2, '2021-03-28', NULL),
(175, 182, 'Встаёт заря и солнца луч на неба всходит', 30, 'Куплет 1\nВстаёт заря и солнца луч на неба всходит\nЗасияв в бескрайней синеве.\nЗа новый день хвалу Творцу поёт природа,\nИ мы воспрянем в радостной хвале.\n\nПрипев: \nСлава Богу, слава Богу!\nЗа милость, за прощение грехов.\nСлава Богу, слава Богу!\nЗа дивную Его любовь.\n\nКуплет2\nКак чудно всё, что сотворил наш Бог великий,\nДа звучит и слава и хвала!\nПрекрасно всё, что созданно Христом Владыкой,\nСлавь Его за дивные дела!\n\nКуплет 3\nВелкий Бог, в любви Своей к нам-людям грешным\nОтдал в жертву Сына Своего.\nИ нас омыл Он кровию Своей пречистой,\nБудем вечно славить мы Его!', '', '', 'ua', NULL, 0, NULL, NULL),
(176, 183, 'Когда в Твои слова вникаю', 0, 'Куплет 1.\nКогда в Твои слова вникаю,\nХристос, Спаситель дивный мой,\nТогда всё глубже понимаю,\nЧто без Тебя я - прах земной.\nТы есть Лоза моя святая,\nА я лишь веточка Твоя\nИ сок для жизни получаю\nЯ, мой Спаситель, от Тебя.\n\nКуплет 2.\nТвой свет во мне всё оживляет,\nДает мне радость и покой,\nДуша так близко ощущает\nТебя, Господь, Спаситель мой.\nКогда случается порою,\nНе пребываю я с Тобой,\nТогда терзаюсь я душою,\nНе находя ни в чем покой.\n\nКуплет 3.\nО как Твои слова правдивы\nЧто без Тебя ничтожны мы\nИ на дела у нас нет силы\nВ греховном мире суеты\nИ потому мое желанье -\nВ Тебе, Христос мой, пребывать,\nЧтоб в жизни все мои деянья\nТвоею силой совершать.\n\nКуплет4\nХристос Ты жизнь и Путь для жизни\nДающий смысл для бытия\nЦеною жизни дверь в Отчизну\nОткрыл Ты грешникам как я\nТы есть Лоза моя святая,\nА я лишь веточка Твоя.\nИ сок для жизни получаю\nЯ мой Спаситель от Тебя', '', 'Dm', 'ua', NULL, 1, '2020-08-23', NULL),
(177, 184, 'Тебя люблю мой Бог', 30, 'Куплет 1\nТебя люблю, мой Бог, я всей душою\nИ с каждым новым днем хочу любить сильней,\nЛюблю Тебя  за то, что Ты со мною\nИ говоришь со мной любовью неземной.\n\nПрипев\nТы мой Бог, крепость моя,\nВ руках Твоих сила моя.\n\nКуплет 2\nМеня Ты никогда не оставляешь\nИ голос слышу Твой звучит в душе моей:\n\"Благословлю тебя, коль Ты благословляешь,\nИ силы не жалей, других люби сильней\"\n\nКуплет3\nИ снова слышу голос Твой чудесный:\n\"Во всём будь совершенным человек,\nКак совершенный наш Отец Небесный.\nНадейся, верь, люби и будешь жить вовек\"', '', '', 'ua', NULL, 2, '2021-01-01', NULL),
(178, 185, 'В ті миті коли певно я стою', 30, 'Куплет 1\nВ ті миті, коли певно я стою\n(Так ті миті дорогі).\nВ ті миті, коли немічним впаду\n(Сам не знаю, що тримає).\nВідчуваю я однак в кожну мить,\n(В кожну мить).\nЩо Господь і Бог наш є так близько біля нас.\n\nПриспів\nКоли в серці туга й страх, знаю, Ти близько,\nЧи втомився я в боях, знаю, я не сам.\nВідчуваю в кожний час в радощах і смутку,\nЩо Господь і Бог наш є так близько біля нас.\n\nКуплет 2\nЄ так близько…', '', '', 'ua', NULL, 3, '2021-03-21', NULL),
(179, 186, 'Народ новый востает в стране', 30, 'Куплет1\nНарод новый востает в стране,\nСвятой народ, все цепи зла он разорвет.\nНарод познавший Божью силу\nШтурмует ад, его врата не устоят.\n\nПрипев\nСодрогнется ад, все царства тьмы.\nРухнут все твердыни сатани.\nЗнают все враги, что дни их сочтены, сочтены.\nПленники греха увидят свет,\nНет цепей и рабства больше нет.\nМы возьмем все то, что нам пренадлежит.\n\nКуплет2\nПомазал Бог меня, помазал Бог тебя.\nПобеду дал Он Церкви, Он ее хранит.\nГосподь послал меня, Господь послал тебя,\nНичто перед тобой не устоит.', '', '', 'ua', NULL, 0, NULL, NULL),
(180, 187, 'Встает заря и солнца луч на неба сходит', 30, 'Куплет1\nВстает заря и солнца луч на небо сходит\nЗасияв в бескрайней синеве.\nЗа новый день хвалу Творцу поет природа,\nИ мы воспрянем в радостной хвале.\n\nПрипев:\nСлава Богу, слава Богу!\nЗа милость, за прощение грехов.\nСлава Богу, слава Богу!\nЗа дивную Его любовь.\n\nКуплет2\nКак чудно все, что сотварил наш Бог великий,\nЗвучит и слава и хвала!\nПеркрасно все, что создано Христом Владыкой,\nСлавь Его за дивные дела!\n\nКуплет3\nВеликий Бог, в любви Своей к нам-людям грешным\nОтдал в жертву Сына Своего.\nИ нас омыл Он кровью Своей пречистой,\nБудем вечно славить мы Его!', '', '', 'ua', NULL, 0, NULL, NULL),
(181, 188, 'Cuando el pueblo de Dios ora', 0, 'Куплет 1\nCuando el pueblo de Dios ora.\nSuceden cosas, suceden cosas,\nMaravillosas!\n\nПрипев\nHay sanidad!\nHay salvación!\nY se siente la presencia del Señor.\n\nКуплет2\nКоли Божий народ молиться, Бог його чує\nБог його чує й відповідає.\n\nПрипев     \nСпасає Він,зціляє Він \nУ присутності Його завжди є мир.\nСпасає Він,зціляє Він,\nХто до Нього щирим серцем йде своїм.\n\nКуплет3\nКоли Божий народ молиться Бог його чує\nБог його чує й відповідає.', '', '', 'ua', NULL, 1, '2020-12-13', NULL),
(182, 189, 'Велики Бог Коли на світ погляну', 30, 'Куплет1\nВелики Бог! Коли на світ погляну,\nІ бачу все, що ти створив в красі,\nЯк кожний цвіт склада тобі пошану,\nІ як обняв любов’ю Ти усіх?\n\nПрипев:\nТоді, Господь, мій дух співа Тобі:\nЯк славен Ти! Як славен Ти!\n\nКуплет2\nКоли беру я Книгу заповітів,\nІ про Твої читаю я діла:\nЯк полюбив Ти нас, людей на світі\nІ для спасіння Сина нам послав.\n\nКуплет3\nSeñor mi Dios, al contemplar los cielos\nEl firmamento y las estrellas mil\nAl oir Tu voz en los potentes truenos\nY ver brillar el sol en su cenit\n\nПрипев2\nMi corazón entona la canción\nCuán Grande es Él.', '', '', 'ua', NULL, 0, NULL, NULL),
(183, 191, 'Великий Бог', 0, 'Куплет1\nВелики Бог! Коли на світ погляну,\nІ бачу все, що ти створив в красі,\nЯк кожний цвіт склада тобі пошану,\nІ як обняв любов’ю Ти усіх?\n\nПрипев:\nТоді, Господь, мій дух співа Тобі:\nЯк славен Ти! Як славен Ти!\n\nКуплет2\nКоли беру я Книгу заповітів,\nІ про Твої читаю я діла:\nЯк полюбив Ти нас, людей на світі\nІ для спасіння Сина нам послав.\n\nКуплет3\nSeñor mi Dios, al contemplar los cielos\nEl firmamento y las estrellas mil\nAl oir Tu voz en los potentes truenos\nY ver brillar el sol en su cenit\n\nПрипев2\nMi corazón entona la canción\nCuán Grande es Él.', '', '', 'ua', NULL, 2, '2020-11-08', NULL),
(184, 193, 'От небесних вершин до глибоких морей', 30, 'Куплет 1\nОт небесних вершин до глубоких морей \nВсё творенье поёт о Славе Твоей.\nВ красках осени и ароматах весны\nОтражаются грани Твоей красоты.\n\nПриспів\nВсё восклицает!!!\nКак прекрасен Ты, как Величествен\nСоздал все звезды на небе и дал  имена\nВеликолепный Бог!!!\nБесподобен Ты! Неизменен Ты!\nВидиш всё в сердце моём и Ты любишь меня.\nВеликолепный Бог!!!\n\nКуплет 2\nКто от солнца с небес направляет лучи?\nКто прохладу и звезды нам дарит вночи?\nКто зимой посылает искрящийся снег?\nКаждый день нам дарует закат и рассвет.\n\nПриспів\nТы великий Бог! Ты Чудесный Бог!\nЗнающий звезды вселенной по их именам\nКак Ты Велик наш Бог!\nМогуществен, Возвышенный, мы  в восхищении\nСмиренно прославим Тебя\nКак Ты велик наш Бог!\nТы чудесный Бог!\nТы чудесный Бог!\nТы чудесный Бог!', '', '', 'ua', NULL, 0, NULL, NULL),
(185, 194, 'Небо і земля', 30, 'Куплет 1\nНебо і земля, Небо і земля\nНині торжествують,\nАнгели й люди, ангели й люди\nВесело святкують.\n\nПрипев\nХристос родився, Бог воплотився\nАнгели співають, славу звіщають,\nПастухи вітають, поклін складають\n\"Чудо!Чудо\" - повідають.\n\nКуплет 2\nУ Вифлиємі, у Вифлиємі\nВесела новина,\nПречиста діва, пречиста діва\nНародила сина.\n\nКуплет3\nОтцівське слово, Отцівське слово\nЗодяглося в тіло,\nВ темряві земній, в темряві земній\nСонце засвітило.\n\nКуплет4\nАнгели служать, ангели служать\nГосподеві свому\nСпівають: \"Слава!\", співають: \"Слава!\"\nНоворожденному.\n\nКуплет5\nТри володарі, три володарі\nЗі сходу приходять,\nЛадан і миро, ладан і миро,\nЙ золото приносять.\n\nКуплет6\nСпасу Святому, Спасу Святому\nТі дари складають,\nПасторі людям, пасторі людям\nНовину звіщають.\n\nКуплет 7\nЙого ми нині, Його ми нині\nТакож величаймо\nСлава на небі і мир на землі!\nЙому заспіваймо.', '', '', 'ua', NULL, 0, NULL, NULL),
(186, 195, 'В палестині', 0, 'Куплет 1\nВ Палестині народився Цар любові і життя,\nБог на землю нам з\'явився, засвітилася зоря.\nПастухам, що пасли стадо, промінь сонця засіяв\nІ тоді в стаєнку йдучи кожен Бога прославляв.\n\nПриспів\nГори зоря, завжди гори\nІ світлом правди освіти.\nВсіх хто блукає в темноті \nХай знайдуть щастя у Христі.\n\nКуплет 2\nМудреці на небосхилі зірку нову віднайшли \nІ дари з собою взявши, поклін дать Христу пішли.\nІ тепер вона сіяє Віфлеємська та зоря,\nЛюдям всім вона звіщає про спасіння, про Царя.\n\nКуплет 3\nЗір багато в небі світить, та яскрівши за всіх одна,\nТа що людям сповістила про народження Царя.\nІ коли печаль на серці ти поглянь у небеса\nДе палає вічним світлом Віфлеємська зоря.', '', '', 'ua', NULL, 6, '2021-01-17', NULL),
(187, 196, 'Эта весть промчалась птицей через века', 0, 'Куплет1\nЭта весть промчалась птицей чрез века\nЭта весть согрела многие сердца.\n\nКуплет2\nРазбудила ночью пастухов\nА из далека вела волхвов,\nЭта ночь Христова Рождества\nРодился  Иисус.\n\nКуплет3\nИисус, что есть дороже на земле,\nИисус звучало ночью в вышине.\n\nКуплет4\nЗасияла новая звезда,\nАнгелы ликуют в небесах.\nЭто счастье к нам тогда пришло\nВ Рождество.\n\nКуплет5\nЭто Он Голгофский подвиг совершил\nЭто Он Спасенье грешникам открыл.\n\nКуплет6\nА пока лежал Он в пеленах,\nНа соломе в яслях просто так\nВидна в Нем любовь и чистота, Иисус.', '', '', 'ua', NULL, 1, '2021-01-03', NULL),
(188, 197, 'Ти мене любиш Боже єдиний', 30, 'Куплет 1\nТи мене любиш, Боже єдиний,\nТи мене любиш, - о яке диво!\nЧасто, як сина, ніжно голубиш,\nТи мене любиш, Ти мене любиш.\n\nПрипев\nО, я щасливий, мить незбагненна,\nДуха Святого дав Ти для мене,\nШлях переможний в хащах туману,\nТож, Алілуя, вічна Осанна!\n\nКуплет2\nМаю від Тебе істини слово,\nВ серці зоріє так світанково. \nЧига  на  душу світ непривітний,\nРадість даруєш в щирій молитві.\n\nПрипев\nО, я щасливий, мить незбагненна,\nДуха Святого дав Ти для мене,\nШлях переможний в хащах туману,\nТож, Алілуя, вічна Осанна!\n\nКуплет 3\nЗнаю, нелегко буде до болю,\nАле невпинно я йду за Тобою.\nБачу Голгофу, серцем радію, - \nТи є Спаситель, - людства надія!', '', '', 'ua', NULL, 0, NULL, NULL),
(189, 198, 'Перед нами пролягла дивна ця життя дорга', 0, 'Куплет 1\nПеред нами пролягла дивна  ця життя дорога,\nІ відкрилась нам вона світлом радісним чудовим,\nПосилає нам свої радощі але й тривоги\nНапрямки два у житті - з Богом жити чи без Бога\n\nПрипев\nМолодість юність - прекрасні роки.\nХай будуть тільки для Бога вони,\nЩоб не прожити даремно життя.\nТи присвяти всі роки для Христа!\nМолодість юність для Бога віддай.\nЗ Ним по дорозі сміливо ступай,\nЗ Ним буде завжди радіти душа.\nЯк присвятиш всі роки для Христа!\n\nКуплет 2\nШвидко так життя летить і таке воно дочасне.\nСвічечка життя горить час пройде - вона погасне.\nЗалишити добрий слід - це завдання всім від Бога.\nСвятість пронести не гріх по життєвій цій дорозі.', '', '', 'ua', NULL, 0, NULL, NULL),
(190, 199, 'Кто сей Царь Слави', 30, 'Куплет 1\nКто сей Царь Славы, Господь Великий,\nСильный и крепкий в брани Своей?\nБлагословен Ты! Бог - Вседержитель,\nСлово Твое - правды чистый елей!\n\nПрипев\nСлава Тебе вовеки,\nО Адонай великий,\nГосподи, Господи!!!\n\nКуплет 2\nКто сей Царь Славы, кроткий и дивный,\nПробиты руки, возложен венец?\nБог в Своем Сыне послал оправданные,\nВернул в Свою обитель заблудших овец.', '', '', 'ua', NULL, 11, '2021-03-24', NULL),
(191, 200, 'Блаженні вбогі духом бо їхнє Царство Боже', 0, 'Куплет 1\nБлаженні вбогі духом, бо їхнє Царство Боже,\nБлаженні всі засмучені, бо будуть втішені вони.\nБлаженні серцем лагідні, бо землю успадкують всю\nБлаженні спраглі правди, бо будуть нагодовані.\nБлаженні милостиві - помилувані будуть,\nБлаженні чисті серцем, бо Господа побачать.\nБлаженні миротворці, синами Бога стануть,\nБлаженні ви, як кривдять вас за Ім\'я Господа.\n\nПрипев\nВи - сіль землі, ви світло для світу,\nНехай воно світить високо вгорі.\nВи - друзі Мої, не слуги, а діти,\nБлагу вість звіщайте до краю землі.\n\nКуплет 2\nНе гнівайтесь на ближнього, і від спокус втікайте\nІ свою милостиню у простоті давайте.\nМоліться Богу в тайні, щоб Він воздав вам явно,\nСкарби складайте в Небесах, скарби нетлінні й славні,\nІ не журіться про життя, що треба їсти й пити,\nШукайте Царста Божого, як Господу служити.\nДорогою вузькою йдіть, в тісні ворота входьте,\nІ не будуйте на піску, - на скелі дім свій зводьте.', '', '', 'ua', NULL, 4, '2021-03-14', NULL),
(192, 201, 'Тихо над горами тане туман', 30, 'Куплет 1\nТихо над горами тане туман,\nНочі минає пора.\nПодихом вітру і шелестом трав\nДень зустрічає земля.\n\nПрипев\nРанок ясніє, небо палає, сходить ранкова зоря,\nГори високі, росами вкриті славлять свого Творця.\nЯк же не буде Бога хвалити співом моя душа?\nЯк же не буде Бога хвалити вічна моя душа?\n\nКуплет2\nТак полюбив вічний Бог цей світ\nСина свого віддав,\nЩоби спастися від смерті зміг\nКожен, хто вірить в Христа.\n\nКуплет3\nВічне слово Ісуса Христа\nСвітло на землю несе.\nТим, хто живе в темній ночі гріха\nРадість, спасіння дає.', '', '', 'ua', NULL, 0, NULL, NULL),
(193, 202, 'Зачем так мучаешь себя', 0, 'Куплет 1\nЗачем так мучаешь себя\nСказал: Когда же Он придет? \nВедь Он всегда везде с Тобой\nВ святую церковь свет свой льет.\n\nПрипев\nО, приходи же, наш Иисус\nОмой сердца,потом уж пусть\nПусть даже мир падет к ногам\nЯ сердце лиш Тебе отдам.\n\nКуплет2\nЧтоб позабыть кем-же я был\nКогда еще я в мире жил.\nЯ согрешал, не понимал,\nНо только Ты лиш руку дал.\n\nКуплет3\n О, как давно жду той поры\nКогда с Тобою мне идти\nИ взявшись за руки вдвоем\nПуть к вечной жизни мы пройдем.', '', '', 'ua', NULL, 0, NULL, NULL),
(194, 203, 'Ти є Цар всього Пан по всій землі', 0, 'Куплет 1\n Ти є Цар всього, Пан по всій землі\nНад гірським струмком, над сонцем в небесах.\nІ у мене є одна мета\nБудь Царем мого життя.\n\nПрипев\nЦарюй Господь, царюй в мені\nВ веселі дні і в дні сумні\nТи Пан всього в моїм житті\nЗавжди Господь царюй в мені!!!\n\nКуплет 2\n Хай в усіх словах, хай в усіх думках\nСяє Господи Твоя краса,\nБо для мене Ти важливіший всього\nБудь Царем життя мого.', '', '', 'ua', NULL, 0, NULL, NULL),
(195, 204, 'Адонай Эль Хай', 30, 'Куплет 1\nЯ такой, как есть, к Тебе бегу,\nВсе сомненья и мечты скрывать нет смысла.\nОдному Тебе внимать хочу,\nОтдаю Тебе весь вал проблем, все мысли.\nТы поймешь, Ты поймешь!\n Куплет2\nпохвала поднимет вновь меня,\nДаже если трудно, буду славить Тебя.\nТвой покой наполнит сердце вновь.\nОщущаю, Бог, Твою неземную любов\nСлава Тебе! Небо поет:\n\nПрипев\nАдонай - Эль Хай!\nБог жив, Бог жив, Господь мой жив!\nАдонай - Эль Шаддай!\nТы можеш все, Ты можеш все!\n\nКуплет3\nАдонай - Эль Хай (4р)', '', '', 'ua', NULL, 0, NULL, NULL),
(196, 205, 'Мій Бог чудовий рухає Він гори', 30, 'Припев\nМій Бог чудовий, рухає Він гори\nЗцілює хвороби\nЦар повік - віків\n\nКуплет 1\nМій Бог чудовий, рухає він гори\nВ низені Він поруч, а в дощ - укриття\nМій Бог чудовий , зцілює хвороби\nВ немочі Він сила, Цар повік - віків\n\nПрипев 1\nМій Бог чудовий, рухає Він гори\nЗцілює хвороби\nЦар повік - віків\n\nКуплет 2\nМій Бог чудовий, Спаситель всього світу,\nДав усім спасіння і ранами зцілив\nМій Бог чудовий,дав мені прощення\nПо милості живу я, слав святе Імя\n\nПрипев 2\nМій Бог чудовий, рухає Він гори\nЗцілює хвороби\nЦар повік - віків\n\nКуплет 3\nМогутній, Могутній, Чудовий, Чудовий - наш Спас\nСвятий, Святий, Великий, Великий - Творець\nЗвільнив нас, Звільнив нас, Він захист Він захист - Ти звільнив нас!\n\nПрипев 3\nМій Бог чудовий, рухає Він гори\nЗцілює хвороби\nЦар повік - віків', '', '', 'ua', NULL, 0, NULL, NULL),
(197, 206, 'Всем сердцем умом', 30, 'Куплет 1\nВсем сердцем, умом,\nВсей душою моей.\nВсем сердцем, умом,\nВсей душою моей.\n\nПрипев\nя возлюблю Тебя всем сердцем моим.\nя возлюблю Тебя умом моим.\nя возлюблю Тебя душой моей.\nТы- мой Господь, Ты- мой Господь.\n\nКуплет 2\nВсем сердцем, умом,\nВсей душою моей.\nВсем сердцем, умом,\nВсей душою моей.', '', '', 'ua', NULL, 0, NULL, NULL),
(198, 207, 'Час Господа прославляти', 0, 'Куплет 1\nЧас Господа прославляти,\nЧас нам принести хвалу сердець.\nЧас славу і честь віддати,\nЧас стати пред Ним таким як є,\nЧас.\n\nПрипев\nДень прийде і визнає кожен язик,\nІ кожен на коліна впаде,\nВічна нагорода чекає тих.\nЩо вибрали Тебе!\n\nКуплет 2\nVen, es hora de adorarle\nVen, abre tu corazon a Él\nVen, ante su trono estamos\nVen, ante la majestad de Dios\nVen!\n\nRefrain\nToda lengua confesaran que Él es Dios\nLas orillas se doblarán\nY un tesoro eterno tendrás en Él\nSi escoges su amor!\n... .   \nЧас Господа прославляти!!!!', '', '', 'ua', NULL, 5, '2020-06-21', NULL),
(199, 208, 'Дай мне видеть величие Твое', 0, 'Куплет 1\nДай мне видеть величие Твое,\nДай мне видеть могущество Твое.\nВозведи меня на высоты Твои,\nЧтобы мне утешатьса Тобою, мой Бог.\n\nПрипев\nТы один, Иисус, Кого люблю,\nТы один, Господь, Кому я поклоняюсь,\nОдин Иисус, Кого люблю,\nОдин Господь, 	Кому я доверяю.\n\nКуплет 2\nТолько Ты, Господь, моя сила и щит,\nТы сложил в уста мои новою песнь.\nТы один- крепость жизни моей, Иисус,\nТы- моя скала, Тебе я доверяю.', '', '', 'ua', NULL, 0, NULL, NULL),
(200, 209, 'Хліб життя Жива вода', 30, 'Куплет 1\nХліб життя, Жива вода,\nСвітло для світу, Божий Син,\nВиноградна лоза, Правда і Шлях,\nПастир добрий, миру Цар.\n\nПрипев\nІсус, Ти - мій Господь, мій Бог,\nТи знаєш мій шлях, кожен мій крок.\nІсус любов´ю смерть здолав,\nЗі мною Ти, Вічний, Святий.\n\nКуплет 2\nЦар царів, Воскресіння й Життя,\nАгнець Божий, Початок і кінець,\nСлово вічне, Двері вівцям,\nДивний порадник, Ранкова Зоря.\n\nПрипев1\nІсус, Ти - мій Господь, мій Бог,\nТи знаєш мій шлях, кожен мій крок.\nІсус любов´ю смерть здолав,\nЗі мною Ти, Вічний, Святий.\n\nПрипев2\nХвалаа...', '', '', 'ua', NULL, 0, NULL, NULL),
(201, 210, 'Ти вище влади всіх царів', 30, 'Куплет 1\n Ти - вище влади всіх царів,\nВище природи, бо Сам її створив,\nНайвища мудрість, Господь, лише в Тобі,\nСловом Ти створив цей дивний світ.\nТи- понад царства земних владик,\nВище багатства, що пропонує світ.\nНайбільше диво з усіх земних скарбів-\nТе, що ради мене Ти зробив.\n\nПрипев\n Кров пролив, розпятий на хресті,\nЩоб вмерти, жив, відкинений людьми,\nЯк троянда, топтана в землі,\nВзяв весь мій бруд і весь мій гріх на себе Ти.\n\nКуплет 2\nТи - вище влади свіх царів,\nВище природи, бо Сам її створив,\nНайвища мудрість, Господь, лише в Тобі,\nСловом Ти створив цей дивний світ.\nНайбільша сила - в Твоїх руках,\nУ каплях крові, що капали з хреста,\nВ простих словах, які залишив Ти,\nЩоб ми любили так, як любиш Ти.', '', '', 'ua', NULL, 0, NULL, NULL),
(202, 211, 'В сиянии Царя блеск величия', 0, 'Куплет 1\nВ сиянии Царя - блеск величия!\nПусть вся земля поет, ликует и поет!\nОн в свет облек Себя, и в страхе меркнет тьма\nОт голоса Его / 2 р.\n\nКуплет 2\nНаш Бог так велик! Пой со мной:\n\"Наш Бог так велик!\"\nПусть видят все:\nНаш Бог, наш Бог так велик!\n\nКуплет 3\nНаш Бог стоит в веках, все дни в Его руках,\nНачало и конец, начало и конец.\nГосподь наш Триедин - Дух, Отец и Сын!\nАгнец Он и Лев, Агнец Он и Лев!\n\nКуплет 4\nОн превыше всех имен,\nИ всей хвалы достоин Он.\nДуша поет - наш Бог так велик!', '', '', 'ua', NULL, 0, NULL, NULL),
(203, 212, 'Достоин', 0, 'Куплет 1\nДостоин, достоин, достоин\nПринять славу и честь\nСвятый, святый, святый\nБожий Сын Иисус\n\nПрипев\n Ты прекрасен, Господь сильный, Господь славный, наполняй сердца\n\nКуплет 2\nДостоин, достоин, достоин\nПринять славу и честь\nСвятый, святый, святый\nБожий Сын Иисус\n\nПрипев\n Ты есть первый и последний, Бог великий, наполняй сердца', '', '', 'ua', NULL, 2, '2020-06-17', NULL),
(204, 213, 'Да будет Имя Бога', 0, 'Куплет 1\n  Да будет Имя Бога благословенно -2р.\nОтныне и вовек, отныне и вовек -2р.\n\nКуплет 2\nОт восхода солнца и до запада да будет Имя Бога благословенно\nОтныне и вовек, отныне и вове\nНад народами Господь высок, да будет Имя Бога благословенно\nОтныне и вовек, отныне и вовек\n\nПрипев\nСлава Ему\nСлава Царю\nБогу нашему, вечно сущему  -2р.\n\nКуплет 3\nНад небесами вовек слава Его\nДа будет имя Бога благословенно\nОтныне и вовек, отныне и вовек. -2р.', '', '', 'ua', NULL, 0, NULL, NULL),
(205, 214, 'На початку Бог створив землю й небеса', 30, 'Куплет 1\nНа початку Бог створив землю й небеса,\nВсе Його творіння є велич та краса.\n\nПрипев\nСонце, гори і ліси,  все кругом, що бачиш ти -\nЦе створила все Його рука.\nВсі найкращі почуття і любов, і доброта\nВ серці є коли співа душа.\n\nКуплет 2\nКоли землю Бог творив де ти був тоді ?\nХто на небі призначив місце для зорі?\n\nКуплет3\nБуду славити Того, Хто створив усе,\nТи довір Йому життя - любить Бог тебе.\n\nКуплет4\nСлави Господньої повна вся земля.\nХай лине до небес Господу хвала!', '', '', 'ua', NULL, 0, NULL, NULL),
(206, 215, 'Славь душа Господа Славь душа', 30, 'Припев:\nСлавь душа, Господа, Славь душа,\n  Имя святое Его.\n  Пой Ему, как никогда, пой, душа,\n  Благослови Господа.\n\nКуплет 1\nСолнце встает, новый день приходит,\n Время опять хвалу воздать\n За все, что Ты мне дал, и за каждый новый вдох мой\n Я буду петь и на закате дня.\n\nКуплет 2\n Велик в любви, и даешь мне милость,\nТы справедлив и так благ ко мне,\nЗа все Твои дела я хочу прославить\nЧтоб петь Тебе, есть 10 тысяч причин.\n\nКуплет 3\nИ когда мои силы иссякнут\nНа закате дней, когда время придет,\nДуша моя Тебя да будет славить\nБольше, чем даже 10 тысяч лет.', '', '', 'ua', NULL, 6, '2021-03-24', NULL),
(207, 216, 'Аллилуйя Аллилуйя Аллилуйя', 30, 'Припев\n Аллилуйя, Аллилуйя,  Аллилуйя !\n Аллилуйя, Аллилуйя,  Аллилуйя !\n\nКуплет 1\nСлавте все Того, Кто милостив, чья любовь дана навек.\nПусть воскликнет дом Израилев, что любовь Его на век.\n\nПрипев\n Аллилуйя, Аллилуйя,  Аллилуйя !\n Аллилуйя, Аллилуйя,  Аллилуйя !\n\nКуплет 2\nМне Он сделался  спасением  в Нем и жизнь, и песень моя.\nНе умру, но Имя Господа буду веч но славить я!\n\nПрипев\n Аллилуйя, Аллилуйя,  Аллилуйя !\n Аллилуйя, Аллилуйя,  Аллилуйя !\n\nКуплет 3\nВ час бедьі я призову Его, Он усльішит этот зов.\nВ час борьбьі меня поддержит Он, смело встречу я врагов.\n\nПрипев\n Аллилуйя, Аллилуйя,  Аллилуйя !\n Аллилуйя, Аллилуйя,  Аллилуйя !\n\nКуплет 4\nОтворите двери правды мне, мне туда откройте вход.\nВ эту дверь с благодарением всякий праведник войдёт!\n\nПрипев\n Аллилуйя, Аллилуйя,  Аллилуйя !\n Аллилуйя, Аллилуйя,  Аллилуйя !', '', '', 'ua', NULL, 0, NULL, NULL),
(208, 224, 'Хвалите хвалите Бога небес Аллилуйя Аллилуйя', 0, 'Куплет 1\n Хвалите, хвалите Бога небес\n Хвалите, хвалите Бога небес.\n Хвалите все, в ком дыханье есть.\n Хвалите, Он наш Творец!!!\n\nПрипев\nАллилуйя, Аллилуйя!\nБогу хвала, Богу хвала!!!\n\nКуплет 2\nПрославьте, прославьте, Бога небес.\nПрославьте, прославьте, Бога небес.\nПрославьте все, в ком дыханье есть.\nПрославьте, Он - наш Творец!!!', '', '', 'ua', NULL, 2, '2020-10-18', NULL),
(209, 219, 'Залишивши батьківський рідний край', 0, 'Куплет 1\nЗалишивши батьківський рідний край\nВ чузий край наш народ емігрував\nАле Господь нас тут не залишав\nІ храм Священний Він Свій збудував.\n\nКуплет2\nНелегкою дорога в нас була\nНе раз сльоза тремтіла на очах\nТа церква наша, як одна сім´я\n\nПрипев\nБлагослови. Господь. Ти свій народ\nНехай в серцях горить святий вогонь\nЩоб не здлала ворога рука\nТу еркву, що Ти, Боже, збудував.\n\nКуплет 3\nБагато душ притулок в ньій знайшли\nСпасіння для безсмертної душы,\nУтіху для утомлених сердець\nІ вічне щастя, що дає Отець !\n\nКуплет4\nБазаємо щиро, Господи, Тебе\nДопоможи пройти життя земне\nІвіру зберехти в своїх серцях\nТебе зустріти там,на небесах !\n\nПрипев\nБлагослови. Господь. Ти свій народ\nНехай в серцях горить святий вогонь\nЩоб не здлала ворога рука\nТу Церкву, що Ти, Боже, збудував.', '', '', 'ua', NULL, 0, NULL, NULL),
(210, 220, 'Здесь на земле ми только странники', 0, 'Куплет 1\nЗдесь на земле ми только странники\nИ часто путь далекий ждет\nПорою ноги то усталости болят \nНо в небе родина нас ждет.\n\nПриспів\nТам-там-там, в небесах ангелы поют\nВ синих-синих-синих небесах, Родина нас ждет\n\nКуплет 2\nПорою ми друзей встречаем\nИ снова дальний путь зовет\nУвидимся у ног Спасителя Христа\nВедь в небе Родина нас ждет\n\nКуплет 3\nВ дороге дальней, дорогие друзья\nВы расскажите людям всем,\nКак велика любовь Спасителя Христа,\nЧто в небе Родина нас ждет.', '', '', 'ua', NULL, 0, NULL, NULL),
(211, 221, 'Коли Ісус мій най кращий Друх з ним щасливий я', 0, 'Куплет 1\nКоли Ісус найкращий Друг, з Ним щасливий я,\nХай навіть грім гримить навкруг, співа душа моя,\nХай навіть сонце не зійде, все сховає ніч.\nДуша надією живе, Він допоможе їй.\n\nПрипев\n Він найкращий Друг, вірю я Йому,\n З Ним не страшно йти, Він - найкращий Друг.\n Хай навіть сонце не зійде, все сховає ніч,\n Душа надією живе, Він допоможе їй!\n\nКуплет 2\nКоли Ісус найкращий Друг, в серці віра є, - \nНа небі горя не буде, де мій Ісус живе.\nСкоро Він з небес прийде, в славі Божий Син,\nМене до Себе забере, повік я буду з Ним.', '', '', 'ua', NULL, 3, '2020-07-19', NULL),
(212, 225, 'Знаходиться світ в дні останні', 30, 'Куплет 1\n Знаходиться світ в дні останні -\nПророки звіщали про це.\nІ царство повстане на царство,\nНарод на народ повстає...\nХоч голод і мор, землетруси,\nСтривожать на світі усіх\nГлядіть, не лякайтесь, бо скоро прийде\nІсус, Божий Син, по Своїх!\n\nПрипев\nОсь Він гряде на білому коні,\nІ золотий вінець блищить на голові.\nТруба звучить, що воля настає\nІ голосить, що Божий Син іде!\n\nКуплет 2\nІсус же промовив для учнів,\nЩо скоро прийде вже кінець.\nНастане великий день суду\nОдним - смерть, а другим - вінець.\nХоч сонце затьмиться і місяць,\nКоли зазвучить та сурма.\nНе бійтесь, бо скоро проявить Себе\nІсус, Божий Син, в небесах!\n\nКуплет 3\nІсус вже скоро прийде!!! (8р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(213, 226, 'Ось Він гряде', 0, 'Куплет 1\nЗнаходиться світ в дні останні -\nПророки звіщали про це.\nІ царство повстане на царство,\nНарод на народ повстає...\nХоч голод і мор, землетруси,\nСтривожать на світі усіх!\nГлядіть, не лякайтесь, бо скоро прийде,\nІсус, Божий Син, по своїх!\n\nПрипев\nОсь Він гряде на білому коні,\nІ золотий вінець блищить на голові.\nТруба звучить, що воля настає,\nІ голосить, що Божий Син іде!\n\nКуплет 2\nІсус же промовив до учнів,\nЩо скоро прийде вже кінець.\nНастане великий день суду -\nОдним - смерть, а другим - вінець.\nХоч сонце затьмиться і місяць,\nКоли зазвучить та сурма.\nНе бійтесь, бо скоро проявить Себе,\nІсус, Божий Син в небесах!\n\nКуплет3\nІсус вже скоро прийде! (8р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(214, 227, 'Мій Бог моя надія', 0, 'Припев\nМій Бог - моя надія, відтепер і назавжди.\nО, мій Бог - моя надія повік - віків!\n\nКуплет 1\nПоклоняюсь я перед лицем Його.\nВін могутній, Він Святий Отець віків;\nСтихає буря перед Ним, все завмира,\nВсесильний Бог є Він, Отець Він поколінь.\n\nПрипев\nМій Бог - моя надія відтепер і назавжди.\nО, мій Бог - моя надія повік - віків!\n\nКуплет 2\nКожен день Він свіжу милість подає,\nІ для грішника Він прощення дає.\nХто відкинутий всіма - Ісус прийме,\nВін йому дасть спокій. Притулок свій знайде.\n\nПрипев\nМій Бог - моя надія відтепер і назавжди.\nО, мій Бог - моя надія повік- віків!\n\nКуплет 3\nМій Бог - моя надія!', '', '', 'ua', NULL, 2, '2021-01-31', NULL),
(215, 228, 'Царю мій Пане мій Ісусе коханий мій', 0, 'Куплет 1\nЦарю мій, Пане мій, Ісусе коханий мій!\nЗаспіваємо Ісусу знов\nЗ вічною подякою за ту кров, що капала\nЗа Твою безмежну любов\nДовго ми блукали, слухали лукавого, \nПокривилися наші путі.\nІ коли все згаснуло - зіронькою ясною\nТи зійшов у нашому житті.\n\nПрипев\nВся слава - Тобі! Вся велич - Тобі!\nТи Один гідний хвалу всю прийняти.\nТи - Пан над панами, Ти - Цар над царями,\nТебе буду я все життя прославляти !\n\nКуплет 2\nЦарю мій, Пане мій, Ісусе коханий мій!\nЯ схиляюся до ніг Твоїх!\nЗ вічною подякою за ту кров, що капала\nЗа відкуплення гріхів моїх.\nЗа нас знеславлений, був життя позбавлений \nТи взяв владу, пекло зруйнував!\nБогом був воскрешений, вище всіх піднесений,\nТи навіки нашим Царем став!\n\nПрипев\nВся слава - Тобі! Вся велич - Тобі!\nТи Один гідний хвалу всю прийняти.\nТи - Пан над панами, Ти - Цар над царями,\nТебе буду я все життя прославляти !', '', '', 'ua', NULL, 0, NULL, NULL),
(216, 229, 'Радійте співайте і славте', 30, 'Куплет 1\nРадійте, співайте і славте \nОбмитії кров´ю Христа!\nВи пісню нову заспівайте\nТому, Хто вас спас від гріха.\n\nПриспів\nРадійте, радійте,\nСпівайте і славте Христа! (2р)\n\nКуплет 2\n Прославмо Того, Хто на землю\nЗійшов, щоби нас оправдать.\nСпасти нас пречистою кров´ю\nІ щастя навіки нам дать.\n\nКуплет3\nВін сили нам дасть й перемогу.\nЗ гріхом в боротьбі підкріпить,\nЛюбов´ю Своєю піддержить\nІ Духом Святим нас зміцнить.\n\nКуплет4\nВсі радісним сердцем співайте,\nВіддайте подяку тому,\nХто Сам заплатив за нас кров´ю\nО, слава навіки Йому!', '', '', 'ua', NULL, 0, NULL, NULL),
(217, 231, 'Подивися навкруги на красу землі своєї', 30, 'Куплет 1\nПодивися навкруги, на красу землі своєї - \nВсе це Бог наш сотворив силою руки своєї.\nВін один так полюбив, що віддав нам Cвого Сина.\nМилість Бог Cвою явив, щоб спаслася Україна.\n\nПриспів:\nМи молим за свій край,\nСпасіння людям дай - \nМи Тебе благаєм.\n\nКуплет 2\nЛюбов свою яви,\nГосподь, благослови\nНашу Україну.\n\nКуплет 3\nБоже, єдності нам дай, навчи любити і прощати.\nВ згоді Господа Христа будем разом прославляти.\nТи один так полюбив, що віддав нам Свого Сина.\nМилість нам свою явив, щоб спаслася Україна.', '', '', 'ua', NULL, 0, NULL, NULL),
(218, 232, 'Все через Нього Всесвіт весь Його', 30, 'Куплет 1\nВсе через Нього, Всесвіт весь Його!\nВсе через Нього, Всесвіт весь Його!\n\nПрипев\nЙому за все слава!\nНавіки. Амінь!\n\nКуплет 2\nБезодня багатства, \nПремудрості Христа,\nЯк неосяжні дороги Господа!\n\nКуплет3\nРозум Господній, хто з людей пізнав?\nЙого премудрість звіщають небеса.\n\nКуплет4\nТож прославляймо ім\'я Господа,  \nХай безупинно звучить Йому хвала!\n\nПрипев\nІсусу  вся слава!\nНавіки. Амінь!\n\nКуплет4\nВсе через Нього, Всесвіт весь Його!\n...                ...                     ... \nВсе через Нього, Всесвіт весь Його!', '', '', 'ua', NULL, 2, '2021-01-20', NULL),
(219, 233, 'Хваліть Господа добрий бо Він', 0, 'Куплет 1\nХваліть Господа, добрий бо Він,\nБо навіки Його милосердя!\nХваліть Господа в зборі святім,\nХвалі те від щирого серця.\nХвали Господа, Єрусалим,\nПрославляй свого Бога, Сіоне,\nБо зміцнив Він засуви брам твоїх!\nБо для тебе Він - щит, охорона!\n\nПрипев\nЗламаних серцем лікує, рани болючі загоїть,\nСпокій у серце приносить кожному, хто щиро просить!\nЩиро дає так багато, сонцю наказує встати!\nЗемлю дощем напоїти, щоби святі Його діти,\nРаділи Ним!\n\nКуплет 1\n//Алілуя! Раділи Ним!// - 2р.', '', '', 'ua', NULL, 4, '2021-01-17', NULL),
(220, 234, 'Як до струменя олень', 0, 'Куплет 1\nЯк до струменя олень так душа моя хоче,\nЛиш до Тебе, мій Боже, все летить і летить.\nЛиш до Тебе, Чудовий, і в півдня, і в півночі \nПориваються очі, і сльоза в них тремтить.\n\nПрипев\nТи мешкаєш над морем, Ти пануєш землею.\nТи є Цар і Страдалець, мій Спаситель Ісус.\nЯ до Тебе бажаю, як бджола до лілеї,\nЯк до струменя олень, так до Тебе і я.\n\nКуплет 2\nДе весілля безмірне, де невір´я  негідне,\nТам немає утіхи для душі без Христа.\nТільки там лиш знайду я собі щастя безмірне,\nДе панує братерство, де свята чистота.', '', '', 'ua', NULL, 0, NULL, NULL),
(221, 236, 'Нет никого как Ты', 30, 'Куплет 1 /2раза.\nНет никого как Ты!\nНикто не может так коснуться меня.\nЯ могу искать всю жизнь - не найти.\nНет никого как Ты!\n\nПрипев/2раза.\nТвоя рука на мне - я не боюсь,\nКогда Ты рядом со мной.\nТы знаешь сердце и мысли мои.\nНет никого, как Ты!\n\nКуплет 2/2раза.\nТы искупил мой грех,\nИ благодать Твоей небесной любви\nВ нерукотворном храме наших сердец.\nНет никого как Ты!', '', '', 'ua', NULL, 0, NULL, NULL),
(222, 217, 'Хай уся земля і небо радіє', 30, 'Куплет 1\nЗнаєш ти , що в Ісусі є нове життя,\n Радіть і перемога Богом кожному дана.\nІ це благословіння є найбільший скарб, -\n Бог тобі спасіння дарував!\n\nПрипев\n Хай уся земля і небо радіє,\n  Хай усе живе прославить Його!\n Хай народи всі разом величають\n  Сина Божого.\n\nКуплет 2\nБог завжди допоможе, силу дасть тобі,\n Тільки в Ньому свобода від усіх гріхів твоїх.\nІ це благословіння є найбільший скарб, -\n Бог тобі спасіння дарував!\n\nПрипев\n Хай уся земля і небо радіє,\n  Хай усе живе прославить Його!\n Хай народи всі разом величають\n  Сина Божого.', '', '', 'ua', NULL, 2, '2021-02-28', NULL),
(223, 237, 'Слав душа Господа Слав душа', 0, 'Припев\nСлавь, душа, Господа, Славь, душа,\nИмя святое Его!\nПой Ему, как никогда, пой, душа, \nБлагослови Господа!\n\nКуплет 1\nСолнце встает, новый день приходит,\nВремя  опять хвалу воздать\nЗа все, что Ты мне дал,\n И за каждый новый вдох мой.\nЯ буду петь и на закате дня!\n\nКуплет 2\nВелик в любви  и даешь мне милость,\nТы справедлив и так благ ко мне.\nЗа все Твои дела я хочу прославить, \nЧтоб петь Тебе,\n Есть 10 тысяч причин.\n\nКуплет 3 \nИ когда мои силы иссякнут,\nНа закате дней, когда время придет,\nДуша моя Тебя да будет славить\nБольше, чем даже 10 тысяч лет!', '', '', 'ua', NULL, 0, NULL, NULL),
(224, 238, 'Вгору мої очі здійму', 30, 'Куплет 1\nВгору мої очї здійму,\nБоже, прийми мою хвалу,\nВсього себе, все , що в мені,\nБоже, Тобі я віддаю!\n\nПрипев\nСпіватиму, Боже, Тобі завжди,\nЛюбитиму, Боже, Тебе, завжди,\nВіддам Тобі, Боже, себе всього,\nЩоб виконать волю Господа мого, волю Його!\n\nКуплет 2\nСерце моє славить Тебе,\nТи - все найкраще й дороге,\nЩо маю я, тільки в Тобі\nМоя надія назавжди.', '', '', 'ua', NULL, 3, '2020-11-20', NULL),
(225, 239, 'Не умру я но буду жить истиной Твоей', 0, 'Куплет 1\nНе умру я, но буду жить истиной Твоей.\nВ тесноте я воззвал Ты услышал меня.\nОкружили и сильно толкнули меня\nНо Господь поддержал Он защита моя.\n\nПрипев\nВот кому принадлежит вся жизнь моя\nАгнец Божий взял мой грех, дал распять Себя \nВот кому принадлежит вся жизнь моя\nС каждой раны Твоей -  крик: \"Люблю Тебя \".\n\nКуплет 2\nМой Господь - моя  сила, спасение мое,\nОтвори врата правды -  и к Тебе я войду.\nГласом радости буду славить Имя Твое,\nПоспеши же ко мне - и Тебя я найду.', '', '', 'ua', NULL, 2, '2020-11-01', NULL),
(226, 240, 'Льется тихий вечер над землею', 0, 'Куплет 1\nЛьется тихий вечер над землею,\nТихо шелестит листва в саду,\nПотрескивают  свечи, а мы сидим все вместе,\nИ думы об одном,  лишь об одном.\n\nПрипев\n О дай нам сердце чистое,\n Как снега сибирские\nГорящее, как солнце над землей.\n\nКуплет 2\nБледный лунный свет проник в окошко,\nЖелтая завидует луна.\nА мы сидим все вместе, \nПлечом к плечу, и песню\nПоем лишь об одном, лишь об одном\n\nКуплет 3\nПролетают годы, расстояния,\nПроплывают реки и моря.\nА мы сидим все вместе,\nПлечом к плечу, и песню\nПоем лишь об Одном, лишь о Христе.', '', '', 'ua', NULL, 0, NULL, NULL),
(227, 241, 'Моє життя тут на землі', 0, 'Куплет 1\nМоє життя тут на землі,\nНе мало змісту, ні ціни,\nІсус прийшов, спасіння дав,\nЗа мене кров Свою пролляв.\n\nПрипев\nСпасіння я знайшов, \nТепер я прощений, Господь!\nТвій Дух Святий живе в мені!\n\nКуплет 2\nСвятого Духа дарував,\nМене від смерті врятував.\nІ в кожну мить готовий я,\nЗ Ним зустріч мати в небесах.\n\nПрипев\nСпасіння я знайшов \nТепер я прощений, Господь!\nТвій Дух Святий живе в мені!\n\nКуплет 3\nІ Дух Святий живе в мені!\nІ Дух Святий живе в мені!\nІ Дух Святий живе в мені!\n\nПрипев\nСпасіння я знайшов \nТепер я прощений, Господь!\nТвій Дух Святий живе в мені!', '', '', 'ua', NULL, 2, '2020-12-06', NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(228, 242, 'Знаєш ти що в Ісусі є нове життя', 30, 'Куплет 1\nЗнаєш ти, що в Ісусі є нове життя,\nРадість і перемога Богом кожному дана.\nІ це благословіння є найбільший скарб,\nБог тобі спасіння дарував!\n\nПрипев\nХай уся земля і небо радіє,\nХай усе живе прославить Його.\nХай народи всі разом величають\nСина Божого.\n\nКуплет 2\nБог завжди допоможе, силу дасть тобі.\nТільки в Ньому свобода від усіх гріхів твоїх.\nІ це благословіння є найбільший скарб,\nБог тобі спасіння дарував!', '', '', 'ua', NULL, 0, NULL, NULL),
(229, 243, 'Ісус Ти сходиш світанком в серці моїм', 0, 'Куплет 1\nІсус, Ти сходиш світанком в серці моїм,\nТвоя милість мене трима.\nЗнаю, кожного ранку чуєш Ти голос мій.\nІсусе, рівних Тобі нема.\nТи приходиш - світає в душі,\nТи знаходиш найкраще в мені.\n\nПрипев\nТи - Світанок нового дня!\nТвоя милість мене наповня,\nВ Тебе буду вірити я!\nТи - Світанок моєї душі,\nВсе найкраще, що є в мені,\nВіддаю я тільки Тобі!\n\nКуплет 2\nТільки Тобі! Тільки Тобі!\nТільки Тобі! Тільки Тобі!', '', '', 'ua', NULL, 0, NULL, NULL),
(230, 218, 'Ісуса якого люблю', 0, 'Куплет 1\nІсуса, Якого люблю, \nЯ чекаю кожен день.\nСказав Він, що скоро прийде, \nМоже, вночі, може, вдень. \nТим часом, як ще бариться, \nПідношу очі догори.\nТримаюсь обітниць Його,\n Бо вірні всі вони.\n\nПрипев\nМоже, день один, може, ніч одна,\nМоже, ще сльоза, чи крапля поту.\nНизину пройти, на гору зійти.\nКривду ще знести,-\nІ прийде мій Спас.\n\nКуплет 2\nПро війни і голод чую,\nКатастрофи на землі.\nПро все це колись сказав Він,\nЯк ще жив на цій землі.\nМоя надія уся на Нього,-\nБо поможе Він мені.\nЩоденно вслід за Ним\nВ моїм житті я хочу йти.', '', '', 'ua', NULL, 1, '2021-01-24', NULL),
(231, 244, 'Ти є скала мойого спасіння Ти сила могожиття', 0, 'Куплет 1\nТи є скала мого спасіння,\nТи сила мого життя,\nМоя надія, моє натхнення,\nБоже! Тебе кличу я.\n\nПрипев\nВ Тебе вірю я, вірю я,\nБо в Тобі є вічне життя.\nТи любов моя, допомога моя, \nНа Тебе надіюся я.\n\nКуплет 2\nКоли журба моє тисне серце,\nТи є потіха моя.\nТи - моя радість, моє Ти щастя, \nВ Тобі втішаюся я!\n\nКуплет3\nТобі, Господь, я хвалу складаю,\nТобі подяка моя,\nТобі молюся, Тобі співаю, \nСлава Тобі і хвала!', '', '', 'ua', NULL, 3, '2021-01-20', NULL),
(232, 245, 'Як олень прагне до потоків', 0, 'Куплет 1\nЯк олень прагне до потоків,\nТак душа моя прагне Тебе.\nЯ бажаю Тобі сказати, \nЩо я так люблю Тебе.\n\nПрипев\nТи один моє серце знаєш,\nІ в нього Ти любов вливаєш.\nЯ бажаю Тобі сказати,\n Що я так люблю Тебе.\n\nКуплет 2\nПростягнув ти пробиті руки\nІ від смерті мене врятував\nЩоб мене захистить від муки,\nНа хресті ти кров проляв.\n\nПрипев\nТи один моє серце знаєш,\nІ в нього Ти любов вливаєш.\nЯ бажаю Тобі сказати,\n Що я так люблю Тебе.\n\nКуплет 3\nЩирим серцем тебе кохаю,\nБо життя дарував ти мені.\nЗа твою доброту і ласку\nДуже вдячний я Тобі.', '[{\"nombre\":\"Куплет 1\",\"veces\":1},{\"nombre\":\"Припев\",\"veces\":3},{\"nombre\":\"Куплет 2\",\"veces\":1},{\"nombre\":\"Припев\",\"veces\":3},{\"nombre\":\"Куплет 3\",\"veces\":1}]', 'D', 'ua', '', 4, '2021-03-03', '2025-07-28'),
(233, 246, 'Господь є Пастир', 0, 'Куплет 1\nГосподь є Пастир і Він провадить\nЧерез долину всіх незгод.\nПройду я через всі перешкоди, \nІ буду знати -  зі мною Бог.\n\nПрипев\nВеди мене, Господь, завжди.\nВ руках Твоїх мої стежки,\nВ моїх устах Твої слова\nЯ збережу до кінця.\n\nКуплет 2\nВін Пастир Добрий і  Він поможе \nМені не впасти у боротьбі.\nЙого рука веде завжди, \nТримає міцно мене в житті.', '', '', 'ua', NULL, 0, NULL, NULL),
(234, 247, 'Бог мой Ты скала моя', 30, 'Куплет 1\nБог мой, Ты – скала моя, на Тебя я уповаю.\nЩит мой, спасение моë, Господь – опора моя.\n\nПриспів\nВ тесноте моей призвал я Господа,\nИ к Богу моему воззвал.\nИ услышал Он, и услышал Он!\nОт чертога Своего голос мой.\n.        .        .\nЛюблю Тебя, Господи, крепость моя,\nТвердыня моя и прибежище моë! (2р.)\n\nКуплет 2\nБоже, Ты даëшь мне свет,\nПросвещаешь тьму мою!\nБоже, Твой непорочен путь,\nИ чисто Слово Твоë!\n\nПриспів\nВ тесноте моей призвал я Господа,\nИ к Богу моему воззвал.\nИ услышал Он, и услышал Он!\nОт чертога Своего голос мой.\n.        .        .\nЛюблю Тебя, Господи, крепость моя,\nТвердыня моя и прибежище моë! (2р.)\n\nКуплет 3\nЖив Бог и благословен,\nБог спасенья моего!\nТы избавляешь от врагов,\nВозносишь, Боже, меня!\n\nПриспів\nВ тесноте моей призвал я Господа,\nИ к Богу моему воззвал.\nИ услышал Он, и услышал Он!\nОт чертога Своего голос мой.\n.        .        .\nЛюблю Тебя, Господи, крепость моя,\nТвердыня моя и прибежище моë! (2р.)', '', '', 'ua', NULL, 1, '2021-03-14', NULL),
(235, 248, 'Ми прийшли сьогодні у святий Твій дім', 0, 'Куплет 1\nМи прийшли сьогодні у святий Твій дім,\nЩоб Тобі одному славу возвести,\nЩоб Тобі віддати кожен свій тягар,\nО, Небесний Батьку, Ти – Всесильний Цар.\n\nПриспів\nСвят, свят, свят наш Господь- Вседержитель, \nТой, що був, і що є, і що має прийти!\nСвят, свят, свят наш Господь - Вседержитель, \nТой, що був, і що є, і що має прийти!\n\nКуплет 2\nВсемогутній Боже, над царями – Цар,\nДай води живої спрагненим серцям.\nМи прийшли сьогодні у святий Твій дім,\nЩоб Тобі одному славу возвести..\n\nКуплет 3\nВсемогутній Батьку, Ти є Цар всього:\nІ землі, і неба, і життя мого.\nДай Тобі служити у своїм житті,\nЩоб з Тобою бути в вічності завжди.', '', '', 'ua', NULL, 0, NULL, NULL),
(236, 249, 'Твоя любов немов ріка', 30, 'Куплет 1\nТвоя любов, немов ріка,\nЯк височінь могутніх гір,\nЗдійму до Тебе я свій зір,\nІ заспіваю Тобі.\n\nКуплет 2\nДо мого серця доторкнись,\nВідчути хочу цю любов,\nНехай Твій Дух Святий зійде\nЙ наповнить серце знов.\n\nПриспів\nПро Твою любов співаю,\nХай мій спів від душі лунає\nКожне серце нехай пізнає,\nЩо любов Твоя не минає.', '', '', 'ua', NULL, 2, '2020-11-23', NULL),
(237, 250, 'Хочу вклонитись Тобі', 30, 'Куплет 1\nХочу вклонитись Тобі,\nЕммануїл!\n\nКуплет 2\nТи народився для нас,\nТи був розп\'ятий за нас,\nТворче Всесильний і Бог,\nЕммануїл!\n\nКуплет 3\nЩастя в житті мені дав,\nРадість небесну послав,\nДобрий Спаситель і Бог,Еммануїл!\n\nКуплет 4\nТи нас візьмеш в небеса, \nТам де оселі Отця\nБуду співати  Тобі - Алілуя!\n\nКуплет 5\nСпокій небесний тепер\nВ серці моєму живе.\nЗа це я славлю Тебе,Еммануїл!\n\nКуплет 6\nТи народився для нас,\nТи був розп\'ятий за нас,\nТворче Всесильний і Бог,\nЕммануїл!\nТи нас візьмеш в небеса, \nТам де оселі Отця\nБуду співати  Тобі - Алілуя!\n\nКуплет 7\nХочу вклонитись Тобі,\nЕммануїл!', '', '', 'ua', NULL, 6, '2020-12-20', NULL),
(238, 251, 'Ты нужен мне больше чем вчера', 0, 'Куплет 1\n Ты нужен мне больше, чем вчера,\n Ты нужен мне больше, чем могу сказать,\nТы нужен мне так, как никогда\nТы нужен мне, Ты нужен мне.\n\nПрипев\nБольше чем я хочу, больше чем я пою,\nБольше чем сердца стук, больше всего.\nИ Господь, никогда я не оставлю тебя\nТы - жизнь моя и свет мой, я люблю Тебя.\nТы нужен мне.\n\nКуплет 2\nВ Твоем присутствии Господь, я счастлив всегда\nИ мое сердце нашло небесный дом Отца.\nЯ не буду одинок....', '', '', 'ua', NULL, 1, '2020-11-16', NULL),
(239, 222, 'Добрий Бог', 30, 'Куплет 1\nДобрий Бог.\nЗнаю я, Ти є кращий за всіх.\nВ світі цілім звучить голос Твій.\nПропонуєш ласку Ти всім Свою.\nЯ люблю Тебе,\nО, Ісус, я люблю Тебе.\nЗнаю я Ти є скеля моя,\nПорятунок мій тільки Ти Господь.\n\nПриспів\nТвоя милість, то мир і спокій,\nКожен день і навіки- віків,\nТвоя любов, то захист є мій.', '', '', 'ua', NULL, 1, '2021-01-20', NULL),
(240, 252, 'Христос є скеля вода з якої ллється', 0, 'Куплет1\nХристос є скеля, вода, з якої ллється,\nВода цілюща, що дає тобі життя.\nХристос є скеля, вода, з якої ллється,\nВода жива, що дасть тобі життя нове.\n\nПриспів: \nЯкщо хтось прагне -\nХай приходить й з неї п’є,\nОсвіжить душу і все єство своє.\nХристос є скеля, вода з якої ллється, \nВода жива, що дасть тобі життя нове.\n\nКуплет 2\nХристос - лілея на ланах квітучих,\nТроянда біла, свіжа із саду Сарон.\nХристос - життя й любов понад любов’ю,\nВін — Той, що нам Своє спасіння подає.', '', '', 'ua', NULL, 0, NULL, NULL),
(241, 235, 'Христос Воскрес', 30, 'Куплет1\nХристос (Воскрес)! (2р.) О радість, радість нам!\nХристос (Воскрес)! (2р.) Кінець журбі й сльозам.\nХристос (Воскрес)! Христос (Воскрес)!\nСмерть смертю подолав і нам спасіння вічне дав.\n\nКуплет2\nЙого злочинців руки на древі розп’яли,\nЗа нас тяжкії муки терпів Він у любві.\nПречиста кров лилася із ніг, рук і чола...\nЗвершилось все, - Йому хвала!\n\nКуплет3\nЗ Ариматеї Йосиф Пилата ублагав,\nЗ хреста щоб зняти тіло, - і зняв, і поховав\nВ саду, у новім гробі... Та сонце лиш зійшло,\nХриста вже в гробі не було.\n\nКуплет4\nДо гробу дуже рано Марія вже прийшла\nІ тіла там нежданно вона вже не знайшла...\nЯвивсь їй ангел з неба і радісно сказав:\n-Христос уже із мертвих встав!\n\nКуплет5\nСхвильована Марія не стримала ридань...\nАж їй у яснім світлі Христос явився Сам...\n-Учитель мій! - сказала, упавши перед Ним,\nЙ про чудо сповістила всім..', '', '', 'ua', NULL, 0, NULL, NULL),
(242, 180, 'Чудное имя открылось нам люди', 30, 'Куплет 1\nБог - наш Отець, а ми - Його діти.\nНіхто не вміє так, як Він любити.\nЙого творіння такі унікальні,\nРадісні, добрі, щирі, веселі, часом печальні.\n\nПрипев\nМи - Його діти, церква, сім\'я,\nОбручена Христу наречена.\nТіло Ісуса, смерть Його з\'єднала нас.\nКров\'ю омиті, чисті, святі,\nДухом народжені ми згори,\nВічним коханням полюбив, Себе відкрив.\n\nКуплет 2\nБудем разом Бога хвалити,\nВіддано й щиро всі Йому служити.\nБожу любов ми світу покажем,\nПро Його пролиту кров усім розкажем.', '', '', 'ua', NULL, 0, NULL, NULL),
(243, 166, 'Бог наш Отець Ми Його діти', 0, 'Куплет 1\nБог - наш Отець, а ми - Його діти.\nНіхто не вміє так, як Він, любити.\nЙого творіння, такі унікальні,\nРадісні, добрі, щирі, веселі, часом печальні.\n\nПрипев:\nМи - Його діти, церква, сім\'я,\nОбручена Христу наречена.\nТіло Ісуса, смерть Його з\'єднала нас.\nКров\'ю омиті, чисті, святі,\nДухом народжені ми згори,\nВічним коханням полюбив, Себе відкрив.\n\nКуплет 2\nБудем разом Бога хвалити,\nВіддано й щиро всі Йому служити.\nБожу любов ми світу покажем,\nІ про Його пролиту кров усім розкажем.\n\nКуплет 3\nБог - наш Отець, а ми - Його діти.', '', '', 'ua', NULL, 6, '2021-02-21', NULL),
(244, 124, 'За кожен день відати славу треба', 0, 'Куплет 1\nЗа кожен день віддати славу треба,\nБо джерелом життя є лише Він один.\nВеликий Бог, Творець землі і неба,\nЗавжди чекає, лиш до Нього ти прийди.\n\nКуплет 2\nЧекає Він тебе: і доньку, й сина,\nА ти блукаєш десь у темряві та злі.\nЧекає Він, бо ти - Його дитина,\nБо Він створив тебе, дав владу на землі\n\nПрипев\nДавайте візьмемось за руки,\nІ помолімося Христу,\nЩоб наші діти, наші внуки\nПізнали істину просту.\nНехай зростають вони,\nДухом водимі Святим,\nТа збережи їх від спокус, Ісус.\n\nКуплет 3\nНехай цвітуть сади на Україні,\nТа всіх наповнить джерела жива вода\nДай нам Господь, Твої благословення\nХай Дух Святий сповняє радістю серця.', '', '', 'ua', NULL, 1, '2021-02-21', NULL),
(245, 253, 'Яке є щастя що в земній недолі', 30, 'Куплет 1\nЯке є щастя, що в земній недолі \nЄ добрий Друг, Якому я в тиші \nЗвертаюся в молитві: Господи, прости! \nЗвертаюся в молитві: Нас помилуй\nІ допоможи іти до Царства, Святим Духом підкріпи!\n\nПрипев\nМи дякуєм Тобі за все!\nЗа сонце, місяць,  зорі ясні. \nІсус, Ти все створив для нас,\nЩо нам дає життя прекрасне. \nМи дякуєм Тобі за хрест, \nЗа вічний Дім у небі яснім.\nНехай Тобі звучить хвала, \nІ пісня наша хай не згасне!\n\nКуплет 2\nО, мій Спасе, як в житті чудово \nДякувать за все Тобі завжди.\nДякую за хліб, за хліб насущний, \nДякую за мир в душі моїй, \nДякую за милість, що до мене \nУ свій час Ти проявив.', '', '', 'ua', NULL, 0, NULL, NULL),
(246, 254, 'Свят Свят Господь Саваот', 30, 'Куплет 1\nСвят, Свят - Господь Саваоф\nИ вся земля полна славы Господней.\nСвят, Свят Господь Саваоф\nРука Твоя не сокротилась сегодня.\n\nПрипев\nСвят, Господь Саваоф!\nСвят, Господь Саваоф!\nСвят!!!\n\nКуплет 2\nТы нас собираеш как птица птенцов\nТы нас защищаешь от наших врагов\nТвое Царство пребывает вовеки - веков\nСвят, Свят Господь Саваоф!!!\n\nКуплет 3\nСвят, Свят - Господь Саваоф\nИ вся земля полна славы Господней.\nСвят, Свят Господь Саваоф\nРука Твоя не сокротилась сегодня.\n----------------------------------\nТы нас собираешь как птица птенцов\nТы нас защищаешь от наших врагов\nТвое Царство пребывает вовеки - веков\nСвят, Свят Господь Саваоф!!!', '', '', 'ua', NULL, 3, '2021-03-10', NULL),
(247, 255, 'Надеющиеся на Господа', 30, 'Куплет 1\nНадеющиеся на Господа,\nНадеющиеся на Господа.\nПоднимут крылья, как орлы\nПоднимут крылья, как орлы.\n\nКуплет 2\nПобегут и не устанут,\nПойдут и не утомятся!\nПоднимут крылья, как орлы.\nПоднимут крылья, как орлы!\n\nКуплет 3\nРазве ты не знаешь, разве ты не слышал,\nЧто Вечный Господь не изнемогает!\nОн сотворил концы земли не утомляется.\nРазум Его не исследим, разве ты не знаешь!', '', '', 'ua', NULL, 9, '2020-12-11', NULL),
(248, 256, 'Величний наш Бог', 30, 'Куплет1\nМогутній, Славний Цар,\nВеличний у красі.\nРадіє вся земля, радіє вся земля.\nУ Ньому світла блиск\nі темряви нема,\n\nКуплет2\nА голос, наче грім, а голос, наче грім.\nВеличний наш Бог!  Заспівай:\nВеличний наш Бог!  Прославляй!\nВеличний, Величний наш Бог.\nНезмінний у віках,\n\nКуплет3\nІ час в Його руках,\nПочаток і Кінець, \nпочаток і Кінець.\nОсоба в трьох один\nОтець, і Дух, і Син,\n\nКуплет4\nВін є Ягня і Лев \nВін є Ягня і Лев \nІм\'я Твоє понад усі\nВся хвала лише Тобі\nзаспіваю знов : “Величний наш Бог”\nАлілуя…', '', '', 'ua', NULL, 0, NULL, NULL),
(249, 257, 'Я поклоняюсь Тобі', 25, 'Куплет 1 \n// Я поклоняюсь Тобі,\n Величаю Тебе, Ісусе!\nЯ віддаю всі жалі \nІ турботи Тобі, Ісусе! // - 2р.\n\nКуплет 2\nЯ лечу до Тебе, \nБолі забуваю,\nБо Тебе кохаю, Ісусе!\nПоруч Ти, я знаю, \nНіжним Своїм Духом\nНас оберігаєш, Ісусе!\n\nКуплет 3\nЯ вибираю Тебе,\nВ моїм серці лиш Ти, Ісусе!\nІншого шляху нема, \nСпалені всі мости, Ісусе!\n\nКуплет 4\nЯ лечу до Тебе, болі забуваю,\nБо Тебе кохаю, Ісусе!\nПоруч Ти, я знаю, \nНіжним Своїм Духом\nНас оберігаєш, Ісусе!', '', '', 'ua', NULL, 5, '2021-03-10', NULL),
(250, 258, 'Отець мій  Ти є мій світ', 0, 'Куплет1\nОтець Мій, я обожнюю\nТебе понад усе у світі, бажаю Тебе,\nІсусе мій, Спаситель любий.\nВсе, що маю, я віддам Тобі, віддам Тобі я все!\n\nКуплет 2\nВсі ангели Тебе підносять.\nІ ми вклоняємось Тобі!\n\nКуплет 3\nТи є мій світ, Ти є мій Бог.\nІ я віддам життя Тобі,\nГосподар мій, моя любов.\nВ серці моєму тільки Ти!\n\nКуплет 4\nУсе, що маю я віддам\nТобі, Господь мій, бо для Тебе,\nЖиву кожен день!\nВсі дні мої – дарунок Твій.\nЯк жити кожну мить, навчи мене,\nМолю я Тебе!\n\nКуплет 5\nВсі ангели Тебе підносять.\nІ ми вклоняємось Тобі!\n\nКуплет 6\nТи є мій світ, Ти є мій Бог.\nІ я віддам життя Тобі,\nГосподар мій, моя любов.\nВ серці моєму тільки Ти!', '', '', 'ua', NULL, 5, '2021-03-26', NULL),
(251, 259, 'Могутній Славний Цар', 0, 'Куплет 1\nМогутній, славний Цар,\nВеличний у красі.\nРадіє вся земля, радіє вся земля.\nУ Ньому світла блиск\nі темряви нема.\nА голос, наче грім, а голос, наче грім.\n\nПриспів\nВеличний наш Бог!  Заспівай:\nВеличний наш Бог!  Ти Прославляй!\nВеличний, Величний наш Бог.\n\nКуплет 2\nНезмінний у віках, і час в Його руках,\nПочаток і Кінець, початок і Кінець.\nОсоба в трьох один Отець, і Дух, і Син,\nВін є Ягня і Лев Він є Ягня і Лев\n\nКуплет 3\nІм’я твой понад усі\nВся хвала лише Тобі,\nзаспіваю знов : “Величний наш Бог”\nАлілуя…\n\nКуплет 4\nАлілуя…!!!\nНаш Бог цар!', '', '', 'ua', NULL, 3, '2021-03-07', NULL),
(252, 260, 'Одне тіло і один Дух', 30, 'Куплет 1\nОдне тіло і один Дух,\nУ любові братній ти, мій друг,\nЗбережемо єдність віри усі разом.\n\nПриспів\nОдин Господь, одна віра,\nІ хрещення одне для всіх.\n\nКуплет 2\nОдин Бог і Отець один,\nНа віки-віків - єдиний Він.\nПриклад нам єднання дав тобі і мені.', '', '', 'ua', NULL, 1, '2020-11-22', NULL),
(253, 261, 'Квітучий край де небо чисте', 30, 'Куплет 1\nКвітучий край, де небо чисте,\nДе сонце ясне, променисте,\nЛіси й озера, ниви і поля,\nБез краю степ і синє море,\nСтарий Дніпро, Карпатські гори\nЦе Україна, наша це земля.\n\nКуплет 2\nБлагослови, Господь, наш край\nВ молитві об\'єднай,\nСмирення і покори, Отче, дай!\nВ серця людей всели любов!\nТвій Син до нас зійшов,\nЩоб ми любили і прощали\nЗнов і знов.\n\nКуплет3\nНавчи, Господь, у мирі жити,\nБлагословляти і любити,\nУ єдності молитися разом.\nА тим, кому даєш Ти владу,\nДай, Боже, страх і дай пораду,\nЯк зло перемогти Твоїм добром.', '', '', 'ua', NULL, 0, NULL, NULL),
(254, 262, 'Хто є я Що Господь Творець Землі', 30, 'Куплет 1\nХто є я, Що Господь Творець Землі,\nНазвав ім’я моє І чув весь мій біль?\nХто є я, Що ранкова зоря\nОсяяла мій шлях, Промінь віри щоб не згас?\n\nКуплет 2\nНе тому, що вірю я,  А тому, що любиш Ти, \nІ тому, що всі гріхи  Ти забрав, аби спасти.\n\nКуплет 3\nЯ є квітка, що зів’яне Промине життя й не стане, \nЯк хвиля в океані,  Мов пара в вишині. \nАле чуєш, як покличу,  Коли падаю – підіймеш \nІ в обіймах пригорнеш.\nЯ – Твій. Я – Твій.\n\nКуплет 5\nХто є я, Що провини й тягарі \nГосподь і Бог Святий Забрав й навік простив? \nХто є я, Що могутній голос Твій \nКрізь бурі й дощі Дав мир душі моїй?\n\nКуплет 6\nНе тому, що вірю я,  А тому, що любиш Ти, \nІ тому, що всі гріхи  Ти забрав, аби спасти.\n\nКуплет 7\nЯ є квітка, що зів’яне Промине життя й не стане, \nЯк хвиля в океані,  Мов пара в вишині. \nАле чуєш, як покличу,  Коли падаю – підіймеш \nІ в обіймах пригорнеш.\nЯ – Твій. Я – Твій.', '', '', 'ua', NULL, 1, '2021-02-21', NULL),
(255, 263, 'Дай мне гореть Тобой', 0, 'Куплет 1\nДай мне гореть Тобой, сильнее, чем горел мечтой,\nСильнее, чем всякая страсть, что жжет меня изнутри.\nДай мне владеть собой, чтоб жизнь моя служила Тебе,\nБыла бы живою хвалою, что льется из глубины.\n\nПриспів\nХвалою Тебе, мой Бог, спасенье и надежда моя,\nМолюсь, чтобы моя глубина была бы Твоей глубиной.\nИз глубины живая вода, вода Твоей любви, как река,\nПусть льется, пробуждая от сна, сердца наполняя хвалой.\n\nКуплет 2\nДай мне идти вперед, оставив все кривые пути,\nИдти Твоею тропой, небесной тропой любви.\nПусть растает в серце лед, и спящая без неба душа,\nПусть станет горящей стрелой, летящей из глубины.\n\nКуплет 3\nСтрелою к Тебе, мой Бог, спасенье и надежда моя,\nМолюсь, чтобы моя глубина была бы Твоей глубиной.\nИз глубины живая вода, вода Твоей любви, как река,\nПусть льется, пробуждая от сна, сердца наполняя хвалой.', '', '', 'ua', NULL, 2, '2021-01-24', NULL),
(256, 264, 'Нічка та радісна зорями світила у Вифлиємі', 30, 'Куплет 1\nНічка та радісна зорями світила у Вифлиємі\nДіва Марія Сина народила в яслах на сіні.\n\nПриспів\nСлава Богу! Слава на висоті!\nНа землі мир, спокій,\nСлава вгорі, мир на землі,\nВ людях добра воля.\n\nКуплет 2\nВ сяйві великому пастухам у полі ангел з\'явився,\nВін сповістив, що в яслах на сіні, Христос родився\n\nКуплет 3\nМи також серцем до ясел припадімо, Христа вітаймо,\nЙому одному - Божому Святому, поклін віддаймо.', '', '', 'ua', NULL, 4, '2021-01-03', NULL),
(257, 265, 'Радуйтеся усі люди', 0, 'Куплет 1\nРадуйтеся усі люди,\nРадість з неба вам хай буде.\n\nПриспів: \nВеселая вам новина,\nНародила Діва Сина,  Марія! (Зр.)\n\nКуплет 2\nДо ясел всі поспішаймо,\nСлаву й честь Йому віддаймо.\n\nКуплет 3\nБудьмо щирі та багаті\nНа добро завжди завзяті.', '', '', 'ua', NULL, 0, NULL, NULL),
(258, 266, 'Ой над Віфлеємом зірка сіяла', 0, 'Куплет 1\nОй, над Віфлеємом зірка сіяла,\nТам Діва Марія Сина родила. \nВ пелени сповила, у яслах положила,\nЦе на світ родився Спаситель миру.\n\nКуплет 2\nВін на світ родився чоловіком, \nБув перше віта ней ангельським хором. \nАнгели співають, пастухи вітають,\nА три царі із Персії у вертеп спішать.\n\nКуплет 3\nЗ’явилась над ними ясна зоря,\nА в яслах на сіні - маленьке Дитя.\nЙосип і Марія над Ним вже сидять \nРучки простягає маленьке Дитя.\n\nКуплет 4\nЙосипові ангел у сні з’явився,\nЩоб з малим Дитятком він удалився \nУзяв Йосип Сина, ще й матір Його, \nУтікав в Єгипет від царя злого.\n\nКуплет 5\nА Ірод, злобний дуже розлютивсь,\nЩо Ісус Син Божий на світ народивсь. \nВійсько посилає у ту країну,\nСказав загубити малу Дитину.\n\nКуплет 6\nСказав Ірод війську - шукати Христа, \nДо двох літ рубати маленьких діток.\nЧотирнадцять тисяч маленьких діток \nБуло в Віфлеємі вбито у той час!\n\nКуплет 7\nГлянь, о Божий Сину, на дітей Своїх,\nТи Спаситель миру, Цар неба й землі.\nПішли нам із неба дар Твій превеликий,\nБудем Тебе славить по вічні віки!!!!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(259, 267, 'В минулі часи далекі часи в краю Палестині', 0, 'Куплет 1\nВ минулі часи, далекі часи в краю Палестині \nЗ’явилась зоря небесна вона, і сяє до нині.\nЦе світло для нас приніс любий Спас, і хто хоче взяти\nДаремно бери, то будеш і ти яскраво палати.\n\nКуплет 2\nВ Віфлеєм, В Віфлеєм поспішіть.\nПеред Спасом коліна схили\nНі дарів, ні скарбів Він не жде.\nСину, серце дай нині своє.\n\nКуплет 3\nВ блуканнях моїх нещасних доріг чимало пройшов я. \nТа щастя не мав, коли пропадав далеко від Бога.\nТа ясна зоря Ісуса Христа вказала дорогу, \nЩоб міг я прийти, спасіння знайти у Бога Святого.\n\nКуплет 4\nВ Віфлеєм, В Віфлеєм поспішіть.\nПеред Спасом коліна схиліть.\nНі дарів, ні скарбів Він не жде.\nСину, серце дай нині своє.\n\nКуплет 5\nСьогодні ще раз лунає для вас ця вістка чудова, \nБлаженство знайдеш, коли ти прийдеш до Бога Святого.\nТо ж, друже, спіши, скоріше прийми спасіння Христове.\nСьогодні прийди, одержиш і ти життя зовсім нове.\n\nКуплет 6\nДо Христа, до Христа поспішіть,\nПеред Спасом коліна схиліть.\nНі дарів, ні скарбів Він не жде -\nСину, серце дай Богу своє.', '', '', 'ua', NULL, 1, '2020-12-20', NULL),
(260, 268, 'Могутній славний Цар', 0, 'Куплет 1\nМогутній, славний Цар, Величний у красі,\nРадіє вся земля! Радіє вся земля!\nУ Ньому світла блиск, І темряви нема,\nА голос, наче грім, А голос, наче грім.\n\nПриспів:\nВеличний наш Бог! Заспівай: Величний наш Бог\nПрославляй! Величний, Величний наш Бог!\n\nКуплет2\nOnczas w swejdłonima, odwieków \nNawiekitrwa,początkiemkońcem On\nJedyny w Trójcy Bog, Ojciec, Syn i Duch\nBarankiemjest i lwem\n\nПриспів:\nJa kwielkij est Bóg.Spiewa jzemną wielki jest Bóg\nNiechwszyscyujrzajak, jakwielkijestBóg\n(Нєх вшисце уйжом як, як великі єст Буг)\n\nКуплет3\nCuan grande es Dios, cántale, cuan grande es Dios\ny todos loverán, cuan grande es Dios\nАлілуя! Алілуя! Алілуя, наш Бог – Цар!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(261, 269, 'Царь царей', 0, 'Куплет 1\nКруль крульов, Пан панов, Хвала, Алелуя\nЄзусксьонже покою, Хвала, Алелуя.\n\nКуплет 2\nЦарь царей, Господь Господ, Слава, Алилуя\nИисус наш Месия Слава Алилуя.\n\nКуплет 3\nRey de reyes, Señor de señores, gloria, aleluya\nCristo, Príncipe de paz, Gloria, Aleluya.', '', '', 'ua', NULL, 0, NULL, NULL),
(262, 270, 'Дай нам вяри', 0, 'Куплет 1\nЧи вистарчи нам вяри, чи надєї старчи нам\nЖе би Буг бил Богем живим і правдівим в каждим з нас\nПшетєш Он ствожив вшистко Христус умар то єстфакт\nЄго план юш шє випевнів Он з мартвих встав, жиє в нас.\n\nКуплет2\nДай нам вяри, дай отвагі,\nДай мілості, Духа дар.\nТи ш єсть Богем, Богем живим,\nТи ш вшехмоцний Велький Пан.', '', '', 'ua', NULL, 0, NULL, NULL),
(263, 271, 'Кожен з нас потребує співчуття і любові', 30, 'Куплет 1\nКожен з нас потребує, співчуття і любові\nІ милості завжди \nКожен з нас потребує прощення і надії\nЩо є в Ісусі\n\nПриспів\nБог наш зрушить навіть гори,\nВін є сильний спати, завжди сильний спасти.\nНавіки дарував спасіння, воскрес і смерть переміг\nСмерть Ісус переміг.\n\nКуплет 2\nЯ знайдений Тобою\nВізьми мене усього \nНаповни знов життям\nПрисвячую себе щоб врити твоєму слову\nЯ підкоряюсь. Підкоряюсь\n\nКуплет 3\nТвоє світло хай наповнить світ співаєм\nЦар воскреслий ми хвалу Тобі Ісус 2р.', '', '', 'ua', NULL, 2, '2021-01-31', NULL),
(264, 272, 'Поклонюсь Тебе Иисус', 0, 'Куплет 1\nПоклонюсь Тебе, Иисус,\nЯ всей душой и телом,\nВоспою Тебе, Иисус,\nЯ духом сердца своего,\nВеликий, Всемагущий,\nБог Великий, Всемогущий.\n\nКуплет 2\nТы прости меня, Господь,\nза все мои сомненья,\nВознеси меня, Господь,\nК вершинам Духа Твоего,\nВеликий, Всемагущий,\nБог Великий, люблю Тебя\n\nПриспів\n В своем серце\nХраню зает Твое крови,\nВ нвом серце\nГорит огонь Твоей любви', '', '', 'ua', NULL, 0, NULL, NULL),
(265, 273, 'Однажды Я поклялся хранить тебя', 30, 'Куплет 1\nОднажды Я поклялся хранить тебя,\nОднажды Я поклялся, солгу ли Я?\nГоры содрогнутся и сгорит земля,\nНо с тобою вечно будет милость Моя!\n\nПриспів\nЯ не человек, Я не предам тебя,\nЯ не брошу за порог во время дождя,\nКамень не подам вместо хлеба Я,\nЕсли слезы на глазах Я успокою тебя.\n\nКуплет 2\nЕсли раны кровоточат у Меня есть елей,\nДля израненного сердца, для души твоей.\nТолько на мгновенье Я оставил тебя -\nИспытать и переплпвить сред страданий и зла.\n\nКуплет 3\nЯ хочу,чтоб ты был сильный закаленный солдат,\nНе дражал перед врагами, пусть трепещет ад!!!!\nТы еще росправиш крыля и взлетишь высоко!!!!\nКто сказал, что побеждать так просто и легко???', '', '', 'ua', NULL, 0, NULL, NULL),
(266, 274, 'Я прагну тебе', 30, 'Куплет 1\nБільше ніж пісня моя\nБільше ніж гарні слова\nПонад усе я знайшов\nТвою незрівняну любов\n\nПриспів\nЯ прагну Тебе мій Ісус\nПрагну Тебе мій Бог\nЯ прагну Тебе Ісус\nЯ прагну Тебе…\n\nКуплет 2\nНе осягнуть до кінця\nЛюбов що прийшла від Отця\nНе заслужив я її\nА вона гріхи прощає мої\n\nКуплет 3\nТільки Твоя любов найбільша\nНічим не зрівняти її\nІ навіть якщо весь світ обшукати\nТакої як Твоя не знайти 2р.', '', '', 'ua', NULL, 4, '2021-04-05', NULL),
(267, 275, 'Хай буде Ім’я Бога благословенне', 0, 'Куплет 1\nХай буде Ім’я Бога благословенне,\nХай буде Ім’я Бога благословенне,\nВіднині і повік (2р.)\n\nКуплет 2\nІ від сходу сонця і до заходу дня\nХай буде Ім’я Бога благословенне\nВіднині і повік (2р.)\n\nКуплет 3\nСлава Йому!\nСлава Царю!\nБогу нашому!\nВічно Сущому! (2р.)\n\nКуплет 4\nХай буде Ім’я Бога благословенне,\nХай буде Ім’я Бога благословенне,\nВіднині і повік (2р.)\n\nКуплет 5\nНад народами всіма Ти Бог,\nХай буде Ім’я Бога благословенне\nВіднині і повік (2р.)\n\nКуплет 6\nСлава Йому!\nСлава Царю!\nБогу нашому!\nВічно Сущому! (2р.)', '', '', 'ua', NULL, 7, '2021-02-28', NULL),
(268, 278, 'Подивися навкруги на красу землі своєї', 30, 'Куплет 1\nПодивися навкруги, на красу землі своєї.\nВсе це Бог наш сотворив силою руки своєї.\nВін один так полюбив, що віддав нам свого Сина.\nМилість Бог свою явив, щоб спаслася Україна.\n\nПриспів:\nМи молим за свій край,\nСпасіння людям дай.\nМи Тебе благаєм.\n\nКуплет 2\nЛюбов свою яви,\nГосподь, благослови\nНашу Україну.\n\nКуплет 3\nБоже єдності нам дай, навчи любити і прощати.\nВ згоді Господа Христа будем разом прославляти.\nТи один так полюбив, що віддав нам свого Сина.\nМилість нам свою явив, щоб спаслася Україна.', '', '', 'ua', NULL, 0, NULL, NULL),
(269, 279, 'Эрусалим що сходить з неба', 0, 'Куплет 1\nЄрусалим, що сходить з неба\nВ проміннях ясних свого Царя,\nТам більше сонця вже не потрібно, \nБо Агнець Божий -  рання зоря.\n\nПрипев\nОце оселя свята Бога з людьми,\nДе будем жити із Богом ми.\nТам усі сльози Ісус з очей зітре.\nСмерті не буде, біль промине.\n\nКуплет 2\nЄрусалим! Нове це місто,\nПерлинні брами відкриті в нім.\nХто прагне пити - нехай приходить, -\nДжерельні води течуть у нім.\n\nКуплет3\nЄрусалим! Тебе кохаю.\nВ тобі панує вічна любов.\nСпасенні люди в тобі зійдуться.\nПрославлять Спаса за  Його кров.', '', '', 'ua', NULL, 0, NULL, NULL),
(270, 282, 'Иисус Ты мой хлеб', 30, 'Куплет 1\nИисус, Ты - мой хлеб, Иисус, Ты - мое вино,\nИисус, Ты - мой покой, моя радость и сила моя.\n\nКуплет 2\nИисус, Ты - мой путь, Иисус, Ты - мой свет,\nИисус, Ты - мой Господь, моя жизнь и надежда моя.', '', '', 'ua', NULL, 0, NULL, NULL),
(271, 283, 'Понад всю силу', 30, 'Куплет 1\nПонад всю силу, над всіх царів,\nПонад природу і все, що Бог створив,\nПонад всю мудрість і всі шляхи людські,\nІсус був тут до створення нас всіх.\n\nКуплет 2\nПонад всі царства, престоли всі,\nНад чудеса всі, що світ побачив їх,\nНад всі джерела і цінності землі\nНе вимірять творінь Його усіх.\n\nПриспів\nРозіп’ятим був, лежав в могилі Він,\nЩоб мертвий жив, за словом Він воскрес.\nЯк і всі ходив Він по землі,\nВін взяв наш гріх, Він нас звільнив.\nВін – над усе!\n\nКуплет 2\nТи вище влади всіх царів,\nВище природи, бо Сам її створив,\nНайвища мудрість, Господь, лише в Тобі,\nСловом Ти створив цей дивний світ.\n.                 .                    .\nНайбільша сила в Твоїх руках,\nУ краплях крові, що капали з хреста,\nВ простих словах, які залишив Ти,\nЩоб ми любили так, як любиш Ти.', '', '', 'ua', NULL, 7, '2021-04-09', NULL),
(272, 284, 'Чудное имя открылось нам люди', 30, 'Куплет 1\nО, благодать пришла с небес,\nКак сладок вкус любви.\nЯ благодатию воскрес,\nТеперь я вижу яркий свет надежды.\n\nКуплет 2\nАллилуйя! Благодать льется на меня опять,\nАллилуйя, ливнями Твоей любви, Твоей любви.\n\nКуплет 3\n О, благодать, Твой яркий свет\nПронзает тьму сердец,\nК Отцу влечет, дает ответ,\nО, благодать Христа, Ты- свет надежды.\n\nКуплет 4\nАллилуйя! Благодать льется на меня опять,\nАллилуйя, ливнями Твоей любви.\nАллилуйя! Благодать исцеляет сердце,\nАллилуйя, ливнями, ливнями Твоей любви.\n\nКуплет 5\nО, благодать, любви поток\nТечет с небес в меня.\nКак сладок благодати дар-\nДар веры и любви, Твоей надежды.', '', '', 'ua', NULL, 0, NULL, NULL),
(273, 285, 'О благодать пришла с небес', 0, 'Куплет 1\nО, благодать пришла с небес,\nКак сладок вкус любви.\nЯ благодатию воскрес,\nТеперь я вижу яркий свет надежды.\n\nКуплет 2\nАллилуйя! Благодать льется на меня опять,\nАллилуйя, ливнями Твоей любви, Твоей любви.\n\nКуплет 3\n О, благодать, Твой яркий свет\nПронзает тьму сердец,\nК Отцу влечет, дает ответ,\nО, благодать Христа, Ты- свет надежды.\n\nКуплет 4\nАллилуйя! Благодать льется на меня опять,\nАллилуйя, ливнями Твоей любви.\nАллилуйя! Благодать исцеляет сердце,\nАллилуйя, ливнями, ливнями Твоей любви.\n\nКуплет 5\nО, благодать, любви поток\nТечет с небес в меня.\nКак сладок благодати дар-\nДар веры и любви, Твоей надежды.\n\nКуплет 6\nАллилуйя! Благодать льется на меня опять,\nАллилуйя, ливнями Твоей любви.\nАллилуйя! Благодать исцеляет сердце,\nАллилуйя, ливнями, ливнями Твоей любви.', '', '', 'ua', NULL, 9, '2021-02-28', NULL),
(274, 286, 'Ти створив усе у світі', 0, 'Куплет 1\nТи створив усе у світі,\nІ сьогодні Твої діти славлять Тебе.\nКоли лице Твоє шукаю,\nТвій подих, Боже, відчуваю в своїй душі.\n\nКуплет 2\nЯ маю віру та й надію,\nТи дав життя нове та мрію – колись побачу Тебе.\nКоли в дорозі зупиняюсь,\nТебе молю, Тебе благаю: дай сили мені.\n\nПриспів\n Я славлю Господа, добрий бо Він,\nБо навіки є милість Його!\nСлавлю Господа, добрий бо Він,\nБо навіки є милість Його!\n\nКуплет 3\nЯ знаю істину і правду,\nТи зняв тягар з душі й кайдани смерті забрав.\nТепер з небес Тебе чекаю\nІ в свому серці прославляю Тебе, мій Господь!\n\nПриспів 2\nСлавте Господа, добрий бо Він,\nБо навіки є милість Його!\nСлавте Господа, добрий бо Він,\nБо навіки є милість Його!', '', '', 'ua', NULL, 8, '2021-04-07', NULL),
(275, 287, 'Милость Твоя Господь велика Иисус Тебе хвалу', 0, 'Куплет 1\nМилость Твоя, Господь, велика,\nОна – как в пустыне живая река,\nОна – как сияющий луч во тьме, и Ты явил ее мне.\nИ нет любви сильней, чем Твоя,\nВедь только она подняла меня,\nВедь только она разорвала круг боли, страданий и мук.\n\nПриспів\nИисус, Тебе хвалу я возношу,\nИисус, со мною будь всегда, Тебя прошу.\nИисус, я лишь Тебе принадлежу,\nИисус, Тебе служу!\n\nКуплет 3\nМилость Твоя, Господь, велика,\nОна – как в пустыне живая река,\nОна – как сияющий луч во тьме, и Ты явил ее мне.\nИ нет любви сильней, чем Твоя,\nВедь только она подняла меня,\nВедь только она разорвала круг боли, страданий и мук.', '', '', 'ua', NULL, 17, '2021-03-24', NULL),
(276, 289, 'До Твоїх ніг', 0, 'Куплет 1\nДо Твоїх ніг припаду я знов,\nПрости мене, помилуй.\nВ долонях рук тримай життя моє\nБо я вже Твій навіки.\n\nПриспів\n Ісусе, в Тебе вірую\nНа Тебе лиш надіюсь я.\nДля тебе лиш живу,\nВсім людям донесу\nЛюбов Твою.\n\nКуплет 2\nТепер іду шляхом Твоїм, Господь,\nКрізь сльози, біль, зневіру.\nІ вже живу з надією в душі,\nБо в Тебе я повірив.\n\nПриспів\nІсусе, в Тебе вірую\nНа Тебе лиш надіюсь я.\nДля тебе лиш живу,\nВсім людям донесу\nЛюбов Твою.\nПоклоняюсь.\nПоклоняюсь я.\n\nПриспів\nІсусе, в Тебе вірую\nНа Тебе лиш надіюсь я.\nДля тебе лиш живу,\nВсім людям донесу\nЛюбов Твою.', '', '', 'ua', NULL, 0, NULL, NULL),
(277, 292, 'Я хочу исполнить волю Твою', 0, 'Куплет 1\nЯ хочу исполнить волю Твою,\nПрошу окропи меня Своей кровью,\nЯ хочу увидеть славу Твою,\nНаполни меня Своей любовью.\n\nПриспів\nЯ без Тебя не знаю пути,\nКуда мне идти и как мне жить,\nПрошу научи меня любить, как любишь Ты.\n\nКуплет/ Бридж\nОчисти меня кровью Своей,\nНе дай мне сойти с Твоих путей.\nОчисти нас, очисти нас...!', '', '', 'ua', NULL, 3, '2021-01-03', NULL),
(278, 293, 'Я прошу тебе Ісусе', 30, 'Куплет 1\nЯ прошу тебе, Ісусе, не лишай мене в біді, \nБо душа на волю рветься у важкійтійсамоті. \nСерцекрається на двоє,біль і страх в меніживе. \nА Христос так промовляє: «Не журися, все мине».\n\nКуплет 2\n«Я візьму тебе на руки, понесу туди де Я. \nІ не буде вжерозлукибодитинати Моя».\n\nКуплет 3\nАле сумнівибувають, недовіращеживе, \nБіль і смутокпосилає - і обличчязновсумне. \nСльозикотятьсярікою і в душіще все пече, \nА Христос так промовляє: «Не журися, все мине».', '', '', 'ua', NULL, 0, NULL, NULL),
(279, 294, 'Я прошу тебе', 0, 'Куплет 1\nЯ прошу тебе, Ісусе, не лишай мене в біді, \nБо душа на волю рветься у важкійтійсамоті. \nСерцекрається на двоє,біль і страх в меніживе. \nА Христос так промовляє: «Не журися, все мине».\n\nКуплет 2\n«Я візьму тебе на руки, понесу туди де Я. \nІ не буде вжерозлукибодитинати Моя».\n\nКуплет 3\nАле сумнівибувають, недовіращеживе, \nБіль і смутокпосилає - і обличчязновсумне. \nСльозикотятьсярікою і в душіще все пече, \nА Христос так промовляє: «Не журися, все мине».', '', '', 'ua', NULL, 0, NULL, NULL),
(280, 295, 'Боже мій Ти Святий Милість Свою нам яви', 0, 'Куплет 1\nБоже мій, Ти Святий! Милість Свою нам яви!\nБоже мій, на Тебе надія моя.\nБоже мій, до Тебе прагне душа.\nБоже мій, вкажи мені праведний шлях!\nБоже мій, Тобі віддаю все життя!\n\nКуплет 2\nПрости мені, Боже, гріхи і образи\nПробач мені, Батьку, невірність мою.\nНа Хрест віддаю мою біль і хвороби\nВ Ім’я Ісуса, Тебе я молю!', '', '', 'ua', NULL, 0, NULL, NULL),
(281, 296, 'Возрадуйтесь же люди Христос воскрес воскрес', 0, 'Куплет 1\nВозрадуйтесь же люди, Христос воскрес, воскрес! \nЛетит пусть эта песня до самых до небес. \nЕё живые звуки звучат и там и здесь \nЛикуйте вместе с нами, Христос воскрес!!\n\nПриспів\nАрфы золотые не смолкнут, нет \nОн восстал из мрака, явил нам свет. \nНашего спасенья зажёг звезду \nСлава, аллилуйя, хвала Христу!!!\n\nКуплет 2\nВ борьбе со мраком ада Он вышел, победил \nГреховные преграды Христос наш сокрушил. \nЗарёю воскресенья мир грешный озарён, \nХристу благодаренье и наш поклон!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(282, 297, 'Окружи меня Дух Святой', 0, 'Куплет 1\nОкружи меня, Дух Святой,\nОкружи меня, Дух Святой!\nПодними меня, подними\nНад землёй, над землёй, над землёй!\n\nКуплет 2\nПрикоснись ко мне, Дух Святой,\nПрикоснись ко мне, Дух Святой!\nПодними меня, подними\nНад землёй, над землёй, над землёй!\n\nПрипев\nЛишь в ладонях Твоих ощущаю любовь,\nЛишь в ладонях Твоих ощущаю тепло,\nЛюбимый Отец, любимый Отец!\n\nКуплет 3\nПрикоснись ко мне, Дух Святой,\nПрикоснись ко мне, Дух Святой!\nПодними меня, подними\nНад землёй, над землёй, над землёй!\n\nКуплет 4\nОбними меня, Дух Святой,\nОбними меня, Дух Святой!\nПодними меня, подними\nНад землёй, над землёй, над землёй!', '', '', 'ua', NULL, 5, '2021-03-17', NULL),
(283, 298, 'Ему имя Чудный', 0, 'Куплет 1\nЕму имя: Чудный (2р), Вечный и Святой\nВ день великий, судный, в день великий, судный\nБудет Он Судьей.\n\nКуплет 2\nЕму имя: Славный(2р) Образ Божества,\nЦарь небес державный, Царь небес державный,\nАнгелов Глава.\n\nКуплет 3\nЕму имя: Слово (2р), Слово - Вечный Бог,\nБез Его покрова, Без Его покрова\nМир бы жить не смог.\n\nКуплет 4\nЕму имя: Верный (2р), Вождь, мудрец, пророк.\nОн в любви безмерной, Он в любви безмерной\nНас из тьмы извлек.\n\nКуплет 5\nЕму имя: Нежный (2р), Пастырь Божьих стад,\nОкеан безбрежный, океан безбрежный\nМилостей, отрад.\n\nКуплет 6\nОн – Первосвященник (2р), Мощный и благой,\nГрешный мира пленник, грешный мира пленник\nВ Нем нашел покой.\n\nКуплет 7\nЕму имя: Чудный, Ему имя: Нежный,\nЕму имя: Славный, Ему имя: Верный.\nЕму имя: Чудный, Ему имя: Нежный,\nЕму имя: Славный и Святой', '', '', 'ua', NULL, 0, NULL, NULL),
(284, 299, 'Лиш поглянь ти навкруги', 30, 'Куплет 1\nЛиш поглянь ти навкруги, як чудово все створив\nТой, хто любить нас усіх, хто помер за грішний світ.\nЛиш поглянь, яка краса, місяць, зорі, ти і я\nЦе творіння лиш Його, тож прославимо Його.\n\nПриспів\nЧудовий Бог, Величний Бог життя подарував\nПрекрасний Бог і Славний Бог!\nЧудовий Бог, Величний Бог життя подарував.\nЧи ти Подякував?\n\nКуплет 2\nТож давай співать разом про величність і Його любов\nСерце ти своє відкрий в нього ввійде Дух Святий.\nЗнов давай підем туди, де знайшли спокій душі,\nДе лилася кров свята, там біля хреста.\n\nКуплет 3\nЧи ти Подякував?', '', '', 'ua', NULL, 6, '2021-03-05', NULL),
(285, 300, 'Прославити я хочу', 30, 'Куплет 1\nПрославити я хочу,Господа Христа\nЗа всі Його творіння,за всі Його діла.\nХвали і поклоніння наповнена земля,\nЯк подивлюсь на небо Йому співаю я:\n\nПрипев     \nВсемогутній,Бог Всесильний!\n Тобі немає рівних,Тобі нема подібних.\n\nКуплет2\nДо нас зійшов з небес,так полюбив світ весь\nНа хрест себе віддав,щоб кожен життя мав\nДо Нього хто приходить, Він не відганяє\nГріхи усі прощає,Духом Святим наповняє.\n\nКуплет3\nСлово Твоє правда,істина і шлях\nНемає більше Бога більшого як наш!!!\n\nПрипев\nВсемогутній, Всесильний,\nНезрівнянний, Ти - Бог Славний!\nСлава, Слава! Алілуя! Осанна!', '', '', 'ua', NULL, 0, NULL, NULL),
(286, 303, 'Скажи мені слово', 0, 'Куплет 1\nСкажи мені слово, потіхи й любові,\nІ ніжно торкнися, моєї душі,\nЩоб знову дзвеніли прекрасні і нові,\nМелодії неба в ранковій тиші.\n\nПриспів\nПовій Святим Духом у спрагнене серце,\nВтомилось воно у земній боротьбі.\nМов ніжне проміння, що кидає сонце.\nЗігрій мою душу ти Духом Святим!!!\n\nКуплет 2\nЛиш тільки в Тобі мій Господь і Спаситель\nЗнаходить душа моя мир і спокій,\nКоли знемагаю до Тебе Утішитель,\nПрихожу з благанням моєї душі.\n\nКуплет 3\nНехай же присутність Твоя зігріває,\nНехай в твоїм серці лунають пісні,\nІ слава й подяка Тобі не змовкає,\nБо Ти є зі мною, бо Ти є в мені...', '', '', 'ua', NULL, 3, '2020-12-06', NULL),
(287, 304, 'Іди до мене', 30, 'Куплет 1\nІди до Мене, коли біль в душі, коли хвороба зла.\nІди до Мене, коли не взмозі зносити страждання.\nКоли ніхто не зрозумів журбу твою,\nКоли нема з ким розділити самоту.\n\nПриспів\nЯ дам душі твоїй\nТепло, мир і спокій,\nДо Мене ти прийди,\nЯ, Я Твій Бог Святий,\nЯ захист вірний твій\nДо Мене ти прийди.\n\nКуплет 2\nІди до Мене, коли в серці страх і скрізь тепла нема,\nІди до Мене, коли сіре все і сонце не сіяє,\nКоли здається, що погасли зорі всі,\nКоли ти прагнеш, щоб любов Я дав тобі.\n\nКуплет3\nІди до мене, коли промінь щастя золотом не сяє,\nІди до мене, коли тільки сум і радості немає,\nКоли не в змозі ближнього свого любить,\nКоли твоя молитва в небо не летить', '', '', 'ua', NULL, 1, '2021-01-24', NULL),
(288, 305, 'Cristo es la peña de Horeb', 0, 'Куплет 1\nCristo es la peña de Horeb q\'está brotando\nagua de vida saludable para ti\nCristo es la peña de Horeb q\'está brotando\nagua de vida saludable para ti\n\nПриспів\nVen a tomarla que más dulce que la miel\nrefresca el alma, refresca todo tu ser\nCristo es la peña de Horeb q\'está brotando\nagua de vida saludable para ti\n\nКуплет 2\nCristo es el lirio del valle de las flores\nEl es la Rosa blanca y pura de Sarón\nCristo es la vida y amor de los amores\nEl es la eterna fuente de la salvación\n\nПриспів\nVen a buscarla en tu triste condición\nrefresca el alma, refresca todo tu ser\nCristo es la vida y amor de los amores\nEl es la eterna fuente de la salvación', '', '', 'ua', NULL, 0, NULL, NULL),
(289, 306, 'Великий Всесильний Бог', 0, 'Куплет 1\nВеликий, Всесильний Бог!\nЩо небо і землю створив.\nНа землю із неба зійшов,\nЩоб, хто вірує в Нього вічно жив.\n\nКуплет 2\nНе був його шлях легким,\nТа Духом водимий Він\nВ єднанні з Отцем своїм\nПустиню пройшов, хоч в стражданнях знеміг,\nколи кликав до Бога:\"Чому мене залишив?\"\n\nКуплет 3\nВеликий Бог, Всесильний Бог!\nДо нас із неба зійшов,\nТяжкий шлях пройшов\nНам явив свою любов!\n\nКуплет 4\nПо дорозі земній, суєтній\nНам здається бува нема сил\nІ питаєш : \"Чому, що і як?\"\nНе відомі шляхи Божі нам.\n\nКуплет 5\nТа крізь сивий і темний туман\nГолос Божий звучить :\"Ти не сам!.\nЗір до неба здійми,\nКроком віри ступи, і по хвилях підеш,\nСправжню радість знайдеш і прославиш мене\".\n\nКуплет6\nВеликий Бог, Всесильний Бог!\nТобі вклоняється все,\nВсе хвалу віддає,\nТи - достойний, Святий Бог.', '', '', 'ua', NULL, 0, NULL, NULL),
(290, 307, 'Вся земля хвалу поёт', 0, 'Куплет 1\nВся земля хвалу поёт,\nЛиш Тебе наш чудный Бог.\nИ во всей Вселенной нет!\nКто б с Тобой сравнится смог.\nТы превосходнее всего на свете!\nИ нет подобного Тебе.\nТы - наш Господь, Ты царствуешь вовеки.\nПревознесем Тебя в хвале!\n\nПриспів\nНебеса Тебе поют: Святый - Святый!\nВся земля Тебе поёт достоин Ты!\nВсе творенье воздаёт Тебе хвалу, Господь!\nБлагословен наш Бог - Творец всего!!!\n\nКуплет 2\nОт престола Твоего, течет поток живой воды!\nДля народа всей земли сияет свет Твоей любви.\nСвоим присутствием покрой всю землю,\nПусть свет прольётся в жизнь людей.\nВсе народы преклонят колени и воспоют хвалу Тебе.', '', '', 'ua', NULL, 10, '2021-04-07', NULL),
(291, 308, 'Все награды и Ты достоин', 30, 'Куплет 1\n Все награды и венцы свои отдам,\n Все заслуги и хвалу кладу я пред Тобой,\n Ведь подобного Тебе не видел мир\nЛишь Ты один достоин, Ты один достоин.\n\nПриспів\nТы достоин, о Бог, высшей славы\nТы достойный, Бог, принять всю честь!\nЯ живу для Тебя, и всем, что есть внутри меня.\nПоклоняюсь я! \n\nКуплет 2\nБлизок Ты ко всем, кто Имя Твое чтит,\nВечно щедрый, вечно любящий, всё тот же Ты\nИ за то, что жизнь мою насытил Ты,\nВоздам Тебе всю славу! воздам Тебе всю славу!\n\nКуплет 3 Мост\nПоклоняюсь я! Чту Тебя!\nСлавлю я Тебя, мой Бог!!', '', '', 'ua', NULL, 4, '2021-03-15', NULL),
(292, 309, 'Каждый день Я буду славить Господа', 0, 'Куплет 1\nКаждый день на устах моих\nЭто славное Имя Иисус.\nЯ не знаю имён других,\nЛишь Его я превозношу!\n\nКуплет1\nМоё сердце поёт о Нём\nО Спасителе дивном моём,\nТолько Он мне даёт покой,\nЕго Имя всегда со мной!\n\nПриспівЯ\nЯ буду славить Господа Христа,\nЯ буду помнить все Его дела,\nЯ буду петь Ему:  Аллилуя , Аллилуя .\n\nКуплет 2\nИ когда солнца свет горит, \nСогревая всю землю теплом, \nВ моем сердце опять звучит\nИисусу Царю псалом.', '', '', 'ua', NULL, 3, '2020-10-25', NULL),
(293, 310, 'Мы поём Тебе славу', 0, 'Куплет 1\nМы поём Тебе славу\nМы поеи Тебе честь\nАллилуйя поём Тебе\nЗа все то Кто Тыесть\n\nПриспів\nМы поем Тебе Святый Бог\nМы поем Тебе Святый Бог\nМы поем Тебе Святый Бог\nСвятый наш Господь\n\nКуплет 2\nМы поём Тебе ночью\nМы поём Тебе днем\nРанним утром поём Тебе\nВместе с первым лучем\n\nКуплет 3\nМы стоим пред Тобой Иисус\nСердце полно хвалы\nЗа любовь Твою и за кровь\nЕй оправданы мы', '', '', 'ua', NULL, 0, NULL, NULL),
(294, 311, 'Все от Него и Им сотворено', 0, 'Куплет 1\nВсе от Него и Им сотворено 2р.\n\nПриспів\nЕму за все слава 3р.\nВо веки аминь\n\nКуплет 2\nО бездну богатства, премудрости Христа\nНепостижимы судьбы Господа.', '', '', 'ua', NULL, 0, NULL, NULL),
(295, 312, 'Eres mi respirar', 0, 'Куплет 1\nEres mi respirar 2p\nDios Tu presencia vive en mi\nEres mi Pan Señor 2p.\nDios Tus palabras viven en mi\n\nПриспів\nY yo te anhelo Señor\nEstoy perdido sin Ti\n\nКуплет 2\nEres mi respirar 2p\nDios Tu presencia vive en mi\nEres mi Pan Señor 2p.\nDios Tus palabras viven en mi', '', '', 'ua', NULL, 0, NULL, NULL),
(296, 313, 'Отче наш що є на небесах', 30, 'Куплет 1\nОтче наш, що є на небесах\nХай святиться Ім’я Твоє .\nМоє життя тримаєш в Своїх руках\nВсесвіт весь на долонях Твоїх.\n\nКуплет 2\nТайне бажання в серці Своїм Ти сховав\nХто побачить біль Твою за Вселену всю?\nКайдани аду розірвав , викуп смертю заплатив\nЦарства Твого час настав, Царство Твоє прийшло!\n\nКуплет 3\nХай буде воля Твоя, хай буде слава Твоя!\nХай буде сила Твоя на землі людей.\nЯ - Твої руки, Господь, я – Твої ноги, Господь,\nГолосом буду Твоїм, щоби царство Твоє прийшло!\n\nКуплет 4\nГолос Свій підіймав за людей усіх\nСвіту гріх на Собі Він поніс.\nНе змовчу, про любов Твою розкажу.\nВіддаю Тобі, Боже, хвалу!\n\nКуплет 5\nТайне бажання в серці Своїм Ти сховав\nХто побачить біль Твою за Вселену всю?\nКайдани аду розірвав , викуп смертю заплатив\nЦарства Твого час настав, Царство Твоє прийшло!\n\nКуплет 6\nХай буде воля Твоя, хай буде слава Твоя!\nХай буде сила Твоя на землі людей.\nЯ - Твої руки, Господь, я – Твої ноги, Господь,\nГолосом буду Твоїм, щоби царство Твоє прийшло!\n\nКуплет 5\nПоможе, бути дитям Твоїм, Господь,\nДля мене Ти - дорожчий всього.\nЯ живу, щоб виконати волю Твою\nХай буде царство Твоє!\n\nКуплет 6\nТайне бажання в серці Своїм Ти сховав\nХто побачить біль Твою за Вселену всю?\nКайдани аду розірвав , викуп смертю заплатив\nЦарства Твого час настав, Царство Твоє прийшло!\n\nКуплет 7\nХай буде воля Твоя, хай буде слава Твоя!\nХай буде сила Твоя на землі людей.\nЯ - Твої руки, Господь, я – Твої ноги, Господь,\nГолосом буду Твоїм, щоби царство Твоє прийшло!', '', '', 'ua', NULL, 6, '2021-03-21', NULL),
(297, 314, 'Спрагненому воду Ти даєш', 30, 'Куплет 1\nСпрагненому воду Ти даєш\nГолодному хліба Ти даєш \nВ спеку прохолоду Ти даєш\nВтомленому силу Ти даєш.\n\nПрипев: \nІсус є хліб життя,Ісус жива вода,\nІсус в Тобі є зміст мого життя.\nБез Тебе не життя,обман і пустота,\nВ Тобі є правда вся.\n\nКуплет 2\nШляхи бувають різні, гори і поля,\nЗелені трав’янисті чи як суха земля.\nЗрошені дощами, чи у спекоті дня\nХристос завжди є з нами,Йому звучить хвала!!!\n\nКуплет 3\nРука Твоя тримає,любов Твоя прощає,\nДає нове життя!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(298, 315, 'Народила Діва Сина', 30, 'Куплет 1\nНародила Діва Сина, Вічний Бог у світ прийшов\nВ бідних яслах спить Дитина, Неба Дар Отця любов.\nБог нам в милості явився, це є чудо із чудес\nУ хліву нам народився Той, Хто Всесвіту Творець\n\nКуплет 2\nІз небес любов спустилась, щоб ходити по воді.\nЩоб зцілить, благословити, дати спокій для душі\nХай хвала Отцю лунає, мудрість в Сині нам відкрив\nНас сьогодні закликає Той, Хто милість нам явив\n\nПриспів\nАлілуя! Алілуя! Алілуя!\nСлава в вишніх, людям мир!\n\nКуплет 3\nВін поніс тяжкі страждання, Він поніс вину мою\nВін за нас терпів знущання, дав нам праведність Свою\nХай хвала Йому несеться залюбив і благодать,\nХай ввійде Він в кожне серце, щоб могло воно співать\n\nКуплет 4\nХай хвала Йому несеться за любов і благодать,\nХай Ввійде Він в кожне серце, щоб могло воно співать\n\nПриспів\nАлілуя! Алілуя! Алілуя!\nСлава в вишніх, людям мир!', '', '', 'ua', NULL, 1, '2020-12-20', NULL),
(299, 316, 'В ніч святу Спаситель народивсь', 30, 'Куплет 1\nВ ніч святу Спаситель народивсь,\nВід співу ангелів прокинувсь світ,\nПриніс Спаситель мир на землю нам,\nІ вилив благодать в людські серця.\n\nПриспів\nРодився нам,\nРодився нам,\nРодився нам,Спаситель.\n\nКуплет 2\nДо Ісуса пастухи прийшли, \nСлаву в вишніх Богу принесли,\nЗа зорею мудреці ідуть,\nЛадан , миро й золото несуть.\n\nКуплет 3\nПрийдемо до Спасителя і ми,\n І принесемо в дар серця свої,\nМиром і теплом наповнить Він, \nРадість і любов ввійде в твій дім.', '', '', 'ua', NULL, 0, NULL, NULL),
(300, 317, 'Небесний Цар прийшов на цю землю', 0, 'Куплет 1\nНебесний Цар прийшов на цю землю. \nБатьківську волю приняв смирено, став як один з нас.\n\nКуплет 2\nІсус залишив ангелів хори.\nСлаву Отця й небесної трони.\nЩоб на землі померти за грішний люд.\n\nКуплет 3\nЯкий же цар свою славу залишив?\nЯкий же пан тіло смертне приняв?\nХто із великих став и слугою всіх?\nЯкий же цар вє серце відкрив би,\nЩоб полюбити цей світ, що у злі?\nЯкий же батько сина віддав за всіх?\n\nКуплет 4\nСкладем подяку Богу Цареві\nГосподь панує на землі і на небі\nВін є достоєн\nКуплет 5\nВмер на хресті за наше спасіння\nСмерть подалав Своїм воскресінням\nЩоб примирити з Богом весь грішний люд\n\nКуплет 6\nТільки Ісус Свою славу залишив\nТільки Ісус тіло смертне прийняв\nТільки Христос слугою зробивсь для нас\nТільки Господь Своє серце відкрив\nЩоб полюбити цей світ, що у злі\nНебесний Батько Сина віддав за всіх (2 р.)\n\nVerse\nТільки Один, тільки Один...', '', '', 'ua', NULL, 1, '2021-04-04', NULL),
(301, 318, 'Oh deja', 0, 'Куплет 1\nOh, deja que El Señor se mueva, con su Espíritu de amor,\nSatisfazca hoy tu alma y corazón.\nEntregalé lo que te pide, y su Espíritu vendrá,\nSobre ti y vida nueva te dará.\n\nПриспів\nCristo, oh Cristo,ven y llénanos.\nCristo, Cristo, llénanos más de Ti !\n\nКуплет 2\nAlzamos nuesra voz con gozo, nustra alavanza a Ti,\nCon dulzura te entregamos nuestro ser.\nEntrega toda tu tristeza en el nombre de Jesús,\nY abundante vida tendras en Él.', '', '', 'ua', NULL, 1, '2020-12-20', NULL),
(302, 319, 'графік', 0, 'Куплет 1\nПн. - 12:00 Зібрання Різдвяне\nСр. - 21:00 Зібрання Молитовне.\nПт. - 19:00 .\nНд. - 10:00 Євангелізація на\" Aluche\"\n11:00 Молитва в класі\n12:00 Загальне Зібрання.\n!!! !!! !!!', '', '', 'ua', NULL, 0, NULL, NULL),
(303, 320, 'Щастя радості', 0, 'Куплет 1\nЩастя, радості, добра,\nМиру, любові на все життя.\nХай Господь береже,\nІ Своїм шляхом у небо веде\nЛише з Ним, Богом Святим - співає душа!!\n\nКуплет 2\nРазом ми дім, одна сім´я,\nЦерква Ісуса, Господа.\nБлагословляємо вас,\nПрийміть вітання щирі від нас.\nЗ днем народження!!\n\nКуплет 3\nЗ Днем \nНародження!!!', '', '', 'ua', NULL, 38, '2021-03-28', NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(304, 321, 'Naviad Navidad Славте всі славте всі', 30, 'Куплет 1\nNaviad, Navidad,\n  Hoy es Navidad. \nCon campanas este día\n  Hay que festejar.\nNavidad, Navidad,\n  Porque ya nació\nAyer noche, Nochebuena\n  El niñito Dios.\n\nКуплет 2\nСлавте всі, славте всі,\nСлавте всі Царя.\nНебо все і вся земля,\nСпівають для Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(305, 322, 'Як славний наш Господь в Сіоні', 0, 'Куплет 1\nЯк сусм ы мука мою душу огорне,\nДай сили славити, Господь, Тебе!\nМаю надыю що крызь бурі проведеш,\nІ буду славити, Ісус Тебе!\n\nПриспів\nТи пастир мій і світло моє,\nІ голос твій голос оживляє.\nЯк хочу я почути: Війди!\nВійди, Мій раб, у ворота\n\nКуплет 2\n --тут слова другого куплету', '', '', 'ua', NULL, 0, NULL, NULL),
(306, 323, 'Як сум і мука', 0, 'Куплет 1\nЯк сум і мука мою душу огорне,\nДай сили славити, Господь, Тебе!\nМаю надію, що скрізь бурі проведеш,\nІ буду славити, Ісус, Тебе!\n\nПриспів\nТи - Пастир мій і світло моє.\nІ голос Твій серце оживляє.\nЯк хочу я почути: Ввійди!\nВвійди, Мій раб, у ворота раю!\n\nКуплет 2\nЯкщо мене, Ти через хвилі проведеш,\nВірю, Спасителю, Ти доведеш!\nЧерез скорботи ми зростаємо в Христі,\nДай сили дякувати всякчас Тобі.\n\nКуплет 3\nТи - Пастир Добрий, Заступник, Господь,\nТи - світло для світу й богонь,\nТи знову прийдеш, Ти був і Ти є, Гряди!!', '', '', 'ua', NULL, 6, '2021-03-21', NULL),
(307, 324, 'Через гори й долини Бог вів мудреців', 30, 'Куплет 1\nЧерез гори й долини Бог вів мудреців,\nЙ вночі їм світила зоря.\nІ радості вогник в серцях їх горів,\nБо вела їх прекрасна зоря.\n\nПриспів\nОсь нова зоря нам на небі зійшла,\nВ серце принесла світлу радість!\nОсь нова зоря нам на небі зійшла,\nВічну радість вона принесла!\n\nКуплет 2\nВсім зоря зійшла, та за нею не йшли\nВона їм була як і всі.\nТа вірили серцем ці три мудреці \nДоведе зоря в оселі святі.\n\nКуплет 3\nЗоря Христа Царя!!!', '', '', 'ua', NULL, 2, '2021-01-03', NULL),
(308, 325, 'Mira al cielo estan adorando', 0, 'Куплет 1\nMira al cielo estan adorando,\nY celebrando la navidad.\nPaz y amor los ángeles cantan y felicidad!\n\nКуплет 2\nQue gran noticia nació Jesús,\nSe hizo pobre y fué a la cruz.\nVin para salvarnos, narnos vida y luz!\n\nПриспів\n --тут слова приспіву', '', '', 'ua', NULL, 0, NULL, NULL),
(309, 326, 'Земле радій Христос прийшов', 0, 'Куплет 1\nЗемле радій - Христос прийшов! \nПрийми Царя царів! \nЩоб в серці твоїм, Він місце знайшов, \nщоб став життям твоїм, \nщоб став життям твоїм, \nщоб став життям твоїм.\n\nКуплет 2\n Нам Він приніс спасіння всім,  \nЙого прославте всі \nЗа радість, любов, Пролитую кров, \nщо змила гріх з душі,\nщо змила гріх з душі,\nщо змила гріх з душі.\n\nКуплет 3\nЛюди, радійте, Спас царить!  \nСпівайте Йому всі! \nВсім людям Христос Спасіння дає \nі щастя для душі, \nі щастя для душі, \nі щастя для душі.', '', '', 'ua', NULL, 0, NULL, NULL),
(310, 327, 'Графік 2', 0, 'Куплет 1\nПн - 21:00 Навчання.\nСр - 21:00 Навчання.\nЧт – 21:00 Навчання.\nПт - 21:00 Навчання.\nНд - 10:00  Євангелізація на \" Aluche \".\n        11:00  Молитва в класі.\n        12:00  Загальне Зібрання.\n!!!             !!!                !!!\nПісля зібрання: обід\nза добровільні Пожертвування(2євро).', '', '', 'ua', NULL, 0, NULL, NULL),
(311, 329, 'Feliz Navidad', 0, 'Куплет 1\nFeliz Navidad\nProspero año y felicidad!!!\n\nКуплет 2\nРадій і співай.\nХриста Спаситиля  ти прославляй!!!\n\nКуплет3\nМи вас вітаєм з Різдвом Христовим!\nНам Бог спасилиля дав.\nХай Рік для вас буде Щасливим!\nЗа все Ісуса прослав!\n\nКуплет4\nЛюбові, Миру, довготерпіння,\nЖивого в Церві завжди служіння!\nІ Божого Всім благословіння,\nВaм бажаєм в чей святкоий час.\n\nКуплет5', '', '', 'ua', NULL, 0, NULL, NULL),
(312, 330, 'Твоя любов як світле почуття', 30, 'Куплет 1\nТвоя любов, як світле почуття\nЗвільнила від оков, дала нове життя.\nТвоя любов, як та жива ріка\nЗаповнила усе існування моє.\n\nПриспів\nІсус, Ти мій Господь,\nТобі вірю я, довіряю я.\nІсус, Ти моя любов,\nТи жива вода, Ти любов свята!!!\n\nКуплет 2\nТвоя любов відкрила для мене,\nСвіт щастя і тепла, які Бог подав.\nТвоя любов розповіла мені,\nЯк мене відкупили Твої руки святі.', '', '', 'ua', NULL, 0, NULL, NULL),
(313, 331, 'Великий Бог в Твоё присутствие хотим', 30, 'Куплет 1\nВеликий Бог, в Твое присутствие хотим!\nВеликий Бог, перед Тобою мы стоим!\nВеликий Бог, и простираем руки наши в небеса!\nМы жаждем...\n\nКуплет 2\nВеликий Бог, поставь печать в наших серцах\nРукой Своей, хотим напиться живой воды Твоей ...\nМы жаждем,...  мы жаждем...  Тебя!\n\nПриспів\nПревозносим, поклоняемся Тебе,\nМы превозносим, поклоняемся Тебе.\nМы превозносим, Славим Имя Твоё Господь!\nПревыше небес!!!\n\nКуплет 3\nВеликий Бог, безмерною любовью возлюбивший нас!\nСвоей великой жертвой вдохновивший нас! .\nМы жаждем ...\nВеликий Бог! Поставь печать в наших серцах рукой Своей,\nХотим  напиться живой воды Твоей.\nМы жаждем,...  мы жаждем...  Тебя!\n\nПриспів2\nМы превозносим Тебя!\nМы превозносим Тебя!\nСвятой Господь!', '', '', 'ua', NULL, 3, '2021-03-07', NULL),
(314, 332, 'Боже Боже Я Тобою живу', 30, 'Куплет 1\nБоже, Боже, знаю що Ти є\nТвою милість завжди відчуваю.\nМій хранитель, Ти  - життя моє\nУ твою любов я поринаю.\n\nПриспів\nЯ Тобою живу, я радію Тобою,\nНавіть коли біль на душі\nТи поруч зі мною/2 рази\n\nКуплет 2\nБоже, Боже, знаю, що Ти є\nКожну зірку Ти створив на небі,\nМоє сердце, що у  грудях б\'є\nСтворене, щоб вірити у Тебе', '', '', 'ua', NULL, 1, '2021-02-26', NULL),
(315, 333, 'Господь Ты мой Бог', 30, 'Куплет 1\nГосподь - Ты мой Бог! Тебя,\nОт ранней зари ищу я,\nИ жаждет Тебя душа моя!\nГосподь - Ты мой Бог! Тебя,\nОт ранней зари ищу я,\nИ жаждет Тебя душа моя!\n\nПриспів\nПо Тебе томится плоть моя.\nВ земле пустой, иссохшей,\nЧтобы видеть силу и славу Твою,\nИбо милость Твоя\nЛучше, нежели жизнь.\n\nКуплет 2\nУста мои возвестят \nХвалу Твою, Хвалу Твою, \nБлагословлю Тебя в жизни моей,\nВо Имя Твое руки вознесу.\n\nКуплет3\nКак елеем, насищается\nДуша моя,душа моя,\nИ радостным светом наполнят.', '', '', 'ua', NULL, 0, NULL, NULL),
(316, 1000, 'Aunque mis ojos no te puedan ver', 33, 'Куплет 1\nAunque mis ojos, no te puedan ver\nTe puedo sentir, se que estas aquí!\nAun que mis manos, no puedan tocar\nTú rostro Señor, se que estas aquí!\n\nПриспів1\nMi corazón puede sentir Tú presencia.\nTú estas aquí,Tú estas aquí,\nPuedo sentir Tu majestad.\nTú estas aquí,Tú estas aquí!!!\n\nКуплет 2\nMi corazón puede mirar Tú hermosura.\nTú estas aquí,Tú estas aquí,\nPuedo sentir Tu gran amor.\nTú estas aquí,Tú estas aquí!!!', '', 'ЛЯ минор', 'ua', NULL, 0, NULL, NULL),
(317, 1001, 'Потрібно вісім спасіння', 33, 'Куплет 1\nПотрібно  вісім спасіння,\nЛюбов Ця безкінечна і благодать Твоя.\nПотрібно всім прощення,\nСпасител, і надія.\n\nПриспів\nНадія світуСпасител може рушить гори\nМій Бог є сильний спасти,\nВін є сильний спасти,\nНавіки дарував спасіння,\nвоскрес і смерть переміг,\nСмерть Ісус переміг,\nСмерть Він переміг.\n\nКуплет 2', '', 'ЛЯ минор', 'ua', NULL, 0, NULL, NULL),
(318, 1002, 'Мой Господь пастырь мой', 0, 'Куплет 1\nМой Господь Пастырь мой,\nИ не будет нужды ни в чем.\nОн покоит меня, к тихим водам ведет,\nНаправляет стези.\n\nКуплет 2\nЕсли я и пойду\nСмертной тени тропой,\nНе убоюсь я зла, ведь идешь Ты со мной,\nЖезл и посох в руке.\n\nПрипев \nИисус, Иисус, Иисус!\nЯ нуждаюсь в Тебе.\n\nКуплет 3\nТы насытишь меня\nНа виду у врагов моих.\nТы возложишь елей, и помажешь меня,\nЧаша будет полна.\n\nКуплет 4\nТвоя благость вовек,\nТвоя милость всегда ко мне.\nДом Ты мне сотворишь среди чистых небес, \nЯ нуждаюсь в Тебе.', '', '', 'ua', NULL, 1, '2020-08-09', NULL),
(319, 1003, 'Шалом мои друзья', 0, 'Куплет 1\nШалом мои друзья, храни Господь ваш дом,\nПусть в сердце к вам войдет шалом, шалом.\nИ хоть не прост порой тот мир, где мы живем,\nПусть окружает нас шалом, шалом.\n\nКуплет 2\nОткрыта сердца дверь, живет Дух Божий в нем,\nИ наполняет нас шалом, шалом.\nУлыбками сиять давайте день за днем,\nПриносит радость нам шалом, шалом.\n\nКуплет 3\nПойдем мы в храм святой, там вечность обретем,\nИ вместе с ней Господь дарует нам шалом.\nНас не смутят пути, которыми пойдем,\nНаградой будет нам шалом, шалом.', '', '', 'ua', NULL, 0, NULL, NULL),
(320, 1004, 'Ісус Ісус Ісус', 0, 'Куплет 1\nІсус, Ісус, Ісус!\n\nКуплет 2\nАлелуя, Алелуя, Алелуя!\n\nКуплет 3\nОсь Він гряде!\nОсь Він гряде!\nОсь Він гряде!\n\nКуплет 4\nО, славний Ти!\nО, славний Ти!\nМи хочемо бути з Тобою ! (3 рази).\nІсус, Ісус, Ісус, \nСлавний Ти!!!\n\nКуплет 5\nМи хочемо бути з Тобою ! (3 рази).\nІсус, Ісус, Ісус, \nСлавний Ти!!!', '', '', 'ua', NULL, 1, '2020-08-09', NULL),
(321, 1005, 'Скажет слабый я силен', 0, 'Куплет 1\nСкажет слабый \"я силён\",\nСкажет бедный \"я богат\",\nСкажет \"вижу\" тот кто слеп,\nВсе это сделал Бог во мне.\n\nПриспів\nОсанна, осанна,\nБудем петь, Иисус, Тебе.\nОсанна, осанна,\nТы был распят, но вновь воскрес!\n\nКуплет 2\nПойду к реке жывой воды,\nГде Ты омыл грехи мои,\nМилость Божью и любовь,\nМне явил Спаситель мой.\n\nКуплет 3\nПоднимусь я из глубин,\nНайду я жизнь в руках Твоих,\nБуду петь, что во Христе\nК новой жизни я воскрес.', '', '', 'ua', NULL, 9, '2021-04-11', NULL),
(322, 1006, 'Господь моя сила и щитИ потому я ликую', 0, 'Куплет 1\nГосподь - моя сила и щит(2р.)\nГосподь - упованье момощь мне.\n\nПриспів\nИ по тому я ликую и сердце ликует,\nИ песнь моя и славит Господа\nлоршшр\n\nКуплет 2\n --тут слова другого куплету', '', '', 'ua', NULL, 0, NULL, NULL),
(323, 1007, 'Я так хочу о Я так устал', 30, 'Куплет 1\nЯ так хочу в небеса ко Христу,\nЯ  так хочу к дорогому Отцу.\nТам наши беды уйдут навсегда,\nТам не тоскует душа никогда.\n\nПриспів\nЯ так устал жить на этой земле,\n Хочется в небо, Господь мой, к Тебе\nЗнаю Ты встретишь меня и любя\n Сам слезы отрешь с моего лица!\nИ воспою песнь хвалы я Тебе, \n Ведь подарил Ты спасение мне.\nЖду этой встречи, ликует душа,\n Что скоро увижу, Христос , Тебя!\n\nКуплет 2\nЗдесь на земле странник я и всегда\nХочется в небо, где ждут нас друзья.\nТам меня ждет мой Спаситель и Бог\nОн лучший Друг среди зла и тревог!\n\nКуплет 3\nС каждым днем ближе и ближе тот час,\nВстреча с Иисусом, Он ждет там всех нас.\nОн умирал, чтоб мы жили всегда,\nМы будем петь у престола Отца!', '', '', 'ua', NULL, 0, NULL, NULL),
(324, 1008, 'Чую я голос Твій Ти моя скала', 30, 'Куплет 1\nЧую я голос Твій,\nДе Твій Дух,\nТам спокій!\nВ Тобі захист вічно мій.\nМіцна скала!\n\nКуплет2\nСвітиш в темряві,\nПроганяєш страх.\nЛиш в Тобі Христос, перемоги шлях!\nЗможу все в Тобі,\nДо кінця дійду.\nБлагодать Твоя обновляє!\n\nКуплет 3\nТи моя скала,\nЗ тобою не боюсь.\nКрізь болі і страх!\nВвись на руках.\nПідіймеш коли я спіткнусь!!!', '', '', 'ua', NULL, 1, '2020-06-29', NULL),
(325, 1009, 'Стою в присуствии ТвоемКровь Христа чистым', 33, 'Куплет 1\nСтою в присутствие Твоем,\nСтою и плачу пред Тобою...\nЯ знаю, что не заслужил Твою любовь,\nНо я искуплен Святою кровью.\n\nКуплет 2\nСтою в присутствие Твоем,\nСтою и сердце изливаю.\nЯ знаю, что не заслужил Твою любовь,\nВ Твоих объятьях я снова таю.\n\nПриспів\nКровь Христа чистым сделала меня,\nКровь Христа внутри все изменила,\nКровь Христа, Того, Кто умер за меня,\nКровь Христа меня омыла.\n\nКуплет 3\nСтою в присутствие Твоем,\nСтою и сердце изливаю.\nЯ знаю, что не заслужил Твою любовь,\nВ Твоих объятьях я снова таю.\n\nКуплет 4\nСтою в присутствие Твоем,\nСтою и плачу пред Тобою...\nЯ знаю, что не заслужил Твою любовь,\nНо я искуплен Святою кровью.', '', '', 'ua', NULL, 3, '2020-08-16', NULL),
(326, 1010, 'Схилимо коліна Отче наш що живеш', 0, 'Куплет 1\nСхилимо коліна перед Отцем,\nЙому моління свої несем.\nМолитву в тайні почує Він\nІ скоро явним від дасть взамін.\n\nПриспів\nОтче наш, що живеш на небі,\nНехай святиться Твоє Ймення!\nНехай буде Твоя воля і на землі, як і на небі!\nОтче наш, що живеш на небі,\nНехай святиться Твоє Ймення!\nНехай прийде Твоє царство!\nСила і слава навік! Амінь!\n\nКуплет 3\nХліб наш щоденний, Господь, пошли,\nБорги нам наші не спом`яни, прости.\nІ у спокусу не введи,\nВід лукавого нас захисти.\n\nКуплет 4\nІ як птахів небесних, що не сіють, не жнуть, \nНе збирають у клуні,\nБлагослови і нас, Небесний наш Отець, \nЯкий усіх годує.\nЯк квітку польову, яка цвіте на мить, \nЦарівною вбираєш,\nУ праведність Свою, Господь, нас зодягни, \nНехай вона сіяє.', '', '', 'ua', NULL, 4, '2021-03-07', NULL),
(327, 1011, 'Хто гріх і темінь Чудова благодать', 30, 'Куплет 1\nХто гріх і темінь перемагає,\nХто нас незмінно, безмежно любить,\nГосподь Могутній, Ти над царями - Цар.\nХто чудесами людей вражає,\nІ хто в обіймах цей світ тримає,\nГосподь Могутній, Ти над царями - Цар.\n\nПриспів\nЧудова благодать... Мене Ти полюбив,\nПоніс усі гріхи, за мене на хресті,\nВіддав Своє життя, щоб я свободу мав,\nОооо                            \nТебе прославлю, за все, що ти нам дав!\n\nКуплет 2\nХто відродив нас і дав надію,\nХто всиновив нас і завжди вірний,\nГосподь Могутній, Ти над царями - Цар.\nХто править в правді, хто справедливий,\nХто в славі сяє, Величний, Сильний,\nГосподь Могутній, Ти над царями - Цар.\n\nКуплет 3\nГідний Агнець честі й хвали,\nГідний слави Цар, що смерть переміг!\nГідний Агнець честі й хвали,\nГідний слави Цар, що смерть переміг!', '', '', 'ua', NULL, 3, '2020-12-06', NULL),
(328, 1012, 'Ти моя сила у житті', 0, 'Куплет 1\nТи - моя сила у житті,\nТи є та ціль, куди я йду,\nТи є для мене все! \nТи є той скарб, що я шукав,\nТи є Господь мого життя, \nТи є для мене все!\n\nПриспів: \nІсус - мій Господь! Славлю я Тебе! (2р.)\n\nКуплет 2\nТи взяв мій гріх, мій хрест, мій біль,\nЗнову підняв мене, я - Твій! \nТи є для мене все! \nКоли є спека, - Ти є тінь,\nКоли я прагну, - Ти - вода, \nТи є для мене все!\n\nКуплет 3\nТи на Голгофі вмер за нас, \nАле воскрес і людство спас,\nТи є для мене - все!\nТи воскресіння і життя,\nІ лиш до Тебе прагну я,\nТи є для мене - все!', '', '', 'ua', NULL, 0, NULL, NULL),
(329, 1013, 'Хто дає надію', 30, 'Куплет 1\nХто дає надію? Ісус Христос!\nХто дає прозріння? Ісус Христос!\nХто дає спасіння? Ісус Христос!\nВін, тільки Він!!!\n-     -     -\nХто дає нам силу? Ісус Христос!\nХто дає нам віру? Ісус Христос!\nХто гріхи прощає? Ісус Христос!\nВін, тільки Він!!!\n\nПриспів\nСтворив Він землю й небеса,\nВід зла спасла Його рука.\nПрощає! Любить! Береже!\nВ небесний край Своїх веде!\nНад усіма царями Цар.\nНад усіма панами Пан.\nЗ Ним будемо ми назавжди,\nЗ Ним, тільки з Ним!\n\nКуплет 2\nХто нам дав свободу? Ісус Христос!\nХто дав перемогу? Ісус Христос!\nХто безмежно любить? Ісус Христос!\nВін, тільки Він!!!\n-     -     -\nВін - мій Відкупитель, Ісус Христос!\nВін - душі Спаситель, Ісус Христос!\nСлави Він достойний! Ісус Христос!\nВін, тільки Він!!!\n\nКуплет (приспів)\nБог - Пастир мій, скеля непохитна -\nВикупив мій гріх, Божа я дитина!', '', '', 'ua', NULL, 4, '2020-10-18', NULL),
(330, 1014, 'La unica razon de mi adoración', 33, 'Куплет 1\nLa unica razon de mi adoración.\nEres Tú mi Jesus,\nEl unico motivo para vivir!\nEres Tú mi Señor.\nLa unica verdad de esta en Ti\nEres mi luz y mi salvación,\nEl unico amor eres Tú Señor.\nY por siempre te alabare!\n\nПриспів\nTú eres todo poderoso;\nEres grande y majestuoso.\nEres fuerte, invencible,\nY no hay nadie como Tú!!!', '', 'ЛЯ минор', 'ua', NULL, 0, NULL, NULL),
(331, 1015, 'Ти сворив усе у світі', 43, 'Куплет 1\nТи сворив усе у світі,\nІ сьогодні Твої діти славлять Тебе.\nКоли лице Твоє шукаю,\nТвій подих, Боже, відчуваю в своїй душі!\n\nКуплет 2\nЯ маю віру та надію,\nТи дав життя та мрію - колись побачу Тебе.\nКоли в дорозі зупиняюсь,\nТебе молю, Тебе благаю: дай сили мені.\n\nПриспів\nЯ славлю Господа, добрий бо Він,\nБо навіки є милість Його!\nСлавлю Господа, добрий бо Він,\nБо навіки є милість Його!\n\nКуплет 3\nЯ знаю істину і правду,\nТи взяв тягар душі й кайдани смирті забрав.\nТепер з небес Тебе чикаю,\nІ в свому серці прославляю Теюе, мій Господь!\n\nКуплет 4 ( Приспів2 )\nСлавти Господа', '', '', 'ua', NULL, 0, NULL, NULL),
(332, 1016, 'Я розмышляю о ТебеСвятой Святой', 43, 'Куплет 1\nЯ размышляю о Тебе,\nО той милости большой, что явил Ты мне.\nКак потухшую свечу,\nТы зажег меня и гореть Тобой хочу.\n\nПриспів\nСвятой! Святой!\nВеликий Бог! Всесильный Бог! Восхищаюсь Тобой.\nСвятой! Святой!\nИ на земле, и в небесах все в Твоих лишь руках, - Святой!\n\nКуплет 2\nЯ помышляю о Тебе,\nКак нашел меня в слезах, в беспроглядной тьме.\nТвой луч света воссиял,\nИ любовью вечной Ты меня объял.', '', '', 'ua', NULL, 4, '2020-12-20', NULL),
(333, 1017, 'Дух Святий Ти торкнись', 33, 'Приспів\nСлава, Слава Тобі мій Бог!\nЗа Дух Святий! (3р.)\nСлава Тобі, Слава Тобі мій Бог!!!\n\nКуплет 1\nДух Святий Ти торкнись мене типлом Своїм.\nДух Святий освіти мій розум світлом Твоїм,\nБожою добротою серце Ти сповняй.\nЗ джерела Свого мені напитись дай!\n\nПриспів\nСлава, Слава Тобі мій Бог!\nЗа Дух Святий! (3р.)\nСлава Тобі, Слава Тобі мій Бог!!!\n\nКуплет 2\nДух Святий виливай на світ любов Свою.\nДух Святий відкривай нам Істину Свою,\nПідіймай нас на крилах Божих в небеса.\nО Дух Святий Ти так потрібен нам!', '', 'ЛЯ минор', 'ua', NULL, 0, NULL, NULL),
(334, 1018, 'Небо небо Поднимаю глаза', 0, 'Куплет 1\nПоднимаю глаза и смотрю в небеса,\nТам я вижу Христа, одесную Отца.\nНебо, небо небес приготовил Он мне.\nЦель моя и мичта - неба вся красота!\n\nПриспів\nНебо, небо небес - город вечных чудес,\nЯ мечтаю о нем, там мечтаю и здесь.\nНебо, небо небес, путь туда через крест.\n\nКуплет 2\nЧтобы в небо попасть, нужо жизь так прожить,\nЧтобы Бог мог сказть: Ты достоин в нём жить,\nТы достоин смотреть Иисусу в глаза!\nЕсли толко войдёшь ты к Нему в небеса.\n\nКуплет 3\nНе слухал человек, и невидел то глаз,\nКак там, в небе небес, что там будет для нас.\nНо я знаю одно - красотой всех небес,\nБудет тот, Кто понес на Голгофу наш крест.', '', '', 'ua', NULL, 3, '2020-11-15', NULL),
(335, 1019, 'Велкм наш', 30, 'Куплет 1\nВелкм наш Бог,\nВелкм наш Цар,\nБезподобный Господь\nНесравненный Он .\n\nПриспів\nСвятой, Превознесён\nЦар славы, Цар небес!\n\nКуплет 2\nЯ смотрю на небеса\nЖду когда придёшь опять!', '', '', 'ua', NULL, 0, NULL, NULL),
(336, 1020, 'Бог с нами в долине удачи', 30, 'Куплет 1\nБог с нами в долине удачи.\nИ близок в часы неудач,\nКогда мы смеемся и плачем -\nОн с нами, Господь наш и Врач!\n--------\nВ глубокие топи унынья,\nВ ущелья, где смертная тень\nСпускается Он и доныне,\nЧтоб нам помагать каждый день!\n\nПриспів\nСкажем вместе: Слава Богу! Слава Богу!\nСкажем вместе: Мы идем за Тобой!\nСкажем вместе: Слава Богу! Слава Богу!\nСкажем вместе: Мы идем за Тобой!\n\nКуплет 2\nОн с нами, когда наше знамя,\nКоторому имя Любовь,\nТоржественно реет над нами\nВобрав в себя образ Христов;\n-------\nКогда мы людей утешаем.\nСлагая дела и слова.\nЛюбовью своей подтверждаем,\nЧто вера у нас не мертва.', '', '', 'ua', NULL, 1, '2020-08-09', NULL),
(337, 1021, 'Верный и Вечный Мы стоим', 0, 'Куплет 1\nВерный и Вечный, Ты Господь, Ты наш  Бог!\nЧудный, Учытел, Ты Господь, Ты наш  Бог!\nСилный,Спасител, Ты Господь, Ты наш  Бог!\nЩит и Защитник, Ты Господь, Ты наш  Бог!\n\nКуплет 2\nЧто вину мне может смыть,\nО, ничто, лиш кровь Иисуса.\nВновь, что может исцилить,\nО, ничто, лиш кровь Иисуса.\n\nКуплет 3\nМы стоим перед Тобою, \nВозвыщая Твоё Имя!\nНаша Башня, наш Спаситель,\nЗащитит от пораженья!\nМы возносим к небу руки,\nПринося свои молитвы:\nЗа упавших в пропасть, в безну, мы стоим в проломе, Иисус!\n\nКуплет 4\nМы в молитве за скорбящих, за всех тех, кто на исходе!\nЗа разрушенные семьи и за наше поколенье!\nТы даёш освобожденье от греха и безаконья!\nКогда силы, оставляют, Твоя вера восстановит', '', '', 'ua', NULL, 2, '2021-04-05', NULL),
(338, 1023, 'Верный и Вечный', 0, 'Куплет 1\nВерный и Вечный, Ты Господь, Ты наш Бог!\nЧудный, Целитель, Ты Господь, Ты наш Бог!\nСильный, Спаситель, Ты Господь, Ты наш Бог!\nЩит и Защитник, Ты Господь, Ты наш Бог!\n\nКуплет 2\nЧто вину мне может смыть,\nО, ничто, лишь кровь Иисуса.\nВновь, что может исцелить,\nО, ничто, лишь кровь Иисуса.\n\nКуплет 3\nМы стоим перед Тобою, \nВозвышая Твоё Имя!\nНаша Башня, наш Спаситель,\nЗащитит от пораженья!\nМы возносим к небу руки,\nПринося свои молитвы:\nЗа упавших в пропасть, в бездну, мы стоим в проломе, Иисус!\n\nКуплет 4\nМы в молитве за скорбящих, за всех тех, кто на исходе!\nЗа разрушенные семьи и за наше поколенье\nТы даешь освобожденье от греха и беззаконья\nКогда силы оставляют, Твоя вера восстановит', '', '', 'ua', NULL, 3, '2020-10-11', NULL),
(339, 1024, 'Господь до тебе йду', 0, 'Куплет 1\nГосподь до Тебе йду, серце Ти моє зміни\nБлагодать Свою Ти мені яви\nЗнаю я Господь, що моя сила лиш в Тобі\nТи зміни мене Своєю силою любові\n\nПриспів\nО, ГОСПОДЬ ЛЮБОВ\'Ю ТИ НАПОВНИ НАС\nЛИШ ВОНА ЗМІНИТЬ ВСЕ ЖИТТ\nІ, ЯК ОРЛИ МИ, ПІДІЙМЕМ КРИЛА\nО НІЖНИЙ ДУХ СВЯТЙ ВЕДИ НАС У ЖИТТІ\nСВОЄЮ СИЛОЮ ЛЮБОВІ\n\nКуплет 2\n ...', '', '', 'ua', NULL, 0, NULL, NULL),
(340, 1025, 'Велик наш Бог', 30, 'Куплет 1\nВелик наш Бог,\nВелик наш Царь,\nБесподобный Господь.\nНесравненный Он!\n\nПриспів\nСвятой, Превознесён,\nЦарь славы, Царь небес!!!\n\nКуплет 2\nЯ смотрю на небеса!\nЖду, когда придёшь опять!', '', '', 'ua', NULL, 7, '2021-01-31', NULL),
(341, 1026, 'Я один из тех кого Ты заметил', 43, 'Куплет 1\nЯ один из тех, кого Ты заметил!\nЯ один из тех, кого Ты не прошел! \nЯ один из тех, кто зимой и летом,\nТвоим солнечным светом греет душу свою.\n\nПриспів\nИисус – я один из многих, \nЧьи пути, дороги к Тебе ведут. \nИисус, Ты готовишь город,\nНас там будет много, я – один из них!\n\nКуплет 2\nЯ один из тех, чьи грехи забыты!\nЯ один из тех, кого Ты простил!\nЯ один из тех, кто был на Голгофе, \nГроб Твой видел пустым, Иисус – Ты воскрес!\n\nКуплет 3\nЯ один из тех, кто поет Тебе песни,\nЯ один из тех, кто любит Тебя!\nЯ один из тех, кто с Тобой будет вместе,\nВ Царстве Небесном во веки веков.', '', '', 'ua', NULL, 3, '2021-01-17', NULL),
(342, 1027, 'ВІН ПРИЙШОВЩОБ ВСІХ СПАСТИ', 30, 'Куплет 1\nВІН ПРИЙШОВ, ЩОБ ВСІХ СПАСТИ,\nЩОБ ТОБІ ДОПОМОГТИ,\nКЛИЧЕ ВІН: \"ДО МЕНЕ ВСІ ПРИЙДІТЬ!\"\nСЛОВА ЙОГО ДО НАС ЗВУЧАТЬ,\nНЕСУТЬ НАМ МИР І БЛАГОДАТЬ,\nНІХТО НЕ ИЛЮБИТЬ ТАК, ЯК ВІН.\n\nКуплет 2\n\"ДО МЕНЕ ЙДИ, О СИНУ МІЙ,\nЯ СПОКІЙ ДУШІ ДАМ ТВОЇЙ!\nЯ ТЕБЕ ЛЮБЛЮ!\nПРИЙДИ І БІЛЬШЕ НЕ БЛУКАЙ,\nЖИТТЯ СВОЄ ВІДАЙ!\nЯ ТЕБЕ ЛЮБЛЮ!\"\n\nПриспів\nЯДУШУ ОЖИВЛЮ І В СЕРЦЕ МИР ЗІЛЮ,\nВІДКРИЮ НОВИЙ СВІТ ЛЮБОВІ Й ВІРИ.\nТЕБЕ Я ОБНІМУ, ТАКИМ ЯК Є ПРИЙМУ,\nНАЗВУ СВОЇМ ТОМУ, ЩО Я ТЕБЕ ЛЮБЛЮ!\n\nКуплет 3\nХРИСТОС ТЕБЕ БЛАГОСЛОВИТЬ,\nЛЮБОВЮ ДУШУ ОБНОВИТЬ, \nТІЛЬКИ ТИ ДО НЬОГО ПІДІЙДИ!\nІ В ТИШІ ТИ ПЕРЕД НИМ СХИЛИСЬ,\nПЕРЕД СПАСОМ ТИ СМИРИСЬ,\nЗНАЙ, НІХТО НЕ ЛЮБИТЬ ТАК, ЯК ВІН!\n\nКуплет 4\nВІН ВІД НЕПРАВДИ ЗАХИСТИЬ,\nІ ВІД ГРІХІВ ТЕБЕ ЗВІЛЬНИТЬ,\nЛЮБОВЮ ОЖИВИТЬ\nСПІШИ СЬОГОДНІ ДО ХРИСТА,\nЩЕ КЛИЧЕ НАС ВАС ЛЮБОВЬ СВЯТА;\n\"Я ТЕБЕ ЛЮБЛЮ\"!', '', '', 'ua', NULL, 0, NULL, NULL),
(343, 1028, 'Desde el fono del mar Que Tú eres la Roca eterna', 30, 'Куплет 1\nDesde el fono del mar, \nDesde el más alto lugar.\nDede el más fondo abismo, te alabaré!\nDesde mí corazon,\nFuerte o debil esté,\nCada instande de mi vida, con gozo yo dire:\n\nПриспів\nQue Tú eres la Roca eterna,\nSeñor sobre cielo y tierra, Tú eres Señor!\nQue toda criatura adore,\nQue toda nacion se postre ante Tí, Señor!\nTú eres Diós!', '', '', 'ua', NULL, 0, NULL, NULL),
(344, 1029, 'Cantare al Señor Carros del faraóoon', 0, 'Куплет 1\n// Cantare al Señor por siepre, su diestra es tode poder! //\n\nПриспів1:\nHecho ala mar los carros que los perseguian \nJinete caballo, hecho a la mar.\n\nПриспів2:\nHechó a la mar los carros del faraóoon. Hey! Hey!\nLa, la, la ...\n\nКуплет 2\n// Mí padre es Diós, y yo le exalto. Mi padre es Díos y le exaltaré! // \nHecho a la mar ...\n\nПриспів2:\nHechó a la mar los carros del faraóoon. Hey! Hey!\nLa, la, la ...', '', '', 'ua', NULL, 0, NULL, NULL),
(345, 1030, 'Огортаєш мене Ти любовю', 30, 'Куплет 1\nОгортаєш мене Ти любов´ю,\nОбновляєш моє життя!\nО Не збагну Тебе мій Боже.\nО Не розумію Твоє буття!\n\nКуплет 2\nО Госодь хто забере мене від Тебе.\nХто зупинить Твою любов до мене;\nЗавжди лине Твоя любов!\nПамятаю я Твою кров.\nТекла за мене!\n\nКуплет 3\nО Ти приймаєш мої розкаяння,\nО робиш вільним мене від гріха!\nО омиваєш мої Ти ноги.\nОвід брудного гріха!', '', '', 'ua', NULL, 0, NULL, NULL),
(346, 1031, 'Просто не можливо Бог добрий', 0, 'Куплет 1:\nПросто не можливо сказати, слів не підібрати,\nЯк Ти Господь, благий.\nІ любовь Твоя безмежна, вона не осяжна,\nБог Ти Господь, завжди благий!\n\nКуплет (Приспів1):\nБог добрий!\nБог добрий!\nБог добрий!\n\nКуплет 2:\nПолюбив людей, світ грішний, на смерть відчайдушно\nЗа нас пішов Божий Син.\nДобровільно прийняв страждання, вогнем випробування,\nЩоб ти, душа, втішалась Ним!\n\nКуплет (Приспів2):\nБог - добрий!\nБог - добрий!\nБог - добрий!\nБог - благий!Бог - благий!\n\nКуплет 3:\nПоведе тебе Святим Духом, Буде твоїм Другом;\nПоклич Його, поможе Він.\nПросто неможливо сказати, фраз не підібрати,\nЧинити шану не хватить слів!\n\nКуплет (Приспів3):\nБог - благий!Бог - благий!\nБог - добрий!\nБог - добрий!\nБог - добрий!\n\nКуплет - БРІДЬЖ:\nЯ славити хочу Тебе за мирне відкрите небо!\nЗа ти, що Ти є, й жива душа моя.\nТи знаєш усі Благання, мріїі сподівання,\nХай славить Тебе повік уся земля!\n\nКуплет (Приспів4):\nБог - добрий!\nБог - добрий!\nБог - добрий!', '', '', 'ua', NULL, 1, '2020-07-19', NULL),
(347, 1032, 'Дай чистое сердце Господь', 0, 'Куплет 1\nДай чистое сердце, Господь,\nОмой от греха мою\n\nПриспів\nВ при\n\nКуплет 2\n --тут слова другого куплету', '', '', 'ua', NULL, 0, NULL, NULL),
(348, 1033, 'Я бачу як Цар Слави', 0, 'Куплет 1\nЯ бачу, як Цар Слави,\nЙде на хмарах із вогнем,\nТремтить усе, тремтить усе!\n\nКуплет 2\nЯ бачу як любовю;\nВсі гріхи омиє Він,\nСпіваєм ми, співаєм ми!\n\nПриспів\n Осанна, Осанна,\nОсанна Богу ввишнім!!!\n\nКуплет 3\nЯ бачу покоління,\nЯке піднялось взяти край,\nЗ вогнем в серцях!\nЗ вогнем в серцях!\n\nКуплет 4\nЯ бачу як в молитві,\nДо нас пробудження прийде,\nВклоняємось Тобі, Господь!\n\nКуплет  5 Бридж:\nСерце Ти моє зціли,\nІ очам відкрий те, що хочеш Ти.\nНавчи мене любити так, як Ти всіх!\nБіль свою моєю зроби,\nЦарству я віддам все, що є в мені.\nТак пройду свій шлях земний до вічності!', '', '', 'ua', NULL, 0, NULL, NULL),
(349, 1034, 'Зранений був Звершелось і прощений я', 30, 'Куплет 1\nЗранений був і зневажений Він,\nРозп\'ятий на хресті Божий Син.\nБожа любов дала силу мені!\nВін заплатив сповна;\nЗа спасіння моєї душі!\n\nПриспів\nЗвершилось і прощений я!\nЗвершилось і зцілений я!\nЗвершилось! Початок нового життя!\nЗвершилось! Звершилось!\nНа небесах буду вічно я з Ним!\n\nКуплет 2\nМій Бог живий, я Його славлю.\nЙому віддаю всю хвалу!\nМій Бог воскрес і я з Ним воскресну;\nВсю вічність з Отцем проведу!\n\nКуплет 3\nЗвершилось! Звершилось!\nНа небесах буду вічно я з Ним!', '', '', 'ua', NULL, 5, '2021-04-04', NULL),
(350, 1035, 'О Любові не в збагну На христі Цар возкрислий', 0, 'Куплет 1\nО! Любові не збагну - \nЖертву за гріх принесену!\nРозбитий за моє зцілення.\nРозп´ятий щоб я здобув життя!\n\nКуплет/Заспів 1\nНа хресті - Мессія, невинний.\nАгнець, Він - надія, Бог вірний!\n\nПриспів1\nЦар воскреслий, Пан любові;\nВознесенний, вічно в славі.\nАлілуя! Переміг Він!\nЯ омитий, Навіки вільний!\n\nКуплет 2\nО! Дивує знов і знов:\nМилість, свята Його Любов.\nСмертний, від смерті щоб спасти,\nВідкинений, щоб я був прийнятий.\n\nКуплет/Заспів 2\nНа хресті - Мессія, невинний.\nАгнець, Він - надія, Бог вірний!\n\nПриспів1\nЦар воскреслий, Пан любові;\nВознесенний, вічно в славі.\nАлілуя! Переміг Він!\nЯ омитий, Навіки вільний!', '', '', 'ua', NULL, 8, '2021-04-04', NULL),
(351, 1036, 'Старый крест', 0, 'Куплет 1\nНа далеком холме, средь деревьев и скал\nСквозь седые века старый крест простоял.\nМиллионы людей у подножья креста.\nСвое счастье нашли, там однажды был я.\n\nПриспів\nСтарый крест, старый крест,\nНеброский, но лишь в нем\nСила есть, сила есть, сегодня может он\nИсцелять розбитые, больные сердца,\nКаждому пришедшему открыть небеса.\n\nКуплет 2\nМежду небом святым  и греховной землей\nПропасть злая лежит разделяя собой.\nХочешь вер, хочешь нет, слушай слово Творца:\nКрест - единственный мост от земли в небеса.\n\nКуплет 3\nИисус дорогой, у подножья креста\nНа далеком холме я увидел Тебя:\nНа пронзенных руках не застывшая кровь,\nА в прекрасных глазах Божья к людям любовь.', '', '', 'ua', NULL, 0, NULL, NULL),
(352, 1037, 'дайте мені крила', 30, 'Куплет 1\nДайте мені крила, в небо я полину\nДо мого Спасителя Христа.\n\nКуплет Приспів \nДайте мені крила, землю я покину\nІ втечу від горя і від зла.\n\nКуплет 2\n Там у небі яснім місто є прекрасне,\nА Царем у місті тім - Христос.\n\nКуплет Приспів\nТам немає ночі, лиш Господні очі\nСвітять там, щоб краще всім жилось.\n\nКуплет 3\nТам посеред раю річка протікає,\nВ річці тій вода жива біжить,\n\nКуплет Приспів\nБіля неї квіти, і, розклавши віти,\nДерево життя повік стоїть.\n\nКуплет 4\nТам хвороб немає, горя не буває,\nІ щасливі всі, хто там живуть.\n\nКуплет Приспів\nДай же, Боже, крила, щоб я не загинув,\nА у світі тім міг вічно жить.\nЗ Господом моїм міг вічно жить.', '', '', 'ua', NULL, 2, '2020-10-11', NULL),
(353, 1038, 'РУКИ ОПУЩЕЫ', 30, 'Куплет 1\n Руки опущены, слезы в очах,\nЛюди, прислушайтесь к свисту бича\nСбылось пророчество — лик Твой в крови,\nСмех и пощечины, крики - \"распни!!!\"\n\nПриспів\n   Это моя вина, это мои дела,\n    Это мои слова — ранят Христа.\n\nКуплет 2\n Крест, поношения, слезы и боль,\nЩедрой жестокостью платим порой,\nВместо награды — зло! \nВместо хвалы — хула!\nБожьему Сыну на плечи легла...\n\nПриспів\n   Это моя вина, это мои дела,\n    Это мои слова — ранят Христа.\n\nКуплет 3\nВетер бушует, луч солнца угас,\nВеет соблазном дьявола глас:\n\"Что же на помощь Отца не зовёшь?\nИли пощады и милости ждешь?\"\n\nПриспів\n   Это моя вина, это мои дела,\n    Это мои слова — ранят Христа.', '', '', 'ua', NULL, 1, '2021-04-01', NULL),
(354, 1039, 'За те що схід сонця щодняДЯКУЄМ МИ', 0, 'Куплет 1\nЗа те, що схід сонця щодня в красі зустрічає земля,\nЗа те, що створив нас людьми, дякуєм ми!\nЗа Слово Батьківське Твоє, що силу в натхненні дає,\nІ нас визволяє з пітьми, дякуєм ми!\n\nКуплет 2\nЗа те, схід сонця щодня в красі зустрічає земля\nЗа те, що створив нас людьми, дякуєм ми!\nЗа Слово Батьківське Твоє, що силу в натхненні дає\nІ нас визволяє з пітьми,\n\nПриспів\nДЯКУЄМ МИ! - 4 р.\n\nКуплет 3\nЗа вічну любов, що з небес\nЗійшла, щоб піднятись на хрест,\nЩо нас обіймає крильми, дякуєм ми!\nСпасибі за вічне життя,\nЗа прощення в мить каяття,\nЗа те, що назвав нас дітьми, дякуєм ми!', '', '', 'ua', NULL, 2, '2020-11-08', NULL),
(355, 1040, 'Чи пізнав ти силу крові о скажи', 0, 'Куплет 1\nЧи пізнав ти силу крові, о скажи!\nЧи звільнився ти від тягарів?\nЧи приніс ти до Христа свої гріхи,\nЩоб Він кров\'ю святою обмив?\n\nПриспів\nЧи ти вже; чистий є?\nМоже змити твій гріх кров Христа;\nМоже убілити, наче сніг, тебе.\nЧи обмитий ти кров\'ю Христа!\n\nКуплет 2\nЧи ти маєш в серці віру у Христа,\nЧи ти жертву Голгофську прийняв?\nВсі гріхи змиває тільки кров свята;\nЧи в підніжжя хреста ти їх склав?\n\nКуплет 3 не співають\nЧи готовий ти Ісуса зустрічать?\nЧи очистився вже від гріхів?\nМоже Спас у край небесний, вічний взять\nТільки тих, кого кров\'ю обмив.\n\nКуплет 4\nТож прийди до Спаса, відступи від зла,\nІ покайся в провинах скоріш,\nБо за тебе із Голгофи кров текла;\nНею гріх свій повіки обмий.', '', '', 'ua', NULL, 1, '2020-08-23', NULL),
(356, 1041, 'Чи пізнав ти', 0, 'Куплет 1\nЧи пізнав ти силу крові, о скажи!?\nЧи звільнився ти від тягарів?\nЧи приніс ти до Христа свої гріхи,\nЩоб Він кровю святою обмив\n\nПриспів\nЧи ти вже чистий є?\nМоже змити твій гріх кров Христа\nМоже убілити, наче сніг, тебе,\nЧи обмитий ти кровю Христа?\n\nКуплет 2\n --тут слова другого куплету\n\nКуплет 1\nЧи пізнав ти силу крові, о скажи!?\nЧи звільнився ти від тягарів?\nЧи приніс ти до Христа свої гріхи,\nЩоб Він кровю святою обмив\n\nПриспів\nЧи ти вже чистий є?\nМоже змити твій гріх кров Христа\nМоже убілити, наче сніг, тебе,\nЧи обмитий ти кровю Христа?\n\nКуплет 2\n --тут слова другого куплету', '', '', 'ua', NULL, 0, NULL, NULL),
(357, 1042, 'Много лет говорят о чуде из чудес', 33, 'Куплет 1\nМного лет говорят о чуде из чудес,\nМного лет говорят, что Иисус воскрес!\nПусть хвалою наполнятся людей сердца,\nПрославляя любовь Воскресшего Христа.\n\nПриспів\nДа, Христос воскрес, и это чудо!\nПрославлять Его, все люди, будем - \nОн воистину воскрес!\nДа Христос воскрес и льются песни\nВ этот воскресенья день чудесный.\nОн воистину воскрес!\n\nКуплет 2\nМного лет говорят о чуде из чудес,\nМного лет говорят, что Иисус воскрес.\nНе умолкнут уста людей пусть никогда,\nПусть несут эту весть через многие года.\n\nКуплет 3\nМного лет говорят о чуде из чудес,\nИ мы знаем, воистину Христос воскрес.\nНебеса приглашают всех людей к Нему - \nВоскресенье Христа навек сокрыло тьму.', '', 'ЛЯ минор', 'ua', NULL, 0, NULL, NULL),
(358, 1043, 'Коли розтане сніг', 0, 'Куплет 1\nКоли розтане сніг,\nІ проліски ясні.\nДо неба знов голівки підіймуть!\nТо Бог їх береже, життя Він всім дає.\nІ сонечком ласкавим зігріває!\n\nПриспів\nХвала мій Бог, Тобі за те, що є в житті!\nЗа вічність і за кожну мить, що маю!\nТи щастя дав мені, і радість у Христі,\nГосподь мене так любиш твердо знаю!\n\nКуплет 2\nДзвенить вже скрізь весна природа ожива.\nІ ніжно ранок землю огортає,\nСпіває соловей новий зустрівши день,\nІ разом з ним душа моя співає.\n\nКуплет 3\nХристос смерть подолав, Живий з могили встав.\nЩоб ми були спасеними з вами.\nЗа щастя, доброту, хвала і честь Христу,\nСпівайте щиро Богу разом з нами!', '', '', 'ua', NULL, 0, NULL, NULL),
(359, 1044, 'Христос Воскрес', 0, 'Куплет 1\nХристос (Воскрес)! 2р.О радість, радість нам!\nХристос (Воскрес)! 2р. Кінець журбі й сльозам.\nХристос (Воскрес)! Христос (Воскрес)! \nСмерть , смертю подолав і нам спасіння вічне дав\n\nКуплет 2\nЙого злочинців руки на двері розп´яли\nЗа нас тяжкії муки терпів Він у любві\nПречиста кров лиласся із ніг, рук і чола\nЗвершилось все- Йому хвала\n\nКуплет 3\nЗ ариматеї Йосип Пилата ублагав,\nЗ хреста щб зняти тіло, - і зняв, поховав.\nВ садуц, у новім гробі... Та сонце лиш зійло,\nХриста вже в гробі не було.\n\nКуплет 4\nДо гробу дуже рано Марія вже прийшла\nІ тіла там нежданно вона вжене знайшла...\nЯвивсь їй ангел з неба і радісно сказав:\n- Христос уже із мертвих встав!\n\nКуплет 5\nСхвильована Марія не стримала ридань...\nАж їй у яснім світлі Христос явився Сам...\nУчителю мій сказала упавши перед Ним', '', '', 'ua', NULL, 0, NULL, NULL),
(360, 1045, 'Співай моє серце', 0, 'Куплет 1\nСпівай, моє серце, мов пташка весела,\nЩо сонце безжурно вітає.\nПрокинулось поле, гаї, рідні села\nТа Божої ласки чекають.\n\nПриспів\nСпівай моє серце, співай моє серце\nЗ ранку й до ночі!\nСпівайі про славу Христову\nЙ молися охоче.\n\nКуплет 2\nЛюби, моє серце, і ворога й друга\nБо щастя нема без любові\nСьогодні люби, бо чи прийде день другий\nСьогодні посій Святе Слово.\n\nКуплет 3\nНадійся, серденько, хоч сунуться хмари\nІ буря зірватися може\nБо часто із радістю горе йде в парі\nМолися: кріпи мене Боже!', '', '', 'ua', NULL, 3, '2020-11-15', NULL),
(361, 1046, 'Довго довго я скитався', 0, 'Куплет 1\nДовго, довго я скитався без Ісуса в темноті\nІ життям розчарувався, не знаходячи мети,\nЯ шукав хто допоможе, моїм другом стане хто,\nІ почув я голос Божий: \"Я люблю тебе давно!\"\n\nПриспів\nТак давно, так давно\nЯ люблю тебе давно\nО приємний голос Божий\nЯ люблю тебе давно.\n\nКуплет2\nБог прийняв мене з любов\'ю,\nВід гріхів звільнив мене,\nБлагодать Його знайшов я\nІ подяку склав за все.\nІ тепер завжди покоюсь\nУ присутності Його,\nПовсякчасно чую голос:\n\"Я люблю тебе давно!\"\n\nКуплет3\nО, засмучений мій друже,\nДо Ісуса поспіши,\nВін до тебе небайдужий,\nСтане Другом назавжди.\nЯк покаєшся ти щиро,\nПриймеш вірою Його,\nТо почуєш голос милий:\n\"Я люблю тебе давно!\".', '', '', 'ua', NULL, 0, NULL, NULL),
(362, 1047, 'Я ДОЖДУСЬ', 0, 'Куплет 1\nЯ сокрыт в Тебе, Бог, вне Тебя меня нету \nКак сквозь камни росток, призываемый светом \nМой измученный дух, Тебя жаждет и алчет \nТы придешь ко мне вдруг, быть не может иначе\n\nПриспів\nЯ ДОЖДУСЬ, ДОТЯНУСЬ, ДОКРИЧУСЬ ДО НЕБЕСНОГО ТРОНА \nО, ИИСУС, Я МОЛЮСЬ, Я СКЛОНЮСЬ, СОБЕРИ МОИ СТОНЫ!\n\nКуплет 2\nБез любви задохнусь, и умолкну так рано \nНо к Тебе я прорвусь, прикоснусь к Твоим ранам \nВдруг по жилам тепло, потечет в мое сердце \nИ смертям всем на зло, я Тобою воскресну, Иисус\n\nКуплет 3\nЯ дождусь, дотянусь, докричусь до небесного трона \nО, Иисус, я молюсь, я склонюсь, собери мои стоны! \nЯ дождусь, дотянусь, докричусь до небесного трона \nО, Иисус, я молюсь, я склонюсь, забери мои стоны!\n\nКуплет 4\nЯ дождусь, дотянусь, докричусь до небесного трона \nО, Иисус, я молюсь, я склонюсь, забери мои стоны! \nЯ приду, припаду, припаду пред престол благодати \nО прими ,обними заключи мою душу в объятья', '', '', 'ua', NULL, 0, NULL, NULL),
(363, 1048, 'Твоє слово є хліб Боже наш Ти – могутній', 30, 'Куплет 1\nБоже наш, Ти – могутній, контролюєш захід і схід,\nТвоя милість навіки, Твоя вірність із роду в рід.\nКожен день Твоє слово проникає в серця людські\nІ зерно оживає, проростає, приносить плід.\n\nПриспів\n  Твоя милість навік!\n Твоя милість навік!\n Твоя милість навік!\n Твоя милість навік!\nКожен день Ти нас водиш, запровадиш на тихий потік.\nЧастування зготовив, переповнив чашу надмір!\n\nКуплет 2\nТвоє слово – це хліб\n  Твоє слово – це хліб!\n  Твоє слово – це хліб!\n  Твоє слово – це хліб!\n           \nНавік!        Навік!        Навік!      Твоя милість навік!\nЦе хліб!    Це хліб!     Це хліб!   Твоє слово – це хліб.\nЦе хліб!    Це хліб!     Це хліб!   Твоя милість навік!', '', '', 'ua', NULL, 2, '2021-03-28', NULL),
(364, 1049, 'В Твоєму Домі Господи', 30, 'Куплет 1\nВ Твоєму Домі, Господи, приємно бути,\nІ серцем прагну лиш до Тебе я.\nВ присутності Твоїй завжди знаходжу спокій,\nУ тіні Твоїх крил співаю я.\n\nПриспів\n Краще з Тобою день один,\nТільки з Тобою в Твоїм Домі,\nКраще з Тобою день один, ніж сотні будь - де,\n		сотні будь - де.\n\nКуплет 2\nПобачити красу Твою, Господь, бажаю,\nЗнайти Тебе, де слава є Твоя.\nВ присутності Твоїй завжди знаходжу спокій,\nУ тіні Твоїх крил співаю я.\n\nКуплет 3\nБажаю всім єством до Тебе, Бог Живий,\nТвій Дух - вода душі моїй.\nО Господи, прошу, прийди до мене знов,\nІ стану ближче я до Тебе, Боже мій.', '', '', 'ua', NULL, 2, '2020-09-18', NULL),
(365, 1050, 'О Господь то Пастир мій', 30, 'Куплет 1\nО, Господь, то Пастир мій в не достатку, тому я не буду.\nТи оселиш мене на зелених лугах, до вод тихих вводиш мене.\n\nПриспів\nДе би я не йшов я не злякаюсь зла!\nДе би я не йшов ти є при мені!\nДе би я не йшов я не злякаюсь зла!\nТвій жезил і твій посох потішають мене!', '', '', 'ua', NULL, 5, '2021-01-24', NULL),
(366, 1051, 'В твоей руке светильник есть', 32, 'Куплет 1\nВ твоей руке светильник есть\nС ним Бог призвал тебя нести благую весть\nПусть Дух Святой зажгет в тебе огонь\nОн нужен тем, кто обречен\n\nПриспів\nЗажги свой свет, сияй во тьме\nНеси огонь по всей земле\nПускай горит перед людьми\nСвятой огнь, огонь любви\n\nКуплет 2\nКогда в пути ты утомлен\nОгонь погас внутри и ты опустошен\nЗнай, ты Его сосуд и Он рукой Своей\nВернет огонь душе твоей\n\nКуплет 3\nНикто свечу не ставит в тень\nНо ставит высоко, чтоб ночь была как день\nПусть Божий свет пронзает тьму скорбей\nНеся спасенье для всех людей!', '', '', 'ua', NULL, 0, NULL, NULL),
(367, 1052, 'Господь вклоняюся тобі', 30, 'Куплет 1:\nГосподь вклоняюся тобі,\nВ піснях плиту вінок хвали.\nМогутній сильний цар святий,\nВклоняюся, поклоняюся.\n\nПриспів 1:\nЖиттям своїм тобі віддати \nДілами рук завжди тебе прославляти\nТи достойний, Ти достойний.\nОсанна! Осанна! Осанна! Тобі цар царів!\n\nПриспів 2:\nЗ небес на землю Бог зійшов,\nНам доказав свою любов.\nМогутній і сильний цар святий,\n Вклоняюся, поклоняюся.\n\nКуплет 2:\nЗранений Ти був за наші гріх\nЗа наші провини ти мучений був.\nКара на Тобі була за наш мир.\n…     …     …\nМогутній цар творець на землі.', '', '', 'ua', NULL, 0, NULL, NULL),
(368, 1054, 'Ангелы трона', 30, 'Куплет 1\nАнгелы трона Твоего,\nТвоего поют.\nЖивому слову Твоему.\nВозносят всю хвалу!\n\nПриспів\nСвятой!\nТы Бог святой!\nТы Бог святой!\nТы наш Царь!\n\nКуплет 2\nСтарцы склоняяьы у ног Твоих \nУ ног Твоех приклоняются\nТворения все на земле\nСклоняются перед Тобой', '', '', 'ua', NULL, 0, NULL, NULL),
(369, 1055, 'Ісусе дякую Тобі', 30, 'Куплет 1\nІсусе дякую Тобі\nЩо ти відкрив моїм очам\nЦей дивний світ - Твій вічний храм\nНіч, зорі і морський прибій\n\nКуплет 2\nТебе не знаючи шукав\nІ ще не вірив та Любив\nХоча мій розум відкидав\nПізнав я серцем диво з див.\n\nПриспів\nЯ відчуваю всюди скрізь \nТебе в сонці і в дощі,\nВ най більш віддаленій зорі\nВ незримій глибині душі\n\nКуплет 3\nІ доки я живу молюсь\nВ тобі життя і любов моя\nЗ тобою в смерті я зіллюсь \nЯк ранкова досвіту зоря', '', '', 'ua', NULL, 0, NULL, NULL),
(370, 1057, 'Великий Бог Коли Señor mi Dios', 0, 'Куплет 1\nВеликий Бог! Коли на світ погляну,\nІ бачу все, що Ти створив в красі,\nЯк кожний цвіт складає Тобі пошану,\nІ як обняв любов’ю Ти усіх,\n\nКуплет - Приспів 1: \nТоді, Господь, мій дух співа Тобі:\nЯк славен Ти! Як славен Ти! (2р)\n\nКуплет 2\nКоли дивлюсь на мерехтючі зорі - \nТам, де горять світи незнані нам,\nДе сонце й місяць в вічному просторі \nПливуть в тиші, подібно кораблям;\n\nКуплет - Приспів 1: \nТоді, Господь, мій дух співа Тобі:\nЯк славен Ти! Як славен Ти! (2р)\n\nКуплет 3\nКоли Господь мене Сам закликає,\nІ світить промінь сяєва Його, - \nТоді мій дух в смиренні замовкає,\nПризнавши велич Господа свого.\n\nКуплет - Приспів 1: \nТоді, Господь, мій дух співа Тобі:\nЯк славен Ти! Як славен Ти! (2р)\n\nКуплет 4\nSeñor mi Dios, al contemplar los cielos\nEl firmamento y las estrellas mil\nAl oir Tu voz en los potentes truenos\nY ver brillar el sol en su cenit.\n\nКуплет 5\nMi corazón entona la canción\nCuan grande es El,\nСuan grande es El', '', '', 'ua', NULL, 8, '2020-11-08', NULL),
(371, 1058, 'Кто то не слышно Я на веки Его', 30, 'Куплет 1\nКто-то не слышно идёт, \nКто-то не зримо парит, \nЭто пришёл мой Господь \nС сердцем моим говорит.\n\nКуплет2\nЧудные мысли слова,\nВ сердце как песня звучат,\nИ раздаётся хвала,\nУст мне уже не сдержать.\n\nПриспів\nЯ навеки Его, Стал я Богу родным,\nЯ навеки Его, Запечатлён Духом Святым.\n\nКуплет3\nХрам в моём сердце создал, \nБог всемогущий благой,\nИ мне свидетельство дал,\nЧто я навеки Его.\n\nКуплет4\nТроицей запечатлён,\nСимволом вечным Креста,\nИ я искуплен спасён,\nКровью Иисуса Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(372, 1059, 'Сонце співає Приношу все', 30, 'Куплет 1\nСонце  співає в лазурнім світанку,\nСтеле на землю проміння ясні.\nДякую, Боже, за сонячні ранки.\nДякую, Боже, за мир на землі!\n\nПриспів\nПриношу все Тобі до ніг!\nПодяку, радість і печалі!\nДо тебе, Боже, я так біг!\nТож будь зі мною і надалі!\n\nКуплет2\nДень переливами нас зустрічає,\nНебо блакитне мене огорта.\nСкинув тягар,і його більш немає.\nСкинув я все у підніжжя хреста!\n\nКуплет3\nДень промине, і ось вечір вже скоро настане,\nСонячні ранки зайдуть за стежину життя.\nДай і надалі тебе, Боже, з радістю славить.\nЗ піснею радо ввійти у Твоє майбуття!', '', '', 'ua', NULL, 0, NULL, NULL),
(373, 1060, 'Наша жизнь на земле пройдёт', 30, 'Куплет 1\nНаша жизнь на земле пройдёт \nВсё исчезнет в густой темноте. \nВремя нет, но рассвет грядёт, \nТолько чистые узрят Его.\n\nПриспів\nОдна лишь истина на свете есть \nОдин лишь только в мире светит свет, \nХотим мы это слышать или нет. \nНо тьма бежит, когда приходит свет. \nПридёт тот день, но только не для всех, \nИ сердцем чистые узрят Его, \nОн грядёт, тьма умрёт, на всегда.\n\nКуплет 2\nЧеловек посмотри вокруг, \nМир во зле, тьма объяла всё. \nНеужели ты хочешь мук \nОн грядёт, поспеши к нему.\n\nКуплет 3\nОн грядёт, чтоб судить народ, \nТы тогда предстанешь пред Христом. \nИ к тебе прозвучит вопрос, \nСможешь ли дать за всё отчёт.', '', '', 'ua', NULL, 2, '2020-08-23', NULL),
(374, 1061, 'Скоро Він гряде Цей світ', 0, 'Куплет 1\nСкоро Він гряде у Своїй силі і хвалі.\n\"Почуйте всі\" - говорить Він по всій землі.\nДіти Господа, це вже останній час,\nЙого Любов створила світ, Він кличе нас.\n\nКуплет 2\nЦей світ побачить Боже Царство,\nПобачить він Його Любов.\n\nКуплет 3\nСпівай, Алілуя Господу/ 3р.\n\nКуплет 4\nІсус любить всіх, чогож сумний ти тепер\nТи чуєш голос кличе, ти ж почуй лиши його \nВсі свої Гріхи ти визнай перед Ним скоріш.\nІсус заступник перед отцем просить він нас.\nІ ось його ми діти . . .\nІ ось звучать Його слова . . .\nКоли будуть ганьбити, ненавидити і гнати вас\nІ скажуть слово лихе, радій, якщо за Мене це.\n\nКуплет 4\nСпівай, Алілуя Господу/ 3р.', '', '', 'ua', NULL, 1, '2021-02-28', NULL),
(375, 1062, 'Ven Epiritu Ven', 0, 'Куплет 1\n//Ven, Epiritu Ven, \nY llénanos Señor con Tu preciosa unción.//\n\nПриспів\nPurifíame y lávame, renuévame, \nRestaurame Señor, con Tu poder!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(376, 1063, 'У пещеры', 0, 'Куплет 3\nУ пещеры стоит в печали, тихо плачет одна душа,\nА у гроба отвален камень, и исчезло тело Христа\nНо вот ангел предстал перед нею: « Ты во гробе Его не ищи,\nОн Воскрес ты иди поскорее, весть благую друзям принеси»\n\nКуплет 4\nВоскресение Христово, это чудо из чудес\nВоскресение Христово, нам открыло ты двери небес\nВоскресение Христово, в нем спасенье твоей душы\nТак прими же это слово, и к Иисусу поспешы!!!\n\nКуплет 5\nВсе ликуют, моря и суша, Богу славу поют Отцу\nЗа такое спасенье свыше, люди пойте хвалу Отцу,\nОн дарует любовь без меры, исцеляет нашы сердца\nИ когда говоришь Ему: « Верю!», торжествуя поют небеса.', '', '', 'ua', NULL, 0, NULL, NULL),
(377, 1064, 'Чи не знаєш ти Співай Алілуя', 0, 'Куплет 1\nЧи не знаєш ти хто так страждав на хресті?\nХто кров Cвою, життя відав Своє, за тебе вмер.\nЧи не знаєш ти, що Божий Син прийшов з небес,\nЩоб знять тягар гріха твого, звільнити від нього.\nІ ось Його ми діти, і ось звучать Його слова,\nКоли будуть ганьбити, ненавидіти і гнати вас,\nІ скажуть слово лихе радій, якщо за Мене це!\n\nПриспів\nСпівай Алілуя, співай Алілуя,\nСпівай Алілуя Господу.\n\nКуплет 2\nІсус любить всіх, чого сумний ти тепер,\nТи чуєш голос кличе, ти ж почуй лише Його.\nВсі свої гріхи ти визнай перед Ним скоріш,\nІсус Заступник наш, перед Отцем простить їх нам.\nІ знов хвала із уст польється, і знов хвала сповнить серця,\nІ мир Божий ваші думки у Христі лиш збереже,\nІ ось серце славить знов, славить знов ім’я Христа!\n\nКуплет 3\nО, хай вихваляють Тебе і хай славлять Тебе народи всі \nЙ племена земні,\nНехай святиться Боже Твоє Ім’я святе,\nЯк на небі, як на небі, так і на землі,\nТож хай лине слава в небо.\n\nКуплет 4\nІсус, славлю Господи твоє святе ім’я,\nНе відверни Свого лиця,\nХай лине слав від нас в небеса,\nАлілуя!', '', '', 'ua', NULL, 5, '2021-04-02', NULL),
(378, 1065, 'Графік Таблиця', 0, 'Куплет 1\nМолитви\n12:00 - Іван Л.\n13:00 -\n14:00 -\n15:00 - \n16:00 - \n17:00 - \n18:00 - \n19:00 -\n\nКуплет 2\n20:00 - \n21:00 - \n22:00 - Денис\n23:00 - \n24:00 - \n01:00 - Альберт\n02:00 -Діма Т.\n\nКуплет 3\n03:00 - Антон\n04:00 - Руслан\n05:00 - Сергій Й.\n06:00 - Вася Н\n07:00 -\n08:00 -\n09:00 -\n10:00 -\n11:00 -', '', '', 'ua', NULL, 0, NULL, NULL),
(379, 1066, 'О благодать спасенний я', 30, 'Куплет 1\nО благодать - спасенний я\nМене Господь звільнив\nХоч мертвим був - вдихнув життя\nСліпим був та прозрів\n\nКуплет 2\nЦе благодать забрала страх\nІ Божий страх дала\nУ серце спокій принесла\nКоли повірив я\n\nКуплет 3\nГосподь добро пообіцяв\nІ вірний буде Він\nМій щит і частка Він моя\nТвердиня моїх днів\n\nКуплет 4\nВже охолоне сонця жар\nЗемля припинить рух\nА я Отцю на небесах\nСпіватиму хвалу', '', '', 'ua', NULL, 1, '2021-02-28', NULL),
(380, 1068, 'І в голос і в Як злі підходять', 0, 'Куплет 1\nЯк злі підходять дні, - до кого йти мені\nКому відкрити душу свою можу?\nПідходить близько гріх, я падаю до ніг,\nЗ молитвою іду до Тебе, Боже.\n\nПриспів\nІ в голос, і в тиші, і в серці, і в душі\nЯ розмовляю з Тим, Кого не бачу.\nТа сумніву нема — Він чує всі слова,\nІ сльози витирає, коли плачу.\n\nКуплет 2\nДосвітньої пори я стану на поріг\nНового дня з молитвою живою.\nЗ молитвою в устах закінчить хочу шлях, -\nЩоб увійти до вічного спокою.\n\nКуплет 3\nІ сумніву нема — відступиться зима,\nКоли молитви жар в душі палає.\nЗ молитвою життя відкриє майбуття,\nЩо з вірою душа моя чекає.', '', '', 'ua', NULL, 0, NULL, NULL),
(381, 1069, 'Він буде вічно Ти віддай', 0, 'Куплет 1\nВін буде вічно любити тебе,\nБлакитне небо в твоїх очах.\nВін бачить розпач твій та твій страх,\nТи віддай всі турботи Йому!\n\nПриспів\nТи віддай все в руки Бога\nВсі печалі, страхи свої,\nВін - надія, Він – допомога,\nВ ньому спокій твоїй душі.\n\nКуплет 2\nІ коли в тебе немає сил,\nТи хворе серце Йому неси.\nТвою молитву почує Він,\nІ понесе у долонях Своїх', '', '', 'ua', NULL, 9, '2021-03-03', NULL),
(382, 1070, 'Господь грядёт', 0, 'Куплет 1\nГосподь грядёт с силою и славою, \nГосподь грядёт на облаках. \nС небесным воинством, вечною державою, \nИ Книга Жизни в Его руках. \nГосподь грядёт с силою и славою \nСобрать с полей созревший плод. \nПожни скорей! Восклицают ангелы, \nНа землю серп упадёт.\n\nПриспів\nДавно жатва созрела, давно дала свой плод,\nСпеши на Божье дело, Дух Святой зовёт. \nДавно жатва созрела, скорей, время не ждёт, \nСпеши на Божье дело, Дух Святой зовёт.\n\nКуплет 2\nГосподь грядёт, близок уж всему конец,\nБудь Ему верен не на словах. \nДля званных, избранных приготовил Он венец, \nНаграды верным на небесах. \nГосподь грядёт, ибо так написано: \nУзрит Его всякий народ. \nПока есть время, облекайся истиной\nИ простирайся вперед!', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(383, 1071, 'Графік Головний', 0, 'Куплет 1\nПн. - 21:00   Молитва.\nСр. - 21:00   Молитва.\nПт. - 21:00   Молитва.\n!!!             !!!                !!!\n\nКуплет 1\nПн. - 21:00 Молодіжне.\nСр. - 21:00 Зібрання Молитовне.\nПт. - 21:00 Розбір Слова Божого.\nНд. - 10:00 Євангелізація на \" Aluche\"\n         11:00 Молитва в класі.\n         12:00 Загальне Зібрання.\n!!!             !!!                !!!', '', '', 'ua', NULL, 0, NULL, NULL),
(384, 1072, 'Обрати взор на О излей от Духа', 0, 'Куплет 1\nОбрати взор на Свой народ, \nИссохла земля и ждёт дождя. \nМы Тобой не забыты, это мы оставили Тебя, \nНо мы хотим возвратиться в дом Отца.\n\nПриспів\nО, излей от Духа на Свои народы,\nО, пролей потоки, мы жаждем Тебя. \nО, излей от Духа на Свои народы, \nО, пролей потоки, мы жаждем Тебя!!!\n\nКуплет 2 \nТы Первый и Последний,\nГосподь Саваоф, Ты наш Искупитель, и нет других Богов. \nТы Первый и Последний, Господь Саваоф, \nТы наш Искупитель, и нет других Богов!\n\nКуплет 3 \nМы жаждем Тебя, жаждем Тебя\nЖаждем Тебя, Дух Святой', '', '', 'ua', NULL, 5, '2021-03-15', NULL),
(385, 1073, 'Ми в Господні брами', 30, 'Куплет 1\nМи в Господні брами входим, славословлячи\nІ в подвір\'я ми Його з хвалою йдем.\nДля народу Він Свого подарував цей день,\nЗаспіваймо вдячних, радісних пісень.\n\nПриспів\nВін дарує радість, Ісус дарує радість,\nІ радіють в Господі серця.\nВін дарує радість, Ісус дарує радість,\nТож, хай славлять Господа серця.\n\nКуплет 2\nМи складаємо подяку Богу, добрий бо Він,\nПосилає необхідне все для нас.\nПоновляє Він над нами ласку кожен час,\nБо навіки Його милість є до нас.\n\nКуплет 3\nМи співаємо хвалу Христу – Спасителю\nЗа любов, що перевищує знання,\nВ небесах чудове місце Він побудував,\nДе зібрати усіх вірних обіцяв.', '', '', 'ua', NULL, 1, '2020-09-27', NULL),
(386, 1074, 'Господь', 30, 'Куплет 1\n	Господь! Даруй Ты мне слова такие,\n 	Чтоб, восприняв людскую боль,\n 	Открыть скалой спасительной Мессию\n 	Голгофский крест с текущею рекой.\n\nПриспів\n --тут слова приспіву\n\nКуплет 2\nТечет река (течет река) за все грехи людские – Цена любви к погибшим сыновьям. \nТечет река (течет река) – и нет на свете силы, Чтоб умалила подвиг Господа. \n 	Господь Иисус, любовью неземною \n 	Наполни мое сердце, чтоб всегда \n 	Чужая боль с чужой бедою \n 	Неслась в молитвах к Богу, как своя. \nНо если люди за любовь такую, \nНе восприняв венец терновый мне дадут Молитву чистую, святую: \nПрости им, Отче, – пусть уста произнесут.', '', '', 'ua', NULL, 0, NULL, NULL),
(387, 1075, 'Течет река течет река', 0, 'Куплет 1\nГосподь! Даруй Ты мне слова такие,\nЧтоб, восприняв людскую боль,\nОткрыть скалой спасительной Мессию\nГолгофский крест с текущею рекой.\n\nПриспів\nТечет река (течет река) за все грехи людские –\n Цена любви Отца к погибшим сыновьям. \nТечет река (течет река) – и нет на свете силы, \nЧтоб умалила подвиг Господа.\n\nКуплет 2\nГосподь Иисус, любовью неземною \nНаполни мое сердце, чтоб всегда \nЧужая боль с чужой бедою \nНеслась в молитве Богу, как своя.\n\nКуплет 3\nНо если люди за любовь такую, \nНе восприняв венец терновый мне дадут \nМолитву чистую, святую: \nПрости им, Отче, – пусть уста произнесут.', '', '', 'ua', NULL, 0, NULL, NULL),
(388, 1076, 'Будь прославлений Ім’я Ісуса дороге', 0, 'Куплет 1\nБудь прославлений,\nЯк рясний плід дає земля,\nЯк достатку тече ріка,\nБудь прославлений!\n...           ...           ... \nБудь прославлений,\nЯк пустеля самотня скрізь,\nЯк іду по долинах сліз,\nБудь прославлений!\n\nПриспів\nКожен дар Твій повертаю Тобі в хвалі,\nКоли темінь наступає, кажу Тобі:\nБудь благословен навіки! Будь благословен!\nБудь благословен навіки!\nГосподи мій, будь благословен!\n\nКуплет 2\nБудь прославлений,\nКоли радість цвіте в мені,\nКоли світлі приємні дні,\nБудь прославлений!\n...           ...           ... \nБудь прославлений,\nКоли в серці страждання й сум,\nКоли тяжко свій хрест несу,\nБудь прославлений!\n\nКуплет 3\nТи дав, і Ти узяв, \nТи дав, і Ти узяв,\nСлова ж мої без змін: \nО, будь благословен!', '', '', 'ua', NULL, 6, '2021-01-31', NULL),
(389, 1077, 'Отче Наш Тайное желание', 30, 'Куплет 1\nОтче Наш, Сущий на Небесах, \nДа, святится имя Твоё. \nЖизнь мою держишь в Своих руках, \nМир вокруг на ладонях Твоих.\n\nПриспів1\nТайное желание в сердце Ты Своём сокрыл,\n Кто увидит боль Твою за вселенную? \nЦепи ада разорвал, выкуп смерти заплатил, \nВремя Царства Твоего, Царство Твоё пришло!\n\nКуплет 2\n Голос Свой поднимал за меня, молясь, \nКо кресту руки пригвождены. \nНе могу промолчать о Твоей любви, \nНа земле Тебе славу верну!\n\nПриспів2\nДа, будет воля Твоя!\nДа, будет слава Твоя! \nДа, будет сила Твоя на земле людей! \nЯ – твои руки, Господь! \nЯ – Твои ноги, Господь! \nГолосом буду Твоим, \nЧтобы Царство Твоё пришло!\n\nКуплет3\nДай мне быть светом Твоим, \nГосподь! Сердце Отца для меня всех дороже. \nБуду жить, чтоб исполнить мечту Твою, \nЦарство Твоё на земле, как на Небе.', '', '', 'ua', NULL, 0, NULL, NULL),
(390, 1078, 'Я є тут вклоняюсь', 0, 'Куплет 1\nЯ є тут вклоняюсь Тобі мій Бог\nВсе віддаю, все віддаю\nМене знайде серце моє візьме\nПотрібно лиш Ти.\n\nКуплет2\nТи звільнив душу мою зцілив\nДо мене звернись слово скажи\nЯ кричу руки свої здіймо\nЯ прагну Тебе.\n\nКуплет 3\nПідкоряюсь, підкоряюсь хочу знати Тебе\nБільше знати Тебе!!!\n\nКуплет 4\nНаче буревій розбуди дух мій \nТвоє життя, Твоє життя мені\nЯк ми могутній шторм розбуди знов твоє життя!', '', '', 'ua', NULL, 0, NULL, NULL),
(391, 1079, 'Light of the Ось я щоб схилитись', 30, 'Куплет 1\nLight of the world, you stepped down into darkness.\nOpened my eyes, let me see,\nBeauty that made this heart adore you.\nHope of a life spent with you!\n\nКуплет2\nHere I am to worship, here I am to bow down.\nHere I am to say that You´re my God,\nYou´re all together lovely, all together worthy.\nAll together wonderful to me!\n\nКуплет 3\nKing of all days, oh so highly exalted.\nGlorious in Heaven above,\nHumbly You came to the Earth You created.\nAll for love´s sake became poor!\n\nКуплет4\nОсь я щоб схилитись Ось я щоб вклонитись.\nОсь я щоб сказати Ти мій Бог,\nТи моя твердиня Ти моє спасіння.\nТи моє натхнення Мій Господь!\n\nКуплет5\nVine adorarte, Vine a postrarme\nVine a desirte que eres mi Dios\nSolo tu eres grande, solo tu eres digno\nEres asombroso para mi', '', '', 'ua', NULL, 0, NULL, NULL),
(392, 1080, 'Люби когда Твоя любов', 8, 'Куплет 1\nЛюби, когда другой тебя толкает.\nЛюби, когда другой не понимает,\nЛюби, когда другойтебя подводит.\nЛюби, когда другойтибя обходит!\n\nПриспів\nТвоя любов границ не знает,\nНо жаль, на деле нетту громких слов...!\nХриста любовь на деле отражает,\nЧто Бог один есть вечная Любовь!!!\n\nКуплет 2\nЛюби, когда увидишь лицимере.\nЛюби, когда заметишь недоверие,\nЛюби, когда фалшивость в сердце встречешь.\nЛюби, когда любовь ты не приметышь!\n\nКуплет3\nЛюби - любовь другого не толкает.\nЛюби - любовь другого Понимает,\nЛюби - любовь другого необходит.\nЛюби - любовь другого не подводит!!!', '', 'СИb мажор', 'ua', NULL, 0, NULL, NULL),
(393, 1081, 'Отпускаю', 30, 'Куплет 1\nОтпускаю все мечты мои,\nЯ полагаю их у ног Твоих\nЕсли в жизни ошибаюсь я,\nТвоя любовь не изминяется\n\nПриспів\nХотель сражится я з\n\nКуплет 2\n --тут слова другого куплету', '', '', 'ua', NULL, 0, NULL, NULL),
(394, 1089, 'No soy capaz de comprender Я бога серцем', 0, 'Куплет 1\nNo soy capaz de comprender\nSu voluntad y su poder.\nSolo sé que a su diestra esta\nQuien mi alma ha salvado.\n\nКуплет2\nTomo su ejemplo y predicción\nCristo me dio su salvación\nY yo siento en mi corazón\nEs Él quien me ha salvado\n\nКуплет3\nQue desde el cielo el bajo,\nY por el pecado murió\nTe suena extraño si tu no,\nConoces a quien me ha salvado.\n\nКуплет4\nEl me ama a mí, Él vive aquí\nCon el siempre puedo contar\nMi Dios él es, mi dios él fue\nMi Dios él siempre lo será.\n\nКуплет5\nЯ бога серцем всім люблю Йому все я відаю \nІ знаю буду я в раю чикає там, Спаситель!\n\nКуплет 6\nПрестол залишив, в світ зійшов \nЗа гріх людей пролив Він кров\nПовірив я в його любов\nТепер він мій спаситель\n\nКуплет 7\nМій Бог - любов мій Бог живий\nСпаситель поряд ти завжди\nБог ти був мій Бог ти є\nІ будеш вічно з нами Ти!', '', '', 'ua', NULL, 1, '2020-12-06', NULL),
(395, 1090, 'Будь прославлений', 30, 'Куплет 1\nБудь прославлений!\nЯк рясний плід дає земля.\nЯк достатку тече ріка.\nБудь прославлений!\n\nКуплет 2\nБудь прославлений!\nЯк пустеля самотня скрізь.\nЯк іду по долинах сліз.\nБудь прославлений!\n\nКуплет-Приспів\nКожен дар Твій повертаю, Тобі в хвалі. \nКоли темінь наступає, кажу Тобі:\n// Будь благословен навіки! \nБудь благословен!\nБудь благословен навіки! \nГосподи мій, будь благословен! // - 2р.\n\nКуплет 3\nБудь прославлений!\nКоли радість цвіте в мені.\nКоли світлі приємні дні.\nБудь прославлений!\n\nКуплет 4\nБудь прославлений!\nКоли в серці страждання й сум.\nКоли тяжко свій хрест несу.\nБудь прославлений!\n\nКуплет-Приспів\nКожен дар Твій повертаю, Тобі в хвалі. \nКоли темінь наступає, кажу Тобі:\n// Будь благословен навіки!\nБудь благословен!\nБудь благословен навіки! \nГосподи мій, будь благословен! // - 2р.\n\nКуплет-Брідж\n// Ти дав, і Ти узяв, Ти дав, і Ти узяв,\nСлова ж мої без змін: О, будь благословен! // - 2р.\n\nКуплет-Приспів\n// Будь благословен навіки!\nБудь благословен!\nБудь благословен навіки! \nГосподи мій, будь благословен! // - 2р.', '', '', 'ua', NULL, 4, '2020-12-21', NULL),
(396, 1091, 'Ісус Ти найкращий Друг', 30, 'Куплет 1\nІсус, Ти - найкращий Друг.\nВ час, коли моє серце плаче,\nЯ до Тебе в молитві йду,\nТи поможеш мені, мій Пастир.\n\nКуплет 2\nДля дущі Ти моєї спокій\nТи відрада моя, Спаситель,\nПідкріпляєш у боротьбі\nВірний Друг і душі Втішитель! \n\nКуплет 3\nЯ любов\'ю Твоєю живу,\nІ вона моє серце гріє.\nЩиро, Спасе, Тебе я люблю,\nІ ніхто вже Тебе не замінить.\n\nКуплет 4\nТи Один розумієш все\nВсі думки потаємні знаєш.\nТи зі мною, у кожну мить\nПотішаєш і підкріпляєш.\n\nКуплет 5\nХай полине подяка Тобі\nЗа щедроти і вічну милість.\nО, Ісус, Ти - Спаситель душі,\nТи є щастя моє і радість!\n\nКуплет 6\nЯ любов\'ю Твоєю живу,\nІ вона моє серце гріє.\nЩиро, Спасе, Тебе я люблю,\nІ ніхто вже Тебе не замінить.', '', '', 'ua', NULL, 13, '2021-03-14', NULL),
(397, 1092, 'Поднимаю глаза Небо небо небес', 0, 'Куплет 1\nПоднимаю глаза, и смотрю в небеса:\nТам я вижу Христа, одесную Отца.\nНебо, небо небес, приготовил Он мне,\nЦель моя и мечта – неба вся красота.\n\nПриспів\n     Небо, небо небес \n     Город вечных чудес,\n     Я мечтаю о нём,\n     Там мечтаю и здесь.\n     Небо, небо небес,\n     Путь туда через крест.\n\nКуплет 2\nЧтобы в небо попасть, нужно жизнь так прожить,\nЧтобы Бог мог сказать: «Ты достоин в нём жить».\nТы достоин смотреть Иисусу в глаза,\nЕсли только войдёшь ты к Нему в небеса.\n\nКуплет 3\nНе слыхал человек, и не видел то глаз,\nКак там в небе небес, что там будет для нас?\nНо я знаю одно: красотой всех небес\nБудет тот, кто понёс на Голгофу наш крест.', '', '', 'ua', NULL, 2, '2020-11-15', NULL),
(398, 1093, 'В жизни кому Я любовью лелею', 0, 'Куплет 1\nВ жизни кому то я доверять хочу\nЖить для кого то, кто б окружал своей нежностью\nЭту любовь к Тебе я могу только с небом сравнить\nТы дал мне больше всех дал дар любви\n\nПриспів\n  Я любовью лелею, в душе моей она как сладкий сон\n  Любовь эта вечна, в небе радуга моя\n  Теплей солнца света, лучше летнего дождя\n  Ветерок этот нежный подымает ввысь меня\n\nКуплет 2\nЕсли я ранен или одинок, мне нужен кто то\nКто б вдохновить меня в жизни смог\nКто бы мог укреплять чтобы быть сильным\nЧтобы быть добрым \nТы дал мне больше всех дал дар любви\n\nКуплет 3\nДолго искал я встречи любовь с тобой\nТы мне открылась нежной и светлой, чистой такой\nЭту любовь к Тебе я могу только с небом сравнить\nТы дал мне больше всех дал дар любви', '', '', 'ua', NULL, 0, NULL, NULL),
(399, 1094, 'Господи благослови', 0, 'Приспів:\nГосподи, благослови наш край\nЖить, любити і вірити навчай\nДіти ми твої, молимось Тобі\nТи в проханні нам не відкажи.', '', '', 'ua', NULL, 0, NULL, NULL),
(400, 1095, 'О Боже', 0, 'Куплет 1\n               О Боже, дай нам з неба миру, \n               в кожну сім`ю, в кожну родину. \n               Благослови всю Україну, \n               Підтримай в тяжку годину.', '', '', 'ua', NULL, 0, NULL, NULL),
(401, 1096, 'До Тебе Господь О Боже дай', 0, 'Куплет 1\nДо Тебе Господь, у молитві йдемо,\nі в Тебе розради шукаєм.\nМогутній і Сильний зупиниш Ти зло\nі зглянешся над нашим краєм.\n\nПриспів:\nО Боже дай нам з неба миру,\nв кожну сім`ю, в кожну родину.\nБлагослови всю Україну,\nпідтримай в тяжку годину.\n\nКуплет 2:\nВ покорі сердець Боже ми стоїмо\nі вірим в Твоє проведіння.\nХто любить Тебе, все для них на добро.\nЧекаємо Твого спасіння\n\nКуплет 3:\nВід зору Твого не захований світ,\nТи знаєш думки всі людини.\nТеплом милосердя Свого нас зігрій.\nЗгадай про народ України.', '', '', 'ua', NULL, 0, NULL, NULL),
(403, 1098, 'Благословен благословен', 0, 'Куплет1: \nБлагословен тот дом, \nгде в каждом чистом сердце, \nСлово Святое Господа живёт. \nНет власти тьмы и страха смерти, \nИ Сам Господь в тот дом Хозяином войдёт.\n\nПрипев: \nБлагословен, благословен, \nБлагословен, тот дом. \nБлагословен, благословен, \nБлагословен, тот дом.\n\nКуплет2:\nБлагословен тот дом, где в тихий час молитвы, \nДухом Святым Господь касается сердец. \nГде радость и счастье любви в избытке,\nИ благодать излил Небесный наш Отец.\n\nКуплет3:\n Благословен тот дом,\n Где старость уважают, \nГде веру свято берегут из рода в род. \nСлавят Творца и Библию читают, \nИ возрастают в мудрости из года в год.', '', '', 'ua', NULL, 0, NULL, NULL),
(404, 1099, 'Эта песня хвалыОкеан Божьей любви', 0, 'Куплет 1\nЭта песня хвалы, словно птица, парит в небеса, а-а-а.\nМоя жизнь как река - моё сердце течёт и душа поет для Тебя.\nЭта песня хвалы, как весенний родник, как любви водопад.\nМоя жизнь как река - моё сердце течёт я вдыхаю любви аромат.\n\nПрипев:\nОкеан Божьей любви - нет начала в нём и нет конца.\nОкеан Божьей любви, безусловной любви Отца.\nОкеан Божьей любви - нет начала в нём и нет конца.\nОкеан Божьей любви, безусловной любви Отца.\n\nКуплет2 Мост:\nСлава, Аллилуйя, Слава Аллилуйя,\nСлава, Аллилуйя, Аллилуйя.\nСлава, Аллилуйя, Слава Аллилуйя,\nСлава, Аллилуйя, Аллилуйя.\n\nКуплет3:\nТы осколки все сердца мои вновь собрал, Мой Господь, а-а-а.\nКак горшечник, слепил и его оживил бесконечной любовью Отца.\nТолько шрамы остались, но боль вся ушла, и Твой мир наполнил меня.\nМоя жизнь как река - моё сердце течёт я вдыхаю любви аромат.\n\nКуплет4:\nБуду петь для Тебя, буду славить Тебя без конца, а-а-а.\nНеизменный, Святой, самый лучший Друг мой - я люблю всем сердцем Тебя.\nТы со мною всегда, не оставишь меня - Ты защита, помощь моя.\nМоя жизнь как река - моё сердце течет я вдыхаю любви аромат.', '', '', 'ua', NULL, 4, '2020-06-15', NULL),
(405, 1100, 'Боже Ты Бог мой Святый Бог', 30, 'Куплет 1\nБоже, Ты Бог мой\nТебя от ранней зари ищу я\nТебя жаждет душа моя\n  По Тебе томится плоть моя\n  Дай мне видеть Твою славу\n  Твою силу, вечный Бог.\n\nПриспів\nСвятый, Святый Бог\nО Святый, Святый Бог!!!\n\nКуплет 2\nКогда вспоминаю о Тебе,\nО том что сделал в жизни моей.\nСнова сердце в руках Твоих!\n  Я вознесу к небу руки свои,\n  Дай мне видеть Твою славу.\n  Твою силу, вечный Бог!\n\nПрипев Іпstrumепtаl::\nКак люблю я Тебя люблю я.\nМилость Твоя лучше чем жизнь.\nУста мои прославят!', '', '', 'ua', NULL, 0, NULL, NULL),
(406, 1101, 'Я сокрыт в Тебе Бог Я дождусь дотянусь', 0, 'Куплет 1\nЯ сокрыт в Тебе, Бог, вне Тебя меня нету \nКак сквозь камни росток, призываемый светом \nМой измученный дух, Тебя жаждет и алчет \nТы придешь ко мне вдруг, быть не может иначе.\n\nПриспів\nЯ дождусь, дотянусь, докричусь до небесного трона \nО, Иисус, я молюсь, я склонюсь, забери мои стоны\n\nКуплет 2\nБез любви задохнусь, и умолкну так рано \nНо к Тебе я прорвусь, прикоснусь к Твоим ранам \nВдруг по жилам тепло, потечет в мое сердце \nИ смертям всем на зло, я Тобою воскресну, Иисус\n\nКуплет 3\nЯ сокрыт в Тебе, Бог, вне Тебя меня нету!', '', '', 'ua', NULL, 0, NULL, NULL),
(407, 1102, 'Хто подібний О Адонай', 30, 'Куплет 1\nХто подібний є такий, як Він -\nАгнець, Божий Син?\nЛев могутній, що на троні Він,\nГори й океан співають:\n\nПриспів\nО Адонай! На світанку і вночі\nЙого славлять всі святі.\nО Адонай! Всі народи на землі\nЙ з ними ангели святі в хвалі.\n\nКуплет 2\nХто подібний є такий, як Він -\nАгнець, Божий Син?\nЗорі Божі, воїнства небес\nГосподу хвалу співають:\n\nКуплет3\nХто подібний є такий, як Він -\nАгнець, Божий Син?\nЦерква Божа псалмами хвали\nУ серцях своїх співає:', '', '', 'ua', NULL, 2, '2020-09-27', NULL),
(408, 1103, 'Більше ніж Я прагну', 30, 'Куплет 1\nБільше ніж пісня моя,\nБільше ніж гарні слова.\nПонад усе я знайшов.\nТвою незрівнянну любов!\n\nПриспів\nЯ прагну Тебе Ісус\nЯ прагну Тебе мій Бог \nЯ прагну Тебе Ісус \nЯ прагну Тебе!!!\n\nКуплет 2\nНе осягну до кінця \nЛюбов, що прийшла від Отця \nНе заслужив я її \nТа вона гріхи прощає мої!\n\nКуплет3 / БРІДЖ:\nТільки Твоя любов найбільша \nНі з чим не зрівняти її\nІ навіть якщо весь світ обшукати \nТакої як Твоя не знайти!', '', '', 'ua', NULL, 0, NULL, NULL),
(409, 1104, 'Бог Ты пришёл Ты Царь вечности', 0, 'Куплет 1\nБог, Ты пришёл в Своей славе, \nБог, Ты явил нам любовь \nБог, Ты принёс исцеление \nЛюдям спасение принёс!\n\nПриспів: \nТы Царь вечности, Царь величия. \nТы - Бог милости, преклоняюсь я!\nТы Бог истинный, Ты величествен, \nТы со мной всегда, преклоняюсь я!\n\nКуплет 1\nБог, Ты пришёл в Своей славе, \nБог, Ты явил нам любовь \nБог, Ты принёс исцеление \nЛюдям спасение принёс!\n\nКуплет 2 / БРИДЖ: \nПреклонюсь пред Тобой, \nМой Господь, мой Бог, \nТы излей благодать!!!', '', '', 'ua', NULL, 1, '2021-03-07', NULL),
(410, 1105, 'До Тебе ялину Ти моя надія', 30, 'Куплет 1\nДо Тебе ялину, Господь мій, всім серцем моїм\n Ти моя надія, Надія, що не вмирає.\nПрийшов як людина, на землю із святих небес,\nПомер за гріх людства, але із мертвих Ти воскрес.\n\nПриспів\nТи моя надія,\nНадія що не вмирає.\nТи спас мою душу,\nГосподь мій.\nЯ тебе прославлю!\n\nКуплет 2\nКоли згасни віра, то в серце приходить печаль\nЗгадаєнадія,надія яка не вмирає,\nІсус є Господь твій, Він вірний в слшові життя\nСпасе твою душу, дасть віру, Йогт майбуття.\n\nПриспів\nТи моя надія,\nНадія що не вмирає.\nТи спас мою душу,\nГосподь мій.\nЯ тебе прославлю!\nЯ тебе прославлю///Господь мій ісус!', '', '', 'ua', NULL, 0, NULL, NULL),
(411, 1106, 'Будь прославлений Будь благословен', 30, 'Куплет 1\nБудь прославлений, як рясний плід дає земля,\n Як в достатку тече ріка, будь прославлений. \nБудь прославлений, як пустеля самотня скрізь, \n Як іду по долинах сліз, будь прославлений.\nКожен дар Твій повертаю Тобі в хвалі. \nКоли темінь наступає, кажу Тобі:\n\nКуплет - ЗАСПІВ: \nКожен дар Твій повертаю Тобі в хвалі. \nКоли темінь наступає, кажу Тобі:\n\nПриспів2\nБудь благословен навіки! \n Будь благословен. \nБудь благословен навіки! \nГосподи мій, будь благословен!\n\nКуплет 2\nБудь прославлений коли радість цвіте в мені \nКоли світлі приємні дні будь прославлений \nБудь прославлений коли в серці страждання й сум \nКоли тяжко свій хрест несу будь прославлений.\n\nПриспів 3\nТи дав, і Ти узяв, \nТи дав, і Ти узяв, \nСлова ж мої без змін: \n...      ....     ...\nО будь благословен!', '', '', 'ua', NULL, 3, '2021-03-21', NULL),
(412, 1107, 'Твердо я вірю Тепер я славлю', 0, 'Куплет 1\nТвердо я вірю, мій любий Спас,\nНим я радію, бо Він мене спас;\nНебо в дарунок хоче Він дать,\nЯк же приємно з Ним пробувать.\n\nПриспів\nТепер я славлю Його щодня,\nБо Його ласка мене спасла.\nВічно я буду славить Його.\nДивного Друга, Спаса мого!!!\n\nКуплет 2\nТвердо я вірю: з часу того,\nЯк я повірив, дитя я Його;\nСповнює спокій за майбуття,\nВ Нім я знаходжу все для життя.\n\nКуплет 3\nТвердо я вірю в Спаса мого,\nСкрізь відчуваю турботу Його;\nЩоб там не сталось – радісний дух:\nВічно зі мною мій вірний Друг.\n\nКуплет 4\nСпокій чудесний, спокій святий\nДух мій знаходить в любові Твоїй;\nДай, щоб Тобі я серце віддав,\nЯ б умалявся, Ти б виростав.', '', '', 'ua', NULL, 3, '2020-07-05', NULL),
(413, 1108, 'Небеса проповедуют Тебе вся слава', 30, 'Куплет 1\nНебеса проповедуют славу Твою\nО делах Твоих рук вещает Земля\nНет места нигде, чтобы Ты мой Бог не вел меня \nИбо я знаю, в Тебе укроюсь я\n\nПриспів1\nТебе вся слава, Тебе вся жизнь моя!\nТебе принадлежу всецело я!\nТебе вся слава, Тебе вся жизнь моя!\nТебе поклоняюсь, в Тебе укроюсь я!\n\nКуплет 2\nВся Земля полна Твоей Славы, Ты – Творец всего, я знаю,\nВозвещать буду я дела Твои,\nЗа Тобой, мой Бог пойду я,\nЖизнь свою Тебе я посвящу, ведь знаю я!\n\nКуплет3 БРИДЖ:\nВся Слава Неба и Земли\nПоют Тебе в смирении:\n«Достоин, достоин Ты»\nВся жизнь моя у Твоих ног\nВзывает: «приди ко мне, мой Бог»\nДостоин, достоин Ты!!!', '', '', 'ua', NULL, 3, '2020-06-14', NULL),
(414, 1109, 'Хтось говорить/Ти благий', 30, 'Куплет 1\nХтось говорить, що Тебе - нема \nХтось говорить, що далеко Ти \nТа знаю я, що Ти живеш в мені \nМоє серце у Твоїх руках\n\nПриспів\nТи благий і любов Твоя навіки!\nТи благий і любов Твоя навіки!\nТи благий і любов Твоя навіки!\nТи благий, Ти благий... !\n\nКуплет 2\nХтось говорить, що не чуєш Ти, \nХтось говорить, що не бачиш Ти. \nТа знаю я,  що Ти присутній скрізь,\nНа всіх шляхах земних ведеш мене!\n\nКуплет 3\nХтось говорить, що Ти не воскрес,\nХтось говорить, не вмирав за нас,\nТа знаю я, Ти кров Свою пролив\nВоскрес, щоб и з Тобою вічно жив!\n\nКуплет 4\nТи є лише один. \nМоя душа Тебе бажає. \nТи є лише один мій Цар!', '', '', 'ua', NULL, 1, '2021-01-03', NULL),
(415, 1110, 'Я іду до мети Я все зможу', 30, 'Куплет 1\nЯ іду до мети так в дорозі слабію,\nІ здається, що вже не під силу іти.\nТа в душі ще надія жевріє-жевріє,\nІ приходять слова із писання мені.\n\nПриспів\nЯ все зможу в Тім, Хто мене підкріпляє, \nЯ все зможу в Тім, Хто мене утішає,\nЯ все зможу в Тім, Хто мене підіймає.\nЯ все зможу в Христі однім!\n\nКуплет 2\nЯ дійду до мети та отримаю вічність,\nІ зустрінусь із Тим, Хто мене підкріпляв.\nНе дам місця журбі і тривожним злим вістям, \nБо мій Бог у біді мене не залишав.', '', '', 'ua', NULL, 0, NULL, NULL),
(416, 1111, 'Славимо ми славимо Давай будемо', 0, 'Куплет 1\nСлавимо, ми славимо,\nСлавимо Святого Отця.\nЛюбимо, ми любимо\nСлавити Його без кінця.\n\nКуплет 2\nДавай будемо ми славити Бога,\nБо Він гідний хвали завжди, завжди.\nМи здіймаєм руки свої до небес \nІ славимо Отця,\nБо нас поєднала в єдину сім’ю \nМилість і любов Творця.\n\nКуплет3\nСлавимо, ми славимо,\nСлавимо Святого Отця.\nЛюбимо, ми любимо\nСлавити Його без кінця.\n\nКуплет 4\nДавай будемо ми співати Христові,\nЩоби наша хвала сягнула небес.\nБо так полюбив нас Отець, що віддав \nСинове життя,\nЩоб ми вічно жили й хвалили Його, \nНашого Творця\n\nКуплет5\nСлавимо, ми славимо,\nСлавимо Святого Отця.\nЛюбимо, ми любимо\nСлавити Його без кінця.', '', '', 'ua', NULL, 10, '2021-03-01', NULL),
(417, 1112, 'Я є тут покірний Величний Бог', 0, 'Куплет 1\nЯ є тут покірний Твоїй величі\nПокритий благодаттю згори\nЯ є тут хоч грішним було моє життя\nТа тепер омитий кров’ю Христа.\n\nКуплет 2 \nОсь я знайшов найбільшу над усе любов\nКоли Ти дав Себе і відкупив мене.\n\nПриспів\nВеличний Бог, Величний Бог\nЗнайшла мене Твоя благодать \nХоч порожнім було моє життя (бо Ти)\nВеличний Бог, Величний Бог\nЛюбов твоя змінила мене\nВсе життя змінила назавжди!\n\nКуплет 2\nЯ є тут в любові яку Ти мені дав \nПрощаю всіх бо прощений сам \nЯ є тут бо бажаним для Тебе я є\nОсвячений кров’ю й вогнем\n\nПриспів\nВеличний Бог, Величний Бог\nЗнайшла мене Твоя благодать \nХоч порожнім було моє життя (бо Ти)\nВеличний Бог, Величний Бог\nЛюбов твоя змінила мене\nВсе життя змінила назавжди!\n\nКуплет 3\nОсь я знайшов найбільшу над усе любов\nКоли Ти дав Себе і відкупив мене.\n\nПриспів\nВеличний Бог, Величний Бог\nЗнайшла мене Твоя благодать \nХоч порожнім було моє життя (бо Ти)\nВеличний Бог, Величний Бог\nЛюбов твоя змінила мене\nВсе життя змінила назавжди!', '', '', 'ua', NULL, 0, NULL, NULL),
(418, 1113, 'Вам наверно знакома Бог тебя никогда', 30, 'Куплет 1\nВам наверно знакома такая усталость,  \nЧто доходит до всех уголочков души,  \nКогда кажется жить уже сих не осталось, \nТы тогда к Иисусу скорее спеши.\n\nКуплет 2\nКогда скорбь высотою до самого неба,\nЗа добро получаешь коварство и ложь – \nБог на помощь придёт всюду, где бы ты не был,\nОн услышит тебя если ты позовешь.\n\nПриспів\nБог тебя никогда, никогда не оставит, \nЕсли будешь надеется, верить, любить.\nИ в огне испытаний Спасителя славить  \nПостарайся об этом, мой друг, не забыть.\n\nКуплет 3\nА порою случается, что неудачи\nНас преследуют в жизни волна за волной.  \nБог противится гордым – но видит, кто плачет,\nОн поможет, живи лишь надеждой одной.', '', '', 'ua', NULL, 0, NULL, NULL),
(419, 1114, 'Достоин достоин Ты прекрасен', 0, 'Куплет 1\nДостоин, достоин, достоин принять славу и честь\nСвятый, Святый, Святый Божий Сын Иисус!\n\nКуплет 2\nТы прекрасен Господь сильный, Господь славный\nНаполняй сердца -2р.\n\nКуплет 3\nДостоин, достоин, достоин принять славу и честь\nСвятый, Святый, Святый Божий Сын Иисус.\n\nКуплет 4\nТы прекрасен Господь сильный, Господь славный\nНаполняй сердца -2р.\n\nКуплет5\nПрекрасен, сильный, славный (только) Ты один.\n\nКуплет\nПервый, последний, великий (только) Ты один.', '', '', 'ua', NULL, 1, '2020-06-17', NULL),
(420, 1115, 'Я вхожу в святое святых Я поклоняюсь Тебе', 40, 'Куплет 1\nЯ вхожу в святое святых,\nЧерез Кровь святую Твою.\nЖизнью Ты Своей заплатил,\nЗа мою свободу в Тебе.\n\nПриспів\nЯ поклоняюсь Тебе, поклоняюсь Тебе.\nЯ поклоняюсь Тебе, поклоняюсь Тебе.\n\nКуплет 2\nПроведи сквозь внешний двор\nНа Твое святое место,\nЯ хочу Твоё видеть лицо, Господь,\nЯ ищу Тебя всем сердцем.\nОт толпы людской возьми меня\nКо святым, поющим песни,\nЖажду праведности Твоей, мой Бог,\nЗдесь единственное место.\n\nКуплет 3\nПроведи во святое святых\nЧерез Агнца кровь проведи\nПроведи во святое святых,\nИ уста мои очисть, вот я!\n\nКуплет 4:\nТвоё Имя - Святой, Святой, Господь', '', 'СОЛЬ минор', 'ua', NULL, 8, '2021-03-24', NULL),
(421, 1116, 'Ктото неслышно идет Я навеки Его', 0, 'Куплет 1 :\nКто-то неслышно идет,\nКто-то незримо парит.\nЭто пришел мой Господь,\nС сердцем моим говорит.\n\nКуплет 2 :\nЧудные мысли, слова\nВ сердце, как песня, звучат,\nИ раздается хвала,\nУст мне уже не сдержать.\n\nПриспів :\nЯ навеки Его, стал я Богу родным.\nЯ навеки Его, запечатлен Духом Святым.\n\nКуплет 3 :\nХрам в моем сердце создал\nБог Всемогущий, благой,\nИ мне свидетельство дал,\nЧто я навеки Его.\n\nКуплет 4 :\nТроицей запечатлен,\nСимволом вечным креста.\nИ я искуплен, спасен\nКровью Иисуса Христа.', '', '', 'ua', NULL, 1, '2020-08-09', NULL),
(422, 1117, 'По всьому світу', 0, 'Куплет 1\nПо всьому світу стала новина:\nДіва Марія Сина родила.\nСіном притрусила,\nВ яслах положила\nГосподнього Сина.\n\nКуплет 2\nЗійшли Ангели з неба до землі,\nПринесли дари Діві Марії:\nТри свічі воскові,\nЩе й ризи шовкові\nІсусови Христови.\n\nКуплет 3\nДіва Марія Бога просила:\n– В що ж би я Сина свого сповила?\nТи, небесний Царю,\nПришли мені дари,\nСього дому господарю.\n\nКуплет4\nЗасіяла звізда з неба до землі,\nЗійшли Ангели к Діві Марії.\nСпівають Їй пісні,\nГосподній Невісті,\nРадости приносять.', '', '', 'ua', NULL, 0, NULL, NULL),
(423, 1118, 'По преданью На скрижалях', 30, 'Куплет1:\nПо преданью отцов человек охранял,\nНа скрижалях Твое откровенье.\nГод за годом его ветер в пыль превращал,\nЧтоб забыло о Боге творенье.\n\nКуплет2:\nНо не букву Закона Господь подарил,\nБлагодати никто не разрушит\nТот, кто искренне Богу всем сердцем служил,\nНе на камне писали, а в души.\n\nПриспів:\nНа скрижалях сердца напиши\nАлой кровью для моей души\nЧтобы помнил о любви Твоей\nВспоминая раны от гвоздей.\n\nКуплет3:\nБоже мой, сотвори веру твёрдой, как камень\nДабы жизнью своей о Тебе рассказать\nМною правь из внутри и душой и руками\nЧтобы в нужный момент все что есть мог отдать\n\nКуплет4:\nНикакая беда почерк Твой не сотрет\nДаже если гоненье вернется\nВоду жизни душа и в пустыне найдет\nИ Любовью Твоей напьется', '', '', 'ua', NULL, 0, NULL, NULL),
(424, 1119, 'Бог Сина в світ Маленьке Дитя', 30, 'Куплет 1\nБог Сина в світ послав щоб, спасіння план звершить.\nСпаситель народився у нічну Різдвяну мить.\nХристос є наш месія, Спаситель всіх людей,\nСвяткуємо перемогу нашу на цей Різдвяний день.\n\nПриспів\nМаленьке Дитя (Маленьке Дитя)\nБог Світові дав (Бог світові дав)\nНічний Віфлеєм Його тихо прийняв (Цей світ прийняв)\nСпаситель народився в місті Віфлеєм\nЙому вклонитись з радістю усі підем\nМесії, підем, в місто Віфлеєм (підем).\n\nКуплет 2\nЦе дивне є Дитя народилося у хліву,\nБез пишноти й корони, щоб спасти люд від гріхів.\nХор ангелів із неба пастухам звістив,\nЩо у Віфлеємі нині їм Спаситель народивсь.\n\nКуплет 3\nСин Божий у світ прийшов тих хто гине, щоб спасти.\nІ на христі помер, взявши наші всі гріхи.\nХристос є єдиний шлях нам до Бога і Отця,\nСпасіння через це Дитя прийшло', '', '', 'ua', NULL, 0, NULL, NULL),
(425, 1120, 'Как же всё таки Боже мой ну за', 30, 'Куплет 1:\nКак же всё-таки все мы счастливы\nБоже мой, за что, за что?\nТвоя милость ко всем участлива\nУсмиряет житейский шторм\nУтешает в житейских горестях\nУстраняет земную боль\nКроме этого Царство горнее\nОбещает Твоя любовь.\n\nПрипев:\nБоже мой ну за что Ты любишь нас?\nУдивляюсь я вновь и вновь\nПочему милостив Ты к людям так?\nПотому что Бог есть любовь,\nМы с тобой, разве жизни мелочи.\nОгорчать станут нас теперь,\nЕсли нас ожидает в вечности.\nРаспахнувший нам рая дверь!!!\n\nКуплет 2:\nМы стояли у края пропасти\nШаг один ещё, мы в аду\nТы пришёл пленяющий кротостью\nИ от нас отвратил беду\nУвлеченные злом в погибели\nМы уверенно шли толпой\nТы открыл нам страницы Библии\nИ теперь мы с Тобой с Тобой.', '', '', 'ua', NULL, 0, NULL, NULL),
(426, 1121, 'Дивный Спаситель Ты – Тот Кого прославляем', 0, 'Куплет 1:\nДивный Спаситель, прекрасный,\nНаш Искупитель и Друг.\nКто мог подумать, что Агнец\nМог искупить нас от мук, о-о-о,\nМог искупить нас от мук?\n\nКуплет 2:\nСторож души и Советник,\nДух Твой мы жаждем вдохнуть.\nНовой надеждой Ты светишь,\nЕсли теряем мы путь, о-о-о,\nЕсли теряем мы путь.\n\nПрипев:\nТы – Тот, Кого прославляем,\nТот, Кого любим всегда.\nДай исцеление и милость\nНашим голодным сердцам, о-о-о,\nНашим голодным сердцам.\n\nКуплет 3:\nВечный Отец Всемогущий,\nВерно Ты любишь Своих,\nВ слабости к Трону идущих,\nЧтобы у ног пасть Твоих, о-о-о,\nЧтобы у ног пасть Твоих.', '', '', 'ua', NULL, 2, '2020-07-12', NULL),
(427, 1122, 'Куди тепер Лиш там знайду', 0, 'Куплет 1\nКуди тепер іти нам, куди шлях проложить?\nБез Тебе любий Боже, де можна спочивати?\n\nПриспів\nЛиш там знайду спокій я\nЛиш там кінець сльозам,\nЛиш там забуду гори,\nДе Бог царює Сам!\n\nКуплет 2\nО як би поспішити ввійти в Небесний Край?\nТож там моя Вітчизна, блаженний, світлий рай.\n\nКуплет 3\nНе знаю, що зі мною зробилося в ту мить,\nЩо серце мов на крилах, у край святий летить?', '', '', 'ua', NULL, 1, '2021-03-21', NULL),
(428, 1123, 'Хочу вклонитись Тобі 2', 30, 'Куплет 1\nХочу вклонитись Тобі,\nСлаву віддати в житті,\nЗа всю любов, доброту, Еммануїл!\n\nПриспів\nТи народився для нас,\nТи був розп\'ятий за нас,\nТворче Всесильний і Бог,\nЕммануїл!\nТи нас візьмеш в небеса, \nТам де оселі Отця\nБуду співати  Тобі - Алілуя!\n\nКуплет3\nЩастя у житті мені дав\nРадість небесну послав,\nДобрий спаситель і Бог,\nЕммануїл!\n\nКуплет4\nСпокій небесний тепер\nВ серці моєму живе.\nЗа це я славлю Тебе,Еммануїл!', '', '', 'ua', NULL, 0, NULL, NULL),
(429, 1124, 'Прославлю я Не потому Ты за меня', 30, 'Куплет 1:\nПрославлю я Тебя мой Бог благой\nЗа то что отдал жизнь Свою Ты на кресте\nЗа то что ночью серой и глухой\nКровавый пот струился по Твоей щеке\n\nКуплет 1- Перед припев:\nНе потому что выбора не было\nА потому что любовь велика\n\nПрипев:\nТы за меня Боже страдал Ты за меня на кресте умирал\nПринял всю боль, болезни забрал, чтобы я вновь жил и мечтал\nТы за меня проклятья понес жертвою стал Святый Христос\nКровь проливая не думал о временном не потому что выбора не было.\n\nКуплет 2:\nЯ преклонюсь мой Боже пред тобой\nЗа то что ты в смирении весь путь прошел\nЗа то что ты предвечный и святой\nНе отказался от меня, а приобрёл\n\nКуплет 4Запев:\nЗа меня, за меня,\nЗа меня, за меня.', '', '', 'ua', NULL, 3, '2021-03-07', NULL),
(430, 1125, 'Ми маєм тайну Будь славен', 0, 'Куплет 1\nМи маєм тайну від Ісуса\nПро Бога в Трійці Пресвятій\nЦю правду кожен знати мусить,\nЩоб не блукати у житті!\nМи віримо в Отця одного\nІ в Сина Божого Христа\nІ в Духа, Господа Святого,\nЩо вів Ісуса до хреста.\n\nПриспів\nБудь славен Боже Триєдиний!\nОтець і Син, і Дух Святий!\nНе втихне в небі урочисте:\n\"Святий, Святий!(Святий!)\nСвятий, Святий!(Святий!)\nСвятий, Святий!(Святий,Святий!)\"\n\nКуплет 2 \nМи любимо, Тебе наш Отче\nЗемлі і неба наш Творець!\nТебе душа безсмертна хоче,\nБо Ти початок і кінець!\nМи любимо, Тебе наш Христе!\nТи наш Спаситель і мета!\nНе втих не в небі урочисте:\n\"Святий, Святий!(Святий!)\nСвятий, Святий!(Святий!)\nНа всі віка!\n\nПриспів\nБудь славен Боже Триєдиний!\nОтець і Син, і Дух Святий!\nНе втихне в небі урочисте:\n\"Святий, Святий!(Святий!)\nСвятий, Святий!(Святий!)\nСвятий, Святий!(Святий,Святий!)\"\n\nКуплет 3\nМи любимо, Тебе наш Царю,\nДаруєш віри таїну,\nЗ\'єднай усіх у нашім краю,\nЯк це робив у давнину!\nМолитва наша в небо лине,\nБо шлях до раю не простий.\nБудь славен Боже Триєдиний\nОтець і Син(Отець),\nО- тець і Син(і Син),\nІ Дух Святий!(І Дух Святий!)', '', '', 'ua', NULL, 0, NULL, NULL),
(431, 1126, 'Із ран Спасителя текла', 0, 'Куплет 1\nІз ран Спасителя текла\nСтрумком пречиста кров,\n-Прощення всім вона дала,\nДо Нього хто прийшов.\n\nКуплет 2\nКоли розбійник на хресті\nРозп\'ятий умирав,\n-То від Христа, в крові святій\nСпасення одержав.\n\nКуплет 3\nБез Господа і я блукав,\nІ гинув в марноті,\n-Мені Христос спасіння дав\nВ Своїй крові святій.\n\nКуплет 4\nСтрумок предивний я найшов\nВ божественній крові\nПізнав Його святу любов,\nІ став щасливий в Нім.\n\nКуплет 5\nКоли ж я, немічний, ізнов\nВ моїм житті згрішу,\nВ крові Спасителя-Христа\nПрощення я знайду.', '', '', 'ua', NULL, 0, NULL, NULL),
(432, 1127, 'Сдвинулись горы Бог Саваоф', 30, 'Куплет 1\nСдвинулись горы, холмы поколеблись\nНо милость господня не отступила от нас\nБыстрые реки не смогут потопить нас\nНе сможет обжечь нас пламя огня\n\nПриспів\nБог Саваоф - имя Эго\nТы слышишь нас зов Отец всего\n.                .                  .\nВсех сильней наш Бог \nТы превыше всех\nОн превознесён\n\nКуплет 2\nНи силы бездна не станут между нами\nНе отлучат от Божьей любви\nЧтущие Бога усилиться в молитве \nИ голос их слышен до края земли.', '', '', 'ua', NULL, 0, NULL, NULL),
(433, 1128, 'Por encima de el', 0, 'Куплет 1\nPor encima de el nadie  un paso dio quien el mundo olvido\nLloró lagrimas de fiel el cielo y tierra movió.\nEntro en la humanidad y fué un capitulo aparte\nAntes y depues principio y fin piedra de la esquina angular\nUnico y verdadero, ultimo y primero.\n\nКуплет 2\nHa pagado el precio por mis pecados\nTraicionado crucificado\nEl rey despojado de gloria en un cuerpo mortal\npara hacerme enmortal.\nSu gloria transciende lo que es natural\n\nПриспів\n --тут слова приспіву', '', '', 'ua', NULL, 0, NULL, NULL),
(434, 1129, 'Христос кто бы знал Христос это имя', 0, 'Куплет 1\nХристос, кто бы знал Твое имя здесь,\nНа этой планете печальной?\nПришел, оказался Ты жертвою,\nЧтоб знал Тебя ближний и дальний.\n\nПриспів\nХристос - это имя мне дорого,\nХристос - это имя мне мило,\nХристос, Ты не хочешь ни одного\nОставить в оковах греха.\n\nКуплет 2\nРаспят ... на Голгофу ты взгляд свой брось,\nПостой, посмотри молчаливо,\nТам Кровь за тебя и меня лилась,\nЧтоб мы были счастливы.\n\nКуплет 3\nХристос, освяти как всегда Ты нас,\nВ любви, чтоб не были пустыми,\nЧтоб те, кто услышит весть в первый раз,\nПришли в объятья святые.', '', '', 'ua', NULL, 0, NULL, NULL),
(435, 1130, 'Как же всётаки Боже мой ну за что', 0, 'Куплет 1\nКак же всё-таки все мы счастливы\nБоже мой, за что, за что?\nТвоя милость ко всем участлива\nУсмиряет житейский шторм\nУтешает в житейских горестях\nУстраняет земную боль\nКроме этого Царство горнее\nОбещает Твоя любовь.\n\nПрипев:\nБоже мой ну за что Ты любишь нас?\nУдивляюсь я вновь и вновь\nПочему милостив Ты к людям так?\nПотому что Бог есть любовь\nМы с тобой, разве жизни мелочи\nОгорчать станут нас теперь\nЕсли нас ожидает в вечности\nРаспахнувший нам рая дверь.\n\nКуплет 2\nМы стояли у края пропасти\nШаг один ещё, мы в аду\nТы пришёл пленяющий кротостью\nИ от нас отвратил беду\nУвлеченные злом в погибели\nМы уверенно шли толпой\nТы открыл нам страницы Библии\nИ теперь мы с Тобой с Тобой.', '', '', 'ua', NULL, 0, NULL, NULL),
(436, 1131, 'Величає Тебе душа моя Алілуя слава Святому', 0, 'Куплет 1\nВеличає Тебе душа моя,\nЯ всім серцем славлю Тебе,\nТи – великий, могутній, всесильний,\nБудемо славити ім’я Твоє. (2 р.)\n\nПриспів:\nАлілуя, слава Святому,\nАлілуя, слава Тобі,\nСлава Богу, Богу живому,\nСлава Богу навіки віків! (2 р.)\n\nКуплет 2\nВеличає Тебе душа моя,\nЯ всім серцем славлю Тебе,\nТи створив світ і всі народи,\nБудемо славити ім’я Твоє. (2 р.)', '', '', 'ua', NULL, 3, '2021-03-07', NULL),
(437, 1132, 'Величає Тебе душа моя', 0, 'Куплет 1\nВеличає Тебе душа моя,\nG  D  G\nЯ всім серцем славлю Тебе,\nC  G  Am  Em\nТи – великий, могутній, всесильний,\nAm  H7  Em\nБудемо славити ім’я Твоє. (2 р.)\n\nПриспів:\nD  G  C  G\nАлілуя, слава Святому,\nC  G\nАлілуя, слава Тобі,\nC  G  A  Em\nСлава Богу, Богу живому,\nAm  H7  Em\nСлава Богу навіки віків. (2 р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(438, 1133, 'Вода тече', 0, 'Куплет 1\n -- тут слова першого куплету\n\nПриспів\nТа й люд ішов до Нього звідусіль\nПочути правди, мудрості у слові.\nВін не жалів ні часу, ані сил\nЖивим струмком текла його розмова.\n\nКуплет 2\nВода тече, бо те є джерело\nНе може час замулити чи стерти,\nХто з нього п\'є, схиляючи чоло,\nСтає як Він воістину безсмертний.', '', '', 'ua', NULL, 0, NULL, NULL),
(439, 1134, 'Слід за Спасом О небесна країна', 0, 'Куплет 1\nО небесна країна! До тебе я іду,\nІ про тебе я всім розкажу!\nБо в тобі лиш царює небесний спокій\nО, прийми мене, Спасе Ти мій.\n\nПриспів.\nСлід за Спасом ми підем!\nУ небесний край підем!\nТам, життя нове ми розпочнем!\nСлід за Спасом ми підем!\n\nКуплет 2\nСлід за Спасом ми підем! Слід за Спасом ми підем!\nУ небесний край підем!У небесний край підем!\nТам, життя нове ми розпочнем!\nСлід за Спасом ми підем, ми підем!\n\nКуплет 3\nСвіт про Тебе не знає, і не може пізнать,\nІ нам треба піти розказать!\nЩоб пізнали тоді про Тебе вони всі,\nЯк за всіх Ти вмирав на хресті.\n\nКуплет 4\nБо не раз я сльозами, так гірко заллюсь,\nЯк на грішний цей світ подивлюсь!\nНа страждання людей, на непевне життя\nБо мине до марнот їх мета.\n\nПриспів.\nСлід за Спасом ми підем!\nУ небесний край підем!\nТам, життя нове ми розпочнем!\nСлід за Спасом ми підем!', '', '', 'ua', NULL, 0, NULL, NULL),
(440, 1135, 'La única razón de mi adoración', 0, 'Куплет 1\nLa única razón de mi adoración eres tu mi Jesús\nMi único motivo para vivir eres tu mi señor\nMi única verdad esta en ti eres mi luz y mi salvación\nMi único amor eres tu Señor y por siempre te alabaré\n\nПриспів\nTú eres todopoderoso eres grande y majestuoso\nEres fuerte, invencible y no hay nadie como Tú\nTú eres todopoderoso eres grande y majestuoso\nEres fuerte, invencible y no hay nadie como Tú\n\nКуплет 2\nLa única razón de mi adoración eres tu mi Jesús\nMi único motivo para vivir eres tu mi señor\nMi única verdad esta en ti eres mi luz y mi salvación\nMi único amor eres tu Señor y por siempre te alabaré\nTu eres', '', '', 'ua', NULL, 0, NULL, NULL),
(441, 1136, 'За веру за Христа История наша', 0, 'Куплет 1\nИстория наша тайну веков хранит\nО подвигах смелых наших героев веры\nХоть мир так жесток он имя Христа не чтит\nБросая в детей его раскаленные стрелы\nА стрелы врага безжалостны и сильны\nОни разлучали жен навсегда с мужьями\nНо Божьи дети Богу всегда верны\nНесли Слово Божье чтоб в небо потом причалить\n\nКуплет 1\nЗа веру, за Христа вы смерти в глаза смотрели\nРыдали в небеса за детей своих\nНестрашны были вам убивающие тело\nГлавнее не сгубить врагу души\n\nКуплет 2\nИ враг наступал, чтоб истину растоптать\nБезжалостно в огне людей сжигая,\nНо не удалось детей Иисуса сломать.\nОни берегли Слово Божье молясь и прощая\nБросала судьба служителей в лагеря\nА там истязали болью земное тело\nИ сироты дети Бога за вас моля\nВ душе понимали что муки за Божье дело\n\nКуплет 3\nЗа веру, за Христа вас ждет венец и награда\nНе здесь, на небесах, где Отчий дом\nВедь истину залить никто не мог безбожным ядом\nВ воде не тонут, в огне не горят с Христом\n\nКуплет 4\nНи холода, ни метель, ни морозы\nНе разлучили души со Христом\nГорькие словно полынь ваши слезы\nСтанут небесною песней потом\nРуки усталые, ноги больные\nГолос охрипший от слез и молитв\nБог это знает и видит доныне\nГрозный Судья не спит, не дремлет, не спит.', '', '', 'ua', NULL, 0, NULL, NULL),
(442, 1137, 'Ты Жизнь Свою Всё что мне надо', 30, 'Куплет 1\nЖизнь Свою отдал на кресте за мой грех,\nКровь Свою пролил на алтарь и спас всех,\nВ Небе навсегда записал моё имя.\nТы для меня всё, Ты для меня всё.\n\nПрипев:\nВсё, что мне надо \nЗнать Тебя и быть с Тобой рядом.\nМоё сердце изменил навсегда.\nДля Тебя поёт душа моя.\n\nКуплет 1 \\ Бридж:\nЯ в присутствии Твоём руки поднимаю,\nТы в сердце моём.\nВсей душой Тебя, мой Бог, благословляю.\nТы всё во всём.', '', '', 'ua', NULL, 6, '2020-06-17', NULL),
(443, 1138, 'Ти звільнив мене Я не буду рабом гріха', 0, 'Куплет 1\nТи звільнив мене,\nІ по милості любов’ю освятив.\nБільше не боюсь, завжди поруч Ти.\nМертві всі страхи земні!\n\nПриспів\nЯ не буду рабом гріха,\nБо я дитя Царя!!!\n\nКуплет 2\nВід початку Бог,\nТи мене обрав.\nЛюбов нас віднайшла!\nНародився знов у Твою сім´ю.\nЧерез кров Христа Святу!\n\nКуплет 3\nОооо!\nТи розділяєш море щоб пройшли ми,\nУсі страхи мої забрав.\nТи віднайшов мене,\nТепер співаю, що я дитя Царя!', '', '', 'ua', NULL, 1, '2020-06-29', NULL),
(444, 1139, 'Небеса Тебе', 0, 'Куплет 1\nВся земля хвалу поет лишь Тебе, наш чудный Бог.\nИ во всей вселенной нет кто б с Тобой сравниться смог.\nТы превосходнее всего на свете, и нет подобного Тебе!\nТы наш Господь, Ты царствуешь вовеки, превознесем Тебя в хвале!\n\nПрипев:\nНебеса Тебе поют: «Святый! Святый!»\nВся земля Тебе поет: «Достоин Ты!»\nВсё творенье воздает Тебе хвалу, Господь:\n«Благословен наш Бог, Творец всего!»\n\nКуплет 2\nОт престола Твоего течёт поток живой воды.\nДля народа всей земли сияет свет Твоей любви.\nСвоим присутствием покрой всю землю, пусть свет прольется в жизнь людей,\nИ все народы преклонят колени, и воспоют хвалу Тебе!', '', '', 'ua', NULL, 1, '2021-04-07', NULL),
(445, 1140, 'Он Царь О как безгранична', 30, 'Куплет1  \nОн Царь, Творенье воспоёт Иисус\nГосподь правит над всем Он, Он Царь\nОн Царь, склонятся пред Тобой, Иисус\nЖивой правит над всем Он Он Царь.\n\nКуплет: втор1\nВоссядь и правь, мой Господь на престоле сердца я сделаю, что хочешь Ты\nВоссядь и правь, мой Господь на престоле сердца, о – о – о - o\n\nКуплет: втор 2\nВ смирении приду к Тебе, чтоб поклониться жизнью всей\nПеред Тобой я\n\nПрипев:\nО, как безгранична Твоя власть, о, как велика, Бог, Твоя слава\nО, как безгранична Твоя власть велика слава, Твоя слава\n\nКуплет \\ Бридж:\nО, как велика, Господь, о, как велика, Господь\nО, как велика, Бог Твоя слава\nО, как велика, Господь, о, как велика, Господь\nО, как велика, Господь, перед Тобой я\nУ-у-у-y, перед Тобой стою.', '', '', 'ua', NULL, 0, NULL, NULL),
(446, 1141, 'Твой вид излучает Я восхищён', 0, 'Куплет 1\nТвой вид затмевает\nСвет большой, самой яркой звезды\nТы проходишь, а вслед за Тобою\nПоднимается возглас хвалы.\n\nПриспів\nЯ восхищён, Господь, Твоим величием\nЯ восхищён Тобой, о, Иисус.\n\nКуплет 2\nТы приходишь и всё изменяется\nОт присутствия Твоего\nВсё что было больным – исцеляется\nПрикасаясь лишь только к Тебе\n\nКуплет 3\nА когда раскрываешь уста Свои\nТвоё слово всесильное\nПроникает в сердца обречённых\nИ даёт надежду на жизнь\n\nКуплет 4\nТы приходишь в сердца простых людей\nПоднимая на подвиги их\nТы приходишь и Божию силу\nОщущаем в телах мы своих', '', '', 'ua', NULL, 5, '2021-03-21', NULL),
(447, 1142, 'Я жажду близости Дух Святой сошел', 30, 'Куплет 1\nЯ жажду близости Твоей, Спаситель мой,\nСпаситель мой, пребудь со мной.\nВо всякий час даренный мне\nПребудь со мной, Спаситель мой, пребудь со мной\n\nКуплет 2\nВсегда во всем яви Ты мне Свою любовь,\nСвою любовь, яви Ты мне\nДай больше рвения к Тебе,\nДай кротость вновь, Свою любовь, дай мне любовь\n\nПрипев\nДух Святой сошел,\nДух Святой нашел,\nДух Святой поднял,\nДух Святой обнял.\n\nКуплет 3\nДай сердцем чистым вознестись к Тебе мой Бог\nМой дивный Бог, Ты мой покой\nС Тобою вечно жажду жить, веди сейчас,\nОтрада мне во всякий час\n\nКуплет 4\nКто я пред Тобой, что узрел Ты меня\nДал мне вечную жизнь, дал мне вечный покой', '', '', 'ua', NULL, 0, NULL, NULL),
(448, 1143, 'Ти є Бог Tu eres el Rey ', 0, 'Verse 1\nТи є Бог цього міста,\nТи є Цар цих людей,\nТи народу цього є, Господь.\nВ темноті Ти є Світло,\nБез надії - надія.\nТи Мир там, де тривога,\nТи Господь.\n\n\nVerse 2\nНі, нема таких, як Ти !!!\nНі, нема таких, як Ти !!!\n\n\nRefrain 1\nЩе настане час чудес,\nНастане час великих чудес\nВ цьому місті\n\nVerse 4\nTu eres el Rey de este pueblo\nEres Dios en nuestra ciudad\nEl señor de esta ciudad, Eres Dios\nEres nuestra esperanza\nEres luz en la oscuridad\nErespaz al acansado, Eres Dios.\n\nVerse5\nNo hay otro como Tu !!!\nNo hay otro como Tu !!!\n\nRefrain 2\nGrandes cosas vienen ya\nGrandes cosas Dios, ara en este pueblo', '', '', 'ua', NULL, 0, NULL, NULL),
(449, 1144, 'Все сильний', 0, 'Verse 1\nВсесильний, нездоланний \nХто збагне великого Творця?\nМи безсилі, безпорадні\nХто зійде явити нам життя?\n\nVerse 2\nСвіту що сидить у темноті світло засяяло\n\nПриспів:\nБог з нами Цар всього творіння\nПрийняв на Себе тління долю всіх людей\nБог з нами Він зняв небесні шати\nЩоб зодягнути в славу усіх Своїх дітей\n\nVerse 3 \nСлава Богу ввисоті\nМир людям на землі радійте! Бог з нами!\nСлава Богу ввисоті\nМир людям на землі радійте! Бог з нами!', '', '', 'ua', NULL, 3, '2020-07-05', NULL),
(450, 1145, 'Я бегу за Тобой!', 0, 'Verse 1\nКогда я рядом с Тобой, я не боюсь ничего.\nОткрою сердце своё, и Ты наполнишь его.\nИ мир не сможет отнять Твою любовь и покой\nЯ буду в Небо кричать: что я бегу за Тобой!\n\nПрипев: \nЯ бегу за Тобой! Каждый день вновь я Твой.\nЖизнь мою отдаю и бегу за Тобой.\n\nVerse 2:\nК Тебе стремится душа, Тебе лишь сердце поет.\nИ снова радость меня в Твоем присутствии ждет.И мир Не сможет отнять Твою любовь и покой\nЯ буду в Небо кричать: что я бегу за Тобой!\n\n\nVerse 3\nНеважно, что вокруг меня я уповаю на Тебя.\nВсегда я слышу голос Твой, хочу бежать лишь за Тобой.\nНеважно, что вокруг меня я уповаю на Тебя.\nВсегда я слышу голос Твой, хочу бежать лишь за Тобой, за Тобой.', '', '', 'ua', NULL, 5, '2020-06-29', NULL),
(451, 1146, 'Жизнь Свою отдал ', 0, 'Куплет:\nЖизнь Свою отдал на кресте за мой грех,\nКровь Свою пролил на алтарь, и спас всех.\nВ небе навсегда записал моё имя.\nТы для меня всё, Ты для меня всё.\n\nПрипев 1:\nВсё, что мне надо -\nЗнать Тебя и быть с Тобой рядом.\nМоё сердце изменил навсегда,\nДля Тебя поёт душа моя.\n\nПрипев: 2Бридж:\nЯ в присутствии Твоём руки поднимаю.\nТы в сердце моём.\nВсей душой Тебя, мой Бог, благословляю.\nТы - всё во всём.', '', '', 'ua', NULL, 1, '2020-06-17', NULL),
(452, 1148, 'По преданью На скрижалях', 0, 'Verse 1\nПо преданью отцов человек охранял,\nНа скрижалях Твое откровенье.\nГод за годом его ветер в пыль превращал,\nЧтоб забыло о Боге творенье.\n\nVerse2\nНо не букву Закона Господь подарил,\nБлагодати никто не разрушит\nТот, кто искренне Богу всем сердцем служил,\nНе на камне писали, а в души.\n\nПрипев:\nНа скрижалях сердца напиши\nАлой кровью для моей души\nЧтобы помнил о любви Твоей\nВспоминая раны от гвоздей.\n\nVerse3\nБоже мой, сотвори веру твёрдой, как камень\nДабы жизнью своей о Тебе рассказать\nМною правь из внутри и душой и руками\nЧтобы в нужный момент все что есть мог отдать\n\nПрипев:\nНа скрижалях сердца напиши\nАлой кровью для моей души\nЧтобы помнил о любви Твоей  \nВспоминая раны от гвоздей.\n\nVerse4\nНикакая беда почерк Твой не сотрет\nДаже если гоненье вернется\nВоду жизни душа и в пустыне найдет\nИ Любовью Твоей напьется	\n\nПрипев:\nНа скрижалях сердца напиши\nАлой кровью для моей души\nЧтобы помнил о любви Твоей\nВспоминая раны от гвоздей.', '', '', 'ua', NULL, 0, NULL, NULL),
(453, 1149, 'Увійду в ', 0, 'Verse 1\nУвійду в Твою присутність брамами хвали\nВ святиню Твою, Боже, щоб Тебе зустрінути.\nТвій образ споглядаю, бачу милість і красу.\nЯ лиш хочу сказати Тобі:\nТи прекрасний з нами тут, сильний Бог,\nТи прекрасний з нами тут, Авва Отче.\nТи достойний є хвали, Життя наше прийми,\nТи прекрасний з нами тут, сильний Бог', '', '', 'ua', NULL, 1, '2020-06-17', NULL),
(454, 1150, 'Увійду в ', 0, 'Verse 1\nУвійду в Твою присутність брамами хвали\nВ святиню Твою, Боже, щоб Тебе зустрінути.\nТвій образ споглядаю, бачу милість і красу.\nЯ лиш хочу сказати Тобі:\nVerse 2\nТи прекрасний з нами тут, сильний Бог,\nТи прекрасний з нами тут, Авва Отче.\nТи достойний є хвали, Життя наше прийми,\nТи прекрасний з нами тут, сильний Бог', '', '', 'ua', NULL, 8, '2021-03-28', NULL),
(455, 1151, 'Жизнь Свою отдал ', 0, 'Куплет:\nЖизнь Свою отдал на кресте за мой грех,\nКровь Свою пролил на алтарь, и спас всех.\nВ небе навсегда записал моё имя.\nТы для меня всё, Ты для меня всё.\nКуплет:2\nВсё, что мне надо -\nЗнать Тебя и быть с Тобой рядом.\nМоё сердце изменил навсегда,\nДля Тебя поёт душа моя.\n\nПрипев: 2Бридж:\nЯ в присутствии Твоём руки поднимаю.\nТы в сердце моём.\nВсей душой Тебя, мой Бог, благословляю.\nТы - всё во всём.', '', '', 'ua', NULL, 1, '2020-06-17', NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(456, 1152, 'А нас манят ', 0, 'Verse 1\nМеня манят к себе небеса, от земного хочу оторваться. \nЛишь не легкой бы быть на весах, чтоб навеки во тьме не остаться.\nЖизнь должна добродетельной быть, доброй кроткой смирёной и верной.  \nМы должны всеx прощать и любить, не смотря на гоненья и терни. \n\nПрипев:\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\n\nVerse 2 куплет:\nКак легко о делах говорить, но а в жизнь воплотить их не просто,\nДай нам Боже для ближнего жить, дай нам сил для духовного роста.\nЗабываем порой небеса, суета завладеет сознаньем.\nО открой нам спаситель глаза, и наполни ты их покаяньем.\n\nПрипев:\nА нас манят к себе небеса мы хотим от земли оторваться \nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\nА нас манят к себе небеса мы хотим от земли оторваться     \nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\n\nVerse 3 дополнительный\nПоднимите глаза в небеса, в небе дом наш и наша отчизна,\nВ своём сердце Христу дверь открыв, навсегда чтобы Он в нём поселился.\nПтицы стаями в небо летят, доверяясь во всём лишь на жатву.\nНам пример они свой оставляют, доверятся во всём только Богу.', '', '', 'ua', NULL, 2, '2020-06-21', NULL),
(457, 1153, 'На скрижалях сердца напиши По преданью', 0, 'Verse 1\nПо преданью отцов человек охранял,\nНа скрижалях Твое откровенье.\nГод за годом его ветер в пыль превращал,\nЧтоб забыло о Боге творенье.\n\nVerse 2 куплет:\nНо не букву Закона Господь подарил,\nБлагодати никто не разрушит\nТот, кто искренне Богу всем сердцем служил,\nНе на камне писали, а в души.\n\nПрипев:\nНа скрижалях сердца напиши\nАлой кровью для моей души\nЧтобы помнил о любви Твоей\nВспоминая раны от гвоздей.\n\nVerse 3 куплет:\nБоже мой, сотвори веру твёрдой, как камень\nДабы жизнью своей о Тебе рассказать\nМною правь из внутри и душой и руками\nЧтобы в нужный момент все что есть мог отдать\n\nПрипев:\nНа скрижалях сердца напиши\nАлой кровью для моей души\nЧтобы помнил о любви Твоей\nВспоминая раны от гвоздей.\n\nVerse 4 куплет:\nНикакая беда почерк Твой не сотрет\nДаже если гоненье вернется\nВоду жизни душа и в пустыне найдет\nИ Любовью Твоей напьется	\n\nПрипев:\nНа скрижалях сердца напиши\nАлой кровью для моей души\nЧтобы помнил о любви Твоей\nВспоминая раны от гвоздей.', '', '', 'ua', NULL, 3, '2020-08-30', NULL),
(458, 1154, 'Ven es hora  Todas las lenguas', 0, 'Verse 1\nVen, es hora de adorarle\nVen, abre tu corazon a El\nVen, ante su trono estamos\nVen, ante la majestad de Dios\nVen!\n\nRefrain\nTodas las lenguas confesaran qiue El es Dios\nLas orillas se doblaran\nY un tesoro eterno tendras en El\nSi coges su amor\nToda lengua confesara que El es Dios', '', '', 'ua', NULL, 0, NULL, NULL),
(459, 1155, 'Всё, что мне надо Жизнь Свою отдал', 0, 'Куплет 1\nЖизнь Свою отдал на кресте за мой грех\nКровь Свою пролил на алтарь и спас всех\nВ небе на всегда записал моё имя\nТы для меня всё, Ты для меня всё\n \nПрипев:\nВсё, что мне надо\nЗнать Тебя и быть с Тобой рядом\nМоё сердце изменил навсегда\nДля Тебя поёт душа моя\n \nVerse 2 Бридж:\nЯ в присутствии Твоём руки поднимаю\nТы в сердце моём\nВсей душой Тебя мой Бог благословляю \nТы всё во всём', '', '', 'ua', NULL, 2, '2020-08-09', NULL),
(460, 1156, 'Від початку ', 0, 'Verse 1 куплет:\nВід початку Ти був словом\nСобою увись створив\nПриховану в творіні Славу\nУ христі ти нам явив\n\nПриспів: \nПрикрасни Твоє імя прекрасне', '', '', 'ua', NULL, 0, NULL, NULL),
(461, 1157, 'Тіло ломиме', 0, 'Куплет 1\nТіло ломиме, пробиті руки \nВін не достойний такої муки!\nСвятий Господь мій, кров проливає.\n«Прости їм Отче» - в небо взиває.\n\nПриспів\nА кров стікає з хреста, \nЗа мої гріхи висока ціна. \nТо кров Ісуса Христа,  \nУ небо кричить: \"прости їм, Боже, прости!\"\n\nКуплет 2\nТакий не легкий, шлях до Голгофи,\nІ не жалів Він себе ані трохи.\nХто з Ним піде, більше не заблукає,\nЙди за Христом він тебе так кохає. \n  \nКуплет 3\nТакий нелегкий шлях Іісуса.\nЗвернись ти до Нього, не йди у спокусу. \nЯ любий друже, тебе закликаю,\nЙди до Христа, Він тебе так чекає!\n                            \nПриспів 2\nА кров стікає з хреста, \nЗа твої гріхи висока ціна. \nТо кров Ісуса Христа,  \nУ небо кричить: \"прости їм, Боже, прости!\"', '', '', 'ua', NULL, 5, '2020-12-27', NULL),
(462, 1158, 'Від початку Прекрасне Твоє Ім’я,', 0, 'Куплет 1\nВід початку Ти був Словом\nСобою світ увесь створив\nПриховану в творінні Славу\nУ Христі Ти нам явив\n\nКуплет-Приспів\nПрекрасне Твоє Ім’я, прекрасне Твоє Ім’я\nІм’я Ісуса Христа Царя\nПрекрасне Твоє Ім’я рівних Йому нема\nПрекрасне Твоє Ім’я, Ім’я Ісуса\n\nКуплет 2\nТи мріяв в небі бути з нами\nТому відкрив нам небеса\nТвоя любов мій гріх прощає,\nЩо ж розлучить зараз нас?\n\nКуплет-Приспів\nСлавне Твоє Ім’я, славне Твоє Ім’я\nІм’я Ісуса Христа Царя\nСлавне Твоє Ім’я рівних Йому нема\nСлавне Твоє Ім’я, Ім’я Ісуса\n\nКуплет-Брідж\nСмерть подолав Ти завісу порвав Ти\nГріх і могилу переміг\nНебо співає, Славу звіщає\nБо Ти воскрес, Ти є Живий!\n\nКуплет-Брідж\nТи Нездоланний, Ти Незрівнянний\nТвоє Панування навіки\nХай Твоє Царство прийде у славі\nІм’я Твоє вище від усіх\n\nКуплет-Приспів\nСильне Твоє Ім’я, сильне Твоє Ім’я\nІм’я Ісуса Христа Царя\nСильне Твоє Ім’я рівних Йому нема\nСильне Твоє Ім’я, Ім’я Ісуса﻿', '', '', 'ua', NULL, 3, '2021-04-04', NULL),
(463, 1159, 'Господи прости меня', 0, 'Verse 1\nГосподи, прости меня за всё, \nВедь я так часто опускаю свои руки, \nИ иногда мне кажется, что вовсе не живу, \nНе верю в этой жизни больше в чудо... \nVerse 2\nГосподи, прости меня, прошу \nЗа то, что вдруг кого-то обижала... \nИ, если часто я кричала \"не могу\" \nИ убегала, чтоб начать сначала. \nVerse 3\nГосподи, прости, что не ценю, \nНе берегу, кто в жизни со мной рядом. \nНе верю тем, кого я так люблю, \nИ часто лишь плохое замечаю... \nVerse 4\nГосподи, прости, что не права, \nИ часто повторяю, \"я устала\", \nОбиды в сердце у себя держу, \nХоть и за всё я здесь всегда прощаю... \nVerse 5\nГосподи, я лишь вперёд иду, \nИ верю, что настанет в мире счастье... \nИ если даже вдруг я упаду, \nТо никогда я больше не заплачу.. \n \nГосподи, я лишь тебя прошу, \nТы береги родных и тех, кто со мной рядом, \nВсё остальное я переживу, \nМне больше ничего не надо...', '', '', 'ua', NULL, 2, '2020-06-28', NULL),
(464, 1160, 'Упала слеза', 0, 'Verse 1\nУпала слеза на горячий песок\nИ кровь на ланитах застыла. \nПолдневное солнце, как красный цветок,\nКазалось в зените застыло.\n\nVerse 2\nГремели доспехи,  звенели мечи\nБлестели на солнце палящем,\nИ громко смеялись, бранясь, палачи, \nНад Агнцем, на древе висящем.\n\nVerse 3\nТак только мог Всемогущий Отец,\nОтдать на заклание Сына. \nТакая любовь для отцовских сердец\nВоистину не постижима!\n\nVerse 4\nКогда Он любил, не любили Его\nКогда Он прощал, проклинали.\nВозмездием за зло не воздал никому\nИ тем, кто Его распинали.\n\nVerse 5\nЗа всё человечество кровь пролилась   \nЦеной бесконечно бесценной.\nГолгофа над грешной землёй поднялась\nИ сделалась центром вселенной.', '', '', 'ua', NULL, 2, '2020-10-25', NULL),
(465, 1161, 'Прости мне мои ', 0, 'Verse 1\nAm                H7              Em\nПрости мне мои мысли и слова,\nD\nГосподи, прости меня за все,\nAm                H7              Em\nПрости мне мои грешные дела.\nГосподи, прости меня за все,\nЗа то, что не умею жить в любви,\nГосподи, за все меня прости,\nИ дай мне силы за Тобой идти.  — D\nRefrain\n¦  Я знаю, свет Твой сильнее всякой тьмы,\n¦  Он спасет меня, сохранит от ада.\n¦  Не унывай, душа моя, не смей,\n¦  Бог – твой Спаситель, уповай и верь!\nVerse 1\nГосподи, Твоя любовь сильней,\nЧем все мои сомнения и страх,\nГосподи, и в веренице дней\nТы держишь жизнь мою в Своих руках.\nГосподи, освободи меня,\nИз плена душу вызволи мою,\nГосподи, и полетит душа\nНавстречу Твоему огню.', '', '', 'ua', NULL, 1, '2020-06-28', NULL),
(466, 1162, 'Прости мне мои   Я знаю свет Твой', 0, 'Verse 1\nПрости мне мои мысли и слова,\nГосподи, прости меня за все,\nПрости мне мои грешные дела.\nГосподи, прости меня за все,\nЗа то, что не умею жить в любви,\nГосподи, за все меня прости,\nИ дай мне силы за Тобой идти.  \n\nRefrain\n¦  Я знаю, свет Твой сильнее всякой тьмы,\n¦  Он спасет меня, сохранит от ада.\n¦  Не унывай, душа моя, не смей,\n¦  Бог – твой Спаситель, уповай и верь!\n\nVerse 2\nГосподи, Твоя любовь сильней,\nЧем все мои сомнения и страх,\nГосподи, и в веренице дней\nТы держишь жизнь мою в Своих руках.\nГосподи, освободи меня,\nИз плена душу вызволи мою,\nГосподи, и полетит душа\nНавстречу Твоему огню.', '', '', 'ua', NULL, 0, NULL, NULL),
(467, 1163, 'Славте Бога піснями Славте Бога (славте ви Бога),', 0, 'Verse 1\nСлавте Бога піснями хваління,\nСлавте, славте всім життям своїм.\nДружним співом \nСлавте за спасіння,\nСеред мук і сліз у світі цім.\n\nVerse 2\nСлавте Бога (славте ви Бога),\nСлавте від душі, \nВін нас спас в Христі. \nСлавте Бога (славте ви Бога),\nСлавте Господа повік!\n\nVerse 3\nСлавте Бога кожної хвилини\nВ почуттях, думках, святих ділах. \nЗа терпіння Господа донині,\nЩо чекає каяття в гріхах. \n\nVerse 4\nСлавте Бога (славте ви Бога),\nСлавте від душі, \nВін нас спас в Христі. \nСлавте Бога (славте ви Бога),\nСлавте Господа повік!\n\nVerse 5\nСлавте Бога щирою душею\nЗа Його безмірную любов.\nВін спас людство ласкою Своєю,\nНа хресті святу проливши кров. \n\nVerse 6\nСлавте Бога (славте ви Бога),\nСлавте від душі, \nВін нас спас в Христі. \nСлавте Бога (славте ви Бога),\nСлавте Господа повік!\n\nVerse 7\nСлавте Бога, славте повсякчасно: \nСкоро Він у славі Сам прийде,\nВ вишній Свій \nЄрусалим прекрасний\nВсіх спасенних з піснею введе.\n\nVerse 8\nСлавте Бога (славте ви Бога),\nСлавте від душі, \nВін нас спас в Христі. \nСлавте Бога (славте ви Бога),\nСлавте Господа повік!', '', '', 'ua', NULL, 2, '2020-07-05', NULL),
(468, 1164, 'Я не знаю що там \\ Вознесу я  Ім’я Бога', 0, 'Куплет 1:\nЯ не знаю що там завтра буде\nЯ не знаю що там колись\nЧи прославлять Твоє Ім’я люди\nЩо прийдуть після мене, чи прославлять вони\n\nКуплет заспів:\n(Хай) Але сьогодні у моєму житті \nЧерез голос мій : буде прославлене Ім’я Творця\nНезнаю що буде завтра, та поки на землі,\nХай возвеличиться Боже Ім\'Я\n\nПриспів:\nВознесу я ! Ім’я Бога вознесу я!\nДопоки бачу! Допоки звучу! Допоки чую!\nВознесу я ! Ім’я Бога вознесу я!\nДопоки бачу! Допоки звучу! Допоки чую!\n\nКуплет 2:\nСкільки голосів на землі звучать\nТа для прославлення Твого Імені мовчать\nКоли ж я у Твоїй Славі перебуваю\nНе можу мовчати, любов Твоя сама в мені співає\n\nКуплет заспів:\n(Хай) Але сьогодні у моєму житті \nЧерез голос мій : буде прославлене Ім’я Творця\nНезнаю що буде завтра, та поки на землі,\nХай возвеличиться Боже Ім\'Я\n\nПриспів:\nВознесу я ! Ім’я Бога вознесу я!\nДопоки бачу! Допоки звучу! Допоки чую!\nВознесу я ! Ім’я Бога вознесу я!\nДопоки бачу! Допоки звучу! Допоки чую!\n\nКуплет 4   БРІДЖ:\nВознесу я, Хай царює, вознесу я, Алілуя,\nВознесу я, Хай царює, вознесу я, Алілуя,\nВознесу я, Хай царює, вознесу я, Алілуя,\nВознесу я, Хай царює, вознесу я, Алілуя.', '', '', 'ua', NULL, 3, '2020-11-22', NULL),
(469, 1165, 'Приходи комне Иешуа, Иешуа!!!', 0, 'Verse 1\nИешуа, Иешуа!!!\n\nRefrain\nПриходи ко мне, Господь мой,\nМой возлюбленный.\nЖдёт Тебя Твоя Невеста,\nЦерковь ждёт Тебя, гряди.\n\nVerse 2\nИешуа, Иешуа!!!\n\nRefrain\nПриходи ко мне, Господь мой,\nМой возлюбленный.\nЖдёт Тебя Твоя Невеста,\nЦерковь ждёт Тебя, гряди.\n\n\n\nVerse 2\nИешуа, Иешуа!!!\nЖдёт Тебя Твоя Невеста,\nЦерковь ждёт Тебя, гряди.', '', '', 'ua', NULL, 7, '2021-02-28', NULL),
(470, 1166, 'Благословен тот дом', 0, 'Куплет 1\nБлагословен тот дом, где в каждом чистом сердце,\nСлово Святое Господа живёт.\nНет власти тьмы и страха смерти,\nИ Сам Господь в тот дом Хозяином войдёт.\n\nПриспів\nБлагословен, благословен,\nБлагословен, тот дом.  \nБлагословен, благословен,\nБлагословен, тот дом.\n\nКуплет 2\nБлагословен тот дом, где в тихий час молитвы,\nДухом Святым Господь касается сердец.\nГде радость и счастье любви в избытке,\nИ благодать излил Небесный наш Отец.\n\nКуплет 3\nБлагословен тот дом, где старость уважают,\nГде веру свято берегут из рода в род.\nСлавят Творца и Библию читают,\nИ возрастают в мудрости из года в год.', '', '', 'ua', NULL, 5, '2021-01-17', NULL),
(471, 1167, 'Благословяє й охороняє  ', 0, 'Verse 1\nБлагословяє й охороняє,\nлице Його хай сяє і милість дає,\nНехай з Тобою Він завжди буде\nІ хай дарує мир. 2р\n                    Амінь амінь амінь -4р.\nVerse 2\nЙого ласка завжди буде\nСеред тисяч поколінь\nВ наших сім’ях\nВ наших дітях,\nЇхніх дітях,\nІ їхніх дітях. -3р.\n\nVerse 3\nХай присутність Божа завжди\nЙде попереду й позаду\nХай  огорне і наповнить,\nВін з тобою, Він з тобою. \n\nVerse 4\nКожен ранок, кожен вечір\nВ твоїм виході і вході,\nКоли плачеш і смієшся,\nВін за тебе, Він з тобою. 1р.', '', '', 'ua', NULL, 3, '2021-04-04', NULL),
(472, 1168, 'Меня манят к себе небеса', 0, 'Verse 1  .  КУПЛЕТ:\nМеня манят к себе небеса, от земного хочу оторваться. \nЛишь не легкой бы быть на весах, чтоб навеки во тьме не остаться.\nЖизнь должна добродетельной быть, доброй кроткой смирёной и верной.  \nМы должны всеx прощать и любить, не смотря на гоненья и терни. \n\nRefrain 1  / ПРИПЕВ:\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\n\nVerse  2 . КУПЛЕТ:\nКак легко о делах говорить, но а в жизнь воплотить их не просто,\nДай нам Боже для ближнего жить, дай нам сил для духовного роста.\nЗабываем порой небеса, суета завладеет сознаньем.\nО открой нам спаситель глаза, и наполни ты их покаяньем.\n\nRefrain  / ПРИПЕВ:\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\n\nVerse     3 .  КУПЛЕТ: ДОПОЛНИТЕЛЬНЫЙ\nПоднимите глаза в небеса, в небе дом наш и наша отчизна,\nВ своём сердце Христу дверь открыв, навсегда чтобы Он в нём поселился.\nПтицы стаями в небо летят, доверяясь во всём лишь на жатву.\nНам пример они свой оставляют, доверятся во всём только Богу.', '', '', 'ua', NULL, 2, '2020-07-26', NULL),
(473, 1169, 'Научи меня мой Господь', 0, 'Куплет 1.\nНаучи меня, мой Господь, во всем\nВолю исполнять лишь Твою,\nЧтобы мне по слову Твоему доказать,\nЧто тебя я, Создатель, люблю.\n\nПрипев:\nНаучи меня среди тысячи\nГолос слышать лишь Твой.\nНаучи меня за Тобой идти\nВ край желанный, дорогой.\n\nКуплет 2.\nНаучи меня в грешном мире жить,\nЧтобы свет Твой сиял во тьме,\nКак не может скрыться город большой,\nЧто стоит на высоком холме.\n\nКуплет 3.\nНаучи меня жизнь свою прожить,\nЧтоб в конце услышать её:\n\"Добрый, верный раб, скорей войди\nВ радость господина твоего\".', '', '', 'ua', NULL, 2, '2020-07-26', NULL),
(474, 1170, 'Плаче небо Кров стікає омиває', 0, 'Verse 1\nПлаче небо, плачу я ...\nБачу тебе в обіймах Христа!\nІ терпіти, дивитись нема сил,\nЯк вмирає Христос - Божий Син.\n\nRefrain\nКров стікає, омиває!\nВсього світу гріхи.\nБог чикає і взиває,\nКличе тебе: Прийди!\n\nVerse 2\nЩо є правда, істина?\nВін за мене жертвою став.\nВін за мене хрест поніс,\nЩоб я серце для Нього приніс!\n\nVerse 3\nВид Його спотвореним був,\nБіль і муку сповна Він відчув.\nСором, ганьба, і рани в руках,\nЩоб нам пробувати в небесах.', '', '', 'ua', NULL, 3, '2020-08-16', NULL),
(475, 1171, 'Иисус хочу поговорить-Прости за боль', 0, 'Verse 1\nИисус хочу поговорить с Тобой,\nИ сердца тайники Тебе открыть.\nВедь Ты один даёшь душе покой,\nИ учишь в этом мире свято жить.\n \nRefrain     -  ПРИПЕВ:\nПрости за боль, что часто причиняю,\nЗа муки и страдания прости,\nЗа то, что я слабею в испытаньях,\nЗа то, что падаю я на пути!\n\nVerse   2 КУПЛЕТ:\nНе нахожу ни в ком я утешенья,                  \nДрузья мои оставили меня,\nЛишь Ты один даруешь мне прощенье.\nИ жаждет лишь Тебя душа моя.\n\nVerse  3 КУПЛЕТ:\nИсточник света Ты и Исцелитель,\nВрачуешь внутренность Ты всякий раз,\nСпешу придти к Тебе, о мой Спаситель!\nО, дай мне силы, чтоб не опоздать.', '', '', 'ua', NULL, 1, '2020-08-16', NULL),
(476, 1172, 'Покажи мені  І тому я йду', 0, 'Verse 1 КУПЛЕТ:\nПокажи мені, що в моєму серці на дні,\nЧи горить вогонь піднятих у небо долонь.\nЩо шукаю, про що мрію, прагнучим небесних слів,\nТочно знаю – є надія, бо мене Бог створив. \n\nRefrain ПРИСПІВ:\nІ тому я йду, я до Тебе йду,\nЯ Тебе знайду,\nГосподь, лице не ховай,\nІ не відпускай!\n\nVerse 2 КУПЛЕТ:\nВіри дай мені, щоб піднятись вище над всім,\nОчі просвіти, щоб дивились далі, як Ти.\nСерце чисте я прохаю, споглядатиму Христа,\nЧисті серцем Бога бачать – істина лиш одна.', '', '', 'ua', NULL, 3, '2020-08-23', NULL),
(477, 1174, 'Господь з Тобою я спокійно йду', 0, 'Verse 1\nГосподь, з Тобою я спокійно йду, \nЗла не боюсь, бо Ти ведеш.\nТриматись хочу я Твого шляху –\nТи мій Пастир і Отець!\n\nVerse  /  ПЕРЕД ПРИСПІВ:\nЯкщо піду я долиною смертної темряви, \nЯ долиною смертної темряви, то не боятимуся!\nБо твердо знаю, що неодмінно Ти поруч зі мною,\nКожну мить огортаєш любов’ю! Навколо милість Твоя!\n\nRefrain   /   ПРИСПІВ:\nДо висот веде мене добрий Пастир\nІ до тихої води.\nЗа Тобою, Боже, я буду йти!\nВсе життя моє в Тобі, мій Пастир.\n\nVerse 2\nГосподь, з Тобою я спокійно йду, \nЗла не боюсь, бо Ти ведеш.\nТриматись хочу я Твого шляху –\nТи мій Пастир і Отець!', '', '', 'ua', NULL, 2, '2021-03-07', NULL),
(478, 1175, 'Сповняй мене Боже навчи мене ', 0, 'Verse 1 КУПЛЕТ:\nСповняй мене\nДобром Своїм і милістю, Господь\nБо Ти Один - любов, і за людей\nСвого сина дав, нас врятував\n\nRefrain   ПРИСПІВ:\nБоже, навчи мене любити так, як Ти\nЛюбов\'ю, яка стирає межі і знайти\nправду Твою я зможу, й бачитимуть всі\nв сяйві моїх очей Твою Батьківську любов\n\nVerse 2КУПЛЕТ:\nТак полюбив\nВід бездомних до відомих, просто всіх\nСтворив Ти й любов\'ю нас покрив\nБо правда в тім, що ми Твої діти\n\nVerse 3    БРІДЖ:\nУсім життям прославлю я Тебе\nЗа любов, що кожну мить Ти нам даєш\nУсім життям прославлю я Тебе\nПрекрасний Ти і Люблячий Батько', '', '', 'ua', NULL, 3, '2021-03-07', NULL),
(479, 1176, ' Кров Христа за мене У стражданнях і тузі', 0, 'Verse 1\nУ стражданнях і тузі наш Господь був на хресті,\nВін поніс туди всі болі і гріхи.\nВін – Предвічний і Святий всіх людей так полюбив,\nСвою кров за всіх людей Він проливав.\n\nПриспів:\nКров Христа за мене (тебе) теж лилась,\nКров Христа захистить моє (твоє) життя!\nКров Христа – омиває від гріха,\nСила, що рятує нас – кров Христа, кров Христа!\nVerse 2\nІ немов мале Ягня, став Він жертвою за нас,\nЙого кров з хреста лилася за людей.\nКров змиває всі гріхи і рятує від діл тьми,\nКожен день, в молитві, кличу до Христа!', '', '', 'ua', NULL, 3, '2021-01-31', NULL),
(480, 1177, 'Иисус за Кровь Твою', 0, 'Куплет 1\nИисус, за Кровь Твою, я Тебя благодарю,\nЧто пролил Ты на кресте!\nТы был мучим и страдал, жизнь Свою за нас отдал,\nЧтобы я искуплен стал!\n\nVerse 1ПРЕД ПРИПЕВ:\nЗнаю, что не тленным золотом и серебром\nБыл искуплен от греха!\nЗнаю я, что нет цены, Иисус, Твоей Крови,\nТвоей Крови!\n\nRefrain  .   ПРИПЕВ:\nРанами Твоими исцелен, милостью прощен,\nБлагодатью я спасен,\nНе забуду никогда какова Твоя цена -\nКровь Иисуса! Кровь Христа!', '', '', 'ua', NULL, 2, '2020-12-27', NULL),
(481, 1178, 'Войду во Святое Святых', 0, 'Куплет 1\nВойду во Святое Святых\nВойду я через Кровь Христа\nВойду я в поклоненье Тебе\nВойду я во Славу Отца\n\nКуплет 2\nПоклонюсь Тебе, о Мой Господь\nПоклонюсь Тебе, о Мой Господь\nТвое Имя Святой, Святой Господь\n\nКуплет 3\nПроведи сквозь внешний двор\nНа Твое Святое место\nЯ хочу Твое видеть лицо Господь\nЯ ищу Тебя всем сердцем\nОт толпы людской возьми меня \nКо святым поющем песни \nЖажду праведности Твоей мой Бог \nЗдесь единственное место\n\nКуплет 4\nПроведи во Святое Святых\nчерез Агнца кровь проведи \nПроведи во Святое Святых\nИ уста мои очисть - вот я\n\nКуплет 5\nПред величием Твоим, мы в почтении стоим \nМилость нам Свою явил кровью нас освободил\nПобедитель Бог всего\nБог Спасенья моего\nОт начала  Ты со мной\nИ возмёш меня домой\n\nКуплет 6\nПоклонюсь Тебе, о Мой Господь//\nТвое имя Святой, Святой Господь //', '', '', 'ua', NULL, 4, '2021-04-02', NULL),
(482, 1179, 'Знову рік проминув, День Подяки настав', 0, 'Куплет 1\nЗнову рік проминув, День Подяки настав\nПеред Господом Богом сьогодні ти став\nЩо ти скажеш Йому, як хвалу принесеш?\nІ які для подяки слова ти знайдеш?\n\nПриспів\nУ День Подяки славу Богу віддай\nІ вдячністю все життя своє наповняй.\nУ День Подяки поглянь на свої шляхи\nГосподь помилуй, помилуй нас грішних прости.\n\nКуплет 2\nСкільки милостей, що Бог тобі посилав\nНа молитви твої завжди відповідав\nКожну мить на шляху Він зберіг і провів\nНе один раз тебе Він від зла захистив.\n\nКуплет 3\nБільше Бог подавав, ніж у нього просив.\nІ біду стороною- це теж Він обвів.\nБог з тобою, казали тобі всі навкруг.\nБог за нас лиш тому, що Він наш кращий друг', '', '', 'ua', NULL, 1, '2020-11-08', NULL),
(483, 1180, 'Я йду за Ісусом', 0, 'Куплет 1\nЯ йду за Ісусом, я йду за Ісусом, \nПо стежині в вічне майбуття.                      \nЯ плачу з Ісусом, радію з Ісусом, \nI живуть в мені Його слова:\n\nПриспів\n«Подивись скоріш у небо ясне, \nТам для тебе місто є прекрасне,\nВже не буде там місця твоїм сльозам.\nА якщо не так, ти маєш знати – \nЯ іду його приготувати,\nБудеш славить в нім, в місті Єрусалим\nГоспода всім серцем своїм».\n\n\nКуплет 2\nСкажи, Ісусе, відкрий, Ісусе, \nЩо ховає синій небокрай?           \nЯ вірю, Ісусе, здолаю спокуси, \nI ввійду з Тобою в вічний рай.\n\nКуплет 3\nЩо ховає синій небокрай?           \nТе, чого не бачиш, вірою прийми!\nВідкриття Ісусове тримай, до Нього йди!\n\nКуплет 4\nЯ йду за Ісусом, я йду за Ісусом', '', '', 'ua', NULL, 1, '2020-11-15', NULL),
(484, 1181, 'А ти шукай Христа Ідучи по дорозі', 0, 'Verse 1 КУПЛЕТ:\nІдучи по дорозі до неба ти зустрінеш не раз у житті\nПерешкоди каміння і терен ноги зранять до болю тобі \nМоже люди не зрозуміють не повірять щирим словам\nЛиш Господь твоє серце зігріє в Нього зраненим душам бальзам \n \nRefrain 1 ПРИСПІВ: \nА ти шукай Христа коли на серці важко \nШукай Його коли вже немає сил \nШукай Христа і знайдеш неодмінно \nЗцілити  біль лиш зможе Божий Син \n\nVerse 2 КУПЛЕТ:\nІ хто сіє тепер зі сльозами в небі радість святую пожне \nІ хоч бурі ідуть із вітрами під Господнім крилом наш човен \nІ ніякі важкі перешкоди віру в серці хай не розіп’ють \nБо Господь-це надійна опора Боже Ім’я це скеля міцна\n\nRefrain 2 ПРИСПІВ: \nТому шукай Христа коли на серці важко\nШукай Його коли вже немає сил \nШукай Христа і знайдеш неодмінно \nЗцілити  біль лиш зможе Божий Син﻿\n\nVerse 3 КУПЛЕТ:\nМоже люди не зрозуміють не повірять щирим словам\nЛиш Господь твоє серце зігріє в Нього зраненим душам бальзам \n\nRefrain 3 ПРИСПІВ: \nА ти шукай Христа коли на серці важко \nШукай Його коли вже немає сил \nШукай Христа і знайдеш неодмінно \nЗцілити  біль лиш зможе Божий Син', '', '', 'ua', NULL, 0, NULL, NULL),
(485, 1182, 'Можу лиш уявити те, що буде там', 0, 'Verse 1\nМожу лиш уявити те, що буде там\nЯк зустрінеш Ти мене в небесах.             \nМожу лиш уявити, що побачу я, \nСерце полонить слава Твоя. \nМожу лиш уявити.\n\nRefrain\nВ Твоїй величі і славі, що відчую я тоді?    \nЧи я буду танцювати, чи застигну у хвалі?\nЧи стояти просто буду, на коліна я впаду?\nЗаспіваю \"Алілуя\", чи взагалі слова знайду?\nМожу лиш уявити, Можу лиш уявити.\n\nVerse 2\nМожу лиш уявити, як той день прийде,\nЯ побачу, Боже мій, Тебе.\nМожу лиш уявити, все, що я зроблю -\nБуду завжди славити Тебе, Ісус.\nМожу лиш уявити.\n\nVerse 3\nЗакриваю свої очі, уявляю я той день,\nCерце в захваті шепоче: \"Бог мій, Ти для мене все\".\nЯ стояти просто буду, у присутності Твоїй,\nЗаспіваю \"Алілуя\", і вклонюся я Тобі.\nМожу лиш уявити\n\nVerse 4\nВ Твоїй величі і славі, що відчую я тоді?\nЧи я буду танцювати, чи застигну у хвалі?\nЧи стояти просто буду, на коліна я впаду?\nЗаспіваю \"Алілуя\", чи взагалі слова знайду?\nМожу лиш уявити.\n\nVerse 5\nМожу лиш уявити, все, що я зроблю -\nБуду завжди славити Тебе, Ісус.\nМожу лиш уявити.', '', '', 'ua', NULL, 2, '2021-01-31', NULL),
(486, 1183, 'Vamos a cantar con la musica del cielo', 0, 'Verse 1\nVamos a cantar con la musica del cielo vamos a cantar\nalegres por que escuchas cuando\ncantamos para exaltar tu nombre\n\nRefrain\nAmamos todo de ti\ncielo y tierra te adoran\nlos reinos se rinden\nHijo de Dios, Tú eres por quien\nTú eres por quien\nvivimos hoy\n\nVerse 2\nTú eres quien nos liberta\nTú eres la luz que guía\ncomo un fuego ardiente\nHijo de Dios, Tú eres por quien\nTú eres por quien\nvivimos hoy\n\nVerse 3\nVamos a cantar con la musica del cielo vamos a cantar\nalegres por que escuchas cuando\ncantamos para exaltar tu nombre', '', '', 'ua', NULL, 0, NULL, NULL),
(487, 1184, 'Ты на троне прославленья', 0, 'Куплет 1\nМы песню воспоем, в которой нет конца.\nСвой голос вознесёт и небо и земля.\nЛюбовь Твоя верна и милость на века.\nТы Царь, но жертвой стал, Бог жизнь за нас отдал.\n\nПриспів\nТы на троне прославленья, средь тысяч поколений.\nТы достоин наш Господь.\nЛишь Тебе, Кто умер и воскрес, мы с небом будем петь,\nЛишь Ты достоин наш Господь.\n\nКуплет 2\nВсе дни и в вечности Тобой мы будем жить.\nИ вечно возглашать Иисус Тебе хвала.\nВсе дни и в вечности Тобой мы будем жить.\nИ вечно возглашать Иисус Тебе хвала. Иисус Тебе хвала.\n\nКуплет 3\nБудь прославлен наш Господь.', '', '', 'ua', NULL, 3, '2021-02-21', NULL),
(488, 1185, 'Я перед тобою', 0, 'Куплет 1\nЯ перед тобою, чекаю Тебе і слова Твого\nпо милості Твоїй святій, зараз тут стою\nв Тобі Ісус життя моє\nСвободу тільки Ти даєш\nмене Ти врятував\nі все Господь я Тобі віддам\n\nRefrain\nТвоє Ім\'я вознесу\nв серці своїм я скажу\nщо я Твій, я є Твій\nБоже, все, щоє в мені \nВ руки відаю Тобі\nЯ є Твій, Я є Твій\n\nКуплет 2\nРуке в небо я здійму, Ти явив любов Свою\nна колінах я Господи стою \nпо всій землі я розкажу\nпро любов Твою святу\nмене ти врятував\nі все Господь я Тобі віддам\n\nКуплет 3\nЯ тут стою, відкривши серце Тобі Ісус\nТи є Вічний Бог, Всемогутній Богю', '', '', 'ua', NULL, 5, '2021-01-31', NULL),
(489, 1186, 'Я не буду плакать', 0, 'Куплет 1\nЯ не буду плакать, не буду горевать,\nЯ буду Бога в сердце громко прославлять,\nМне уже не страшно, мой Бог всегда со мной,\nОн ведет меня в Небесный край родной.\n\nПриспів\nДомой, домой, Он ведет меня домой!\nДомой, домой, в Небесный край родной.\n\nКуплет 2\nЯ безмерно счастлив, мне открылась жизни суть,\nМой Господь Спаситель показал мне верный путь.\nЯ теперь свободен, Господь – Спаситель мой,\nОн ведет меня в Небесный край родной.\n\nКуплет 3\nИисус – моя защита, Бог мой – моя скала,\nДля меня открыта Небесная страна.\nЯ теперь свободен, Господь всегда со мной,\nОн ведет меня в Небесный край родной.', '', '', 'ua', NULL, 0, NULL, NULL),
(490, 1187, 'Без Тебе я не можу йти Моя душа спокій знайшла', 0, 'Куплет 1\nБез Тебе я не можу йти,\nмені потрібен, Боже, Ти\nНіби в пустелі без води \nЯ прагну, Боже, де є Ти?\n\nКуплет 2\nІ я шукаю спокій в Тобі,\nІ я шукаю…\n \nПриспів:\nМоя душа спокій знайшла в Тобі, Господь, є сила вся.\nМоя душа спокій знайшла в Тобі, Господь…\n\nКуплет 2:\nКолись я думав, що знайду без Тебе спокій для душі,\nІ не потраплю у біду, я думав світло є в мені\nАле вже знаю, що світло є – Ти\nАле вже знаю, спокій в Тобі', '', '', 'ua', NULL, 1, '2021-01-24', NULL),
(491, 1188, 'Духом Твоим меня наполняй Я буду славить', 0, 'Куплет  1 :\nДухом Твоим меня наполняй,\nДай мне исполнить желанье Твоё.\nДушу мою в образ Свой изменяй,\nИ говори прямо в сердце моё\n....        ....         ....\nКак хорошо мне быть в доме Твоём,\nСлава Твоя наполняет Его.\nЖертву хвалы на алтарь вознесём,\nИ да прославится имя Твоё\n\nКуплет  3 :\nЯ буду славить Тебя вовеки,\nЯ буду петь Тебе, мой Бог.\n Огонь Твоей любви и жизни реки\nВо мне открой, Иисус Господь', '', '', 'ua', NULL, 3, '2021-03-28', NULL),
(492, 1189, 'Славим Того', 0, 'Куплет 1\nСлавим Того хто життя дарував\nЛюдство створив і природу нам дав\nЗорі створив і на небі розклав\nСонце нам дав, місяць дав, воду дав\n\nПриспів\nБудь прославлений наш Бог\nЗ нами Бог так з нами Бог\nІ життя вже не сумне з нами Бог\nІ з нами все \n\nКуплет 2\nТвоє ім\'я: Цар царів, Бог богів\nВище всього і сильніший усіх\nБачиш моє ти нутро і життя\nБоже тобі вся хвала, вся хвала\n\nКуплет 3\nСкоро грядеш Ти у славі своїй\nЦеркву візьмеш і одягнеш вінці\nКнига відкрита лежить перед Ним\nНаші ім\'я там записані в ній', '', '', 'ua', NULL, 1, '2020-12-21', NULL),
(493, 1190, 'Иисус сегодня, Иисус вчера', 0, 'Verse 1\nИисус сегодня, Иисус вчера,\nИисус во веки, Иисус всегда. \nБез Него нет счастья , без Него беда.\nТолько с   Иисусом, жизни полнота. \n\nRefrain\nТы наш добрый пастырь, Иисус Христос.\nТы твердыня в жизни, в час скорбей и слез.       \nПо дороге в небо, ... в небо,  сохранишь меня...меня. \nВ Тебе много хлеба,   И жива вода. \n\nVerse 2\nТолько в Иисусе нахожу покой,\nДля души усталой, Ты оазис мой. \nПо пустыне дикой проведешь меня. \nВ город вечной славы, моего Отца.\n\nVerse 3\nВо Христе спасенье, Бог желает дать.  \nТолько в Иисусе мир и благодать, \nМой Попутчик в жизни. Он всегда со мной,   \nТолько с Иисусом, небо дом родной.\n\nVerse 4\nИисус есть Альфа и Омега Он,\nИисус есть первый и последний Он. \nОн всему начало и всему конец. \nЦарь Царей Владыка,  Он наш Бог Отец.', '', '', 'ua', NULL, 0, NULL, NULL),
(494, 1191, 'Amarte solo a Ti Señor Любить только Тебя ', 0, 'Куплет  1\n/// Amarte solo a Ti Señor, ///\nY no mirar atrás.\n\nКуплет 2\n//Seguir tu caminar Señor,\nSeguir sin desmayar Señor, \nPostrada ante Tu altar Señor, \nY no mirar atrás. //\n\nКуплет 3\n/// Любить только Тебя Господь, ///\nИ не смотреть назад.\n\nКуплет 4\n// Идти только с Тобой Господь,\nИдти не уставать Господь,\nИ преклонятся пред Тобой,\nИ не смотреть назад. //\n\nКуплет5\n///Служить только тебе господь/// \nИ не смотреть на зад\nИскать только тебя Господь\nИ жить только для Тебя Господь\nЗа всё благодарю Тебя\nИ не смотреть на зад!!!', '', '', 'ua', NULL, 1, '2020-12-27', NULL),
(495, 1192, 'Amarte solo a Ti Señor Любить только Тебя ', 0, 'Куплет  1\n/// Amarte solo a Ti Señor, ///\nY no mirar atrás.\n\nКуплет 2\n//Seguir tu caminar Señor,\nSeguir sin desmayar Señor, \nPostrada ante Tu altar Señor, \nY no mirar atrás. //\n\nКуплет 3\n/// Любить только Тебя Господь, ///\nИ не смотреть назад.\n\nКуплет 4\n// Идти только с Тобой Господь,\nИдти не уставать Господь,\nИ преклонятся пред Тобой,\nИ не смотреть назад. //\n\nКуплет5\n///Служить только тебе господь/// \nИ не смотреть на зад\nИскать только тебя Господь\nИ жить лиш для Тебя Господь\nЗа всё благодарю Тебя\nИ не смотреть на зад!!!', '', '', 'ua', NULL, 0, NULL, NULL),
(496, 1193, 'Сквозь слёзы ', 0, 'Verse 1\nСквозь слёзы   смотрю на Тебя,\nРаспятый Иисус, мой Господь.\nТы снял    мою боль,   изгнал с сердца страх,\nХотя Сам   повис   на гвоздях.\n\nRefrain\nТо не гвозди ведь держали на кресте,\nТо не люди   причиняли боль Тебе.\nТо не гвозди и не люди,  но мой грех,\nХоть минуло   с этой казни так много лет.\n\nVerse 2\nЯ вижу    Тебя    на кресте,\nИзбитым,  в терновом венце.\nПронзить дал Ты руки, и ноги Свои,\nМеня чтоб спасти     от вины.\n\n \nVerse 3\nТак часто     я вижу тот день,\nГолгофы    кровавую тень.\nСклонясь   у  креста,   я милость нашёл,\nСвободу   мне дал    Божий Сын!', '', '', 'ua', NULL, 0, NULL, NULL),
(497, 1194, 'Веселися і радій', 0, 'Куплет 1\nВеселися і радій – день Різдва настав!\nВеселися і радій – Бог нам Сина дав!\nВеселися і радій – дивний з неба дар\nВеселися і радій – народився Цар!\n\nПриспів\nХай радіють всі! Хай співають всі! - 2р.\nПрославляють всі люди на землі.\n\nКуплет 2\nВеселяться небеса, радіє земля\nВеселяться всі річки і гори, і моря\nТож радій і веселись разом з нами ти,\nБогові хвалу віддай і дар Його прийми.\n\nПриспів 2\nХай радіють всі! Хай співають всі! - 2р.\nПрославляють всі люди на землі\nСлавав в небесах, І мир на землі\nНародився Цар, веселіться всі!\n\nКуплет 3\nОсанна, Осанна\nБлагослобен, хто йде у Господнє їм\' я', '', '', 'ua', NULL, 3, '2021-01-03', NULL),
(498, 1195, 'Ангели в небі', 0, 'Куплет 1\nАнгели в небі пісню співають, \nЩо Христос родився, всім возвіщають. \n\nПриспів\nСлава в вишніх Богу, \nІ на землі мир. \n\nКуплет 2\nПречиста Діва дитятко сповила, \nБожого сина в ясла положила. \n\nКуплет 3\nЙосип і Марія Богу помолились, \nПастухи ягняток Христу поклонились. \n\nКуплет 4\nІ ми нині вірні, Христа величаймо, \nАнгельську пісня Йому заспіваймо.', '', '', 'ua', NULL, 1, '2020-12-27', NULL),
(499, 1196, 'В Новом году Время летит', 0, 'Verse 1\nВремя летит очень быстро,\nГоды сменяют года.\nВсё в этом мире так зыбко и тленно\nНам показали века.\nВсё изменяется и происходит,\nВремя стремительно мчится вперёд.\nТолько добро никогда не проходит,\nТолько любовь никогда не пройдёт.\n\nПрипев:\nВ Новом году вам желаем добра,\nСчастья и радости в ваши сердца.\nПусть вас Господь на пути сохранит\nИ год грядущий благословит\n\nКуплет 2:\nДавайте мы будем добрее,\nДавайте друг друга любить.\nЛюбовь - это праздник, забудем обиды,\nИ будем всем праздник дарить.\nЛюбовь дарит счастье и дарит улыбки,\nЛюбовь покрывает обиды и боль.\nЛюбовь прощает другому ошибки,\nНадеется, верит и ждёт.', '', '', 'ua', NULL, 1, '2021-01-01', NULL),
(500, 1197, 'Коли схиляюсь Я просто дякую', 0, 'Куплет 1\nКоли схиляюсь я до ніг Твоїх, \nНе можуть мовчати вуста мої, \nАле немає слів передать всю подяку мою. \nЗа все що Ти нам дав и ще даєш, \nЩо нас усіх бережеш. \nЗа все Тобі я дякую завжди, Ісус! \n\nПриспів\nЯ просто дякую Тобі за те що не лишаєш в біді. \nЯ просто дякую Тобі і молюсь. \nЯ просто дякую Тобі за те що Ти в моєму житті. \nЯ просто дякую Тобі, Ісус! \n\nКуплет 2\nКоли тривога серця огорне, \nБіду нещастя принесе, \nАле я точно знаю в мене вихід є! \nУ Тобі щастя завжди є моє. \nЯк добре, Бог, що Ти в мене є. \nАле прості, прості, \nСлова подяки линуть з серця до небес.', '', '', 'ua', NULL, 2, '2021-01-24', NULL),
(501, 1198, 'Доверять Тебе', 0, 'Куплет 1\nОтпускаю все мечты мои,\nЯ полагаю их у ног Твоих\nЕсли в жизни ошибаюсь я,\nТвоя любовь не изменяется\n\nКуплет 2\nХотел сразиться я за жизнь мою...\nОслабли руки, устал я в бою\nТы сильный Воин, Ты Царь всех побед!\nЯ побеждаю, когда я в Тебе\n\nПриспів\nИ даже если горы не двигаясь стоят\nИ если воды моря не разделяются...\nИ если на молитвы, не вижу я ответ\nДоверять, доверять буду я Тебе!\n\nКуплет 3\nЧто завтра мне принесет опять?\nТы знаешь, все известно для Тебя!\nЖиви во мне, будь дыханием моим\nДай каждый день ходить путем Твоим!\n\nКуплет 4\nТы мой покой и сила, опора Ты моя!\nМоё Ты основание, Ты крепкая скала!\nТвои пути прекрасны, они превыше всех!\nТы держишь эту Землю и всё в Твоей руке!', '', '', 'ua', NULL, 1, '2021-01-03', NULL),
(502, 1199, 'Ми прибули, господарю', 0, 'Куплет 1\nМи прибули, господарю,\nДо вашої хати,\nХочемо Вам, господарю,\nЗаколядувати!\n\nПриспів\nХай Ісус, мале дитя,\nБлагословить Ваше життя,\nЩоб Ви в мирі проживали\nІ біди не знали!\n\nКуплет 2\nА чи знаєш, господарю,\nЩо Бог народився?\nУ вертепі на соломці\nСам Ісус явився!\n\nКуплет 3\nМи же будем, господарю,\nВід вас відходити\nІ рожденного Ісуса\nБудемо просити!', '', '', 'ua', NULL, 1, '2021-01-06', NULL),
(503, 1200, 'Чи знала ти Маріє', 0, 'Verse 1\nЧи знала ти Маріє що твоє Дитя ходитиме водою?\nЧи знала ти Маріє що твій Син спасе людей від гріха собою?\nЧи ти знала що твоє Дитя змінить твоє життя?\nНароджений тобою подарує тобі вічне життя.\n\nПриспів 1\nЧи знала ти Маріє що твоє Дитя відкриє очі сліпому?\nЧи знала ти Маріє що твоє дитя втихомирить бурю на морі?\nЧи знала ти Маріє що всі ангели вклоняються Йому?\nКоли и цілувала Сина ти цілувала Боже лице.\n\nКуплет Приспів 2\nЧи знала ти Маріє…?\nПобачить сліпий, почує глухий,\nІ мертві знову оживуть.\nКривий затанцює, німий заспіває,\nХвалу всевишньому\n\nVerse 4\nЧи знала ти Маріє що твоє дитя Господь всього творіння\nЧи знала ти Маріє що одного дня твій Син поведе народи?\nЧи знала що твоє Дитя небесний агнець Божий?\nНемовля що тихенько спить у яслах це святий Господь Яхве', '', '', 'ua', NULL, 1, '2021-01-17', NULL),
(504, 1201, 'Освяти нас, Господь', 0, 'Куплет 1\nОсвяти нас, Господь, Освяти\nДухом Святым, освяти\nОсвяти нас, Господь освяти\nСердце моё зажги \n\nКуплет 2\nПробуди нас, Господь, пробуди\nДухом Святым, пробуди,\nПробуди нас, Господь, пробуди\nСердце моё зажги \n\nПриспів\nДождь, дождь, серебряный дождь,\nДождь Духа Святого\nДождь, дождь, серебряный дождь\nСердце моё наполнил\n\nКуплет 3\nОживи нас, Господь, оживи\nНебесною росой окропи,\nОживи нас, Господь, оживи\nСердце моё зажги \n\nКуплет 4\nБлагодарю, благодарю\nЗа всё Тебя благодарю, Иисус\nЗа всë, за всë благодарю', '', '', 'ua', NULL, 2, '2021-03-14', NULL),
(505, 1202, 'Вся земля лише Небеса співають', 0, 'Verse 1\nВся земля лише Тобі,\nВіддає усю хвалу,\nТи Бог неба і землі, \nТебе я прагну і молю\nТи найпрекрасніший з усіх на світі\nНема подібного Тобі\nТи наш Господь царюєш Ти навіки\nМи віддаєм хвалу Тобі\n\nRefrain\nНебеса співають Ти Святий! Святий!\nВеличає вся земля, Тебе Ісус,\nВсе творіння віддає, Тобі хвалу Господь\nБлагословенний Бог, Творець всього!\n\nVerse2\nХай тече жива вода, \nЗі святого джерела\nНаповняє нас щодня, \nЛюбов і радість від Отця\nСвоєю славою покрий всю землю,\nХай світло лине у життя,\nЛише Тобі ми хочемо служити,\nІ віддаєм свої серця!', '', '', 'ua', NULL, 1, '2021-01-24', NULL),
(506, 1203, 'Тобі, добрий Боже', 0, 'Куплет 1\nТобі, добрий Боже, співати бажаю\nРожевого ранку подячний псалом,\nЯ очі мої після сну відкриваю,\nОточений ласкою неба кругом.\n\nКуплет 2\nЧудово всміхається ранішнє сонце,\nПривіт променистий на землю нам шле,\nШироко відкрилося серця віконце,\nЧекає, що ласка Господня пошле.\n\nКуплет 3\nМелодія груди мої наповняє,\nЩасливі хвилини в союзі з Христом,\nНа струнах сердечних акорди лунають,\nХвалою бринять перед Божим лицем.\n\nКуплет 4\nУ серці моєму все спів не змовкає\nЗа всяких обставин лунають пісні\nЗневіру вони до душі не пускають\nМинає весь день, як у мрійному сні\n\nКуплет 5\nТа струни душі виграють серед ночі\nЧудову гармонію слави й хвали,\nІ хоч закриваються зморені очі,\nДуша моя лине до Тебе й тоді!', '', '', 'ua', NULL, 2, '2021-02-28', NULL),
(507, 1204, 'Ти є тут просто ', 0, 'Verse 1\nТи є тут просто серед нас\nТвоє Ім‘я прославлю я.      \nТи є тут, дієш у серцях.\nТвоє Ім‘я прославлю я.\n\nRefrain\nПровадиш, чуда вчиняєш\nТи Бог вірний, світло в темряві.\nМій Бог, знаю, Хто Ти є!\n\nVerse 2\nТи є тут зцілюєш серця\nТвоє Ім‘я прославлю я.   \nТи є тут змінюєш життя\nТвоє Ім‘я прославлю я.\n\nRefrain\nПровадиш, чуда вчиняєш\nТи Бог вірний, світло в темряві.\nМій Бог, знаю, Хто Ти є!\n\nVerse  4\nЗнаю, Хто Ти є!\nЗнаю, Хто Ти є!\nЗнаю, Хто Ти є!\nЗнаю, Хто Ти є!\n\nRefrain 2\nПровадиш, чуда вчиняєш\nТи Бог вірний, світло в темряві.\nМій Бог, знаю, Хто Ти є!\n\nVerse    БРІДЖ:\nІ коли навіть не відчуваю\nВсе одно довіряю і знаю:\nНіколи нас Ти не залишаєш!\nНіколи нас Ти не залишаєш!\n\nRefrain   ПРИСПІВ:\nПровадиш, чуда вчиняєш\nТи Бог вірний, світло в темряві.\nМій Бог, знаю, Хто Ти є!\n\nVerse   ПОВТОР:\nЗнаю, Хто Ти є!\nЗнаю, Хто Ти є!\nЗнаю, Хто Ти є!\nЗнаю, Хто Ти є!', '', '', 'ua', NULL, 0, NULL, NULL),
(508, 1205, 'Неописуемый такой ', 0, 'Verse 1\nНеописуемый такой мой Бог\nВо всех путях  Своих прекрасен  мой Господь\n\nVerse 1 КУПЛЕТ:\nПозвал меня Ты через воды\nИ стал так близко, все изменил \nТы показал мне смысл жизни\nСвое спасенье, и новый день - пою я\n\nVerse ПРЕД ПРИПЕВ:\nУуу, нет слов, чтоб описать\nУуу, прекрасен в Своих путях\nО Иисус, открыл Ты мои глаза\nЯ в сердце Твоем всегда мой Бог, мой Бог\n\nVerse ПРИПЕВ: \nНеописуемый такой мой Бог\nВо всех путях Своих прекрасен мой Господь\nИ не понять никак, не объяснить \nВсю полноту и глубину Твоей любви\n\n\nVerse 2 КУПЛЕТ:\nСвободу дал мне, теперь дышу я\nМоя награда быть с Тобой\nВойну Ты выиграл я в Твоем Царстве\nТебя прославлю, прими хвалу - я восхищаюсь\n\nVerse ПРЕД ПРИПЕВ:\nУуу, нет слов, чтоб описать\nУуу, прекрасен в Своих путях\nО Иисус, открыл Ты мои глаза\nЯ в сердце Твоем всегда мой Бог, мой Бог\n\nVerse ПРИПЕВ: \nНеописуемый такой мой Бог\nВо всех путях Своих прекрасен мой Господь\nИ не понять никак, не объяснить \nВсю полноту и глубину Твоей любви\n\nVerse ЗАПЕВ: X2\nНеописуемый, у-у-у \nНеописуемый, у-у-у \n\nVerse БРИДЖ:\nО любовь здесь Твоя\nИзливаешь благодать\nБез Тебя жить не могу\nТы зовешь Бог,  я пойду\n\nVerse ПРИПЕВ: \nНеописуемый такой мой Бог\nВо всех путях Своих прекрасен мой Господь\nИ не понять никак, не объяснить \nВсю полноту и глубину Твоей любви\n\nVerse ЗАПЕВ: X2\nНеописуемый, у-у-у \nНеописуемый, у-у-у', '', '', 'ua', NULL, 1, '2021-01-31', NULL),
(509, 1206, 'В голове сомнений нет/Любишь Ты меня', 0, 'Verse 1\nВ голове сомнений нет рой\nТвердит мне вновь и вновь о том,\nЧто я слаб, и не достигнуть\n\nVerse 2\nМне небес святых потом\nЗнаешь Ты падение и взлёты,\nБоже, все мои.\nТы напомни опять,\nКто я, Бог, и кто я\n\nRefrain\nЛюбишь Ты меня, хотя не вижу я,\nСила Ты моя, хотя и слабый я,\nДержишь Ты меня, когда я падаю\nКогда я сам с собой, Ты говоришь, я Твой.\nИ верю я, все твоим словам, верю я.\n\nVerse 3\nГоршечник Ты, я глина,\nБог, теперь в твоих святых руках.\nС тобой я буду здесь и вечно там,\nна небесах.\n\nVerse 4\nВсе венцы свои кладу к ногам\nТвоим святым, мой Бог.\nВсе падения, победы у Твоих святых, Бог мой.', '', '', 'ua', NULL, 0, NULL, NULL),
(510, 1207, 'О, Благодать!', 0, 'Verse 1\nО, Благодать! Спасенний я.\nМене Господь звільнив\nХоч мертвим був - вдихнув життя\nСліпим був та - прозрів.\n\nVerse2\nЦе благодать забрала страх\nЩо душу полонив\nІ Божий страх мені дала\nТепер у серці мир.\n\n\nRefrain 1\nВін з мене зняв кайдани всі.\nГосподь - Спаситель мене звільнив\nЙого любов - немов ріка\nО, Благодать! Спасенний я.\n\nVerse 3\nГосподь добро пообіцяв \nВірний буде Він,\nМій щит і частка Він моя\nТвердиня моїх днів.\n\nRefrain 1\nВін з мене зняв кайдани всі.\nГосподь - Спаситель мене звільнив\nЙого любов - немов ріка\nО, Благодать! Спасенний я.\n\nVerse 4 \nГосподь добро по обіцяв\nІ він вірний буде\nМій щит і частка Він моя.\nТвердиня моїх днів\n\n\nVerse 5\nВже охолоне сонця жар \nЗемля припинить рух\nА я Отцю на небесах\nСпіватиму хвалу!', '', '', 'ua', NULL, 4, '2021-02-28', NULL),
(511, 1208, 'Жертвой Иисуса Христа', 0, 'Куплет 1\nЖертвой Иисуса Христа я спасён от огня, \nРанами Иисуса Христа я исцелён - нет сомнения. \nКровью Иисуса Христа я омыт от греха, \nЧерез смерть Иисуса Христа мне дана\nЖизнь вечная. \n\nПриспів\nБлагослови душа моя, Господа, \nИ вся внутренность моя святое имя Его! \nБлагослови душа моя, Господа, \nИ не забывай всех благодеяни\n\nКуплет 2\nЯ верю в Голгофскую жертву, \nКровь святую Твою, жизнь вечную. \nВ то, что имя мое записано на небесах.', '', '', 'ua', NULL, 1, '2021-03-07', NULL),
(512, 1209, 'Сповняй мене Боже навчи мене ', 0, 'Куплет 1:\nСповняй мене\nДобром Своїм і милістю, Господь\nБо Ти Один - любов, і за людей\nСвого сина дав, нас врятував\n\nПриспів:\nБоже, навчи мене любити так, як Ти\nЛюбов\'ю, яка стирає межі і знайти\nправду Твою я зможу, й бачитимуть всі\nв сяйві моїх очей Твою Батьківську любов\n\nКуплет 2:\nТак полюбив\nВід бездомних до відомих, просто всіх\nСтворив Ти й любов\'ю нас покрив\nБо правда в тім, що ми Твої діти\n\nКуплет 3 Брідж:\nУсім життям прославлю я Тебе\nЗа любов, що кожну мить Ти нам даєш\nУсім життям прославлю я Тебе\nПрекрасний Ти і Люблячий Батько', '', '', 'ua', NULL, 0, NULL, NULL),
(513, 1210, 'Любов Христа безмірна / Якщо б любові не було', 0, 'Verse 1\nЛюбов Христа безмірна і палка\nНема початку і ллється як ріка\nІ наче хвиля близько берегів\nТак і вона близька споконвіків.\n\nVerse 2\nВін полюбив тебе, мене давно \nВін полюбив і тих, хто всео дно\nКричали ,,Ні\"- і підіймали сміх.\nА Він з любов\'ю закликає всіх.\n\nRefrain \nЯкщо б любові не було\nМи б не змогли здолати зло,\nНадію мати на життя,\nЩо може дати лиш любов Христа.\n\nVerse 3\nЯкби пізнали люди на землі\nЛюбов Христа спрямовану до всіх,\nЯкщо забрати хоть на мить,\nТо світ увесь в ненависті згорить.\n\nVerse 4\nПрийди до Нього швидше, не барись,\nДавно чекає Він, лише звернись,\nЩе кличе Він, прийми любов Христа,\nЩо дасть тобі спасіння і життя.', '', '', 'ua', NULL, 1, '2021-03-14', NULL),
(514, 1211, 'Мы с вами столько верст / ', 0, 'Verse   1 КУПЛЕТ:\nМы с вами столько верст уже прошли,\nПусть мало было в них тепла и неги,\nЗато теперь осталось позади\nПо полдороги в небо, по полдороги в небо,\nПо полдороги в небо\n\nVerse    2 КУПЛЕТ:\nТревожно, что замедлили шаги\nЧто в ком-то тает робкая надежда,\nА ведь у нас осталось впереди\nПо полдороги небо (3р)\n\nVerse   3 КУПЛЕТ:\nКому-то надо руку протянуть,\nКого-то надо бережно заметить.\nКак страшно потерять кого-нибудь\nНа полдороги в небо (3р)\n\nVerse   4 КУПЛЕТ:\nНе дай, Господь, кому из нас вздремнуть\nНе дай запачкать белые одежды.\nОсталось, может несколько минут\nОт пол дороги в небо (3р)', '', '', 'ua', NULL, 1, '2021-03-14', NULL),
(515, 1212, 'Там на Віа Долороса, у Єрусалим в той день', 0, 'Куплет 1\nТам по Віа Долороса, у Єрусалим в той день\nЛюдські юрби прибували звідусіль.\nРимські воїни вели\nЧоловіка, що мав вмерти на хресті.\n\nКуплет 2\nЗ ран Його сочилась кров, \nа меч рвав рани на спині,\nІ корону мав з тернини на чолі.\nЗ кожним кроком знемагав\nВід зойків тих, хто так кричав: \"Розіпни!\"\n\nRefrain\nТам на Віа Долороса по шляху страждань і сліз,\nЯк ягня, ішов Месія, Цар Христос.\nВін вибрав цю дорогу, щоб спасти тебе и мене! \nЙшов Христос по Долороса, що веде до Голгофи.\n\nКуплет 3\nВін терпів, був спокійний\nХоч страждав та й ще знеміг\nБув за грішників Безгрішнем в Бородобі\nВорогів не докорял та любов свою до Всіх Він доказав\n\nКуплет 4\nА сонче палить, і небо мовчить, запашений\nБатьком Божий Син\n\nКуплет 5 \nТа кров, що спасла людей від гріха\nВкрила щлях до гори Голгофа', '', '', 'ua', NULL, 1, '2021-04-02', NULL),
(516, 1213, 'Слава! Слава Алілуя!', 0, 'Куплет 1\nХай всі народи радісно співають \nБо наш Господь Воскрес! і з мертвих встав\nІ перед Ним всі схиляться коліна\nЩо Він- Господь всі визнають уста.\n\nПриспів\nСлава! Слава Алілуя!\nСлава, слава Царю!\n\nКуплет 2\nВін Цар царів Він пан над панами\nВін є Господь- Творець усіх творів\nЙому співайте разом із нами\nДостойний слави тільки Він один.\n \nКуплет 3\nЛиш Він один сесія Він Спаситель\nЛиш Він один дав бути з ним в раю\nТому Йому ми будемо служити \nІ дарувати всю любов свою.', '', '', 'ua', NULL, 1, '2021-04-04', NULL),
(517, 1214, 'Стемніло навкруги ', 0, 'Verse 1\nСтемніло навкруги пітьма накрила світ\nСпасителя Христа розп’яли\nІ тіло на хресті —\nВін кров пролив за всіх проклятя і гріхи на Ньому\n\nVerse 2\nЯ віддаю дух Мій, в руки, Отець, Твої —\nБув розп’ятий за нас Син Божий.\nІ боротьба в пітьмі, та смерть Він переміг:\nОтримав тут спасіння кожен!\n\nRefrain \nТут потряслась земля завіса розтялась.\nЛюбов Отця непереможна!\nДе жало твоє, смерть? Ісус за нас воскрес!\nВоскрес Христос, воскрес назавжди!\n\nVerse\nНавіки ти прославлений!\nНавіки Ти вознесений!\nНавіки Ти воскрес!\nТи — живий!\nТи — живий!\n\nVerse\nСпіваєм: «Алілуя»\nСпіваєм: «Алілуя»\nСпіваєм: «Алілуя»\nАгнець прославлений!', '', '', 'ua', NULL, 1, '2021-04-04', NULL),
(518, 1215, 'Пусть всё творенье пусть вся земля', 0, 'Verse 1\nПусть всё творенье пусть вся земля\nПуть приготовит для Бога Царя\nВскоре придёт Иисус\nГрешных спасайте будите святых\nПусть Его славят народы земли\nВскоре придёт Иисус\nRefrain\nКак жениха Его невеста ждёт\nЦерковь Твоя ждёт Твой приход\nЖдут Царя все сердца земли\nПоём мы - Бог наш приди, Иисус приди.\nVerse 2\nВсё восстановишь всё обновишь\nИстинным, верным в веках Ты стоишь\nВскоре придёт Иисус\n\nVerse\nМы так ждём в сердцах своих\nБог, мы ждём скорей приди', '', '', 'ua', NULL, 1, '2021-04-04', NULL),
(519, 1216, 'На нас излей, Бог,', 0, 'Куплет 1\nНа нас излей, Бог,\nДух Святой.\nЗажги в нас пламя \nТой любви живой.\n\nПриспів\nУ ног Твоих я склонюсь,\nК славе Твоей прикоснусь.     \nБоже Святой, крик мой услышь,\nИ приди в наш мир!\n\nКуплет 2 \nПравишь Ты над всей Землёй,\nВ нас Иисус - Твой Сын живой.\nВ церкви вновь зажги огонь,\nПогружая в Дух Святой!', '', '', 'ua', NULL, 4, '2021-04-05', NULL),
(520, 1, 'Отче наш', 29, 'Куплет 1\nОтче наш, що єси на небесах!\nНехай святиться Ім’я Твоє,\nНехай прийде Царство Твоє,\nНехай буде воля Твоя, як на небі, так і на землі.\n\nRefrain \nХліб наш насущний дай нам сьогодні;\nІ прости нам провини наші,\nЯк і ми прощаєм винуватцям нашим.\nІ відверни нас від спокуси,\n\nVerse 2\nАле визволи нас від лукавого.\nБо Твоє є Царство і сила,\nІ слава во віки віків. Амінь.', '', '', 'ua', NULL, 4, '2020-10-11', NULL),
(521, 2, 'Отче Небесний Боже Могутній', 1, 'Куплет 1\nОтче Небесний, Боже Могутній,\nТи Утішитель, Дух Правди  Ти,\nВсюди присутній і Всевідучий,\nБудь тут із нами, нас просвіти!\n\nКуплет 2\nОтче Небесний, Скарбе ласк многих!\nНас, дітей своїх, не забувай;\nПрийди, вселися в серцях убогих,\nБлагослови нас, щастя нам дай!\n\nКуплет 3\nОтче Небесний, збав нас від скверни\n І чистотою душу вкраси;\nХай Твоя ласка радість нам верне,-\n Нас у недолі, Боже, спаси!', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(522, 3, 'О Боже вчуй мене Господи мій', 0, 'Куплет 1\nО, Боже, вчуй мене, Господи мій!\nХочу Тебе любить якнайщиріш.\nХочу Тебе любить (2р.) якнайщиріш (2р.).\n\nКуплет 2\nХочу сердечно я із коленим днем Твоє хвалить Ім’я любві вогнем.\nТвоє хвалить Ім’я (2р.) любві вогнем (2р.).\n\nКуплет 3\nБлукав я в марноті - до зла ішов,\nА щастя лиш в Христі навік знайшов.\nА щастя лиш в Христі (2р.) навік знайшов (2р.).\n\nКуплет 4\nСкорботи іноді смутять спокій, - Хочу я і тоді любить щиріш.\nХочу я і тоді (2р.) любить щиріш (2р.).\n\nКуплет 5\nКоли й моє життя в вічність піде,\nБуду і в небі я любить Тебе.\nБуду і в небі я (2р.) любить Тебе (2р.).\n\nКуплет 6\nІ вірю, - буду там у славі жить,\nДе вічний Божий храм, Творця хвалить.\nДе вічний Божий храм (2р.), Творця хвалить (2р.).', '', '', 'ua', NULL, 0, NULL, NULL),
(523, 4, 'О Боже милосердний Ти нас благослови', 0, 'Куплет 1\nО, Боже милосердний, Ти нас благослови,- \nСвій дощ ізлий небесний: /серця всіх оживи!/(2р.)\n\nКуплет 2\nДай нам у всьому мудрість, у праці помагай,\n Небесне світло - радість /постійно посилай!/ (2р.)\n\nКуплет 3\nЗавсіди будь Ти з нами: навчай, охороняй, - \nПремудрими путями /до Царства направляй!/ (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(524, 5, 'Боже почуй мої моління', 0, 'Куплет 1\nБоже, почуй мої моління,\nТебе, Господь, благаю я:\nПрийми мій плач і сокрушіння,- \nВ Тобі надія вся моя!\n\nКуплет 2\nМоя молитва нехай лине \nДо Тебе, наче фіміам,\nІ серце лине безупинно \nВ чудовий Твій небесний храм.\n\nКуплет 3\nСердечно я Тебе благаю, - \nПрости мені, чим я згрішив;\nТобі злі вчинки відкриваю,\nПровини всіх минулих днів.\n\nКуплет 4\nПрости усі мої провини,\nСкорботне серце підкріпляй:\nВ безрадній і тяжкій годині \nДля боротьби Ти сили дай.\n\nКуплет 5\nЩоб повсякчасно за Тобою \nУ світлі правди міг я йти.\nМій Боже, я Тебе благаю,- \nПочуй мої моління Ти!', '', '', 'ua', NULL, 0, NULL, NULL),
(525, 6, 'О Господи Боже благаю Тебе', 0, 'Куплет 1\nО, Господи Боже, благаю Тебе:\nВізьми Ти у жертву життя все моє;\nОчисть моє серце і дух обнови,\nОбмий всі провини в пречистій крові!\n\nПриспів: \nКров’ю обмий, кров’ю обмий,\nЗішли в моє серце небесний спокій!\n\nКуплет 2\nО, Господи Боже, почуй Ти мене,\nНавчи прославляти Ім’я лиш Твоє;\nІзлий в моє серце святу благодать,\nДай радість спасіння душею прийнять!\n\nКуплет 3\nОбмий мою душу в пречистій крові,\nІ стану, обмитий, за сніг я біліш.\nО Боже, дай твердість у вірі мені,\nЩоб овоч приносив завжди я Тобі!', '', '', 'ua', NULL, 0, NULL, NULL),
(526, 7, 'Не минай мене мій Спасе', 0, 'Куплет 1\nНе минай мене, мій Спасе, - в серце світла дай!\nВсюди молять Тебе люди: Боже, не минай!\n\nПриспів: \nБоже, Боже, о почуй мене!\nВсюди молять Тебе люди: Не минай мене!\n\nКуплет 2\nЯ утомлений душею, - поможи мені,\nБудь завсіди Ти зі мною в тяжкі й кращі дні.\n\nКуплет 3\nЯ на Тебе покладаю надії мої, - \nОживи мій дух, благаю, сили дай мені!', '', '', 'ua', NULL, 0, NULL, NULL),
(527, 8, 'Я утомлений безсилий', 0, 'Куплет 1\nЯ утомлений, безсилий, Боже мій, до Тебе йду!\nТільки в Тобі, Боже милий, Я спокій душі знайду!\n\nПриспів: \nБоже мій, до Тебе йду я,\nОживи мене, молю!\nПідкріпляй постійно Духом,\nСерцю дай любов Твою!\n\nКуплет 2\nБезутішний, скрізь блукав я, - де ж міг радість я знайти?\nДо Тебе тепер прийшов я: вірю, втішиш мене Ти.\n\nКуплет 3\nВсю марноту і тривогу Сам розвій, о Боже мій;\nПоможи пройти дорогу-цей тернистий шлях земний!\n\nКуплет 4\nІ коли я знеможуся в боротьбі тут на землі, - \nМій Спасителю, молюся, поможи тоді мені!', '', '', 'ua', NULL, 0, NULL, NULL),
(528, 9, 'Я чую поклик Твій', 0, 'Куплет 1\nЯ чую поклик Твій, ласкавий Спасе мій, - \nОбмитися в Крові святій, знайти душі спокій!\n\nПриспів: \nО, Спаситель мій, йду до Тебе я:\nВірю, змиє гріх тяжкий Пречиста Кров Твоя!\n\nКуплет 2\nНадія вся моя і сила лиш в Тобі:\nКріплюсь Тобою завжди я в життєвій боротьбі.\n\nКуплет 3\nТи всім життя даєш, хто за Тобою йде,\nІ в Царство Правди тих ведеш, в любові хто живе.\n\nКуплет 4\nСпасителю, хвала, хвала любві Т воїй:\nДуша моя в Тобі знайшла і радість, і спокій!', '', '', 'ua', NULL, 0, NULL, NULL),
(529, 10, 'О Спаситель через хвилі', 0, 'Куплет 1\n О, Спаситель, через хвилі, через степи нас веди: \nНемічні ми і безсильні, - завжди перед нами йди; \nХліб небесний (2р.) дай нам, любий Спасе наш!\n\nКуплет 2\nІ струмінь води живої нам відкрий Ти із скали;\nНас дорогою вузькою Сам, Спасителю, веди!\nО, Спаситель (2р.), будь Ти з нами в кожний час!\n\nКуплет 3\nСтоїмо ми над Йорданом, — нам дорогу освіти, \nЩоб в Країну ту бажану всі могли ми увійти;\nСпів хваління (2р.) буде линути Тобі!', '', '', 'ua', NULL, 0, NULL, NULL),
(530, 11, 'О Спаситель благодать на святі слова пролий', 0, 'Куплет 1\nО, Спаситель, благодать на святі слова пролий!\nДай нам більше пізнавать волю у любві Твоїй.\n\nПриспів:\nДух єднання дай серцям, в святості охороняй,\n Засіяй, як сонце, нам, - Твоїм Словом научай!\n\nКуплет 2\nХай відкриє Святий Дух наше серце і наш слух -\n На святі діла любві, Боже, нас благослови!', '', '', 'ua', NULL, 0, NULL, NULL),
(531, 12, 'Спасителю будь з нами всіх нас охороняй', 0, 'Куплет 1\nСпасителю, будь з нами, всіх нас охороняй, -\nПремудрими путями до світла направляй!\n\nКуплет 2\nО, Боже, пробуди світ, людей об’єдини,\nЩоб за Тобою йшли вслід, у згоді всі жили!\n\nКуплет 3\nДай нам думки єдині, любов зогрій в серцях,\nЩоб всі були ми вірні у правді до кінця!\n\nКуплет 4\nСпасителю ласкавий, Ти нас благослови; \nПролий дощ благодатний, - нас знову оживи!', '', '', 'ua', NULL, 0, NULL, NULL),
(532, 13, 'Милосердний Спасе вічно з нами будь', 0, 'Куплет 1\nМилосердний Спасе, вічно з нами будь,\nЩоб небесний голос Твій могли ми чуть.\nВелика нам радість, коли Ти із нами:\nТи нас підкріпляєш живими словами В скорботах всіх.\n\nКуплет 2\nЩоб спасти загиблих, Ти з небес зійшов,\nНа цей світ скорботний у тілі прийшов;\nЗа нас, о Спаситель, терпів Ти страждання, \nЩоб грішним нам дати усім оправдання В крові святій.\n\nКуплет 3\nТи нас захищаєш, як пастир овець;\nТи покірних любиш, як сина отець;\nДай нам більше віри, втішай Святим Духом. \nПостійно будь нашим Заступником, Другом,\nНас научай!\n\nКуплет 4\nО, дай шлях тернистий в святості пройти,\nІ для Тебе, Спасе, овоч принести.\nНавчи ж нас завсіди на Тебе взирати,\nТепер і повіки Тебе прославляти В Царстві Твоїм!', '', '', 'ua', NULL, 0, NULL, NULL),
(533, 14, 'Ось зібрались знову ми Тебе Отче прославлять', 0, 'Куплет 1\nОсь зібрались знову ми Тебе, Отче, прославлять. \nБоже наш, хвалу прийми, - і пошли нам благодать! \nДух наш в вірі підкріпляй, щоб Тобою ми жили,- \nКрай земний, дочасний край свято, радісно пройшли.\n\nКуплет 2\nО, Спасителю, навчай, як у світі маєм жить.\nСилу Духа посилай, щоб могли ми всіх любить. Поможи, щоб ми жили в згоді, як одна сім’я, Вірними у всім були до приходу Твого дня!\n\nКуплет 3\nБудем з радістю в серцях Господа Отця молить, - Віджене Він горе, страх, вірних нас благословить. Всю забудьмо марноту, будем Господу співать,\nІ Спасителю Христу, у піснях хвалу складать.', '', '', 'ua', NULL, 0, NULL, NULL),
(534, 15, 'Предвічний Дух прийди Любов в серцях зогрій', 0, 'Куплет 1\nПредвічний Дух, прийди! Любов в серцях зогрій \nІ Царство Правди утверди поміж Твоїх дітей.\n\nКуплет 2\nДай чисті почуття, будь з нами в кожний час, \nОсвітлюй темряву життя, веди вперед Ти нас.\n\nКуплет 3\nДай глибше нам пізнать премудрість слів Твоїх,\nНавчи Твій голос відрізнять від голосів чужих.\n\nКуплет 4\nНавчи перемагать спокуси всі земні;\nНавчи нас правди лиш шукать в небесній стороні.\n\nКуплет 5\nДай з радістю приймать страждання за Тебе,\nЩоб все життя могли віддать в служінні для Тебе.', '', '', 'ua', NULL, 0, NULL, NULL),
(535, 16, 'О Спасе мій благаю я', 0, 'Куплет 1\n О, Спасе мій, благаю я: прости провини всі мої!\nВ тузі моїй приходжу я й гріхи всі визнаю Тобі.\n\nКуплет 2\nОсь боротьбу з гріхом веду, і сам не маю сили я;\nЗа поміччю до Тебе йду: безмірна є любов Твоя!\n\nКуплет 3\nВід всіх гріхів мене обмий, дух підкріпи, пошли спокій. \nПрости мені, Спаситель мій, і буду вже повік я Твій!\n\nКуплет 4\n \nМене, о Боже, не суди, - перед Тобою я стою;\nПо милості Твоїй прости, прости, Спасителю, молю!\n\nКуплет 5\nРозбійника Ти сам простив і двері в рай йому відкрив; \nІ я на поклик Твій спішу, прощення, Господи, прошу!', '', '', 'ua', NULL, 0, NULL, NULL),
(536, 17, 'Ісуса люблю я бо Він спас мене', 0, 'Куплет 1\nІсуса люблю я, бо Він спас мене;\nДо Нього молюся, бо Він чує все.\nМій любий Ісусе, за мене Ти вмер, - \nЛюбити я щиро бажаю Тебе!\n\nКуплет 2\nВ житті і в час смерті любитиму я\n Спасительну жертву Благого Христа,\nМій любий Ісусе, Ти гріх мій простив,\nСлужити я завжди бажаю Тобі!\n\nКуплет 3\nУ славі небесній, при зборі святих \nІз уст спів чудесний поллється моїх.\nТам вічно вже буду я жити в Христі,\nА горе забуду, що мав на землі!', '', '', 'ua', NULL, 0, NULL, NULL),
(537, 18, 'Днесь молитви шлемо ми', 0, 'Куплет 1\nДнесь молитви шлемо ми,- друже, чуєш біль душі?\nТебе кличе Дух Святий, - чи ж не прийдеш, друже мій?\n\nПриспів: \nО, спіши (о, спіши), о, спіши (о, спіши), \nДнесь до Господа прийди! (2р)\nТи далеко заблудив; чи ж так й далі будеш жить?\nНаверни лице своє: тобі ласку Спас дає..\n\nКуплет 2\nТебе світ обманював, і спокою ти не знав;\nДо Христа вернись мерщій, в Нім однім знайдеш спокій.\n\nКуплет 3\nПрийди, визнай кожний гріх, - Він є Лікар ран твоїх. \nВсе життя віддай Христу, - душу Він спасе твою.', '', '', 'ua', NULL, 0, NULL, NULL),
(538, 19, 'Всім серцем прагну я хвалить Небесного Отця', 0, 'Куплет 1\nВсім серцем прагну я хвалить Небесного Отця, \nБажаю Богові служить в житті цім до кінця.\n\nКуплет 2\nХристос за мене постраждав, - мене Він полюбив;\nГосподь життя Своє віддав, - і двері в рай відкрив.\n\nКуплет 3\nПодяку, честь, хвалу Христу спішу в піснях складать: \nВін кров пролив Свою святу; нас хоче оправдать.\n\nКуплет 4\nІ ти, о друже змучений, Христа не забувай:\nПовір, - і ти відкуплений! Іди в Небесний Край!\n\nКуплет 5\nЖиттям святим ти приклад дай, шоб грішники прийшли \nДо ніг Спасителя Христа й спасіння в Нім знайшли.\n\nКуплет 6\nВ цей час смиренно всі прийдім до Господа Творця, \nВін сповнить Духом нас Святим, утішить всі серця.', '', '', 'ua', NULL, 0, NULL, NULL),
(539, 20, 'Гляньте браття вгору в синій небозвід', 0, 'Куплет 1\nГляньте, браття, вгору, в синій небозвід,\nНа шляхи небесні, на молочний слід!\nСонце, місяць, зорі, - хто їх засвітив?\nТу красу Всесильний Бог наш сотворив.\n\nКуплет 2\nГляньте, браття, в море, в темний океан,\nЩо водно хвилює, мов пшеничний лан.\nХто життям глибини морські наповнив?\nТвори ті Всесильний Бог наш сотворив.\n\nКуплет 3\nГляньте, любі браття, в повітряний світ:\nВесело гуляє там пташиний рід.\nХто орлам, соколам крила приростив?\nДива ті Всесильний Бог наш сотворив.\n\nКуплет 4\nГляньте кругом себе, на луги й поля:\nПишно вбрана в квіти рідная земля.\nХто в ліси й левади звірів нагніздив?\nВсе те Всемогутній Бог наш сотворив.\n\nКуплет 5\nГляньте всі на себе, гляньте на братів!\nХто серденькам нашим битися звелів?\nХто спрагу науки й віри в нас вселив?\nВсе це, браття, Бог дав, Він це сотворив.\n\nКуплет 6\nХто світи тримає у своїх руках,\nТак про сонце дбає, як і про комах, - \nТой ще більше дбає про дітей Своїх:\nДобром наділяє Господь нас усіх.', '', '', 'ua', NULL, 0, NULL, NULL),
(540, 21, 'Як славний наш Господь в Сіоні', 0, 'Куплет 1\nЯк славний наш Господь в Сіоні,\nТого наш розум не обняв;\nВеличний в небесах на троні - \nЖиття Він всьому й устрій дав.\nТи, Боже наш, повсюди славний,\nТи серед дня і ночі явний.\n\nКуплет 2\nТи сонця світло посилаєш \nВ проміннях ясних для людей,\nНебесним хлібом підкріпляєш \nСвоїх улюблених дітей.\nТи смертних, Боже, навіщаєш \nІ благодаттю оживляєш.\n\nКуплет 3\nО, Господи, у Край Небесний \nХай дійдуть наші голоси,\nПрийми хваління спів сердечний,\nЯк перли ранньої роси.\nСерця для Тебе відкриваєм,\nТебе в піснях ми величаєм!', '', '', 'ua', NULL, 0, NULL, NULL),
(541, 22, 'Коли в житті цім утомлюся', 0, 'Куплет 1\nКоли в житті цім утомлюся,\nВ борні затрачу я спокій,\nТоді благаю і молюся:\nПошли спокій, о Боже мій!\n\nПриспів:\n Зішли спокій примирення,\nДай мир і радощі спасіння,\nПошли бажаний спокій,\nО, Боже мій, пошли спокій!\n\nКуплет 2\nСкажи лиш слово - й стихне буря,\nУляжуть хвилі, і спокій.\nВсі прожене думки понурі,- \nІ стане знову світ ясний.\n\nКуплет 3\nЗнов проясни мою свідомість, - \nЩо тільки Ти Спаситель мій,\nЩо Ти зі мною в час утоми,\nІ в час досвідчень, в час грізний!\n\nКуплет 4\nІ Бог моління ці приймає \nИ душі зсилає свій спокій,\nІ їй предивно сповіщає,\nЩо дасть спокій ще більш ясний.\n\nКуплет 5\nНе буде то спокій вмирання,\nЧи спокій сну, чи забуття...\nЦе буде спокій воскресіння,\nІ спокій райського життя.\n\nКуплет 6\nТо буде спокій всехваління \nПо перемозі світлих сил,\nВ безсмерті вічного спасіння,\nКоли загине страх могил.', '', '', 'ua', NULL, 0, NULL, NULL),
(542, 23, 'Я знаю так я знаю живе Спаситель мій', 0, 'Куплет 1\nЯ знаю, так, я знаю, - живе Спаситель мій:\nВ Нім однім я лиш маю і радість, і спокій (2р.).\n\nКуплет 2\nЯ знаю, хто в хвилини недолі і журби \nМені дарує сили в земній тут боротьбі (2р.).\n\nКуплет 3\nЯ знаю, що скорботну Він душу утіша:\nНасичує голодну, на поміч поспіша (2р.).\n\nКуплет 4\nЯ знаю, навіть з мертвих мене підійме Він.\nВін знищив жало смерті: жить вічно буду з Ним (2р.).', '', '', 'ua', NULL, 0, NULL, NULL),
(543, 24, 'У Край Небесний я іду', 0, 'Куплет 1\nУ Край Небесний я іду,\nДе всі багатства у Христа:\nТам відпочинок я знайду,\nБлаженство вічного життя.\n\nПриспів: \nО, дивний Край, небесний рай!\nТуди, туди пливе човен,\nДе в ясних променях життя \nВ оселях вічних у Христа,\nЯ бачу берег вже новий,\nДе наш царює Бог Живий!\n\nКуплет 2\nЯ йду услід лиш за Христом,\nВеде мене Він під щитом;\nНадія в Нім моя уся:\nВвійду за Ним у небеса.\n\nКуплет 3\nВ краю тім дерева цвітуть,\nКвітки чудовий запах ллють,\nЖива вода струмком дзюрчить,\nНіколи там не в’яне цвіт.\n\nКуплет 4\nТам тихий віє вітерець,\nПриносить радість для сердець:\nТо — пісня ангелів святих \nДалеко від тривог земних.', '', '', 'ua', NULL, 0, NULL, NULL),
(544, 25, 'Честь Тобі Спаситель слава Тяжкі муки Ти прийняв', 0, 'Куплет 1\nЧесть Тобі, Спаситель, слава! Тяжкі муки Ти прийняв; \nЩоб були ми діти Божі, право радісне нам дав.\n\nПриспів: \nЧесть Тобі, Спаситель, слава!\nТяжкі муки Ти прийняв; \nЩоб були ми діти Божі,\nПраво радісне нам дав.\n\nКуплет 2\nДовго я блукав у світі, прагнув щастя і добра, —\nЛиш тепер усе знайшов я у Спасителя Христа.\n\nКуплет 3\nІ тепер моя надія на Христа - Його любов;\nЛиш Йому я довіряю: Він пролив за мене кров.\n\nКуплет 4\nІ живу я чи вмираю, — Відкупитель вічно мій:\nЛиш Йому хвалу складаю, - в Нім вся радість і спокій!\n\nКуплет 5\nВін, як Пастир, щохвилини стереже мене від зла \nІ до вічної Країни приведе, - Йому хвала!\n\nКуплет 6\nЧесть Тобі, Ісусе, й слава за терпіння на хресті,\nІ за поклик Твій ласкавий до життя в святій красі!', '', '', 'ua', NULL, 0, NULL, NULL),
(545, 26, 'Великий Бог Коли на світ погляну', 0, 'Куплет 1\nВеликий Бог! Коли на світ погляну,\nІ бачу все, що Ти створив в красі,\nЯк кожний цвіт склада Тобі пошану,\nІ як обняв любов’ю Ти усіх.\n\nПриспів:  \nТоді, Господь, мій дух співа Тобі:\nЯк славен Ти! Як славен Ти! - 2р\n\nКуплет 2\nКоли дивлюсь на мерехтючі зорі - \nТам, де горять світи незнані нам,\nДе сонце й місяць в вічному просторі \nПливуть в тиші, подібно кораблям.\n\nКуплет 3\nЯк навесні природа розцвітає,\nІ чую я в діброві солов’я,\nІ запах піль квітуючих вдихаю,\nЛюбов’ю сповнена душа моя.\n\nКуплет 4\nКоли із хмар навислих грім лунає,\nІ в пітьмі ночі блискавка мигтить,\nЯк під дощем природа оживає,\nВеселка в небі барвно заяснить.\n\nКуплет 5\nКоли беру я Книгу Заповітів,\nІ про Твої читаю я діла: \nЯк полюбив Ти нас, людей на світі \nІ для спасіння Сина нам послав.\n\nКуплет 6\nЯк зрю Христа cмиренного між людом,\nІ думаю я про Його любов,\nЯк Він прийняв за нас усіх наругу,\nІ на хресті пролив невинну кров.\n\nКуплет 7\nКоли спокуси серце огортають,\nІ дух мій тужить у важкій журбі,\nІ Він пречисті руки простягає,\nІ я кріплюсь в Його любві святій.\n\nКуплет 8\nКоли Господь мене Сам закликає,\nІ світить промінь сяєва Його, - \nТоді мій дух в смиренні замовкає,\nПризнавши велич Господа свого.', '', '', 'ua', NULL, 5, '2020-08-23', NULL),
(546, 27, 'Як зір багато є вгорі', 0, 'Куплет 1\nЯк зір багато є вгорі! \nЗоря ясніша від зорі.\nТа краще зір усіх краса \nЛюбові вічної Христа! (2р.)\n\nПриспів: \nЛюбов Христа (Зр.) -\nВона світліша сонця й зір.\n\nКуплет 2\nО, серце стомлене, радій:\nТворець усіх - Спаситель твій...\nЛюбов Христа шляхом вузьким \nВведе тебе у Вічний Дім (2р.).\n\nКуплет 3\nЛюбов веде всіх до Христа \nКрізь морок зла, в тісні врата; \nВона свята душі моїй, - \nЯ довіряюсь тільки їй (2р.).\n\nКуплет 4\nЯк зір багато є вгорі!\nЗоря ясніша від зорі,\nТа краще зір усіх краса \nЛюбові вічної Христа! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(547, 28, 'Є кращий інший світлий Край', 0, 'Куплет 1\nЄ кращий інший - світлий Край, | світ ясний! (2р.) \nНезнаний там є сум, відчай - | Край Святий! (2р.) \nСпівають там святі пісні,\nІ духи там живуть ясні.\nНіхто не знає там гріха, - | світ ясний! (2р.)\n\nКуплет 2\nБлакитне небо там без хмар, - | світлий край! (2р.) \nЖиття не має там примар, | Божий рай! (2р.)\nІ радості там без кінця \nПеред ясним лицем Творця.\nТам скрізь нев’януча краса, | дивний Край! (2р.)\n\nКуплет 3\nМи винні всі перед Христом, - | Він нас спас! (2р.) \nХоч світ пройнятий весь гріхом, — І Він нас спас! (2р.) \nІ Хто прийшов страждать за нас,\nТой може знять провини з нас,\nІ в край блаженства нас введе, — | Він нас спас! (2р.)\n\nКуплет 4\nЗа Господом усі ідіть, | вслід за Ним! (2р.)\nЗ Ним будемо там вічно жить,- | вслід за Ним! (2р.) \nНе гайтесь! Скоро час іде, - \nЧи в вірі вас Господь знайде,\nКоли за нами знов прийде? | Вслід за Ним! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(548, 29, 'Я співаю як Спаситель мене дивно полюбив', 0, 'Куплет 1\nЯ співаю, як Спаситель мене дивно полюбив.\nЯк страждав Він, мій Учитель,\nІ мене навік простив.\n\nПриспів:\nПісня ллється про Ісуса, смертю Він мене купив, \nКров пролив Свою невинну і мої гріхи простив..\n\nКуплет 2\nЯ співаю - дивні звуки: щоб мене від мук спасти, \nВін прийняв за мене муки,\nДав Себе Він розп’ясти.\n\nКуплет 3\nЯ співаю, як Спаситель в небі чистому сія,\nЯк всіх любить Відкупитель, - \nВічно з Ним там буду я .', '', '', 'ua', NULL, 0, NULL, NULL),
(549, 30, 'Дізнавсь я про Церкву живую', 0, 'Куплет 1\nДізнавсь я про Церкву живую -\n В ній радість для серця знайшов,\nНікуди вже більш не піду я,\nПрийнявши Христову любов.\n\nПриспів: \nО, друже, йди в Церкву живую,\nТам спокій і радість знайдеш.\nПовір і віддайся Ісусу,\nУ вічне блаженство ввійдеш.\n\nКуплет 2\nЧи знаєте Церкву живую ви,\nБраття і сестри мої?\nІдіть на дорогу святую - \nДо Церкви живої усі!\n\nКуплет 3\nСерця, що не мали спокою,\nЗнайшли там і щастя й спокій:\nТам ллються молитви рікою, - \nЖиве наш Спаситель у ній.\n\nКуплет 4\nХодив я усюди по світу,\nІ щастя ніде не знайшов;\nЗакінчився шлях безпросвітний,\nКоли я в ту Церкву прийшов.', '', '', 'ua', NULL, 0, NULL, NULL),
(550, 31, 'Бог є любов о велике щастя', 0, 'Куплет 1\nБог є любов, о велике щастя!\nБог є любов, любить Він і нас.\n\nПриспів: \nХай кожний радісно співа та славить,\n Його хай славить: Бог є любов!\n\nКуплет 2\nБог є любов; ми Його не знали;\nБог є любов, Він нам світло дав.\n\nКуплет 3\nБог є любов. Ми гріху служили, - \nБог є любов, - нам гріхи простив.\n\nКуплет 4\nІсус-Спаситель вмирав за мене,\nМій Відкупитель спасіння дав.\n\nКуплет 5\nТебе я буду величать, славить,\nЯ буду славить Твою любов!', '', '', 'ua', NULL, 0, NULL, NULL),
(551, 32, 'В рідний Край в рідний Край серцем лину я', 0, 'Куплет 1\nВ рідний Край, в рідний Край серцем лину я:\nТам щастя, радість вся моя, - забуду мук одчай.\nЦей світ чужий душі моїй, не рідний він мені;\nЗнайду я серцю лиш спокій в небесній стороні.\n\nКуплет 2\nВ небесах, в небесах, в оселі святій,\nО, скільки любих в тих краях, і там - Спаситель мій.\nУ цьому світі тяжко жить, стомивсь я в боротьбі;\nЯ хочу дні мої прожить з Тобою і в Тобі.\n\nКуплет 3\nСкоро я, скоро я в рідний Край ввійду.\nВстає зоря нового дня, святі часи ідуть.\nЧого ніколи на землі Не бачив я й не знав,\nГосподь спасенним і мені навік приготував.', '', '', 'ua', NULL, 0, NULL, NULL),
(552, 33, 'Вперед сміліше браття спішімо всі вперед', 0, 'Куплет 1\nВперед, сміліше, браття, спішімо всі вперед;\nІдімо без вагання лиш за Христом услід!\nНесімо хрест терпіння, - в серця спокій прийде;\nА хто Христа не прийме, той в Царство не ввійде.\n\nПриспів: \nВ небі жде нас спокій, (2р.)\nВ небі жде нас, (Зр.) спокій!\n\nКуплет 2\nХристос є наш Світильник, -\n Він попереду йде\n І путь нам освітляє, до щастя нас веде.\nХто серцем і душею довіриться Йому,\nТой в радості й спокою жить вічно буде з Ним.\n\nКуплет 3\nБагато дітей Божих вже спочивають там,\nДе сил нема ворожих, - Бог дав спокій серцям.\nМи теж там скоро будем у небі вічно жить...\nНе будем, як в цім світі, ми плакать і тужить.', '', '', 'ua', NULL, 0, NULL, NULL),
(553, 34, 'Співайте хваліте Творця', 0, 'Куплет 1\nСпівайте, хваліте Творця,\nХоч хрест ми несем на землі!\nХристос прийде в славі Отця, - \nО, як же нам буде тоді?\n\nКуплет 2\nОбмились ми в крові Христа,\nТепер же готуймось туди,\nДе в Божій любові життя.\nО, як же нам буде тоді?\n\nКуплет 3\nУ Агнця весілля для нас, - \nРадіючи, йдем ми туди,\nХоч сумно буває не раз...\nО, як же нам буде тоді?\n\nКуплет 4\nВ Божественнім Слові дзюрчить \nСтрумочок живої води, - \nІз нього ми можемо пить...\nО, як же нам буде тоді?\n\nКуплет 5\nХристос нас усіх відкупив, - \nВід нас Він тепер жде плодів;\nВін нам Царство Правди відкрив.\nО, як же нам буде тоді?\n\nКуплет 6\nУ вічному Царстві Христа Не будемо жити в біді:\nМинеться земна марнота.\nО, як же нам буде тоді?', '', '', 'ua', NULL, 0, NULL, NULL),
(554, 35, 'Чи зможе хто на всьому світі', 0, 'Куплет 1\nЧи зможе хто на всьому світі\nСвободу вірним відібрать,\nЩоб волю нашу ув’язнити \nІ дух в кайдани закувать?\nНаш дух закутий був в темряві,\nТа Бог звільнив і волю дав:\nЙому кайданів світ лукавий \nЩе і донині не скував.\n\nКуплет 2\nО, ні, ніхто на всьому світі \nНе візьме правди й честі в нас, \nХоч злобно будуть нас ганьбити \nИ гонить за правду в кожний час. \nПідіймем вгору прапор правди, \nЗлобу любов’ю обснуєм,\nІ честь не в славі цього світу, - \nВ любові вічній ми знайдем.\n\nКуплет 3\nО, ні, ніхто на всьому світі \nБагатства не візьме у нас.\nХай в жертву боротьби святої \nВ нас заберуть в жорстокий час \nІ золото, і все, що маєм, - \nСумління ж ми не віддамо:\nМи тайну щастя всім відкриєм,\nІ нею світ збагатимо.', '', '', 'ua', NULL, 0, NULL, NULL),
(555, 36, 'Коли ти знеможений впадеш в безсилля', 0, 'Куплет 1\nКоли ти знеможений впадеш в безсилля \nОслабнеш в нерівній, тяжкій боротьбі \nІ краплю по краплі із чаші страждання \nПить будеш з докором недолі своїй, - \nДушею не падай, вперед іди знов:\nЄ віра, надія, любов.\n\nКуплет 2\nКоли твоє серце заниє порою,\nІ прийдуть сумні та безрадісні дні,\nДуша не почує ні слова спокою,\nНіхто їй не скаже: \"Іди, відпочинь!\" \nЗгадай, що зігріє і душу, і кров, - \nЦе віра, надія, любов.\n\nКуплет 3\nКоли тебе стріне в житті якась втрата,\nНе плач безутішно, в тугу не впадай; \nЗнай, доля така є від Бога, мій брате:\nПризначення це неземного суда!\nТоді твою душу потішить лиш знов, - \nЦе віра, надія, любов.\n\nКуплет 4\nЗабракне терпіння, ослабнуть всі сили,\nІ буде тонуть у сумнівах душа, - \nОдну бережи в серці ціль до могили,\nБо й в тяжких стражданнях нам любе життя. \nНайбільше нам щастя у тому лежить: \nНадіятись, вірить, любить!', '', '', 'ua', NULL, 0, NULL, NULL),
(556, 37, 'Спасен я О яка то радість', 0, 'Куплет 1\nСпасен я! О, яка то радість,\nСпасенний я Кров’ю Христа;\nСпасен я по милості Божій - \nТепер я вже Боже дитя.\n\nПриспів:\nТак я, так я, спасенний я Кров’ю Христа,\nТак я, так я, тепер я вже Боже дитя!\n\nКуплет 2\nСпасен я! Щасливий в Ісусі,\nЩоб вияснити, - нема слів;\nВін в серці моїм поселився,\nІ любо мені жити з Ним.\n\nКуплет 3\nЯ думаю завжди про Спаса,\nІ безперестанно, ввесь день \nПро Його любов я співаю,\nЩо змістом є моїх пісень.\n\nКуплет 4\nЙого я побачу у славі —\nЦаря, в Кому розкіш моя;\nВін кроки мої направляє,\nНа путь Свій - у вічне життя.\n\nКуплет 5\nУ славі вінець мене жде вже,\nЩо Спас приготовив мені;\nЯк земне життя закінчиться,\nВін його доручить мені.', '', '', 'ua', NULL, 0, NULL, NULL),
(557, 38, 'Буде дощ благословення', 0, 'Куплет 1\nБуде дощ благословення, що нам Господь обіцяв. \nЙ грішники знайдуть спасіння в Христовій святій крові.\n\nПриспів: \nБлагословення нині нам, Боже, зішли. \nТебе ми щиро всі просим:\nДухом Святим нас сповни!\n\nКуплет 2\nБуде дощ благословення: хмари надходять уже! \nДуха Святого хрещення, Боже, пошли нам тепер!\n\nКуплет 3\nБуде дощ благословення... Боже, його нам зішли!\n В Христі новонародження дощ благодатний зішли!\n\nКуплет 4\nБуде дощ благословення... Зішли нам, Боже, тепер; \nВ тобі шукаєм спасіння, почуй нас, просим Тебе!', '', '', 'ua', NULL, 0, NULL, NULL),
(558, 39, 'Слухай Чуєш Спасів голос', 0, 'Куплет 1\nСлухай! Чуєш Спасів голос:\n«Хто з вас стане до діла?\nНиви білі, повний колос, - хто збере Мої жнива?» \nЛюбий голос Спаса кличе й нагороду обіця...\nХто з нас перший радо скаже:\n«Посилай мене, - ось я!»?\n\nКуплет 2\nЯк не можеш ти далеко нести добру новину,\nТо знайдеш усюди, брате, впавшу душу не одну. \nЯк не можеш дати тисяч, - Лепту вдовину хоч дай!\nСпас й те прийме до скарбниці,\nТільки щире серце май.\n\nКуплет 3\nХоч не так ти красномовний,\nЯк апостол був Павло, - Ближнім можеш поміч дати,\nВслід їх вести за Христом.\nКоли люди не зважають на твої любві слова,\nТи збери дітей маленьких і провадь їх до Христа.\n\nКуплет 4\nХай ніхто з нас не говорить:\n«Як я можу помогти?»\nБо навколо люди гинуть, - рятувати їх спіши! \nСлухай радо, що Спас каже,\nЩастя в праці тій знайди.\nЩирим серцем відізвися: «Ось я, Ти мене пошли!»', '', '', 'ua', NULL, 0, NULL, NULL),
(559, 40, 'З любовію Ісус прийшов', 0, 'Куплет 1\nЗ любовію Ісус прийшов, мене загиблого знайшов,\nІз глибини гріха, стида Ісус мене підняв...\n\nПриспів:\nАж з глибини Він спас мене, рукою Він підняв мене \nЗ нічної тьми до світла дня: о, слав Його, душе моя!\n\nКуплет 2\nІсус мене тоді шукав, коли я був ще у гріхах;\nЯк голос я Його почув, - і Він мене здвигнув...\n\nКуплет 3\nЗранений був з терня вінцем - кров потекла Його лицем, \nПрибити дав Він своїх рук,- тим спас мене від мук.\n\nКуплет 4\nЧому Ісус так постраждав, за людський гріх себе віддав? \nНе можу висловити я, - як Він з гріхів звільня...', '', '', 'ua', NULL, 0, NULL, NULL),
(560, 41, 'Де знайде душа у країні якій', 0, 'Куплет 1\nДе знайде душа, у країні якій,\nДля серця свойого і ласку й спокій?\nХто зміг би журливу її утішать,\nБо люди не можуть рятунку їй дать?\nНі-ні, ні-ні, світ нам чужий,\nЛиш в Царстві Христовім є повний спокій.\n\nКуплет 2\nУсім, хто Ісусові серце віддав,\nВін місто на небі святе збудував, - \nІ місто те сяє, як дивний вінець;\nЧи ж рідний то дім для спочинку сердець?\nТак-так, так-так - дім дорогий,\nЙ мені там з святими є вічний спокій.\n\nКуплет 3\nВізьми, мій Спасителю, Ти і мене,\nДе хори святих величають Тебе;\nДуша моя хоче в тім сонмі стоять,\nЗа Кров, за страждання Тебе прославлять. \nЖди, жди, скоро час твій прийде, —\nУ славу небесну тебе Він візьме,\n\nКуплет 4\nНадійся, душе, - недалеко той Край, \nНедовго і скажуть: Іди спочивай! \nБорися, не падай в тяжкій боротьбі: \nТам буде і слава, і спокій тобі. \nРадість, радість там у Отця \nУсім, хто терпить на землі до кінця.', '', '', 'ua', NULL, 0, NULL, NULL),
(561, 42, 'Не хотів би я без плоду перед Господа прийти', 0, 'Куплет 1\nНе хотів би я без плоду перед Господа прийти,\nХоч одну хотів би душу, - сніп один хоч принести.\n\nПриспів:\nНе хотів би я без плоду перед Господа прийти,\nХоч одну хотів би душу, - сніп один хоч принести.\n\nКуплет 2\nСпас життя дав, - добре знаю,- і я смерті не боюсь, \nАле сам себе питаю: 3 чим я перед Ним з\'явлюсь?\n\nКуплет 3\nКоли б міг літа минулі, що намарно я прожив,\nЗ днів далеких повернути, -я б лиш Господу служив.\n\nКуплет 4\nО, працюйте, діти Божі! Подивіться - вже смерка:\nВсі негайно закликайте грішні душі до Христа!', '', '', 'ua', NULL, 0, NULL, NULL),
(562, 43, 'Непослушне я дитя був залишив я отчий дім', 0, 'Куплет 1\nНепослушне я дитя був, залишив я отчий дім.\nНа дорозі злій я гинув, - думу в серці я носив:\n\nПриспів:\nЯ вернусь, я вернусь! Отче любий, я вернусь!\nВсі гріхи Тобі скажу я, знов до Тебе я вернусь!\n\nКуплет 2\nЯ згрішив перед Тобою, признаюся я в сльозах; \nБуду я Тобі слугою, - не дай згинути в гріхах.\n\nКуплет 3\nО, тяжке життя моє є, бо далеко мій Отець!\nВсюди бачу тільки горе, та прийде йому кінець.\n\nКуплет 4\nОтче Ти мій милостивий, руку дай мені Свою! \nУчини мене щасливим, прийми сина, як слугу.', '', '', 'ua', NULL, 0, NULL, NULL),
(563, 44, 'Милість Господня велика', 0, 'Куплет 1\nМилість Господня велика так,\nЩо більша, як всі наші гріхи:\nТам на Голгофі з’явилася, - \nАгнець-Христос кров Свою пролив.\n\nПриспів:\nБожа милість (Божа милість) (2р.),\nВсім нам прощає вона гріхи,\nБожа милість (Божа милість) (2р.),\nБільша є, як наші всі гріхи.\n\nКуплет 2\nГріх і вагання, як море те,\nБушують, щоби душу згубить,\nНад всі гріхи милість більша є, -\n Вона навчає нас свято жить.\n\nКуплет 3\nНаші провини - не скриєм їх,\nЩо ж може змити їх нам з душі?\nГлянь, ось струмок на змиття тече, - \nБілим, як сніг, зробить він тебе.\n\nКуплет 4\nЦя милість дивна й безмежна є,\nПокриє тих, що вірні Йому;\nВсі, що готові любить Його,\nМилість в цю хвилю прийміть святу.', '', '', 'ua', NULL, 0, NULL, NULL),
(564, 45, 'Любить нас Христос безмірно', 0, 'Куплет 1\nЛюбить нас Христос безмірно, - як любить Він! \nЗавжди ласкаво і вірно, - як любить Він!\n(Щастя світу проминає, кращий друг нас забуває, \nСпас же ні, - не покидає! Як любить Він!)	 (2р)\n\nКуплет 2\nНа хресті Ісус в стражданнях... \nЯк любить Він! Грішним дав \nВін оправдання, - як любить Він! \n(Він минуле все прощає, радість дивну посилає, \nХто Йому лиш довіряє, - як любить Він!)	(2р)\n\nКуплет 3\nХто пізнать Його бажає, - як любить Він, \nСпокій, щастя той пізнає, - як любить Він!\n(Він лікує усі болі; хто покірний Його волі, -\n Утішає Своїм Словом, - як любить Він!)	 (2р)', '', '', 'ua', NULL, 0, NULL, NULL),
(565, 46, 'Небо яснеє темніє пітьма ночі настає', 0, 'Куплет 1\nНебо яснеє темніє, пітьма ночі настає!\nМоже скоро вже Спаситель \nДух у вічність твій візьме.\n\nКуплет 2\nІ тоді ти пригадаєш, в Слові Божім, що читав, \nТоді гірко заридаєш,\nЩо Христа ти не прийняв.\n\nКуплет 3\nТа дарма, вже буде пізно: там не можна того взять,\n Що в житті ти цім відкинув...\nДармо будеш лиш благать.\n\nКуплет 3\nКнига Божа вже розкрита, перевірка там іде; \nНе записаний хто в Книзі,\nВ Царство Боже не ввійде.\n\nКуплет 4\nДруже, втомлений гріхами, у неправді не ходи,\nА небесний вчувши голос,\nДо Христа скоріш іди!', '', '', 'ua', NULL, 0, NULL, NULL),
(566, 47, 'Пам’ятай про Бога завжди', 0, 'Куплет 1\nПам’ятай про Бога завжди, друже мій, не забувай: \nЖиттям, словом і ділами Його в світі прославляй.\n\nКуплет 2\nТи собі все помишляєш: \"Молодий, то веселись!\nА коли вже постарієш, тоді кайся і молись\".\n\nКуплет 3\nО, нещасний, ти не знаєш, в яку пору ти умреш!\nМоже завтра вже не встанеш, - жити більше не будеш.\n\nКуплет 4\nМоже завтра побудують гріб сосновий вже тобі,\nІ земля навік покриє твоє тіло в глибині.\n\nКуплет 5\nО душе, душе, загинеш, так, загинеш ти тоді.\nПізно каятися буде, любий друже, вже тобі!\n\nКуплет 6\nТреба всі гріхи лишити, - грішнику, це пам’ятай:\nНе забудь Христа прийняти, - все життя Йому віддай!\n\nКуплет 7\nПам’ятай про це, мій друже, в молодих твоїх літах! \nПрославляй Христа Ісуса, - будеш з Ним у небесах.', '', '', 'ua', NULL, 0, NULL, NULL),
(567, 48, 'По морю буйнім друже мій', 0, 'Куплет 1\nПо морю буйнім, друже мій,\nПливеш ти прямо в Край святий,\nТвій Адмірал велить тобі: | \"Вперед!\" (Зр.)\n\nПриспів: \nВперед, вперед, і скоро буря ця \nУтихне, і перейде тьма,і Вперед (2р.). \nЖивий Бог, - Він велить: \"Вперед, вперед!\"\n\nКуплет 2\nХоч море шумить і реве,\nІ буря вітрила так рве;\nТа пристань недалеко вже, | \"Вперед!\" (Зр.)\n\nКуплет 3\nОсь корабель увесь дрижить,\nІ серце злякано тремтить,\nТа голос Божий все звучить: | \"Вперед!\" (Зр.)\n\nКуплет 4\nХоч буря так сильна й грізна \nІ човен вода залива,\nСтій, друже, на словах Христа: \'\'Вперед!\" (Зр.)', '', '', 'ua', NULL, 0, NULL, NULL),
(568, 49, 'Вбачу я Царя радість це моя', 0, 'Куплет 1\nВбачу я Царя, радість це моя;\nЯк узрю Царя в той день, - \nВ славнім тім раю, там я з Ним буду.\nБуду там завжди я з Ним.\n\nПриспів: \nВ Його славі вбачу я Царя,\nІ цю пісню заспіваю я,\nЩо за мене Він на хресті умер;\nВбачу я Царя в той день.\n\nКуплет 2\nВ славнім тім раю славу вбачу я,\nТам вже ночі не буде!- \n3 моїм Господом вічно буду там,\nВічне світло там буде.\n\nКуплет 3\nВбачу я Царя й принесу все я,\nБіля ніг Його складу!\nЗаспіваю я, як Він спас мене\nИ вдержав мене до часу.', '', '', 'ua', NULL, 0, NULL, NULL),
(569, 50, 'О прокиньсь байдужий грішник', 0, 'Куплет 1\nО, прокиньсь, байдужий грішник, годі, годі тобі спать!\nТи страждаєш, безутішний? - Ісус радість тобі дасть.\n\nПриспів: \nТи, що прагнеш очищення?\nВір! - і радість буде у душі твоїй,\nВстань! Спаситель кличе твій.\n\nКуплет 2\nХто приніс гріхи покірно до Голгофського хреста,\nТой знайшов душі прощення у Спасителя-Христа.\n\nКуплет 3\nО, прийди скоріш до Бога! Ти в гріхах, в неправді жив.\nЗа багатих і убогих кров Свою Христос пролив.', '', '', 'ua', NULL, 0, NULL, NULL),
(570, 51, 'Знаєш друже річеньку ту', 0, 'Куплет 1\nЗнаєш, друже, річеньку ту,\nЩо з Христа струмочком біжить?\nЗнаєш, Хто всім радість дає,\nНавчає прощати й любить?\n\nПриспів: \nХоч мій гріх великий, тяжкий:\nУ гріхах я довго блукав,\nАле став за сніг я біліш,\nЯк любов Христову прийняв.\n\nКуплет 2\nНа хресті в терновім вінку \nНаш Спаситель в муках вмирав:\nНедаремно Кров Він пролив, - \nТо за нас Він тяжко страждав.\n\nКуплет 3\nЯ у світі довго блукав,\nДумав в людях правду знайти;\nЛиш Господь мене пожалів,\nСилу дав до Нього прийти.\n\nКуплет 4\nВ серці довго я не вагавсь, -\n Кликав Він, - я встав і пішов,\nІ велику радість душі \nЯ навіки в Ньому знайшов.\n\nКуплет 5\nВ думах я люблю уявлять \nРічку, що з Голгофи біжить:\nЗ гріхів обмиває вона,\nІ життя та радість дарить.', '', '', 'ua', NULL, 0, NULL, NULL),
(571, 52, 'Радіснії співи линьте в небеса', 0, 'Куплет 1\nРадіснії співи, линьте в небеса!\nБлудний син, одумавшись, прийшов:\nЗ Богом примирився в радісних сльозах,\nВ рідний дім Отця він увійшов.\n\nПриспів: \nСлава, слава Богу в небесах!\nПрославляй уся земля Творця!\nНе вмовкайте співи в праведних устах,\nПрославляйте всі любов Отця!\n\nКуплет 2\nРадіснії співи, линьте в небеса,\nБо знайшлась загублена вівця:\nГрішник, що був мертвий у своїх гріхах,\nВін тепер прийшов вже до Отця.\n\nКуплет 3\nРадіснії співи, линьте в небеса!\nПрославляйте всі любов Христа,\nХай звучить подяка в радісних серцях,\nХай Христа прославлять всі уста.', '', '', 'ua', NULL, 0, NULL, NULL),
(572, 53, 'Голос Духа Святого звучить', 0, 'Куплет 1\nГолос Духа Святого звучить:\nВсіх до Спаса Він кличе: Прийдіть!\nО, друже, вчуй голос святий!\n\nПриспів: \nПрийди (кличе Він), прийди (кличе Він)!\nПрийди скоріш! Христос дасть спокій.\n\nКуплет 2\nРозкіш світу тебе обмане...\nА Спаситель все кличе тебе, - \nЧому ж до Ісуса не йдеш?\n\nКуплет 3\nТо за тебе Син Божий вмирав,\nДар спасіння тобі завіщав.\nВізьми ж дар Ісуса тепер!', '', '', 'ua', NULL, 0, NULL, NULL),
(573, 54, 'Я дізнавсь про любов Христа', 0, 'Куплет 1\nЯ дізнавсь про любов Христа,\nЯк ходив Він колись по землі,\nЯк робив Він великі діла,\nЯк страждав і умер на хресті (хресті). | (2 р.)\n\nПриспів: \nТак, так, за мене, мене,\nТак, так, за мене;\nСпаситель з небес, повний слави, чудес, \nУмирав, щоб спасти вас, мене.\n\nКуплет 2\nЯ дізнавсь, як Ісус страждав,\nЯк томився Він в муках і вмер.\nЗ Книги Божої я дізнавсь,\nЩо Христос умирав за мене (мене). | (2 р.)\n\nКуплет 3\nЯ дізнавсь про Небесний Край,\nДе святі будуть в славі Христа,\nО, чи є там, у тім Краю,\nПриготоване місце мені (мені)? | (2 р.)\n\nКуплет 4\nО, я знаю Господні слова:\n- Життя вічне Я вірним даю. -\n Так, я вірю і люблю Христа!\nЗнаю, дасть мені місце в раю (в раю). | (2 р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(574, 55, 'Ми вибрані Богом на діло святеє', 0, 'Куплет 1\nМи вибрані Богом на діло святеє, - \nСкрізь працю Христову по світі звершать;\nЛюбити безмежно, що тільки живеє,\nНа благо для ближніх себе віддавать.\n\nПриспів: \nМи слуги Христові (ми слуги Христові),\nГосподар Він наш (Господар Він наш),\nДля нас Свою працю Бог дав (працю Бог дав), \nВиконуймо щиро (виконуймо щиро)\nГосподній наказ (Господній наказ),\nНам царство дать Бог обіцяв.\n\nКуплет 2\nМи вибрані Богом - скрізь спокій творити,\nНещасних в недолі, в біді потішать;\nПро Бога та правду всім людям вістити,\nЗ гріха та неволі усіх визволять.\n\nКуплет 3\nМи вибрані Богом, щоб Слово Христове,\nМов добре зерно розсівати кругом;\nНа всякеє добреє діло готові,\nНе скаржитись тяжким життєвим хрестом..', '', '', 'ua', NULL, 0, NULL, NULL),
(575, 56, 'О ласкавий ласкавий Спаситель', 0, 'Куплет 1\nО, ласкавий, ласкавий Спаситель!\nНа хресті Він за мене вмирав;\nВін єдиний є наш Примиритель, - \nВін всім вірним життя вічне дав.\n\nПриспів: \nВін за мене на хресті постраждав (2р.), \nНа хресті постраждав, за мене вмирав, \nВін за мене на хресті постраждав.\n\nКуплет 2\nГрішні Праведника осудили,\nНа Голгофі Його розп’яли,\nЙого одіж собі поділили,\nТак немудрі Творця прийняли.\n\nКуплет 3\nДав життя Своє в жертву Син Божий,\nЩоб від смерті людей врятувать;\nПереміг темні сили ворожі,\nВірним Він дав Свою благодать.', '', '', 'ua', NULL, 0, NULL, NULL),
(576, 57, 'Слава слава Богу в небі', 0, 'Куплет 1\nСлава, слава Богу в небі, - \nНа землі мир - благодать!\nЗакликайте, браття, ближніх:\nБудем Бога прославлять.\n\nПриспів: \nАлілуя! Алілуя! | Слава Богу в небі. (2р.) \nТой, Хто світом володіє,\nМає в небі Свій престол,\nЗалишив небесну славу,\nЯк людина в світ прийшов.\n\nКуплет 2\nО, друззя! Всім вам прощення \nБог сьогодні хоче дать:\nБожий Син звершив спасіння,\nПоспішіть Його прийнять.\n\nКуплет 3\nВ Вифлеємі Спас родився,\nВ бідних яслах Він лежав;\nЗадля нас Христос смирився, -\n То для нас Він приклад дав.\n\nКуплет 3\nО, друззя, прийдіть, не гайтесь,\nДо Ісуса поспішіть.\nУ гріхах своїх покайтесь, - \nВ серце всі Христа прийміть!', '', '', 'ua', NULL, 0, NULL, NULL),
(577, 58, 'Коли горе на серце наляже', 0, 'Куплет 1\nКоли горе на серце наляже, І скажи Ісусу! (2р.)\nКоли душу смуток дуже зв’яже, -\nСкажи Ісусу про все.\n\nПриспів: \nСкажи Ісусу, скажи Ісусу, - Він друг, Який знає все;\nНема брата ліпшого в цім світі,\nЯк наш Спаситель Христос.\n\nКуплет 2\nКоли сльози твій спокій зворушать, - скажи Ісусу! (2р.) \nКоли тайні гріхи душу мучать...\nСкажи Ісусу про все.\n\nКуплет 3\nКоли бачиш, що біда надходить,- | скажи Ісусу! (2р.) \nКоли голод або смерть приходить, - \nСкажи Ісусу про все.\n\nКуплет 4\nКоли в світі загинуть не хочеш,- | скажи Ісусу! (2р.) \nКоли в Царстві Божім бути хочеш, - \nСкажи Ісусу про все.', '', '', 'ua', NULL, 0, NULL, NULL),
(578, 59, 'Нехай хвалять Тебе земля і всі світи', 0, 'Куплет 1\nНехай хвалять Тебе земля і всі світи,\nНехай творіння все повік хвалить Тебе.\nБо Ти великий Бог, Творець землі й небес,\nЗ глибин всього мого чуття хвалю Тебе!\n\nКуплет 2\nПрославлю я Того, Чия любов сильна;\nМене від злого захища Його рука.\nВ нечистоті гріхів, мов у неволі жив.\nТа кровію Христос мене з гріхів обмив.\n\nКуплет 3\nЯ бачу Край новий спокою і добра,\nДе кожен справді вільним є вже від гріха.\nНа тих височинах царює вічно Спас, - \nУ сяєві Отця Свого у небесах.\n\nКуплет 4\nХор ангельський Йому невпинно все співа: \n«Святий, святий, святий єси! Тобі хвала!»\nІз ангелами я Спасителя хвалю;\nТи, Боже, незначну хвалу прийми мою. Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(579, 60, 'Як чудесно змінилося моє життя', 0, 'Куплет 1\nЯк чудесно змінилося моє життя,\nВідколи я Христа пізнав.\nІ я маю спокій, що його я шукав...\nВідколи я Христа пізнав.\n\nПриспів: \nВідколи я Христа пізнав (2р.),\nРіки радості в душу мою все пливуть, \nВідколи я Христа пізнав.\n\nКуплет 2\nЯ лишив мандрівки і блукання мої,\nВідколи я Христа пізнав, - \nІ гріхи мої змиті з моєї душі,\nВідколи я Христа пізнав.\n\nКуплет 3\nЯ надію одержав тверду і певну,\nВідколи я Христа пізнав, - \nІ я більше не маю вагань ні страху,\nВідколи я Христа пізнав.\n\nКуплет 4\nЙду долиною смерті, Спас - світло моє,\nВідколи я Христа пізнав...\nЯ є певний, що Він є зі мною усе,\nВідколи я Христа пізнав.\n\nКуплет 5\nЯ в небесний дім йду, там Господь жде мене, \nВідколи я Христа пізнав, - \nДе побачу Ісуса лицем у лице,\nБо я серцем Його пізнав.', '', '', 'ua', NULL, 0, NULL, NULL),
(580, 61, 'Вірю я в обітниці ХристаЦаря', 0, 'Куплет 1\nВірю я в обітниці Христа-Царя,\nБезупинно хай звучить Йому хвала.\nСлава Богу в небі, вже зійшла Зоря!\nВірю я в обітниці Христа!\n\nПриспів: \nВірю (Зр.), я в обітниці Христа, я вірю, \nВірю, вірю, вірю я в обітниці Христа.\n\nКуплет 3\nВірю я в обітниці, живу з Христом, - \nПокоряюсь всім своїм Йому єством;\nПо правиці хочу бути я з Христом:\nВірю я в обітниці Христа!\n\nКуплет 4\nВірю я в обітниці, в них я кріплюсь;\nБлагодаттю Божою я веселюсь...\nЩо ж буде за радість, як зустрінусь з Ним?!\nВірю я в обітниці Христа!', '', '', 'ua', NULL, 0, NULL, NULL),
(581, 62, 'Ісус Спаситель вмер на Хресті', 0, 'Куплет 1\nІсус Спаситель вмер на Хресті, - \nВмер Він за грішних, щоб їх спасти;\nДушу скропіть ви Кров’ю Христа,\nІ Він пройде, пройде мимо вас!\n\nПриспів: \nЯк Я вбачу кров, (Зр.)\nЯ пройду, Я пройду мимо вас!\n\nКуплет 2\nВ силі Спаситель грішних усіх \nСпасти з найбільших тяжких гріхів;\nВін обіцяв Сам зняти гріх ваш,\nІ Він пройде, пройде мимо вас!\n\nКуплет 3\nСуд Божий прийде скоро всім нам,\nКожний заплату матиме там.\nСкрийся в крові, пролитій за нас,\nІ Він пройде, пройде мимо вас!\n\nКуплет 4\nІсус - Приятель, повний любві, - \nСила чудесна в Його Крові;\nВін спасти може ще нині вас,\nБо Він страждав і умер за нас!', '', '', 'ua', NULL, 0, NULL, NULL),
(582, 63, 'Я лицем в лице з Ісусом стрінусь скоро в небесах', 0, 'Куплет 1\nЯ лицем в лице з Ісусом стрінусь скоро в небесах, \nКоли Він прийде у славі всіх судити по ділах.\n\nПриспів:\nЯ лицем в лице з Ісусом стрінусь скоро в небесах,\nЯк Він явиться у славі всіх судити по ділах.\n\nКуплет 2\nІ тепер я через віру можу бачити Христа, - \nА тоді Його побачу, як Він є - у небесах.\n\nКуплет 3\nВічно утішатись буду - в славі Господа мого,\nБо все горе й зло забуду і не знатиму його.\n\nКуплет 4\nЯ лицем в лице Ісуса стріну скоро Його там,\nДе предвічне «Алілуя» буде в вірних на устах.', '', '', 'ua', NULL, 0, NULL, NULL),
(583, 64, 'Нащо журитися мені', 0, 'Куплет 1\nНащо журитися мені,\nКоли скарби земні \nНалежать до Царя царів,\nА Він - Приятель мій?\n\nПриспів:\nО, так, Приятель мій! \nЗі мною ділиться Він всім. \nВсе є Його, а Він є мій. \nНащо журба мені?\nБо Ісус є Приятель мій!\n\nКуплет 2\nВін сонце, місяць й зорі всі \nДержить в Своїй руці,\nДо Нього скрізь належить все, - \nВін є Приятель мій.\n\nКуплет 3\nДля мене Він є хліб життя, - \nІ при Його столі \nДається їжа людям всім.\nВін є Приятель мій!\n\nКуплет 4\nЯк Він прийде й вбере своїх \nУ ясний білий стрій,- \nЦе все тоді скаже мені,\nЩо Він - Приятель мій!', '', '', 'ua', NULL, 0, NULL, NULL),
(584, 65, 'О скрізь розголосіть вість людям всім скажіть', 0, 'Куплет 1\nО, скрізь розголосіть, вість людям всім скажіть,\nДе тільки є душа не знаюча Христа.\nХай кожний, хто спасен, цю новину несе,\nЩо Дух Святий прийшов.\n\nПриспів: \nО, Дух Святий прийшов! (2р.)\nУтішитель з небес, що обіцяв Отець.\nО, скрізь розголосіть,\nВість людям всім скажіть,\nЩо Дух Святий прийшов!\n\nКуплет 2\nНіч темна вже мина, рання Зоря зійшла,\nТьму розганяє вже, - день вічний настає.\nЛюдство гріхи лиша, - приходить до Христа;\nБо Дух Святий прийшов.\n\nКуплет 3\nОсь, Цар царів прийде, Христос з небес зійде, \nЩоби забрати нас - всіх тих, котрих Він спас. \nНехай труба звучить, щоб голос чути скрізь, \nЩо Дух Святий прийшов.', '', '', 'ua', NULL, 0, NULL, NULL),
(585, 66, 'О слава Богу що Ісус прийшов', 0, 'Куплет 1\nО, слава Богу, що Ісус прийшов,\nІ Він на Себе всі гріхи забрав;\nСлава Спасителю за Його кров,\nСлава! Алілуя! Ісус спас мене!\n\nПриспів: \nІсус спас мене, Ісус спас мене!\nВ моїм серці свідок - Він спас мене!\nВін гріхи простив, Духом охрестив: \nСлава! Алілуя! Ісус спас мене!\n\nКуплет 2\nО, як я довгий час гріху служив,\nВін кров’ю Своєю мене купив; ,\nТепер я буду все Христу служить:\nСлава! Алілуя! Ісус спас мене!\n\nКуплет 3\nЛюбов Його задовольняє всіх,\nІ теж зціляє всіх слабих й калік; \nЩе нині Він до себе кличе всіх: \nСлава! Алілуя! Ісус спас мене', '', '', 'ua', NULL, 0, NULL, NULL),
(586, 67, 'Все віддам я для Ісуса', 0, 'Куплет 1\nВсе віддам я для Ісуса, і все серце Йому дам;\nХочу я Йому служити, як Він Сам служив і нам.\n\nПриспів: \nВсе Тобі даю, все Тобі даю,\nВсе для Тебе, мій Ісусе, нині віддаю!\n\nКуплет 2\nВсе це я зроблю з Ісусом, бо Він силу дасть мені;\nЗ ним я вічно жити буду там - в небесній стороні.\n\nКуплет 3\nЗа для Спаса я здолію в світі хрест тяжкий нести,\nБо на Нього я надіюсь, що Він може помогти.\n\nКуплет 4\nСлава й честь Тобі, Ісусе, за любов Твою святу,\nЩо відкрив для мене ясне світло правди в цім житті.', '', '', 'ua', NULL, 2, '2021-01-31', NULL),
(587, 68, 'Як ваше серце світ в рану оберне', 0, 'Куплет 1\n, - \nСпасові те в молитвах розкажіть:\nВін біль утишить вам, вихід покаже, - \nРан тих немає, щоб Спас не зцілив.\n\nКуплет 2\nСпас - втіха в смутку, світло незрячим,\nНемічним міцність, Спас - сила в борні;\nГолос потіхи все скривдженим: мовить:\n«Спас ваші рани загоїть усі!»\n\nКуплет 3\nГляньте на Хліб Життя, на Живу Воду, - \nДари, що ними спасенний живе;\nЙдіть на обід любві у повній вірі, - \nСпас вам турботи усі розжене!', '', '', 'ua', NULL, 0, NULL, NULL),
(588, 69, 'Я ходжу в світлі куди лиш піду', 0, 'Куплет 1\nЯ ходжу в світлі, куди лиш піду, - \nЧи то по горах, чи долами,\nІсус сказав: «Я тебе не лишу!»\nІ я іду все прямо за Ним.\n\nПриспів: \nСвітло небесне, світло небесне, \nВсю освітило душу мою! Алілуя! \nРадуюсь я все – \nПісні співаю: Слава Христу!\n\nКуплет 2\nТьма скрізь - довкола і наді мною,\nТа тьма не зможе скрити Христа,\nБо Він є світло, в Нім тьми немає,\nІ близько Нього завжди йду я.\n\nКуплет 3\nВ цім яснім світлі радуюсь все я, \nСпіваю Богу пісні хвали;\nІ я прямую просто в Дім Вічний, -\nЯ ходжу в світлі, в світлі любві.', '', '', 'ua', NULL, 0, NULL, NULL),
(589, 70, 'О друже вчуй Нині приємний ще час', 0, 'Куплет 1\nО, друже, вчуй! Нині приємний ще час:\nТвої всі провини простить хоче Спас.\nНе будь же байдужим, - Бог кличе усіх,\nБо може Дух Божий замовкнуть зовсім.\n\nКуплет 2\nХристос закликає усіх до Отця,\nІ Духа зливає в покірні серця.\nВчуй голос Ісуса, до Нього іди, \nУчителя Духа ти не засмути!\n\nКуплет 3\nБез Бога блукав ти і втратив спокій,\nІ попіл присипав вже жертівник твій.\nХрам Бога Живого, о друже, пильнуй \nІ Духа Святого ти ревно шануй!', '', '', 'ua', NULL, 0, NULL, NULL),
(590, 71, 'Гірко плакав Христос на скорботній землі', 0, 'Куплет 1\nГірко плакав Христос на скорботній землі,\nСльози горя текли із очей...\nВін дививсь на цей світ і в нім бачив у злі \nПогибаючих марно людей.\n\nПриспів:\n О, Я плачу за вас, \nЯ ллю Свої сльози і кров;\nЯ приніс вам на землю\nНебесну любов, - Та за неї розпнете Мене!\n\nКуплет 2\nЧерез що, наш Спасителю, Ти у сльозах?\nМоже храми твої не блищать?\nЧи ж не Твій віковічний престол в небесах?\nЧи страждання Тебе тяготять?\n\nКуплет 3\nЯ дивлюся вперед на людей, як братів:\nВсі страждають в гріхах на землі \nНе цінують крові, що за них Я пролив,\nТа забули страждання Мої.\n\nКуплет 4\nЯ молюся за вас! Мною куплені ви,\nО, прийміть же ви жертву Мою!\nЯ даю вам спасіння в пролитій крові,\nЯ віддав за вас душу Свою.', '', '', 'ua', NULL, 0, NULL, NULL),
(591, 72, 'Пригадаймо муки Христову любов', 0, 'Куплет 1\nПригадаймо муки, Христову любов,\nЯк страждав Син Божий, пролив за нас кров...\nОсь у Гефсиманськім темному саду \nЧути шум і гомін: вороги ідуть.\n\nКуплет 2\nЙдуть вони з вогнями, дико гомонять,\nЗ кіллями, мечами, Спаса хочуть взять.\nЯк вже близько стала ворогів юрба,\nТихо і ласкаво їх Христос спитав:\n\nКуплет 3\n«Кого вам тут треба уночі, друззя?\nЯк тільки Ісуса, то це - самий Я!»\nВороги змовчали від тих слів краси,\nЗлякавшись, упали на землю усі.\n\nКуплет 4\nАле зрадник Юда перед Спасом став,\nІ лице Господнє він поцілував.\n«Радуйся, Учитель!» - Юда так сказав,  \nА його Спаситель лагідно спитав:\n\nКуплет 5\n«Чого з ворогами, друже, ти прийшов?\nНащо залишаєш ти Мою любов?...\nВ той час нарід лютий на Христа напав,\nІ святії руки Господу зв’язав...', '', '', 'ua', NULL, 0, NULL, NULL),
(592, 73, 'О як печально й гірко нам як згадуємо ми про день', 0, 'Куплет 1\nО, як печально й гірко нам, як згадуємо ми про день, \nКоли Син Божий Сам | муки за нас прийняв. (Зр.)\n\nКуплет 2\nЯк Агнця тихого взяли, Правди Учителя,\nІ на Голгофі розп’яли | Христа-Спасителя. (Зр.)\n\nКуплет 3\nПішов Спаситель наш Христос прийняти смерть за нас,- \nI муки хресні Він терпів, І і нас від смерті спас,.(Зр.)\n\nКуплет 4\nЗа грішників Безгрішний був розп ’ятий на хресті; \nРозбійника благання вчув, | гріхи йому простив .(Зр.)\n\nКуплет 5\nПроколото Його ребро - стекла вода і кров:\nЗа нас Він тяжко так страждав, | відкрив Свою Любов. (Зр.)\n\nКуплет 6\nДо грішників причислили Спасителя Христа...\nУ гробі був - і в третій день І Христос із мертвих встав. (Зр.)', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(593, 74, 'Ночі пізня вже година всюди тиша і все спить', 0, 'Куплет 1\nНочі пізня вже година, всюди тиша і все спить,\nА Ісус в саду самотній тихо став Отця молить:\n«Отче Мій Святий, - чи може проминути чаша ця?\nТільки хай буде, о Боже, воля лиш у всім Твоя!»\n\nКуплет 2 \nМолить Він Отця, благає так у другий, в третій раз, - \nПіт кривавий виступає на обличчі в скорбний час.\nВ саду молиться Спаситель. Учнів всіх сон подолав.\nВсі дрімають, їх Учитель докоряє, як друзів:\n\nКуплет 3\n«Годі, годі вам дрімати!» - Своїм учням Він сказав: \n«Ось Мене ідуть узяти, час страждання Мій настав.\nІ проллю Я кров невинну за цей грішний світ, за вас»..- \nІ з вогнями в ту хвилину вороги явились враз.\n\nКуплет 4\nЗ ними разом - Юда-зрадник; він Христа поцілував, - \nКого мали вони взяти, цілуванням показав.\nПізня ніч... з саду сторожа із вогнями геть іде, - \nА із нею Він, Син Божий, сповнить волю Отця йде.', '', '', 'ua', NULL, 0, NULL, NULL),
(594, 75, 'Уже північ навкруги все спить', 0, 'Куплет 1\nУже північ... навкруги все спить...\nЧорні хмари по небу пливуть;\nТемний сад Гефсиманський мовчить, - \nНіби молиться Хтось - в тиші чуть.\n\nКуплет 2\nУже північ... Ісус в боротьбі \nЧисті руки в молитві підняв,\nЙого серце в смертельній журбі,\nІ лицем до землі Він припав.\n\nКуплет 3\nУже північ... Христос - без вини – \nПочав Господа тихо благать;\nЧує - час наблизився сумний;\nЙого мучити візьмуть, розпнуть.\n\nКуплет 4\nУже північ... сад прокинувся, - \nТо Ісуса взяти вже прийшли...\nПоцілунок Юди, то зрада.\nБула північ, Ісуса взяли...', '', '', 'ua', NULL, 0, NULL, NULL),
(595, 76, 'Поглянь поглянь Ось повели', 0, 'Куплет 1\n Поглянь, поглянь! Ось повели \nХриста на гору й розп’яли.\nI у тяжких Він муках там \nПридбав усім спасіння нам.\n\nПриспів: \nГолгофський хрест (2р.), - \nІсус за мене там страждав. \nГолгофський хрест (2р.), - \nІсус за мене там вмирав.\n\nКуплет 2\nЗемля стряслась... всіх сум обняв...\n «Звершилося!» - Христос сказав.\nТо Він умер за грішний світ \nІ в рай відкрив спасіння вхід.\n\nКуплет 3\nСпасителю! Ти многих спас \nВ той скорбний час, голгофський час. \nЙ за мене Ти там постраждав, - \nМені життя Ти смертю дав.', '', '', 'ua', NULL, 0, NULL, NULL),
(596, 77, 'Чи читали ви повість про той хрест', 0, 'Куплет 1\nЧи читали ви повість про той хрест,\nДе вмер Ісус за нас,\nДе Він заплатив наш борг кров’ю,\nЩо текла із Його ран?\n\nПриспів:\n Христос прийняв смерть тоді за нас \nХристос прийняв смерть за нас!\nОй, як же Він нас полюбив,\nЩо вмер на хресті за нас!\n\nКуплет 2\nЧи читали ви про вінок з терну \nНа голові Його?\nЯк молився Він: «Отче, їм прости,\nБо не знають, що чинять!»\n\nКуплет 3\nЧи читали, як лиходія спас,\nЩо висів разом з Ним,\nКотрий смутно глянув і сказав Йому:\n«У Царстві спом’яни мене!»\n\nКуплет 4\nЧи читали ви, як зітхнувши,\n Він «Звершилося!» - сказав?\nЧи сказали ви: «Тобі дякую,\nЩо життя за мене дав!»', '', '', 'ua', NULL, 0, NULL, NULL),
(597, 78, 'Прийдіть та погляньте на страшні знущання', 0, 'Куплет 1\nПрийдіть та погляньте на страшні знущання...\nНаш гріх приготовив Ісусу страждання;\nОсь руки і ноги пречисті пробили,\nЗ тернини вінка на чоло положили.\n\nПриспів:\nСлава! Алілуя! Алілуя Господу!\n\nКуплет 2\nВже люди дізнались про муки Христові.\nЧому ж їх не цінять? Не мають любові?\nВідкиньте ж марні всі свої мудрування!\nПрийміть усім серцем Христові страждання!\n\nКуплет 3\nХто прагне душею, шукає спасіння.\nТой в крові Ісуса знайде очищення.\nЗа гріх, хто по правді себе докоряє,\nТому двері Царства Сам Бог відкриває.\n\nКуплет 4\nЗа наші гріхи ми всі мали страждати, - \nХристос постраждав, щоб усіх врятувати. \nВіддаймо Спасителю честь, поклоніння,\nНа землю приніс Він для нас всіх спасіння.', '', '', 'ua', NULL, 0, NULL, NULL),
(598, 79, 'Зійдім на Голгофу друззя', 0, 'Куплет 1\nЗійдім на Голгофу, друззя!\nСпаситель у жертву віддав там життя.\nМесія лиш правди людей научав,\nНедужих зціляв, - за що так постраждав?\nСхилімсь перед Ним!\n\nКуплет 2\nЗійдім на Голгофу, друззя!\nІсус там мучення терпить до кінця.\nВін прагне, а оцет Тому подають,\nІз уст Чиїх води живії течуть.\nСхилімсь перед Ним!\n\nКуплет 3\nЗійдім на Голгофу, друззя!\nСпаситель в любові благає Творця:\n«Прости їм, - не знають, що чинять Мені!» \nХристова молитва знялась від землі...\nСхилімсь перед Ним!\n\nКуплет 4\nЗійдім на Голгофу, друззя!\nПочуєм Ісуса слова до Отця:\n«О, Боже Мій! Нащо Мене залишив?»\nО любі друззя, то за нас \nВін терпів! Схилімсь перед Ним!\n\nКуплет 5\nЗійдім на Голгофу, друззя!\nНевже ж не зворушаться наші серця?.., \n«Звершилось! Я Дух Мій Тобі віддаю!»\nЗа нас Він пожертвував душу Свою.\nСхилімсь перед Ним!\n\nКуплет 6\nЗійдім на Голгофу, друззя!\nТам грішного світу отрута уся \nСтраждання безмірні Христу завдала. \nЛиш Божа любов нас від смерті спасла. \nСхилімсь перед Ним!', '', '', 'ua', NULL, 0, NULL, NULL),
(599, 80, 'Чи тобі все одно що Спаситель страждав', 0, 'Куплет 1\nЧи тобі все одно, що Спаситель страждав?\nВсе одно, все одно, чи тобі все одно?\nТи байдуже стоїш,- Він же кров проливав,\nА тобі все одно, а тобі все одно.\n\nКуплет 2\nЗа тебе на Голгофі Христос умирав,\nА тобі все одно, а тобі все одно.\nВсі провини людей на Себе Він узяв,\nА тобі все одно, а тобі все одно?\n\nКуплет 3\nЗа кого ж Він вмирав? Чи ти думав про те?\nЩоб гріхи Він простив, чи благав ти Його? \nВідкупитель Христос кличе в Царство тебе, - \nО, невжеж в своє серце не приймеш Його?\n\nКуплет 4\nНаближається вічність... подумай про те!\nНа суді, знай, ніхто не заступить тебе. \nСтануть всі перед білим престолом Христа, - \nДе ж тоді ти сховаєш нечисті діла?', '', '', 'ua', NULL, 0, NULL, NULL),
(600, 81, 'Хто з гріхів мене спасе', 0, 'Куплет 1\nХто з гріхів мене спасе?\nО, ніхто, лиш кров Ісуса!\nЩо знов оживить мене?\nО, ніщо, лиш кров Ісуса!\n\nПриспів: \nО, кров Ісусова спасає від гріха!\nНіщо нас не спасе, тільки кров свята Ісуса\n\nКуплет 2\nЗ Богом хто з’єдна мене?\nО, ніхто, лиш кров Ісуса!\nСерцю що спокій дає?\nО, ніщо, лиш кров Ісуса!\n\nКуплет 3\nХто знов підкріпить мене?\nО, ніхто, лиш кров Ісуса!\nЩо знов душу підійме?\nО, ніщо, лиш кров Ісуса!', '', '', 'ua', NULL, 0, NULL, NULL),
(601, 82, 'Друззя Двері райські відкрив Сам Христос', 0, 'Куплет 1\nДруззя! Двері райські відкрив Сам Христос,\nВсіх кличе Він в Царство Своє.\nСпішіте ввійти, ще сьогодні є час!\nХто знає, що завтра нас жде?\n\nПриспів: \nСпіши, друже любий, прийнять \nВелику святу благодать:\nЖиття вічне - Божий дар прийми!\nПрийди до Ісуса, прийди!\n\nКуплет 3\nСпаситель наш скоро, вже скоро прийде,\nДе місце знайдеш ти собі?\nСпасенних Він в Царство Своє всіх візьме, \nЗачиняться двері тоді.\n\nКуплет 4\nПокайся негайно, - гріхи Він простить, \nОбмиє пороки твої,\nІ душу, і тіло твоє оживить.\nНе гайсь, до Ісуса іди!', '', '', 'ua', NULL, 0, NULL, NULL),
(602, 83, 'Путь до спасіння вічний живий', 0, 'Куплет 1\nПуть до спасіння вічний, живий,\nВ слові Своїм Господь нам відкрив;\nВін всі провини наші простив,\nВін кличе всіх: «Прийдіть!»\n\nПриспів: \nРадість, радість буде в небесах, \nРайські співи будуть на устах,\nТам вічне світло в святих серцях - \nВічна любов Христа!\n\nКуплет 2\n«Будьте, як діти!» - Він так сказав,\nВ любові жити заповідав,\nДо покаяння всіх закликав,\nКличе й тепер: «Прийдіть!»\n\nКуплет 3\nДруже! Спаситель кличе й тебе \nВ вічне небесне Царство Своє,\nЙому довірся, - Він тебе жде!\nОсь, кличе Він: «Прийди!»', '', '', 'ua', NULL, 0, NULL, NULL),
(603, 84, 'У сльозах покірно біля ніг Христа', 0, 'Куплет 1\nУ сльозах покірно біля ніг Христа \nСлухала Марія Божії слова,\nСерцем прагнула прийнять \nВід Ісуса благодать...\nЖити з Ним бажаю, служити Йому,\nВ хорі зі святими принести хвалу.\n\nКуплет 2\nМиро найдорожче Марія лила \nЩиро для Ісуса - в жертву віддала. \nЩирий дар Христос прийняв,\nГріх тяжкий Він з неї зняв...\nБіля ніг Христових, як Його слуга, \nХочу утішатись радістю і я.\n\nКуплет 3\nПершою Марія поспішила йти,\nЩоб Ісуса тіло в гробі там знайти,\nІ ось чудо із чудес:\nЗ мертвих вже Христос Воскрес! \nЇй Христос живий тоді явився Сам \nІ сказав: «Іди, скажи Моїм учням».', '', '', 'ua', NULL, 0, NULL, NULL),
(604, 85, 'В долині паслася отара овець', 0, 'Куплет 1\nВ долині паслася отара овець, \nЇх сто всіх було, як одна.\nІ добрий їх Пастир стеріг, як Отець;\nАж ось заблудилась одна;\nВід Пастиря свого далеко зайшла,\nДо Нього вернутись сама не змогла.\n\nКуплет 2\nДев’яносто дев’ять пасуться в гурті, - \nБлукає одна в самоті.\nІ Пастир промовив: «А де ж та одна? \nЛюблю всіх, і люба вона;\nПіду Сам за нею по горах крутих, - \nБажаю її Я привести до них».\n\nКуплет 3\nІ Пастир ласкавий за нею пішов,\nВсі гори й поля обійшов,\nІ бачить: над ровом овечка стоїть,\nІ Пастир до неї спішить.\nКаміння і терен Його не здержав;\nВівцю погибаючу Він врятував.\n\nКуплет 4\nНа плечі спасенну овечку Він взяв,\nЗ любов’ю її пригортав;\nНа пашу зелену її Він пустив, - \nЖиттям її Пастир зрадів.\nРадіють всі ангели... співи звучать... \nЇм любо за неї Творця прославлять.', '', '', 'ua', NULL, 0, NULL, NULL),
(605, 86, 'Свій маяк Господь Всесильний вічним світлом засвітив', 0, 'Куплет 1\nСвій маяк Господь Всесильний вічним світлом засвітив. \nНам же Він вогонь небесний зберігати доручив.\n\nПриспів: \nХай же світло наше сяє,\nПромінь ласки ближнім ллє,\nВ тиху пристань направляє,\nДо спокою всіх веде!\n\nКуплет 2\nМов ті хвилі, гріх бушує, хоче душу затопить; \nПодорожній там бідує, йому треба посвітить.\n\nКуплет 3\nО поправ, мій брате, нині свій сердечний каганець!\nГлянь, на хвилях вітри буйні б’ють човен з кінця в кінець.', '', '', 'ua', NULL, 0, NULL, NULL),
(606, 87, 'Найкраще одне Ім’я нам то Ім’я є Ісус', 0, 'Куплет 1\nНайкраще одне Ім’я нам, то Ім’я є - Ісус!\nЛиш в Нім спасіння всім серцям, Ним тільки я кріплюсь,\n\nКуплет 2\nІсус сердечний гоїть біль і душу веселить.\nДає своїм Він вірним сил тернистий путь звершить.\n\nКуплет 3\nІсус - маяк мій, до Нього по хвилях я пливу,\nВ Нім відпочинок від всього навіки я знайду.\n\nКуплет 4\nІсус - мій Спас, а не суддя, Він добрий Пастир мій;\nВ Нім щастя вічного життя і радість, і спокій.', '', '', 'ua', NULL, 0, NULL, NULL),
(607, 88, 'Хто ці спасенні й відкіля прийшли', 0, 'Куплет 1\nХто ці спасенні, й відкіля прийшли?\nБілі одежі де собі взяли?...\nЛлються співи їх хвали: Агнець їх кров’ю обмив.\n\nПриспів: \nАгнець нас привів у Новий Єрусалим \nЙ кров’ю Своєю обмив, обмив...\nМи жить вічно будем \nВ небесній славі з Ним, —\nАгнець нас кров’ю обмив.\n\nКуплет 2\nХристос Спаситель в Царство їх зібрав,\nЗа них страждав Він, на хресті вмирав,\nБог їх спас і оправдав, Агнець їх кров’ю обмив.\n\nКуплет 2\nВсі, всі слідом за Агнцем вони йшли,\nЧерез великі смутки перейшли,\nУ Христа спокій знайшли, Агнець їх кров’ю обмив.\n\nКуплет 3\nШляхом тернистим їм прийшлось іти,\nХристос поміг його їм перейти,\nВін стеріг їх на путі, Агнець їх кров’ю обмив.\n\nКуплет 4\nЗа Євангельську віру всі вони\n Були постійно з ворогом в борні,\nВірно жили у всі дні, Агнець їх кров\'ю обмив.\n\nКуплет 5\nБог їх простив, навіки полюбив,\nВ Небесний Край для радості привів,\nТам новий лунає спів: Агнець нас кров’ю обмив!', '', '', 'ua', NULL, 0, NULL, NULL),
(608, 89, 'Браття сестри молоді не гайтесь', 0, 'Куплет 1\nБраття, сестри молоді, не гайтесь,\nПоспішіть на Божу ниву жать,\nЯк один, на труд святий віддайтесь:\nСлухайте, вас кличе Сам Господь.\n\nПриспів:\nО, підем же дружно всі на поле,\nЩоб хто снопик, два, хто більш нажать \nІ принести до святого трону,\nЩоб Спасителю Христу віддать.\n\nКуплет 2\nБраття, сестри, дружно всі готуйтесь,\nХай не буде перешкоди вам,\nІ в святій любові всі згуртуйтесь,\nІ Спаситель поведе вас Сам!\n\nКуплет 3\nПодивіться - нива побіліла.\nГоді вам на торжищі стоять!\nТам потрібні ви і ваша сила,\nДе вас хоче Сам Господь найнять.\n\nКуплет 4\nМоже вже останній поклик чуєш:\nЗавтра вже Господь не прийме нас,\nО, тоді навіки засумуєш, - \nЯк почуєш: «Я не знаю вас!»', '', '', 'ua', NULL, 0, NULL, NULL),
(609, 90, 'О де ж ті женці щоб зібрать снопи', 0, 'Куплет 1\nО, де ж ті женці, щоб зібрать снопи \nЗ ланів світа й Господу принести?\nЗ серпами любові до праці йдіть,\nНевпинно працюйте, лани зіжніть!\n\nПриспів: \nО, де ж ті женці? Хто з нами враз\nПоділить ту працю, що вже жде на нас? \nХто нам поміч дасть зібрати з піль \nДобра снопи, вибрати кукіль?\n\nКуплет 2\nШукайте колосся, що десь в траві;\nКукіль із пшениці ви виберіть; \nЗберіть ті колосся, що при путі,\nНічого не киньте, усе зберіть!\n\nКуплет 3\nЛани вже дозріли, й зерно в них є,\nІ жнив тих великих вже світ наш жде. \nРобітників мало, а праці скрізь...\nНе гаймось, до праці усі берімсь!\n\nКуплет 4\nБеріть же ви, браття, свої серпи, - \nНесіть ті багаті зерном снопи...\nГотуйтесь зустріти Христа-Царя:\nВін дасть нагороду нам за жнива.', '', '', 'ua', NULL, 0, NULL, NULL),
(610, 91, 'Хрест тяжкий терпіння', 0, 'Куплет 1\nХрест тяжкий терпіння (2р.) на Голгофу Він \nНіс покірно й сміло (2р.) - вічний Божий Син.\n\nКуплет 2\nІ Його є воля (2р.), щоб в житті земнім \nЯ ішов покірно (2р.) із хрестом своїм.\n\nКуплет 3\nЙшов смиренно й тихо (2р.) на Голгофу Він.\nПадав у знемозі (2р.) під хрестом тяжким.\n\nКуплет 4\nІ мій хрест суворий (2р.) Сам Він облегшив:\nІз кайдан гріховних (2р.) мене увільнив.\n\nКуплет 5\nЯрмо Його любе (2р.) у моїм житті.\nРадість і відвагу (2р.) маю у Христі.\n\nКуплет 6\nТягар Його знаю (2р.) - він легкий мені,\nНа Нього взираю: (2р.) моя сила в Нім.', '', '', 'ua', NULL, 0, NULL, NULL),
(611, 92, 'Коли б до скали що є вища ніж я', 0, 'Куплет 1\nКоли б до скали, що є вища, ніж я,\nЯ духом із битви піднятися міг!\nСлаба в мене віра і немічний я...\nСкала та - Христос, щит і захист Він мій.\n\nПриспів: \nСкриюсь в Тобі, скриюсь в Тобі,\nСкала - мій Ісус, я укриюсь в Тобі!\n\nКуплет 2\nВ південній тиші, і в годинах тяжких,\nІ в пору спокус, як душа в боротьбі,\nІ в грізну теж бурю на хвилях морських,- \nСкала - мій Ісус, я укриюсь в Тобі.\n\nКуплет 3\nЯк змучений часто в нерівній борні,\nБіжу до скали - щоб знайти захист в ній... \nВона, віковічна, ясніє в тиші:\nСкала та - Христос: в Нім спокій для душі.', '', '', 'ua', NULL, 0, NULL, NULL),
(612, 93, 'Коли погляну в вірі я', 0, 'Куплет 1\n Коли погляну в вірі я\nНа хрест, де Божий Син страждав,\n(Тремтить тоді душа моя,\nСоромлюсь, що Його не знав.)(2р)\n\nКуплет 2\nО, Спасе, хорони мене,\nЩоб в світі слави не шукав,\n(Щоб Твої муки, смерть Твоя \nБули вінцем моїх похвал.)(2р)\n\nКуплет 3\nВ любві гарячій, Спасе мій,\nЗа нас пролив свою Ти кров.\n(Терпів зневагу від людей:\nВелика є Твоя любов.)(2р)\n\nКуплет 4\nКоли б я все Тобі віддав, \nЖертва моя була б мала.\n(Що ж за любов Твою я дам? \nО, Спасе мій, я весь Твій сам!)(2р)', '', '', 'ua', NULL, 0, NULL, NULL),
(613, 94, 'Плачте очі лийтесь сльози умирає на хресті', 0, 'Куплет 1\nПлачте очі, лийтесь, сльози, - умирає на хресті \nСам Ісус Христос, Син Божий; ллється кров із ран святих!\nЩо зробив кому Ти злого? Чому мусиш так страждать? \nЗа розбійника якого забажав відповідать?\n\nПриспів: \nПлачте очі, лийтесь, сльози,\nУмирає на хресті\nСам Ісус Христос, Син Божий;\nЛлється кров із ран святих.\n\nКуплет 2\nУ вінку терновім чоло, чистий погляд - в небеса.\nЖурно робиться навколо, ніч удень, - холодний жах.\nЦе за мене всі страждання, за гріхи мого життя...\nО, Ісусе! Вчуй благання: хочу мать прощення я.\n\nКуплет 3\nЯ іду, хоч і безсилий, силу Духа дай мені!\nХочу завжди, до могили бачить образ в муках Твій. \nХочу мать одне бажання - Твій тримати заповіт,\nІ в душі святим стремлінням всі до Тебе дні горіть.', '', '', 'ua', NULL, 0, NULL, NULL),
(614, 95, 'Я вірю прийде Судний день', 0, 'Куплет 1\nЯ вірю - прийде Судний день,\nТоді зблідніють з жаху люди;\nЗамовкне хор гучних пісень, -\nІ скрізь скорботно й страшно буде.\n\nКуплет 2\nТемрява чорна землю вкриє,\nПогасне сонце, згаснуть зорі.\nЗаграють сумно води моря,\nІ вітер в темряві завиє.\n\nКуплет 3\nВеликий жах на світ повіє,\nЗатрублять ангели у труби,\nЗ могил устануть усі люди,\nВсе змовкне раптом, заніміє.\n\nКуплет 4\nЯ вірю - прийде Судний День,\nІ гірко плакатимуть люди;\nЗамовкне хор гучних пісень,\nСкорботно всюди й страшно буде.', '', '', 'ua', NULL, 0, NULL, NULL),
(615, 96, 'Відкритий мені був Суд Божий', 0, 'Куплет 1\nВідкритий мені був Суд Божий:\nТруби звук під небом гримів;\nБіля трону зібрались народи,\nИ рішалась навік доля їх.\nІ з неба зійшов світлий ангел.\nВін став на землі й на воді,\nИ посвідчився Богом небесним,\nЩо час вже пройшов для людей.\n\nПриспів: \nОдчай, крик, благання і стогін \nПовстав на тім страшнім суді:\nВ мольбі многі крились у гори,\nТа вже було пізно тоді.\n\nКуплет 2\nБули там багаті, що в світі \nСумління своє продали, - \nСтояли вони бідні, грішні,\nДіла бо їх з ними прийшли.\nТакож там вельможні стояли,\nЩо славились тут на землі,\nТа ангели в книзі небесній \nВеличності їх не знайшли.\n\nКуплет 3\nТам сироти стали, вдовиці, - \nГосподь всі їх сльози згадав;\nЗневажених світом, убогих \nСпаситель ласкаво прийняв.\nА «праведність» всіх лицемірів,\nВсю гордість, що нею світ жив,\nЯк рештки старої одежі \nСуддя вогнем правди спалив.', '', '', 'ua', NULL, 0, NULL, NULL),
(616, 97, 'Пильнуй у всякий час брате всі дні пильнуй', 0, 'Куплет 1\nПильнуй у всякий час, брате, всі дні пильнуй:\nХай вчують голос твій, - всім говори: \n«Пильнуй!» Пильнуй, як Бог велить, - служи Йому всі дні; \nПильнуй, - ось Він спішить дати спокій тобі.\n\nПриспів: \nПильнуй — молись, пильнуй - молись, \nПильнуй вночі, та будь готовий і вдень, \nВсякий час пильнуй!\n\nКуплет 2\nПрокиньсь від сну і стій, брате, на варті стій! \nТримай Завіт святий, даний Христом самим.\nБрате, пильнуй, молись, бо Сам Спаситель твій \nЗа тебе кров пролив і умер на хресті.\n\nКуплет 3\nВ час битви із гріхом на Господа вповай; \nВіддайсь Йому цілком - Він перемогу дасть. \nКоли зоря зійде, — прокинься, не дрімай!\nА як Господь прийде, то нас введе в Свій рай.', '', '', 'ua', NULL, 0, NULL, NULL),
(617, 98, 'Іду вгору на небеса і все щораз то вище я', 0, 'Куплет 1\nІду вгору на небеса, і все щораз, то вище я;\nТакож я Господа молю:\n«Провадь мене у вись святу!»\n\nПриспів: \nМене, мій Боже, піддержи,\nЩоб міг встояти в боротьбі,\nБо я пізнав - Твоя любов Людей спасає знов і знов.\n\nКуплет 2\nНе хочу жити так, як жив,\nХоч ворог стріли нагострив;\nЯ чую райськії пісні, пісні святих, в святій землі.\n\nКуплет 3\nЯ хочу в самий верх зійти, але не маю сили йти, \nТебе, о Боже, я молю:\n«Провадь мене у вись святу!»', '', '', 'ua', NULL, 0, NULL, NULL),
(618, 99, 'Я сиджу в ногах Ісуса слухаю Його слова', 0, 'Куплет 1\nЯ сиджу в ногах Ісуса - слухаю Його слова:\nО, як любо, як солодко научатись від Христа.\n\nКуплет 2\nЯ сиджу в ногах Ісуса - на минуле дивлюсь я...\n Милість Його так велика, що збагнуть не можу я.\n\nКуплет 2\nЯ сиджу в ногах Ісуса, Він мене благословля.\nВін гріхи простив мої всі і спокоєм наповня.\n\nКуплет 2\nЯ сиджу в ногах Ісуса: люблю теж молитись я,\nІ пісні хвали співати, в славу для Спасителя.\n\nКуплет 2\nО, благослови, мій Спасе, біля ніг Твоїх мене,\nГлянь на мене із любов’ю і яви Своє лице.\n\nКуплет 2\nОтче! Дай Духа Святого, а також любов Христа,\nЩоб я міг тут свято жити, серцем линуть в небеса.', '', '', 'ua', NULL, 0, NULL, NULL),
(619, 100, 'О як радісно в дружбі з Господом Йти', 0, 'Куплет 1\nО, як радісно в дружбі з Господом Йти, \nОпершись на Його рам’я;\nЯк солодка та дружба з Господом,\nПрославляю я Його Ім’я.\n\nПриспів: \nЛюбо йти з Ним (Любо іти з Ним (2р.))\n Опершись на Його рам’я;\nЛюбо й мило (Любо і мило (2р.)) \nСлавити Його святе Ім’я!\n\nКуплет 2\nО, як радісно йти в дорозі з Ним...\nВсе покласти на Його рам’я;\nО, як добре з Ним жити в кожнім дні,\nЗавжди славити Його Ім’я.\n\nКуплет 2\nО, нічого я тепер не боюсь,\nБо підтримку маю від Христа.\nІ спокійно я Господу молюсь, - \nПрославляю я Його Ім’я.', '', '', 'ua', NULL, 0, NULL, NULL),
(620, 101, 'Ми ідемо в Ханаан мандруєм в путі', 0, 'Куплет 1\nМи ідемо в Ханаан, мандруєм в путі...\nСмілий хто через Йордан вірою іти?\n\nПриспів: \nБудь, як був Ісус Навин. «Я піду!» - скажи,\n «Я і дім мій - ми будем Господу служить!»\n\nКуплет 2\nБезліч горя бачим ми на нашім путі;\nПроти сили зла і тьми вірою ідім.\n\nКуплет 3\nЯк Червоне море нам ляже впереді,\nПам’ятаймо ці слова: «Вірою іди!»\n\nКуплет 4\nДля всіх вірних Ісус Сам є Проводирем, - \nМи в небесний Ханаан вслід за Ним ідем.', '', '', 'ua', NULL, 0, NULL, NULL),
(621, 102, 'Я не залишу вас самих коли від вас піду', 0, 'Куплет 1\nЯ не залишу вас самих, коли від вас піду, - \nСвятого Утішителя, Небесного Учителя \nЯ вам навік зішлю.\n\nПриспів: \nПрийняв ти Його? Прийняв ти Його? \nУтішителя прийняв чи ні?\nГосподь докорить світ за гріхи,\nКоли прийде до нас Дух Святий.\n\nКуплет 2\nО, Церкво Божа, час вставать, всю повноту прийнять!\nЩоб грішники по всіх місцях\nПокаялись в своїх гріхах, - прийняли благодать.\n\nКуплет 3\nДари духовні в небесах у Бога є для нас.\nВперед, молімся з вірою, - Господь наділить силою \nВ борні у кожний час.\n\nКуплет 4\nМи до П’ятидесятниці скоріш, скоріш спішім:\nСвятим життям усі живім\nХрещення Духом ми Святим у Бога всі просім!', '', '', 'ua', NULL, 0, NULL, NULL),
(622, 103, 'Там на хресті де Христос страждав', 0, 'Куплет 1\nТам, на хресті, де Христос страждав,\nТам всі провини мої Він зняв,\nТам Він спасіння для нас звершив. О, хвала Йому!\n\nПриспів: \nО, хвала Йому! (2р.)\nТам всі провини мої Він зняв.\nО, хвала Йому!\n\nКуплет 2\nКров’ю Спас душу мою обмив.\nІ Словом правди Він відродив,\nДухом Святим Він мене хрестив. О, хвала Йому!\n\nКуплет 3\nЛюбі друззя, ще приємний час:\nБог нині хоче спасти всіх вас,\nТож поспішіть до Христа в цей час! О, хвала Йому!', '', '', 'ua', NULL, 0, NULL, NULL),
(623, 104, 'О Слово Боже вірне В нім наше все життя', 0, 'Куплет 1\nО, Слово Боже вірне! В нім наше все життя.\nБагатство в нім нетлінне - наука це Христа.\nХристос в любві втішає і душу оживля,\nЗ сумніву визволяють Його святі слова:\n\nПриспів:\n Прийди до Христа: в Нім твоє життя;\nДруже безутішний, не вагайсь, іди! (2р.)\n\nКуплет 2\nО, серце, не вагайся, Спасителю повір,\nНавік Йому віддайся, проси у Нього сил.\nНещасний, хто блукає далеко від Христа,\nЩасливий, хто приймає Божественні слова.\n\nКуплет 3\nО, Боже, будь Ти з нами і вдень, і уночі,\nЩоб світлими путями до Тебе йшли мерщій; \nМогутньою рукою веди нас всіх вперед \nДорогою вузькою все за Собою вслід!', '', '', 'ua', NULL, 0, NULL, NULL),
(624, 105, 'Ніч яка темна настала', 0, 'Куплет 1\nНіч яка темна настала...\nЧорно і холодно скрізь...\nХтось там самотній ридає,\nХтось обезсилів від сліз. 	(2р)\n\nКуплет 2\nНащо ж ви знов задрімали?\nВстаньте, прокиньтесь, не спіть!\nНіч яка темна настала...\nГрішних спасайте,- будіть! 	 (2р)\n\nКуплет 3\nСили темрява збирає...\nІ чорні сни свої снить:\nГоспода люди не знають \nИ не хочуть Йому служить. 	 (2р)\n\nКуплет 4\nНащо ж ви знов задрімали,\nЧому не йдете спасать?\nБачите темно як стало:\nВсюди байдужість, всі сплять.  (2р)\n\nКуплет 5\nПравди на світі так мало,\nМіж людьми гасне любов:\nСумом нас й жахом обняло \nЙ бачу я горе і кров.  	(2р)', '', '', 'ua', NULL, 0, NULL, NULL),
(625, 106, 'Дрімає Гефсиманський сад', 0, 'Куплет 1\nДрімає Гефсиманський сад. Друзі Ісуса мирно сплять.\nА там пооддаль Сам один Отця благає Божий Син.\n\nКуплет 2\nВін приклонивсь, лице схилив і гаряче Отця молив,\nІ голос скорбної душі почувся в дрімотній тиші:\n\nКуплет 3\n- Хай чаша мук пройде оця, та воля не Моя - \nТвоя Хай буде, Отче. Я іду! - все було тихо у саду.\n\nКуплет 4\nІ капав піт з лиця Його, як краплі крові, - вкрив чоло.\nІ ангел Божий тут стояв, Христа в молитві підкріпляв.', '', '', 'ua', NULL, 0, NULL, NULL),
(626, 107, 'В день коли труба Господня', 0, 'Куплет 1\nВ день, коли труба Господня,\nВсіх святих згромадить там\nНад прозорою рікою, як кришталь (як кришталь).\nНа весільну там вечерю забере Ісус нас Сам:\nО, яка ж то зустріч дивна буде там!\n\nПриспів: \nО, яка ж то зустріч!\n(О, яка ж то зустріч буде, де зберуться святі люди).\nІ збавлення звістить трубний Голос нам (голос нам).\nО, яка ж то зустріч!\n(Там зустрінем наших близьких серед райських радощів там).\nО, яка ж то зустріч дивна буде там!\n\nКуплет 2\nІ звістить всім ангел Божий,\nЩо нема вже більш часу!\nМи будем підхоплені у небеса (в небеса);\nТам усіх Ісус-Спаситель вдягне в славу нас Свою...\nО, яка ж то зустріч дивна буде там!\n\nКуплет 3\nТе, що тайне і закрите, в той день виявиться все,- \nЯк Господь буде судити всіх людей (всіх людей). \n«Увійдіть, - Він скаже правим - В радість Пана свойого!»\nО, яка ж то радість дивна буде там!\n\nКуплет 4\nТам при звуках гуслів стройних,\nАрф небесних золотих, -\nГімн спасіння й перемоги викликнем (викликнем): \nПісню Агнця і Мойсея заспіваєм всі разом ...\nО, яка ж то радість дивна буде там!', '', '', 'ua', NULL, 0, NULL, NULL),
(627, 108, 'Душа Утішайся Ісусом', 0, 'Куплет 1\nДуша! Утішайся Ісусом:\nГріхи Він обмив всі твої,\nЛюбов’ю тебе окриляє,\nДобро посилає тобі.\n\nПриспів:\nЩасливий я вічно з Ісусом!\nСпочинок в Христі я знайшов: \nМені дав спокій Він і радість, \nКоли я до Нього прийшов.\n\nКуплет 2\nЩасливий я всюди з Ісусом!\nВін Духом мене оживив,\nЯк щедрий Отець у любові,\nНебеснеє Царство відкрив.\n\nПриспів:\nЩасливий я всюди з Ісусом!\n Тягар свій зложив у Христа: \nСпокій я знайшов і блаженство\n В любові Ісуса Христа.\n\nКуплет 3\nЩасливий я всюди з Ісусом!\nХоч шлях мій тернистий, вузький,\nМене до мети доведе Він,\nДе вічний знайду я спокій.\n\nПриспів \n-Щасливий я всюди з Ісусом!\nЗавжди бути в спільності з Ним; \nУ серці Його відчувати\n І тішитись Ним лиш одним.', '', '', 'ua', NULL, 0, NULL, NULL),
(628, 109, 'Обізвись мій милий Боже', 0, 'Куплет 1\nОбізвись, мій милий Боже, Боже - Правдо Ти моя! \nОбізвись в тяжку годину, як подам свій голос я.\n\nКуплет 2\nМені тісно було, Боже, а Ти дав мені простір,\nІ тепер мене помилуй та пошли душі Твій мир!\n\nКуплет 3\nМайте страх ви перед Богом, усі люди на землі, \nПомишляйте в ваших серцях про діла Його святі!\n\nКуплет 4\nЗасіяй над нами, Боже, світлом Твойого лиця,\nТим святим, небесним світлом, що сіяє без кінця!', '', '', 'ua', NULL, 0, NULL, NULL),
(629, 110, 'Ось прийшов молитви час Господу принесім', 0, 'Куплет 1\nОсь прийшов молитви час, Господу принесім,\nВесь тягар, що мучить нас, і знайдем радість в Нім. \nСам Господь нам дав це знать, що нас хоче прийнять \nІ святі благословення на життя посилать.\n\nПриспів: \nО, молитви час! О, молитви час!\nЗ Господом в святім єднанні В серці радість і мир.	2р.\n\nКуплет 2\nОсь прийшов молитви час, ми благаєм Тебе:\nБоже, Дух пролий на нас та відкрий нам Себе!\nПісня слави ллється хай, душі нам зогрівай,\nІ любов, і мир рікою у серця проливай.\n\nКуплет 3\nОсь, прийшов молитви час, - всі зібралися ми;\nО, прийди, Господь, до нас, всіх в одно з’єдини.\nМир подай усім серцям, мир пролий з неба нам,\nВсі почуй наші моління, Боже, будь з нами Сам!', '', '', 'ua', NULL, 0, NULL, NULL),
(630, 111, 'До Тебе Боже мій ближче я йду', 0, 'Куплет 1\nДо Тебе, Боже мій, ближче я йду;\nХоч би і на хресті розп’ятий був,\nСпівав би я й тоді: «До Тебе, Боже мій,\nДо Тебе, Боже мій, ближче я йду!»\n\nКуплет 2\nХоч би, мов мандрівник, сонце зайшло,\nНа скелі в тьмі моє ложе було,\nСпівав би я і в сні: «До Тебе, Боже мій,\nДо Тебе, Боже мій, ближче я йду!»\n\nКуплет 3\nХай вбачу сходи в сні, що в небо йдуть;\nДані дари мені від Тебе суть.\nХай ангели Твої путь вказують мені, - \n«До Тебе, Боже мій, ближче я йду!»\n\nКуплет 4\nПрокинусь, і в думках моїх, як дар,\nПоставлю, Боже мій, Тобі вівтар.\nСпіватиму й в журбі: «До Тебе, Боже мій,\nДо Тебе, Боже мій, ближче я йду!»\n\nКуплет 5\nКоли б у небо я навіть злітав, - \nСонце, місяць, зірки я б проминав...\nСпівав би я й тоді: «До Тебе, Боже мій,\nДо Тебе, Боже мій, ближче я йду!»', '', '', 'ua', NULL, 0, NULL, NULL),
(631, 112, 'Ми всі уповаємо на Скалу', 0, 'Куплет 1\nМи всі уповаємо на Скалу, - \nСкала та - Христос Спаситель:\nІ в бурю страшну, і в час негод знайдемо захист в ній.\n\nПриспів: \nХристос - та Скала,\n(Ми всі уповаєм на ту Скалу)\nХристос - та Скала,\n(Ми всі уповаєм на ту Скалу)\nМи всі уповаєм на ту Скалу,\nСпаситель наш - Скала.\n\nКуплет 2\nСвої всі надії на піску поклали тут всі байдужі: \nБагатство і слава, в світі честь - \nЛише в цім їх бажання.\n\nКуплет 3\nПрийдіть і будуйтесь на Скані, усі проженіть сумніви, \nА хто прагне правди, хай прийде:\nТут всі знайдуть спасіння.', '', '', 'ua', NULL, 0, NULL, NULL),
(632, 113, 'Пливе світами пісня любові', 0, 'Куплет 1\nПливе світами пісня любові...\nСпів той хай громом могутнім гуде!\n(Для нас спливає щастя чудове:\nСам Господь Христос у славі іде. )	(2р)\n\nКуплет 2\nВ маній хатині, в мирній оселі \nГостить безмежне там щастя - любов.\n(Сам Христос Господь, що на Голгофі \nЗа гріхи світу віддав в жертву кров.)	(2р)\n\nКуплет 3\nО, пресвятая Тайна любові!\nПеред Тобою і мудрість є німа.\n(В кожний час спомину тіла і крові \nХай за нас молить теж віра тверда.)	(2р)\n\nКуплет 4\nХай за нас молить і серце чисте;\nКаяння сльози у наших очах. \n(Вітай між нами, Спасе наш, Христе,- \nВсесильний Боже, в чудових ділах!)	(2р)', '', '', 'ua', NULL, 0, NULL, NULL),
(633, 114, 'Чи знаєш битву Ісуса', 0, 'Куплет 1\nЧи знаєш битву Ісуса, - муки страшні від хреста? \nВесь я сльозами заллюся, смерть як згадаю Христа. \nО, як над Ним там знущались, як розпинали Його! \n(Цвяхи, мов змії, в’їдались\nВ руки і ноги Його.) (2р)\n\nКуплет 2\nЗ ран кров стікала струмочком, Син Божий там умирав, \nА непроглядна мла-морок землю тоді покривав... \nТам дух злоби притаївся - змій беззаконня - гріхів...\n(О, як в страждальця він в’ївся! \nТемні хрести три обвив.) (2р)\n\nКуплет 3\nВесь я сльозами заллюся, як пригадаю той час,\n Коли Спаситель у муках прагнув спасти усіх нас. \nЯк умирав Він, молився за розпинателів злих,\n(Як до кінця полюбив нас!\nВзяв на Себе весь наш гріх.) (2р)\n\nКуплет 4\nГлянь на Зорю Воскресіння! Вчуй спів чудовий хвали.\n Бачиш, - виходить нетлінний Цар і Спаситель землі. \nДишучи злістю німою, змій той побитий лежить,- \n(Пастир до стада явився,\nЩоби овець хоронить.) (2р)', '', '', 'ua', NULL, 0, NULL, NULL),
(634, 115, 'Бажаю все Тебе о Боже мій', 0, 'Куплет 1\nБажаю все Тебе, о Боже мій!\nЛаскавий голос Твій дає спокій.\n\nПриспів: \nТи захист мій, надія в кожний час, о Боже, \nБлагослови, мій Спасе - до Тебе йду!\n\nКуплет 2\nБажаю все Тебе: зі мною будь!\nЗ Тобою у пітьмі ясніє путь.\n\nКуплет 3 \nБажаю я усе, Боже, Тебе;\nБез Тебе є марне життя моє.\n\nКуплет 4\nБажаю все Тебе, - сил мені дай,\nЯк жити на землі, мене навчай.', '', '', 'ua', NULL, 0, NULL, NULL),
(635, 116, 'Хваліте Господа співайте', 0, 'Куплет 1\nХваліте Господа, співайте,\nЯк радісно складать хвалу!\nЙого Єдиного прославте,\nВіддайте серце все Йому!\n\nПриспів:\nХваліте Господа (хваліте всі),\nСпівайте (співайте всі), -\nЯк радісно складать хвалу, (хваліте всі), —\nЙого Єдиного прославте (Його Єдиного прославте (2р.)),\n Віддайте серце все Йому (серце все Йому)!\n\nКуплет 2\nУсім світилам, сонцю, зорям \nШляхи у небі призначив \nВеликий Бог,- світів простори\nПремудро-дивно сотворив.\n\nКуплет 3\nІ хмари в небі чередою \nПо слову Господа пливуть,\nВін скроплює квітки росою,\nСади в красі Творця цвітуть.\n\nКуплет 4\nЗвірям, пташкам дає Бог їжу,\nІстотам всім Він дав життя,\nВін людям всім дає одежу,\nІ постанови дав царям.\n\nКуплет 5\nЛаскаво тихих Бог приймає \nІ захист праведним дає;\nУ гордих силу відіймає,- \nІ мудрості в них не стає.\n\nКуплет 6\nНачніте ж Бога, ви начніте,\nВсі людські пізнавать уми,\nДля слави ви Його спішіте \nСкладати співи і псальми.', '', '', 'ua', NULL, 0, NULL, NULL),
(636, 117, 'Він у двері стукає з любовію', 0, 'Куплет 1\nВін у двері стукає з любовію.\nО, впусти (впусти Його), впусти Його (впусти Його).\nХоче Він спасти з гріха твою душу,	\nО, впусти (впусти Його), впусти Його (впусти Його)!\n\nПриспів: \nСтук, стук! Стук, стук! Двері відчини,\nДнесь Христа впусти (Христа впусти).\nВ серце ти своє (в серце своє).\nСтук, стук! Стук, стук! Він подасть спокій,\nЯк приймеш Його в дім свій (у дім свій).\n\nКуплет 2\nТебе кличе лагідно, з любовію.\nО, впусти (впусти Його), впусти Його (впусти Його)!\nГлянь! Який Він милосердний до тебе,\nО, впусти (впусти Його), впусти Його (впусти Його)!\n\nКуплет 3\nВін чекає на тебе з любовію,\nО, впусти (впусти Його), впусти Його (впусти Його).\n Ти прийми Його днесь радо до себе,\nО, впусти (впусти Його), впусти Його (впусти Його)!', '', '', 'ua', NULL, 0, NULL, NULL),
(637, 118, 'Коли складаєш ти хваління і веселишся', 0, 'Куплет 1\nКоли складаєш ти хваління і веселишся, брат,\nРадієш, що знайшов спасіння,\nДуші нетлінний скарб, -\nПоглянь лиш на життєве море, і в нім побачиш ти \nПотоки сліз, людей у горі, що тонуть в марноті.\n\nКуплет 2\nБез світла віри у темряві плавці кудись пливуть, \nІ Сонце Правди, їм незнане, не освітляє путь. \nХто ж з нас відкликнеться на горе -\nТих моряків спасать?...\nїм руку помочі на морі, о, поспішіть подать!', '', '', 'ua', NULL, 0, NULL, NULL),
(638, 119, 'Як праця скінчиться тут вже моя', 0, 'Куплет 1\nЯк праця скінчиться тут вже моя,\nІ в Край Небесний перейду вже я:\nГосподню славу побачу там я, - \nЗ того буде вічна радість моя...\n\nПриспів: \nО, то буде радість моя, (2р.)\nКоли обличчя побачу Христа!\nТо буде радість, то радість моя!\n\nКуплет 2\nСпас приготовив там місце мені \nВ домі Отця, у небесній красі,\nО, що за радість: там вбачу Христа, - \nЗ того буде вічна радість моя!\n\nКуплет 3\nТам я зустріну всіх близьких моїх,\nЩо жили ми разом тут на землі.\nТам буде правда й Христова рідня,\nЗ того буде вічна радість моя.', '', '', 'ua', NULL, 0, NULL, NULL),
(639, 120, 'Прекрасний білий стрій прекрасний дім святий', 0, 'Куплет 1\nПрекрасний білий стрій, прекрасний дім святий, \nСвітла земля свята, - там ночі вже нема.\nТам я вінець життя одержу від Христа,\nБуде він сяяти, наче зоря.\n\nПриспів:\nПрекрасний стрій (прекрасний білий стрій) \nСвітла земля (прекрасна та земля),\nПрекрасний дім (прекрасний дім святий),\nДля вірних там (для вірних слуг є там),\nСлавний вінець (славний вінець нас там жде), \nСіяючий (ясно так, ясно сія)...\nЧудесний хор там є (чудесний хор там є), \nСлавить Христа (все славить Христа).\n\nКуплет 2\nПрекрасні ті думки радують так мене, - \nМи вічно там будем, як це життя пройде. \nРадість небесна там наповнить всі серця, \nБажаю бути там, - про це молюсь...\n\nКуплет 3\nПрекрасні речі там, де наш Спаситель сам;\nВід смутку й марноти скоро підем туди,\nДе смерті вже нема, а вічне там життя;\nДе правда вічная - в землі святій...', '', '', 'ua', NULL, 0, NULL, NULL),
(640, 121, 'Христос за гріх наш викуп дав', 0, 'Куплет 1\nХристос за гріх наш викуп дав, о, чудесний Спаситель! \nМи куплені, - ціна дана, о, чудесний Спаситель!\n\nПриспів: \nО, чудесний Спаситель, є Ісус, мій Ісус,- \nО, чудесний Спаситель, Ісус, мій Господь.\n\nКуплет 2\nВін кров святу за нас пролив, о, чудесний Спаситель !\nІ з Богом примирив мене, о, чудесний Спаситель!\n\nКуплет 3\nІз мого серця гріх Він стер, о, чудесний Спаситель!\nІ Сам царить Він в нім тепер, о, чудесний Спаситель!\n\nКуплет 4\nВ дорозі йде зі мною Він; о, чудесний Спаситель !\nІ поміч Він дає в біді, о, чудесний Спаситель!\n\nКуплет 5\nВін перемогу нам дає, о, чудесний Спаситель!\nІ радість в горю подає, о, чудесний Спаситель!\n\nКуплет 6\nЙому я серце дав своє, о, чудесний Спаситель!\nВ нім місця світ немає вже, тільки любий Спаситель!', '', '', 'ua', NULL, 0, NULL, NULL),
(641, 122, 'О як мило чути голос голос той дивний', 0, 'Куплет 1\nО, як мило чути голос, голос той дивний: \nВчора, нині і навіки Ісус той самий! ;\nВін спасає всіх нас грішних, а тих, хто слабий - \nВін зціляє від недугів, - Бог наш дорогий!\n\nПриспів:\nВчора, нині і навіки Ісус той самий,\nВсе зміниться, Він - ніколи, Він все той самий,. \nСлава все Йому, слава все Йому!  Все зміниться, \nВін - ніколи: слава все Йому!\n\nКуплет 2\nВін для грішників був другом, згублених спасав.\nО, прийдіть усі до Нього - Він же кров пролляв.\nВін колись сказав до жінки: «Не суджу тебе,\nЙди і більше не гріши вже», й скаже так тобі.\n\nКуплет 3\nВін колись зціляв недужих, як був на землі,\nІ також оздоровляє Він і в наші дні.\nВін давав здоров’я многим, бо Він мав ту власть; \nХто до Нього приторкнеться, Він і нині дасть.\n\nКуплет 4\nЯк колись на Еммаус йшли, - з ними був в той час; \nТак і в нашім Він житті є завжди близько нас;\nСкоро знов Його побачим - того дня ждем всі... \nТой самий Ісус все буде, як вознісся Він.', '', '', 'ua', NULL, 0, NULL, NULL),
(642, 123, 'Будем розсівати Слово Боже рано', 0, 'Куплет 1\nБудем розсівати Слово Боже рано,\nВ півдні, й при заході сонця, і вночі;\nБудемо чекати овочу, що зродить;\nЗ радощами в серці принесем снопи.\n\nПриспів: \nПринесем снопи (2р.), \nЗ радощами в серці принесем снопи.\n\nКуплет 2\nЧи то в пору добру, чи в час непогоди,\nНавіть в часі бурі, спеки чи дощу \nМи не занедбаєм доброї нагоди, - \nЗ радощами в серці принесем снопи.\n\nКуплет 3\nБудем поширяти правду Божу всюди,\nХоч і перешкоди всякі навкруги:\nСкоро час настане, жниво дозріває.\nЗ радощами в серці принесем снопи.', '', '', 'ua', NULL, 0, NULL, NULL),
(643, 124, 'Не знаю чому Бог мені відкрив Свою любов', 0, 'Куплет 1\nНе знаю, чому Бог мені відкрив Свою любов,\nАбо чому Спаситель мій пролив за мене кров?\nНе знаю, як Бог дав мені спасіння дар прийнять,\nІ сила Його Слова як дає нам благодать.\n\nПриспів: \nАле знаю, в Кого я вірю, -\nНіщо мене з Христом не розлучить; \nМені Він насліддя вручить \nВ день, коли Він знов прийде.\n\nКуплет 2\nНе знаю я, як Дух Святий хоронить в вірі нас,\nІ відкриває нам Христа в Божественних словах?\nНе знаю я часу, ні дня, коли Господь прийде - \nЧи через смерть,чи Сам мене в той день Він забере?', '', '', 'ua', NULL, 2, '2021-03-28', NULL),
(644, 125, 'Я чужоземець тут у стороні чужій', 0, 'Куплет 1\nЯ чужоземець тут у стороні чужій.\nНа небесах, в святім краю, там дім є мій.\nЯ посланець є тут з Царства Небесного, - \nПриношу вістку для людей!\n\nПриспів:\nВістку приношу із небес, що ангели співають все: \n«О, примирітеся, - звучать слова Царя, -\n О, примирітесь з Богом всі!»\n\nКуплет 2\nЦе є Царський наказ, щоби всі люди скрізь \nВ гріхах покаялись, і Він простить їм гріх.\nО, нині, друже мій, прийми Христа і жий! -\n Приношу вістку для людей.\n\nКуплет 3\nМій дім гарніший є, як саронські квітки,\nІ радість вічна там над всіма вірними.\nНе замовкаю я і кличу всіх туди —\nДо Господа, мого Царя.', '', '', 'ua', NULL, 0, NULL, NULL),
(645, 126, 'Вже темно і народ тремтить весь', 0, 'Куплет 1\nВже темно і народ тремтить весь.\nЗдригаються небо й земля.\nА ось мертві вже воскресають, - \nЯвляється слава Христа.\n\nПриспів: \nХристос прийде, своїх візьме, \nСпасенних в славу всіх збере; \nХристос прийде! О, славний час \nДля всіх людей, котрих Він спас.\nО, радісний для нас той день, (2р.) \nКоли Христос з небес прийде,\nУ славу нас введе.\n\nКуплет 2\nПрийде Він не так, як приходив \nВмирати за людські гріхи,\nА прийде у славі Владика - \nСудити живих і мертвих.\n\nКуплет 3\nО, люди, від сну пробудіться! \nПокайтесь, втікайте від зла!\nЗабудьте злобу, обніміться!\nІ будем чекати Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(646, 127, 'Ти пішов так далеко геть від Отця', 0, 'Куплет 1\nТи пішов так далеко геть від Отця,\nСмуток, горе і блуд в світі цім;\nОсь лагідний днесь голос зове тебе:\n-Сину мій, сину мій, йди в свій дім!\n\nПриспів: \nСину мій, (йди в свій дім), (2р.) \nСину мій, о, йди в свій дім!\n(Сину мій, о йди в свій дім!)\nЙди в свій дім (2р.)\n(Це Отець твій кличе днесь):\nСину мій, йди в свій дім, в свій дім! \n(Сину мій, іди в свій дім!)\n\nКуплет 2\nХочуть хвилі морські потопить тебе,\nНебезпека тебе жде в путі;\nОсь дім захисту жде у Отця тебе,\nСину мій, сину мій, йди в свій дім!\n\nКуплет 3\nВін благає тебе, поклик вчуй Його,\nЯк Він просить тебе: сину мій, - \nВ дім Отця твого йди і більш не блуди. \nСину мій, сину мій, йди в свій дім!', '', '', 'ua', NULL, 0, NULL, NULL),
(647, 128, 'Коли страх мене обгорне', 0, 'Куплет 1\nКоли страх мене обгорне, о, Спасе, тримай!\nІ коли віра ослабне, Ти мене тримай!\n\nПриспів: \nЗа руку тримай, за руку тримай!\nСпасителю Всемогутній, Сам мене тримай\n\nКуплет 2\nЯ не можу сам триматись, о, Спасе, тримай!\nДай на Тебе покладатись, Ти мене тримай!\n\nКуплет 3\nВ ясний час чи в час нещастя, о, Спасе тримай!\nВ дні недолі чи у щастю Ти мене тримай!\n\nКуплет 4\nСтережи Сам мою душу, о, Спасе, тримай!\nТи купив мене ціною, Ти мене тримай!', '', '', 'ua', NULL, 0, NULL, NULL),
(648, 129, 'Як солодко йти з Ісусом', 0, 'Куплет 1\nЯк солодко йти з Ісусом, крок за кроком, день за днем.\nУ Його сліди ступати і ходити все за Ним.\n\nПриспів: \nСлідом в слід (2р.) піду за Ісусом.\nКожний день, кожний час піду за Ісусом.\n\nКуплет 2\nЯк безпечно йти з Ісусом, спершись на рам’я Иого - \nЙти усюди, де веде Він, поки є життя мого.\n\nКуплет 3\nКрок за кроком йду з Ісусом, всякий час усе за Ним; \nХоч я немічний, безсилий, але сила моя в Нім.\n\nКуплет 4\nО, тримай мене, мій Спасе, близько, близько при Собі, \nЩоб ніколи не зблудив я, щоб ступав в сліди Твої!', '', '', 'ua', NULL, 0, NULL, NULL),
(649, 130, 'Любо вірити в Ісуса і святим Його словам', 0, 'Куплет 1\nЛюбо вірити в Ісуса і святим Його словам;\nЯ душею підношуся в Край Небесний, де Він Сам.\n\nПриспів:\nМій Спасителю, Ісусе! Ти є добрий Пастир мій.\nМій Спасителю, Ісусе, я вже вічно буду Твій!\n\nКуплет 2\nЯ надіюсь на Ісуса, на Його святу любов;\nЯ Йому служу й молюся: Він пролив за мене кров.\n\nКуплет 3\nЯк приємно знати Бога, духом пробувати з Ним, \nПідкріплятись Його Словом і ходити завжди з Ним!', '', '', 'ua', NULL, 0, NULL, NULL),
(650, 131, 'Більш про Ісуса хочу знать', 0, 'Куплет 1\nБільш про Ісуса хочу знать,\nБільше про Його благодать,\nБільш про Його святу любов,\nЩо Він за мене умирав.\n\nПриспів: \nБільш, більш про Ісуса, (2р.)\nБільш про святу Його любов,\nЩо Він за мене умирав.\n\nКуплет 2\nБільш до Ісуса я спішу,\nЩоб волю пізнавать святу;\nЩоб Дух Святий учив мене,\nЯк маю свято жить усе.\n\nКуплет 2\nБільш про Ісуса хочу знать,\nСлово Його святе читать,\nБачити в Нім Його любов,\nЯк за людей пролив Він кров.\n\nКуплет 4\nБільше я хочу знати те,\nЯк вічно Він Царем буде,\nБільш про Його славний прихід,\nЯк прийде взяти Він своїх.', '', '', 'ua', NULL, 0, NULL, NULL),
(651, 132, 'Як олень спрагнений в степу біжить до джерела', 0, 'Куплет 1\nЯк олень спрагнений  степу біжить до джерела, \nТебе так прагне, Боже мій, моя сумна душа. (2р.)\n\nКуплет 2\nТи є цілюще джерело, що в нім жива вода,\nЯка відсвіжує наш дух і спрагнені серця. (2р.)\n\nКуплет 3\nЧого ж ви журитесь, брати, чого такі сумні? Надійтесь, \nБог оберне жаль у радісні пісні. (2р.)\n\nКуплет 4\nКріпіться, браття, та з душі ви смуток геть женіть.\nМи ж діти Того, що держить в руках Своїх весь світ. (2р.)\n\nКуплет 5\nО, Спасе! Спрагненим серцям живої дай води,\nІ нас знеможених кріпи, шляхом життя веди! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(652, 133, 'Спокій небесний я знайшов', 0, 'Куплет 1\nСпокій небесний я знайшов, як до Христа прийшов: \nМоє Він серце відродив, мої гріхи простив.\nТам біля студні Сихаря я був з Христом моїм,\nНераз була душа моя там в Галилеї  з Ним.\n\nПриспів: \nТам, в Галилеї з Ним,\nІ часто бачу я себе там, в Галилеї з Ним.\n\nКуплет 2\nПостійно я стремлюсь вперед, в небесний вічний рай;\nЛиш за Христом іду я вслід в обітований Край.\nТепер надіюсь на Нього, і рад Йому служить,\nІ я спішу в ногах Його тягар гріха зложить.\n\nКуплет 3\nЯ бачу той тернистий шлях, на нім Христову кров; \nМи всі томились у гріхах, нас всіх спасла Любов. \nЛюбов Христа нас підняла із рова марноти. \nБушують в світі хвилі зла, життя ж лиш у Христі.', '', '', 'ua', NULL, 0, NULL, NULL),
(653, 134, 'Без Бога я блукав у світі', 0, 'Куплет 1\nБез Бога я блукав у світі, спокою не мав,\nЛише Спаситель в Своїй крові спокій мені дав.\n\nПриспів: \nДивний спокій Христос дарував,\nНа хресті дар спасіння придбав.\nХоч ще гріх навкруги так бушує, кипить, \nАле Бог нас хранить.\n\nКуплет 2\nМарноти світу затопляли душу вже мою,\nТоді Збавитель для спасіння руку дав Свою.\n\nКуплет 3\nНезмінне щастя, милість Божу серцем я пізнав: \nХристос за наші всі провини на хресті вмирав.\n\nКуплет 4\nХоч втомлені ви і безсильні в боротьбі земній, \nСпішіть ви до Христа, - Він дасть вам радість і спокій.\n\nКуплет 5\nСердечні двері відчиніте і прийміть Христа,\nВін вашу душу знов очистить, дасть нове життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(654, 135, 'Працю всім працю всім нам Господь доручив', 0, 'Куплет 1\nПрацю всім, працю всім нам Господь доручив:\nВ путь підем, що Спаситель наш Сам проложив.\nІ Дух Правди Його буде нас підкріплять,\nВіру, сили, й життя кожний день обновлять.\n\nПриспів: \nПрацю всім (працю всім), (2р.)\nВірним Бог (вірним Бог)\nДоручив (доручив).\nО, працюй і молись,\nПоки Спаситель наш прийде.\n\nКуплет 2\nВсі до праці, усі! Хліб голодний знайде\nІ, хто правди шукає, - до Бога прийде.\nМи всі маєм про істину ближнім сказать,\nВ смутку-горю знеможеним поміч подать.\n\nКуплет 3\nВсі до праці, усі! Світ страждає у злі... \nЦарство Правди поширюймо тут на землі, \nТоді Бог Сам оселиться в наших серцях,\nБуде рай на землі, як тепер в небесах.\n\nКуплет 4\nВсі до праці, усі! Наш небесний Отець \nВ нагороду за працю дасть правди вінець.\nТам всі хори зіллються в божественний спів:\nВічна слава Тобі, наш Господь, Цар царів!', '', '', 'ua', NULL, 0, NULL, NULL),
(655, 136, 'Візьми хрест сві', 0, 'Куплет 1\n«Візьми хрест свій, йди за Мною!» (Зр.)\nСам Спаситель кличе вас, мене.\n\nКуплет 2\nЯ іду, куди веде Він, (Зр.)\nПо путі тернистім в світі цім.\n\nКуплет 3 \nЯ іду через Голгофу,  (Зр,) \nЗ Ним пройду страждання всі земні.\n\nКуплет 4\nЯ пройду з Ним перешкоди (Зр.)\nІ ввійду в небесний Вічний Край.\n\nКуплет 5\nВсюди Він мені поможе, (Зр .) \nБлагодаттю підкріпить мене.\n\nКуплет 6\nО, душе моя, кріпися! (Зр.) \nЗа тобою скоро Він прийде.', '', '', 'ua', NULL, 0, NULL, NULL),
(656, 137, 'Сіється зерно при ранній зорі', 0, 'Куплет 1\nСіється зерно при ранній зорі,\nСіється зерно в південній жарі,\nСіється зерно, як ляже тінь, \nСіється зерно, - скінчивсь вже день.. .\nЩо будеш, друже, жать?  \nЩо, друже, будеш жаты?\n\nПриспів: \nСіється в ясний чи похмурий час, \nСіється в силі чи в немочі в нас; \nЗібране тут чи то там в небесах, \nПраведне жниво чекає нас.\n\nКуплет 2\nПадає зерно на стежці твердій, \nі Падає зерно на грунт кам’яний,\nПадає зерно і у бур’ян,\nПадає зерно й на добрий лан...\nЩо будеш, друже, жать?\nЩо, друже, будеш жать?\n\nКуплет 3\nСіється зерно і мрій, і зітхань,\nСіється зерно плачу і страждань,  \nСіється зерно ганьби, гріха,\nСіється зерно і кривди, і зла...\nЩо будеш, друже, жать?\nЩо, друже, будеш жать?\n\nКуплет 4\nСіється зерно і добре, і зле,- \nВсякеє зерно свій плід принесе...\nСіється зерно до того дня,\nАж поки Божі прийдуть жнива...\nЩо будеш, друже, жать? \nЩо, друже, будеш жать?', '', '', 'ua', NULL, 0, NULL, NULL),
(657, 138, 'Пригадаймо браття сестри тіминулії часи', 0, 'Куплет 1\nПригадаймо, браття, сестри, ті-минулії часи,\nЯк зібрались на вечерю діти Божі у любві;\nНе щоб тілу догоджати час проводили вони,\nЛиш щоб Бога прославляти, ж одна сім’я, в любві.\n\nКуплет 2\nЗа столом псалми хваління щиро Неслися з сердець \nЗа дароване спасіння, що у Сині дав Отець.\nУ той час любов Христову відчували вірні всі: \nЦеркви Божої будова виростала у красі.\n\nКуплет 3\nІ тепер ми знов зійшлися за братерським цим столом,\nНаші співи знов злилися у Божественний псалом.\nО, Спасителю, благаєм: будь Ти з нами по всі дні,\nДух Святий хай нас навчає жити в радості, в любві!', '', '', 'ua', NULL, 0, NULL, NULL),
(658, 139, 'О дивний день чудовий час', 0, 'Куплет 1\nО, дивний день, чудовий час, коли Спаситель в перший раз \nЗі мною в заповіт вступив, спокоєм серце наділив.\n\nПриспів:\nДивний день, (2р.) коли Господь гріхи простив,\nТепер зі мною Сам Ісус, Він захищає від спокус: \nДивний день, (2р.) коли Господь гріхи простив!\n\nКуплет 2\nО, дивний день, коли Христос знайшов мене в долині сліз. \nТепер Він Пастир добрий мій, я вже Його, я вже не свій!\n\nКуплет 3\nО, дивний день, коли в любві Він руку простягнув мені; \nСумніви серця розігнав, — хвалу я Господу віддав.\n\nКуплет 4\nО, дивний день, коли життя моє воскресло у Христі, \nКоли мої всі почуття Він Духом обновив Святим.\n\nКуплет 5\nО, дивний день; коли пізнав душею я любов Христа.\nІ в серце Господа прийняв, - щасливим став на все життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(659, 140, 'О Боже Ти бачиш мене', 0, 'Куплет 1\nО, Боже, Ти бачиш мене, \nТи знаєш стремління душі, \nПрийми в жертву серце моє,\nНавчи, як служити Тобі!\nЯ хочу веління Твої завсіди з любов’ю сповнять.\nО, Боже, дай сили мені Твоє лиш Ім’я прославлять.\n\nКуплет 2\nСпасителю мій! Обновляй постійно мої почуття,\nІ серце моє оживляй, освітлюй моє Ти життя, - \nЩоб вірним слугою Твоїм Трудився у Церкві живій,\nСлужив Тобі серцем усім завсіди, Спасителю мій\n\nКуплет 3\nРукою могутньою Сам, о, Боже, мене Ти веди, \nЩоб міг я в святі небеса дорогою правди іти.\nО, Боже, дай сили мені,\nЩоб хрест свій щоденний я ніс,\nНе впав у земній боротьбі і плід я для Тебе приніс!', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(660, 141, 'Іди в виноградник робота там є', 0, 'Куплет 1\nІди в виноградник, робота там є,\nДавно уже жде тебе діло святе.\nБагато всього там ще треба зробить,\nРобітників мало, щоб все закінчить:\nТам треба копать і полоть, прочищать,\nІ часто водою усе поливать;\nВід холоду, вітру і бур берегти \nІ часто від хижих вовків стерегти.\n\nПриспів:\n Іди (іди, іди), іди (іди, іди),\nіди в виноградник, робота там є.\nІди (іди), іди (іди, іди)!\nРобітників мало, а час нас не жде.\n\nКуплет 2\nІди в виноградник, іди вже скоріш!\nСтраждав Я за тебе, навіки ти Мій.\nВесь час твій, і розум, і сили твої,\nВіддай ти віднині для праці Мені.\nТебе дорогою ціною придбав, - \nУ муках тяжких Свою кров проливав.\nЯк тяжко було там страждати Мені;\nУмер Я, щоб дати спасіння тобі.\n\nКуплет 3\nІди в виноградник, ще поки є день;\nЧас тіні, час ночі вже скоро прийде:\nВже сонце на захід схилилось, біжить, - \nЯк зайде, не зможеш прийти і робить. \nПрацюй від зорі до зорі, і \nЯ Сам Навчать тебе буду і сили подам. \nБлажен, хто, почувши Мій голос, прийде \nУ Мій виноградник, де працю знайде.', '', '', 'ua', NULL, 0, NULL, NULL),
(661, 142, 'За тебе Я вмирав і кров Свою пролив', 0, 'Куплет 1\nЗа тебе Я вмирав і кров Свою пролив,\nСтражданням на хресті тебе Я відкупив.\nЖиття віддав тобі, а що Ти дав Мені? (2р.)\n\nКуплет 2\nЯ на землі прожив в скорботах та журбі,\nЩоб ти у небі жив, щоб щастя дать тобі.\nЯ радість дав тобі, а що ж ти дав Мені? (2р.)\n\nКуплет 3\nКоли Я умирав у муках на хресті,\nТобі життя Я дав, твої гріхи простив.\nСтраждав за тебе Я, подяка де ж твоя? (2р.)\n\nКуплет 4\nО, друже дорогий, Христу життя віддай:\nЛиш Він - Спаситель твій, Йому хвалу складай.\nНа землю Він прийшов, пролив за гріх твій кров. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(662, 143, 'О скільки душ страждають без Бога в світі цім', 0, 'Куплет 1\nО, скільки душ страждають без Бога в світі цім,\nУ темряві гріховній грозить загибель їм:\nБез Пастиря блукають на гибельнім путі,\nКуди ідуть, - не знають... Що жде їх впереді?\n\nПриспів: \nХодім же шукать заблудлих,\nДо Христа їх приведім.\nМожна буде і нам у той день сказать:\n«Я прийшов сюди з моїм».\n\nКуплет 2\nХто жертви не страшиться, на все готовий йти,\nЩоб тих овець заблудлих від гибелі спасти?\nХто показать піде їм путь правди, дім Отця.\nЛюбов’ю хто потішить розбиті їх серця?\n\nКуплет 3\nВелика радість буде при зустрічі Христа.\n«Наш добрий Пастир, - скажеш, овечка знайдена!\nВ гущавині блукала і змучилась в біді,\nЯ взяв її безсильну... Прошу, її прийми!»', '', '', 'ua', NULL, 0, NULL, NULL),
(663, 144, 'До Христа мій друже йди з вірою скоріш', 0, 'Куплет 1\nДо Христа, мій друже, йди з вірою скоріш,\nВін прийшов тебе спасти, дасть тобі спокій.\n\nПриспів: \nХай прославлять всі уста Господа Христа!\nВін за грішників страждав і їм вічність дав.\n\nКуплет 2\nВін престол Свій залишив в славних небесах,\nІ на землю Він прийшов, знищив смерті страх.\n\nКуплет 3\nДруже! Спас Себе віддав за твоє життя.\nНа хресті Він Сам сказав: «Завершилося!»\n\nКуплет 4\nНе вагайся, поспішай, скинь тягар душі,\nВсе життя Христу віддай і Йому служи!', '', '', 'ua', NULL, 0, NULL, NULL),
(664, 145, 'Для світу спасіння', 0, 'Куплет 1\nДля світу спасіння - Христова любов:\nЗа наші провини Ісус пролив кров;\nСпасіння звершив Він, дав радість, спокій,\nРадійте всі вірні, (Зр.) в любові святій!\n\nКуплет 2\nЯ вірю Ісусу, Він нас відкупив,\nЗ гріхів Він нас кров’ю Своєю обмив,\nВін світлом небесним серця освітив: \nСпасіння від Бога, (Зр.) і Господа сил.\n\nКуплет 3\nСин Божий розп’ятий вмирав на хресті, \nРозп’ятий для світу і я у Христі,\nІ світ цей для мене розп’ятий з гріхом.\nІ з Ним все живу я, (Зр.) з Ісусом Христом.\n\nКуплет 4\nГосподь дасть насліддя для вірних \nСвоїх, На небі оселить навіки святих.\nЗіллються там хори спасенних усіх: \n«Хвала, честь Ісусу, (Зр.) хай буде повік!»', '', '', 'ua', NULL, 0, NULL, NULL),
(665, 146, 'Буду співати славу складати Тому', 0, 'Куплет 1\nБуду співати, славу складати Тому, \nХто на хресті за нас вмирав.\nДивний Учитель - Христос Спаситель:\nВін нам спасіння всім дарував.\n\nКуплет 2\nСлавити вічно буду Христа:\nВ Ньому знайшов я світло й життя \nСили ворожі з Ним переможу \nВ земній тут боротьбі. (2р.)\n\nКуплет 3\nЯ на Ісуса завжди дивлюся,\nНим лиш одним на світі я живу.\nВін - мій Спаситель, Пастир, Учитель,\nДасть мені місце в небі, в раю.\n\nКуплет 4\nРадості в людях я не знайду \nІ від Ісуса куди піду?\nЗ Богом іду я і неземную \nРадість знайду в раю. (2р.)\n\nКуплет 5\nТут все минає, - там в Божім раю \nВтомленим душам дасть Господь спокій. \nКоли ввійду я в славу святую,\nТам мене прийме Спаситель мій.\n\nКуплет 6\nТам залунає пісня свята, -\nСлавити вірні будуть Христа.\nПісню спасіння, пісню хваління \nБуду співати й я. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(666, 147, 'Пошли Господь сказати про Твою безмірну любов', 0, 'Куплет 1\nПошли, Господь, сказати про Твою безмірну любов,\nЯк послав Ти Сина з неба, сказати знову і знов.\n\nПриспів: \nЗнову і знову скажи, (2р.)\nЧудову ту вість про Ісуса знову і знову скажи!\n\nКуплет 2\nПошли, Господь, сказати про Христову до всіх любов, \nЯк прийшов до нас Він з неба, сказати знову і знов.\n\nКуплет 3\nПошли, Господь, сказати про Христову пролиту кров. \nВін воскрес, вознісся в небо, сказати знову і знов.\n\nКуплет 4\nПошли, Господь, сказати, що Христос спасіння дає.\nХто Його благає щиро, радість життя пізнає.', '', '', 'ua', NULL, 0, NULL, NULL),
(667, 148, 'Заспіваймо всі пісню що потішить нас', 0, 'Куплет 1\nЗаспіваймо всі пісню, що потішить нас!\nСкоро ми підем у Вічний Дім;\nНіч гріха мине, і прийде спасіння час,\nСкоро ми підем у Вічний Дім.\n\nПриспів:\nСкоро ми підем, (2р.) перейдем через Йордан,\nІ ввійдемо в Край, в довгожданний Ханаан.\nСкоро ми підем у Вічний Дім.\n\nКуплет 2\nМи для Бога всі будем разом працювать,\nСкоро ми підем у Вічний Дім;\nА Христос на поміч Свою дасть благодать, \nСкоро ми підем у Вічний Дім.\n\nКуплет 3\nПокажімо всім правду в нашому житті,\nСкоро ми підем у Вічний Дім;\nА Христос спасіння Своє нам також дасть,\nСкоро ми підем у Вічний Дім.\n\nКуплет 4\nНі недуг, ні смерті нема в Краю святім,\nСкоро ми підем у Вічний Дім;\nМи знайдем спокій в місті вічнім, золотім,\nСкоро ми підем у Вічний Дім.', '', '', 'ua', NULL, 0, NULL, NULL),
(668, 149, 'Кріпися ти безсильний', 0, 'Куплет 1\nКріпися ти безсильний, поможе Бог тобі;\nЛиш будь Йому все вірний, Він поміч дасть в біді.\nГосподь розвіє хмари, і сонце засія...\nДуші спокій пошле Він і оживить тебе.\n\nПриспів: \nКріпись, кріпись, і сонце освітить тебе, \nКріпись, кріпись, і Господь оживить тебе.\n\nКуплет 2\nКріпись, християнине! Будь вірним до кінця;\nЯк трапиться нещастя - на поміч клич Христа. \nСкінчиться ця дорога, заплати день прийде:\nБо праця, що для Бога, марною не буде.\n\nКуплет 3\nКріпись, християнине, про Божу правду дбай!\nЗа Богом йди Єдиним, в душі Йому співай.\nІсус наш скоро прийде, і близько вже той час.\nЯка то радість буде, коли Він візьме нас!', '', '', 'ua', NULL, 0, NULL, NULL),
(669, 150, 'Проміння радості з небес горять в моїй душі', 0, 'Куплет 1\nПроміння радості з небес горять в моїй душі;\nЯсніше Він понад усе - то є Спаситель мій.\n\nПриспів: \nДивне сяйво,(2р.) як минають у спокою дні:\n Коли Ісус явля лице - дивне сяйво є в душі.\n\nКуплет 2\nЧудесний гімн в моїй душі звучить Царю царів:\nЦю пісню чує Він, хоч би співати я не міг!\n\nКуплет 3\nВесна царить в моїй душі, як близько є Христос;\nІ голуб миру для душі красу життя приніс.\n\nКуплет 4\nПроміння радості в душі, надії і любві.\nХвала Йому за всі дари, що Він дає мені!', '', '', 'ua', NULL, 0, NULL, NULL),
(670, 151, 'О брате час вже пробудися', 0, 'Куплет 1\nО, брате, час вже, - пробудися \nВід сну гріха і марноти.\nХристос зове тебе: Прокинься!\nТебе Він кличе у любві.\n\nПриспів: \nНе ухиляйсь, бо Він в любві зове тебе,\nА поспішай скоріш, скоріш до Нього йди.\n\nКуплет 2\nВін полюбив тебе, мій брате,\nЗа тебе Він на хрест пішов,\nЩоб за гріхи твої страждати,\nЩоб ти у Нім життя знайшов.\n\nКуплет 3\nІз ран Його свята кров ллялась,\nЛюбов’ю зір Його горів.\nО, брате мій, ми провинились, - \nНевинно Він за нас терпів.\n\nКуплет 4\nПречиста кров нас очищає,\nЗмиває з серця всякий гріх;\nВона і душу відновляє,\nСпокій дає для вірних всіх.', '', '', 'ua', NULL, 0, NULL, NULL),
(671, 152, 'Я спасіння знайшов', 0, 'Куплет 1\nЯ спасіння знайшов, як до Бога прийшов, - \nУсім серцем я вірю в Ісуса! Він спокій дав мені,\nІ тягар зняв з душі, - в Сина Божого вірую я.\n\nПриспів: \nВірю я, (2р.) усім серцем я вірю в Ісуса.\nВірю я, (2р.) в Сина Божого вірую я!\n\nКуплет 2\nВін мене відкупив, - вірою я прийняв,\nУсім серцем я вірю в Ісуса! У незмінній любві\n Він Хранитель душі,-в Сина Божого вірую я!\n\nКуплет 3\nЩо за радість тепер, Він зі мною є все,- \nУсім серцем я вірю в Ісуса! Хочу славити все,\nБо Він спас і мене, - в Сина Божого вірую я!', '', '', 'ua', NULL, 4, '2020-07-31', NULL),
(672, 153, 'Кращі літа молодії', 0, 'Куплет 1\nКращі літа молодії, - свіжії сили в ці дні весни, - \nМи присвятім їх Ісусу в дар для Нього дорогий.\nЩо може бути ще краще нам, як Ісусу служить?\nТут, у житті цім дочаснім, серце Христу присвятім.\n\nКуплет 2\nВчуй, як Христос закликає, час благодатний для нас настав; \nБільше вагатись не можем: Спас нам життя дарував. Сестри!\n Ми прапор підіймем з Іменем чудним Христа.\n Промінь небесний зогріє віру й любов у серцях.\n\nКуплет 3\nСміло, во Ім’я Ісуса, браття, вперед в боротьбі з гріхом! \nТисячі гинуть в темряві. З світлом до них ми підем.\nХоч нас зустрінуть гоніння, смерть за Христа не страшна;\nЗ вірою все переможем для слави Спаса Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(673, 154, 'Вже Сонце засіяло і правди', 0, 'Куплет 1\nВже Сонце засіяло і правди, і добра,\nПуть Божий освітило, вставати пора!\nПогляньте! Божа нива жовтіє навкруги;\nМи чуєм голос Божий, -- час до праці йти.\n\nКуплет 2\nНе втомлюйтесь душею на ниві трудовій, \nПрацюйте всі для Нього у любві святій.\nЯк вже жнива скінчаться - Пройдем ми шлях земний,\nБудем відпочивати в країні святій.\n\nКуплет 3\nОб’єднуйтеся, браття і сестри, всі гуртом \nВ союзі благодаті у святім труді.\nХоч хмари насувають, хоч не вгаває зло,\nАле всі вірні знають, що Сонце зійшло!', '', '', 'ua', NULL, 0, NULL, NULL),
(674, 155, 'Господь мені спасіння дав', 0, 'Куплет 1\nГосподь мені спасіння дав | в крові святій, (2р.)\nЛюбов Ісуса я пізнав в крові Його святій.!\n\nПриспів: \nКров’ю святою, Спасе мій,\nДушу мою обмий ізнов!\nО, Спаситель, Пастир мій,\nТи Сам пролив за мене кров!\n\nКуплет 2\nЄдиний захист маю я | в крові святій, (2р.)\nЗнаходжу я спокій, життя в крові Його, святій.\n\nКуплет 3\nЄ сила для відродження | в крові святій. (2р.)\nМоїх гріхів всіх прощення в крові Його святій.\n\nКуплет 4\nГосподь оздоровив мене І в крові святій, (2р.)\nІ серце обновив моє в крові Своїй святій.', '', '', 'ua', NULL, 0, NULL, NULL),
(675, 156, 'О наш Отець на небесах', 0, 'Куплет 1\nО, наш Отець на небесах,\nПочуй моління Ти моє!\nХай у житті, в благих ділах святиться Ім’я ввік Твоє.\n\nКуплет 2\nТи Всевідучий, Господь сил, \nтремтить перед Тобою все. \nСоздателю усіх світил,\nХай прийде царство вже Твоє!\n\nКуплет 3\nО, Боже, як премудрий Ти!\nІ ціль життя мого одна:\nВ часи безрадні і тяжкі,\n хай буде воля ввік Твоя.\n\nКуплет 4\nТи Цар і Бог наш Всеблагий, \nжиття даєш усім єствам, \nТебе благаєм, Всесвятий: \nдай хліб щоденний нині нам!\n\nКуплет 5\nТи Милосердний, Боже наш,\nПрости провини наші нам,\nЯк ми прощаєм в кожний час \nзлі вчинки нашим ворогам!\n\nКуплет 5\nХто без Тебе спастися б міг?\nВід всіх спокус нас захисти. \nНас немічних, дітей Твоїх, від злого духа хорони.\n\nКуплет 6\nПремудрі всі Твої діла,\nТвоє і царство, Боже сил,\nТобі і слава, і хвала повіки вічнії. Амінь.', '', '', 'ua', NULL, 3, '2021-04-01', NULL),
(676, 157, 'Я подорожній тут на землі', 0, 'Куплет 1\nЯ подорожній тут на землі:\nТут я скитаюсь на чужині.\n\nПриспів: \nТам в небі дім мого Отця, \nТуди стремиться моя душа.\n\nКуплет 2\nЯ переходжу цю чужину,\nВертаю в рідну я Вітчизну.\n\nКуплет 3\nТяжко і тісно, смутно мені,\nЯк то звичайно на чужині.\n\nКуплет 4\nХочу як швидше тут перейти,\nМоє скитания закінчити.\n\nКуплет 5\nКоли земне життя я скінчу,\nТоді навіки в домі спічну.\n\nКуплет 6\nВведе у дім Свій мене Отець,\nТоді стражданням прийде кінець.', '', '', 'ua', NULL, 0, NULL, NULL),
(677, 158, 'Ідуть подорожні додому ідуть', 0, 'Куплет 1\nІдуть подорожні, додому ідуть,\nВ Край Вічний, де радість, спокій.\nНі горя, ні сліз вони там не знайдуть:\n їх прийме Христос дорогий.\n\nПриспів: \nТам нема (там нема) вже зла (нема зла),\n Темрява (темрява) пройшла,\n(вже пройшла),\nСонце Правди там вічно сія. (2р.)\n\nКуплет 2\nНемає там смерті, немає страждань,\nТам кривди і гніву нема,\nНі голосу злого, ні грішних бажань...\nТам світло Господнє сія.\n\nКуплет 3\nІдуть подорожні... вже близько той Край,\nДе праведні душі усі;\nТуди їх Спаситель зібрав в дивний рай,\nДе сяє все в Божій красі.', '', '', 'ua', NULL, 0, NULL, NULL),
(678, 159, 'Неділя день спочинку', 0, 'Куплет 1\nНеділя - день спочинку, день світла і тиші,\nДень молитов, розваги, день скріплення душі.\nВ неділю ми в родину збираємось в одну,\nСпіваємо Творцеві псалми, хвалу святу.\n\nКуплет 2\nВ день перший у неділю Бог світло сотворив,\nВ неділю Спас від гробу печаті відломив.\nАпостолам в неділю Бог Духа з неба дав, \nВідвагу в них збудивши, на проповідь послав.\n\nКуплет 3\nВ неділю, день Господній, зміцниться в нас душа,\nЩоб краще ми сповняли побожнії діла.\nХвала Отцеві в небі і Синові Його,\nІ Духові Святому за радість дня цього!', '', '', 'ua', NULL, 0, NULL, NULL),
(679, 160, 'Страшно бушує життєвеє море', 0, 'Куплет 1\nСтрашно бушує життєвеє море,\nХвилі мій човен гойдають і б’ють.\nВ смертній тривозі, в великому горі,\nБоже, молюся, - не дай потонуть!\n\nКуплет 2\nЗглянься на мене, спаси і помилуй, - \nЗ днів моїх ранніх зі злом я борюсь,\nБільше боротись не маю вже сили...\nБоже, помилуй! - благаю, молюсь.\n\nКуплет 3\nНе залишай мій човен в хвилях моря,\nБоже мій милий, о Боже Благий!\nБлизько вже берег небесний, - і скоро \nТам лиш знайду для душі я спокій!', '', '', 'ua', NULL, 0, NULL, NULL),
(680, 161, 'Хвала що час вже той минув', 0, 'Куплет 1\nХвала, що час вже той минув,\nКоли у темряві гріха тонув. \nСпокою в світі цім я не знайшов, - \nГосподь мій спас мене, до Нього я прийшов.\n\nПриспів: \n3 Христом я буду в небесах\nЗ вітками дивних пальм в руках,\nЗ золотим на голові вінцем,\nСпівати буду там: Спасен Христом!\n\nКуплет 2\nСумніви й страх Спаситель віддалив,\nВін силу смерті смертю переміг.\nВ святій крові мене Він обілив,\nМене в гріхах погибшого Він полюбив.\n\nКуплет 3\nХвала Спасителю! Тепер Він мій:\nВін збудував у серці храм святий;\nЯ не страшусь: Господь мене хранить,\nВід зла Христос мене спасе і захистить.\n\nКуплет 4\nТепер завсіди я уже Його,\nВін - щит мій, і Він захист від всього;\nСпаситель мій, і скеля Він моя.\nЙому від всіх хай буде слава і хвала!', '', '', 'ua', NULL, 0, NULL, NULL),
(681, 162, 'Брате знову нагадай про святу любов', 0, 'Куплет 1\nБрате, знову нагадай про святу любов,\nПро Ісусові слова розкажи нам знов.\nСпів любові ллється, дух до неба рветься.\n\nПриспів: \nСлавте Христа, (2р.)\nСлавте любов Христа!\n\nКуплет 2\nЛюдям всім Христос приніс із небес Любов;\nУтіша в годину сліз нас Його любов.\nНас Христос навчає, - грішних Бог прощає.\n\nКуплет 3\nБрате, знову нагадай про святу любов; \nЗникне з серця сум, одчай, буде радість знов. \nКличе спів любові на дорогу нову.', '', '', 'ua', NULL, 0, NULL, NULL),
(682, 163, 'Уже Йорданські береги здалека бачу', 0, 'Куплет 1\nУже Йорданські береги здалека бачу я;\nТам рідний край мій дорогий, Вітчизна там моя.\n\nПриспів:\nДо пристані ми пливем, де бур нема, ні хвиль.\nЩезає мла, світліють дні, човен пливе вперед.\n\nКуплет 2\nО, берег дивний, берег мій, до тебе я пливу;\nВвійду у Край я рідний свій і там спокій знайду.\n\nКуплет 3\nІ скоро, скоро буду там, де зла немає вже,\nДе всім спасенним сльози Сам Спаситель наш утре.\n\nКуплет 4\nЧудова пристань жде мене, Святий Єрусалим;\nЗ Христом човен мій все пливе, там вічно буду з Ним.\n\nКуплет 5\nХвороби там не буде вже, ні смерті, ні плачу;\nЗемне страждання промине, коли туди ввійду.\n\nКуплет 5\nНавіки буду царювать і славити Христа,\nХристос дасть право споживать плід дерева життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(683, 164, 'Усі що у Христа хрестилися', 0, 'Куплет 1\nУсі, що у Христа хрестилися,\nУ Христа зодягнулися.\n\nПриспів: \nАлілуя!', '', '', 'ua', NULL, 0, NULL, NULL),
(684, 165, 'Із ран Спасителя текла струмком пречиста кров', 0, 'Куплет 1\nІз ран Спасителя текла струмком пречиста кров, - \nПрощення всім вона дала, до Нього хто прийшов.\n\nКуплет 2\nКоли розбійник на хресті розп’ятий умирав, - \nТо від Христа, в крові святій спасіння одержав.\n\nКуплет 3 \nБез Господа і я блукав, і гинув в марноті, - \nМені Христос спасіння дав в Своїй крові святій.\n\nКуплет 4\nСтрумок предивний я знайшов в божественній крові. \nПізнав Його святу любов і став щасливий в Нім.\n\nКуплет 5\nКоли ж я, немічний, колись в моїм житті згрішу,\nВ Крові Спасителя Христа прощення я знайду.', '', '', 'ua', NULL, 0, NULL, NULL),
(685, 166, 'Господь коли ученикам про смерть Свою відкрив', 0, 'Куплет 1\nГосподь, коли ученикам про смерть Свою відкрив, \nТоді ласкаво, як друззям,- взяв хліб, благословив.\n\nКуплет 2\nІ, розламавши, їм подав й слова до них сказав: \n«Прийміте ви і їжте всі; це - тіло є Моє!»\n\nКуплет 3\nЗ вином також Він чашу взяв, благословив її:\n«Оце є кров Моя, - сказав, — із неї пийте всі!»\n\nКуплет 4\nНовий Мій Заповіт в крові Я вам усім даю:\nОце робіть завсіди ви, - смерть згадуйте Мою!»\n\nКуплет 5\nО, Господи, дозволь же й нам Твою пречисту кров, \nПролиту на хресті, згадать - Твою прийнять любов.', '', '', 'ua', NULL, 0, NULL, NULL),
(686, 167, 'Я є вівця Ісуса', 0, 'Куплет 1\nЯ є вівця Ісуса, - Він Пастир добрий мій;\nНим всюди я хвалюся: Він дав душі спокій.\nСебе віддав на муки, за мене постраждав,\nВід смерті, від розпуки мене урятував.\n\nКуплет 2 \nЯ є вівця Ісуса, - Він Пастир добрий мій; \nКоли прийде спокуса, знаходжу захист в Нім. \nПречистою Він кров’ю мої гріхи обмив, \nНебесною любов’ю мене Він оживив.\n\nКуплет 3\nЯ є вівця Ісуса, - Він Пастир добрий мій;\nВін, в знак любві союзу, на вечері святій\nВзяв хліб, благословивши, апостолам роздав,\nПро смерть Свою відкривши, з вином їм чашу дав.\n\nКуплет 4\nЯ є вівця Ісуса, - Він Пастир добрий мій,\nЙому я віддаюся, — Він є Спаситель мій...\nВін душу наповняє любві вином святим,\nХліб з неба посилає, і я кріплюся Ним.', '', '', 'ua', NULL, 0, NULL, NULL),
(687, 168, 'Вже чую я шум', 0, 'Куплет 1\nВже чую я шум, наче шум той води,\nІ стогін людей від безсилля...\nГотуйся, Невісто! Жених твій іде!\nВже скоро вечеря весільна.\n\nПриспів: \nПрийди, о Спасителю мій дорогий:\nЯ можу вже бути з Тобою!\nМене обілив Ти у крові святій,\nКупив дорогою ціною.\n\nКуплет 2\nЗабудь про усе, чим світ вабив тебе,\nМарні залиши вже бажання;\nЗгадай, як Збавитель твій любить тебе;\nЗа тебе терпів Він страждання.\n\nКуплет 3\nЛюби, як Спаситель тебе полюбив,\nРадій же та будь Йому вірна!\nЗгадай, як Господь твій тобі все простив,\nІди за Ісусом покірно!\n\nКуплет 4\nО, вір, що навік Він тебе полюбив,\nО, вір, що Він любить незмінно,\nЩо вище і глибше всіх гір і морів \nЛюбов Його вічна, безмірна!', '', '', 'ua', NULL, 0, NULL, NULL),
(688, 169, 'Христос Господь у Галилеї', 0, 'Куплет 1\nХристос Господь у Галилеї \nНа шлюб у Кану приходив,\nСвятою силою Своєю \nТам перше чудо Він звершив.\n\nПриспів:\nО, Господи, (Господи) до нас прийди (Ти прийди)\nI славу Свою яви,\nО, Г осподи, (Г осподи) до нас прийди (Ти прийди)\nІ нас благослови!\n\nКуплет 2\nПрийди до нас, як Гість небесний,\nІ Сам цей шлюб благослови,- \nСкріпи союз у славі й честі,\nЩоб жили в вірності й любві!\n\nКуплет 3\nСоюз подружжя закріпляєш...\nВ живій Ти Церкві, як Жених;\nНа шлюбі вірних Ти буваєш \nПоміж відкуплених Твоїх.\n\nКуплет 4\nТи всіх зовеш на свято славне...\nБлагаєм ми, щоб і вони \nЖили для Тебе свято, вірно \nВ Твоїй любові по всі дні.\n\nКуплет 5\nІ Ти невісту вибираєш\nЗ людей відкуплених Своїх,\nЛюбов Свою їй відкриваєш,\nНевісті-Церкві, як Жених.\n\nКуплет 6\nНемає щастя на цім світі \nБез Твого світлого лиця;\nО, поможи їм - Твоїм дітям \nПрожити вірно до кінця!', '', '', 'ua', NULL, 0, NULL, NULL),
(689, 170, 'Христа хай величають всі', 0, 'Куплет 1\nХриста хай величають всі, | і ангели в красі (2р.) \nХвалу Йому хай принесуть.\n\nПриспів: \nПрославте (4р.),\nПрославте Бога сил!\n\nКуплет 2\nІ ви, страдальці за Христа, звіщайте всім життя, (2р.) \nЦаря царів прославте всі!\n\nКуплет 3\nТи, Богом вибраний народ, | стомився від скорбот, (2р.) \nПрослав, і Він тебе спасе!\n\nКуплет 4\nНароди, люди, племена, | всі, як сім’я одна, (2р.) \nХриста хай славлять за любов!', '', '', 'ua', NULL, 0, NULL, NULL),
(690, 171, 'Дай Боже їм щастя', 0, 'Куплет 1\nДай, Боже, їм щастя, у всім помагай,\nВід бур, від нещастя, від зла захищай. (2р.)\n\nКуплет 2\nВ житті хай з Тобою вони проживуть.\nІ світло любові всім ближнім несуть. (2р.)\n\nКуплет 3\nХай міцно з’єднає їх щира любов,\nВ час горя втішає серця знов і знов. (2р.)\n\nКуплет 4\nДай, Боже, їм мудрість, щоб вірні були,\nДаруй Твою тихість, щоб свято жили. (2р.)\n\nКуплет 5\nДай їм пізнавати, що з ними Твій Дух,\nПовік пам’ятати, що Ти — вірний Друг! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(691, 172, 'Дві руки в цей час з’єднались', 0, 'Куплет 1\nДві руки в цей час з’єднались для життя, надій і втіх.\nБоже вічний, Боже милий, Сам благослови Ти їх!\nДвоє уст тепер сказали перед Богом «Так» святе, \nЖити вірно обіцяли на усе життя своє.\n\nКуплет 2\nДві душі віднині стали у любові разом жить.\nЩоб і щастя, горе, й жалі поміж себе все ділить.\nБоже наш, Тебе благаєм: дай щасливе їм життя, - \nТвоя воля хай з’єднає їх на многії літа!\n\nКуплет 3\nПідкріпляй їх, Боже милий, в горю їх не залишай,\nІ Святого Духа силу завжди Ти їм посилай.\nХай вони уже віднині в згоді, в радості живуть,\nБоже, у земній долині Сам Заступником їм будь!', '', '', 'ua', NULL, 0, NULL, NULL),
(692, 173, 'Де Божий Дух в серцях', 0, 'Куплет 1\nДе Божий Дух в серцях живе, там радість, щастя, мир, \nЛюбов там близьких обійме, -примирить ворогів.\n\nПриспів: \nТвою любов, Господь, пошли,\nЛюбов’ю всіх нас освіти,\nНавчи любить Ім’я Твоє \nІ прославляти лиш Тебе.\n\nКуплет 2\nДе Божа лиш любов горить, там єдність, там спокій,\nТам вірних Бог не залишить, - Він Пастир дорогий;\n\nКуплет 3\nДе всі живуть в любві святій - в громаді чи в рідні, \nЇх супроводить Бог живий, щасливі там усі.', '', '', 'ua', NULL, 0, NULL, NULL),
(693, 174, 'Даруй Боже святість', 0, 'Куплет 1\nДаруй, Боже, святість, пошли тихість, страх,\nДля всього дай мудрість, будь в наших серцях. \nПобільшуй в нас віру, чуття обнови, \nІзлий любов щиру, сумнів віддали!\n\nКуплет 2\nНавчи бути вдячним за милість Твою,\nСтремлінням сердечним дай силу Свою.\nВ хвилину страждання дай сльози мені,\nЩоб щирі благання приносив Тобі!\n\nКуплет 3\nДай чисте лиш серце, духовно зрости,\nІ світлом небесним мій дух освіти.\nНавчи приклад брати в житті від Тебе,\nНавчи прославляти ім’я лиш Твоє!', '', '', 'ua', NULL, 0, NULL, NULL),
(694, 175, 'Ти думками йдеш до неба', 0, 'Куплет 1\nТи думками йдеш до неба... Що ж про діток ти забув?\nВони ж прагнуть життя-хліба; ти у Слові теє чув. Приспів:\n\nКуплет 2\nО, батьки! Ви своїх діток, тих, що Бог вам дарував,\nПриведіте до Ісуса, бо й за них Він постраждав.\n\nКуплет 3\nТи сидиш в Господнім Домі, веселишся у Христі,- \nДітки ж бідні у Содомі... Чи байдуже це тобі?\n\nКуплет 4\nЧом не видно їх з тобою? На кого їх залишив?\nСпас ласкавою рукою тут би їх благословив.\n\nКуплет 4\nЇм ласкавий Відкупитель Царство Боже обіцяв. \nПриведи ж їх до Ісуса, щоб Він світлом осіяв!', '', '', 'ua', NULL, 0, NULL, NULL),
(695, 176, 'Закликає Спас діток', 0, 'Куплет 1\nЗакликає Спас діток, кличе їх до Себе всіх;\nВін збирає їх в гурток, любить Він, хоронить їх.\n\nПриспів:\nКличе всіх Ісус діток, кличе Він, кличе Він.\nВ вічний райський Свій садок, де немає перемін.\n\nКуплет 2\nМолоді серця свої зберігайте в чистоті,\nНепорочні хай уста прославляють лиш Христа.\n\nКуплет 3\nДітки, всі до одного вчуйте заклик ви Його - \nТож Спаситель кличе вас. Поспішайте в той же час.', '', '', 'ua', NULL, 0, NULL, NULL),
(696, 177, 'Слава На Сіонгорі', 0, 'Куплет 1\n«Слава!» - На Сіон-горі дітки кликали тоді,\nЯк в’їздив у місто Спас; тож і нині кликнім враз:\n\nПриспів: \nВикликуйте: Благословен Спас!\nКличте всі, хай кожний чує вас:\nСлава в вишніх! (Зр.) - Спас іде!\n\nКуплет 2\nСлів Христових вчили нас; Духа втіхи дав нам Спас.\nМи до неба маєм шлях. Спас живе у нас в серцях.\n\nКуплет 3\nСтарші і молодші - всі, заспіваймо враз пісні,\'\nХай наш спів до хмар злетить, в небесах загомонить.', '', '', 'ua', NULL, 0, NULL, NULL),
(697, 178, 'Малих Бог любить пташечок', 0, 'Куплет 1\nМалих Бог любить пташечок і їжу їм дає...\nПро всі істоти дбає Бог, - Він любить і мене.\n\nПриспів: \nТак, любить Бог, так, любить Бог,\nЯ знаю, - любить Він;\nДіток маленьких любить Бог,\nВін любить і мене.\n\nКуплет 2\nБог любить лілеї в полях, де річенька тече;\nКоли Він любить квіточки, - Він любить і мене.\n\nКуплет 3\nГосподь пташкам і квіточкам життя й красу дає, \nВін дбає про малих дітей, Він любить і мене.', '', '', 'ua', NULL, 0, NULL, NULL),
(698, 179, 'Книгу Божу маю я', 0, 'Куплет 1\nКнигу Божу маю я, хоч поношена вона...\nДні пригадую давно минулії;\nМоя мама там знайшла дар спасіння у Христа.\nНе забуду я щасливих тих хвилин!\n\nПриспів: \nО, чудова, найдорожча Книга Божа!\nЯ люблю, люблю тебе: Ти зблудити не даєш, \nВ Царство Боже нас ведеш,\nВ Край, куди прийме Господь вас і мене!\n\nКуплет 2\nПам’ятаю: про Христа все читала мама там,\nЯк любив, страждав, вмирав Він на хресті.\nЯ уважно слухав все...\"Пам’ятай, то за тебе,-\nГоворила мама: — Ти Його люби!\"\n\nКуплет3\nТе давно-давно я чув, але слів тих не забув.\nІ мені та Книга світлом є в житті.\nЯ слова Христа люблю, все вперед за Ним іду, \nЩоб до щастя вічного життя дійти.', '', '', 'ua', NULL, 0, NULL, NULL),
(699, 180, 'О дітки ідіте', 0, 'Куплет 1\nО, дітки, ідіте, ідіть же скоріш,\nДо Спаса усі поспішайте мерщій:\nЗоря освітила ніч темну з небес, \nДала знак про дивнеє чудо з небес!\n\nКуплет 2\nПогляньте, як в яслах Спаситель лежить:\nНебесна в Нім святість, мов світло горить.\nНебесне Дитятко — краса на весь світ,\nЙому хори ангельські шлють всі привіт.\n\nКуплет 3\nО, дітки, для вас Він у яслах лежить;\nМарія і Иосиф Ісуса глядять...\nПочувши від ангелів вістку святу,\nПрийшли пастухи поклонитись Христу.', '', '', 'ua', NULL, 0, NULL, NULL),
(700, 181, 'Прийде знову', 0, 'Куплет 1\nПрийде знову, прийде знову, на землю Спаситель, - \nЗбере перли найдорожчі - маленьких діток.\n\nПриспів: \nНіби ясні ті зірки, що вночі в небі сяють,\nТак і дітки засяють в Царстві Христовім.\n\nКуплет 2\nЇх Спаситель позбирає у Край Свій небесний,\nВід землі візьме Він діток всіх любих Своїх.\n\nКуплет 3\nХто із діток щирим серцем Спасителя любить,\nТі, як перли-самоцвіти, засяють у небі.', '', '', 'ua', NULL, 0, NULL, NULL),
(701, 182, 'При Божім троні', 0, 'Куплет 1\nПри Божім троні в небесах зібрались діточки;.\nСпівають радісні пісні, ясніють, як зірки.\n\nПриспів: \nІ там (і там, і там) (2р.)\nРадіють у Христі;\nІ там (і там, і там) (2р.)\nСпівають Йому всі \n(Слава Господу повік, повік).\n\nКуплет 2\nТа хто ж у небо їх привів - в світ Божої любві?\nІ як туди, де вічний мир, вони, малі, ввійшли?\n\nКуплет 3\nЗа них Спаситель кров пролив, щоб змити всякий гріх,\nЩоб і вони у небесах зазнали райських втіх,\n\nКуплет 4\nІ Божу ласку всі вони прийняли на землі,\nТому тепер лице Христа так близько бачать всі.', '', '', 'ua', NULL, 0, NULL, NULL),
(702, 183, 'Дітки на діло', 30, 'Куплет 1\nДітки! На діло ревно і сміло \nВсі, як один, поспішім,\nПро відкуплення, вічне спасіння \nЛюдям усім розкажім. (2р.)\n\nПриспів:\nБудем трудитись, будем молитись,\nБога усі прославлять.\nЗа кров невинну будем постійно \nХриста усі величать. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(703, 184, 'Стою біля Йордана', 0, 'Куплет 1\nСтою біля Йордана я і бачу впереді \nОбітований вічний Край, де думи всі мої.\n\nПриспів: \nТам спочнем, друззя, навік \nЗ Христом (близький час)\nВ світлі берега, де всі святі (всі святі),\nЗ ними пісню заспіваєм ми, (близький час) \nІз Ісусом вічно будем ми.\n\nКуплет 2\nВ небеснім тім Краю горить яскраве світло дня:\nТам Божий Син в любві царить, у славі все сія.\n\nКуплет 3\nКоли ж і я ввійду в той Край, де радість і спокій,\nДе вічне щастя, Божий рай, де Відкупитель мій?\n\nКуплет 4\nХоч грізні хвилі навкруги, я все ж туди пливу,\nДе вічні Божі береги, - я там спокій знайду.', '', '', 'ua', NULL, 0, NULL, NULL),
(704, 185, 'За днями линуть дні', 0, 'Куплет 1\nЗа днями линуть дні, все ближче Край!\nІ думка все моя - все ближче Край!\nВже скоро буду я у рідній стороні.\nВсе ближче рідний Край, все ближче Край!\n\nКуплет 2\nМинають мої дні, - все ближче Край!\nДо Господа я йду, - все ближче Край!\nТам чуть святих пісні, і я туди прийду. \nВсе ближче рідний Край, все ближче Край!\n\nКуплет 3\nСкінчу я шлях земний, - все ближче Край!\nІ горе все скінчу, - все ближче Край!\nВід суму і плачу піду я в край Святий; \nВсе ближче рідний Край, все ближче Край!', '', '', 'ua', NULL, 0, NULL, NULL),
(705, 186, 'І буде Божі діти встануть', 0, 'Куплет 1\nІ буде: Божі діти встануть,\nУсі зберуться до Христа,- \nВ нетлінній славі засіяють,\nПоллється пісня їх свята,\n\nКуплет 2\nСтарі, і молоді, і діти, \nЗодягнені усі в виссон,\nТам будуть Бога прославляти,\nКоли зберуться на Сіон.\n\nКуплет 3\nГосподь: усіх ласкаво прийме \nСвоїх улюблених дітей,\nНеславу від людей з них здійме \nІ сльози обітре з очей.\n\nКуплет 4\nТам вже ніхто ні мук, ні болю \nНе нанесе ніколи їм,\nІ хто томився тут в неволі,\nВвійде в небесний супокій.\n\nКуплет 5\nНе буде й тіні там страждання,\nІ смерть повіки не прийде, \nІ світло Божого проміння \nНе потемніє, не зайде.\n\nКуплет 6\nВони, як зорі, засіяють \nВ небесній славі і красі;\nБлаженства вічного дізнають \nВ Христовім Царстві вірні всі.', '', '', 'ua', NULL, 0, NULL, NULL),
(706, 187, 'Ми знаєм про Край', 0, 'Куплет 1\nМи знаєм про Край, де царює Спаситель,\nІ місто збудоване Богом для нас;\nХристос приготовив для нас там оселі,\nТам щастям наділить відкуплених Спас.\n\nПриспів: \nРайське нам щастя,\n(Райське нам щастя Голгофа дає),\nРайську нам радість \n(Райська нам радість з Голгофи тече), \nКров’ю святою Спаситель придбав. \n(Куплені кров’ю ми Агнця, \nприносим Христові подяку за все).\nАлілуя! Божий Син відкрив двері раю. \nСлава Христу, (слава навіки Ісусу Христу!), \nВін від смерті нас спас.\n\nКуплет 2\nАпостоли, вірні й святії пророки,\nУсі там спасенні з Ним вічно живуть;\nІ ми перейдемо у край той навіки,\nДе душі в спокою і сліз вже не ллють;\n\nКуплет 3\nТут в світі панують лукаві бажання,\nА наша душа прагне щастя й життя.\nО, браття і сестри, вперед без вагання! \nГотуймось у вічнеє, Царство Христа!', '', '', 'ua', NULL, 0, NULL, NULL),
(707, 188, 'Де будеш в вічності', 0, 'Куплет 1\nДе будеш в вічності ти жить?\nПодумав ти про це чи ні? \nПитання це для нас усіх:\nДе будеш в вічності ти жить?\n\nПриспів: \nО, вічність, вічність без кінця ! \nДе будеш в вічності ти жить?\n\nКуплет 2\nВже многі до Христа прийшли,\nГріху покинули служить;\nЖиття і щастя в Нім знайшли...\nДе будеш в вічності ти жить?\n\nКуплет 3\nЯке життя ти тут ведеш?\nТи ж можеш Богові служить! \nЯкий кінець тебе там жде, - \nДе будеш в вічності ти жить?\n\nКуплет 4\nО, друже мій, у той же час \nХристу віддайсь: тебе Він спас, - \nІ поспішай усім звістить:\n«З Ним буду в вічності я жить!»', '', '', 'ua', NULL, 0, NULL, NULL),
(708, 189, 'Радісно радісно', 0, 'Куплет 1\nРадісно, радісно в путь я іду,\nДе відпочинок навіки знайду;\nПуть той Спаситель відкрив Сам мені,\nМій відпочинок в Ісусі Христі.\nСкоро проходять земні мої дні...\nПрацю закінчу, піду я туди, \nДе вже не буде ні смерті, ні сліз:\nСмерть наш Спаситель уже переміг.\n\nКуплет 2\nВ вічних оселях, в святих небесах \nВсі ми прославим Ісуса Христа;\nСпів наш поллється з цілої душі...\nБрате наш любий, і ти поспіши!\nСпіви солодкі там дивно звучать,\nХвилями радості в серце пливуть.\nЗвуки небесні наповнюють рай,\nКличуть ласкаво в небесний той Край, -\n\nКуплет 3\nВ край, де повіки з Христом будеш жить,\nВічно за жертву спасіння хвалить!\nТам ми забудем турботи земні,\nБудемо жити в Христовій любві.\nВічності ранок там ясно зійде,\nСмерті не буде, і горе пройде.\nБогові буду співати хвалу .\nРадісно в вічнім небеснім Краю.', '', '', 'ua', NULL, 0, NULL, NULL),
(709, 190, 'Чи зустрінемось з тобою', 0, 'Куплет 1\nЧи зустрінемось з тобою, де святі усі живуть,\nДе спокійною рікою води чистії течуть?\n\nПриспів:\nТак, зустрінемось з тобою\nНад світлою, чудовою рікою,\nТам усі з достойною хвалою \nМи Ісусові будем служить.\n\nКуплет 2\nПоміж нами і рікою смертна пропасть ще була, - \nБожий Син ціною крові путь спасіння нам проклав.\n\nКуплет 3\nТам над світлою рікою ми Христа побачим всі, - \nЗалунає спів хвалою в вічній радості-красі.\n\nКуплет 4\nТам зусрінемось з тобою, де спокій і благодать,\nТам ми будем над рікою вічно Бога прославлять.', '', '', 'ua', NULL, 0, NULL, NULL),
(710, 191, 'Несем ми тіло на спокій', 0, 'Куплет 1\nНесем ми тіло на спокій,\nСхоронимо його в землі;\nБог всіх на смерть приговорив,\nУ гріх упавших осудив...\n\nКуплет 2\nО, браття й сестри, всі туди \nВ свій час ми маєм відійти;\nТурботам всім прийде кінець,\nПокличе в вічність нас Творець...\n\nКуплет 3\nЯк скоро день за днем летить!..\nЖиття, мов хвиля, пробіжить, - \nЧи близько, чи далеко час...\nЩо в вічності чекає нас?\n\nКуплет 4\nБог відграничив тут наш вік,\nДе смертний кожен чоловік...\nХристос смерть смертю подолав,\nЖиття нам вічне дарував.', '', '', 'ua', NULL, 0, NULL, NULL),
(711, 192, 'Повний благості', 0, 'Приспів: \nПовний благості, повний радості \nНам день Христового Різдва.\n\nКуплет 1\nСвіт в гріхах томився, Спас нам народився, \nЗадля нас зійшов, - Йому хвала!\n\nКуплет 2\nАнгели злетіли, співами звістили:\nСлава в небі, спокій між людьми!\n\nКуплет 3\nНам родивсь Спаситель,- Вічний Примиритель. \nРадуйтеся, славте всі Христа!', '', '', 'ua', NULL, 0, NULL, NULL),
(712, 193, 'Вістку ангельську прийми', 0, 'Куплет 1\nЗвістку ангельську прийми: народився Цар землі!\nЗ неба Він до нас зійшов,\nЩоб ти в Нім спокій знайшов.\nВсі народи, пробудіться!\nВже пора всім примириться!\nПрославляйте всі Отця, - неба і землі Творця!\n\nПриспів: \nВістку ангельську прийми!\nНародився Цар землі.\n\nКуплет 2\nПрославляймо всі Його:\nЦар Христос - Предвічний Бог.\nВін від Діви народивсь,\nДо нас грішних Спас явивсь.\nБожий Син став Чоловіком,\nЯк призначено від віку:\nСин Творця небесних сил, Спас Ісус Еммануїл!\n\nКуплет 3\nВірні шлють Христу привіт:\nВ тілі Бог прийшов на світ;\nСвітло Правди Він відкрив,\nНарід з Богом примирив;\nЗалишив небесну славу,\nСмерті переміг державу, - \nНародивсь, щоб нас піднять,\nЗвиш народження нам дать.', '', '', 'ua', NULL, 0, NULL, NULL),
(713, 194, 'Ось Спаситель на землю зійшов', 0, 'Куплет 1\nОсь, Спаситель на землю зійшов,\nНаше тіло на Себе прийняв.\nЗа оселю Він ясла обрав:\nЛюдиною в цей світ прийшов.\n\nПриспів: \nСлава! (слава) Христу! (слава),\nСлава (Зр.) Христу! (славу,\nМир і радість нам всім Він приніс). (2р.)\n\nКуплет 2\nСам Син Божий на землю прийшов,\nНе в пошані, не в царськім вінці,\nНе в палацах, не в пишнім вбранні, - \nВ бідних яслах Він місце знайшов.\n\nКуплет 3\nЦар Небесний до нас Сам прийшов,\nЩоб з Творцем нас, людей, примирить;\nЗ нами хоче повіки Він жить,\nОб’явивши небесну любов.', '', '', 'ua', NULL, 0, NULL, NULL),
(714, 195, 'Нині всі вірні Христа прославляють', 0, 'Куплет 1\nНині всі вірні Христа прославляють.\nСили небесні Ісуса вітають:\n«Спас народився! - звіщають в хвалі,\nСлава Богу в небі, мир на землі!»\n\nПриспів:\nСлава, слава, (слава Богу в небі, мир на землі)\nСлава Богу в небі, мир на землі!\nСлава, слава, (Цар народився Христос, Господь)\nЦар народився Христос!\n\nКуплет 2\nХристос родився, - радійте душею!\nПсалми хваління хай ллються рікою;\nВірні, співайте Творцеві в хвалі:\n«Слава Богу в небі, мир на землі!»\n\nКуплет 3\nЗірка небесна вказала Дорогу \nТрьом мудрецям, що вклонилися Богу: \nЦінних принесли Ісусу дарів, -\nЗнали, що є те Дитя - Цар царів.\n\nКуплет 4\nІрод почув, що Христос народився,\nВ заздріснім серці своїм розлютився,\nТайно Дитятко убити рішив,\nДе Спас родився, шукати велів.\n\nКуплет 5\nЙосифові сон від Бога приснився:\nІрод шукати Ісуса рішився, - \nРано візьми ж ти Марію й Дитя,\nАж у Єгипті спасай їх життя!\n\nКуплет 6\nІрод з військами діток побиває, - \nМати з Дитятком в Єгипет вступає;\nДивно спаслося Предвічне Дитя, -  \nЩоб нам, всім людям, принести життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(715, 196, 'Хто у бідних яслах', 0, 'Куплет 1\nХто у бідних яслах спить? Там чиє Дитя лежить?\nТо - Господь, Христос-Спаситель, Божий Син, наш\nВідкупитель.\n\nПриспів: \nМи до Нього всі прийдім,\nІ склонімся перед Ним!\n\nКуплет 2\nХто там нарід науча, то Чиї слова звучать?\nДо Кого слабих несуть та сліпих, кривих ведуть?\n\nКуплет 3\nХто там, плачучи, стоїть, де сном смерті Лазар спить?\nВ честь Кого лунає спів? До Кого біжать з домів?\n\nКуплет 4\nХто в саду припав лицем, молиться перед Отцем?\nХто так на хресті терпів? Хто смерть смертю переміг?\n\nКуплет 5\nХто воскрес, щоб оживлять, мертвих до життя піднять? \nХто весь круг земний держить, хто Вселенну всю глядить?', '', '', 'ua', NULL, 0, NULL, NULL),
(716, 197, 'Для мене мій Спаситель', 0, 'Куплет 1\nДля мене мій Спаситель зійшов з святих небес,\nВін залишив всю славу - Небесний Край чудес.\n\nПриспів:\nЗа мене Ти (так, за мене, за мене Спаситель) \nПрийняв Голгофський хрест,\nХвала Тобі (хвала Тобі, о мій Відкупитель),\nХвала Тобі і честь!\n\nКуплет 2\nДля мене мій Спаситель у яслах народивсь;\nСин Божий, Примиритель, в любві до нас явивсь.\n\nКуплет 3\nСпасителя любов’ю моя душа живе.\nО, Спасе за Тобою серце стремить моє.\n\nКуплет 4\nБажаю відпочити я лиш в Тобі Однім.\nДай свято, чисто жити, - в серці царюй моїм!', '', '', 'ua', NULL, 0, NULL, NULL),
(717, 198, 'Пастухи в полях дрімали', 0, 'Куплет 1\nПастухи в полях дрімали... Ось проміння засіяло, \nДивне сяйво із небес, - сталось чудо із чудес:\nАнгел Божий прилітає, -\n«О, не бійтесь! - їм звіщає, -\nЯ від Бога вам приніс нині радісную вість:\n\nКуплет  2\nВ місті древньому Давида, без величності і виду, \nВідкупитель народивсь, в яслах, як дитя, смиривсь. \nТвердо вірте, не страшіться,\nУ Христі всі веселіться:\nБожий Син до вас прийшов, проявіть свою любов.\n\nКуплет  3\nО, не тратьте віри, люди!\nЦар Всесвіту з вами всюди:\nХто у яслах тут лежить, грізні бурі усмирить:\nЛюдям, що живуть в темряві, засіяє світло слави,\nІ до Нього хто прийде, вічну радість в Нім знайде».', '', '', 'ua', NULL, 0, NULL, NULL),
(718, 199, 'Браття всі радійте', 0, 'Куплет 1\nБраття, всі радійте, - славний день настав,\nСестри, веселіться, - Бог нам радість дав!\nМи були чужими, а тепер - друззя:\nМи всі з’единились кровію Христа.\n\nПриспів: \nВсі співайте «Алілуя!»\n(Всі співайте «Алілуя!»2р.),\nБог нас спас і оправдав \n(Бог нас спас і оправдав! 2р.)\nНаші імена навіки \n(Наші імена навіки 2р.)\nВ життя книгу записав\n(В життя книгу записав, навіки записав).\n\nКуплет 2\nНе закон Сінайський - заповіт старий,\nЩо прийняв Ізраїль на святій горі,\nА слова ми чуєм Господа Христа:\nГрішників спасає благодать свята.\n\nКуплет 3\nМи живем в надії, вірі і любві,\nВід гріхів обмились у святій крові.\nДух Господній тішить, веселить серця.\nБудьмо, браття-сестри, вірні до кінця!', '', '', 'ua', NULL, 0, NULL, NULL),
(719, 200, 'Христос воскрес із мертвих', 0, 'Куплет 1\nХристос воскрес із мертвих,\nСмертю смерть подолав, -\n І тим, що у гробах, життя дарував! Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(720, 201, 'Радість з неба сяє', 0, 'Куплет 1\nХристос Воскрес! (2р.)\nРадість з неба сяє ясна, завітала Пасха красна;\nВсі радіймо щиро нині, Бог дав щастя всій родині;\nБог дав радість нам з небес: | Христос Воскрес! (2р.)\n\nКуплет  2\nХристос воскрес! (2р.)\nМир нам Сам Христос приносить,\nМир нам небо днесь голосить,\nМир той Божий всі вітаймо, -\nБожу Пасху споминаймо, -\nБоже чудо всіх чудес: І Христос Воскрес! (2р.)\n\nКуплет  3\nХристос Воскрес! (2р.)\nГімн апостоли співають, жах і смуток забувають; \nСлово Боже всім голосять і спасіння їм приносять,- \nА спасіння йде з небес: | Христос Воскрес! (2р.)\n\nКуплет  4\nХристос Воскрес! (2р.) В Божій правді просвітімся,\nВ Божій правді звеселімся;\nЩезла вже страшна недоля, завітала краща доля - \nБожа благодать з небес: | Христос Воскрес! (2р.)\n\nКуплет  5\nХристос Воскрес! (2р.)\nРадуйтеся, Божі люди, хай між вами згода буде, - \nХай зросте в нас любов Божа,\nЯк барвиста квітка рожа.\nТа любов прийшла з небес: | Христос Воскрес! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(721, 202, 'Як сонце в небі засіяло', 0, 'Куплет 1\nЯк сонце в небі засіяло,\nХристос Спаситель наш Воскрес;\nХвилина дивная настала, - \nЗвершилось чудо із чудес!\nХристос Воскрес із мертвих!\n\nКуплет 2\nХристос Воскрес! Усім спасіння \nВін воскресінням показав;\nХристос Воскрес ! Гріхів прощення \nИ життя нам вічне дарував.\nХристос Воскрес із мертвих!\n\nКуплет 3\nВоскресла радісна надія,\nУ серці мир, - Христос Воскрес!\nІду до Тебе я з хвалінням,\nМій захист, Цар, Творець чудес!\nХристос Воскрес із мертвих!', '', '', 'ua', NULL, 0, NULL, NULL),
(722, 203, 'У гробі Він лежав', 0, 'Куплет 1\nУ гробі Він лежав - Христос Спаситель, \nДня слави дожидав Ісус Господь.\n\nПриспів: \nІз гробу Він устав (Він устав),\nВсі ворожі сили подолав, (подолав),\nВін Воскрес, Воскрес, —\nСмерть смертю переміг.\nІ всім вірним Царство Вічне дарував.\nВін Воскрес (Він Воскрес)! (2р.)\nАлілуя! Він Воскрес!\n\nКуплет 2\nНамарно сторожать Христа у гробі;\nНащо кладуть печать?! Ісус - Господь!\n\nКуплет 3\nХристос Смерть подолав, Воскрес у славі, \nЖиття нам дарував, Ісус Господь.', '', '', 'ua', NULL, 1, '2021-04-04', NULL),
(723, 204, 'О яку радість вірним', 0, 'Куплет 1\nО, яку вірним радість велику Бог дав:\nПута смерті Христос розв’язав,\nТемні сили ворожі Господь переміг \nІ народ Свій з гріхів увільнив.\n\nПриспів:\nВ Нім, лиш в Нім, радість в Нім,\nВ Нім вічне життя і любві повнота (повнота),\nВсі серця хай прославлять Христа (лиш Христа)! (2р.)\n\nКуплет 2\nУже наше спасіння Спаситель звершив,\nІ навік смертю смерть подолав.\nХай радіють всі люди і сили небес:\nНаш Спаситель із мертвих Воскрес!\n\nКуплет 3\nВ воскресінні Його — оправдання для всіх, \nВоскресінням Його стерто гріх,\nВоскресінням Своїм переміг силу зла,\nХай лунає Йому честь, хвала!\n\nКуплет 4\nНаш Господь і Спаситель у гробі лежав,\nВін Воскрес, — перемогу здобув.\nНе намарно божественну кров Він пролив:\nВін нас з Богом навік примирив.\n\nКуплет 5\nХай живе Воскресіння Христове в серцях: \nЗникнуть всякі сумніви і страх.  \nВін воскрес, морок ночі навіки вже щез. \nВін воістину в славі Воскрес!', '', '', 'ua', NULL, 0, NULL, NULL),
(724, 205, 'Христос Воскрес', 0, 'Куплет 1\nХристос (Воскрес)! (2р.) О радість, радість нам! \nХристос (Воскрес)! (2р.) Кінець журбі й сльозам. \nХристос (Воскрес)! Христос (Воскрес)!\nСмерть смертю подолав і нам спасіння вічне дав.\n\nКуплет 2\nЙого злочинців руки на древірозп’яли,\nЗа нас тяжкії муки терпів Він у любві.\nПречиста кров лилася із ніг, рук і чола... \nЗвершилось все, - Йому хвала!\n\nКуплет 3\nЗ Ариматеї Иосиф Пилата ублагав,\nЗ хреста щоб зняти тіло, - і зняв, і поховав \nВ саду, у новім гробі... Та сонце лиш зійшло,\nХриста вже в гробі не було.\n\nКуплет 4\nДо гробу дуже рано Марія вже прийшла \nІ тіла там нежданно вона вже не знайшла... \nЯвивсь їй ангел з неба і радісно сказав:\n- Христос уже із мертвих встав!\n\nКуплет 5\nСхвильована Марія не стримала ридань...\nАж їй у яснім світлі Христос явився Сам...\n- Учитель мій! - сказала, упавши перед Ним, - \nЙ про чудо сповістила всім..', '', '', 'ua', NULL, 0, NULL, NULL),
(725, 206, 'Любив Ісуса Йосиф', 0, 'Куплет 1\nЛюбив Ісуса Йосиф щиро:\nПречисте тіло зняв з хреста,\nІ полотном обвив він чистим,\nУ гробі поховав Христа.\nВорожі сили не змовкали,\nБоялись, що Він може встать; \nВони негайно наказали \nДо гробу приложить печать.\n\nКуплет 2\nЯк тільки стало розсвітати,\nЖінки до гробу вже спішать.\nІ ось два мужі в білих шатах \nВже там на камені сидять.\nНебесні слуги в Божій силі \nКамінь відкинули, і враз \nВорожу ту печать зломили, - \nХристос Воскрес - о, дивний час!\n\nКуплет 3\nЖінки до гробу приступають і бачать чудо із чудес. \nІ ангели у них питають:\n- Кого шукаєте? - Воскрес!\nЖінки у радості вертають,\nЗвістить апостолам спішать, - \nПро чудо їм оповідають:\n- Христос Воскрес! - благовістять.', '', '', 'ua', NULL, 0, NULL, NULL),
(726, 207, 'Ідіть розкажіте Христовим друзям', 0, 'Куплет 1\nІдіть, розкажіте Христовим друзям:\nВоскрес Він із гробу, нема Його там!\nНебесний Учитель їм явиться знов; - \nПовернеться радість, поверне любов.\n\nПриспів:\nСкажіте: Христос вже із мертвих воскрес, \nСкажіте всім ближнім: Син Божий Воскрес!\n\nКуплет 2\nНесіть же ту вістку скорботним серцям:\nУтішити хоче Спаситель їх Сам;\nУсім, хто страждає і сльози тут ллє,\nНебесную радість Спаситель дає.\n\nКуплет 3\nУсім засвідкуйте про милість Христа,\nБо Він відкупив нас - дарує життя;\nВоскрес Він із мертвих, щоб нас оправдать,\nДітей Своїх вірних із мертвих піднять.\n\nКуплет 4\nНе за серафимів Спаситель страждав, - \nЗа грішних людей Божий Син умирав.\nВоскрес Він у славі і смерть подолав,\nІ грішних нас з Богом навік примирив.', '', '', 'ua', NULL, 0, NULL, NULL),
(727, 208, 'Христа Творця святих чудес', 0, 'Куплет 1\nХриста - Творця святих чудес \nПрославте всі сердечним співом.\nРадійте всі! Звершилось диво: | Христос Воскрес! (2р.)\n\nКуплет 2\nХвала, хвала! Христос Воскрес!\nЖиття! У грудях серце б’ється...\nТепер усюди пісня ллється: І Христос Воскрес! (2р.)\n\nКуплет 3\nПо всьому світу до небес \nХвала Творцеві щира ллється.\nСпів радісний нехай несеться: | Христос Воскрес! (2р.)\n\nКуплет 4\nТобі, Спаситель - Божий Син,\nТобі і слава, і хваління,\nПодяка, честь і поклоніння повіки вічнії! Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(728, 209, 'Зарожевів вже схід небес', 0, 'Куплет 1\nЗарожевів вже схід небес, - \nХристос Спаситель наш Воскрес \nВін гріх-темряву розігнав,\nСпасіння людям дарував.\n\nПриспів: \nУ гробі вже Христос лежав,\nНа третій день Він з мертвих встав. \nСмерть не могла вдержать Його - \nЦаря царів - Творця всього.\n\nКуплет 2\nСпаситель мій, Ти ворогів -\nЗлі, темні сили подолав,\nВже каменя з грудей Ти зняв,\nІ милість я Твою пізнав.\n\nКуплет 3\nХристос Воскрес! - гріхи простив,\nМене Він з Богом примирив,\nВін в Царство вічне кличе нас,\nІ береже у кожний час.\n\nКуплет 4\nТвою любов і благодать,\nО, Спасе, будем прославлять\nТепер, і там у небесах,\nЗ святими в радісних піснях!', '', '', 'ua', NULL, 0, NULL, NULL),
(729, 210, 'О смерть Де скажи твоє жало', 0, 'Куплет 1\nО, смерть! Де, скажи, твоє жало?\nДе, пекло, звитяга твоя?\nВоскрес наш Господь! Засіяло \nВ Нім вічнеє сонце життя.\n\nПриспів: \nХристос Воскрес, - Смерть подолав,\nЩоб в людях міг Дух Божий жить.\nХристос Воскрес, щоб до життя \nНас, мертвих, з гробу воскресить.\nЯка нам радісна та вість! (2р.) \nХристос Воскрес! (2р.) Хвала Йому і честь!\n\nКуплет 2\nПогляньте: вже камінь від гробу \nВіднятий, і ангел з небес \nПромінням там сяє чудовим:\n«Ісуса ж нема: Він Воскрес!»\n\nКуплет 3\nВоскрес Він, щоб з серця людського \nГріховного каменя знять;\nВоскрес Він, щоб Духа Святого,\nЯк ангела в гріб, нам послать.\n\nКуплет 4\nВоскрес Він, щоб світлом спасіння \nЛюдей у пітьмі осіять;\nВоскрес Він, щоб в день Воскресіння \nВідкуплених в славі обнять.', '', '', 'ua', NULL, 0, NULL, NULL),
(730, 211, 'Радійте співайте і славте', 0, 'Куплет 1\nРадійте, співайте і славте \nОбмитії кров’ю Христа!\nВи пісню нову заспівайте \nТому, Хто вас спас від гріха.\n\nПриспів: \nРадійте, радійте,\nСпівайте і славте Христа!\n\nКуплет 2\nПрославмо Того, Хто на землю \nЗійшов, щоби нас оправдать. \nСпасти нас пречистою кров’ю \nІ щастя навіки нам дать.\n\nКуплет 3\nВін сили нам дасть й перемогу.\nЗ гріхом в боротьбі підкріпить, \nЛюбов’ю Своєю піддержить \nІ Духом Святим нас зміцнить.\n\nКуплет 4\nВсі радісним серцем співайте, \nВіддайте подяку тому,\nХто Сам заплатив за нас кров’ю.\nО, слава навіки Йому!', '', '', 'ua', NULL, 1, '2021-03-21', NULL),
(731, 212, 'Як овечку Пастир', 0, 'Куплет 1\nЯк овечку, Пастир сильний, Сам веди мене вперед! \nНа Твої луги просторі, - за Тобою я йду вслід,\nО, Ісус мій! О, Ісус мій! Ти за мене кров пролив.\n\nКуплет 2\nО, Спасителю незмінний, захищай нас, бережи:\nМи без Тебе всі безсильні, - у Своїх руках держи.\nО, Ісус мій! О, Ісус мій! Ти за мене постраждав.\n\nКуплет 3\nПрояви обітування, - в серце благодать зішли,\nЩирі вчуй мої благання і Твій мир мені пошли.\nО, Ісус мій! О, Ісус мій! Від спокус охороняй.\n\nКуплет 4\nДай, щоб серцем міг я вірно Твій лиш заповіт любить, \nБлижнім всім служити щиро; научи в любові жить.\nО, Ісус мій! О, Ісус мій! В моїм серці будь повік.', '', '', 'ua', NULL, 0, NULL, NULL),
(732, 213, 'Єдиний лікар є', 0, 'Куплет 1\nЄдиний лікар є для нас, - ласкавий наш Спаситель:\nВін ранами Своїми спас всіх вірних - наш Збавитель.\n\nПриспів:\nКращий скарб мені Ти дав: душу й тіло врятував, \nЩоб хвалу Тобі співав, мій Господь-Спаситель!\n\nКуплет 2\nВін всі гріхи мої простив, мій Лікар, мій Збавитель,\nВін дім Отця мені відкрив, - Ісус, наш Примиритель.\n\nКуплет 3\nЯ прагну щиро все любить Тебе, мій Відкупитель!\nТвоє ім’я люблю хвалить, Предвічний Цар, Спаситель!\n\nКуплет 4\nНедуг невиліковний твій Спаситель ізціляє;\nЙого могутність зрозумій: Він вірним помагає!\n\nКуплет 5\nПрославмо, браття, всі Христа, любов Його безмірну! \nХай славить серце і уста Господню милість дивну.', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(733, 214, 'В вічнім спасінні укрийся', 0, 'Куплет 1\nВ вічнім спасінні укрийся, навіть з великим трудом! \nКров’ю Ісуса обмийся, - ти обтяжений гріхом!\nДушу тривожить спокуса, - помочі жди від Ісуса;\nА в Нім знайдеш відпочинок,\nО, ти, обтяжений гріхом! (2р.)\n\nКуплет 2\nВін хоронить тебе буде і твій тягар понесе;\nІсус тебе не забуде, - сльози з очей Сам утре. \nБачить твої Він страждання,\nВсі заспокоїть зітхання,\nПлач віддалить та ридання, - \nВсі сльози з очей Сам утре. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(734, 215, 'Побачу нове небо й землю', 0, 'Куплет 1\nПобачу нове небо й землю по слову мойого Творця,\nІ славу від Бога одержу, я буду щаслив без кінця!\n\nПриспів: \nТам усі в небесах\nЖдуть з Христом і мене у Творця.\nЗ мене хрест Спас здійме \nІ в небесную радість прийме.\n\nКуплет 2\nПобачу я місто прекрасне, де всі вихваляють Творця;\nУ світлій оселі небесній я буду щаслив без кінця!\n\nКуплет 3\nДванадцять воріт там перлинних, і слава там Божа сія. \nТам вічно в проміннях Христових я буду щаслив без кінця!\n\nКуплет 4\nТам будуть спасенні народи у славі свойого Творця. \nДалеко від бур і негоди, я буду щаслив без кінця!\n\nКуплет 5\nТам в царстві небесного міста зіллються спасенні серця, \nХвалу віддадуть там всі Богу... Я буду щаслив без кінця!', '', '', 'ua', NULL, 0, NULL, NULL),
(735, 216, 'На землі тут є тлінне', 0, 'Куплет 1\nНа землі тут є тлінне срібло, золото - все,\nТільки в Бозі незмінне вічне щастя моє.\nСпас усіх научає скарби в небі збирать,\nДе іржа не з’їдає, злий не може забрать.\n\nПриспів: \nО, скажи, Боже мій, чи записаний я,\nВ вічній книзі спасенних чи записаний я?\n\nКуплет 2\nДовго, довго блукав я, у гріхах проживав \nІ спасіння не знав я, і Христа не шукав; \nТільки вічний Спаситель мене Сам віднайшов \nІ ласкаво покликав.. . Я до нього прийшов.\n\nКуплет 3\nМісто вічне для вірних в небі Бог збудував,\nІ оселі Син Божий для спасенних придбав.\nТам гріха вже немає, ані темряви-зла, - \nСонце правди сіяє,, там небесна краса.', '', '', 'ua', NULL, 0, NULL, NULL),
(736, 217, 'Подивись на берег річки', 0, 'Куплет 1\nПодивись на берег річки, де багато є роси,\nТам поміж квіток барвистих лілея цвіте в красі.\n\nПриспів:\nЯк Бог лілію так любить, (2р.) дбає про її красу, - \nТо невже ж тебе забуде? Бачить Він твою тугу...\n\nКуплет 2\nКорінці її водою підкріпляються щодня,\nКвітка скроплена росою, - світить рання їй зоря.\n\nКуплет 3\nЛілея цвіте на волі, вверх глядить у небеса;\nБджілку, що літа у полі, вабить лілеї краса.\n\nКуплет 4\nЗапах милий і пахучий розливається в полях...\nЧи ж ходив хто найбагатший в пишних шатах, як вона?\n\nКуплет 5\nОсь яка краса творіння, як про неї Бог подбав!\nБез турбот вона й мучіння. Чого ж ти в журбу упав?', '', '', 'ua', NULL, 0, NULL, NULL),
(737, 218, 'До Христа навернись', 0, 'Куплет 1\nДо Христа навернись, нащо в світі блукать,\nЦінний час марнувать? Встань, кругом подивись:\nТи в грісі потонув та про Бога забув...\nДо Христа навернись!\n\nКуплет 2\nДо Христа навернись, гріхом стомлений син,\nТи ідеш на загин; на хвилинку спинись \nТа поглянь на Христа, — ллється кров з ран свята \nЗа тебе... Навернись!\n\nКуплет 3\nДо Христа навернись, Йому серце віддай,\nВін введе тебе в рай. На цей світ, не дивись.\nСпас так тяжко страждав, за тебе умирав:\nДо Христа навернись!', '', '', 'ua', NULL, 0, NULL, NULL),
(738, 219, 'Прийми хваління і подяку', 0, 'Куплет 1\nПрийми хваління і подяку,\nСин Божий, за Твою любов!\nЗа нас терпів Ти тяжкі муки,\nЗа нас пролив пречисту кров.\n\nКуплет 2\nЗнущання всі і оплювання,\nЛаскавий Спасе, Ти прийняв, - \nЩоб дати всім нам оправдання,\nЗа нас Ти на хресті страждав.\n\nКуплет 3\nПробитою, Спасе, рукою \nМене Ти до життя підняв;\nВ Тобі лиш джерело спокою,\nЯ радість і любов пізнав.\n\nКуплет 4\nПрийми хваління і подяку, \nСин Божий, за Твою любов! \nЗа нас терпів Ти тяжкі муки, \nЗа нас пролив святую кров.', '', '', 'ua', NULL, 0, NULL, NULL),
(739, 220, 'Прийди Святий Дух Утішитель', 0, 'Куплет 1\nПрийди, Святий Дух Утішитель!\nСердечний храм мій освяти,\n Завсіди будь Ти мій Учитель,\nВідкрий Твої слова святі.\nНавчай мене пізнать Творця,\nВ Нім научи любить Отця.\n\nКуплет 2\nДаруй мені дух розуміння, - \nВ сумнів ніколи не впадать,\nЩоб всі божественні веління,\nЯ міг завсіди виповнять.\nЛюбов’ю душу знов зігрій,\nЛюбов до святості дай їй.\n\nКуплет 3\nДля мене радість і утіха,\nДух Утішитель, Ти один:\nСпокоєм серце наповняє \nТобою, вічний Божий Син.\nЛюбов, надію, шле як дар \nІ в серці віри гріє жар.\n\nКуплет 4\nБлагаю: милістю Твоєю \nІ дух, і серце обновляй,\nМоєю володій душею,\nВ смиренні волю підкріпляй.\nБлагий Учитель завжди будь \nІ направляй на світлий путь!', '', '', 'ua', NULL, 0, NULL, NULL),
(740, 221, 'Як сумно на серці', 0, 'Куплет 1\nЯк сумно на серці мені, коли я не бачу Христа, - \nСпокою не маю тоді, | змовкають (Зр.), німіють уста.\n\nКуплет 2\nІ ніби все спить навкруги: і місяць, і зорі смутні,\nНе тішать ні гай, ні луги... І сумно (Зр.) на серці в ті дні.\n\nКуплет 3\nВ Ісусі все щастя моє: з Ним всюди у світлі іду, —\nКоли Він у серці живе,  співаю (Зр.) Йому я хвалу.\n\nКуплет 4\nНайкращим для мене в житті, учитись усе від Христа, \nСлова розуміти святі, — | дочасне (Зр.) усе - марнота.', '', '', 'ua', NULL, 0, NULL, NULL),
(741, 222, 'Грішник слухай', 0, 'Куплет 1\nГрішник, слухай! (2р.) Голос чийсь звучить:\nГолос милий, голос тихий просить відчинить.\nТо не пізній перехожий в двері стукає,\nТебе просить Сам Спаситель: - О, впусти Мене! - і\n\nКуплет 2\nВ твоїм серці смерті холод, темрява нічна;\nЯк відчиниш Йому серце, стане там весна.\nРіч свята Його поллється, як небесний спів....\nЧуєш - стука, чуєш - каже: - Відчини мені!\n\nКуплет 3\nО, відкрий же Йому серце, - Він там хоче жить.\nІ твою скорботну душу світлом оживить.\nНе вагайся відчинити, не зостанься в сні;\nСкоро змовкне голос тихий: - Відчиніть Мені!', '', '', 'ua', NULL, 0, NULL, NULL),
(742, 223, 'Повернись додому', 0, 'Куплет 1\nПовернись додому! В країні чужій, чужій,\nТи блукав так довго (2р.), сину дорогий, дорогий!\n\nКуплет 2\nПовернись додому, на чужині тій, чужій,\nВзнав ти голод й холод (2р.), сину дорогий, дорогий !\n\nКуплет 3\nПовернись додому; шлях недобрий твій, шлях твій \nЗалиши навіки(2р.), сину дорогий, дорогий!\n\nКуплет 4\nПовернись додому, - в боротьбі тяжкій, тяжкій \nТи втомивсь стояти (2р.), сину дорогий, дорогий!\n\nКуплет 5\nПовернись додому, будь навіки Мій, будь Мій: \nЖду тебе давно Я (2р.), сину дорогий, дорогий!', '', '', 'ua', NULL, 0, NULL, NULL),
(743, 224, 'Чи є місце для Ісуса', 0, 'Куплет 1\nЧи є місце для Ісуса? Муки Він за нас терпів... \nВідчини ж сердечні двері! Нас Він кров’ю всіх обмив.\n\nПриспів:\nДля Ісуса - Його слави місце в серці приготуй,\nГолос вчуй Його любові, сам до Нього поспішай.\n\nКуплет 2\nТи дочасним всім турботам місце в серці сам даєш?!\nО, невже ж перед Ісусом двері серця ти замкнеш?\n\nКуплет 3\nЧи прийдеш ти до Ісуса? Ось Він кличе знов тебе.\nО, будь, друже, обережний: скоро час земний пройде!\n\nКуплет 4\nПоспішай же до Ісуса, серце ти Йому віддай,\nПоки не замовк ще голос, Сина Божого приймай!', '', '', 'ua', NULL, 0, NULL, NULL),
(744, 225, 'Вір душа кріпися', 0, 'Куплет 1\n«Вір, душа, кріпися! Я - Спаситель твій,- \nЗавжди лиш дивися на світильник Мій!\nНа шляху тернистім руку Я подам,\nЯ з тобою всюди, - вір, що уже ти не сам».\n\nПриспів: \nНі, (я не один), я не один, (я не один):\nПастир мій — Ісус! Він мене Сам захищає \nВід всіх ворожих спокус.\n\nКуплет 2\nЛілії пов’януть, сонце теж зайде,\'\nА Господня слава повік не пройде.\nХоч бушує буря ніччю, чи удень, - \nВсюди Спас Зі мною, - з Ним я уже не один.\n\nКуплет \nХоч трудна дорога тут мого життя, - \nЧую Божий голос: «Ти - Моє дитя!»\nВірю, що Спаситель вірних захистить,\nІ спасенні душі будуть у небі з Ним жить.', '', '', 'ua', NULL, 0, NULL, NULL),
(745, 226, 'Життя одне ми маєм', 0, 'Куплет 1\nЖиття одне ми маєм в цьому світі,\nІ хутко як минають Його дні;\nЖиття одне, щоб славити Ісуса,\nЙому служити, не пробути в сні.\n\nКуплет 2\nВсе, що Він дав, Йому лиш поверну я,\nВесь час, всі дні і сили всі мої.\nСпаситель мій! За мене постраждав Ти:\nЯк не віддам життя моє Тобі?!\n\nПриспів: \nЖиття одне як швидко пролетить,\nЛиш все, що Боже, вічно устоїть (2р.)\n\nКуплет 3\nЖиття одне - чому нема в вас діла?\nХристос усіх на працю кличе вас \nПогляньте! Тисячі в гріхах вмирають,\nПочуйте - тисячі благають нас.\n\nКуплет 4\nВставайте всі, вставайте до роботи, - \nПролинуть скоро, скоро наші дні.\nВставайте всі, хоч спали ви так довго,\nБо прийдете до Господа-Судді.\n\nКуплет 5\nЖиття моє Тобі припоручаю, -\nПошли мене про Тебе розказать\nЗаблудлим всім, що в темряві блукають,\nПро смерть Твою, про рани нагадать.\n\nКуплет 6\nВсе, все візьми, о Боже, на служіння,\nЛиш би від смерті грішників спасти!\nЗ Тобою я - моя уся в тім слава,\nБо в радість неба можу я ввійти.', '', '', 'ua', NULL, 0, NULL, NULL),
(746, 227, 'Нам здалека вже видно', 0, 'Куплет 1\nНам здалека вже видно той Край,\nДе у славі небесній Господь.\nСам Спаситель веде в Божий рай \nСвій відкуплений, вірний народ.\n\nПриспів:\nСкоро Він (скоро Він) нас введе (нас введе)\nУ бажаний той Край дорогий (нас введе)!\nСкоро Він (скоро Він) нас введе (нас введе)\nУ бажаний той Край дорогий!\n\nКуплет 2\nТам, забувши недолю земну,\nДе чудова Країна свята,\nВсі співають Творцеві хвалу,\nПрославляють всім серцем Христа.\n\nКуплет 3\nТам зібрання спасенних усіх,\nЩо втішаються Духом Святим,\nВеличають Христову любов \nПеред троном Його пресвятим.', '', '', 'ua', NULL, 0, NULL, NULL),
(747, 228, 'Пастир добрий', 0, 'Куплет 1\nПастир добрий, стережи нас; наше щастя лиш в Тобі! \nДоглядай і підкріпляй нас: всі без Тебе ми слабі.\n\nПриспів: \nО, Ісус Христос, Спаситель!\nТи купив нас, - ми Твої.\n\nКуплет 2\nМи бажаєм за Тобою, тільки за Тобою йти;\nСам дорогою вузькою в Царство вічне нас веди.\n\nКуплет 3\nВсіх прийняти Ти бажаєш, кличеш кожного: -Прийди! \nВсі провини Ти прощаєш тим, хто вірує Тобі.', '', '', 'ua', NULL, 0, NULL, NULL),
(748, 229, 'Будем браття жити свято', 0, 'Куплет 1\nБудем, браття, жити свято, хоч панує гріх кругом.\nМи ж в єднанні брат із братом всі підемо за Христом. \nНас Христос прийняв з любов’ю,\nВ Ньому радуймося ми: Він нас спас Своєю кров’ю - \nБудьмо ж світлом між людьми.\n\nКуплет 2\nУ марнотах ми блукали, смерть за нами всюди йшла. \nБожа ласка нас шукала і, знайшовши, нас спасла. \nХоч ми духом всі убогі, -\nНам Христос багатство дав:\nПоказав у рай дорогу і спасіння дарував;\n\nКуплет 3\nЧи то в горю, чи в стражданнях,\nВірим - Бог нас підкріпить.\nПідем далі без вагання за Спасителем услід.\nХоч кипить ще зло у світі, темрява гріха царить,- \nБог в любві по заповіту від спокус нас захистить.', '', '', 'ua', NULL, 0, NULL, NULL),
(749, 230, 'Насліддя моє в небесах', 0, 'Куплет 1\nНасліддя моє в небесах, - і моя туди лине душа, \nДе Творцеві в чудових піснях \nВід спасенних лунає хвала.\n\nПриспів: \nВ небесах, (в небесах), (2р.)\nНасліддя моє в небесах, (в небесах), \nВ небесах (в небесах), (2р.) \nНасліддя моє в небесах.\n\nКуплет 2\nГосподь мене жде в небесах,\nІ Він прийме в оселю Свою,\nДе у сяйві Господнім краса \nВ Його світлім блаженнім раю.\n\nКуплет 3\nВ край світлий і я увійду, - \nЗакінчу путь тернистий земний,\nТам всіх вірних слуг Божих знайду- \nВони вийдуть назустріч мені.', '', '', 'ua', NULL, 0, NULL, NULL),
(750, 231, 'Де живуть у злі', 0, 'Куплет 1\nДе живуть у злі й без Бога, - ти життям не називай! \nДля Спасителя Ісуса серце стомлене віддай!\n\nКуплет 2\nДруже, глянь, як народ тоне у гріхах і марноті!\nНе знайдеш ти тут спокою, щастя знайдеш лиш в Христі.\n\nКуплет 3\nО, збирай борців за віру, до Ісуса закликай:\nДень за днем проходить скоро, - не барися, поспішай!\n\nКуплет 4\nСкільки душ Христа не знають і без Господа живуть... \nРозкажи їм про Ісуса, наверни на добру путь!\n\nКуплет 5\nСвідком будь ти перед ними, розкажи, що бачив сам, \nЯк любов Свою Спаситель дав покірним всім серцям.\n\nКуплет 6\nПрисвяти себе Ісусу, - всі літа ще молоді,\nПрисвяти Йому і старість, будеш з Богом жить тоді!\n\nКуплет 7\nО, віддайся ти Ісусу, - і за тебе Він страждав, \nПеретерпів хресні муки, кров невинну проливав.\n\nКуплет 8\nСерце хто віддасть Ісусу, вічне в Нім життя знайде;\nТого Сам Христос Син Божий \nВ царство радості введе.', '', '', 'ua', NULL, 0, NULL, NULL),
(751, 232, 'Ісусу Відкупителю', 0, 'Куплет 1\nІсусу-Відкупителю із роду в рід хвала!\nСлаву і честь Спасителю віддайте, племена!\n\nПриспів: \nСпівайте щиро всі, (співайте всі), (2р.)\nПро вістку радісну святу,\nБожу ласку доброту,\nСпівайте щиро всі, (співайте всі)!\n\nКуплет 2\nСпаситель кров Свою пролив, смерть смертю подолав. \nНас у любові оправдав й життя нам вічне дав.\n\nКуплет 3\nПрийдіть до Господа усі, до Джерела життя: \nВода жива є для душі у Господа Христа.\n\nКуплет 4\nЯк твоє серце ще скорбить, - до Спаса йди скоріш;\nВін твою душу оживить і дасть тобі спокій.', '', '', 'ua', NULL, 0, NULL, NULL),
(752, 233, 'Хто хто там веселиться', 0, 'Куплет 1\nХто, хто, там веселиться, так радісно співа? - \nЗаблудлий син вернувся до рідного Отця. \nНе хоче споминати Отець старих подій,\nДитя своє обняти Він хоче найщиріш..\n\nКуплет 2\nХто, хто там веселиться? Спів голосно звучить!... \nЗагублений син вдома з Отцем уже гостить.\nВін пропадав далеко, у світі цім блудив,\nВін гинув у пороках, лиш у Отця ожив.\n\nКуплет 3\nХто, хто там веселиться? То Божий є слуга;\nТепер він не смутиться: журба його пройшла.\nЛюбов його зогріла, як до Отця прийшов,\nІ радість завітала у серці його знов.\n\nКуплет 4\nХто, хто там веселиться? Христів це є слуга,\nУ рідний дім ввійшов він, де смутку вже нема. \nДруззя! І ви спішіте радіти у Христі,\nДо Бога всі прийдіте, не жийте в марноті!', '', '', 'ua', NULL, 0, NULL, NULL),
(753, 234, 'Спасіння вічне завершив', 0, 'Куплет 1\nСпасіння вічне завершив Христос для всіх людей; \nВін грішних з Богом примирив, дав світло для очей.\n\nПриспів: \nО, серце, не вагайся, вір!\nПрийми Христа тепер.\n\nКуплет 2\nГосподь всіх грішних полюбив, за них Він кров пролив.\nВін на хресті в предсмертний час Отця молив за нас.\n\nКуплет 3\nЖиття Спаситель мертвим дав, гріх переміг і тьму. \nСвоє нам слово дарував, щоб вірили Йому.\n\nКуплет 4\nГосподнє слово - меч святий, струмінь води живий; \nВоно карає всякий гріх, навчає правди всіх.', '', '', 'ua', NULL, 0, NULL, NULL),
(754, 235, 'Як я пізнав любов Христа', 0, 'Куплет 1\nЯк я пізнав любов Христа, знайшов я вічне в Нім життя, \nТепер Ісус-Спаситель мій дарує серцю Свій спокій.:\n\nПриспів:\nО, Алілуя! Сталося!... Мене Ісус вже відкупив, \nСпаситель мій дає спокій і силу в боротьбі земній.\n\nКуплет 2\nКоли я до Христа прийшов, нетлінні скарби в Нім знайшов: \nНадія, віра і любов - мене втішають знов, і знов.\n\nКуплет 3\nВсе щастя у любві Христа, земне багатство - марнота; \nХристос для мене - Хліб живий, Я вже Його, я вже не свій.', '', '', 'ua', NULL, 0, NULL, NULL),
(755, 236, 'Чи буде заграва на сході світати', 0, 'Куплет 1\nЧи буде заграва на сході світати,\nЧи яснеє сонце почне вже сіяти, - \nІз неба прийде знов Ісус в вічній славі \nУзять від землі Своїх.\n\nПриспів:\nО, наш Спасителю, Тобі заспіваєм в той день:\n«Ось, гряде Він, - Алілуя! | Алілуя, амінь!» (2р.)\n\nКуплет 2\nЧи буде опівдні, чи то опівночі,\nНежданно побачать Його наші очі;\nПрийде наш Спаситель осяяний світлом \nУзять від землі Своїх.\n\nКуплет 3\nІ ангельські сили з Ним будуть сіяти,\nХристос буде вірних Своїх зустрічати.\nІ співи хваління поллються рікою,\nЩо взяв від землі Своїх.\n\nКуплет 4\nО, радість, туди перейти без страждання,\nБез болю, тривог та недуги й зітхання,\nУ славу Господню на небо піднятим, \nКуди Він візьме Своїх.', '', '', 'ua', NULL, 0, NULL, NULL),
(756, 237, 'Блаженні серця', 0, 'Куплет 1\nБлаженні серця, що Христа прийняли,\nСпасіння і мир на Голгофі знайшли.\nПростив Ти мені, і навіки я Твій:\nЗнайшов я у Тебе і радість, й спокій.\n\nПриспів: \nПрославте любов Христа, \nДивну, Божественну.\nСпасає грішників любов Христа.\n\nКуплет 2\nДалеко в гріхах від Христа я блукав: \nСпасіння, спокою у серці не мав; - \nТепер я співаю: Спасителю мій,\nЗцілив Ти мене у любові Своїй!\n\nКуплет 3\nБлаженні відкуплені смертю Христа,- \nСпаситель відкрив їм нове вже життя: \nУтер Він їх сльози і світлом осяяв \nІсус мені силу слабому подав.\n\nКуплет 4\nО, Спасе мій милий, Ти - радість моя! \nНавчай же, щоб вірно служив Тобі я:\nПролив Ти за мене Божественну кров, \nСлавлю я милість Твою і любов.', '', '', 'ua', NULL, 0, NULL, NULL),
(757, 238, 'Людям блукаючим шлях покажіте', 0, 'Куплет 1\nЛюдям блукаючим шлях покажіте,\nТих, що зневірились, ви підбодріть, - \nВсім погибаючим правду скажіте,\nХто спить душею, ідіть, розбудіть!\n\nПриспів: \nЛюдям блукаючим шлях покажіте;\nХто спить душею, ідіть, пробудіть!\n\nКуплет 2\nПро відкуплення всім вістку несіте, - \nКожного кличе Спаситель- Прийди!\nІ научайте всіх в Господі жити,\nЩоб міг нещасний в Нім щастя знайти!\n\nКуплет 3\nЛюдям, що в світі тут ходять в темряві,\nСвітло Христове негайно несіть.\nВ серце утомлене життям гріховним \nРадість Дух Божий лиш може пролить.\n\nКуплет 4\nЩиро до праці ми, браття, підемо,\nЩоб ближнім поміч в недолі подать,\nВ праці для Господа радість знайдемо:\nНас підкріпить в ній Його благодать.', '', '', 'ua', NULL, 0, NULL, NULL),
(758, 239, 'Слухайте вістку святу', 0, 'Куплет 1\nСлухайте вістку святу в простоті,\nПоки ще маєте час:\nВірним дарує Спас вічне життя;\nБог нас від гибелі спас.\n\nПриспів: \nБог нас від гибелі спас! (2р.)\nТак, Бог нас навіки простив у Христі, \nБог нас від гибелі спас.\n\nКуплет 2\nКоли ще спомин пролинувших днів\nДушу тривожить нераз, -\nВірте, — Спаситель усе вам простив:\nБог нас від гибелі спас.\n\nКуплет 3\nКоли в темряві й життєвій борні \nПромінь надії погас,\nЗнов пригадайте ви, браття, тоді:\nБог нас від гибелі спас.', '', '', 'ua', NULL, 0, NULL, NULL),
(759, 240, 'Скажіть мені браття', 0, 'Куплет 1\n«Скажіть мені, браття і сестри, куди ви зібрались іти?\nКаміння на вашій дорозі, і терен колючий росте».\n- Ідемо ми в царство Христове,\nТам вічного щастя краса,\nКрізь темряву чорної ночі \nМи бачим світ Божого дня.\n\nПриспів: \nВже скоро, і путь ми пройдем,\nДо рідного дому ввійдем;\nГосподь в Свою радість нас прийме, \nТам вічнеє щастя знайдем.\n\nКуплет 2\n«Як дуже бажав би я з вами в далеку дорогу піти, \nТа думка одна лиш тривожить:\nНе знаю, де сили знайти?» \n- Ми слухаем Боже веління, -\nВін Духа Святого дає,\nЩо наші серця підкріпляє і сил  бородьбі подає\n\nКуплет 3\n- О, браття,тепер я рішась\nЛишити все и з вами піти! Я вірю, мені Бог поможе \nДалекий той путь перейти».\n- Вітаємо, брате, бажання!\nСкоріше нам руку подай, і підемо в путь без вагання \nВ чудовий і світлий той край.', '', '', 'ua', NULL, 0, NULL, NULL),
(760, 241, 'Я люблю з Христом ходити', 0, 'Куплет 1\nЯ люблю з Христом ходити, як апостоли колись;\nЯк зібрав їх коло Себе, й говорив їм благу вість:\nЯк прийшов Він, щоб з неволі\nУвільнити всіх людей,щоб тягар гріхів з них зняти,\nА їм дати Свій спокій.\n\nПриспів: \nЯ піду, де поведе Він,\nЯ буду там, де буде Він;\nЯ піду з Ним все і всюди - \nЯ піду з Ісусом кожний день.\n\nКуплет 2\nЯ люблю з Христом ходити,\nЯк тих два мужі в той час,\nЯк Ісус йшов з Єрихону - \nКричали: «Помилуй нас!»\nІ Христос вчув їх благання та дав зір їхнім очам;\nІ вони з радістю встали, і пішли вслід за Христом.\n\nКуплет 3\nЯ люблю з Христом ходити\nНа гору Голгофську там, -\nІ дивитись на страждання, де заплачу із жалем.\nТам Він каже, як Він любить;\nЯк мої гріхи простив. - з радістю За Ним я піду,\nДе б лиш Він мене не вів.\n\nКуплет 4\nЯ колись буду ходити з Ним в небеснім місті тім,\nЯк я земний шлях скінчу вже \nІ ввійду в той вічний дім.', '', '', 'ua', NULL, 0, NULL, NULL),
(761, 242, 'Хто хто радість дасть', 0, 'Куплет 1\nХто, хто радість дасть? Я в журбі благав- \nРадість, щастя у Христа лиш я пізнав.\n\nКуплет 2\nВін мене від зла завжди захистить, - \nБез Нього не можу я на світі жить.\n\nКуплет 3\nХочу жити з Ним, з Господом моїм, - \nВін стражданням відкупив мене Своїм.\n\nКуплет 4\nКличе Спас усіх, щоб скоріш прийшли \nІ велику радість в серце прийняли.\n\nКуплет 5\nО, мій друже, встань, до Христа прийди,\nУ цім грішнім світі більше не блуди!', '', '', 'ua', NULL, 0, NULL, NULL),
(762, 243, 'Далеко від земних марнот', 0, 'Куплет 1\nДалеко від земних марнот \nІ всіх людських турбот\nЄ край, де вічно ясний день,\nДе ллється звук пісень.\n\nПриспів:\nВ той Край (в той Край) (2р.) всім серцем лину я, \nДе вічне щастя - Божий рай, де вічне світло дня.\n\nКуплет 2\nТам лиш любов свята царить \nІ вірних веселить,\nЖиття там вічного весна,\nКраса там неземна;\n\nКуплет 3\nНове там небо і земля, - \nПо правді всі живуть;\nХристом відкуплені серця \nТам сліз уже не ллють.', '', '', 'ua', NULL, 0, NULL, NULL),
(763, 244, 'До Господа прийдіть', 0, 'Куплет 1\nДо Господа прийдіть, в любві Йому служіть: \nХристос за грішних постраждав і їм спасіння дав!\n\nПриспів:\nІдем ми з хвалінням в світлий небесний Сіон,\nУсі ми йдем до Сіону і будем там вічно з Христом!\n\nКуплет 2\nСпасенні всі спішать, і співи їх звучать;\nЗа Господом вони пішли і в Нім життя знайшли.\n\nКуплет 3\nДруззя! І ви спішіть, вслід за Христом ідіть; \nПрийміть Його в свої серця, знайдете в Нім життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(764, 245, 'Буря грізна завиває', 0, 'Куплет 1\nБуря грізна завиває, і вітер страшний загув,\nХмара, як ніч, насуває, - ми гинем, а Ти заснув.\nХіба тебе не турбує, що смерть облягає нас? \nСтрашні хвилі ревуть і бушують, і можуть залити нас.\n\nПриспів:\n«І море, і буря почують Мене, затихне усе;\nМоре бурхливе смириться,\nМені тут усе впокориться:\nСоздатель землі і небес тут Сам,\nНе дасть Він ніколи загинуть вам!\nІ море, і буря вчують Мене, затихне усе»: (2р.)\n\nКуплет 2\nБоже, в великій печалі голову хилю свою,-  \nДушу гріхи заливають; о, Боже, спаси, молю!  \nСерце скорбить і страждає в тривозі, в борні земній;  \nО, я гину, помилуй, благаю, душі моїй дай спокій !\n\nКуплет 3\nБуря уже перестала, і в серці настав спокій;\nСонце з небес засіяло, ллє промінь душі моїй.\nБудь же, мій Спасе, зі мною, мене Ти охороняй \nІ в Небесну Країну спокою душу мою направляй!', '', '', 'ua', NULL, 0, NULL, NULL),
(765, 246, 'Дружно дружно будем працювати', 0, 'Куплет 1\nДружно, дружно будем працювати;\nМи на труд той з радістю підем, \nЩо для нас тепер Господь призначив \nЧесно й свято виповнять будем.\n\nПриспів: \nТруд цей для Бога \n(труд цей, труд цей весь для Бога),\nРадісно підем, (так), радісно підем\nТруд цей для Бога\n(труд цей, труд цей весь для Бога),\nВ винограднику Його.\n\nКуплет 2\nСміло, сміло про Христа розкажем,\nПро любов Його до грішних нас;\nНаш Спаситель, Божий Син у славі, \nБлагодать Він нам безмірну дасть.\n\nКуплет 3\nМи підем услід за Ним покірно,\nУ терпінню хрест наш понесем,\nІ людей, що тут живуть без Бога, \nДо Христа Ісуса приведем.', '', '', 'ua', NULL, 0, NULL, NULL),
(766, 247, 'Я не хочу марно часу провести', 0, 'Куплет 1\nЯ не хочу марно часу провести:\nВ світлі правди за Христом я буду йти,  \nКожний час-хвилину мойого життя \nХочу я віддати для Христа.\n\nПриспів:\nПонесу (понесу) я вість Христа (я вість Христа)\nПо землі (по землі) у всі місця ( у всі місця).\nХай за мене ангел скаже Господу,\nЩо услід я за Христом іду.\n\nКуплет 2\nСкільки душ блукає у гріхах і тьмі,\nСкільки сліз гарячих пролито людьми... \nДе недуги мучать душу, де печаль,\nРозказать там хочу про Христа.\n\nКуплет 3\nДе в домах незгода і тривожно жить,\nДе дітей молитись не хочуть учить,\nТам де зло і п’янство - темнота ума,\nПро Христа звістити хочу там.', '', '', 'ua', NULL, 0, NULL, NULL),
(767, 248, 'Ми по водах океану', 0, 'Куплет 1\nМи по водах океану .\nДрузі, в рідний Край пливем;\nТам за грізними водами,\nВідпочинок ми знайдем!\n\nПриспів: \nНезабаром стихне море,\nЯкір кинемо ми скоро.\nВ Небесний край ми увійдем\nДе не буде буде більше плачу,\nДе проблем я не побачу,\nТам вічну радість ми знайдем.\n\nКуплет 2\nСкільки, скільки вже приплило до завітних берегів,\nЄ ще місце в тій Країні і для інших моряків.\n\nКуплет 3\nПрипливем і кинем якір, де кінець журбі, сльозам; \nУвійдем в той Край прекрасний, будем вічно жити там.', '', '', 'ua', NULL, 1, '2020-12-20', NULL),
(768, 249, 'Беззахисні тьмою вкриті', 0, 'Куплет 1\nБеззахисні, тьмою вкриті, поміж хвиль учні пливуть. \n«Спасе, чи тобі байдуже? Поможи!» - Вони зовуть. \nМоре страшно розігралось, у скалистий берег б’є; \nШум вітрів не замовкає, буря стогне і реве.\n\nКуплет 2\nПроясніло, буря втихла, - все Господь перемінив,\nІ розлючені Він хвилі Своїм словом усмирив. \nЗаспіваєм: «О, Спаситель, Алілуя, честь Тобі!\nВід усього Хоронитель, впокорив Ти все Собі».\n\nКуплет 3\nО, душе! Куди прямуєш ти в житті цім без Христа? \nГріх, як хвилі, заливає,- не спасти тобі життя!\nКлич на поміч ти Ісуса,- Він за тебе кров пролив,\nЙ Він спасе тебе від бурі; Силу зла Він переміг.', '', '', 'ua', NULL, 0, NULL, NULL),
(769, 250, 'Мир повний мир', 0, 'Куплет 1\nМир, повний мир! -І там, де марнота,\nНебесний мир дає нам кров Христа.\nМир, повний мир Сам Бог нам подає,\nНадія на Христа нам мир дає.\n\nПриспів: \nМир, повний мир! (Мир, повний мир2р.) \nХоч (хоч зло навкруг) зло \nНавкруг кипить (навкруг кипить),\nТільки в Христі Ісусі.\n(Тільки в Христі Ісусі мир царить),\nМир царить, так мир царить,\nТак, (так, мир царить) мир царить,\nТак, мир царить.\n\nКуплет 2\nМир, повний мир! - Вдалі від дорогих:\nБог їх хоронить на путях земних; \nМир, повний мир, хоч тьма є впереді;  \nХристос - наш Цар, і сила наша в Нім!\n\nКуплет 3\nМир, повний мир! - Хоч смерть навкруги нас,-\nЇї вже переміг Спаситель наш.\nКоли ж кінець земній борні прийде,\nХристос в небесний дім всіх нас візьме.', '', '', 'ua', NULL, 0, NULL, NULL),
(770, 251, 'Наш Спаситель Ісус', 0, 'Куплет 1\nНаш Спаситель Ісус смерть прийняв за всіх нас, \nЩоб ми грішні життя осягли;\nНа хресті постраждав Він в призначений час, \nЩоб простити всі наші гріхи.\n\nПриспів: \nНа хресті Божий Син\nЗа всіх нас кров пролив.\nО, ж тяжко Спаситель страждав!\nЗа гріхи наші Він на хресті умирав,\nІ спасіння Він нам дарував.\n\nКуплет 2\nМилосердно й ласкаво приймає Він нас,\nІ прощає провини нам всі;\nСам Спаситель Христос відкупив усіх нас \nІ дає нам небесний спокій.\n\nКуплет 3\nВсі до Спаса прийдім, і ми будемо з Ним \nЖити в правді святій кожний день;\nА Він буде навчати нас Словом Своїм \nІ введе нас у Царство Своє.', '', '', 'ua', NULL, 0, NULL, NULL),
(771, 252, 'Христос любові повний', 0, 'Куплет 1\nХристос-любові повний,\nВ Нім світло й благодать.\nВін - Манна, Хліб небесний,\nВін - наша сила й щит;\nВ Нім наше відкуплення, життя в Нім без кінця:\nВ Нім звершене спасіння, спочинок для борця.\n\nПриспів: \nЛиш в Нім (Однім)! (2р.)\nІ благословіння повнота лиш в Нім. \nЛиш в Нім (Однім)! (2р.)\nВся повнота лиш в Нім (Однім).\n\nКуплет 2\nТепер я спочиваю, - не вискажуть уста,\nЯкий спокій в Нім маю, як любе з Ним життя!\nЯ в серці Його маю, і Він - моя хвала;\nВ душі Йому співаю за всі Його діла.\n\nКуплет 3\nКоли побачу, Боже, Тебе лицем в лице,\nТоді іще дорожчим Ти будеш для мене;\nТоді за всі даяння Тобі віддам хвалу\nЗа те, що від страждання Ти душу спас мою.', '', '', 'ua', NULL, 0, NULL, NULL),
(772, 253, 'Хвала Тобі Христос Господь', 0, 'Куплет 1\nХвала Тобі, Христос Господь,\nЩо Ти нас спас від зла-негод.\nЗа нас Ти на хресті страждав,\nЖиття загиблим дарував. Алілуя! Амінь.\n\nКуплет 2\nЄдинородний Божий Син! \nЗа безліч наших же провин, \nПрийняв Ти наше тіло й кров,\nСвою Ти проявив любов, Алілуя! Амінь.\n\nКуплет 3\nХто дав Вселенній рух, життя,\nЛежав у яслах, як Дитя\nНайкращий приклад всім подав,\nВ любові жить заповідав. Алілуя! Амінь.\n\nКуплет 4\nВін світло правди нам відкрив,\nЛюбов’ю зло Він переміг.\nІ на Голгофі постраждав, -  \nДітьми своїми нас назвав. Алілуя! Амінь.\n\nКуплет 5\nЗвершив предивне діло Спас:\nВід смерті врятував Він нас,\nХвала, о Богочоловік,	\nТобі віднині і повік! Алілу! Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(773, 254, 'На шляху життя', 0, 'Куплет 1\nНа шляху життя сміліше ми підем,\nКоли будем вірити Ісусу;\nСилу Божу для роботи ми знайдем,\nКоли будем вірити Ісусу.\n\nПриспів: \nЯсним стане шлях тоді,\nРадість серце оживить;\nНе здолає ворог нас,\nКоли будем вірити Ісусу.\n\nКуплет 2\nЗаповіти Божі будуть нам ясні,\nКоли будем вірити Ісусу:\nНаші всі серця наповнить Дух СВЯТИЙ,\nКоли будем вірити Ісусу.\n\nКуплет 3\nЖити будемо, як Вічний Бог велить,\nКоли будем вірити Ісусу;\nСерцем чистим будем в яснім небі жить,\nКоли будем вірити Ісусу.', '', '', 'ua', NULL, 0, NULL, NULL),
(774, 255, 'Минула ніч', 0, 'Куплет 1\nМинула ніч і день настав, Господь, хвала Тобі!\nТи мирний, тихий сон послав, був захистом мені.\n\nКуплет 2\nСьогодні, Боже, помагай з Тобою свято жить, \nЛюбити, вірити навчай, усім добро робить!\n\nКуплет 3\nЩо жде мене, не знаю я, та вірю - приймеш Ти,\nКоли скінчу моє життя, в край вічний і святий.', '', '', 'ua', NULL, 0, NULL, NULL),
(775, 256, 'Ми зібрання закінчили', 0, 'Куплет 1\nМи зібрання закінчили і додому йдем, -\nВсе, чого ми научились, у серця візьмем.\n\nПриспів:\nМирно-тихо і спокійно додому підем,\nСлово Боже, що ми чули, виповнять будем.\n\nКуплет 2\nОтож будемо ми завжди на зібрання йти \nІ учитися тут правди, як життя вести.\n\nКуплет 3\nДасть Бог жити, ми зійдемось на зібрання знов,\nЧи то в будень, чи в неділю - прославлять Його.', '', '', 'ua', NULL, 0, NULL, NULL),
(776, 257, 'О Боже йду я відпочить', 0, 'Куплет 1\nО, Боже, йду я відпочить у тишині нічній\nІ в руки віддаюсь Твої, мій Отче Всеблагий!\n\nКуплет 2\nО, Боже! Ти зі мною будь і в сні охороняй,\nЩоб тілом відпочив я тут, й душі спочинок дай!\n\nКуплет 3\nКоли ж по волі вже Твоїй сном смертним я засну, \nПрийми утомлений дух мій в Країну неземну. Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(777, 258, 'На спокійних хвилях моря', 0, 'Куплет 1\nНа спокійних хвилях моря вдаль кудись човен пливе.\nВсюди тиша. У просторі небо ясне, голубе.\nОсь схопилася раптово буря, й хвилі заревли. \nСеред моря страшно стало,- чорні хмари налягли.\n\nКуплет 2\nМандрівці зніяковіли, у зневір’я впали враз;\nСтрашно! Де ж узяти сили? Віру тратять в грізний час. \nТам Один лиш спочиває на кермі після трудів;- \nМоряки Його благають, і Він голову підвів.\n\nКуплет 3\n«Встань, Учителю, дивися! Чи байдуже це Тобі?\nВстань, Благий, розпорядися: в морі грізнім тонем ми! »\nВін устав і, погрозивши, змовкнуть бурі приказав,\nІ друззям за маловірство співчутливо докоряв...\n\nКуплет 4\nТак у нас в життєвій битві від страху душа тремтить, \nТа Христос через молитви своїх вірних захистить.\nХай утіхою Він буде для знеможених сердець,\nІ для гинучих усюди - вірний Пастир і Отець.', '', '', 'ua', NULL, 0, NULL, NULL),
(778, 259, 'Так той день вже близький', 0, 'Куплет 1\n1-5. Так, той день вже близький,\nДень великий, страшний,\nКоли всі народи враз стануть перед Судом.\n1. Браття і сестри розлучаться (Зр.)\nНавіки, раз на все.\n2. Мужі з жонами розлучаться, (Зр.)\nНавіки, раз на все.\n3. Діти з батьками розлучаться, (Зр.)\nНавіки, раз на все.\n4. Пастирі з стадом розлучаться, (Зр.)\nНавіки, раз на все.\n5. Що тут посіяв, то там пожнеш, (Зр.)\nНавіки, раз на все.', '', '', 'ua', NULL, 0, NULL, NULL),
(779, 260, 'За Євангельську ми віру', 0, 'Куплет 1\nЗа Євангельську ми віру, як один в борню ідім,\nІ, за прикладом Христовим, всі вперед, вперед за Ним!\n\nПриспів: \nДружно, радісно підемо,\nЯк один, в борню зі злом,\nЩирим серцем, одним духом \nЗа Спасителем Христом!\n\nКуплет 2\nБоротьба іде завзята, і кипить жорстокий бій, —\nЗа Христову ми науку піднесем прапор святий!\n\nКуплет 3\nСвіт байдужий не вважає на Спасителя-Христа;\nМи ж стоять за правду будем, за Його святі слова.\n\nКуплет 4\nВіра в Бога - наша сила: Він на поміч поспішить.\nЗброя в нас, як в Гедеона, - переможем нею зло.\n\nКуплет 5\nПовні віри в перемогу правди Божої над злом,\nСміло, радісно ідімо за Начальником-Христом!', '', '', 'ua', NULL, 0, NULL, NULL),
(780, 261, 'Друже Як хочеш свій гріх подолать', 0, 'Куплет 1\nДруже! Як хочеш свій гріх подолать, - \nЄ сила в крові, сила в крові!\nСерцем в свободу Христову ввійти, - \nЄ сила в Його крові.\n\nПриспів: \nСила Божа чудодійная -\nВ крові (в крові) Христа (Христа),\nСила Божа чудодійная -  \nУ пречистій крові Христа.\n\nКуплет 2\nХочеш ти пристрасть і гордість вмертвить,- \nЄ сила в крові, в крові Христа!\nМоже Христос всі гріхи віддалить:\nЄ сила в Його крові.\n\nКуплет 3\nХочеш ти бути біліший за сніг, - \nЄ сила в крові, в крові Христа! \nКров’ю Ісус тебе може обмить: \nЄ сила в Його крові.\n\nКуплет 4\nГосподу хочеш ти вірно служить, - \nЄ сила в крові, сила в крові!\nХочеш життям ти Ісуса хвалить, - \nЄ сила в Його крові!', '', '', 'ua', NULL, 0, NULL, NULL),
(781, 262, 'Докіль будеш спати', 0, 'Куплет 1\nДокіль будеш спати, о любий мій друже,\nХіба ти не чуєш святих слів Христа?\nПочуй, як ласкаво тебе Він все кличе!\nЧому не проснешся від сплячки-гріха?!\n\nКуплет 2\nХристос тебе кличе, - прийди ти до Нього, \nСклади свій тягар і гріховне ярмо:\nВін все може зняти, тягар облегчити, —\nІ більше не будеш носити його.\n\nКуплет 3\nСьогодні Він кличе, - покайся негайно,\nЧас лине-минає, - Христові віддайсь,\nБо скоро замовкне цей зов благодаті.\nТоді буде пізно спасіння шукать.\n\nКуплет 4\nЗове Він, бо любить, як батько і мати: \n«Прийдіть всі до Мене, прийміть благодать». \nБажаю, мій друже, тебе запитати:\nЯк довго ти будеш без Бога блукать?\n\nКуплет 5\nТобі раджу, друже, скоріш навернися, —\nІсус усіх хоче до себе прийнять.\nПрийди днесь до Нього, прийди, не барися!\nХристос Сам спасіння тобі хоче дать.', '', '', 'ua', NULL, 0, NULL, NULL),
(782, 263, 'Був ти друже на Голгофі', 0, 'Куплет 1\nБув ти, друже, на Голгофі, де Христос страждав,\nЯкі рани там глибокі Він за нас прийняв?\n\nКуплет 2\nЧи ти бачив, скільки крові з ран святих стекло, \nБачив той вінок терновий на чолі Його?\n\nКуплет 3\nЧи ти чув розпуки слово: «Боже, Боже Мій!\nЧом лишив Мене Самого в боротьбі тяжкій?!..’.»\n\nКуплет 4\n«Я прийшов до них з любов’ю, прагну їх спасти,\nА вони Мене розп’яли... Боже, їм прости!\n\nКуплет 5\nЗавершилось! -І до Твоїх, Отче, рук святих \nВіддаю Мій дух покірно,-Ти його прийми!»\n\nКуплет 6\nДруже, знай, що задля моїх і твоїх провин\nМусів тяжко так страждати Святий Божий Син.\n\nКуплет 7\nТому, друже, зараз-нині на Fолгофу йди,\nВ ногах Господа Ісуса весь твій гріх зложи.\n\nКуплет 8\nА із уст Його почуєш ті слова любві:\n«Ще сьогодні ти зі Мною будеш у раю»;', '', '', 'ua', NULL, 0, NULL, NULL),
(783, 264, 'Гopa Сіон гора святая', 0, 'Куплет 1\nГopa Сіон - гора святая, \nПрестол там Господа стоїть.\nТуди всім серцем моїм лину, \nДе Сонце вічнеє горить.\n\nКуплет 2\nДе бур нема; то край спокою,\nДе радості лунає спів,\nДе все в красі, у сяйві щастя,\nДе вже нема похмурих днів.\n\nКуплет 3\nУ славі там Господь сіяє \nПоміж відкуплених Своїх;\nВін сльози їх утер навіки \nІ втішив вічним щастям їх.\n\nКуплет 4\nХваління ллється з уст спасенних,\nТам співи радості звучать, -\nЗемна ніяка людська мова\nНе може слів тих передать.\n\nКуплет 5\nО, скоро, скоро я там буду\nЗ Христом на тій горі святій:\nВін спас мене Своєю кров’ю,\nМій Відкупитель - Пастир мій.', '', '', 'ua', NULL, 0, NULL, NULL),
(784, 265, 'Ви блудите і б’єте ноги', 0, 'Куплет 1\nВи блудите і б’єте ноги, - спасіння хочете знайти,\nАле чи знаєте дорогу, яким вам шляхом треба йти?\n\nКуплет 2\nІдіть дорогою ви правди, до злих на раду не ходіть, \nЛюбіте ворога, як брата, то раєм зробиться цей світ.\n\nКуплет 3\nКоли ж ще мучитесь душею, - моліться: «Господи, прости!»\nНе допускайтеся, щоб Каїн у серці місце міг знайти.\n\nКуплет 4\nЧитайте Божу Святу Книгу, - в ній все ви можете знайти; \nВона покаже ту дорогу, якою треба вам іти.', '', '', 'ua', NULL, 0, NULL, NULL),
(785, 266, 'Не сумуй ти душе дорогая', 0, 'Куплет 1\nНе сумуй ти, душе дорогая,\nНе журися, а радісна будь!\nЖиття краще тебе дожидає:\nЛюбить всіх нас Господь, не забудь.\n\nКуплет 2\nУповай ти на Господа Бога \nІ частіше молися в тиші,\nТо затихне у серці тривога,\nІ одержиш спокій для душі.\n\nКуплет 3\nВ світі хвилі бушують, як в морі,\nВітер страшно і дико шумить;\nАле глянь, як ласкаво в тім горю \nНа тебе твій Спаситель глядить.\n\nКуплет 4\nТут терпіти уже нам недовго, - \nМи готові стоять в боротьбі;\nПерейдем у житті труд і горе,\nІ ввійдемо у вічний спокій.\n\nКуплет 5\nПристань тиха усіх нас чекає,\nБурних хвиль і тривог там нема;\nКраще сонця Господь там сіяє,\nІ для вірних там радість свята.\n\nКуплет 6\nНе сумуй же, душе дорогая,\nНе журися, а радісна будь: \nВ небі наша Країна святая, -\nВсі спасенні спокій там знайдуть!', '', '', 'ua', NULL, 0, NULL, NULL),
(786, 267, 'Не знав я Ісуса', 0, 'Куплет 1\nНе знав я Ісуса - життя я не знав:\nБез Божого світла у тьмі я блукав.\nАж чую я голос - Господні слова:\n«Він любить, Він любить!» - то любов Христа.\n\nПриспів: \nЯ жив у гріхах (я жив у гріхах),\nХристос мене спас (Христос мене спас); \nВін любить (2р.): Він умер за нас!\n\nКуплет 2\nКоли утомлюся в земній боротьбі,\nСпокою не знайду я тут для душі, - \nТоді чую голос - Господні слова:\n«Він любить, Він любить!» - то любов свята.\n\nКуплет 3\nХристові довіривсь і Ним я живу, - \nДолиною смерті без страху іду;\nІ Він не покине, твердять слова знов:\n«Він любить, Він любить, бо Він є любов!»', '', '', 'ua', NULL, 0, NULL, NULL),
(787, 268, 'Не піддайсь спокусі', 0, 'Куплет 1\nНе піддайсь спокусі, бо впадеш у гріх;\nПрикладом будь добрим у житті для всіх,\nІ зі злом борися, гніватись не смій, - \nНа Христа дивися: Він - Заступник твій!\n\nПриспів: \nСпаса зови на поміч:\nВін - твій добрий приятель,\nВчує твоє благання і дасть поміч тобі.\n\nКуплет 2\nУникай ледарства, не гріши в словах,\nІ шануй все Бога, май Господній страх.\nСвято, чесно, мудро живи у любві, - \nНа Христа дивися: Він - Заступник твій.\n\nКуплет 3\nТому, хто у світі воює з гріхом,\nБог вінець дарує і життя з Христом.\nБрате мій, кріпися і у вірі стій,\nНа Христа дивися: Він - Заступник твій.', '', '', 'ua', NULL, 0, NULL, NULL),
(788, 269, 'Коли я до Христа прийшов', 0, 'Куплет 1\nКоли я до Христа в гріхах прийшов,\nВін взяв мої гріхи; Він взяв мої гріхи;\nІ замість смутку радість я знайшов:\nВін взяв мої гріхи.\n\nПриспів: \nМої гріхи Він взяв (2р.)\nІ серцю радість дарував,\nЯ рад, що мої гріхи Він взяв\nІ радість дарував.\n\nКуплет 2\nТягар гріхів для мене був тяжким,\nВін взяв мої гріхи, Він взяв мої гріхи;\nІ я на Нього мій тягар зложив:\nВін взяв мої гріхи.\n\nКуплет 3\nОсудження для мене вже нема, -\nВін взяв мої гріхи, Він взяв мої гріхи;\nІ досконалий спокій мені дав:\nВін взяв мої гріхи.\n\nКуплет 4\nКоли й ти прийдеш до Христа тепер,\nТвої гріхи візьме, твої гріхи візьме:\nВін і тобі у серце радість дасть,\nТвої візьме гріхи.', '', '', 'ua', NULL, 0, NULL, NULL),
(789, 270, 'Небо місце є святе', 0, 'Куплет 1\nНебо місце є святе, повне ласки і любві:\nГріх не може там ввійти. І ворота чисті там, - \nНе для грішних місце там: гріх не може там ввійти!\n\nПриспів: \nГріх не може там ввійти, (2р.)\nТак, всіх грішних суд там жде,\nДруже, не дури себе:\nТи з гріхом там не ввійдеш.\n\nКуплет 2\nЯк захоч туди ввійти, як мине твоє життя,\nСвітлість ясна в домі тім: тож з гріхів очистися,\nМай в собі життя Христа: гріх не може там ввійти!\n\nКуплет 3\nЖити можеш у гріхах, благодаті не приймать,- \nТа не можеш там ввійти! Тебе здержать при дверях \nІ не впустять до Христа: гріх не може там ввійти!\n\nКуплет 4\nЯк грішити ти будеш й так життя це перейдеш, - \nВ пітьму вічну підеш ти, в місце те, де будуть всі \nТі, що жили у грісі: гріх не може там ввійти!', '', '', 'ua', NULL, 0, NULL, NULL),
(790, 271, 'Гей борці Христові', 0, 'Куплет 1\nГей, борці Христові, сміло в бій спішіть,\nПереможний прапор в гору піднесіть!\nСам Гетьман Небесний нас усіх веде,\nПолки в нас завзяті, грізний бій буде!\n\nПриспів: \nГей, борці Христові, в ряд ставайте враз, \nБо ворожі лави ідуть проти нас!\n\nКуплет 2\nАле злобний ворог врозтіч весь піде,\nЯк почує вістку: Наступ Бог веде!\nВже ворожі сили зі страху тремтять,\nГей, в ім’я Господнє час нам наступать!\n\nКуплет 3\nЄвангельське військо до бою іде,\nСміло, мов герої, бо Христос веде!\nМи не розділені, одне тіло ми,\nМи одного духа, Божі воїни.\n\nКуплет 4\nВсі світські престоли час руйнує геть,\nА Церкву Христову не здолає смерть,\nХристової Церкви пекло не звалить,\nБо Вона на Скелі - на Христі стоїть.\n\nКуплет 5\nЛюди, діти Божі, в наш табір спішіть,\nПід наш Євангельський прапор всі ідіть,\nЗ нами разом в співах Спаса прославлять,\nІ тоді відступить весь ворожий світ.', '', '', 'ua', NULL, 0, NULL, NULL),
(791, 272, 'Вождь наш перемагає', 0, 'Куплет 1\nВождь наш завсіди перемагає,\nПанцир любові на Нім;\nМеде Він військо Своє вірне, - \nСтроєм у битву йдуть всі.\nГлянь! Як всі сміло вступають\nВ бій проти зла, сатани,\nІм’я Христа викликають;\nСлухай, що кажуть вони:\n\nПриспів: \nНе для швидких перегони,\nЙ не для сильних боротьба,\nА перемога для вірних \nПо благодаті Христа.\n\nКуплет 2\nВсіх переможе Вождь наш сильний.\nХто ж Цей Чудовий є Цар?\nЧиє це військо, що веде Він,\nА спів лунає до хмар?\nВін — наш Господь і Спаситель,\nЩо переміг смерть і зло, - \nА борці Його - то вірні \nСлуги держави Його.\n\nКуплет 3\nПеремагає Вождь наш в битвах,\nІ довершить Він усе.\nЦарства й престоли світа цього \nСпаситель наш обійме.\nТоді Його військо вірне,\nЩо устоїть до кінця,\nБуде з Ним вічно у Царстві,\nУ славі Бога Отця.', '', '', 'ua', NULL, 0, NULL, NULL),
(792, 273, 'Непереможний ми маємо прапор', 0, 'Куплет 1\nНепереможний ми маємо прапор,\nВ бою за віру його підіймем!\nБог нас здобув Собі в вічне насліддя,\nНам перемогу дарує з Христом.\n\nПриспів: \nВсі за Ісусом, всі за Ісусом,\n(Всі за Ісусом сміло) (2р.)\nРадісно в бій ми підем, (ми підем),\nПовну одержим ми перемогу, \n(Повну одержим ми над злом \nПеремогу, сміло!).\nВсі за Ісусом сміліш, (всі сміліш)!\n\nКуплет 2\nЛюдську залишимо в світі ми славу;\nВзявши свій хрест, Його смерть сповістім. \nКоли страждаємо з Ним в цьому світі.\nТо в вічній славі будемо з Ним.\n\nКуплет 3\nЗ радістю приймемо ганьбу від світу,\nЗ радістю скажемо всім про Христа;\nМи покладаєм на Нього надії,\nЩиро Його славлять наші уста.\n\nКуплет 4\nБог дарував нам могутнюю силу, - \nВорога нею Христос переміг.\nНею одержим і ми перемогу \nІменем Вічного Господа Сил.', '', '', 'ua', NULL, 0, NULL, NULL),
(793, 274, 'Коли я чую про Христа', 0, 'Куплет 1\nКоли я чую про Христа, я в серці веселюсь,\nТоді співаю в простоті: Спаситель мій Ісус.\n\nКуплет 2\nКоли на тьму земного зла, де гинув, подивлюсь \nТоді звучить моя хвала: Спаситель мій Ісус!\n\nКуплет 3\nВ якій безодні потопав, — згадати я боюсь;\nГосподь мене урятував, Спаситель мій Ісус!\n\nКуплет 4\nУ світі я без Бога жив, тепер же я учусь \nУ Тебе, як Творця любить, Спаситель мій Ісус!\n\nКуплет 5\nПеред Тобою мертвим був, - тепер я веселюсь:\nМій дух від смерті оживив Спаситель мій Ісус!\n\nКуплет 6\nТи радість дав душі моїй, і я тепер молюсь, \nЩоб цілий світ Тебе пізнав, Спаситель мій Ісус', '', '', 'ua', NULL, 0, NULL, NULL),
(794, 275, 'З Ісусом жити радісно', 0, 'Куплет 1\nЗ Ісусом жити | радісно, (Зр.)\nВін нас веде в завітний Край, чудовий, світлий Край.\n\nПриспів: \nО, Ісус Спаситель! Ти вічно мій,\nТи вічно будеш мій найкращий друг.\n\nКуплет 2\nМене від смерті І відкупив (Зр.)\nІ словом правди відродив, мене Він відродив.\n\nКуплет 3\nСвятого Духа | Він послав (Зр.)\nІ Духом Він мене хрестив, і серце оживив.\n\nКуплет 4\nЯ буду Бога І прославлять (Зр.)\nЗа радість ту великую і милість вічную.\n\nКуплет 5\nЙого всім серцем І я люблю, (Зр.)\nЖиття своє я віддаю, Йому я віддаю.', '', '', 'ua', NULL, 0, NULL, NULL),
(795, 276, 'О Спаситель мій', 0, 'Куплет 1\nО, Спаситель мій, чую голос Твій,\nГолос любий, неземний!\nПромінь віри враз душу оживив,\nПолум’ям любві зогрів.\n\nПриспів: \nБлижче, ближче до Твого хреста,\nДе вмирав Ти за мене,\nБлижче, ближче, ближче до Твого хреста, \nГосподи, веди мене!\n\nКуплет 2\nСвітлом істини, о Спаситель мій,\nМоє серце осіяй,\nВсе життя візьми, - я віднині Твій, - \nМудрість для служіння дай!\n\nКуплет 3\nПонад світла всі, що у світі цім,\nНайяснішим є Христос...\nСили дай мені, о Спасителю,\nЩоб світильник мій не згас!', '', '', 'ua', NULL, 0, NULL, NULL),
(796, 277, 'Ми у Христі вже', 0, 'Куплет 1\nМи у Христі вже, -- не під законом:\nПрощені всі ми навіки Богом, - \nЗа нас Спаситель Сам постраждав,\nРаз назавсіди нас оправдав.\n\nПриспів: \nРаз Він страждав! О, грішнику, знай!\nЗа нас вмирав, - подяку віддай!\nТягар гріховний Син Божий зняв з нас,\nРаз назавсіди Спаситель спас.\n\nКуплет 2\nТепер ми вільні - нема осуду,\nХристом спасенні, з Ним жити будем.\n«Прийдіть до Мене!» - звучать слова:\n«Я відкупив вас кров’ю хреста».\n\nКуплет 3\nБожі ми діти, - То наша слава!\nВся честь Христові, хвала й держава!\nВ життя від смерті ми перейшли:\nНаше спасіння в Христі знайшли.', '', '', 'ua', NULL, 0, NULL, NULL),
(797, 278, 'Любий Спасе будь зі мною', 0, 'Куплет 1\nЛюбий Спасе, будь зі мною, як покриє тьма мене,- \nВ час, як бурхають зла хвилі, дай й тоді любить Тебе!\n\nПриспів: \nСпасе мій, Тебе я люблю (більш і більш),\nІ буду любити більш, (більше я люблю),\nЯк ввійду в небесну славу, (в місто святе),\nВ місто, де Ти Сам живеш.\n\nКуплет 2\nСпасе мій, Тебе я люблю і до Тебе ближче йду,\nБо не маю тут нікого, Хто б так близько мене був.\n\nКуплет 3\nЯ буду Тебе любити в час моєї праці тут, - \nЗнаю, що як буду вірний, то в Небесний Дім ввійду.\n\nКуплет 4\nЗадля Тебе я покинув всі розкоші в світі цім \nІ тепер живу для Тебе, хочу бути вже Твоїм.', '', '', 'ua', NULL, 0, NULL, NULL),
(798, 279, 'Коли в житті момент важкий', 0, 'Куплет 1\nКоли в житті момент важкий, й стискає серце жаль,\nТоді в молитві я святій всю виявлю печаль. (2р.)\n\nКуплет 2\nЄ сила благодатная в її словах живих,\nТаємна, життєдайная свята краса у них. (2р.)\n\nКуплет 3\nЗ душі тягар мов скотиться, і зникне десь сумнів,- \nІ вірить, плакать хочеться... І легко так мені!...', '', '', 'ua', NULL, 0, NULL, NULL),
(799, 280, 'Так як пташка утомлена', 0, 'Куплет 1\nТак, як пташка утомлена з ворогами в боротьбі,\nЯк овечка заблукана, так і я, о Боже мій!\n\nПриспів: \nХто б мені (хто б ті крила дав),\nХто б мені дав крила (хто б ті крила дав)\nГолуба (як крила у голуба), (2р.)\nЯ б полетів, полетів,\nПолетів би і заспокоївся;\nЯ б полетів на Голгофу (я б полетів)\nЯ б полетів на Голгофу \nІ там (знайшов би я) спокій.\n\nКуплет 2\nМов червяк, що крильця жде, щоб злетіти від землі,\nЯк невільник, що волі жде, так і я, о Боже мій!\n\nКуплет 3\nЯк ріка, що все пливе поміж піль, лугів, лісів, -  \nЗ тьмою світло у боротьбі, так і я, о Боже мій!', '', '', 'ua', NULL, 0, NULL, NULL),
(800, 281, 'Прагне правди народ', 0, 'Куплет 1\nПрагне правди народ, світла радості жде...\nСкільки душ ще у тьмі погибає!\nЛиш Спаситель Христос в світ спасіння приніс:\nІз неволі народ свій спасає.\n\nКуплет 2\nВін всі рани зцілить, від злих сил захистить.\nВіддалить і журбу, і страждання. \nСонце правди зійде, любов Божа прийде, -\nВ пісню радості змінить ридання.\n\nКуплет 3\nБраття й сестри, ідіть, вість спасіння несіть,\nЗ тьми гріховної народ спасайте!\nСвоє серце Христу і душі всю красу \nДля свободи людей ви віддайте.\n\nКуплет 4\nВ світі - гріховний вир, звістіть людям всім мир \nІ засмученим слово відради:\nЩо Спаситель воскрес, - двері слави небес \nВідчинив Всім шукаючим правди.\n\nКуплет 5\nВ Царство Боже ввійдем, радість вічну знайдем,\nТам не буде в насильстві людина:\nТам братерство святе всіх людей обійме,\nБудуть жити, як одна родина.', '', '', 'ua', NULL, 0, NULL, NULL),
(801, 282, 'Укрий своє горе', 0, 'Куплет 1\nУкрий своє горе від людських очей:\nСліз в світі багато і горя в людей.\nІди та подумай в нічную пору,\nСкажи твоє горе Ісусу Христу.\n\nКуплет 2\nХристос усе знає у горю твоїм, - \nТебе Він утішить на лоні Своїм.\nСвіт Божий сіяє на нашім путі;\nМи тим, що в темряві, те світло несім.\n\nКуплет 3\nСерця так страждають в неволі й нужді,\nІди із любов’ю, - утішиш їх ти.\nУкрий свої сльози, дай радість усім,\nШукай в Христі втіхи у горю твоїм!', '', '', 'ua', NULL, 0, NULL, NULL),
(802, 283, 'Тебе я славлю Спасе мій', 0, 'Куплет 1\nТебе я славлю, Спасе мій, всім серцем і життям,\nІ пісня радості й хвали наповнить хай уста!\n\nПриспів: \nО, кров Христа мене спасла (Зр.)\nІ все нове дала. І Нове, (все нове)! (2р.)\nО, кров Христа мене спасла і все нове дала!\n\nКуплет 2\nТомилась все душа моя, коли я жив у тьмі.\nТепер же хай звучить хвала Тобі, о Спасе мій!\n\nКуплет 3\nТяжке життя було в гріхах, тепер спасен вже я: \nОбмитий кровію Христа, о, як щасливий я!', '', '', 'ua', NULL, 0, NULL, NULL),
(803, 284, 'Утіху небесную для сердець', 0, 'Куплет 1\nУтіху небесную для сердець\nНам послав Отець, (2р.)\nДля радості нині зібрав Він нас, - \nЧесть Йому за втішний час!\n\nПриспів: \nВсім привіт, (всім привіт)! (2р.)\nБраттям, сестрам всім привіт, (всім привіт)! \nБог відкрив (відкрив нам)\nСвітлий край (світлий край).\nБудем радуватись в Нім!\n\nКуплет 2\nВ зібранні спасенних в Ім’я Його \nІсус буде Сам: (2р.)\nВін хоче, щоб з Ним вічний наш союз \nВ благодаті все зростав.\n\nКуплет 3\nУтіхи тієї не знає світ,\nЩо Господь нам дав. (2р.)\nМолитись ми будем, щоб Він, Благий,\nВічно з нами пробував.', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(804, 285, 'Дорогі нам хвилини', 0, 'Куплет 1\nДорогі нам хвилини Господь дарував,\nЛюбі браття і сестри в Христі!\nСам Господь з нами є, як Він нам завіщав,\nЙому даймо в серці простір!\n\nКуплет 2\nО, як радісно стрінутись з вами, брати.\nІ неспокій забувши зовсім,\nВеселитися разом у Дусі Святім,\nВ Господнім єднанні усім.\n\nКуплет 3\nВ Край Небесний ми в світлі Христовім ідем.\nВідпочинем, де Божий струмінь... \nПідкріпім свої сили і далі підем \nЗ Ісусом, як народ один.\n\nКуплет 4\nУ святому єднанні при Божих очах \nМи забули страждання путі:\nСвіжі сили знайшли у Господніх словах, \nЩоб сміло і радісно йти.\n\nКуплет 5\nМи в єднанні усі за Ісусом Христом,\nНа Начальника віри глядім, - \nЗодягнувшись у броню, під вірним щитом \nВперед, браття, дружно ідім!', '', '', 'ua', NULL, 0, NULL, NULL),
(805, 286, 'Ми ждемо Христа Спаса', 0, 'Куплет 1\nМи ждемо Христа-Спаса, як прийде, (2р.)\nМи ждемо Ісуса, що нам приготовив \nВідпочинок у Царстві Своїм.\n\nКуплет 2\nМи стрінем Христа-Спаса, як прийде, (2р.) \nМи стрінем Ісуса, - Він руки простягне \nІ візьме нас, де Сам завіщав.\n\nКуплет 3\nПобачать Його в славі, як прийде, (2р.) \nПобачать Ісуса і ті, що розп’яли,\nІ цілий світ заплаче тоді.\n\nКуплет 4\nО, друже, що ти скажеш, як прийде, (2р.) \nЯк Господь спитає, що зробив з талантом, \nЧи придбав що ним, чи закопав?\n\nКуплет 5\nЗаплачеш, друже, гірко, як прийде, (2р.)\nО, тобі, небоже, тоді не поможе,\nБо те місце сам ти заробив.', '', '', 'ua', NULL, 0, NULL, NULL),
(806, 287, 'Де згода в сімействі', 0, 'Куплет 1\nДе згода в сімействі, там мир і тишина; \nЩасливі там люди, блаженна сторона: \nЇх Бог благословляє, добро їм посилає \nІ з ними ввік живе, і щастя їм дає.\n\nКуплет 2\nДе згоди немає, там мир не царить:\nТам Бог не вітає, добра їм не дарить... \nРуйнуються пожитки: Добро їх, їхні дітки \nВсе марно пропаде... все марно пропаде!', '', '', 'ua', NULL, 0, NULL, NULL),
(807, 288, 'Христос вийшов з храму', 0, 'Куплет 1\nХристос вийшов з храму з учнями Своїми,\nІ сів на Оливній горі, -\nСкорбними словами, святими устами\nУчив своїх любих друзів.\n\nКуплет 2\n«Скажи нам, Учитель, останнєє слово,\nЩе доки Ти з нами живеш,\nСкажи нам, Учитель, Коли те все буде,\nКоли Ти судити світ прийдеш?» -\n\nКуплет 3\n- У світі почуєте чутки воєнні,\nБо встане народ на народ,\nІ будуть недуги, і голод, і помір,\nІ братськая кров потече.\n\nКуплет 4\nІ зменшиться віра, погасне надія,\nВ серцях охолоне любов,\nІ многії люди тоді поблазняться,\nПроллють неповинную кров.\n\nКуплет 5\nКоли ви гидоту побачите в храмі,\nТо знайте, що Суд при дверях,\nВважайте, щоб двері для вас не закрились,\nДержіть ви світильники в руках.\n\nКуплет 6\nВеликеє горе охопить всю землю,\nІ страшнії муки прийдуть, \nТоді скажуть люди; «Падіть на нас гори!»\nТа гори на них не впадуть.\n\nКуплет 7\nУ тії хвилини бажатимуть смерті,  \nТа смерть від людей відбіжить...\nІ хто в той час буде на даху, чи в полі, \nНехай він додому не спішить.\n\nКуплет 8\nІ сонце померкне, не дасть місяць світла,\nІ зорі із неба спадуть;\nІ мертві воскреснуть, земнії народи\nПрийдуть на Божественний Суд.\n\nКуплет 9\nЗ небес прийде в славі Син Божий на землю \nІ буде, як сонце, сіять;\nІ зібрані діти побачать Ісуса,\nІ в радості будуть стрічать.', '', '', 'ua', NULL, 0, NULL, NULL),
(808, 289, 'Хто підійме свій зір', 0, 'Куплет 1\nХто підійме свій зір на Христа на хресті,\nТой одержить спокій для душі.\nДруже мій! Ось поглянь, як Він світ полюбив: \nНа хресті Він за тебе терпів.\n\nПриспів: \nГлянь, глянь, друже, глянь!\nГлянь на рани Христові \nЙ терновий вінець,\nІ пізнай, як Він любить тебе.\n\nКуплет 2\nВід загрози і суду тебе увільнив,\nІ від смерті тебе відкупив.\nСмерть! Де жало й держава твойого буття? Пекло! Де перемога твоя?\n\nКуплет 3\nТемна хмара кругом, смуток душу вповив \nІ стражданнями серце прибив.\nАле глянь на Христа: Він в проміннях сія, \nПравда вічна у Нім і життя.\n\nКуплет 4\nО, чому ж у твоїх невідкритих очах \nВсе байдужість до правди і жах?\nДруже! Глянь на Христа ти в надії живій \nІ одержиш спасіння душі.', '', '', 'ua', NULL, 0, NULL, NULL),
(809, 290, 'Бог з тобою до побачення', 0, 'Куплет 1\nБог з тобою, до побачення!\nПуть твій хай охороняє; \nКожний крок хай направляє, - \nБог з тобою, до побачення!\n\nПриспів: \nДоки (стрінемся) ми зустрінемся,\nМи стрінемся в ногах Христа (стрінемся) \nДоки (стрінемся) ми зустрінемся, - \nБог з тобою, до побачення!\n\nКуплет 2\nБог з тобою, до побачення!\nДушу Він хай підкріпляє,\nСилу з неба посилає, - \nБог з тобою, до побачення!\n\nКуплет 3\nБог з тобою, до побачення!\nВін -рятунок у скорботах, \nВ Нім життя твоє укрите, -\nБог з тобою, до побачення!\n\nКуплет 4\nБог з тобою, до побачення!\nНа Христа ти все дивися,\nУ любві Його трудися, - \nБог з тобою, до побачення!', '', '', 'ua', NULL, 0, NULL, NULL),
(810, 291, 'О який нам путь відкрився', 0, 'Куплет 1\nО, який нам путь відкрився, щоб ним в Царство Боже йти: \nБожий Син з небес явився, щоб і нас туди ввести.\nВ світі горя Він родився, правди вчив, усім служив,\nУ любві для всіх трудився, був розп’ятий - і ожив.\n\nКуплет 2\nЗ гробу вставши, Він являвся учням своїм сорок днів, \nІ Тома переконався, оглядівши рани сам. \nЇм послать Святого Духа завіщав, щоб прийняли,- \nІ Його голгофські муки плід прекрасний принесли.\n\nКуплет 3\nІ зібрав Христос на гору всіх апостолів Своїх,\nПеред їх відкритим зором Він вознісся там від них.\nТут два мужі їм явились і сказали: «Цей Ісус,\nЩо на Нього ви дивились, прийде вдруге ще на Суд!»', '', '', 'ua', NULL, 0, NULL, NULL),
(811, 292, 'Будьте пильні', 0, 'Куплет 1\nБудьте пильні завжди і моліться:\nСкоро наш Господь прийде;\nВін лиш тих візьме у Край Небесний,\nХто Його в молитві жде.\n\nПриспів: \nВір, молись уже недовго,\n(Вір, молись, надійсь на Бога 2р.)\nВір, молись, - Господь велить,\n(Вір, молись, - Господь велить 2р.); \nСкоро Він прийде у славі,\n(Скоро Він прийде у славі (2р.),\nНас візьме, - з Ним будем жить.\n(Нас візьме, з Ним будем жить 2р.)\n\nКуплет 2\nБудьте пильні завжди і моліться!\nВорог правди все не спить,\nВ броню праведності зодягніться.\nІ візьміть ви віри щит.\n\nКуплет 3\nБудьте пильні завжди і моліться!\nБог спасе від всіх гріхів,\nВ силі Божій Духом підкріпіться,\nСтійте твердо в боротьбі.\n\nКуплет 4\nБудьте пильні завжди і моліться!\nБог ласкаво вчує вас,\nНа Ісуса з вірою дивіться, - \nВін поможе в кожний час.', '', '', 'ua', NULL, 0, NULL, NULL),
(812, 293, 'Я подорожую тут', 0, 'Куплет 1\nЯ подорожую тут на цій землі,\nЗ кожним днем зближаюсь я до Вітчизни, \nХрест несу щоденно на своїх плечах,\nІду до Вітчизни в святих Небесах.\n\nКуплет 2\nА коли я прийду до небес святих, - \nВ зустріч мені вийде небесний Жених, \nВийде стрічати, мене вітати там у воротах, \nХрест Він з мене здійме і до Себе прийме \nВ святих небесах.\n\nКуплет 3\nВузька і терниста дорога моя:\nЧерез густі терни пробираюсь я,\nІ каміння гострі на путі лежать,\nТерни і каміння все тіло ранять.\n\nКуплет 4\nА коли я прийду і т.д.\nВін рани загоїть, мене успокоїть \nВ святих небесах.\n\nКуплет 5\nГоре та недолю зустрічаю я \nІ часто сльозами заливаюся,\nТа лише надія веселить мене,\nЩо в моїй країні горя не буде.\n\nКуплет 6\nА коли я прийду і т.д.\nУтре мої сльози, змінить в радість горе \nТам у небесах.\n\nКуплет 7\nНавкруг себе бачу я хижих вовків,\nІ часто стрічаю я голодних львів.\nО, як небезпечна дорога моя, - \nДля борні готовим мушу бути я.\n\nКуплет 8\nА коли я Прийду і т.д.\nИ пісню перемоги дасть Він нам навіки \nТам у небесах.\n\nКуплет 9\nЧасто я знаходжусь на вершині скал,\nЧасто зустрічаю ураганів шал:\nРевуть страшні бурі і буйні вітри,\nХотіли б в безодню все мене звести.\n\nКуплет 10\nТа коли я прийду і т.д.\nВізьме нас з Собою, введе в край спокою,-  \nТам, де тишина.', '', '', 'ua', NULL, 0, NULL, NULL),
(813, 294, 'Вождь Христос могутній', 0, 'Куплет 1\nВождь Христос могутній в битву нас веде,\nІ нам з Ним не страшно, Він вперед іде.\nЦіль Його висока в мудрості святій,\nСміло з Ним ідемо в бій.\n\nПриспів: \nСміло! Сміло! Так нам Бог велить!\nСміло! Сміло! -Він нас підкріпить;\nРадо й мило - хай наш спів звучить:\nЛиш перемагати - Спас велить.\n\nКуплет 2\nХай наше знамено розвівається, \nЗло Христовим словом подолається.\nНаш Господь Спаситель впокорить цей світ,\nІ за Ним ми йдемо вслід.\n\nКуплет 3\nХоч страшна ще битва, та скоро кінець...\nВірним нагороду готовить Отець:\nДасть нам відпочинок у Царстві Своїм,\nКоли йдемо вслід за Ним.', '', '', 'ua', NULL, 0, NULL, NULL),
(814, 295, 'О предвічний Цар Єгова', 0, 'Куплет 1\nО, предвічний Цар Єгова! Путь в пустині освіти,\nІ втомленого, слабого подорожнього веди.\n\nПриспів:\nХліб небесний, (2р.) дай нам, Боже,\nДушу підкріпляй (підкріпляй),\nДай нам (хліб небесний), (4р.) \nХліб небесний, і ним душу підкріпляй!\n\nКуплет 2\nХай струмінь води живої нам поллється із скали;\nХай горить в час тьми нічної світло слів Твоїй Святих.\n\nКуплет 3\nПереміг Христос тьми силу, в небесах Йому хвала.\nЯ стою біля Йордану, а за ним - завітний Край.\n\nКуплет 4\nТут Вождя я дожидаю, - скоро знову Він прийде,\nІ в небесну вічну славу Сам Христос мене введе.', '', '', 'ua', NULL, 0, NULL, NULL),
(815, 296, 'О Ісус укрий мене', 0, 'Куплет 1\nО, Ісус, укрий мене в тіні крил спасіння:\nНа хресті Ти умирав, щоб нам дать прощення.\n\nПриспів:\nНа хресті, на хресті Спас нам дав прощення;\nЯ знайшов в ногах Христа для душі спасіння.\n\nКуплет 2\nПри хресті душа моя мир знайшла небесний, \nI Зоря проміння ллє в серце світло ясне.\n\nКуплет 3\nПри хресті, о Боже мій, пошли мені сили,\nЩоб Тобі служить я міг вірно до могили!', '', '', 'ua', NULL, 0, NULL, NULL),
(816, 297, 'Дорожчим за все є Христос', 0, 'Куплет 1\nДорожчим за все є Христос для мене:\nЗагине багатство земне;\nЗнайшов у Христі я багатство моє, - \nЩасливий я з Ним над усе.\n\nПриспів: \nЩасливий я всюди з Христом! (2р.)\nЗневажений в світі, я можу сказать: \nЩасливий я завжди з Христом!\n\nКуплет 2\nЯ грішник великий, осуджений був,\nБез Божого Слова блукав,\nСпаситель прийшов, - мене спас, оправдав: \nНасліддя у вічності дав.\n\nКуплет 3\nЛиш жертва одна була в силі спасти\nІ з Богом мене примирить:\nТо мій Відкупитель - за мене Він вмер, \nЩоб з Ним я повіки міг жить.\n\nКуплет 4\nПризвав, научив, правди путь показав \nІ в серце спокій мені дав; \nМолитись Він учить і в світлі ходить,\nЗавіт Його в серці носить,\n\nКуплет 5\nХоч навіть і рідні покинуть мене,\nІ всього лишусь на землі, -  \nХристові віддавсь я, Він любить мене, \nНавік я укриюся в Нім.', '', '', 'ua', NULL, 0, NULL, NULL),
(817, 298, 'О Ісус достоєн Ти', 0, 'Куплет 1\nО, Ісус, достоєн Ти слави й честі на землі,\nСлави й честі на землі від нас;  \nІ від серця повноти я співаю все Тобі,\nБуду всюди славити Тебе.\n\nПриспів: \nХорони у світі нас (2р.)\nДай у Тобі пробувать (2р.,)\nПідкріпляй нас в кожний час (2р.)\nЩоб Тебе лиш прославлять! (2р.)\n\nКуплет 2\nТи життя нам дарував, світлом правди осіяв,\nМир небесний в серце нам послав;\nТи нас кровію обмив, наші всі гріхи простив.\nНаші всі гріхи Ти нам простив.\n\nКуплет 3\nТи гріхи мої простив, Свою милість проявив, \nСвою милість проявив до нас:\nТи хорониш в кожний час, утішаєш Духом нас, \nДухом Правди утішаєш нас.', '', '', 'ua', NULL, 0, NULL, NULL),
(818, 299, 'Радуйтесь браття', 0, 'Куплет 1\nРадуйтесь, браття, і в піснях духовних, \nСлаву і честь віддавайте Христу:\nВін нас знайшов всіх в неволі гріховній,\nВін об’явив нам любві повноту, (2р.)\n\nКуплет 2\nО, як безмірно нас любить Спаситель! \nОхороняє нас в житті земнім,\nВін приготовив нам святі оселі \nІ нагородить вінцем золотим. (2р.)\n\nКуплет 3\nЗ радістю, браття, за Слово Господнє \nВсякі знущання смиренно терпім:\nБог підкріпить нас на нашій дорозі,\nВ славу введе нас у Царстві Своїм. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(819, 300, 'Ой чого так плачеш', 0, 'Куплет 1\n- Ой, чого так плачеш, душе утомлена?\nЧи з путі ти збилась, чи любов завмерла?\n- Я з путі не збилась, любов не завмерла,\nТільки опізнилась, бо була невірна.\n\nКуплет 2\n- Не дивись за братом, дивись за собою,\nНе гонись за прахом, утішайся Бого.\nБо земная слава - для душі отрута, \nХто з нею спізнався, той з Богом розстався.\n\nКуплет 3\nДуховнії хори ти любила слухать,\nА чужі обряди твою душу мучать.\nДуше, пробудися, бо світло явилось,\nПоспішай назустріч, та й не опізнися.\n\nКуплет 4\nЛюди повставали, стають до роботи, \nПрацюють для Бога з доброї охоти.\nА ліниві люди не хочуть робити,\nІ Господу Богу, не хочуть служити.\n\nКуплет 5\nА ви, браття, сестри, в зібрання ходіте,\nУтішайтесь Словом, та й Бога любіте.\nБо хто Бога любить, той Йому і служить,\nА хто Йому служить, того Бог полюбить.\n\nКуплет 6\nО, яка то радість Богові служити,\nА після на небі вічно з Богом жити!', '', '', 'ua', NULL, 0, NULL, NULL),
(820, 301, 'Я славлю все Ісуса', 0, 'Куплет 1\nЯ славлю все Ісуса: Він душу спас мою,\nЗа всі мої провини пролив Він кров Свою.\nЯ славлю все Ісуса! Він на хресті вмирав,\nІз темряви страшної Він Сам мене підняв.\n\nКуплет 2\nЯ славлю все Ісуса! Втішає Він мене,\nУ Край, де вічна радість; Він Сам мене веде. \nЯ славлю все Ісуса за всі Його діла,\nЯ славлю милість Божу: вона мене спасла.\n\nКуплет 3\nЯ славлю все Ісуса в долині тут земній,\nІ вірю, буду жити, де Відкупитель мій;\nТам, в царстві всіх спасенних, я буду прославлять \nСпасителя Святого безмірну благодать.', '', '', 'ua', NULL, 0, NULL, NULL),
(821, 302, 'Не залишу ніколи', 0, 'Куплет 1\nНе залишу ніколи Святої Біблії:\nВ Христі спасіння вічне дає вона мені.\n\nПриспів:\nНізащо, нізащо я Біблії не залишу,\n(Нізащо я Біблії не залишу, Біблії не залишу).\nНізащо, нізащо цеї Книги Божої,\n(Нізащо не залишу цеї святої Книги Божої).\n\nКуплет 2\nКоли я у спокусі буваю іноді, - \nВона мене навчає, підтримує й тоді.\n\nКуплет 3\nКоли човен мій хвилі в життєвім морі б’ють,\nЯ в Біблії знаходжу єдиний світлий путь.\n\nКуплет 4\nЯ їй лиш довіряю, знаходжу в ній Христа,- \nВ Нім сяє Сонце Правди й любові повнота.', '', '', 'ua', NULL, 0, NULL, NULL),
(822, 303, 'Небо і земля', 0, 'Куплет 1\nНебо і земля (2р.) нині торжествують,\nАнгели й люди (2р.) весело святкують,\n\nПриспів: \nХристос родився, Бог воплотився,\nАнгели співають, славу звіщають, \nПастухи вітають, поклін складають, \n«Чудо! Чудо!» - повідають.\n\nКуплет 2\nУ Віфлеємі (2р.) весела новина:\nПречиста Діва (2р.) породила Сина.\n\nКуплет 3\nВітцівське слово (2р.) зодяглося в тіло,\nВ темряві земній (2р.) Сонце засвітило.\n\nКуплет 4\nАнгели служать (2р.) Господеві своєму,\nСпівають: «Слава!» (2р.) Ново родженому.\n\nКуплет 5\nТри володарі (2р.) зі Сходу приходять,\nЛадан і миро (2р.), й золото приносять.\n\nКуплет 6\nМесії своєму (2р.) ті дари складають;\nПастирі людям (2р.) новину звіщають.\n\nКуплет 7\nЙого ми нині (2р.) також величаймо:\n«Слава на небі, і мир на землі!» Йому заспіваймо.', '', '', 'ua', NULL, 0, NULL, NULL),
(823, 304, 'Нині радість стала', 0, 'Куплет 1\nНині радість стала, яка не бувала:\nНад вертепом зоря ясна світові засяла.\n\nКуплет 2\nТам Христос родився, з Діви воплотився,\nЯк людина пеленками вбогими вповився.\n\nКуплет 3\nАнгели співають, Христа величають,\nВсім народам цю чудову Новину звіщають.\n\nКуплет 4\nМи також співаймо, Спаса прославляймо,\nВід Марії Родженому хвалу й честь віддаймо!', '', '', 'ua', NULL, 6, '2021-01-06', NULL),
(824, 305, 'Спас від Діви народився', 0, 'Куплет 1\nСпас від Діви народився, | прийшов днесь Він з небес, \nЩоб спасти люд свій весь, - і світ втішився | (2р.).\n\nКуплет 2\nВ Вифлеємі народився | Ісус Спас - Пастир наш,\nПравди Цар із небес нам об’явився | (2р.).\n\nКуплет 3\nСповістив це ангел Божий уночі пастирям, \nМудрецям-звіздарям - зі Сходу царям | (2р.).\n\nКуплет 4\nЩо за чудо це з’явилось: | де Марія Христа \nВповила, там зоря прийшла і стала | (2р.).\n\nКуплет 5\nІз дарами три царі йдуть | до міста Вифлеем\nІ Народженому поклін віддають | (2р.).\n\nКуплет 6\nХвалу і ми заспіваймо, | і Народженому \nБогові і Царю поклін віддаймо | (2р.).', '', '', 'ua', NULL, 0, NULL, NULL),
(825, 306, 'Хай буде Творцеві від нас честь хвала', 0, 'Куплет 1\nХай буде Творцеві від нас честь, хвала!\nГосподня любов нас від смерті спасла.\n\nПриспів: \nАлілуя! Честь і слава, алілуя повік.\nАлілуя! Честь і слава. Бог з нами. Амінь.)\n\nКуплет 2\nСпасителю наш, Тобі слава й хвала!\nБо в Тобі дар спасіння людині знайшла.\n\nКуплет 3\nНаш Отче небесний! У Дусі Святім \nПрославляйся й веди нас у вічний Свій Дім!', '', '', 'ua', NULL, 0, NULL, NULL),
(826, 307, 'Благодать Господа', 0, 'Куплет 1\nБлагодать Господа Ісуса Христа і любов \nБога Отця, та єднання Святого Духа,\nХай буде з нами. Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(827, 308, 'Збудись від сну', 0, 'Куплет 1\nЗбудись від сну, мій дух! Свій страх марний відкинь: \nХристос - твій вірний Друг, страждав за тебе Він, \nЗаступником твоїм Він став, - \nВ небесній книзі записав. (2р.)\n\nКуплет 2\nПоглянь, Спаситель твій за тебе так страждав! \nЩоб ти з Ним вічно жив, Свою Він кров пролляв. \nХристос нас кровію обмив,\nНове життя в нас відродив. (2р.)\n\nКуплет 3\nСпаситель в небесах вже в славі у Отця,\nБлагає Він за нас Предвічного Творця...\nЗ неволі всіх Він відкупив,\nНас, грішних, з Богом примирив. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(828, 309, 'О якби ти це знав', 0, 'Куплет 1\nО, якби ти це знав хоч в цей останній день,\nЩо ти за світло дня прийняв лиш тільки тінь.\n\nПриспів:\nКоли б же ти пізнав хоч в цей останній день,\nЩо може дать тобі спокій, - одне, що дасть тобі спокій!\n\nКуплет 2\nО, якби ти це знав, що путь, якою йдеш,\nВеде в безодню — й там ти смерті не минеш.\n\nКуплет 3\nО, якби ти це знав - Хто, повний дивних слів,\nТебе до Себе звав, - прийти ж ти не хотів.\n\nКуплет 4\nО, якби ти це знав, Хто про тебе скорбить,\nЩо ти у гріх упав, - не хочеш в правді жить.\n\nКуплет 5\nО, якби ти пізнав, Хто полюбив тебе,\nХто за тебе віддав на смертний хрест Себе.\n\nКуплет 6\nО, якби ти пізнав Його - Царя душі!\nВ Нім Бог любві сія для тебе й для усіх.\n\nКуплет 7\nО, якби ти пізнав, що Всемогутній Він,\nЗ мольбою б ти упав й смирився перед Ним.', '', '', 'ua', NULL, 0, NULL, NULL),
(829, 310, 'Пастир все шукає', 0, 'Куплет 1\nПастир все шукає бідную вівцю,\nЩо десь заблудилась: жаль її Йому.\n\nПриспів: \nКличе тебе, кличе тебе,\nХоче Господь спасти тебе.\n\nКуплет 2\nДрахма дорогая згублена була,\nВ поросі прикрита, - знов віднайдена.\n\nКуплет 3\nРадість з Ним ділити всіх Отець зове:\nБлудний син вернувся і тепер живе.', '', '', 'ua', NULL, 0, NULL, NULL),
(830, 311, 'В дикій пустині', 0, 'Куплет 1\nВ дикій пустині безрадно я \nВ смутку проводжу мої літа.\nВ голоді ходжу чужий усім... \nВстану, піду в свій дім! \nХоч сором до Отця йти у дім,\nЩо був колись мені рідний він;\nРад би я стати слугою в нім, - \nВстану, піду в свій дім!\n\nПриспів: \nСерце стремить в рідний дім (Отця), \nВстану, піду в Отчий дім \nТам мій Отець! Піду, (піду!)\nВ рідний мій дім до Отця.\n\nКуплет 2\nЧого ще тут пропадаю я?  \nЖиття немає на чужині!  \nА в домі ріднім - усе там є;\nВстану, піду в свій- дім!\nТяжко я проти Отця згрішив. \nВина моя на мені тяжить. \nХочу признатись, чим провинив.\nВстану, піду в свій дім!\n\nКуплет 3\nО, Боже мій, куди ж я пішов?\nУсі достатки я в Батька мав.\nСам своє щастя я змарнував!...\nВстану, піду в свій дім!\nВ думках я бачу мій рідний дім, - \nЛюбі обличчя у домі тім.\nЩасливий був я Поміж друзів.\nВстану, піду в свій дім!\n\nКуплет 4\nОтець ласкавий прощає всім, - \nПрийме й мене хоч слугою в дім.\nЧого ж ще жду, чого гаюсь я?\nВстану, піду в свій дім!\nЩось то все каже: «Він не забув;\nХоч непослушний Йому ти був, - \nВін тебе любить... Хутчій, хутчій!\nВстань і іди в свій дім!»', '', '', 'ua', NULL, 0, NULL, NULL),
(831, 312, 'Радість радість Бог дарує', 0, 'Куплет 1\nРадість, радість Бог дарує, серце, наше веселить, -  \nПромінь щастя, що від Бога, в нас ніщо вже не вгасить!.\n\nКуплет 2\nБог нас Сам веде за руки, підкріпляє в боротьбі, \nНас хоронить від спокуси, помагає у біді.\n\nКуплет 3\nПо слідах підем Христових ми під захистом Його, \nЩоб у битвах всіх суворих не загинуть без Нього\n\nКуплет 4\nРадість віри нехай сяє і, як сонце, в нас горить!\nГрішних Спас лиш визволяє і добром усіх дарить.', '', '', 'ua', NULL, 0, NULL, NULL),
(832, 313, 'Ах радість радість', 0, 'Куплет 1\nАх, радість, радість буде там відкупленим серцям, \nКоли закінчим путь свою і будем там, в раю.\nРосте там дерево життя, де вічна неземна краса,\nІ там Гопцодь Спаситель мій царить в любві Своїй.\n\nПриспів:\nАх, що за радість там, радість там, радість дам!.\nАх, що за рад|сть там спасенним буде нам,\nДе всі святії без числа хвалу приносять для Христа!\nІ ми співати там будем, коли туди Прийдем;\n\nКуплет 2\nДорога вузька лиш одна для нас призначена;\nКоли ми нею не підем, спасіння не знайдем.\nКоли ж дорогу ту пройдем, що часто сльози на ній ллєм, \nТо там будем в любві Творця щасливі без кінця.\n\nКуплет 3\nХристос Воскрес,- розсіяв страх і ось,ввеликий час \nВ чудових світлих небесах Він дожидає нас.\n0, любий друже, пам’ятай, що є блаженства вічний край! \nХоч тяжко, трудно в світі нам, та радість буде там.', '', '', 'ua', NULL, 0, NULL, NULL),
(833, 314, 'Сказав Господь', 0, 'Куплет 1\nСказав Господь Бог до Ноя: «Я затоплю світ водою \nВ близький час. (4р.)\n\nКуплет 2\nТи ж збудуй собі ковчега для родини і для себе,  \nЩоб спастись». (4р.)\n\nКуплет 3\nНой повірив, - не вагався, будувати ковчег взявся \nВ той же час. (4р.)\n\nКуплет 4\nЛюди Ноя висмівали, - слова правди не приймали: \nГрішний люд... (4р.).\n\nКуплет 5\nПотоп хлинув, як те море, - люди бігли всі на гори, \nТам спастись. (4р.)\n\nКуплет 6\nВоди землю заливали, тоді люди вже благали:\nДе спастись? (4р.)\n\nКуплет 7\nВсі на себе нарікали, чому правди не прийняли:\nГнів прийшов. (4р.)\n\nКуплет 8\nПташки в небі ще літали і рятунку скрізь шукали, \nНе знайшли. (4р.)\n\nКуплет 9\nВоди землю всю покрили, всіх безбожних затопили: \nБожий суд. (4р.)\n\nКуплет 10\nЛише плавав над водами ковчег з Ноєм і синами \nВ хвилях тих... (4р.)\n\nКуплет 11\nЯк ковчег став на вершині,\nЗ Ноєм вийшла вся родина, - | всі спаслись. (4р.)\n\nКуплет 12\nТак, як було за днів Ноя,\nВсім безбожним гірка доля | знов прийде... (4р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(834, 315, 'Вище світил небесних', 0, 'Куплет 1\nВище світил небесних, де тьми нема,\nВ тіні дерев чудесних наш Край є там.\nТам зла уже немає, спів ангельський луна;\nВ небесній вічній славі Христос сія.\n\nКуплет 2\nЗа нас тяжкі страждання Ісус терпів.\nІ наше осудження Він кров’ю змив.\nІ смерть Спаситель хресну прийняв від грішних рук, \nПридбав для нас спасіння від вічних мук.\n\nКуплет 3\nІ вас давно Спаситель усіх зове,\nВ небеснії оселі він нас введе.\nЩасливий, хто почує святий Його призив:\nГосподь його обмиє від всіх гріхів.', '', '', 'ua', NULL, 0, NULL, NULL),
(835, 316, 'Xриста славте', 0, 'Куплет 1\nXриста славте! Він наш великий Спаситель,\nСпівай, земле, все про любов святу.\nСлавте, славте Його, архангели Божі,\nЧесть віддайте ви за любов Йому.\nВін, як Пастир, дітей Своїх хоронить,\nІ Він носить їх на руках Своїх;\nВірні всі, що з Богом живуть на Сіоні,\nСлавте, славте у піснях радісних.\n\nКуплет 2\nХриста славте! Він наш великий Спаситель,\nВін за гріх наш постраждав на хресті.\nВін Скала й надія вічного спасіння:\nСлавте, славте Ісуса всі святі.\nВін за нас всіх терпів тяжкі страждання,\nВінець з терну Він на чолі носив;\nЗневажений, переніс Він всі знущання.\nРаз навіки Спаситель переміг.\n\nКуплет 3\nХриста славте! Він наш великий Спаситель.\nІ «Осанна» - звучить чудовий спів.\nНаш Спаситель царює в славі повіки,\nЦар, Пророк і Первосвященик Він.\nПереміг смерть! - з радістю сповіщайте.\nСмерть, де ж перемога тепер твоя?...\nВін Воскрес, - вже смерті окови не страшні:\nНаш Спаситель для всіх життя придбав.', '', '', 'ua', NULL, 0, NULL, NULL),
(836, 317, 'Було сказано нам', 0, 'Куплет 1\nБуло сказано нам про чудовий той Край,\nПро який учить нас Біблія. Де турбот вже нема,\nНі тяжкого труда, і нема там насильства вже!\n\nПриспів:\nВ тім прекраснім Краю, у небеснім раю,\nХмар грізних не буде уже;\nПройшла смерті тінь, настав вічний день,\nІ повік сонце не зайде!\n\nКуплет 2\nТам у райськім саді овочі золоті,\nВсе цвіте там, немов лілія. Там спасенні серця \nПрославляють Творця, де немає насильства вже!\n\nКуплет 3\nТам оселі для нас приготовив Христос,\nТак украшені, як скинія. Джерело там життя,\nПісня ллється свята, і нема там насильства вже!', '', '', 'ua', NULL, 0, NULL, NULL),
(837, 318, 'Дай що найкраще для Бога', 0, 'Куплет 1\nДай що найкраще для Бога, - силу для Нього віддай; \nЙому віддай всі спромоги і за Христом вслід вступай. \nВін приклад для нас залишив, сміло за правду стояв,\nІ тяжко за нас страждав Він, - у жертву життя віддав.\n\nПриспів: \nДай що найкраще для Бога,\nСилу для Нього віддай!\nЗ радістю йди на служіння - \nВсім про спасіння звіщай.\n\nКуплет 2\nДай що найкраще для Бога; в серце Його ти впусти,\nІ для служіння святого Йому усе присвяти.\nВесь на служіння віддайся: Він за нас Сина віддав; \nЖити для Нього старайся, - все, що найкраще - віддай!\n\nКуплет 3\nДай що найкраще для Бога, Він тобі більше вже дав:\nВ небі залишив всю славу, в жертву Себе Він віддав. \nСтраждав за нас Він безвинно, щоб від гріхів всіх спасти; \nДай Йому честь і хваління, все, що найкраще, віддай!', '', '', 'ua', NULL, 0, NULL, NULL),
(838, 319, 'О не лякайсь і не страшись', 0, 'Куплет 1\nО, не лякайсь і не страшись: Бог захистить тебе; \nДо Нього завжди ти молись, Бог захистить тебе.\n\nПриспів: \nБог захистить тебе в руках Своїх,\nВ путях твоїх, — Бог захистить тебе,\nБог захистить тебе, (спасе тебе).\n\nКуплет 2\nКоли прийдуть часи трудні, Бог захистить тебе. \nУ небезпеці та в біді Бог захистить тебе.\n\nКуплет 3\nВ біді Він вічний Друг є твій, Бог захистить тебе; \nВ сумнів не падай - в вірі стій, Бог захистить тебе.\n\nКуплет 4\nКоли спокуса тут прийде, Бог захистить тебе, - \nСвій захист Він тобі пошле, Бог захистить тебе.', '', '', 'ua', NULL, 0, NULL, NULL),
(839, 320, 'Я знаю що Христос Спаситель', 0, 'Куплет 1\nЯ знаю, що Христос Спаситель \nМісце мені приготував;\nЖиття відкрив для мене вічне,\nДитям Своїм мене назвав.\n\nПриспів: \nНіщо у світі цім мене\nВже від Христа не відійме.\n\nКуплет 2\nТепер Його я дожидаю,\nКоли за мною Він прийде,\nТоді візьме мене до Себе,\nУ Дім Небесний приведе.\n\nКуплет 3\nТому всім серцем довіряюсь,\nХто на хресті вмер за мене,\nДо Його зову прислухаюсь:\n«Скоріш прийди! Я жду тебе».\n\nКуплет 4\nЙoro любов усе здолала,\nВін так за мене постраждав,\nІ кров пролляв Свою невинну, - \nЖиття мені Він смертю дав.\n\nКуплет 5\nСпаситель мій прийде вже скоро\nІ Сам мене туди візьме,\nДе в Царстві правди, Царстві Божім \nМій дух навіки відпочне.', '', '', 'ua', NULL, 0, NULL, NULL),
(840, 321, 'Я пришлець в земній долині', 0, 'Куплет 1\nЯ пришлець в земній долині, все навколо - чужина,\nАле вище зір небесних - моя рідна сторона.\n\nПриспів: \nТам країна свята, там Вітчизна моя, - \nТам Отець мій благий, вся родина моя;\nВсі вони в рідній стороні,\nА я блукаю на чужині.\n\nКуплет 2\nТут насильство і неправда, скрізь ненависть і злоба, \nАле там край повний щастя: там любов царить свята.\n\nКуплет 3\nТут мене всі зневажають, ненавидять мене всі,\nАле там всі мене люблять в моїй рідній стороні.\n\nКуплет 4\nТут мене смерть ще лякає в тій похмурій чужині. \nЖиття вічне там чекає мене в рідній стороні.', '', '', 'ua', NULL, 0, NULL, NULL),
(841, 322, 'Волі Дух Кайдани тління', 0, 'Куплет 1\nВолі Дух! Кайдани тління із людських сердець здійми, \nДай, щоб дух усиновлення між Твоїми був дітьми.\n\nКуплет 2\nДух, що в день П’ятидесятий на апостолів зійшов, \nБлагодаттю Ти багатий - о, збудуй в нас Свій престол!\n\nКуплет 3\nУтішителю! В скорботі Ти утіху нам пошли,\nПоможи в Твоїй роботі, підкріпляй дітей Своїх.\n\nКуплет 4\nДай дари оздоровлення, дар пророчих дай нам слів,\nА найбільше дарування - нам пошли Ти дар любві.\n\nКуплет 5\nТи на вірних виливаєш благодать на благодать, - \nСвою Церкву укріпляєш, в ній Ти хочеш пробувать.\n\nКуплет 6\nДух любві Отця і Сина, нас, благаєм, оживи;\nХай зіллються всі в єдино у святих ділах любві.', '', '', 'ua', NULL, 0, NULL, NULL),
(842, 323, 'Не задля почесті і слави', 0, 'Куплет 1\nНе задля почесті і слави \nУ Край Небесний я стремлюсь.\nХоч шлях змагань важкий, кривавий - \nЯ все ж у вірі тій не гнусь,\n\nКуплет 2\nБо я сподвижник Твій і воїн,\nБо я за Тебе все в борні.\nЧи більша слава є від тої?\nЧи треба більшої мені?\n\nКуплет 3\nНе задля вічного спокою \nУ Край Небесний я стремлюсь;\nХоч і на шлях свій я з тугою \nІ сльози й піт нераз проллю,\n\nКуплет 4\nОдначе труд Твій - насолода \nДля духа дивна і свята, - \nНайвища серцю нагорода:\nВ ній спокій неба процвіта.\n\nКуплет 5\nНе задля благ обітування\nУ Край Небесний я стремлюсь;\nТи дав мені гріхів прощення,\nЙ те щастя дав,що я молюсь.\n\nКуплет 6\nВ нове життя мій дух покликав, \nЙого любов’ю осінив...\nО, як ця ласка є велика!\nПро це я й думати не смів.\n\nКуплет 7\nНе задля вічних втіх неземних \nУ Край Небесний я стремлюсь, - \nЛишень, щоб тут, в скорботах земних, \nВсе проявлять любов Твою.\n\nКуплет 8\nЛюбові пісня тут нерівна,\nІ часто рветься в пітьмі зла, - \nА там поллється в звуках дивних, \nЯк безконечная хвала.', '', '', 'ua', NULL, 0, NULL, NULL),
(843, 324, 'В час коли труба', 0, 'Куплет 1\nВ час, коли труба Господня \nНад землею прозвучить,\nІ як вічного дня ранок засія,\nІмена усіх спасенних Сам Ісус оголосить,\nТам по милості Господній буду я.\n\nПриспів: \nВ небесах з Христом я буду,\n(Там по милості Господній буду я),\nВ небесах з Христом я буду,\n(Там по милості Господній буду я).\nВ небесах (в небесах) з Христом я буду, \nТам по милості Господній буду я.\n\nКуплет 2\nВ день останній воскресіння \nВсіх померлих у Христі,\nВ день, коли введе спасенних в дім Царя,\nВсіх святих, омитих кров’ю,\nЩо пролив Він на хресті,\nВін покличе - і тоді відкликнусь я.\n\nКуплет 3\nДай нам сили працювати \nІ для ближніх послужить \nЗ ранку раннього і до заходу дня,\nА коли земну нам працю \nТи дозволиш закінчить,\nТо на поклик Твій небесний стану я.', '', '', 'ua', NULL, 3, '2021-03-21', NULL),
(844, 325, 'Отець мій багатий', 0, 'Куплет 1\nОтець мій багатий оселями,\nПолями, золотом і перлинами;\nВін скарби Всесвіту держить в руках,\nБагатства безмірні є в Нього для нас.\n\nПриспів: \nЯ наслідник Царя, наслідник Царя,\nЗ Христом Ісусом наслідник Царя.\n\nКуплет 2\nВсевишнього Син - Спаситель людей - \nВін жив на землі тут бідніше усіх,\nТепер в небесах - Заступник за нас;\nЯк прийде, мені Він оселю вже дасть.\n\nКуплет 3\nЗабутий я був на грішній землі,\nВід роду поганин і ріс я у злі,\nПрийнятий тепер, записаний Ним,\nНасліддя від Бога одержу з вінцем.\n\nКуплет 4\nНавіщо мені турботи земні?\nОселі Христом готуються мені.\nЯ тут чужоземець, пісня ж моя:\n«Отцю слава, честь: я наслідник Царя!»', '', '', 'ua', NULL, 0, NULL, NULL),
(845, 326, 'Тобі я служити бажаю', 0, 'Куплет 1\nТобі я служити бажаю, мій Спасе, від літ молодих,\nТа сили я мало так маю, а прошу, щоб Ти допоміг.\n\nПриспів: \nСлужити всім серцем, всім тілом Тобі \nЯ буду, зміцни ж мої сили слабі;\nНа славу Тобі все життя посвятить, \nДорогами правди Твоєї ходить.\n\nКуплет 2\nЯзнаю, що Ти мене любиш; о дай, щоб Тебе я любив \nТа вірив, що Ти не погубиш, і завжди з Тобою я жив.\n\nКуплет 3\nДо Тебе молитися завжди навчи, щоб я більше умів \nТвоєї шукав лише правди і людям про неї свідчив.\n\nКуплет 4\nПорою, як сили слабіють і в’яну під спекою дня,\nХай крила святії закриють, зміцнить мене сила Твоя.\n\nКуплет 5\nДо смерті Твоїм хочу бути, служити до гробу Тобі,\nІ в небі з Тобою злучитись у вічній чудовій хвалі.', '', '', 'ua', NULL, 0, NULL, NULL),
(846, 327, 'Як прийде Господь', 0, 'Куплет 1\nЯк прийде Господь у славі, чи готовий ти будеш?\nДосі ходиш ти в темряві і в гріхах усе живеш.\n\nКуплет 2\nПодивися на Голгофу, як Він тяжко там страждав,\nТо за тебе, милий друже, щоби ти спасіння мав.\n\nКуплет 3\nО нещасний, ти не знаєш, - скоро вже Господь прийде; \nВін і праведних і грішних - всіх нежданно тут знайде.\n\nКуплет 4\nВін розкриє вічну книгу, перегляне її Сам\nІ довідається з Неї, чи записаний ти там.\n\nКуплет 5\nКоли будеш Йому вірним, прийме з радістю тебе,\nА як будеш непокірний, Він у Царство не прийме.\n\nКуплет 6\nСкаже: «Йдіть в вогонь прокляті!»Там не буде каяття, \nВічно будеш там ридати, проклинать своє життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(847, 328, 'Часто в смутку я', 0, 'Куплет 1\nЧасто в смутку я, і скорблю в душі,\nІ нема друзів, хто б поміг мені.\nІ ні в чім мені радості нема,\nВсе чогось скорбить тут душа моя.\n\nКуплет 2\nПригадаю я у нічній тиші,\nЧого гірко так плачу я в душі.\nТяжко, трудно жить без щасливих днів, ‘\nЗ чаші горя пить у житті земнім.\n\nКуплет 3\nСкільки злих людей без любві живуть,\nЗа добро вони злом лиш віддають.\nПоміж них нема вірних друзів тих,\nЗ ким би в час тяжкий горе розділив.\n\nКуплет 4\nЗорі яснії в небесах горять,\nГіркі сльози все на очах блищать...\nХто рятунок дасть в ті часи трудні,\nІ утіху хто може дать мені?\n\nКуплет 5\nХто б це зрозумів, чого плачу я?\nЗнає тільки Бог, в чім печаль моя.\nВ трудний, скорбний час до Нього піду,\nВсю мою печаль розкажу Йому.\n\nКуплет 6\nВін приблизиться близько до мене,\nСльози гіркії із очей утре.\nВ тіні крил Його відпочину я,\nІ спокій душі тільки в Нім знайду.', '', '', 'ua', NULL, 0, NULL, NULL),
(848, 329, 'Вже поля дозріли', 0, 'Куплет 1\nВже поля дозріли і чекають нас,\nБог нас посилає, близько жнива час.\nПраці є багато, але мало слуг...\nЧуєте ви, браття, що нас кличе Бог?\n\nПриспів: \nНадходить жнива день,\n(Надходить радісний жнива день), \nРадісний жнива день,\n(Надходить радісний жнива день), \nЗолоте колосся жать, - \nМи будем серпом жать.\nНадходить жнива день,\n(Надходить радісний жнива день), \nРадісний жнива день,\n(Надходить радісний жнива день).\nЗ вірою цей труд зачнем,\nДо праці враз підем!\n\nКуплет 2\nНемічному брату руку ти подай,\nI додай охоти, щоб він працював,\nПраця ця поважна, Бог заплату дасть,\nВін тебе покличе: «Йди в пробуток Мій!»\n\nКуплет 3\nПоки сонце світить, правду голоси,\nЖнива час минеться, прийдуть злі часи.\nБраття й сестри, дружно ви снопи зберіть,\nЗ радістю у серці до Христа несіть.', '', '', 'ua', NULL, 0, NULL, NULL),
(849, 330, 'Овець заблудлих', 0, 'Куплет 1\nОвець заблудлих Пастир шукає,\nХодить по горах Він ніч і день.\n\"Прийдіть до Мене» - всіх закликає;\nСлова Ісуса звучать ще днесь.\n\nПриспів: \nПрямо іде Він поміж гори,\nБлудну вівцю назад несе, (Він несе),\nА в небесах співають хори\nАгнцю Христу, Спасителю (що вмер за нас).\n\nКуплет 2\nШукайте грішних в гріхах страждання,\nДуш, котрі блудять ще у гріхах,\nІ направляйте на путь спасіння,\nКотра провадить у небеса.\n\nКуплет 3\nТак і я піду слідом Христовим,\nДавати поміч всім, хто стражда:\nГрішних і бідних, калік і хворих, - \nВсіх направляти їх до Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(850, 331, 'Я по роздолі з моїм Спасом піду', 0, 'Куплет 1\nЯ по роздолі з моїм Спасом піду все,\nТуди, де квіти цвітуть і вода тече;\nДе б Він не повів мене, я піду всюди з Ним,\nЙду Його слідами у Небесний Дім.\n\nПриспів: \nПіду, піду, піду за Ісусом!\nВсюди, де поведе, я піду за Ним.\nПіду, піду, піду за Ісусом!\nДе б Він не повів, там я піду за Ним.\nЯ по роздолі з моїм Спасом все піду,\nТам де буря віє, навіть в тьму нічну, - \nВін мене веде могутньою рукою Сам.\nЯ нічого не боюсь: зі мною Спас.\nЧи то в долині, чи високо на горі,\nВ злуці з моїм Спасом скрізь весело мені:\nВін мене так певно Сам провадить по путі \nДо Свойого дому, там де всі святі.', '', '', 'ua', NULL, 0, NULL, NULL),
(851, 332, 'Хай бере хто хоче', 0, 'Куплет 1\nХай бере, хто хоче, - нині ще пора, -\nБожий дар спасіння, вічного добра.\nСлухайте, ідіте - поспішайте взять \nТе, що Бог всім хоче дать.\n\nПриспів: \nХай бере бідняк! Хай без срібла п’є!\nТо Ісус Спаситель нас усіх зове.\nОсь вода живая без кінця біжить,\nДармо пий, хто прагне пить.\n\nКуплет 2\nО, приходь, мій друже, і бери хутчій!\nНині Бог спасіння хоче дать тобі;\nЗавтра буде пізно вже тобі благать:\nЗмовкне Божа благодать.\n\nКуплет 3\nХай бере, хто хоче, Бог усіх зове:\nВічний дар спасіння хай кожний прийме.\nВсе, що обітує, Бог в любві дає, —\nВбогий духом хай прийде.', '', '', 'ua', NULL, 0, NULL, NULL),
(852, 333, 'З небес Своїх у славі', 0, 'Куплет 1\nЗ небес Своїх у славі Господь прийде;\nНе сонних нас, а пильних, Він хай знайде.\nСвітильники держімо в наших руках,\nЛюбов і дожидання в наших серцях.\n\nПриспів: \nРадість велика буде, - Господь прийде! \nВсе небо «Алілуя» співать буде. \nЗемля вся обновиться в вічній красі,\nІ в славі освітиться Його святій.\n\nКуплет 2\nЗабудем всі незгоди: Господь прийде,\nНастане Царство Правди, - Господь прийде.\nЩезне вже зло й сумніви: Господь прийде.\nНе буде сліз, томління, - Господь прийде.\n\nКуплет 3\nВін знає, як страждали ми на путі,\nТут ми не спочивали - свій хрест несли. \nГосподь тягар з нас здійме, коли прийде,\nВ славу небесну прийме: Господь прийде!', '', '', 'ua', NULL, 0, NULL, NULL),
(853, 334, 'Брате кріпись', 0, 'Куплет 1\nБрате, кріпись! Дні пробігають;\nБрате, кріпись! Хай всі вважають:\nПрийшов уже останній час, - \nБог кличе всіх до праці нас.\n\nПриспів: \nБо вічність вже | зовсім близька. (2р.)\nБо вічність вже зовсім близька.\n\nКуплет 2\nСлав, брат, Христа за радість нашу!\nСлав, брат, Христа за скорбну чашу:\nНебесний Цар до нас іде,\nБлаженство вірним Він несе!\n\nКуплет 3\nБрате, кріпись! Літа проходять;\nБрате, пильнуй! Дні злі надходять:\nЯк воїн, стій ти на часах\nЗ мечем Божественним в руках!\n\nКуплет 4\nОсь, брате, глянь! Вже день світає;\nБрате, почуй! Господь скликає \nСвоїх дітей в Небесний Дім,\nДе буде слава й радість з Ним.', '', '', 'ua', NULL, 0, NULL, NULL),
(854, 335, 'В серце моє', 0, 'Куплет 1\nВ серце моє, (2р.) Ісусе, ввійди у серце;\nВвійди в цей час, мій любий Спасе,\nВвійди, Ісусе, в серце!', '', '', 'ua', NULL, 0, NULL, NULL),
(855, 336, 'Як скоро час біжить', 0, 'Куплет 1\nЯк скоро час біжить невпинно!\nПройшли вже тисячі років, - \nІ так час нинішній пролине \nУслід забутих вже родів.\nТак в вічність день за днем стремиться,\nНе залишає і сліда.\nЖиття на крилах мов несеться:\nПрийде і наша вже черга.\n\nКуплет 2\nІ наші всі земні діяння:\nТруди, турботи, марнота - \nНемов десь зникнуть у безодні \nПодібно мрії, що пройшла.\nПощо ж на світ ти цей родився\nІ стільки переніс страждань?\nДо чого ум твій все стремився?\nЩоб статись жертвою червам?...\n\nКуплет 3\nЗемнеє щастя, привид зрадний,\nДержав тебе завсіди в тьмі:\nЗабув, що порох ти нікчемний - \nЄ перехожим на землі.\nТа є за гробом життя краще,\nВоно не знає лічби днів,\nА що ж тебе там дожидає?\nПро це ти думав вже, чи ні?', '', '', 'ua', NULL, 0, NULL, NULL),
(856, 337, 'В ті дні останнього часу', 0, 'Куплет 1\nВ ті дні останнього часу,\nО, радість нам тоді буде,\nЯк ми побачим наяву,\nКоли на землю Цар царів прийде.\n\nПриспів: \nІсус прийде, Він знов прийде.\nМи з радістю Його чекаєм, (Він прийде). \nО, може рано, може і в північ,\nМи знаєм, що прийде.\n(Скоро наш Ісус прийде).\n\nКуплет 2\nНа небі вже ознаки є,\nI на землі довкола нас,\nА Боже Слово свідчить нам,\nЩо Спаситель Ісус прийде до нас.\n\nКуплет 3\nІ всі померлі у Христі, \nЯк зазвучить труба з небес,-\nВони воскреснуть всі тоді,\nЯк у славі Господь по нас прийде.\n\nКуплет 4\nЖиві - всі перемінимось,\nВ небо підхоплені будем,\nІ з Господом зустрінемось,\nІ так ми завжди з Господом будем.', '', '', 'ua', NULL, 0, NULL, NULL),
(857, 338, 'На горі Оливній там', 0, 'Куплет 1\nНа горі Оливній - там Спас моливсь цілу ніч Сам. \nДля молитви приклад всім Спас нам дав;\nІ як ми також щодня проведем в молитві час,\nМи дізнаєм, любо як наєдині.\n\nПриспів: \nО, як любо є мені бути з Ним наєдині; \nРозказати все Йому наєдині.\n\nКуплет 2\nЄ також щасливі дні, в котрі любо так мені \nБути з Господом і наєдині; Господь душу там мою \nНаповняє радістю. О, як любо бути з Ним наєдині.\n\nКуплет 3\nЯк надія упаде, смуток душу вповине,\nДо Христа прийди ти наєдині,\nІ Він смуток віддалить, серце радістю сповнить,\nЯк прийдеш до Нього ти наєдині.', '', '', 'ua', NULL, 0, NULL, NULL),
(858, 339, 'На Голгофській горі', 0, 'Куплет 1\nНа Голгофській горі я все бачу там хрест.\nВін є символ, страждання, наруг...\nАле люблю цей хрест, він мені дорогий:\nНа нім Спас за весь світ постраждав.\n\nПриспів: \nНе забуду ніколи той хрест:\n(Хрест старий, тяжкий хрест),\nВ нім прощення дарує Отець.\nМовби в серці я ношу той хрест,\n(Хрест старий, тяжкий хрест), - \nВ славний день я зміню на вінець.\n\nКуплет 2\nДуже давній той хрест, і забутий людьми,\nАле лине до Нього душа:\nБог у жертву на нім Свого Сина віддав,\nЗа нас смерть на хресті Він прийняв.\n\nКуплет 3\nЯ все бачу той хрест, де Христос пролив кров... \nТо ж і я тут свій хрест понесу;\nА Спаситель мене в Дім Свій вічний прийме,\nІ вже вічно там з Ним я буду.', '', '', 'ua', NULL, 0, NULL, NULL),
(859, 340, 'Глибше всіх морів та океанів', 0, 'Куплет 1\nГлибше всіх морів та океанів \nВічна, недосяжна і свята,\nВище від усіх світил небесних - \nБлагодатная любов Христа.\n\nПриспів:\nВін обмив гріхи мої,\nДав одіж слави Він мені,\nДар Святого Духа звіщав,\nСвоїм дитям мене назвав\n\nКуплет 2\nЩастя я знайшов в Христі Ісусі;\nЯ спасен від смерті і суда:\nМоїм серцем гріх не володіє\nВ нім оселя Господа Христа.\n\nКуплет 3\nЖив я довго у пітьмі без світла;\nЯ блукав далеко від Христа,\nГинув я поранений, нещасний,\nТа Ісус знайшов і спас мене.', '', '', 'ua', NULL, 0, NULL, NULL),
(860, 341, 'За все Тобі я дякую', 0, 'Куплет 1\nЗа все Тобі я дякую, Спаситель Ти мій,\nЗа Духа, що з ознакою Ти дав душі моїй.\n\nПрипев\nЯ дякую за все, за те, що спас мене,\nЗа те, що життя дав, духа злого прогнав.\nМене Ти охоестив Дух в серці поселив,\nЩобі життям моїм завжди Він керував.\n\nКуплет 2\nЗа все Тобі я дякую, за Твій голгофський хрест,\nЗа Тебе, вам розп\'ятого, за те, що чуеш нас,\n\nКуплет 3\nЗа все Тобі я дякую, надія Ти моя;\nВ житті я хочу славити, Тобі честь і хвала', '', '', 'ua', NULL, 3, '2021-03-19', NULL),
(861, 342, 'О Небесна Країно', 0, 'Куплет 1\nО, Небесна Країно, до тебе я йду,\nТа про тебе усім розкажу;\nЛиш у тебе царює небесний спокій\nО, прийми мене, Спасе, Ти мій\n\nПрипев\nВслід за Спасом ми підем (2р.)\nІ в Небесний Край ввійдем (2р.)\nТам життя нове ми розпочнем\n\nКуплет 2\nСвіт про тебе не знає, не може пізнать\nБо нам треба піти розказать,\nЩоб пізнали про Тебе також люди всі\nЩо вмирав Ти за них на хрестіюю.\n\nКуплет 3\nО, не раз я сльозами так гірко заллюсь;\nЯк на грішний цей світ подивлюсь;\nЩо він так у гріхах та неправді живе\nЙого кара за гріх не минею.', '', '', 'ua', NULL, 0, NULL, NULL),
(862, 343, 'Ой у Вифлеємі весела новина', 0, 'Куплет 1\nОй, у Вифлеємі весела новина, - радуйся!\n\nПриспів: \nОй, радуйся, земле,\nСин Божий народився!\n\nКуплет 2\nТам Діва Марія народила Сина, - радуйся!\n\nКуплет 3\nІ Отцівське Слово зодяглося в тіло, - радуйся!\n\nКуплет 4\nВ мороці земному Сонце засвітило, - радуйся!\n\nКуплет 5\nАнгели співають Господу своєму, - радуйся!\n\nКуплет 6\nСлаву-честь складають Йому Родженому-радуйся!\n\nКуплет 7\nІ ми Родженого Христа прославляймо, - радуйся!\n\nКуплет 8\nГосподеві Спасу всі поклін віддаймо, - радуйся!', '', '', 'ua', NULL, 3, '2021-01-06', NULL),
(863, 344, 'Ой зійшла зійшла Правда', 0, 'Куплет 1\nОй, зійшла, зійшла Правда на землю\nІ пробуває між людьми.\nВсе розказала, що треба людям;\nЯк треба жить, як Бог велить.\n\nПриспів: \nДе ж тая Правда, звідки з’явилась,\nДе ж вона нині на світі є?\nТам в Вифлеємі в яслах родилась,\nА тепер в вірних серцях живе.\n\nКуплет 2\nІ Дух Святої Правди із неба,\nНині шукає в серцях ясел,\nДе б поселитись, щоби родити\nОвочі правди в життю людей.\n\nКуплет 3\nІ в кому знайде місце для себе, \nТам запанує радість життя; \nТому дарує місце на небі,\nЩе й допоможе нести хреста.\n\nКуплет 4\nXристос є Правда, Христос є Світло, \nХристос є Хліб Життя для нас.\nО, якби люди з усього світу\nПрийшли до Нього, — Він би їх спас.', '', '', 'ua', NULL, 1, '2020-12-27', NULL),
(864, 345, 'Небо голубе', 0, 'Куплет 1\nНебо голубе, я люблю тебе,\nТи - мета моїх завітних мрій.\nЗабуваю все - прагну до тебе;\nУявляю дивний спокій твій.\n\nПриспів: \nА на цій землі сумно так мені, \nЗавжди лише сльози на очах,\nБо навкруг мене виє та реве; \nПотопає світ цей у гріхах.\n\nКуплет 2\nСпасе дорогий, голос вчуй Ти мій,\nПоможи дорогу цю пройти,\nЩоб для Тебе жить і Тобі служить,\nДосягти завітної мети.\n\nКуплет 3\nНебо голубе, хочу до тебе;\nТам мене чекає мій Творець,\nТам спочину я, заспокоюсь я,\nТам стражданням всім прийде кінець.', '', '', 'ua', NULL, 0, NULL, NULL),
(865, 346, 'Я буду співати', 0, 'Куплет 1\nЯ буду співати в кожний час, журби в мене нема. \nМене Христос від смерті спас; щасливий я без кінця.\n\nПриспів: \nСпівай, (4р.) для Господа співай.\nСпівай, (4р.) о, сумний брате, співай.\n\nКуплет 2\nСпівай тоді, коли в душі тягар тобі наляжеться,\nСпівай від серця, від душі, і легше зробиться.\n\nКуплет 3\nЯ буду співати, доки серця стук останній відіб’є,\nІ доки любий мій народ; співать зі мною буде.', '', '', 'ua', NULL, 0, NULL, NULL),
(866, 347, 'Лине пісня про Ісуса', 0, 'Куплет 1\nЛине пісня про Ісуса, про діла Його святі.\nЯ до Нього пригорнуся щирим серцем у житті.\n\nПриспів: \nВсе віддам я для Ісуса:\nСерце, душу і життя.\nІ навіки з ним зіллюся,\nВ Царстві вічного буття!\n\nКуплет 2\nПро любов Його безмірну лине пісня серед нас,\nБуду я для Нього вірним, всякий день і всякий час.\n\nКуплет 3\nНехай світ, як море грізно, клекотить, реве всю ніч, \nВ небесах моя Вітчизна, непохитною стоїть.', '', '', 'ua', NULL, 1, '2020-08-16', NULL),
(867, 348, 'Вірний Спасителю мій', 0, 'Куплет 1\nВірний Спасителю мій, Ти є найкращий мій Друг;\nЯ все Тобі віддаю, даю, серце, любов і красу.\n\nКуплет 2\nВ світі далеко я був, грішний, неправдою жив,\nТи ж мене, Боже, любив, любив, кров’ю гріхи всі обмив.\n\nКуплет 3\nПісню про ласку Твою в серце моє Ти вселив..\nДай сили хрест свій нести, нести, вірним Тобі буть завжди.', '', '', 'ua', NULL, 0, NULL, NULL),
(868, 349, 'Дні минають швидко', 0, 'Куплет 1\nДні минають швидко, мов на крилах,\nЗ днями пролетить життя,\nI свої розправивши вітрила,\nВідлетить у майбуття.\n\nКуплет 2\nПоки у горі синіє небо,\nКвітнуть молоді літа;\nЧасу марно гаяти не треба,\nВічність часу не верта.\n\nКуплет 3\nОбіб’ють дощі зів’яле листя,\nВідсумують журавлі.\nВідлунає пісня урочиста,\nЗмовкне у вечірній млі.\n\nКуплет 4\nНе марнуй же, юність, днів найкращих,\nБо з усіх життєвих втрат,\nВтрата часу — саме є найтяжче,—\nЧас - це найдорожчий скарб.\n\nКуплет 5\nТи життя - святий дарунок неба,\nПринеси до ніг Христа.\nЧасу марно гаяти не треба,\nВічність часу не верта.\n\nКуплет 6\nА літа пливуть немов на крилах,\nЗ ними пролетить життя.\nЮність, направляй свої вітрила \nУ щасливе майбуття.', '', '', 'ua', NULL, 0, NULL, NULL),
(869, 350, 'Дух Святий навесні', 0, 'Куплет 1\nДух Святий навесні, разом з сонцем ясним,\nМоє серце від сну розбудив.\nВін і радість приніс, і веселі пісні,\nПро щасливі майбутнії дні.\n\nКуплет 2\nЯ співав про любов у терновім вінку,\nЯк Христос за людей умирав.\nПро щасливу країну святу в небесах, \nЩо для вірних Христос обіцяв.\n\nКуплет 3\nЯсний промінь погас, злий орел налетів,\nВін позаздрив веселим пісням.\nВ чисте серце моє він отруту пустив, \nВирвав пісню і геть полетів.\n\nКуплет 4\nІ тепер нема слів, щоб співати пісні, \nА в очах моїх сльози блищать.\nЯ німий пред Тобою, Ісусе, стою, \nХочу скинути ношу мою.\n\nКуплет 5\nЛюбий друже Ісус, я благаю Тебе, \nПоможи в цю хвилину тяжку.\nНехай зникне сльоза, пройдуть думи сумні, \nПоверни знову пісню мені.', '', '', 'ua', NULL, 0, NULL, NULL),
(870, 351, 'Місце є дороге', 0, 'Куплет 1\nМісце є дороге, де бажав би бути ще,\nТам з моїми братами в селі.\nДе в неділю ходив, Господеві я служив,\nТам у Церкві з братами в селі.\n\nПриспів: \nО, як радують думки про минулі ті роки. \nХочеться хоч раз мені \nБути в Церкві з братами в селі.\n\nКуплет 2\nЯк я був молодий, - радувався я тоді,\nЯк моливсь там в тій Церкві в селі.\nМій Спаситель з гори по любові Своїй \nСпас мене там в тій Церкві в селі.\n\nКуплет 3\nО, коли б в наші дні так молились усі,\nЯк молились колись у селі.\nТреба серце відкрить, а Ісус благословить,\nЯк благословив нас у селі.\n\nКуплет 4\nЧасто думаю я, що мій брат і сестра;\nПерейшли вже туди в небеса.\nМоже скоро Господь вже й за мною прийде,\nІ з Ним в небі спочину там я.', '', '', 'ua', NULL, 0, NULL, NULL),
(871, 352, 'В час горя та журби', 0, 'Куплет 1\nВ час горя та журби я лину до Христа,\nВін є притулок мій; в Нім радість вся моя.\n\nПриспів: \nА Він єдиний друг і Пастир добрий мій;\nПоможе Він мені, та радість дасть душі.\n\nКуплет 2\nВ нещасті і сльозах, коли відчай душі,\nЯ Його кличу знов, молюся у тиші.\n\nКуплет 3\nА як грозить мені шалений буревій,\nТо до Христа спішу, до Нього йду скорій.\n\nКуплет 4\nБуває і в бою поранений гріхом,\nТо підіймаю взір, і лину до Христа.\n\nКуплет 5\nКоли сердечний біль, і томиться душа,\nЙому все розкажу спочатку й до кінця.', '', '', 'ua', NULL, 0, NULL, NULL),
(872, 353, 'Ти знаєш Боже', 0, 'Куплет 1\nТи знаєш, Боже, моє бажання,\nМолитву чуєш Ти мою.\nТи знаєш серця мого страждання,\nКоли я гіркі сльози ллю.\n\nКуплет 2\nТи знаєш, Боже, що я бажаю Н\nе слави, скарбів на землі.\nЯ щирим серцем Тебе кохаю \nВ мої весняні юні дні.\n\nКуплет 3\nСумує серце моє порою,\nВ устах моїх немає слів.\nІ я самотній скорблю душею,\nЗмовкає мій весняний спів.\n\nКуплет 4\nНіхто не знає, усім байдуже,\nКуди душею лину я.\nІ хто спитає, і хто потішить,\nКоли сумна душа моя.\n\nКуплет 5\nЦей світ чужий вже мені зробився,\nО, Боже, Ти зі мною будь. \nБо слабнуть сили, і я втомився,\nА ще далека моя путь.', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(873, 354, 'В цей день славний', 0, 'Куплет 1\nВ цей день славний я хочу співати для Христа.\nПро ласку, добрість і любов - прославлять Його ім\'я. \nЗавжди я хочу співати своїм слабим голосом,\nЩоби у спільності бути з моїм Ісусом Христом.\n\nПриспів: \nО, за це Тебе славить душа моя,\nБо без Тебе я завжди в серці біль відчував. \nА тепер я спасенний, любов\'ю зігрітий,\nІ ціною Крові Ти мене врятував.\n\nКуплет 2\nІсус тепер закликає, - не зачиняй серця ти.\nСвітлом тебе Він провадить аж до висот Голгофи. \nСміло за Ним йти рішися, - радісним будеш тоді,\nДуха Святого одержиш, щасливим повік будеш ти.', '', '', 'ua', NULL, 2, '2020-11-01', NULL),
(874, 355, 'Вставайте вставайте браття мої', 0, 'Куплет 1\nВставайте, вставайте, браття мої милі,\nПогляньте на небо, вже зійшла зо \nЯсним промінням б’є нашу руїну,\nХвилини не гайте, спішіте туди.\n\nКуплет 2\nДитя народилось у яслах на сіні,\nСин Божий на землю зійшов із небес. \nСпасати народи, з гріхів визволяти,\nНа волю пускати люд праведний весь.\n\nКуплет 3\nЦарі із Востоку до Нього приходять,\nЦіннії дарунки до Нього несуть.\nА воїни царські в степу переходять,\nНа допит невинних в палаци ведуть.\n\nКуплет 4\nТа їх не злякають тортурнії муки,\nНі підступи лживі Ірода-царя. \nЇм Дух Божий ласки дорогу торує.\nДо цілі провадить ясная зоря.\n\nКуплет 5\nСпішіте дарунки приносити Йому,\nМалому дитяті Ісусу Христу. \nВін висушить сльози заплаканій неньці \nІ добром наділить в годину тяжку.', '', '', 'ua', NULL, 0, NULL, NULL),
(875, 356, 'Одна лиш Біблія свята', 30, 'Куплет 1\nОдна лиш Біблія свята для нас - і світло, і мета.\nМи з неї знаєм, як за нас помер у муках любий Спас.\n\nПриспів: \nО, Слово Боже - світло ти,\nВ житті постійно нам світи!\nО, Слово Боже, ясно сяй,\nІ нас веди в Небесний Край.\n\nКуплет 2\nВідомо з Біблії і те, що Бог життя дає святе\nУсім, хто серце та уста поклали на вівтар Христа.\n\nКуплет 3\nХто любить Біблію читать, тому не страшно помирать.\nУсіх, кого вона веде, життя на небі вічне жде.', '', '', 'ua', NULL, 0, NULL, NULL),
(876, 357, 'Ой над Вифлеємом зірка', 0, 'Куплет 1\nОй, над Вифлеємом зірка вже зійшла,\nТам Діва Марія Сина родила. \nВ пелени сповила, у яслах поклала,\nЦе на світ родився Спаситель світу.\n\nКуплет 2\nВін на світ родився як людина, \nАнгели ж вітали Божого Сина. \nАнгели співають, пастухи вітають,\nА три царі із Персії у вертеп спішать.\n\nКуплет 3\nЗ’явилась над ними ясная зоря,\nА в яслах на сіні - маленьке Дитя.\nЙосиф і Марія над Ним вже стоять \nРучки простягає маленьке Дитя.\n\nКуплет 4\nЙосифові ангел у сні з’явився,\nЩоб з малим Дитятком він удалився \nУзяв Йосиф Сина і матір Його, \nУтікав в Єгипет від царя злого.\n\nКуплет 5\nА Ірод, цар злобний, дуже засмутивсь,\nЩо Ісус Син Божий на світ народивсь. \nВійсько посилає у ту країну,\nСказав загубити малу Дитину.\n\nКуплет 6\nСказав Ірод війську - шукати Христа, \nДо двох літ рубати маленьких дитят.\nСкільки ж душ невинних, чистих немовлят, \nБуло в Вифлеємі вбито у той час!\n\nКуплет 7\nГлянь, о Божий Сину, на дітей Своїх,\nТи Спаситель світу, Цар неба й землі.\nЗішли нам із неба дар Твій превеликий,\nБудем Тебе славить по вічні віки.', '', '', 'ua', NULL, 0, NULL, NULL),
(877, 358, 'Ісус з Назарету', 0, 'Куплет 1\nІсус з Назарету, на хресті прибитий,\nПокривало крові покрило лице.\nЛице Його миле, святе і небесне;\nВінка із тернини Йому надягли.\n\nПриспів: \n«Елі, елі, елі, лама савахтані!»,\nВзивав наш Учитель, небесний Ісус. \nНаш милий Спаситель нас так полюбив,\nІ скрикнувши сильно, Він Духа віддав.\n\nКуплет 2\nВдягли в багряницю, подали тростину, \nНавколішки стали і били Його.\n«Радій! Цар Юдейський», - вони всі кричали, \nОдежу ділили, сміялись над Ним.\n\nКуплет 3\nЗемля затряслася і сотник промовив: \n«Це справді Син Божий висить на хресті!» \nМесія-Спаситель так тяжко страждав, \nЩоб грішникам двері до раю відкрить.', '', '', 'ua', NULL, 1, '2020-10-25', NULL),
(878, 359, 'Куди піду куди від Тебе', 0, 'Куплет 1\nКуди піду, куди від Тебе?\nСпаситель мій, куди піду?\nДе зможу я навік для себе \nСпокій і мир душі знайти?\n\nКуплет 2\nХто мені скаже правди слово, \nВ розбите серце силу дасть? \nЩоб я тонув в святій любові \nІ міг її братам подать.\n\nКуплет 3\nXіба піду, де розлилися\nБезжурний сміх та п’яний спів?!\nЯ там вже був, там я томився,\nТам чорна хмара темних днів.\n\nКуплет 4\nЯк цвіт на квітці засихає,\nЯк лист пожовкне, облетить, \nТакий кінець їх всіх чекає;\nО, ні, не можу це любить.\n\nКуплет 5\nКуди піду, куди від Тебе?\nСпаситель мій, куди піду?\nЗ Тобою буду, бо для себе\nНіде я щастя не знайду.', '', '', 'ua', NULL, 0, NULL, NULL),
(879, 360, 'Підніми мене Ісусе', 0, 'Куплет 1\nПідніми мене, Ісусе, з цього світу марноти\nВ ту Країну, де з святими, пробуваєш вічно Ти. (2р.)\n\nКуплет 2\nЯ стомився в цій мандрівці, в небеса спочити йду.\nЛиш в Тобі я нові сили і спокій душі знайду. (2р.)\n\nКуплет 3\nПідніми мене, Ісусе, в Край Небес, у Край святий,\nДе минуться всі спокуси, смуток і тягар людський. (2р.)\n\nКуплет 4\nТи почуй мої благання, власний гріх я визнаю. \nСкороти мої страждання, душу обнови мою. (2р.)\n\nКуплет 5\nЛиш з Тобою я безпечно зможу йти шляхом вузьким. \nО, провадь мене, мій Спасе, у небесний вічний дім.(2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(880, 361, 'Прийди ти до Ісуса', 0, 'Куплет 1\nПрийди ти до Ісуса, мій друже дорогий.\nТебе стомив до краю великий гріх тяжкий.\n\nКуплет 2\nПрийди і не лякайся, Христос приймає всіх. \nВідкрий Йому всі рани, весь біль із себе скинь.\n\nКуплет 3\nЙого віддайся волі, Його лиш слухай ти;\nВін вилікує скоро з гріха й нечистоти.\n\nКуплет 4\nВ крові Його пречистій вздоровлення знайдеш; \nДушею в ній омитий, спасіння дар приймеш.\n\nКуплет 5\nВізьми свій хрест, з Ісусом іди вузьким шляхом; \nІдучи, не журися, не плач ти під хрестом.\n\nКуплет 6\nСтарайся шлях свій вірно пройти з Ним до кінця; \nТоді ввійдеш у вічність, в Небесний Дім Отця.', '', '', 'ua', NULL, 0, NULL, NULL),
(881, 362, 'Не покину я вас', 0, 'Куплет 1\nНе покину я вас, не забуду!\nТак Бог каже тобі і мені:\n// Турбуватись про вас завжди буду,\nУ стражданнях тяжких на землі. // - 2р.\n\nКуплет 2\nБуду в праці Я вам помагати,\nБуду силу і міць подавать,\n// І в годину сердечної втрати,\nБуду в душу бадьорість вливать. // - 2р.\n\nКуплет 3\nНе покину Я вас, не забуду,\nКоли батько і мати, й рідня \n// Відречуться від вас, то Я буду,\nРідним батьком для вас з того дня. // - 2р.\n\nКуплет 4\nНіжно буду Я вас доглядати,\nТак, як мати маленьке дитя, \n// Від усякого зла зберігати,\nІ провадить у вічне життя. // - 2р.\n\nКуплет 5\nЯ самотнєє серце розважу,\nСумні думи Я геть віджену,\n// І розбите життя Я поладжу,\nДух засмучений в вас підкріплю. // - 2р.', '', '', 'ua', NULL, 0, NULL, NULL),
(882, 363, 'Юність ти прекрасна', 0, 'Куплет 1\nЮність, ти прекрасна, цвіт життя чудовий;\nТи весняна квітка молодечих літ.\nОй, чому ж так скоро в’яне лист чарівний,\nБлиск очей погас твій, скроні в сивині?\n\nКуплет 2\nЧим би заплатить міг, щоби ти лишилась, \nЗавжди нероздільно, до кінця цвісти.\nСкоро так проходять роки золотії,\nІ ти безперечно хочеш відійти.\n\nКуплет 3\nХто би повернуть міг чарівні привілля,\nІ вогонь любові, силу повернуть.\nЮність - це є щастя днів моїх тривожних,\nПролетіли в бурях на земнім путі.\n\nКуплет 4\nНе сумуй же, брате, є надія в Бозі,\nЦей недолік в людях знав Отець завжди. \nНедаремно руки - Ті були прибиті,\nЩоб вернути юність - життя назавжди.', '', '', 'ua', NULL, 0, NULL, NULL),
(883, 364, 'Люба мамо не плач', 0, 'Куплет 1\nЛюба мамо, не плач, не журись,\nДухом не падай у тяжкій борні;\nБо мине журба, зникне вся боротьба,\nСонце засяє тобі.\n\nКуплет 2\nСкільки раз заливалась в сльозах,\nТи на колінах стояла своїх.\nІ в мольбі палкій перед Богом живим,\nБіль відкривала душі.\n\nКуплет 3\nПригадую, як просила мене:\n«Сину мій, сину, віддайсь для Христа.\nВін тебе полюбив, двері раю відкрив,\nВ Царство Він кличе своє.»\n\nКуплет 4\nТа не слухав тебе, мамо, я,\nВибрав дорогу гріха й марноти.\nНа шляху своїм щастя я не зустрів, \nЛиш змарнував я життя.\n\nКуплет 5\nТа молитва твоя все неслась,\nВ небо до Бога за ледарство моє.\nЇї Бог почув і мене навернув,\nГріх мій тяжкий з мене зняв.\n\nКуплет 6\nТепер славлю Його в серці я,\nДивне життя я отримав в Христі; \nБільш ніколи я не залишу Христа, \nЖитиму з Ним по всі дні.\n\nКуплет 7\nТо ж, люба мамо, не плач, не журись, \nДухом не падай, а серцем радій.\nОсь приходить час, коли в небо всіх враз; \nБог забере нас повік.', '', '', 'ua', NULL, 0, NULL, NULL),
(884, 365, 'Чого ждеш на широкім шляху', 0, 'Куплет 1\nЧого ждеш на широкім шляху?\nЧому досі ти служиш гріху?\nО, чому ти не хочеш прийнять \nДар безцінний - Христа благодать?\n\nПриспів: \nСпіши тепер, (2р.) - до Христа Ісуса скорій!\nСпіши тепер, (2р.) — бо в темряві згинеш нічній.\n\nКуплет 2\nТи поглянь на Ісуса Христа, - \nТо ж за тебе кров ллялась свята.\nЧашу горя за тебе Він пив \nІ від суду тебе відкупив.\n\nКуплет 3\nДля Христа все життя присвяти, - \nІ щасливий повік будеш ти.\nКров свята змиє твій тяжкий гріх,\nІ вбереш одіж білу, як сніг.', '', '', 'ua', NULL, 0, NULL, NULL),
(885, 366, 'Коли прийде біда', 0, 'Куплет 1\nКоли прийде біда, хто вам, скажіть, допоможе?\nНавіть через літа бачу я руку Божу.\nСтань на коліна, друг, коли прийде тривога,\nІ ти пізнаєш вмить щастя в єднанні з Богом!\nСвіт не поможе, ні, серце тривога ранить. \nТільки Господь тобі руки Свої простягне.\n\nКуплет 2\nВилиєш душу Йому в горі своїм і стражданнях.\nНавіть останню тьму Він перетворить в сіяння.\nСтань на коліна, друг, коли прийде тривога,\nI ти пізнаєш вмить щастя в єднанні з Богом!\nСвіт не поможе в біді, серце ще більше ранить. \nТільки Христос завжди руки тобі простягне.\n\nКуплет 3\nПрийди ти до Христа, Він тебе закликає,\nНіжно звучать слова: любить Ісус і прощає.\nІ коли, друже, ти серцем пізнаєш Бога,\nСтане в житті твоїм легкою земна дорога.\nВ небі чекають тебе вічні оселі з Богом,\nДе вже не буде біди, горя, сліз і тривоги.', '', '', 'ua', NULL, 0, NULL, NULL),
(886, 367, 'До Тебе мій Боже душею', 10, 'Куплет 1\nДо Тебе, мій Боже, душею я лину,\nДо Тебе всім серцем я рвусь.\nЩоденно борюсь я і кожну хвилину \nТобі, мій Спаситель, молюсь.\n\nПриспів: \nДо Тебе молитву приношу,\nХай Дух Твій у серці живе.\nКеруй моїм серцем, Тебе щиро прошу, \nХай буде все власне Твоє!\n\nКуплет 2\nМолюсь я за світ, що в гріхах погибає,\nЗа братство, що в світі живе.\nЧому ж так буває, що сил не хватає,\nІ плоть моя борить мене?\n\nКуплет 3\nЧому я не можу на ниві трудитись,\nЯк, було, трудився колись?\nЧому я не можу так щиро молитись,\nЯк вперше до Тебе моливсь?\n\nКуплет 4\nЧи може життя є важке непомірно?\nЧи сумнів проймає мене? \nЧи може втомивсь я на хресній дорозі? \nЧи щиро не люблю Тебе?\n\nКуплет 5\nЧи може я брата не люблю прийняти?\nЧи гордість ще мучить мене?\nЧи ворога я ще не вмію прощати?\nЧи гріх ще у серці живе?\n\nКуплет 6\nПрости, любий Боже, за те, що не діяв, - \nЯк Слово навчає Твоє,\nХоч діяти завжди у серці я мріяв, - \nПрости, Милосердний, мене.\n\nКуплет 7\nБо тільки з Тобою, я можу здолати, - \nУсе, що так гнобить мене, - \nДай сили мені у годину скорботи,\nЩоб славити вічно Тебе.', '', '', 'ua', NULL, 0, NULL, NULL),
(887, 368, 'Радісні ті діти', 0, 'Куплет 1\nРадісні ті діти, Отцем яких є Бог!\nРадісні ті діти, в яких є Дух Святий!\nРадісні ті діти, що в Церкві істинній!\nРадісні ті діти, хто двічі народивсь!\nРадісні ті діти, по вірі хто хрестивсь!\nРадісні ті діти, хто в небі буде жить!\nРадісні ті діти, чий каганець горить! \nРадісні ті діти, що люблять Біблію!\nРадісні ті діти, в любові хто живе!\nРадісні ті діти, що завжди моляться!\nРадісні ті діти, яких Спаситель спас.\nРадісні ті діти - воскреснуть для життя!\nРадісні ті діти, яким Бог дасть вінець!', '', '', 'ua', NULL, 0, NULL, NULL),
(888, 369, 'На Христа дивися', 0, 'Куплет 1\nНа Христа дивися, - Він взірець тобі.\nВіруй і молися, - поміч Він в журбі.\nВін умер за тебе, взяв твій гріх Він Сам,\nУ твоїй потребі вір Його словам.\n\nКуплет 2\nНа Христа дивися, йди за Ним услід,\nЙ хвилі не барися залишити світ\nХоча ти й безсилий в боротьбі з гріхом, \nСпас твоя є сила, йди за Ним слідом.\n\nКуплет 3\nНа Христа дивися й твердо в вірі стій,\nПеред Ним корися, Він - Спаситель твій.\nПоки день ясніє й сонечко сія.\nВіра та надія зміцниться твоя.\n\nКуплет 4\nНа Христа дивися, вірним Йому будь,\nІ коли скінчиться ця скорботна путь,\nІ важка дорога прийде до кінця,\nВід твойого Бога матимеш вінця.', '', '', 'ua', NULL, 0, NULL, NULL),
(889, 370, 'Бог чудово створив небеса', 0, 'Куплет 1\nБог чудово створив небеса:\nМісяць, зорі по небу пливуть.\nЯ свій зір підіймаю туди,\nМоє серце, думки туди йдуть.\n\nКуплет 2\nБачу в небі чудову красу,\nЩо говорить про Бога-Творця.\nЗрозуміти не можу людей,\nЩо не вірять у Сина й Отця.\n\nКуплет 3\nВся природа говорить для нас,\nЩо для всього цього є Творець.\nЗемля й небо, співайте Йому,\nБо достойний хвали наш Отець.\n\nКуплет 4\nНе лишає ніколи нас Бог,\nНе спішить, щоб карати за гріх.\nЩоб не ласка Його до всіх нас,\nТо ніхто б ввійти в небо не зміг.', '', '', 'ua', NULL, 0, NULL, NULL),
(890, 371, 'Білий сніг', 0, 'Куплет 1\nБілий сніг упав на землю, все покрив кругом,\nВся природа спочиває тихим мирним сном.\nТи Свої благословіння, Боже, нам пошли \nЯк на землю посилаєш кожної зими.\n\nПриспів: \nБілий, білий сніг (2р.) скільки оком глянь.\nТи благослови (2р.) весь наш рідний край. \nПросимо Тебе (2р.), Боже, ми в цей час, \nЩоб благословив Ти (2р.) кожного із нас.\n\nКуплет 2\nВсі сади, поля, посіви снігом Ти покрив,\nВід морозу і від вітру Ти їх захистив,\nТакож нас в житті земному, Боже, захищай,\nВід лукавого і злого нас охороняй.\n\nКуплет 3\nІ якщо багато снігу, - буде урожай \nНашу землю, нашу ниву Ти благословляй,\nДай і нам плоди принести, Боже, в цім житті,\nЩоби були ми готові в небо увійти.', '', '', 'ua', NULL, 0, NULL, NULL),
(891, 372, 'В сльозах приходжу', 0, 'Куплет 1\nВ сльозах приходжу я до Тебе, всесильний Батьку дорогий, \nТи пригорни мене до себе, дай радість Ти душі моїй.\n\nПриспів: \nНехай же буде Твоя воля,\nНехай святиться ім’я Твоє,\nНехай же буде Твоя воля, нехай, нехай.\n\nКуплет 2\nЯк часто душу огортають гіркі сумніви у житті,\nТа Ти мені допомагаєш все далі, далі йти.\n\nКуплет 3\nКоли сльоза туманить око, а серце плаче і щемить, \nТоді душа моя так хоче Тебе побачити в цю мить.\n\nКуплет 4\nНехай душа моя співає, а серце рветься в небеса. \nТебе я, Боже, величаю за чудні, дивнії діла.', '', '', 'ua', NULL, 0, NULL, NULL),
(892, 373, 'О ласкавий мій Спаситель', 0, 'Куплет 1\nО, ласкавий мій Спаситель, Ти поміг мені в житті. \nБачив Ти мої страждання, бачив Ти журбу мою.\n\nПриспів: \nМені легко на дорозі, як з Тобою я іду. \nДаєш світло Своїм Словом \nІ несеш журбу мою.\n\nКуплет 2\nО, мій Спасе, будь зі мною, захищай від ворогів.\nБо я хочу жить з Тобою скільки Ти назначив днів.\n\nКуплет 3\nХочу все Тобі віддати: душу, тіло і любов.\nХто б так міг мене кохати? Тільки Ти, що пролив кров.\n\nКуплет 4\nЯ багато настраждався, сліз немало вилив я.\nТа коли Ти йдеш зі мною, Ти надія є моя.', '', '', 'ua', NULL, 0, NULL, NULL),
(893, 374, 'Боже великий', 0, 'Куплет 1\nБоже великий, могутній та добрий,\nЯк дуже Ти любиш людей!\nТи щастя даруєш, Ти тьму проганяєш,\nТи сльози втираєш з очей.\n\nКуплет 2\nЧим ми заробили любов Твою, Боже,\nВ пороках усіх та гріхах?\nЗагинули б всі ми, та Ти доторкнувся, \nПромінням сяйнув у серця.\n\nКуплет 3\nХвала Тобі, Боже, за нашу планету,\nЗа наші щасливі серця,\nЗа хліб, що ми маєм, за ласку й турботу,\nЗа наші на небі місця.\n\nКуплет 4\nНехай же весь світ принесе щиру вдячність \nТому, Хто від смерті нас спас,\nХто кожного з нас береже й опікує,\nХто в небо веде усіх нас.', '', '', 'ua', NULL, 0, NULL, NULL),
(894, 375, 'До Христа вузенька стежка', 0, 'Куплет 1\nДо Христа вузенька стежка \nІ по ній нелегко іти.\nТам безліч перешкод, туманів і негод,\nТа з Богом йду я до мети.\n\nПриспів: \nІди зі мною по вузькій стежині,\nА Бог поможе подолати тяжкий шлях.\nІди зі мною по вузькій стежині\nКінець якої - Боже Царство в небесах.\n\nКуплет 2\nА навкруги життя кипить,\nТа без Бога воно лиш дочасне.\nКоли твій час пройде, і смерті мить прийде,\nТо лиш в Христі знайдеш Ти щастя.\n\nКуплет 3\nІсус Христос за всіх вмирав \nІ воскрес, щоб весь світ був спасенний. \nПрийди ж ти до Христа - і кров Його свята \nОбмиє гріх з душі твоєї.', '', '', 'ua', NULL, 0, NULL, NULL),
(895, 376, 'Любий друже', 0, 'Куплет 1\nЛюбий друже, скільки раз в житті \nТи в знемозі прихиляв коліна,\nІ молився Господу в журбі,\nВідганяючи усі сумніви.\n\nПриспів: \n3 хвилюванням слухав ти тоді \nВ твоїм серці радіснії звуки.\nЙ рятували завжди від біди \nДобрії, невидимії руки.\n\nКуплет 2\nСкільки раз ці руки біль душі \nНіжно так з любов’ю обіймали \nІ утомленого у житті \nТебе руки ніжно пригортали.\n\nПриспів: \nА коли непрошена сльоза\nЗастеляла взір твій в час розлуки, \nВитирали сльози ніжно так \nДобрії, невидимії руки.\n\nКуплет 3\nРуки в ранах від страждань важких \nПринесли всім грішникам спасіння,\nІ на протязі усіх віків\nРуки шлють з небес благословіння.\n\nПриспів: \nА коли гріху прийде кінець,\nЗникнуть назавжди страждання й муки, \nПокладуть на голову вінець \nГоспода сіяючії руки.', '', '', 'ua', NULL, 0, NULL, NULL),
(896, 377, 'Ось знову день', 0, 'Куплет 1\nОсь знову день, як мить, пробіг, минає так життя,\nТі сірі будні суєти, в яких Христа нема.\nКоли ж приходить Він в тиші\nХоч в дощ, хоч в град, хоч в сніг -\nВсе оживає у мені, і сум зникає вмить.\n\nПриспів: \nІсус, о Ісус! Тебе побачу я колись.\nІсус, о Ісус! З Тобою хочу буть завжди.\n\nКуплет 2\nДо Тебе я прийшов в мольбі, нічого не скривав.\nСказав: «Ісус, пробач мені». Мені Ти руку дав.\nІ з того часу у житті \nЧи в дощ, чи в град, чи в сніг,\nТак тихо й вільно на душі, коли Ти поруч є.\n\nКуплет 3\nІ не забуть мені любві Твоїх пробитих рук,\nЩо дарували і мені спасіння від всіх мук.\nЯ вірю: зустріч близька ця.\nТуди всім серцем рвусь.\nТам мрія збудеться моя, з Тобою я зіллюсь.', '', '', 'ua', NULL, 0, NULL, NULL),
(897, 378, 'Серцем устами Ісус дорогий', 0, 'Куплет 1\nСерцем, устами, Ісус дорогий,\nБуду я славить Тебе, мій Благий.\nТут на землі, серед горя й біди\nПотім на небі - спішу я туди. Алілуя! Алілуя!\n\nКуплет 2\nЗ ніжним світанком недільного дня \nПеред Тобою схиляюся я.\nДухом Святим Ти мене наповни,\nЯк Ти за мене страждав, розкажи.Алілуя! Алілуя!\n\nПриспів: \nАлілуя! Кров Христа.\nАлілуя! Нас спасла. Алілуя! Алілуя!,\n\nКуплет 4\nБуду я вічно хвалити Христа,\nПісня нехай наповняє уста.\nВ ранню весну і в холодну зиму\nБуду я вічно співати Христу. Алілуя! Алілуя!\n\nКуплет 5\nПіснею слави хай буде життя \nЗ раннього ранку до заходу дня,\nЗ юності - перших поривів любві,\nВ зрілих роках і до сивини. Алілуя! Алілуя!', '', '', 'ua', NULL, 0, NULL, NULL),
(898, 379, 'Я дякую Спасител', 0, 'Куплет 1\nЯ дякую, Спаситель, Господь із Назарету,\nБо в Тобі радість дивну я знайшов.\nКоли одного разу мене в житті зустрів Ти \nІ в Край святий дорогу показав.\n\nКуплет 2\nНазустріч мені вийшов Господь із Назарету, \nПовів шляхом, якого я не знав.\nНим люди йшли спасенні, бо кров’ю Заповіту \nТи їх обмив, простив і оправдав.\n\nКуплет 3\nЯ бачив сльози щастя і радісні обличчя \nВ усіх, хто тим святим шляхом ішов.\nЯ чую, як ласкаво Твій ніжний голос кличе \nЩоби весь світ прийняв Твою любов.\n\nКуплет 4\nВеди мене і дальше, Господь із Назарету \nДорогою любові і добра.\nЩоб людям міг я нести Твоєї правди світло \nЙшов за Тобою по твоїх слідах.\n\nКуплет 5\nВеди мене, Дух Божий, Господь із Назарету,\nЯ знаю, що Ти - Правда і Життя.\nЗа муки і страждання, за кров святу пролиту \nТобі подяка, слава і хвала!', '', '', 'ua', NULL, 0, NULL, NULL),
(899, 380, 'Християнин неси вогонь', 0, 'Куплет 1\nХристиянин, неси вогонь чудесний свій,\nДарований тобі Христом.\nПомер Він на хресті, в жертву Себе віддав,\nЛюбові всім вогонь приніс.\n\nПриспів: \nПалай, вогонь, завжди палай.\nЗігрій собою ти холоднії серця, \nІ світ новий, чудовий освіти,\nВ якому радість без кінця.\n\nКуплет 2\nОсь мандрівник... втомився він в земній борні.\nЗігрій його та підбадьор,\nСкажи, що не покине його вічний Бог,\nЗасвітить сонце на шляху.\n\nКуплет 3\nЯкщо вже мандрівник звернув з того шляху, \nКотрий до радощів веде,\nТо ти вогонь любові в ньому запали,\nЩоб він той шлях міг знов знайти.', '', '', 'ua', NULL, 0, NULL, NULL),
(900, 381, 'Я блукав у цьому світі', 0, 'Куплет 1\nЯ блукав у цьому світі, як я Бога ще не знав,\nТа, й не знав я мого Спаса, що життя я в Нім знайшов.\n\nКуплет 2\nВін Сам взяв мене за руку, очі Він мої відкрив \nТа й сказав, щоб я за Ним йшов, бо мене Він полюбив.\n\nКуплет 3\nО, як любо мати Спаса, коли в серці моїм є.\nПровідник Він в житті моїм, світло правди і добра.\n\nКуплет 4\nТепер я йду за Ісусом, бо Він душу спас мою.\nІ в цей світ більш не дивлюся, Ісус в серці моїм є.', '', '', 'ua', NULL, 0, NULL, NULL),
(901, 382, 'Ми вам звіщаєм', 0, 'Куплет 1\nМи вам звіщаєм спокій (Зр.)\nМи вам звіщаєм спокій, спокій, спокій у Христі.\n\nКуплет 2\nМи вам звіщаєм радість (Зр.)\nМи вам звіщаєм радість, радість, радість у Христі.\n\nКуплет 3\nМи вам звіщаєм любов (Зр.)\nМи вам звіщаєм любов, любов, любов у Христі.\n\nКуплет 4\nМи вам звіщаєм спокій, ми вам звіщаєм радість, \nМи вам звіщаєм любов,\nМи вам звіщаєм спокій, радість, любов у Христі.', '', '', 'ua', NULL, 0, NULL, NULL),
(902, 383, 'Спасе мій', 0, 'Куплет 1\nСпасе мій, в цьому світі гріха й марноти\nМи Тобі лише хочем служити.\nСвої юнії дні, щоб віддати Тобі,\nКаганцем у темряві світити.\n\nКуплет 2\nСерця юні свої ми цілком віддаєм \nНа служіння Тобі, любий Боже,\nСили дай в боротьбі, щоби ворога й тьму \nНам здолати Твоєю любов’ю.\n\nКуплет 3\nДай життя провести до вподоби Тобі\nІ з темряви загиблих спасати.\nДо кінця хрест тяжкий поможи донести,\nЩоб спасенними разом нам стати.', '', '', 'ua', NULL, 0, NULL, NULL),
(903, 384, 'Коли Дух Господній', 0, 'Куплет 1\nКоли Дух Господній наповняє мене,\nСпіваю, як Давид\nСпіваю, співаю, співаю, як Давид. (2р.)\n\nКуплет 2\nКоли Дух Господній наповняє мене,\nМолюся, як Давид.\nМолюся, молюся, молюся, як Давид. (2р.)\n\nКуплет 3\nКоли Дух Господній наповняє мене,\nЯ плачу, як Давид.\nЯ плачу, я плачу, я плачу, як Давид. (2р.)\n\nКуплет 4\nКоли Дух Господній наповняє мене,\nСпіваю, як Давид.\nКоли Дух Господній наповняє мене,\nМолюся, як Давид.\nСпіваю, молюся і плачу, як Давид. (2р.)', '', '', 'ua', NULL, 3, '2021-03-19', NULL),
(904, 385, 'Як цінні ці хвилини', 0, 'Куплет 1\nЯк цінні ці хвилини жити в спільності з Христом. \nРадість серце наповняє, що дітьми ми є Його. \nНе від нас це все залежить, це Спаситель нам придбав.\nНа хресті Він кров святую за нас грішників проляв.\n\nПриспів: \nСкоро день цей настає,\nІ Спаситель наш прийде.\nКожний вірний це одержить,\nЩо Спаситель нам дає.\n\nКуплет 2\nО, як Він ще закликає всіх, хто чує, до Себе.\nІ знайдете відпочинок лише тільки у Христа.\nБо нема рятунку в інших, що живуть тут на землі.\nI не знають, де шукати, - лише тільки у Христі.', '', '', 'ua', NULL, 0, NULL, NULL),
(905, 386, 'Чи знаєте люди', 0, 'Куплет 1\nЧи знаєте, люди, що прийде той день,\nЯк прийде, Спаситель судити людей. (2р.)\n\nКуплет 2\nЧи знаєте, люди, що прийде той час,\nЯк прийде Спаситель розлучати нас? (2р.)\n\nКуплет 3\nЧи знаєте, люди, що світу кінець?\nХто заслужить Царство, одержить вінець. (2р.)\n\nКуплет 4\nА гучнії громи будуть гриміти,\nА голосні труби будуть трубіти. (2р.)\n\nКуплет 5\nБуде під ногами земля дрижати,\nЩо не зможуть мертві в гробах лежати. (2р.)\n\nКуплет 6\nУставайте мертві - годі вам лежать,\nТреба перед Богом відповідь давать. (2р.)\n\nКуплет 7\nЯк зійшов Спаситель з праведним мечем, \nЗібрав праві душі і в Царство повів. (2р.)\n\nКуплет 8\nА грішнії душі плачуть, ридають,\nДо Господа Бога руки здіймають. (2р.)\n\nКуплет 9\nА Господь почув їх, відповідь їм дав:\n«Ідіть ви, прокляті, вам місця нема.» (2р.)\n\nКуплет 10\nА грішнії люди плачуть, ридають,\nОтця свого, неньку та й проклинають: (2р.)\n\nКуплет 11\n«Чом ти, моя ненько, та й не навчила,\nЩоб я собі Царство та й заслужила? (2р.)\n\nКуплет 12\nТи мене учила хороше ходить,\nА тепер прийдеться вік в вогні горіть. (2р.)\n\nКуплет 13\nТи мене учила, що Бога нема,\nНаука про Нього, що то якась тьма. (2р.)\n\nКуплет 14\nА тепер я бачу: святий Він сидить,\nРозкрив Вічну Книгу, та й буде судить. (2р.)\n\nКуплет 15\nА праведні душі та й радуються,\nЩо їхньому Царству не буде кінця.» (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(906, 387, 'Наша надія Ти Христос', 0, 'Куплет 1\nНаша надія - Ти, Христос.\nТи наша радість, наша любов,\nТи наше щастя і життя,\nТи наше світле майбуття.\n\nПриспів: \nЛиш на Тебе ми вповаєм,\n Вгору руки підіймаєм,\nЛиш на Тебе споглядаєм\n Ввись до небес.\n\nКуплет 2\nТи постраждав за нас, Христос,\nТи на хресті пролив Свою кров\nІ нам спасіння вічне приніс,\nВикупив нас від горя й сліз.', '', '', 'ua', NULL, 1, '2020-11-29', NULL),
(907, 388, 'Ось на наших з тобою столах', 0, 'Куплет 1\nОсь на наших з тобою столах \nХліба бачим завжди достаток.\nА в далеких чужих краях \nЛюдей з голоду гине багато.\n\nПриспів: \nІсус каже: «Я є хліб».\nА без хліба життя немає.\nХто без Бога в цім світі живе,\nЖиття вічного той не має.\n\nКуплет 2\nУ голодного думка така:\nЗа окраєць віддав би маєток.\nА у нас іноді бува -\nВикидають окраєць діти.\n\nКуплет 3\nПам’ять наша не держить зла \nІ голодних не пам’ятає.\nМи лиш знаєм право таке:\nЗадарма наїдатися хлібом.\n\nКуплет 4\nОсь гряде попереду день,\nКоли жниво Господнє настане\nДобрим ділом, друже, скажи,\nЩо для Бога зерном ти став вже.', '', '', 'ua', NULL, 0, NULL, NULL),
(908, 389, 'О невже ти підеш', 0, 'Куплет 1\nО, невже ти підеш, не прийнявши Христа,\nЩоб далі в темряві блукать?\nДар Божий - спасіння - відкинеш навік \nІ не приймеш Христа благодать?\n\nПриспів: \nО, невже ти підеш? (Зр.)\nНе прийнявши Христа.\nО, невже ти підеш?\n\nКуплет 2\nІсус із любові страждав на хресті,\nЩоб грішних з темряви звільнить.\nТвої всі гріхи у пречистій крові \nВін може ще нині обмить.\n\nКуплет 3\nО, невже ти підеш? То ж другом своїм \nТи можеш прийняти Христа.\nВін став би хранителем вірним твоїм. \nЦінніша чи є честь така?\n\nКуплет 4\nО, друже, сьогодні Христа не відкинь.\nСпокій дасть тобі тільки Він.\nНа заклик Його поспіши без вагань,\nПокайся і будеш спасен.', '', '', 'ua', NULL, 0, NULL, NULL),
(909, 390, 'Бог в світ послав', 0, 'Куплет 1\nБог в світ послав Свого нам Сина.\nВін на хресті за всіх помер.\nІ хоч Його в могилу вклали,\nПорожній гріб всім свідчить нам, що Він живе!\n\nПриспів: \nБо Він живе, я надію маю.\nБо Він живе - весь страх пройде.\nІ знаю я - мене Він любить!\nТепер живу для Нього, бо Ісус живе!\n\nКуплет 2\nХоч часто це життя сумне є,\nГріх нам спокою не дає.\nВін через смерть гріхи обмив всі, - \nТо будем жити вічно з Ним, бо Він живе!\n\nКуплет 3\nІ прийде час - мій день скінчиться,\nІ з болем боротьба пройде.\nВін перемогу дасть над смертю!\nЙого побачу в небі: там Ісус живе!', '', '', 'ua', NULL, 0, NULL, NULL),
(910, 391, 'О алілуя амінь', 0, 'Куплет 1\nО, алілуя, амінь! Царство Боже близько.\nО, алілуя, амінь! Схиліться в дусі низько.\nО, алілуя, амінь! Складіть всі славу Богу.\n\nПриспів: \nАлілуя, алілуя, слава Богу\n Алілуя, алілуя, Дух Святий. (2р)\n\nКуплет 2\nО, алілуя, амінь! Живе Отець на небі.\nО, алілуя, амінь! Куди прийдуть всі діти.\nО, алілуя, амінь! В Його ми будем світлі.\n\nКуплет 3\nО, алілуя, амінь! Співайте пісню в дусі.\nО, алілуя, амінь! Немає місця смутку.\nО, алілуя, амінь! Візьміться всі за руки.', '', '', 'ua', NULL, 0, NULL, NULL),
(911, 392, 'Пролетять стрілою молодії роки', 0, 'Куплет 1\nПролетять стрілою молодії роки,\nСтомиться серденько від турбот, тривоги.\nОслабіє тіло, ослабіють сили,\nСтане душу мучить близький час могили.\n\nПриспів: \nЛиш щасливий той,\nХто в сивину глибоку\nРадісно згадає молодії роки.\n\nКуплет 2\nІ ніхто не зможе втішити ридання.\nЛиш заб’ється серце, закипить страждання.\nХто в роках пройдешніх бачить лише втрату \nТа не служить Богу, істині і брату.\n\nКуплет 3\nО, не тратьмо, друзі, дармо наші роки,\nУ Христа візьмемо добрії уроки,\nПомагайте ближнім, підбадьорте брата,\nЩоб згадать на старість юність, а не втрату.', '', '', 'ua', NULL, 0, NULL, NULL),
(912, 393, 'Радію я і торжествую', 0, 'Куплет 1\nРадію я і торжествую\nСпасенний я кров’ю Христа.\nХриста Ісуса прославляю,\nЯк вірне Його дитя.\n\nПриспів: \nІсус Христос мене звільнив\nІ дав мені вічне життя,\nГріхи простив, в крові обмив\nІ нині я - Боже дитя.\n\nКуплет 2\nСпасенний я в Христі Ісусі,\nСловами не можна сказать.\nВін в серці моїм поселився\nІ любо в Нім пробувать.\n\nКуплет 3\nВінець готовий мій, я знаю,\nУ вічних оселях Христа.\nЯ з вірою Христа чекаю,\nЩоб з Ним пробувать до кінця.', '', '', 'ua', NULL, 2, '2021-02-21', NULL),
(913, 394, 'Бог є любов а я не знав', 0, 'Куплет 1\nБог є любов, а я не знав. Мене Він полюбив,\nЩо Сина Він на смерть віддав, гріхи мої простив.\n\nПриспів: \nПростив, простив гріхи мої,\nПростив. Він кров пролив аби я жив.\nВін гріх мій на хресті простив, простив.\n\nКуплет 2\nБог є любов, чи знаєш ти? Страждав Він на хресті.\nТобі Він хоче спочинок дать, з душі тягар здійме.\n\nКуплет 3\nБог є любов. Чи хочеш ти у вічності з Ним жить?\nЧи кинеш гріх, чи поспішиш ти Богові служить?\n\nКуплет 4\nБог є любов. Він на хресті п’ять ран за нас прийняв.\nЧи є життя Його в тобі? Чи Бога ти пізнав?\n\nКуплет 5\nБог є любов. О, друже мій, до Нього ти прийди:\nСкажи: Прости, я буду Твій; тягар з душі здійми.', '', '', 'ua', NULL, 0, NULL, NULL),
(914, 395, 'Радуйтеся усі люди', 0, 'Куплет 1\nРадуйтеся усі люди,\nРадість з неба вам хай буде.\n\nПриспів: \nВеселая вам новина,\nПородила Діва Сина, | Марія! (Зр.)\n\nКуплет 2\nЗійшов до нас з високості \nТой, що всі гріхи нам простить.\n\nКуплет 3\nДо ясел всі поспішаймо,\nСлаву й честь Йому віддаймо.\n\nКуплет 4\nБудьмо щирі та багаті\nНа добро завжди завзяті.', '', '', 'ua', NULL, 0, NULL, NULL),
(915, 396, 'Великая Школа в цім світі', 0, 'Куплет 1\nВеликая Школа в цім світі існує,\nДавно для людей її Бог збудував,\nХоч ворог так часто ту школу руйнує,\nТа завжди Господь Бог той дім поправляв.\n\nПриспів:\n Мій друже, спіши до Господньої школи,\nДо серця науку святую приймай.\nТоді лиш настане кінець цій недолі, \nПовернеться радість, і щастя, і рай.\n\nКуплет 2\nВ тій Школі є милий та славний Учитель;\nТак любо навчає, як в світі цім жить.\nТо вічний, єдиний Ісус наш Спаситель\nПрийшов Він, щоб людям всім очі відкрить.\n\nКуплет 3\nВ тій Школі любов та лиш згода панує \nЛюбов в ній палає, нема їй кінця,\nА зло і неправду, ненависть руйнує,\nЗм’якшає стальні й зачерствілі серця.\n\nКуплет 4\nІ знатних й незнатних в ту Школу приймають,\nХто тільки низеньким при вході зробивсь.\nТаланти та здібності вмить наділяють,\nКорисним для Бога там всякий родивсь.', '', '', 'ua', NULL, 0, NULL, NULL),
(916, 397, 'В очах твоїх сльози', 0, 'Куплет 1\nВ очах твоїх сльози чому так блищать?\nІ рани сердечні невпинно болять?\nСумніви та смуток, що гноблять твій дух,\nЖиття огорнув такий страшний недуг.\n\nКуплет 2\nЧи віри забракло у серці твоїм?\nНадія затрачена в Бозі Живім?\nТвій Бог є великий, Всесильний, - згадай!\nДо Нього з молитвою ти поспішай.\n\nКуплет 3\nЛиш тільки до Спаса Христа ти прийдеш,\nИ Нім радість, і щастя, і спокій знайдеш.\nЗагояться рани, твій дух оживе,\nI радісна пісня з грудей попливе.', '', '', 'ua', NULL, 0, NULL, NULL),
(917, 398, 'Вже надходить той день', 0, 'Куплет 1\nВже надходить той день, де не буде горя вже.\nАні хмар на небесах, ані сліз, що на очах. \nТой спокій навіки вже в золотім краю буде.\nЩо за день, славний день той буде!\n\nПриспів:\n Що за день то буде, як побачу я Христа,\nЯк погляну на лице, на Того, Хто Спас мене, \nЯк за руку Він візьме, в Дім Отця мене введе, \nЩо за день, радісний день то буде!\n\nКуплет 2\nЩо за день то буде, як Ісус Господь прийде,\nЩоб забрати усіх нас в ті оселі,що для нас.\nЯк на хмарах Він прийде, вірних зустріч там буде!\nЩо за день, славний день то буде!', '', '', 'ua', NULL, 0, NULL, NULL),
(918, 399, 'В чудові дні юначих літ', 0, 'Куплет 1\nВ чудові дні юначих літ не знав я зла й біди,\nНе знав журби і клопотів від ранку до зорі.\nЯ не тривожився нічим, по волі жив своїй.\nА серце завжди наповняв біль матері моїй.\n\nПриспів:\nВ молитві матері	\n(Я чув в молитві матері), 2р.\nЯ часто чув своє ім’я в молитві матері.\n\nКуплет 2\nХодив за голосом бажань, не думав про Творця,\nТим задавав я матері скорботи без кінця.\nТак серце мами день і ніч томилося одне.\nЯ чув щодня: вона в сльозах молилась за мене.\n\nКуплет 3 \nВесь час моїх веселих днів я мамин голос чув:\n«Дивись, мій сину, пам’ятай, щоб слів цих не забув:\nЗла не чини, втікай з гріха, себе ти бережи.»\nЯ чув в молитві матері своє ім’я завжди.\n\nКуплет 4\nТепер знайшов я у Христі спасіння для душі.\nТягар гріхів я склав Йому в молитві у тиші.\nІ щастя, і відкуплення, і промінь той святий \nПролив Христос на розум мій за молитви її.', '', '', 'ua', NULL, 0, NULL, NULL),
(919, 400, 'Люблю Господь Твій Дім', 0, 'Куплет 1\nЛюблю, Господь, Твій Дім, бо там Христа Любов,\nБо там я бачу Його Кров, за нас пролиту Ним.(2р.)\n\nКуплет 2\nЛюблю Предвічний Бог, я Церкву — Храм живий. \nЇї боронить Дух Святий від горя і тривог. (2р.)\n\nКуплет 3\nЗа Церкву я молю, за всіх її дітей.\nЛюблю я Церкву із людей, улюблену Твою. (2р.)\n\nКуплет 4\nЯ радий би, друззя, до віку бути в ній, \nЩоб помогти в порі сумній нести її хреста. (2р.)\n\nКуплет 5\nЯ знаю, що разом до Господа ми йдем.\nЯ вірю, вірю, що будем співать перед Христом. (2р.)', '', '', 'ua', NULL, 25, '2021-04-11', NULL),
(920, 401, 'Дорогий Завіт Ісуса', 0, 'Куплет 1\nДорогий Завіт Ісуса, що Він вірним обіцяв:\n«Нa шляху з землі до неба поведу тебе Я Сам».\n\nПриспів: \nПоведу Я, поведу Я, поведу тебе Я Сам.\n\nКуплет 2\nКоли ворог тебе зводить із шляху, що ти прийняв,\nПам’ятай, що Він говорить: «Поведу тебе Я Сам».\n\nКуплет 3\nКоли серце перестане уповати на Христа - \nТо чуй з вірою слова ці: «Поведу тебе Я Сам».\n\nКуплет 4\nКоли дні життя кінчаться, і остання хвиля йде,\nТо й тоді звучать слова ці: «Поведу тебе Я Сам».', '', '', 'ua', NULL, 0, NULL, NULL),
(921, 402, 'Як син марнотратний', 0, 'Куплет 1\nЯк син марнотратний, так і я нещасний \nВ тім світі блудив.\nДуша все стогнала, спокою не мала,\nБо гріх її томив.\n\nКуплет 2\nДуша все стогнала, була в серці спрага, \nЩоб спокій знайти.\nТа мертві обряди не дали розради \nВтомленій душі.\n\nКуплет 3\nШукав я повсюди, де казали люди \nСпасіння собі.\nАле світ лукавий, як той важкий камінь,\nВсе душу гнобив.\n\nКуплет 4\nВтомлений душою, я чув за собою \nХтось кликав мене:\n«Вернись блудний сину, ти йдеш до загину, \nЯ прийму тебе».\n\nКуплет 5\nІ я оглянувся на той дивний поклик,\nХто кликав мене.\nНа хресті прибитий, і кров’ю облитий \nСказав до мене:\n\nКуплет 6\n«Глянь на мої рани, на лице криваве,\nЗвідки кров текла.\nТи - грішник, Я знаю. Я в муках вмираю, \nЩоб дати життя».\n\nКуплет 7\nВід тої хвилини спасен я, щасливий,\nЖиття все віддав \nСпасителю свому, Цареві і Богу,\nПовік Його став.', '', '', 'ua', NULL, 0, NULL, NULL),
(922, 403, 'Не сумуй', 0, 'Куплет 1\nНе сумуй, що так склалось у тебе життя, \nТерен густо поріс на дорозі,\nНе сумуй, що нема на землі співчуття \nНа гарячі, гіркі твої сльози.\n\nПриспів:\nНе сумуй, не сумуй! Христос каже тобі і мені. \nЛиш радій, лиш радій! Нагороду тримаю тобі.\n\nКуплет 2\nНе сумуй, що у світі ніхто не зумів \nДо кінця ввесь твій біль зрозуміти.\nНе сумуй, що за те, що ти щиро любив, \nСвіт спішив тобі злом заплатити.\n\nКуплет 3\nНе сумуй, що так довго самотнім ти був,- \nВ житті, може, ще важче прийдеться.\nНе сумуй, що від ближнього ти не почув \nТепле слово від щирого серця.\n\nКуплет 4\nНе сумуй, бо твоя, друже, кожна сльоза \nВ Книзі пам’ятній пишеться в небі.\nНе сумуй, після горя - щаслива пора \nНезабаром настане для тебе.\n\nКуплет 5\nНе сумуй, бо вже явиться скоро з небес \nТой, Хто любить, Хто щиро жаліє.\nДо грудей Він, як батько, пригорне тебе,\nІ без слів до кінця зрозуміє.', '', '', 'ua', NULL, 0, NULL, NULL),
(923, 404, 'Він так любить всіх нас', 0, 'Куплет 1\nВін так любить всіх нас, що покинув небо,\nІ прийшов у грішний світ цей, щоб людей спасти.\nІ щоб кожен грішник, яким не був би грішним, З\nамість смерті життя вічне міг собі знайти.\n\nПриспів:\nВін родився, щоби гріх твій на Себе прийнять,\nБув розп’ятий на Голгофі, за тебе вмирав.\nІ тобі Він дав всю славу і любов Свою,\nНазавжди вернув в Країну неземну.\n\nКуплет 2\nО, невже ж сьогодні ти Христа не приймеш? \nЧом не можеш зрозуміти ту святу любов?\nО, невже ж даремно на хресті вмирав Він? \nПроливав за тебе там Свою невинну кров.\n\nКуплет 3\nВін так любить всіх нас, що покинув небо,\nІ прийшов у грішний світ цей, щоб людей спасти.\nТож прийди сьогодні на поклик Господній!\nВідчини сердечні двері і Христа впусти.', '', '', 'ua', NULL, 0, NULL, NULL),
(924, 405, 'Єрусалим що сходить з неба', 0, 'Куплет 1\nЄрусалим, що сходить з неба \nВ проміннях ясних свого Царя.\nТам більше сонце вже не потрібно,\nБо Агнець Божий - рання зоря.\n\nПриспів: \nОце оселя свята Бога з людьми, \nДе будем жити із Богом ми.\nТам усі сльози Ісус з очей зітре. \nСмерті не буде, біль промине.\n\nКуплет 2\nЄрусалим! Нове це місто,\nПерлинні брами відкриті в нім.\nХто прагне пити - нехай приходить, - \nДжерельні води течуть у нім.\n\nКуплет 3\nЄрусалим! Тебе кохаю.\nВ тобі панує вічна любов. \nСпасенні люди в тобі зійдуться. \nПрославлять Спаса за Його кров.', '', '', 'ua', NULL, 6, '2021-03-28', NULL),
(925, 406, 'Єдиним серцем і устами', 0, 'Куплет 1\nЄдиним серцем і устами \nХвалити Господа начнім.\nЧесть Богу даймо молитвами,\nСмиренно духа приклонім.\n\nКуплет 2\nМолитва щира, Богу мила,\nАж до небес ти вознесись,\nЯк благовонний дим кадила,\nЗа Церкву всю і нарід весь.\n\nКуплет 3\nВладико, Господи Небесний,\nПомилуй нас і пом’яни,\nПрийми молитву - дар словесний \nВід нужд й недолі бережи!\n\nКуплет 4\nТобі готові ми служити \nВесь вік синівської любві,\nТебе бажаємо просити - \nТи з неба нас благослови.\n\nКуплет 5\nІ благодать Свою зливай нам \nНа всякий день і всякий час,\nБезгрішно жити помагай нам,\nСпаси нас, Боже, Отче наш.', '', '', 'ua', NULL, 0, NULL, NULL),
(926, 407, 'З нами Бог', 0, 'Куплет 1\nЗ нами Бог! Хто буде проти нас? (З нами Бог!) (Зр.) \nТак Павло Апостол нам сказав.\n\nКуплет 2\nОсь Я з вами буду кожний день! (Кожний день!) (Зр.) \nТак Господь Спаситель нам сказав.\n\nКуплет 3\nКров Христа змиває всякий гріх! (Всякий гріх!) (Зр.) \nТак Іван Апостол нам сказав.\n\nКуплет 4\nДар Святого Духа нам (Господь обіцяв) (Зр.)\nТак пророк Йоіль пророкував.', '', '', 'ua', NULL, 0, NULL, NULL),
(927, 408, 'Залишись зі мною', 0, 'Куплет 1\nЗалишись зі мною, бо темніє вже,\nТьма прикриває, не лишай мене.\nЯ покладаюсь на любов Твою.\nТи моя поміч, залишись зі мною.\n\nКуплет 2\nТак і життя день короткий пройде,\nВся земна слава щезне раз-на-все.\nУсе зміняється в світі цьому,\nДруже незмінний! Залишись зі мною!\n\nКуплет 3\nЯ все бажаю всякий час Тебе,\nБо лиш з Тобою переможу все,\nБо хто ж є інший такий вірний друг?\nО, Спасе милий, залишись зі мною!\n\nКуплет 4\nДай, Спасе, щоб Твій хрест я бачив все.\nХай Він провадить все вперед мене.\nНадходить вічний день і проганя тьму,\nВ житті і смерті будь все зі мною.', '', '', 'ua', NULL, 0, NULL, NULL),
(928, 409, 'Ісус тебе чекає', 0, 'Куплет 1\nІсус тебе чекає, щоб любив (4р.)\n\nПриспів: \nНезалежно від раси\nЧи від кольору людей -\nТи люби всіх, як братів, роби добро.\n\nКуплет 2\nТому, хто біля тебе, дай любов (4р.)\n\nКуплет 3\nЯк тебе не вітають, дай любов (4р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(929, 410, 'Іскра Божа вже погасла', 0, 'Куплет 1\nІскра Божа вже погасла,\nСтали Бога забувать.\nЩо ж ви робите, нещасні?\nВи будете пропадать.\nБо колись-то обіцяв Бог - \nНа землі усіх спасти.\nПослав Сина Свого з неба,\nЩоб звільнити нас з гріхів.\n\nКуплет 2\nБо гріхи - це путь розлога,\nПо якій народи йдуть,\nВорог так завів глибоко,\nЩо не можна повернуть.\nВже багато повертало \nІз широкої путі \nІ знаходять путь-стежину,\nЩоб до Бога нею йти.\n\nКуплет 3\nБо та стежка є вузенька,\nІ сам нею не пройдеш.\nПроси в Бога супроводу,\nТо скоріше перейдеш.\nБо Бог знає твоє серце,\nЯким шляхом ти ідеш,\nШляхом правди, чи шляхом кривди,\nЩо посіяв, те й пожнеш.\n\nКуплет 4\nБо за гробом там не сіють,\nТільки будуть пожинать.\nОдні в клунях, мов пшениця,\nДругі - мов кукіль - в вогні', '', '', 'ua', NULL, 0, NULL, NULL),
(930, 411, 'Краю мій', 0, 'Куплет 1\nКраю мій, серцем лину, щоб скоріш \nЯ в брами високі вже входив твої,\nЩоб там спочити, горе забути \nІ всі зітхання на цій землі.\n\nКуплет 2\nІ в сльозах, смутку, горю та журбі \nЯ тут томлюсь завжди на цій чужині. \nКоли згадаю про тебе, Краю,\nТо жаль стискає серце мені.\n\nКуплет 3\nКраю мій, Краю любий, дорогий,\nБогом збудований для Його дітей. \nДо Тебе лину, до Тебе прагну,\nСпішу до Тебе, Краю мій.\n\nКуплет 4\nЗоря ясна виринає вдалині,\nТо мій Край сіяє в рідній стороні \nТуди спішу я, де скоро буду \nВ Сіонськім милім тім краю', '', '', 'ua', NULL, 0, NULL, NULL),
(931, 412, 'Коли моє життя кінчатись буде', 0, 'Куплет 1\nКоли моє життя кінчатись буде,\nІ страх, мов камінь, стисне мою грудь,\nКоли почую голос, що покличе \nМене в незнану путь.\n\nКуплет 2\nТоді, мій Спасе, залишись зі мною,\nТак, як в житті стояв при мені Ти.\nЄдина втіхо небесної любові,\nМене не опусти.\n\nКуплет 3\nВудь близько мене, як усе зникає:\nРідня, знайомі, сестри і брати.\nЯк очі згаснуть, серце моє змовкне,\nМене не опусти.\n\nКуплет 4\nТебе Одного, Спасе мій, благаю \nВ годину смерті Ти мене кріпи.\nПодай надію в мою бідну душу,\nМене не опусти.\n\nКуплет 5\nБлаженне місце дай мені, о Боже,\nДе вже нема гріха, ні бур життя,\nТам, де спокій сповняє душу чисту,\nЖиве любов свята.\n\nКуплет 6\nПочую там пісні, ангельський голос,\nЩо їх ніхто на світі не чував.\nПритулок мій - в Тобі, мій милий Боже, \nЯкий мені Ти обіцяв.', '', '', 'ua', NULL, 0, NULL, NULL),
(932, 413, 'Моя мета далеко за рікою', 0, 'Куплет 1\nМоя мета далеко, за рікою,\nДо неї змалку я направив путь:\nБо там брати великою сім’єю \nМене до себе на вечерю ждуть.\n\nПриспів: \nЯ все пливу, вперед свій зір керую.\nВже сонечко заходить за обрій.\nХай ураган підноситься й бушує,- \nЯ до мети направив човен свій.\n\nКуплет 2\nЯ через води човен мій направив,\nВід берега далеко вже відбивсь,\nНазустріч хвилі й люті урагани,\nНемов би хочуть, щоб скоріш втопивсь.\n\nКуплет 3\nДалеко бачу світло за рікою,\nТам вже скінчиться небезпечна путь,\nБо там брати великою сім’єю \nМене до себе на вечерю ждуть.', '', '', 'ua', NULL, 0, NULL, NULL),
(933, 414, 'Між хвиль бурхливих', 0, 'Куплет 1\nМіж хвиль бурхливих, в життєвім морі \nНіде спокою нема душі.\nДуша так прагне Тебе, Спаситель,\nМолю, мій Боже, о поможи.\n\nПриспів: \nТак прагне серце моє спокою,\nЯ так стомився в борні земній,\nДуша страждає в напливах горя.\nО, Милосердний, зі мною будь.\n\nКуплет 2\nЗлоба невір’я та лицемір’я,\nЗловіщий відблиск гріха й вогню.\nЗло торжествує, але вже близько \nВеликий, славний Господній День!\n\nКуплет 3\nЯ вірю, Боже, що Ти вже скоро \nПрийдеш покласти всьому кінець.\nХто жив в надії на поміч Твою,\nТи подаруєш їм Свій вінець.', '', '', 'ua', NULL, 0, NULL, NULL),
(934, 415, 'Мама Мені слово це миле', 0, 'Куплет 1\nМама... Мені слово це миле,\nПовне воно ласки й любві.\nМама... на руках нас носила \nІ нас зберігала в любві..\n\nКуплет 2\nМама... скільки ти пережила,\nМама... скільки горя знесла!\nНас ти берегла і Любила,\nМама... найдорожча моя!\n\nКуплет 3\nМама... Хто так ніжно голубить?\nХто так сам не цінить себе?\nМама... Хто так ніжно ласкає?\nМама... так, тільки ти одна!\n\nКуплет 4\nТи нас до Христа приносила,\nТи нам помагала в біді.\nВ горі і в недолі плекала, — \nМама, хто подібний тобі?\n\nКуплет 5\nМама... Часто діти не люблять \nСтарість і турботу твою,\nЛаску й доброту вони гублять,\nМаму не жаліють свою.\n\nКуплет 6\nПізно, пізно буде при гробі \nПлакать і скорбіти в душі. \nДіти, вам коротка дорога.\nСкоро прийде смерть і до вас.\n\nКуплет 7\nСій, друг, але жати прийдеться \nВсе, що насадила рука.\nМаму ти шануй і побачиш \nЩастя, коли горе в житті.', '', '', 'ua', NULL, 0, NULL, NULL),
(935, 416, 'Многі вам літа', 0, 'Куплет 1\nМногі вам літа! (Зр.)\nМногі вам (Зр.) літа!\nБажаєм ми вам | радості щастя. (2р.) \nРадості (Зр.) щастя.\n\nКуплет 2\nЛюбов Христова | хай буде з вами. (2р.)\nХай буде (Зр.) з вами.\nІ хай утішить | Бог Святим Духом. (2р.) \nБог Святим (Зр.) Духом.\n\nКуплет 3\nБлагословить вас | хай Його ласка. (2р.)\nХай Його (Зр.) ласка.\nЛюбіте Бога І і Його діло. (2р.)\nІ Його (Зр.) діло.\n\nКуплет 4\nБудьте ви світлом І в темряві світу. (2р.)\nВ темряві (Зр.) світу.\nЖивіте в згоді. (Зр.)\nЖивіте (Зр.) в згоді.\n\nКуплет 5\nБажаєм ми вам | радості щастя. (2р.)\nРадості (2р.) щастя.\nВеликий Боже, ми Тебе просим:  \nБлагослови їх, благослови Ти їх \nРаз і навіки.', '', '', 'ua', NULL, 0, NULL, NULL),
(936, 417, 'Минають дитячі роки', 0, 'Куплет 1\nМинають дитячі роки,\nЯк мряка, коли сонце зійде. \nІ молодість також минула, - \nГосподь уже скоро прийде.\n\nКуплет 2\nМені так миленько велося, \nПриємно мені так було жить. \nЖаль мені те, що не можу \nЯ молодість ту завернуть.\n\nКуплет 3\nТепер то усе це змінилось.\nТурботи так мучать мене.\nАх молодість ти дорогая,\nВернися ти ще до мене.\n\nКуплет 4\nТа того вже бути не може,\nПро теє і думать на варт,\nБо скоро прийде вже могила \nІ тіло покриє земля.\n\nКуплет 5\nБог долю назвав усім людям,\nЗ землі вони й в землю підуть.\nА дух їх, який є від Бога,\nКуди ж він по смерті піде?\n\nКуплет 6\nКоли б мені вічно тут жити \nІ смерті ніколи не знать,\nКоли б молодим завжди бути, \nІ з Богом весь час проживать.', '', '', 'ua', NULL, 0, NULL, NULL),
(937, 418, 'На землі не все нам видно', 0, 'Куплет 1\nНа землі не все нам видно, але гляньмо в небеса:\nПеред нашими очима розкривається краса.\nЗірки, місяць, ясне сонце, що Господь їх сотворив,\nВиповняють Божу волю, яку Він їм доручив.\n\nПриспів: \nБог нам дав безсмертну душу,\nЖиття вічне обіцяв.\nВін простив нам всі провини,\nБожий Син за нас страждав.\nО, скажи, мій милий друже,\nЩо Йому за це ти дав?\n\nКуплет 2\nПташки знають свою пору, напрямок, куди летіть.\nДерева, квіточки знають, коли їм зазеленіть.\nВсе творіння славить Бога так, як Він кому звелів,\nДруже, що ти для Ісуса в житті доброго вчинив?\n\nКуплет 3\nБог дає все, що потрібно нам для тіла і душі.\nЙого очі всюди бачать, що Ми творимо в тиші.\nЧас прийде, Господь спитає кожного, що хто зробив \nІ розплатиться по правді, як хто в Нього заслужив.', '', '', 'ua', NULL, 0, NULL, NULL),
(938, 419, 'Господь хто увійде', 0, 'Куплет 1\nГосподь, хто увійде в Твою святиню святості? (2р.)\n\nПриспів: \nВ кого чисті руки та щиреє серце,\nНе йде за цим світом, а любить Христа.\n\nКуплет 2\nГосподь, хто увійде в Твою святиню, щоб прославлять? (2р.)\n\nКуплет 3\nГосподь, хто увійде в Твою святиню, щоб вічно жить? (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(939, 420, 'Юність юність', 0, 'Куплет 1\nО, юність, юність ти золотая,\nТи забираєш барви свої.\nІ непомітно підходить старість,\nІ заглядає в очі мої.\n\nКуплет 2\nПриходить час з тобою розстатись.\nТи відлітаєш, ніби у путь,\nІ наділяєш ти сивиною.\nОх, тебе, юність, більш не вернуть.\n\nКуплет 3\nПройшло дитинство, проходить юність,\nЗабуто все, що проживав.\nТільки одного забуть не можна,\nЩо в роках юних Бога пізнав.\n\nКуплет 4\nО, Боже, Боже, будь милосердний,\nВ тяжкі хвилини допомагай.\nДо сивини, і до могили \nТи мене, Боже, не залишай.\n\nКуплет 5\nО браття-сестри, будем трудитись.\nСпаситель буде нам помагать.\nВінець перлинний Він обіцяє \nТим, хто достоєн його прийнять.', '', '', 'ua', NULL, 0, NULL, NULL),
(940, 421, 'О як гарне святе місце', 0, 'Куплет 1\nО, як гарне святе місце, де всі вірні моляться.\nСкільки раз туди приходжу, чую, ніби в небесах.\n\nПриспів: \nПоглянь вгору, зір звернувши!\nВ небо мислями лину,\nРадість наповняє серце,\nЗабуваю про журбу.\n\nКуплет 2\nЧую тут побожні пісні, мов ангельський чудний спів. \nЗабуваю світ лукавий, рветься дух в блакить небес.\n\nКуплет 3\nТам колись при звуці сурем я з Ісусом увійду.\nУвільнить Він з журби й трудів, Його в Царстві восхвалю.', '', '', 'ua', NULL, 0, NULL, NULL),
(941, 422, 'Правда любить Бог мене', 0, 'Куплет 1\nПравда, любить Бог мене, Сам за мене постраждав.\nВ темну ніч чи в світлий день буть зі мною обіцяв.\n\nПриспів: \nПравда, любить Бог мене (2р.)\nВін за мене постраждав.\n\nКуплет 2\nПравда, любить Бог мене. Коли в горю я скорблю,\nВін, я вірю, подає руку сильную Свою.\n\nКуплет 3\nПравда, любить Бог мене. І в життєвій боротьбі \nЗлі учинки подолать подає Він сил мені.\n\nКуплет 4\nПравда, любить Бог мене. Учить Він добру без слів. \nВчитись буду в Нього я все життя до вічних днів.', '', '', 'ua', NULL, 0, NULL, NULL),
(942, 423, 'Про любов Христа співаймо', 0, 'Куплет 1\nПро любов Христа співаймо,\nПро усі Його діла.\nВ небі чистому там місце \nПриготовив Він для нас.\n\nПриспів: \nЯк ми зійдемось в небі, —\nО, як радісний для нас день буде. \nВбачим там Ісуса \nІ пісню слави викликнем.\n\nКуплет 2\nДоки ми шляхом земним йдем,\nЧасом нас вкриває тьма.\nЯк земний наш шлях скінчиться,\nСпас візьме нас в небеса.\n\nКуплет 3\nБудьмо вірні всі Ісусу \nІ служім Йому усе,\nА як Він прийде у славі,\nНам заплату принесе.\n\nКуплет 4\nВсі вперед і не вагаймось,\nСкоро вбачимо Христа.\nВін відчинить двері райські\nІ введе нас Сам туди.', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(943, 424, 'Північ пройшла', 0, 'Куплет 1\nПівніч пройшла, навколо темрява,\nТрохи спізнились ми сюди прийти.\nСвітло погасло, олії нема,\nСтукаймо, може впустять нас туди.\n\nПриспів: \nПізно, пізно, зачинені двері!\nЩоб нам не почути голос той: \n«Вже двері зачинені!»\nСпішіть (усі) тепер (ввійти), - \nЩе двері відчинені.\nІди (іди) іди (скоріш), -\nЩе двері відчинені.\nЩоб нам не почути голос той: \n«Вже двері зачинені.»\n\nКуплет 2\nПівніч пройшла, а ми ще стоїмо,\nЖдемо вже довго, відчини Ти нам.\nДобрий Господар, нас не віджени,\nЧути, як гарно всі співають там.', '', '', 'ua', NULL, 0, NULL, NULL),
(944, 425, 'Подивися мій друже на мурашку', 0, 'Куплет 1\nПодивися, мій друже, на мурашку,\nЯк все літо працює вона.\nІ не спить вона літом анітрошки:\nВона знає, що прийде зима.\n\nКуплет 2\nСам Христос тобі руку простягає,\nБо Він хоче, щоб ти працював.\nІ життя тобі дати обіцяє,\nЩоб ти серце Йому віддавав.\n\nКуплет 3\nПодивися, як праці багато,\nЗапустіла вся нива кругом.\nДруже мій, ти долай гріх завзято \nІм’ям Вічного Спаса Христа.\n\nКуплет 4\nПроживай, любий друже, покірно,\nЩоби храм твій сердечний яснів.\nБо прийде мій Спаситель, я вірю,\nПісля горя і темних цих днів.\n\nКуплет 5\nГоді Спаса народи побачать,\nЯк прийде Він судити усіх.\nТоді многії люди заплачуть, \nБo любили неправду і гріх.\n\nКуплет 6\nСпас на вірних ласкаво погляне,\nПрийме в Царство Христос Своє Сам.\nЦарство вічне Христове настане \nВ славі вічного Спаса Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(945, 426, 'Про Божу ласку звіщайте людям', 0, 'Куплет 1\nПро Божу ласку звіщайте людям.\nБог милосердний Сина послав, - \nДать людям визвіл з гріхів-кайданів.\nІ зрозуміть, що за них страждав.\n\nПриспів:\n На хресті Ісус страждав,\nВін святую кров пролляв, \nЖиття вічне Він всім нам придбав,\nНа Голгофі умирав.\n\nКуплет 2\nСпаситель кличе лагідно всіх нас:\n«Прийдіть до Мене, Я прийму вас.»\nА завтра може вже пізно буде,\nСпаситель скаже: «Не знаю вас.»\n\nКуплет 3\nВ Христі Ісусі наше спасіння,\nБо на хресті Він його придбав.\nДав людям визвіл з гріхів-кайданів,\nТо ж Він для цього і умирав.', '', '', 'ua', NULL, 0, NULL, NULL),
(946, 427, 'Прийде Господь із Сіону', 0, 'Куплет 1\nПрийде Господь із Сіону, щоб забрати нарід Свій. \nБачить Бог із Свого трону, що настав вже час тяжкий.\nНарод стогне у неволі і знемігся в боротьбі.\nБог по Своїй святій волі світить світлом у ці дні.\n\nКуплет 2\nБог поможе Своїм дітям увійти в святе життя. \nУважаймо, чи ми встоїм в правді Божій до кінця.\nБо лиш вірним Бог поможе, щоб одержати життя. \nХто сповняє Слово Боже, хай хоронить до кінця.\n\nКуплет 3\nХоч і важко в світі жити, гріх бушує навкруги.\nЯк будем Бога гнівити, то пропадем у цій тьмі.\nКоли Господь покарає тую блудницю тяжку,\nТоді мир нам завітає, поміч дасть Господь Свою.\nТреба нам тут свято жити, щоб Господь нас хоронив, \nСвітлом правди засвітити, щоб світильник наш горів.', '', '', 'ua', NULL, 0, NULL, NULL),
(947, 428, 'Подивися на Ісуса', 0, 'Куплет 1\nПодивися на Ісуса, на ті Його рани.\nЯк ми своїми гріхами Його розпинали.\nВін молився, Він томився, як ішов на муки.\nЯк привели на Голгофу, цвяхи били в руки.\n\nКуплет 2\nНa голову терен клали, били, як хотіли.\nЯк скінчили поругання, оцтом напоїли.\n«Завершилось» - сказав Господь. О, як кров лилася! \nО, як було тоді страшно, як земля тряслася!\n\nКуплет 3\nБраття, сестри дорогії, щось маю сказати:\nТреба нам себе судити, щоб не постраждати.\nІ ми нині ті страждання, браття, споминаймо,\nДо святого того хліба руку простягаймо.\n\nКуплет 4\nБо ми бачимо, як Юда нерозумно поступив.\nВін з неправдою до хліба свою руку простягнув.', '', '', 'ua', NULL, 0, NULL, NULL),
(948, 429, 'Предвічний Небесний Учитель', 0, 'Куплет 1\nПредвічний Небесний Учитель народ научав,\nІ кожний, хто Його йшов слухать, вільний доступ мав.\nНаука з уст Його лилася, оживляла всіх.\nДо Нього матері приносять діточок малих.\n\nКуплет 2\nТа учні стали не пускати їхніх матерів,\nСпаситель же їх научає: «Допустіть дітей, -\nТаких бо є Царство Небесне, - зрозумійте всі, \nТакими маєте у Царстві й самі стати ви».\n\nКуплет 3\nІ матері піднесли діток до Учителя.\nЛюбов’ю засвітліли очі у Спасителя.\nРуками ласкаво Спаситель діток обіймав, - \nПоклавши на голівки руки, їх благословляв.\n\nКуплет 4\nО, Спасе, до Тебе приносим дитятко мале,\nІсусе, благослови й нині немовлятко це!\nНа втіху щоб воно зростало, в святості жило, \nЩоб воно для Тебе, Ісусе, плоди принесло.', '', '', 'ua', NULL, 0, NULL, NULL),
(949, 430, 'В часи предавні', 0, 'Куплет 1\nВ часи предавні | сидів й співав. (Зр.)\nВ руках він арфу свою держав,\nСпівав сердечно і славив.\n\nКуплет 2 \nСпівав про Бога, про сильного,\nНема на світі Йому подібного.\nСпівав про Бога, що є любов,\nІ вічно Він той самий буде.\n\nКуплет 3\nДавидом звався | Божий співець. (Зр.)\nВін ладив арфу, співав-співав \nПро своє щастя й спасіння.\n\nКуплет 4\nНа небесах він співа тепер,\nА я скитаюсь тут на землі.\nРазом ми славим з ним Господа \nЗа те, що Він - наш Спаситель.\n\nКуплет 5\nЗ ним я співаю, | а як же ти? (Зр.)\n«Не маю арфи, - говориш ти, - \nСпівать не можу, як Давид».\n\nКуплет 6\nНе маєш арфи - співай псалом,\nСпівать не можеш - молись за всіх;\nНе можеш цього - доказуй всім,\nЩо Ісус є наш Спаситель.\n\nКуплет 7\nДавид співає | там в небесах. (Зр.)\nА я щасливий тут на землі,\nЩо Ісус є наш Спаситель.\n\nКуплет 8\nКоли ми станем перед Творцем,\nІ там з Давидом ми будем всі,\nТо урочисто співать будем,\nЩо Ісус - наш Спаситель.', '', '', 'ua', NULL, 0, NULL, NULL),
(950, 431, 'Боже добротливий', 0, 'Куплет 1\nБоже добротливий, вчуй мої благання \nНа землі журливій в дні мого страждання.\n\nПриспів: \nВірному бути дай Тобі, мій Боже,\nДушу ворог лютий хай не переможе. (2р.)\n\nКуплет 2\nЙду я долом смерті всюди за Тобою,\nО, не дай померти з ворогом в двобою.\n\nКуплет 3\nВийду переможно, Спасе мій, з Тобою,\nХоч душа тривожна, сповнена журбою.', '', '', 'ua', NULL, 0, NULL, NULL),
(951, 432, 'Боже в серцях наших', 0, 'Куплет 1\nБоже, в серцях наших розпали вогонь,\nХай горить, не гасне в нас Твоя любов.\nВсе, що тільки маєм - власність це Твоя.\nТримай Ти нас міцно у Своїх руках.\n\nПриспів: \nТи наша радість, наше Ти життя!\nВ Тобі Єдинім - світле майбуття.\nНаші молитви чуєш в час тривог, \nІсус-Спаситель, Ти наш Цар і Бог. (2р.)\n\nКуплет 2\nЗбережи нас, Боже, в світі цім від зла,\nМиром наповни наші всі серця;\nВ темноті щоденній зіркою засяй,\nНе залишай же нас, не залишай.\n\nКуплет 3\nНе втрачай надії, зіркою світи,\nЩоб могли в темряві люди шлях знайти.\nЧерез перешкоди з піснею пройти.\nІсус вже близько, зустрічать спіши.', '', '', 'ua', NULL, 0, NULL, NULL),
(952, 433, 'В небі є моя свята Вітчизна', 0, 'Куплет 1\nВ небі є моя свята Вітчизна,\nДе нема страждань, сліз і спокус.\nМісце те для мене приготовив \nМій Спаситель - Сам Ісус.\n\nПриспів: \nСкоро, скоро в небі буду я,\nДе Христос з святими мене жде.\nБог не залишить тут мене, в Небо доведе.\n\nКуплет 2\nДім мій є за хмарами високо,\nДе святі спокійно всі живуть.\nСлавлять Бога за любов велику,\nІ мене вони там ждуть.\n\nКуплет 3\nО, Небесна ти моя Країно,\nВсім своїм єством тебе люблю. \nХоч в дорозі часто знемагаю, \nЗ вірою до Тебе йду.', '', '', 'ua', NULL, 0, NULL, NULL),
(953, 434, 'Веди нас Месія', 0, 'Куплет 1\nВеди нас, Месія, по стежці вузенькій,\nНе дай нам упасти на нашім шляху.\nЗміцни нашу віру до Тебе, Учитель,\nНе дай же нам більше служити гріху.\n\nКуплет 2\nВеди нас, Месія, до Батька Святого, \nНехай ми побачим всю славу Його.\nМи впадем перед Батьком на наші коліна, \nДитячую славу Йому віддамо.\n\nКуплет 3\nА там пред Престолом Творця заспіваєм, \nСплетемо вінець із пісень тих святих, \nВозложим на вівтар завіту святого,\nРозкажем, як гірко жилося нам тут.\n\nКуплет 4\nОй важко, ой важко, хто Бога не знає, \nЖиття безталанне, гірке, як полин. \nЩасливі ті люди, що Бога шанують \nІ люблять Закон тільки Божий один.', '', '', 'ua', NULL, 0, NULL, NULL),
(954, 435, 'В місті Вифлеємі', 0, 'Куплет 1\nВ місті Вифлеємі сталась новина,\nЩо Діва Марія Сина вродила.\n\nПриспів: \nЯк радісна новина!\nСкажіть, де та Дитина?	\nЩоб ми там поспішали, славу дали.\n\nКуплет 2\nА над Вифлеємом зоря сіяла,\nТрьом царям зі сходу шлях показала.\n\nКуплет 3\nЯк з вірою, браття, шукать будете,\nТо у Вифлеємі Дитя знайдете.\n\nКуплет 4\nА Ірод злосливий з того засмутивсь,\nЩо Христос-Спаситель на світ народивсь.\n\nКуплет 5\nНаказав воїнам всюди шукати \nІ дітей маленьких щоб убивати.\n\nКуплет 6\nДітей повбивали, Вифлеєм пройшли,\nСпасителя ж світу ніде не знайшли.', '', '', 'ua', NULL, 0, NULL, NULL),
(955, 436, 'В земній долині', 0, 'Куплет 1\nВ земній долині задоволений я,\nХоч і хатина небагата моя.\nАле в тім місті, де спасенні живуть,\nМене багаті оселі там ждуть.\n\nПриспів:\nЯ маю місце там у славній країні,\nДе не старіють, де вічна весна.\nІ вічно буду з Ісусом я жити,\nКоли ввійду вже у небеса.\n\nКуплет 2\nХоч зустрічаю горе я і недугу,\nАле все ж знаю, що до Неба я йду.\nІ лиш дочасно я з’явився сюди,\nУ Небі буду з Богом завжди.', '', '', 'ua', NULL, 1, '2020-10-18', NULL),
(956, 437, 'Господь я в душі Тобі вдячний', 0, 'Куплет 1\nГосподь, я в душі Тобі вдячний,\nЗа те, що мене просвітив.\nДо смерті Тебе буду славить,\nЗа те, що гріхи Ти простив.\n\nПриспів: \nЧасто ідучи, сил не мав,\nХоч в боротьбі я не встояв,\nДуші моєї всі думки знаєш лиш Ти.\n\nКуплет 2\nОчі, переповнені смутком,\nСерце плаче і сильно болить.\nЛиш Ти розумієш, мій Боже,\nПоможеш це все пережить.\n\nКуплет 3\nМолюся до Тебе, мій Боже,\nДушею, єством всім своїм.\nЗглянься і прости всі провини,\nДозволь же буть сином Твоїм.', '', '', 'ua', NULL, 0, NULL, NULL),
(957, 438, 'Ісусе Тебе люблю', 0, 'Куплет 1\nІсусе, Тебе люблю, тільки Тебе люблю.\nНе можу без Тебе я й дня прожить, тільки Тебе люблю.\n\nКуплет 2\nІсус, Ти є надія, Ісус, Ти є життя.\nІсус, Ти - дорога до неба, о, алілуя!\n\nКуплет 3\nІсус, Ти є мій Пастир, Ісус, Ти є мій друг.\nТобі довіряю своє життя, о, алілуя!\n\nКуплет 4\nІсус, Ти є Спаситель, від мук Ти спас мене.\nТож вічно я буду вже жити там в Небесах Твоїх.', '', '', 'ua', NULL, 0, NULL, NULL),
(958, 439, 'Край Палестина', 0, 'Куплет 1\nКрай Палестина - земля благословенна,\nТам, де народився наш Ісус.\nКрай той всім знаний, завжди величний, славний \nСяйвом з неба покритий був кругом.\n\nПриспів: \nО, незабутня є та історія,\nЯк наш Спаситель кров проливав.\nО, кров та дорогоцінна!\nСина Божого Ісуса Христа! 2р.\n\nКуплет 2\nО, незабутня для нас є та історія,\nЯк жив, учив людей колись Христос.\nВ садах оливних, серед гір тих чарівних \nЛились слова Його до слухачів.\n\nКуплет 3\nМури і стіни того Єрусалиму \nСвідчать про всі діла й чуда Христа.\nЯк наш Спаситель на хресті був прибитий, \nВипив чашу гірку за нас до дна.', '', '', 'ua', NULL, 0, NULL, NULL),
(959, 440, 'Люди грішні', 0, 'Куплет 1\nЛюди грішні, схаменіться, наверніться до Христа.\nНа Голгофу подивіться,- ллється кров Його свята.\n\nПриспів: \nБожий голос ще лунає, кличе всіх Його любов.\nВсі провини обмиває на хресті пролита кров.\n\nКуплет 2\nЧому досі вам блукати у гріховній марноті,\nСили марно витрачати, дні губити золоті?\n\nКуплет 3\nВи вже стомлені до краю, запеклась на ранах кров.\nПодивіться без відчаю на Голгофу знов і знов.\n\nКуплет 4\nВо широкая дорога - то принада для очей.\nТам лиш горе і тривога, жах безвихідних ночей.', '', '', 'ua', NULL, 0, NULL, NULL),
(960, 441, 'Моє щастя заховане в Бозі', 0, 'Куплет 1\nМоє щастя заховане в Бозі,\nНе в земному житті чи ділах,\nБо приходить воно в перемозі,\nА все інше - то тління і прах.\n\nПриспів: \nКраю мій, я радію тобою,\nІ всі мрії мої до тебе.\nТам все радість святого спокою \nІ лиш віра туди приведе.\n\nКуплет 2\nМоє серце завсіди радіє,\nІ немає для нього границь,\nБо з любов’ю Христовою діє \nІ п ’є воду з джерельних криниць.\n\nКуплет 3\nВода чиста там все прибуває,\nЩо з-під каменя завжди дзюрчить.\nВона рани мої обмиває \nІ спокійно дає відпочить.', '', '', 'ua', NULL, 0, NULL, NULL),
(961, 442, 'О як хочеться в небо', 0, 'Куплет 1\nО, як хочеться в небо мені, Боже благий!\nТам моя лиш надія, там для серця спокій.\nТам закінчу мандрівку і далеку я путь,\nАж туди мої мрії, щоб скоріш відпочить.\n\nКуплет 2\nСерце рветься, о Боже, Ти мені поможи.\nСвою руку ласкаву на мене поклади,\nОбнови мою душу, Ти мене обніми.\nКоли я в житті падаю, Ти мене підніми.\n\nКуплет 3\nБо я знаю, що в небі - там Країна моя.\nТам брати мої й сестри, моя люба рідня.\nЛиш туди мої думи, хочу бути там я.\nТам уже спочиває Ісуса рідня.\n\nКуплет 4\nТак порою є важко: перепони одні,\nІ ніхто не порадить, не поможе мені.\nДух Святий утішає тоді серце моє,\nМій Христос підкріпляє, мені силу дає.\n\nКуплет 5\nЯсне небо прекрасне і нетлінна краса,\nУ Тобі все так ясне від сіяння Христа.\nУ Тобі там і спокій, там щасливе життя,\nМоє щастя у небі, в Ісуса Христа.\n\nКуплет 6\nВін зітре мої сльози, Спас мене обніме.\nВін мене заспокоїть, там Він явить Себе.\nВ небі яснім, прекраснім з Ісусом моїм \nВічно буду я жити у Небеснім Краю.', '', '', 'ua', NULL, 0, NULL, NULL),
(962, 443, 'О як важко іти', 0, 'Куплет 1\nО, як важко іти по вузькому шляху кам’янистім.\nЯ бажаю в душі дні прожити свої життям чистим.\n\nПриспів: \nХрест несу я важкий,\nЙду тернистим шляхом І надіюсь я,\nЩо колись прийде день,\nСльози Бог обітре,\nЯк я з Ним зустрінусь.\n\nКуплет 2\nЯ - безсилий, слабий, щоб боротись в житті.\nСил дальше йти не маю. Але вірю, що Бог \nПоміч дасть в боротьбі. Це я твердо знаю.\n\nКуплет 3\nІ Христос знемагав, коли хрест важкий ніс,\nЩоб за нас померти. Він помер - з мертвих встав, \nДав життя для мене, щоб спасти від смерті.', '', '', 'ua', NULL, 0, NULL, NULL),
(963, 444, 'Ой над Вифлеємом', 0, 'Куплет 1\nОй над Вифлеємом, над щасливим краєм,\nТам небесна зірка сяє, срібним світлом грає.\nСрібним світлом грає, та й на стайню вбогу, \nЩо притулком стала нині Предвічному Богу.\n\nКуплет 2\nТам Ісус, Син Божий в темну ніч родився,\nЙ перед ясною зорею в яслах звеселився.\nВ яслах звеселився і став промовляти: \n«Підеш зірко по всім світі ясно запалати».\n\nКуплет 3\nА де зірка гляне, там добро настане,\nБуде щастя, буде доля: ні раба, ні пана.\nНі раба, ні пана, ні важкого лиха.\nРадість люба між братами, мир і згода тиха.\n\nКуплет 4\nОй, ти, ясна зоре, не зайди за море.\nЗлинь на наші рідні ниви, на степи, на гори.\nНа степи, на гори, під селянські стріхи.\nСяй на нас промінням щастя, долі та потіхи.', '', '', 'ua', NULL, 1, '2021-01-03', NULL),
(964, 445, 'О Дух Святий', 0, 'Куплет 1\nО, Дух Святий, Тебе ми благаєм,\nБлагослови і силу пролий.\nПеред Тобою серце схиляєм,\nНас навісти, любов’ю зігрій.\n\nПриспів: \nГосподи Боже наш Всемогутній, \nДухом Святим повій Ти на нас.\nЗнаєш Ти все, Ти всюди присутній, \nБлагослови нас всіх у цей час.\n\nКуплет 2\nО, Дух Святий, Ти все наповняєш,\nЩастя і радість душам даєш.\nШлях у темряві нам прокладаєш \nІ в Дім Отця, у Небо ведеш.\n\nКуплет 3\nО, Дух Святий, Ти світлом небесним \nШлях на Голгофу нам освітив.\nТам, на Голгофі, подвигом хресним \nДвері спасіння грішним відкрив.', '', '', 'ua', NULL, 0, NULL, NULL),
(965, 446, 'Сонце місяць зорі й землю', 0, 'Куплет 1\nСонце, місяць, зорі й землю - Бог усе це сотворив.\nІ життя - дарунок неба також Він нам всім послав.\n\nПриспів: \nБог є любов, (2р.) співаємо разом, \nРазом всі - Бог є любов.\n\nКуплет 2\nЩоб життя було спасенне, з неба Сина Він послав. \nНа горі, горі Голгофі в муках Він за нас вмирав.\n\nКуплет 3\nТому в житті своєму буду вдячний Йому я завжди \nЗа зорі, зорі, зорі ясні й небо, небо голубе.', '', '', 'ua', NULL, 0, NULL, NULL),
(966, 447, 'Треба так багато мати сили', 0, 'Куплет 1\nТреба так багато мати сили,\nЩоб не потонути в морі зла.\nДе б мені узяти віри крила?\nЯ би полетів - прощай Земля!\n\nКуплет 2\nВ Небо полетів би я до Бога,\nЗалишився там би назавжди.\nЗнаю до Спасителя дорогу,\nСерцем лину я нераз туди.\n\nКуплет 3\nЛюбий мій Спасителю, Ісусе,\nДай моїй душі все більше сил \nПобороти всі гріхи, спокуси \nТа піднятись в небо і без крил.\n\nКуплет 4\nДай мені в молитві пробувати,\nСерцем завжди линуть в небеса,\nЩоб там вічне щастя, радість мати,\nДе нетління Боже, де краса.', '', '', 'ua', NULL, 0, NULL, NULL),
(967, 448, 'Тебе Творця світів просторів', 0, 'Куплет 1\nТебе, Творця світів, просторів\nЯ співом прагну величать\nДай сили, ласки і покори\nСлова достойні уживать\n\nПрипев\nТобі хвалу душа складає\nТобі життя я віддаю.\nІ знаю, там в блаженстві раю,\nХвалу в піснях віддам мою.\n\nКуплет 2\nТвоя величність незмірима\nІ розум гасне, я німий.\nЛюбові грієш Ти промінням,\nЯк сонце вранці в день ясний.\n\nКуплет 3\nПремудрий Ти і Всевидючий,\nСуддя і мертвих і живих.\nСвоїх дітей завжди прощаєш,\nЖиття й надія всіх святих.\n\nКуплет 4\nЯ прагну вічно гімн хваління\nСпівать Тобі, о, Спасе мій,\nЗа дар великий, за спасіння,\nЗа подвиг хрестний, смертний Твій.', '', '', 'ua', NULL, 2, '2020-08-16', NULL),
(968, 449, 'Ти мій Бог Святий', 0, 'Куплет 1\nТи - мій Бог Святий, до Тебе дух мій,\nБо в Тобі лиш знайду я спокій.\n\nПриспів: \nНа Твоїх грудях заспокоюсь я,\nВідпочине душа там моя.\n\nКуплет 2\nЛиш в Тобі Однім радість всім святим,\nРадість Божа спасенним усім.\n\nКуплет 3\nРадість ця з небес, що дає Отець.\nНе залишить вже наших сердець.\n\nКуплет 4\nЧас мій надійде, все земне пройде,\nВ вічну радість мене Бог введе.', '', '', 'ua', NULL, 0, NULL, NULL),
(969, 450, 'У молитві схиляюсь', 0, 'Куплет 1\nУ молитві схиляюсь на коліна в тиші \nІ Тебе я чекаю, Бог - Владика душі.\nВвійди в серце, благаю, Сам засяй у ньому,\nЯ Твій голос пізнаю, Твоє слово прийму.\n\nКуплет 2\nВсі щоденні турботи залишили мене,\nСерце тиснуть скорботи, сон нічний не бере. \nДасиш відповідь, знаю, на питання душі,\nТо ж приходь, я благаю, у вечірній тиші.\n\nКуплет 3\nСловом правди щоденно шлях життя освітляй,\nДай надію нужденним, тайни нам відкривай,\nЩоб прийнять життя слово, щоб горіли серця,\nЩоб іти до обнови, до Небес, до Отця.', '', '', 'ua', NULL, 0, NULL, NULL),
(970, 451, 'Хіба рано віддать', 0, 'Куплет 1\nХіба рано віддать тобі серце Христу?\nПолюбив Він ще юним тебе.\nХіба рано сповнять Його волю святу,\nСвітлу вістку спасіння нести?\n\nПриспів: \nНевже рано, невже рано?\nПрийди до Христа тепер (сьогодні, зараз).\nНевже рано, невже рано?\nЩастя в Ньому, о, повір.\n\nКуплет 2\nЧи ти хочеш віддати всю юність свою \nНа служіння Ісусу Христу?\nНевже варто чекати осіннюю пору,\nЦвіт зів’ялий принести Йому?\n\nКуплет 3\nБез Христа нема радості й щастя тобі.\nВін - Друг вірний, надійний для всіх.\nСпрагу, сховану часто у твоїй душі,\nУтамує в живій Він воді.\n\nКуплет 4\nТвоє бідне життя, як холодна зима,\nЯкщо миру немає в душі.\nА з тобою Христос, то й гроза не страшна, \nЯ спокійний, хоч тьма навкруги.', '', '', 'ua', NULL, 0, NULL, NULL),
(971, 452, 'Христос є скеля', 0, 'Куплет 1\nХристос є скеля, вода, з якої ллється,\nВода цілюща, що дає тобі життя.\nХристос є скеля, вода, з якої ллється,\nВода жива, що дасть тобі життя нове.\n\nПриспів: \nЯкщо хтось прагне -\nХай приходить й з неї п’є,\nОсвіжить душу і все єство своє.\nХристос є скеля, вода з якої ллється, \nВода жива, що дасть тобі життя нове.\n\nКуплет 2\nХристос - лілея на ланах квітучих,\nТроянда біла, свіжа із саду Сарон.\nХристос - життя й любов понад любов’ю,\nВін— Той, що нам Своє спасіння подає.', '', '', 'ua', NULL, 1, '2020-12-13', NULL),
(972, 454, 'Чудову пісню Спас мені дав', 0, 'Куплет 1\nЧудову пісню Спас мені дав з небесної висоти, \nТакої я ще ніколи не співав, то мелодія любві.\n\nПриспів: \nВ моїм серці є мелодія, яка чудова є!\nВ моїм серці є мелодія, то мелодія любві. \nВ моїм серці є подяка, в моїм серці є хвала, \nВ моїм серці є мелодія для Спасителя Христа.\n\nКуплет 2\nЛюбов Христа, Який вмер за нас дала мені вічне життя.\nІ в серці вселила мелодію, радію тепер вже я.\n\nКуплет 3\nБуду співати Спасові я, коли там зійдемось усі.\nО, як буде там мені радісно, коли зустріну святих.', '', '', 'ua', NULL, 0, NULL, NULL),
(973, 455, 'Я схиляюся до Тебе', 0, 'Куплет 1\nЯ схиляюся до Тебе, милосердний Батьку мій.\nТи прийми мене до Себе, радість дай душі моїй.\n\nКуплет 2\nЯ блукаю на чужині, без надії, без Христа,\nДармо трачу на чужині молоді свої літа.\n\nКуплет 3\nКину я оцю чужину, встану, в рідний край піду,\nВже не сином, а слугою в ноги Батькові впаду.\n\nКуплет 4\nІ скажу, що я - син блудний, Батьку мій, прости мене,\nІ не згадуй, що я тратив в марноті свої літа.\n\nКуплет 5\nБо я знаю серця муки, які Батько мій несе,\nДень і ніч Він виглядає, коли син Його прийде.', '', '', 'ua', NULL, 0, NULL, NULL),
(974, 456, 'Як добре нам разом бути тут', 0, 'Куплет 1\nЯк добре нам разом бути тут,\nСпівати, молитись Богу-Творцю.\nХотілося б бути так щодня,\nА покищо - до побачення...\n\nКуплет 2\nЦя земна розлука лишає жаль,\nІ в серці людини одна печаль,\nА тут на землі біда щодня,\nА покищо - до побачення.\n\nКуплет 3\nХай буде надія на зустріч з Ним,\nДе спокій всім вірним серцям святим.\nНа небі не буде розлучення,\nА покищо - до побачення.\n\nКуплет 4\nНа небі ми будемо жити з Ним,\nДе спокій всім вірним серцям святим. \nНа небі ми будем співать щодня,\nА покищо - до побачення.', '', '', 'ua', NULL, 0, NULL, NULL),
(975, 457, 'На світанку чи пізньої ночі', 0, 'Куплет 1\nНа світанку чи пізньої ночі,\nДе б тобі не прийшлося бувати \nДо Небес підіймай свої очі, - \nГоворила мені моя мати.\n\nПриспів: \nНе забудь помолитися Богу,\nБо в молитві - надія та сила.\nСтане легшою важка дорога.\nТи з молитвою будеш щасливий.\n\nКуплет 2\nТі слова мені в серце запали,\nНавесні, мов добірні зернята,\nІ рясні їх дощі поливали,\nБо за мене молилася мати.\n\nКуплет 3\nВ ніжнім смутку твоїм голубинім \nОкеан доброти відчуваю.\nТвоє слово, неначе перлина,\nВ синім небі, мов зіронька сяє.\n\nКуплет 4\nСрібло скроні мої покриває,\nВже і сонце на захід схилилось,\nАле слово її пам’ятаю:\n- Сину мій, не забудь помолитись,', '', '', 'ua', NULL, 0, NULL, NULL),
(976, 458, 'Не залишай Ісусе', 0, 'Куплет 1\nНе залишай, Ісусе, не лишай,\nБо без Тебе тут страх душі й одчай,\nЯк через ліс вночі звершати путь.\nО, Спасе мій, завжди зі мною будь.\n\nПриспів: \n3 дитячих літ я помилятись міг,\nТа Ти мене від зла завжди беріг.\nУчитель, скільки в світі зла й біди!\nНе залишай, порадь мене й веди!\n\nКуплет 2 \nБагато стріл смертельних випускав \nПротивник, щоб я на шляху упав.\nНе продержусь і дня я без Тебе, \nНачальник віри, не лиши мене!\n\nКуплет 3\nЗустріти прагну вічную весну \nЗ Тобою, Спасе. А якщо засну, - \nЯк із печери Лазаря збудив - \nМене в життя від смерті проведи.', '', '', 'ua', NULL, 0, NULL, NULL),
(977, 459, 'Голгофа', 0, 'Куплет 1\nГолгофа! (Зр.) В цій тиші я спокій знайшов,  \nІ промінь надії зійшов.\nВспокоюєш ти, і гине мій страх,\nЯк бачу крізь сльози Тебе.\n\nПриспів: \nЦвяхи рук там не пробили, а мій гріх.\nТо не люди розп’яли Тебе, а гріх.\nТо не цвяхи Тебе тримали, а мій гріх.\nХоч давно вже це все сталось - бачу Тебе.\n\nКуплет 1\nЯ бачу Тебе, Христе, там: побите лице й безліч ран.\nЦе сила любові Тебе завела,\nЩоб мене звільнити з кайдан.\n\nКуплет 2\nЯ згадую часто той день, Голгофи кривавую тінь, \nПрийшов я під хрест з гріхами в той час,\nЗвільнив мене Сам любий Спас.', '', '', 'ua', NULL, 0, NULL, NULL),
(978, 460, 'Вперед через всі перешкоди', 0, 'Куплет 1\nВперед, через всі перешкоди \nВ Країну святую ми йдем.\nЗабудем земні всі негоди,\nТам вічний спочинок знайдем.\n\nПриспів: \nВперед, все вперед, все вперед,\nВсе вперед поспішайте, брати!\nВсе вперед, все вперед,\nХай радісно спів той дзвенить.\n\nКуплет 2\nВперед через терни колючі \nПідемо ми шлях прокладать,\nВидніється край вже наш рідний,\nТам буде нас Бог зустрічать.\n\nКуплет 3\nВперед, хоч скрізь море бушує,\nМов лев хоче нас погубить.\nГосподня рука нас пильнує,\nВона нас в біді захистить.\n\nКуплет 4\nВперед просікаймо дорогу,\nЩоб бачили люди цей слід.\nНесімо плоди ми для Бога \nЗі співом нових перемог.', '', '', 'ua', NULL, 0, NULL, NULL),
(979, 461, 'За Мною йди', 0, 'Куплет 1\nЗа Мною йди, коли море бушує.\nЗа Мною йди, коли зло торжествує,\nЗа Мною йди по тернистім шляху.\nО, йди за Мною, іди.\n\nКуплет 1\nЗа Мною йди, коли горе й страждання,\nЗа Мною йди, коли сили немає.\nЗа Мною йди - допоможу тобі.\nО, йди, за Мною іди.\n\nКуплет 2\nЗа Мною йди, коли ворог лякає,\nЗа Мною йди, коли брат забуває,\nЗа Мною йди, не залишу тебе.\nО, йди, за Мною іди.\n\nКуплет 3\nЗа Мною йди, хоч дорога далека,\nЗа Мною йди, хоч порою нелегко,\nЗа Мною йди в Вічний Дім, в Небеса.\nО, йди, за Мною іди.', '', '', 'ua', NULL, 0, NULL, NULL),
(980, 462, 'Кров Свою Син Божий', 0, 'Куплет 1\nКров Свою Син Божий пролив,\nІ життя для всіх Він відкрив.\nВін Своїми ранами нас \nВсіх з гріховних пут увільнив. \nЯк вівця в далі я блудив,\nГріх в моєму серці царив.\nВмий мене з гріхів Ти моїх,\nІ буду біліший над сніг.\n\nПриспів: \nБіліший над сніг (2р.)\nВмий мене з гріхів Ти моїх,\nІ буду біліший над сніг.\n\nКуплет 2\nВін вінок терновий носив,\nНа хресті розп’ятий Він був.\nСмуток і тягар Він зносив,\nВін для всіх спасіння здобув.\nЩоб до джерела я прийшов,\nЩоб Христу я серце віддав.\nВмий мене з гріхів Ти моїх,\nІ буду біліший над сніг.\n\nКуплет 3\nОтче, я від Тебе пішов,\nЗавсіди я серцем блудив.\nЗнаю, що я тим провинив,\nІ нічим гріха я не змив.\nГосподи, до Тебе я йду,\nЗмий мою всю з мене вину.\nВмий мене з гріхів Ти моїх,\nІ буду біліший над сніг.', '', '', 'ua', NULL, 0, NULL, NULL),
(981, 463, 'Любий Спасе', 0, 'Куплет 1\nЛюбий Спасе, Тебе прошу, Тебе молю я щодня.\nХай дійде до Тебе, Спасе, просьба з уст моїх сумна.\n\nКуплет 2\nТа не тільки з уст і серця, але й з цілої душі.\nТебе прошу із безсилля - Ти почуєш голос мій.\n\nКуплет 3\nТебе прошу, вчуй мій голос і Сам мене проведи, \nБо без Тебе я безсильний, щоби до мети дійти.\n\nКуплет 4\nТи Сам бачиш, я стремлюся від літ моїх молодих.\nЯ служить Тобі бажаю серед грізних хвиль страшних.\n\nКуплет 5\nЯк човен мій все прямує, щоб до берега дійти,\nГрізні хвилі заливають, ніде помочі знайти.\n\nКуплет 6\nТож до Тебе я взиваю, одна поміч моя - Ти. \nЯ на Тебе все здаюся, Ти Сам мене проведи.', '', '', 'ua', NULL, 0, NULL, NULL),
(982, 464, 'Сонце на захід схилилось', 0, 'Куплет 1\nСонце на захід схилилось,\nОсь, день світла скоро мине.\nНастане нежданно хвилина,\nІ Син Людський в славі прийде.\n\nПриспів: \nСкоро Господь прийде з неба,\nЩоб грішних усіх засудить.\nДо Нього зберуться всі люди,\nВідділить одних від других.\n\nКуплет 2\nПраведним скаже: «Прийдіте,\nДавно жде вас вічне життя, \nЙoro приготовив Отець вам,\nЗа вас умирав тяжко Я».', '', '', 'ua', NULL, 0, NULL, NULL),
(983, 465, 'О яка то радість буде', 0, 'Куплет 1\nО, яка то радість буде, не можу сказати,\nКоли Господь Своїх вірних буде забирати.\nУсі гори, наче хори, будуть нам співати. \nСадовина-деревина - в долоні плескати.\n\nКуплет 2\nТоді розлука настане, якої не було,\nЯкої ніхто не бачив, і вухо не чуло.\nРідні сестри будуть разом на жорнах молоти. \nОдну схоче Господь взяти, а другу лишити.\n\nКуплет 3\nСтане сестра, заридає і заломить руки:\nРідну сестру Господь забрав, її ж лишив на муки.\nБатько з сином будуть разом на даху робити, \nСина схоче Господь взяти, а батька лишити.\n\nКуплет 4\nСин повірив в Слово Боже і часто молився,\nБатько за своє невірство на горе лишився. \nМати й дочка будуть в полі, розлука настане. \nРідну матір візьме Господь, а дочку залишить.\n\nКуплет 5\nДочка матір не любила, докоряла грізно.\nТоді схоче покаятись, - буде вже запізно.\nТакож невістка і свекруха будуть розлучатись,\nБо свекруху візьме Господь, невістку ж залишить.\n\nКуплет 6\nІ заплаче, заголосить невістка до Бога,\nБо свекрусі докоряла, не любила Бога.\nДвоє будуть в однім ліжку тої ночі спати,\nХристос прийде з ангелами Церкву забирати.\n\nКуплет 7\nІ заплачуть, заридають жінки й чоловіки,\nБо їх Господь вже розлучить на вічнії віки!\nЯк забере Господь вірних, то многі заплачуть,\nБо вже більше своїх рідних повік не побачать.\n\nКуплет 8\nТому, друже, ти подумай, що робити маєш:\nЧи лишитися на горе, чи гріха зречешся?', '', '', 'ua', NULL, 0, NULL, NULL),
(984, 466, 'О християнин як ти живеш', 0, 'Куплет 1\nО, християнин, як ти живеш?\nЯк до Ханаану ти ідеш?\nЧи проводиш свято дні свої,\nЧи приємні Богові вони?\n\nПриспів: \nСкоро Господь прийде,\nАле чи готовими нас знайде? \nТепер дарував Він час,\nЩоб приготувався кожен з нас.\nДавайте будем ми\nЖити справедливо між людьми.\n\nКуплет 2\nА може ти часто заглядав \nУ цей грішний світ і там блукав?\nЗнай, що там панує тільки гріх,\nТам немає радості й потіх.\n\nКуплет 3\nМоже в тебе радості нема,\nІ твоя душа чомусь сумна? \nНавернись до Господа скоріш, \nЩиро та сердечно помолись.\n\nКуплет 4\nБудем пильнувати ми щодня,\nБудем жити свято, без гріха.\nБудемо готові в кожен час \nЗустрічати Господа Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(985, 467, 'Ой тату тату', 0, 'Куплет 1\nОй, тату, тату, як сумно жити,\nКоли відходиш ти від дітей.\nЗоря не сяє, місяць не світить,\nКоли ще прийдеш до дітей?\n\nКуплет 2\nБо горе жити в земній долині. \nСльози втираю із очей.\nОй, тату, тату, коли ще прийдеш, \nРозділиш радість між дітей?\n\nКуплет 3\nРадісна пісня в домі лунала,\nСльози втирав хтось із очей,\nЯк рука твоя, наш любий тату, \nБлагословляла всіх дітей.\n\nКуплет 4\nКуди не глянеш - сумна надія, \nКоли в дитини тата нема.\nСонце хоч світить, але не гріє,\nВсіх укриває доля сумна.\n\nКуплет 5\nНема де взяти любві, поради.\nО, горе, горе все сироті.\nБез тебе, тату, все чужі люди,\nРадість щезає із душі.\n\nКуплет 6\nКоли ще ласка всіх зогрівала,\nО, любий тату, на путі \nУсе схилена голова моя;,\nІ тихо молюся в тиші.\n\nКуплет 7\nО, тату, тату, як сумно жити,\nКоли відходиш ти від дітей.\nЗоря не сяє, сонце не світить,\nКоли ще прийдеш ти до дітей?', '', '', 'ua', NULL, 0, NULL, NULL),
(986, 468, 'О Боже милий дай мені сили', 0, 'Куплет 1\nО, Боже милий, дай мені сили,\nЖиття за ближніх покладать,\nІ в серці тихім до могили \nВсі кривди ворогам прощать.\n\nКуплет 2\nНе дай з гріхами помиритись \nУ важкій життєвій боротьбі,\nІ научи мене молитись,\nМолитись гаряче Тобі.\n\nКуплет 3\nО, Боже, Боже, тут зневажають \nМене і рідні, і чужі.\nА я від серця всім прощаю,\nЯк в Слові Ти сказав мені.\n\nКуплет 4\nХай в груди кидають каміння,\nХоч важко й тужно мені жить,\nТа вірю - вчуєш всі моління,\nІ будеш Ти мене любить.\n\nКуплет 5\nО, Боже мій, дай мені сили,\nСлова Твої не забувать,\nУсім прощати до могили \nИ життя за ближніх покладать.', '', '', 'ua', NULL, 0, NULL, NULL),
(987, 469, 'Ось вдруге приходжу', 0, 'Куплет 1\nОсь, вдруге на землю приходжу,\nЗабрати готових у рай.\nВставайте, рівняйте дорогу,\nСпливає бо милості час!\n\nКуплет 2\nПогляньте, уже догорає \nГріхами знівечений світ.\nВостаннє Господь закликає:\n«Весільне вбрання зодягніть\n\nКуплет 3\nДонині ви вірили плачем,\nДух істини в серці стогнав.\nТа з вірними звершу інакше,\nВ вас все заблищить, як кришталь.\n\nКуплет 4\nЯ - Бог, Я живий, вас охрещу \nПролитим із неба вогнем,\nУ кожному серці воскресну \nЯ духом Святим у той день!\n\nКуплет 5\nБездушну, удавану віру \nЗруйную дощенту, у мить.\nЯ маску зірву з лицеміра \nІ виявлю гріх перед ним.\n\nКуплет 6\nНе буде між вами розділень, \nВідкинете з серця божків. \nСотворю любові єднання \nУ Дусі Святому навік.\n\nКуплет 7\nОхрещу таким вас хрещенням,\nЯк перших віків християн. \nРозплавлю в горнилі страждання, \nЩоб ввести святих в Ханаан».', '', '', 'ua', NULL, 0, NULL, NULL),
(988, 470, 'Господи до Тебе зір', 0, 'Куплет 1\nГосподи, до Тебе зір підношу я, таким, як є, до Тебе йду. \nВтомивсь в житті й душа болить, де спокій я знайду.\n\nКуплет 2\nСльози вночі і вдень я ллю, де спокій я знайду?\nПочуй мене, я жду, де бідний я піду, щоб мир душі знайти?\n\nКуплет 3\nГосподи, до Тебе хочу я прийти, в Тобі я хочу віднайти \nДля серця радість і спокій, прийми мене, я - Твій.\n\nКуплет 4\nБоже! Мої гріхи прости, тягар з душі зніми,\nСпокоєм наділи, самого не лиши, до неба доведи.', '', '', 'ua', NULL, 0, NULL, NULL),
(989, 471, 'Боже Боже ми благаєм', 0, 'Куплет 1\nБоже, Боже, ми благаєм: поможи нам в світі йти.\nЧасто важко нам буває, але поміч наша - Ти. (2р.)\n\nКуплет 2\nПосилай нам Твоє Слово і слабим нам силу дай.\nДари Духа і любові в серце щедро проливай. (2р.)\n\nКуплет 3\nВ цьому світі небагато нам боротись і страждать.\nПоможи прожити свято, щоб Ти міг нас в небо взять. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(990, 472, 'День уже минає', 0, 'Куплет 1\nДень уже минає, наступає ніч,\nПітьма прикриває кожну земну річ.\nВже на Твоїм небі миготять зірки,\nТихим сном заснули пташки і квітки.\n\nКуплет 2\nІ людей стомлених подолав вже сон. \nХай Господній ангел - сторож їх вікон. \nХай з’явиться світлий нашим діточкам, \nСторожем хай буде всім мандрівникам.\n\nКуплет 3\nКожний біль в ту нічку, Боже, усмири,\nІ до злого вчинку нас не допусти\nАнгел надзирає над народом всім,\nМир святий і спокій Ти зішли в наш дім.\n\nКуплет 4\nЗавтра нас уранці, Боже пробуди.\nІ тільки до добрих вчинків нас веди. \nЩоб могли ми завтра спів почати свій. \nСлава Тобі, Боже, в Трійці Пресвятій!', '', '', 'ua', NULL, 0, NULL, NULL),
(991, 473, 'Зважайте люди на Слово', 0, 'Куплет 1\nЗважайте, люди, на Слово Боже,\nБо воно сьогодні звучить,\nВоно замовкнути може скоро \nІ в цей час останній звучить.\n\nПриспів: \nСкажуть люди: «Слово Боже \nНехай ще повернеться нам».\nДармо люди будуть ждати,\nБо Слово не вернеться їм.\n\nКуплет 2\nСлова Амоса так ясні стали,\nЩо він сповіщав наперед:\nЩо люди сильно голодні будуть - \nНе буде то голод про хліб.\n\nКуплет 3 \nХодити будуть від моря до моря \nІ Слова ніде не знайдуть.\nЛюдей за поли хватати будуть \nІ скажуть: «Ось, Слово в тобі!»\n\nКуплет 4\nІ юнаки, і дівчата юні \nЗнеможені будуть в душі.\nЦе все за кару гріховних вчинків,\nЩо славились тут на землі.', '', '', 'ua', NULL, 0, NULL, NULL),
(992, 474, 'З Божої ласки', 0, 'Куплет 1\nЗ Божої ласки, ось, двоє людей \nСтали й бажають, щоб Ти, як дітей,\nБлагословив їх, о Боже, з’єднав,\nВ житті родиннім їм щастя подав.\n\nПриспів: \nО, поклади, Боже, руку на них,\nВ житті триматись доріг дай Твоїх.\nМи, Боже, їх доручаєм Тобі,\nБудь з ними завжди в достатку й в біді.\n\nКуплет 2\nЖиттєву разом пройдуть вони путь.\nБлизько Ти, Боже, до них завжди будь,\nЩоб, подружившись, ще краще жили,\nТобі служили усі свої дні.\n\nКуплет 3\nБоже, доглянь, щоб ці юні серця \nВірні в подружжі були до кінця.\nВ радості, в горі, у праці, в біді \nДумки в них завжди хай будуть одні.', '', '', 'ua', NULL, 0, NULL, NULL),
(993, 475, 'До Небес мій дух злітає', 0, 'Куплет 1\nДо Небес мій дух злітає, до Всевишнього Творця,\nДе любов Божа спливає на утомлені серця.\n\nКуплет 2\nСонце ясне там сіяє, тут - скитання і одчай.\nТам спокій мене чекає - то ж спішу я в рідний край.\n\nКуплет 3\nТам святі всі проживають у чудових небесах.\nВічно Бога прославляють, а я томлюся в сльозах.\n\nКуплет 4\nГоря там ніхто не знає, там - спасенних сторона.\nТам в любові процвітає вічна радості весна.\n\nКуплет 5\nЛиш до дому я бажаю, Там Христос - Спаситель мій. \nМоє щастя добре знаю - у Вітчизні дорогій.\n\nКуплет 6\nСліз ніхто не проливає, там немає вже журби.\nЯсне сонце вічно сяє Євангельської любві.\n\nКуплет 7\nНе забариться година, смерть до мене прилетить.\nЯ піду в мою Вітчизну, там я вічно буду жить.', '', '', 'ua', NULL, 0, NULL, NULL),
(994, 476, 'Дві руки з’єднались', 0, 'Куплет 1\nДві руки з’єднались нині \nПеред Богом назавжди.\nЩоб в важкій земній долині	\nШлях свій радісно пройти.\nДля піддержки в праці спільній,\nДля потіхи в час важкий.\n\nКуплет 2\nРуку милості, Всесильний,\nПоклади тепер на них. (2р.)\n\nКуплет 3\nДвоє уст тепер сказали \nПеред Богом «Так» святе.\nЖити вірно обіцяли \nНа усе життя своє.\nБоже, ми Тебе благаєм,\nПоможи в житті їм Сам.\n\nКуплет 4\nХай Твої уста з’єднають \nЇх серця на все життя. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(995, 477, 'Великі та чудні діла Твої', 0, 'Куплет 1\nВеликі та чудні діла Твої,\nГосподи Боже Вседержителю!\nПраведні і правдиві дороги Твої, - Цар святих!\nХто не побоїться Тебе, Господи,\nІ не прославить імені Твого?\nБо Ти - єдиний Святий,\nВсі народи прийдуть і поклоняться перед Тобою,- \nБо суди Твої об’явились.', '', '', 'ua', NULL, 0, NULL, NULL),
(996, 478, 'Ім’я Ісуса дороге', 0, 'Куплет 1\nІм’я Ісуса дороге люблю повторювати все,\nБо завжди радує мене Святе Ім’я Ісуса.\n\nПриспів: \nО, Ісус, хвала Тобі\nХай несеться від землі.\nНайдорожче в світі цім \nСвяте Ім’я Ісуса.\n\nКуплет 2\nСтрадальцям Ім’я миле це, спокій і мир воно несе,\nЛюбов’ю Бога сповнене Святе Ім’я Ісуса.\n\nКуплет 3\nЯ люблю чути це Ім’я, ним кріпиться душа моя.\nХай славить весь народ і я Святе Ім’я Ісуса!\n\nКуплет 4\nНема слів, щоб сказать вповні, як любе те Ім’я мені.\nЙого хай славлять всі святі Святе Ім’я Ісуса.', '', '', 'ua', NULL, 0, NULL, NULL),
(997, 479, 'Коли в душі твоїй', 0, 'Куплет 1\nКоли в душі твоїй зовсім нема спокою,\nКоли сумне, о брате мій, твоє лице.\nІ всі думки твої охоплені журбою,\nТоді Ісусові ти розкажи про все.\n\nПриспів: \nА Він, як вірний друг,\nПошле душі твоїй і радість, і спокій,\nІ серце стомлене любов’ю обігріє,\nІ стане радісно тоді душі твоїй.\n\nКуплет 2\nНемає іншого нікого в цьому світі,\nЛиш Він один усякий гріх може простить. \nІ душу у Крові Святого Заповіту \nВін може чистою, як білий сніг, зробить.\n\nКуплет 3\nБо Він віддав колись життя Своє за тебе.\nЩоби сьогодні ти життя безсмертне мав.\nІ за любов оту, проявлену до тебе \nЗавжди ім’я Його величне прославляв.', '', '', 'ua', NULL, 0, NULL, NULL),
(998, 480, 'О Боже Отче наш благий', 0, 'Куплет 1\nО, Боже, Отче наш благий, хвала, хвала Тобі.\nЗа кожний дар Твій дорогий, що Ти даєш в любві.\n\nПриспів: \nХвала Тобі, Создателю, за ласку й доброту.\nХвала Тобі, Спасителю, за Кров Твою святу.\n\nКуплет 2\nПрестолуєш Ти в небесах, де вічно світлий день.\nУсі дари в Твоїх руках, Тобою ми живем.\n\nКуплет 3\nТвоя любов мене кріпить, життя мені дає.\nЗа це бажаю я хвалить Святе ім’я Твоє.\n\nКуплет 4\nІз рову темного гріхів Ісус мене підняв.\nДушею й серцем я ожив, святу любов пізнав.\n\nКуплет 5\nЯк пташка з клітки виліта на волю в поле, в гай.\nОтак стремить душа моя в Небесний світлий край.', '', '', 'ua', NULL, 0, NULL, NULL),
(999, 481, 'О Христе прийми мою молитву', 0, 'Куплет 1\nО, Христе, прийми мою молитву\nЩиру та простеньку:\nГлянь на нашу Україну, \nНашу любу неньку.\n\nКуплет 2\nДе в неволі вічно пробувають \nНаші браття рідні.\nДе роками знемагають \nЇхні душі бідні.\n\nКуплет 3\nТи пошли їм радість, щастя й волю \nЇхнього сумління.\nДай їм з неба кращу долю \nІ вічне спасіння.', '', '', 'ua', NULL, 0, NULL, NULL),
(1000, 482, 'Цілою душею я люблю Христа', 0, 'Куплет 1\nЦілою душею я люблю Христа,\nТому відрікаюсь розкошів, добра.\nХристос - мій Спаситель, надія вся моя.\nВід серця люблю я Ісуса Христа.\n\nКуплет 2\nНе я Його перше - мене Він полюбив,\nЗа мене у жертву Свою кров пролив.\nВін - шлях мій до вічного щастя-буття,\nТому я так щиро все люблю Христа.\n\nКуплет 3\nВ найтяжчих хвилинах, в турботах моїх \nДо Спаса звертаюсь в благаннях моїх.\nІду за Тобою, мій Спасе, усе.\nВ добрі і в недолі я люблю Тебе.\n\nКуплет 4\nЯ прагну зустрітись з Ісусом в раю,\nСпівать переможную пісню мою.\nМоє це бажання, моя це мета, - \nНавік щоб зустрітись на лоні Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1001, 483, 'Прощайте браття', 0, 'Куплет 1\nПрощайте, браття, у Христі ріднії.\nМоже, ми з вами вже останній раз.\nІ ви прощайте, сестри дорогії,\nМоже, вам більше не бачити нас.\n\nКуплет 2\nВеселі хвилі ми з вами тут жили,\nСпільно трудились в той останній час,\nРадість і горе разом ми ділили,\nТепер настав розлуки день для нас.\n\nКуплет 3\nПрощайте, друзі наші, прощавайте.\nНе раз в незнанню шкодили ми вам.\nБог нам є світлом - всі це твердо знаєм,\nЩо ви зробили злого, ми прощаєм вам.\n\nКуплет 4\nВсі наші ближні, друзі, прощавайте, \nІдіть слідами Ісуса Христа.\nІ нас в молитвах ви не забувайте, \nПам’ять хай буде навіки свята.\n\nКуплет 5\nПрощай ти, наша дорога країно,\nВи, діти Божі, всі в правді ходіть,\nНе допускайте гріха і руїни,\nА здобувайте для Ісуса світ.\n\nКуплет 6\nПрощальну пісню кінчаєм співати,\nХай з нами буде Христова любов. \nХриста Ісуса будем прославляти,\nА в Його Царстві побачимося знов.', '', '', 'ua', NULL, 0, NULL, NULL),
(1002, 484, 'Прийди ти до Христа', 0, 'Куплет 1\nПрийди ти до Христа, бо Він вмер за тебе,\nЗа гріх провин твоїх Він Сам віддав Себе. \nДобрий Ісус мій вмер, щоб все простити тобі. \nСерце своє відкрий, - Він дасть тобі спокій.\n\nПриспів:\nСумний враз день прийде, як місця більш не буде, \nДвері відкриті ще є, ввійти ти можеш ще.\nЯкщо ж ти не ввійдеш, то пізно вже буде тоді.\nО, друже мій, прийди, спасіння Його прийми.\n\nКуплет 2\nРуки Господь простер, щоб пригорнуть тебе. \nНадійсь на Нього все, а радість Він пошле. \nПровини всі відкрий, а Він тягар забере. \nТакого, як ти є, в ласці й любві прийме.\n\nКуплет 3\nПоглянь на Голгофу, як кров стікала з ран,\nЯк Агнець на хресті в муках важких вмирав.\nГолос почуй Його, що кличе у любві,\nПрийди не відкладай, Христу себе віддай.', '', '', 'ua', NULL, 0, NULL, NULL),
(1003, 485, 'Подивись як гарно', 0, 'Куплет 1\nПодивись, як гарно, Бог усе створив:\nТверду землю круглу й небо голубим. \nЩоб на світі люди славили Творця,\nІм’я те святеє, Ім’я Господа Христа.\n\nКуплет 2\nЩоб пізнали люди, що Він любить їх \nІ Йому служили, залишивши гріх.\nНа горі Голгофі в муках умирав,\nБожий Син розп’ятий життя Своє віддав.\n\nКуплет 3\nО, подумай, друже, йдеш ти до кінця,\nНе провадь даремно ти свого життя.\nРозкажи Ісусу, що тебе гнітить,\nВін тобі поможе, від гріхів звільнить.\n\nКуплет 4\nХай наповнить серце радість без кінця,\nІ полине пісня слави для Творця.\nЗа любов велику, за нове життя \nЙ Вічне Царство в небі, - Господу хвала.', '', '', 'ua', NULL, 0, NULL, NULL),
(1004, 486, 'Пригадай мій друже', 0, 'Куплет 1\nПригадай, мій друже, про Ісуса,\nПро Його любов до нас слабих,\nНемічних, і грішних, і байдужих,\nІ безсильних в боротьбі важкій.\n\nПриспів: \nНе забудь той хрест, що на Голгофі, \nСпаса, що за тебе умирав,\nТой вінок, вінок терновий\nІ ту Кров, що Він за нас пролив.\n\nКуплет 2\nВажко було Спасові страждати,\nВ муках умирати на хресті,\nТа рішив Він гріх там розіп’яти \nІ спасіння дати назавжди.\n\nКуплет 3\nПригорнись ти серцем до Ісуса\nІ відчуєш ти Його тепло, \nЩо тече до нас з гори Голгофи,\nНемов те цілюще джерело.\n\nКуплет 4\nО, поглянь у небо ти покірно,\nТам побачиш ти свого Отця.\nПодивись, як сонце служить вірно,\nТак служи Йому ти до кінця.', '', '', 'ua', NULL, 0, NULL, NULL),
(1005, 487, 'Почуй мене Боже', 0, 'Куплет 1\nПочуй мене, Боже, коли я сумую,\nКоли моє серце втомилось страждать.\nПочуй, бо тягар мій лежить за спиною.\nУста пломеніють, не можуть мовчать.\n\nКуплет 2\nПочуй мене, Боже, бо слабну порою,\nЙдучи проти вітру вночі і в пургу.\nПочуй, бо я часто болію душею,\nВтомився я, Боже, нема сили йти.\n\nКуплет 3\nДай відповідь, я вже знесилений, прошу.\nЗніми біль, дай радість для серця мого.\nМолюся я щиро, сердечно до Тебе,\nО, Боже, почуй Ти молитву мою.', '', '', 'ua', NULL, 0, NULL, NULL),
(1006, 488, 'Проповідник один', 0, 'Куплет 1\nПроповідник один із зібрання ішов \nІ в душі сумував:\nЧлени Церкви байдужі, сам зовсім став безсилий, \nВповні Слова не мав.\nХлопчик, ось, при дорозі,\nЩо себе забавляє, на колінах стоїть.\nПастор руку подав, але хлопчик сказав:\n«На колінах - найкраще».\n\nПриспів: \nНа колінах - найкраще. (2р.)\nЧи в добрі, чи в біді \nТи молись у житті,\nНа колінах - найкраще.\n\nКуплет 2\nОсь, він думати став над словами, що чув,\nНемов хлопчик все знав.\nСкоро день проминає, темна ніч вже вітає,\nА заснути не міг.\nВсе забути бажав, інших дум він шукав,\nТа спокою не мав. \nПеред ним те дитя все стоїть, промовля:\n«На колінах - найкраще».\n\nКуплет 3\nВін прийняв ті слова, як від Бога-Отця \nІ молитись почав.\nНа коліна упав, а Бог Духа зілляв,\nЧленів всіх об’єднав.\nУ байдужих людей ревність знов запалив, \nКаганці засвітив.\nПастор духом ожив, хлопця він похвалив. \nНа колінах - найкраще!', '', '', 'ua', NULL, 3, '2020-08-23', NULL),
(1007, 489, 'Пам’ятати завжди треба', 0, 'Куплет 1\nПам’ятати завжди треба - Бог обітницю дав нам:\nНа шляху з землі до неба поведу тебе я Сам!\n\nПриспів: \nДе Я буду, де Я буду,\nІ слуга Мій буде там.\nЯ ніколи не забуду \nЙ поведу тебе Я Сам.\n\nКуплет 2\nКоли втома чи спокуса серце стримує слабе,\nСлухайсь поклику Ісуса: поведу Я Сам тебе.\n\nКуплет 3\nКоли подорож знеможе, як зустрінеш жах, біду, \nХай піддержить Слово Боже: Сам тебе Я поведу\n\nКуплет 4\nКоли смерть прийде за тілом, і злякається Адам,\nХай би слово це бриніло: поведу тебе Я Сам!', '', '', 'ua', NULL, 0, NULL, NULL),
(1008, 490, 'Боже в цей час', 0, 'Куплет 1\nБоже, в цей час я до Тебе взиваю:\nСили пошли Ти мені.\nСам порятуй мене, - я погибаю \nВ хвилях, в морській глибині.\n\nПриспів: \nБоже, скоріше порятуй мене,\nДай мені приплисти в рідний Край.\n\nКуплет 2\nБоже, поглянь - мене хвилі ховають,\nДалі не можу я плисти. \nДовго боровся я, - і все це даремно,\nПрийди до мене, дай жить!\n\nКуплет 3\nБерег Твій вічний уже недалеко,\nХвилі навколо ревуть.\nСкоро почуй мене, слово скажи лиш, —\nІ море замовкне в ту ж мить.', '', '', 'ua', NULL, 0, NULL, NULL),
(1009, 491, 'Радість у Христі я знайшов', 0, 'Куплет 1\nРадість у Христі я знайшов.\nВін - моє життя і спокій.\nКоли я до Нього прийшов,\nЗ того часу Батько Він мій.\n\nПриспів: \n3 Того часу я Його Син\nІ радію, що Він прийняв\nМене до святих тих країн,\nЩоб Його я там прославляв.\n\nКуплет 2\nЯ приніс до Нього все зло,\nВін спокій дав в серце моє.\nМені в світі добре буде,\nБо Отець спасіння дає.\n\nКуплет 3\nІ тепер радію всі дні,\nЩо мене мій Батько знайшов.\nВін подав прощення мені,\nКоли я до Нього прийшов.', '', '', 'ua', NULL, 0, NULL, NULL),
(1010, 492, 'Сину серце Мені дай', 0, 'Куплет 1\nСину, серце Мені дай, на чужині не блукай.\nСерце втомлене рида, і давно воно стражда.\n\nПриспів: \nСину, серце Мені дай! (2р.)\n\nКуплет 2\nУтомився ти блудить, де ж ти зможеш відпочить? \nТо ж іди, вертайсь скоріш, нащо вік губити свій?\n\nКуплет 3\nБуде радісно тобі, коли встоїш в боротьбі.\nТоді прийдеш до Мене, виглядаю Я тебе.\n\nКуплет 4\nХто був ворогом твоїм, того довго ти кохав.\nЯ ж усе віддав тобі, ти ж любить Мене не став.\n\nКуплет 5\nСину, серце Мені дай - неподільне, все цілком. \nРозлучися жить з гріхом, на чужині не блукай.', '', '', 'ua', NULL, 0, NULL, NULL),
(1011, 493, 'Слово мама найдорожче', 0, 'Куплет 1\nСлово «мама» - найдорожче,\nНим нам треба дорожить.\nЗ її ласкою, любов’ю легко нам на світі жить.\n\nПриспів: \nКоли мама ще жива є,\nТи щасливий на землі,\nБо молитви ллються в небо \nВранці, в південь і вночі.\n\nКуплет 2\nКоли був я ще малятком, мама у тиші нічній,\nНіби ангел яснокрилий, зберігала спокій мій.\n\nКуплет 3\nУ дитинстві безтурботнім я не знав, як важко жить,\nБо трудилась моя мама, щоб кормити й одягать.\n\nКуплет 4\nПам’ятаю, як матуся вчила завжди нас про те,\nЩоб розумно і взірцево ми пройшли життя усе.\n\nКуплет 5\nПам’ятаю, як бувало, я з дороги приїжджав,\nПлечі рідної матусі, як дитина, обнімав.\n\nКуплет 6\nПережив часи розлуки, як схвильована й сумна \nТихо плакала й ридала мама рідна, дорога.\n\nКуплет 7\nІ самотньою зоставшись, пломеніючи в любві,\nДо Отця в сльозах гарячих все молилась у тиші.', '', '', 'ua', NULL, 0, NULL, NULL),
(1012, 494, 'Скільки душ бажає в світі', 0, 'Куплет 1\nСкільки душ бажає в світі спокій радісний знайти.\nТа ніхто їм не розкаже про Христа, куди іти.\n\nПриспів: \nДруже, брате, йди зі мною \nЛюдські душі потішать.\nБожим Словом та любов’ю \nБудем ми їх зогрівать.\n\nКуплет 2\nСвітла! Світла! - Просять люди. Хто ж піде їх просвіщать? \nХто рішуче піде всюди Правду Божу сповіщать?\n\nКуплет 3\nЩастя, волі там шукають бідні, змучені серця.\nДолі кращої не знають, - хто ж покаже їм Творця?', '', '', 'ua', NULL, 0, NULL, NULL),
(1013, 495, 'Сміло браття всі підемо', 0, 'Куплет 1\nСміло, браття, всі підемо\nЗа Євангельську віру ми, з гріхом у боротьбу.\n\nПриспів: \nБог - наша сила, ми з Ним підем,\nБог - наша сила, щастя знайдем.\n\nКуплет 2\nБоротьба наша не з тілом,\nА з піднебесним духом злим, - боротись мусим ми.\n\nКуплет 3\nЗодягніться в зброю Божу,\nЩоб встояти у боротьбі у святому житті.\n\nКуплет 4\nСміло, браття, в перемогу!\nЗнайдемо поміч у Христа у Бога і Отця.', '', '', 'ua', NULL, 0, NULL, NULL),
(1014, 496, 'Сам Твоє дитя веди', 0, 'Куплет 1\nСам Твоє дитя веди,\nБудь нам світлом на путі.\nМій Спаситель і мій Бог,\nБачиш Ти мій кожний крок.\n\nПриспів: \nСам веди, в руці Своїй мене веди,\nНіколи не дай зійти з Твоєї, Господь, путі.\n\nКуплет 2\nГріх як хочеш подолать,\nСам Господь нас захистить.\nНе боюсь я нічого,\nУповаю на Нього.\n\nКуплет 3\nВірю, Ти хорониш нас,\nНе залишиш ні на час,\nВ Край Небесний приведеш,\nУсі сльози Сам утреш.\n\nКуплет 4\nТам не буде вже ридань,\nКрику, горя і страждань,\nСмуток, горе перейде, - \nРадість вічна там буде.\n\nКуплет 5\nТам Єрусалим новий,\nТам наш Бог, Отець Благий,\nТам вулиця золота,\nРадість вічна і свята.\n\nКуплет 6\nПри світлі Його лиця \nСпів Мойсея і Агнця.\nЧудні пісні Мойсея \nСпіватиму Тобі я.\n\nКуплет 7\nТам мільйони є святих.\nВсі на арфах золотих \nГрають пісні без кінця,\nСлавлять Бога і Отця.', '', '', 'ua', NULL, 0, NULL, NULL),
(1015, 497, 'Скоро Спаситель на землю прийде', 0, 'Куплет 1\nСкоро Спаситель на землю прийде,\nСкоро, о, скоро нам радість пошле,\nСкоро ми будемо всі в небесах,\nВічну хвалу дамо за те, що нас спас.\n\nПриспів: \nЖдемо Тебе, (2р.)\nБоже, о, Боже, ждемо Тебе.\n\nКуплет 2\nБоже, Ти бачиш, як важко жить,\nТебе ми просим: сил нам подай,\nРадість в служінні, смілі серця,\nЩоб люд невірний Тебе бачив в нас.\n\nКуплет 3\nО, ця надія - бути з Христом,\nЄ найдорожча у світі цім.\nВірить, любить і молитись Тобі \nТож поможи, Боже, хрест свій нести!', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(1016, 498, 'Співайте для Господа пісню нову', 0, 'Куплет 1\nСпівайте для Господа пісню нову. (Зр.)\nСпівайте Йому, співайте Йому.\n\nКуплет 2\nЗа чуда Його цю пісню співайте. (Зр.) \nСпівайте Йому, співайте Йому.\n\nКуплет 4\nБо навіки є Його милосердя. (Зр.)\nСпівайте Йому, співайте Йому.\n\nКуплет 5\nЗа те, що Він нас хрестив Святим Духом. (Зр.) \nСпівайте Йому, співайте Йому.\n\nКуплет 6\nЗа те, що Він нас так любить безмірно. (Зр.) \nСпівайте Йому, співайте Йому.', '', '', 'ua', NULL, 2, '2021-02-24', NULL),
(1017, 499, 'Такий який я є тепер', 0, 'Куплет 1\nТакий, який я є тепер,\nТвоя кров лилась за мене.\nМене Ти кличеш до Себе.\nО, Спасе мій, до Тебе йду.\n\nКуплет 2\nТакий, який є, більш не жду,\nОчиститись з гріхів хочу.\nОбмий мене з гріхів, прошу.\nО, Спасе мій, до Тебе йду.\n\nКуплет 3\nТакий, як є у скорботах \nГнітять мене вагання й страх.\nСпаси мене, бо вмру в гріхах.\nО, Спасе мій, до Тебе йду.\n\nКуплет 4\nДо Тебе йду, не віджени,\nМою Ти душу ізціли.\nВ Небесний Край мене прийми.\nО, Спасе мій, до Тебе йду.', '', '', 'ua', NULL, 0, NULL, NULL),
(1018, 500, 'Тихая ніч дивная ніч', 0, 'Куплет 1\nТихая ніч, дивная ніч...\nТихий сон все сповив.\nЗ радістю в серці Марія не спить,\nДивне Дитятко у яслах лежить.\nЛюдям Спаситель родивсь! (2р.)\n\nКуплет 2\nТихая ніч, дивная ніч...\nАнгел Божий з’явивсь \nІ пастухам ніжно він проказав:\n«О, не лякайтесь, Бог радість вам дав». \nЛюдям Спаситель родивсь! (2р.)\n\nКуплет 3\nТихая ніч, дивная ніч...\nБожий Син в світ з\'явивсь.\nО, нехай тішаться ваші серця,\nХай із любов’ю прославлять Отця.\nЛюдям Спаситель родивсь! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1019, 501, 'У цім світі птахи мають гнізда', 0, 'Куплет 1\nУ цім світі птахи мають гнізда,\nА лисиці в земних норах є.\nНаш Спаситель не мав де схилити \nНа землі Своєї голови.\n\nКуплет 2\nВін родився не в пишних палацах,\nХоч цілий світ Сам Він сотворив.\nЗнайшов місце в стаєнці, не в хаті,\nІ там Ірод вже за Ним гонивсь.\n\nКуплет 3\nДо Єгипту мусів Він втікати,\nТридцять років в Галилеї жив.\nА три роки Він ставав навчати,\nДля добра нещасних в світі жив.\n\nКуплет 4\nТа тоді напроти злобно стали \nАрхиреї гонити Його.\nПроти Нього люди бунтували,\nНазивали погано Його.\n\nКуплет 5\n«То - єретик» - на Нього казали,\nБо ВІН правда людей научав.\nБіснуватим Його називали,\nБо Він бісів із них виганяв.\n\nКуплет 6\n«Він Є грішний», - на Нього казали,\nБо Він грішних від гріхів спасав.\n«Він - нечистий», - на Нього казали,\nБо прокажених Він очищав.\n\nКуплет 7\n«Він - обманщик», - на Нього казали,\nБо Він їх із мертвих воскрешав.  \nБожевільним Його називали,\nБо Він сліпим очі відкрив.\n\nКуплет 8\n«То -прожора», - на Нього казали,\nБо Він хлібом людей годував. \nП’яницею Його називали,\nЩо живої води їм давав.\n\nКуплет 9\nТа опісля на Нього напали,\nЯк молився в саду у тиші.\nЙого взяли, руки пов’язали,\nДо Пилата на суд повели.\n\nКуплет 10\nНа голову вінок положили,\nЩо з тернини Йому там сплели.\nА на плечі важкий хрест вложили,\nНа Голгофу Його повели.\n\nКуплет 11\nНа Голгофі до хреста прибили,\nТам умер Він серед важких мук.\nЗа всі добра Йому заплатили, \nТо така заплата з грішних рук.\n\nКуплет 12\n«Не є більший слуга пана свого,—\nТак говорить Спаситель до нас. \nЗненавидів Мене той світ гордий, \nЗненавидить також він і вас».\n\nКуплет 13\n«Князь бісовський» - Мене називали,\nНазивати також будуть вас.\nТе, що в світі зі Мною робили,\nТе і з вами робити будуть.\n\nКуплет 14\nТа не бійтесь, бо і волосина \nНе забракне вам із голови,\nБо я з вами аж до кінця світу,\nЯ поможу вам у боротьбі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1020, 502, 'Говори говори до душі', 0, 'Куплет 1\nГовори, говори до душі,\nОбнови Ти мене Духом правди.\nГовори, говори до душі, -\nя бажаю віддатись Тобі.\n\nКуплет 2\nУ вечірній тиші Ти мені говори,\nЯк до Тебе думками я лину. \nОчищай мене, мій Господь, \nОбновляй Ти мене Духом правди.\n\nКуплет 3\nО навчи мене, Боже, покірливим буть,\nДай постійно радіти Тобою.\nОсвяти життя кожну мить,\nОбновляй Ти мене Духом правди.', '', '', 'ua', NULL, 0, NULL, NULL),
(1021, 503, 'Хочу я з Тобою жить', 0, 'Куплет 1\nХочу я з Тобою жить, Спасе, Ти мій дорогий,\nХочу я Тобі служить кожний день і час земний.\nМиру без Тебе нема, щастя без Тебе дріма,\nСвітло лиш в Тобі сія, вічність в нім моя.\n\nКуплет 2\nБув в неволі я, в гріхах, Ти мене з гріха звільнив. \nМертвим був, та Ти мене з мертвих воскресив.\nСерцем де схилюся я, де спічне душа моя?\nЛиш на грудях є Твоїх спокій для Святих.\n\nКуплет 3\nНа Голгофі Ти страждав, кров Свою за нас пролив.\nВ муках Ти важких вмирав, світ цей пожалів.\nХочу, Господи, як Ти, хрест Нести аж до мети. \nТвердо знаю й вірю я: путь в Тобі моя.\n\nКуплет 4\nРозказать, що можна ще про Тебе й любов Твою?\nСльози щастя веселять душу все мою.\nХочу лиш в Тобі я жить, хочу лиш Тобі служить. \nТи - Христос, і вірю я в світле майбуття.', '', '', 'ua', NULL, 2, '2021-03-14', NULL),
(1022, 504, 'Xвалити Господа я буду', 0, 'Куплет 1\nXвалити Господа я буду, поки ще сили Він дає.\nЙому співати тільки буду, поки ще серце в грудях б’є.\n\nКуплет 2\nДоки душа моя в тім світі, то працювати буду я.\nДля Господа на Його ниві, бо щастя в Нім душа знайшла.\n\nКуплет 3\nВід серця вірити я буду, що Сам Господь - моя скала.\nІ я ніколи не забуду, що кров Його мене спасла.\n\nКуплет 4\nХвалити Господа я буду, поки ще сили Він дає.\nЙому співати тільки буду, поки ще серце в грудях б’є.', '', '', 'ua', NULL, 0, NULL, NULL),
(1023, 505, 'Чому ти мій друже', 0, 'Куплет 1\nЧому ти, мій друже, ще й досі байдуже \nЖивеш у гріхах? Про душу не дбаєш, \nА Біблію маєш і віри не ймеш.\n\nКуплет 2\nХіба ти не чуєш, як ласкаво кличе \nЄвангельський голос Христів? Невже не бажаєш, \nЩоб чути у серці приємність Євангельських слів?\n\nКуплет 3\nО, друже, покайся, з гріхом не дружися,\nДо Спаса прийди. Бо добре ти знаєш,\nЩо стати ти маєш на Його суді.\n\nКуплет 4\nСьогодні Бог хоче, щоб кожен охоче \nСкоріше до Нього прийшов. І замість зотління \nТи радість спасіння для себе у Нього знайшов.\n\nКуплет 5\nЧому ти блукаєш, стомився, страждаєш \nВ дорозі земній? Вернися, мій друже,\nНе будь ти байдужий, вернися скоріш!\n\nКуплет 6\nВернися до Спаса, вернися скоріше, \nПоки ще не пізно, прийди. Поки твоє серце \nЩе б’ється у грудях, старайсь життя вічне знайти.\n\nКуплет 7\nПодумай, що скаже Спаситель, мій друже,- \n«Не знаю Я вас».  Сьогодні не пізно, - \nВставай і відважно борись кожний час.\n\nКуплет 8\nБорись з своїм тілом - Спаситель поможе. \nМолися до Спаса Христа. Вчуй, як призиває \nТебе голос Божий. Спіши, друг, ще світить зоря.', '', '', 'ua', NULL, 0, NULL, NULL),
(1024, 506, 'Чи оцінюєш достойно', 0, 'Куплет 1\nЧи оцінюєш достойно благодать Христа з небес?\nЯк і поміч Його нам? Попроси смиренно у молитві \nБога, як Отця. Вчує Він з небес тебе!\n\nПриспів: \nВін наповнить твоє серце до розливу. \nТільки до Нього прийди,\nСвоє серце відчини.\nВін наповнить твоё серце до розливу \nСвятим Духом і вогнем.\n\nКуплет 2\nБлагодать Його безмірна, милість Божа вічная,\nА любов великая. Згідно із Його завітом \nСвятим Духом і вогнем сповнить серце твоє Він.\n\nКуплет 3\nПринеси своє ти тіло й душу нині до Христа,\nІ обмийсь в крові Христа. Посвяти себе ти Богу, \nІ віддайсь Йому вповні, а Він Духа дасть тобі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1025, 507, 'Підніму руки до Царя', 0, 'Куплет 1\nПідніму руки до Царя і Богу сильному співаю, \nЩо все життя своє, мій Бог, Тобі даю.\n\nКуплет 2\nЯ не знаю всіх богів, багатства не бажаю \nІ на Тебе лиш дивлюсь, бо чисте серце маю.\n\nКуплет 3\nО, прийди, Дух Святий, живи в мені.', '', '', 'ua', NULL, 0, NULL, NULL),
(1026, 508, 'Чому безпечно ти живеш', 0, 'Куплет 1\nЧому безпечно ти живеш сьогодні в світі цім?\nПеред Творцем Всевишнім і Святим \nТворіння Боже найдивніш,\nВід земного всього і найдорожче творива Його.\n\nПриспів: \nМій друже, зупинись, пильніше подивись,\nЧи є у колосі твоїм зерно. Уважно роздивись, \nГлибоко зажурись, щоб не буть лиш \nСолом’яним стеблом.\n\nКуплет 2\nБo сонце, місяць, зорі всі, що сяють в небесах,\nВістять величність Божу у віках.\nВони Йому послушні всі і служать лиш Йому.\nЧи коришся ти так в своїм житті?\n\nКуплет 3\nДивися, як Йому природа піддана у всім.\nВсе клониться перед Божим Лицем.\nНавчися в неї і дивись знов у життя своє- \nЧи так послушний Богові і ти?', '', '', 'ua', NULL, 0, NULL, NULL),
(1027, 509, 'Чи чуєш друже', 0, 'Куплет 1\nЧи чуєш, друже, заклик Христа?\nНіжно з любов’ю Він кличе: \"Прийди».\nЛиш у Христі, в Ньому Одному\nЩастя душі своїй можеш знайти.\n\nПриспів: \nЙди до Ісуса, поки Він кличе,\nІ не відкинь ти Спаса свого.\nЗнай, що не вічно будеш ти чути \nЛаску спасіння і заклик Його.\n\nКуплет 2\nЧи чуєш, друже, що за тебе\nСпас на хресті у стражданнях вмирав?\nЩоб у гріхах ти не загинув, \nРадість і спокій, життя вічне мав.\n\nКуплет 3\nЧи бачиш, друже, що Бог зробив — \nЛюбов’ю вічною нас полюбив.\nТвої гріхи Він взяв на Себе,\nЩоб ти не загинув, але вічно жив.', '', '', 'ua', NULL, 0, NULL, NULL),
(1028, 510, 'Чи ти був на Голгофі', 0, 'Куплет 1\nЧи ти був на Голгофі, чи бачив хреста,\nНа якому Син Божий вмирав?\nЦе за наші гріхи Він життям заплатив,\nЩоб життя вічне ти і я мав.\n\nПриспів: \nПоможе, Боже мій, зрозуміти любов! \nЩо за нас показав на хресті!\nЛиш тоді зможу я за Тобою іти!\nСеред бур і страждань на землі!\n\nКуплет 2\nНе забуду ніколи страждання Христа, \nЯк між небом й землею висів.\nДе людину з Творцем назавжди примирив,\nЩоб, хто прийме Христа, вічно жив.\n\nКуплет 3\nБог давно кличе всіх, щоб до Нього прийшли,\nА ти досі ще в світі живеш.\nЧим ти платиш Йому за страждання і смерть,\nЗа пролитою кров що даєш?', '', '', 'ua', NULL, 4, '2021-01-31', NULL),
(1029, 511, 'Що то за предивна', 0, 'Куплет 1\nЩо то за предивна в світі новина?\nЩо Діва Марія Сина родила.\nВона Його породила і в яселках положила \nГосподнє Дитя.\n\nКуплет 2\nЙшло три володарі до Народженого, \nНесли вони дари Сумиренному.\nВийшов Ірод та и питає і до себе закликає:\n - Куди ви йдете?\n\nКуплет 3\nА ми йдемо, йдемо до Народженого,\nНесемо ми дари Сумиренному.  \nА ви йдіте, віднайдіте і до мене знов прийдіте,\nЯ потім піду.\n\nКуплет 4\nАле злобний Ірод про те розмишляв \nІ по всьому краю вояків послав.\nДав наказ дітей вбивати, кров невинну проливати, \nХриста шукати.\n\nКуплет 5\nУ дітей маленьких життя відняли,\nПоміж ними всіма Христа не знайшли.\nСлава Йому, слава буде, Спасителю слава всюди,\nНа землі спокій', '', '', 'ua', NULL, 0, NULL, NULL),
(1030, 512, 'Що ти сіяв Що посіяв', 0, 'Куплет 1\nЩо ти сіяв? Що посіяв? При дорозі що посіяв?\nОсь, летять недобрі птиці, зерна виберуть пшениці: \nЩо ж залишиться тобі? (2р.)\n\nКуплет 2\nЩо ти сіяв? Що посіяв? Між камінням що посіяв? \nМіж камінням грунту мало, що зійшло - і те зів’яло, \nЩо ж залишиться тобі? (2р.)\n\nКуплет 3\nЩо ти сіяв? Що посіяв? Поміж терни що посіяв?\nЗнай марноти та незгоди завжди глушать добрі сходи,\nЩо ж залишиться тобі? (2р.)\n\nКуплет 4\nЩо ти сіяв? Що посіяв? В добрім грунті що посіяв?\nТі посіви не зав’януть у чеканні не обмануть,\nА стократно віддадуть. (2р.)\n\nКуплет 5\nЩо ти сіяв? Що посіяв? В цім житті що ти посіяв?\nВсе, що сіяв, бувши в тілі чи то словом, чи то ділом,\nВсе пожнеш за гробом ти. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1031, 513, 'Що я дам Тобі мій Спасе', 0, 'Куплет 1\nЩо я дам Тобі, мій Спасе, за безмежную любов,\nЗа дароване спасіння, за святу пролиту кров?\n\nПриспів:\nДай мені своє ти серце, щоби жити міг Я в нім.\nВсе життя своє земнеє сином добрим будь Моїм.\n\nКуплет 2\nДав би я Тобі всі скарби, що на цій землі придбав,\nТа того Ти не бажаєш - так в Святім Письмі читав.\n\nКуплет 3\nДе не гляну, подивлюся, - все Твоє, о Спасе мій.\nЧим Тобі я відплачуся за той дар великий Твій?', '', '', 'ua', NULL, 0, NULL, NULL),
(1032, 514, 'Якщо тебе тягар давить', 0, 'Куплет 1\nЯкщо тебе тягар давить,\nНе думай, що це тяжкий гріх.\nБажав би ти кудись піти,\nОднак терпіти треба тут.\n\nПриспів: \nЧекай. Тихим будь, не нарікай,\nЧекай, чекай, чекай, не нарікай.\n\nКуплет 2\nУ тебе терня на путі - \nХристос носив на голові.\nХрест до землі тебе припер- \nЗгадай, Христос на нім помер.\n\nКуплет 3\nКріпись і Богу вірним будь, - \nБог знає, коли хрест зняти.\nНе нарікай і не бунтуйсь,\nЧекай, будь тихим і терпи.\n\nКуплет 4\nЩе хвилька й горя не буде: \nМинеться біль, журба і гнів. \nХристос усіх нас забере \nВ край щастя, миру, вічних втіх.', '', '', 'ua', NULL, 0, NULL, NULL),
(1033, 515, 'Як тихо скрізь', 0, 'Куплет 1\nЯк тихо скрізь. В глибокій сні \nСповився мрійно Вифлеєм.\nА в небі зіроньки ясні\nНад славним тішаться Царем.\n\nПриспів: \nЦе - ніч Христового Різдва,\nТо Бог Святий з Небес зійшов. \nПророчі здійснились слова, \nГосподня звершилась любов.\n\nКуплет 2\nДалеко десь лунає спів,\nВ небесній Божій висоті.\nTо людям кращих світлих днів \nБажають ангели святі.\n\nКуплет 3\nНебесні арфи золоті \nВ цю пору весело бринять.\nІ чути спів на висоті: \nХвалу віддати там спішать.\n\nКуплет 4\nЯк тихо скрізь. В душі моїй \nРіздвяна нічка сяє знов,\nВ яку в Дитині неземній \nЗ’явилась Божая любов.', '', '', 'ua', NULL, 0, NULL, NULL),
(1034, 516, 'Я пісню бажаю співати', 0, 'Куплет 1\nЯ пісню бажаю співати \nТому, Хто за мене вмирав. \nІ серцем Того величати,\nСвятую Хто кров проливав.\n\nПриспів: \nПолинь, моя пісне, від серця, \nЛунай із глибини душі.\nДля слави Воскресного Сонця  \nБезкраї хваління неси.\n\nКуплет 2\nЯ пісню Тому заспіваю,\nХто нині із мертвих воскрес.\nСердечну подяку складаю,	\nХай лине вона до небес.\n\nКуплет 3\nТому я цю пісню співаю, \nХто є поміж, нами всяк час..\nНехай моя пісня лунає, \nМов дзвін, що Спаситель нас спас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1035, 517, 'Як спрагою втомлена ланя', 0, 'Куплет 1\nЯк спрагою втомлена ланя \nШукає води у степах,\nТак прагне душа за Тобою,\nГосподь мій, Ісус, в небесах.\nДе в світі без Тебе спасіння \nДуші своїй зможу знайти?\nУсюди лиш гріх і страждання,\nСпасти мене можеш лиш Ти\n\nПриспів: \nЯк спрагою втомлена ланя \nШукає води у степах,\nТак прагне душа за Тобою, \nГосподь мій, Ісус, в небесах.\n\nКуплет 2\nЗ Тобою забув я ридання,\nЯ серцем радію в тиші.\nЗабув і журбу, і страждання.\nЛиш в Тобі спокій для душі.\nДля мене ті дні повні щастя,\nКоли бачу сестер, братів,\nКоли Божі діти зберуться,\nЗвучить повний радості спів.\n\nКуплет 3\nБлаженні, що Бога шукають, \nЇх пісням немає кінця.\nБлаженні, що, правди бажають \nІ прагнуть славити Отця.\nО друже, чому ти не прийдеш?\nСпаситель Сам кличе: «Прийди!»  \nСпіши, о душа, ти що прагнеш,\nДо джерел живої води.', '', '', 'ua', NULL, 0, NULL, NULL),
(1036, 518, 'Як швидко й непомітно', 0, 'Куплет 1\nЯк швидко й непомітно дні життя людського йдуть. \nЩе не скінчилися одні, а вже другі пливуть.\n\nПриспів: \nРік за роком, день за днем \nДо кінця турбот ми йдем.\nОсь, прийде останній час,\nІ Христос покличе нас.\n\nКуплет 2\nХто Господа весь час любив і жив тут завжди з Ним, \nТой, хто тут праведно ходив ввійде з Ним в Вічний Дім.\n\nКуплет 3\nКоли для мене надійде останній час буття,\nХристос покаже, як буде там вічнеє життя.\n\nКуплет 4\nВсім серцем вірю, вірю я, що поклик цей Христів \nПочує і душа моя, бо я по-Слову жив.\n\nКуплет 5\nКоли відкриється вже рай й настане судний час,\nО, Боже мій, Ти спогадай того, кого Ти спас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1037, 519, 'Я знайшов своє спасіння', 0, 'Куплет 1\nЯ знайшов своє спасіння у Спасителі Христі,\nБо Ісус Христос - мій Пастир, Він спокій дає душі.\n\nКуплет 2\nІ тепер ніхто не зможе засмутити мир в душі, \nБо і труднії хвилини Він полегшить Сам мені.\n\nКуплет 3\nЯк в дорозі знемагаю, під крило іду Його.\nІ лиш спрагу погасити в Слові зможу я Його.\n\nКуплет 4\nВідкупитель мій зі мною, розмовляю часто з Ним,\nАле дивна та розмова не повториться ніким.\n\nКуплет 5\nВін мене не відкидає, вчувши жалобу мою.\nІ в потребах життя мого руку подає Свою.\n\nКуплет 6\nВід нещастя зберігає, Він хоронить на путі. \nІ життя дає мені Він, Він давно простив мені.\n\nКуплет 7\nЯкщо хочете дізнатись, що є щастя для душі,\nТо відкиньте всі сумніви і знайдіть Його в Христі.\n\nКуплет 8\nУ серцях своїх рішайте завжди прямо з Ним іти.\nБо безмежно Він вас любить, допоможе нам в путі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1038, 520, 'О Боже мій хочу щодня', 0, 'Куплет 1\nО, Боже мій, хочу щодня  \nВ житті моїм буть вірним я;\nДля Тебе лиш одного жить,  \nІ повсякчас Тебе любить.\n\nПриспів:\nТут на землі (тут на землі)\nІ в небесах (і в небесах)\nПрославлю я (прославлю я)  \nТебе в піснях (тебе в піснях)\nЗа доброту (за доброту)  \nІ за життя (і за життя),\nЯке в Тобі (яке в Тобі)\nВже маю я (вже маю я).\n\nКуплет 2\nО, Боже мій, допоможи \nБлагу цю вість усім нести,	\nІ розказать всім про Христа, \nЯкий дає усім життя.\n\nКуплет 3\n0, Боже мій. дай Ти мені  \nШляхом Твоїм хутчій іти,\nНещасним всім допоможи \nЩастя в Тобі їм віднайти.\n\nКуплет 4\n0, Боже мій, веди мене  \nДухом Твоїм в краю земнім. \nЗабути всю журбу в житті \nІ радісно співать Тобі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1039, 521, 'Я довго блукав у цьому світі', 0, 'Куплет 1\nЯ довго блукав у цьому світі\nІ сам я не знав, що шукав.\nТа Ісус простягнув мені руку\nІ життя вічне Він мені дав.\n\nПриспів: \nЗвільнив Він мене від неволі,\nВід муки, біди і гріха.\nПослав в моє серце Він радість, \nСпіваю тепер для Христа.\n\nКуплет 2\nМій друже, що ти шукаєш?\nЯка є у тебе мета?\nТо ж знай, що нічого не знайдеш, \nБo щастя є тільки в Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1040, 522, 'Поклоняюсь я Творцю землі', 0, 'Куплет 1\nПоклоняюсь я Творцю землі.\nМогутній Бог, для Тебе пісня ця.\nСвятиться Ім\'я Твоє! Святиться Ім\'я Твоє!\n\nПриспів: \nВін Той, що був і є. Бог-Отець і Син, \nЦар царів і Пан панів!\nТвоє Ім\'я, Твоє Ім\'я, Твоє Ім\'я святе', '', '', 'ua', NULL, 0, NULL, NULL),
(1041, 523, 'Я дякую Тобі Спаситель мій', 0, 'Куплет 1\nЯ дякую Тобі, Спаситель мій,\nЗа те, що спас мене,- тепер я Твій.\nЯка велика є любов Христа!\nЗ гріхів мене спасла, життя дала.\n\nКуплет 2\nЯ дякую Тобі за мир душі,\nЗа те, що близький Ти, як я в журбі.\nТебе прославлю я, Спаситель мій, \nЗа ласку і любов, за спокій Твій.\n\nКуплет 3\nМене за руку Ти шляхом ведеш.\nУ важкі дні страждань сил подаєш.\nВ Небесний Край я йду, о, Боже мій.\nІ буду там, в раю навіки Твій.', '', '', 'ua', NULL, 1, '2020-06-21', NULL),
(1042, 524, 'Як душа моя сумная', 0, 'Куплет 1\nЯк душа моя сумная, зір звертаю в небеса. \nКоли ближнього немає, зір звертаю в небеса.\n\nПриспів: \nВ небеса, в небеса,\nСвій зір звертаю в небеса. Алілуя!\n\nКуплет 2\nКоли Бог благословляє, зір звертаю в небеса.\nКоли славлю, Господа, я зір звертаю в небеса.\n\nКуплет 3\nЩоб цей світ мав радість, спокій, зір звертаю в небеса. \nЩоб всі знали про Христа, я зір  звертаю в небеса.', '', '', 'ua', NULL, 0, NULL, NULL),
(1043, 525, 'Я без Бога прожив', 0, 'Куплет 1\nЯ без Бога прожив \nтільки літ І не знав Його доброї волі. \nВ марноті і неправді ходив\nНа дорозі гріха та недолік.\nТа зустрів оДИН раз християн \nІ почув слово правди святої:\nЯк Христос за гріхи умирав,\nЩоб звільнити всіх нас від неволі.\n\nПриспів:\nНі, не забудь, що Він кличе сьогодні з любовью.\nПоки ласки Господньої час, не легковаж.\nНі, не відкинь, Його голос є ніжний, ласкавий. \nВін за тебе вмирав на хресті, \nЩоб тобі дарувати життя.\n\nКуплет 2\nВін тебе жде щоночі, щодня,\nТак як батько блудного сина.\nПри дорозі стоїть, вигляда,\nЯк не прийнять такого Христа?', '', '', 'ua', NULL, 0, NULL, NULL),
(1044, 526, 'Я врятований від смерті', 0, 'Куплет 1\nЯ врятований від смерті Сином Божим на хресті.  \nПриєднавсь до Його Церкви, даром взяв дари святі.\n\nПриспів: \nВін є Альфа і Омега, \nВін - Початок і Кінець.\nБільш нічого вже не треба:\nВін- утіха для сердець.\n\nКуплет 2\nЯ Христові покорився і своє життя віддав. \nДобровільно охрестився, себе Богу присвятив.\n\nКуплет 3\nБуду завжди умалятись і Спасителю служить. \nДухом Божим керуватись, По Євангелії жить.', '', '', 'ua', NULL, 0, NULL, NULL),
(1045, 527, 'Як до струменя олень', 0, 'Куплет 1\nЯк до струменя олень так душа моя хоче,\nЛиш до Тебе, мій Боже, все летить і летить.\nЛиш до Тебе, Чудовий, і в півдні, і в півночі \nПориваються очі, і Сльоза в них тремтить.\n\nКуплет 2\nТи мешкаєш над морем, Ти пануєш землею. \nТи є Цар і Страдалець, мій Спаситель ІСУС.\nЯ до Тебе бажаю, як бджола до лілеї,\nЯк до струменя олень, так до Тебе і я.\n\nКуплет 3\nДе весілля безмірне, де невір\'я  негідне, \nТам немає утіхи для душі без Христа.\nТільки там лиш знайду я собі щастя безмірне, \nДе панує братерство, де свята чистота.', '', '', 'ua', NULL, 1, '2021-03-03', NULL),
(1046, 528, 'Хвала Тобі о Боже мій', 0, 'Куплет 1\nХвала Тобі, о Боже мій, Великий Цар небес, землі.\nВсе підкоряється Тобі на небесах і на, землі.\n\nКуплет 2\nІ все Тобою створено Володарем і вічним Богом. \nНема імення на землі, щоб називать Великим Богом.\n\nКуплет 3\nІ в світлі дивнім із небес, у сяйві слави вічної.\nТебе все славить буду я, Спаситель мій любимий.\n\nКуплет 4\nІ хай живе любов Твоя в народі вибранім Тобою.\nВ Твоїх ми зійдемось місцях, серця, оновлені Тобою.\n\nКуплет 5\nТобі і слава, мій Господь, Тобі і поклоніння,\nЩо хліб щоденний подаєш і мир Свій посилаєш.\n\nКуплет 6\nЯк дивно Ти все сотворив і серце радість наповняє. \nКоли з Тобою в самоті я, Боже мій, перебуваю.\n\nКуплет 7\nТобі і слава, і хвала, Тобі і поклоніння,\nЗа те, що полюбив мене, бо Ти — моє спасіння.\n\nКуплет 8\nО, алілуя, мій Господь, подяка і хваління.\nТебе прославлю я в піснях, бо Ти - моє спасіння.', '', '', 'ua', NULL, 0, NULL, NULL),
(1047, 529, 'Спокою часто шукав я', 0, 'Куплет 1\nСпокою часто шукав я в марноті земній, \nПричину невдач всіх своїх я не бачив в собі.  \nРозвагами світу хотів я заповнить життя,\nА Він хотів все мене врятувать від Гріха.\n\nПриспів: \nВін на мене чекав. (2р.)\nЯ життя марнував, а Він мене чекав.\n\nКуплет 2\nБільше не буду шукати у світі ярма, \nВ Спасі моїм я знайшов весь зміст мого життя.\nБуду щоденно у волі Його пробувать, \nЖаль тільки того, що Він мене так довго чекав.', '', '', 'ua', NULL, 0, NULL, NULL),
(1048, 530, 'Він є любов', 0, 'Куплет 1\nВін є любов, жде тебе, Він - Твій Бог  \nДруже, прийди від гріха і тривог.  \nВін є любов сердечна й свята, \nСерце своє лиш відкрий для Христа,\n\nКуплет 2\nВін є любов, залиши всякий страх,\nДруже, спіши - жде Христос в небесах.\nВін є любов, з Ним щасливе життя,\nВічний спокій в Ньому знайде душа.\n\nКуплет 3\nВін є любов, дав життя за тебе,\nО, Божий Агнець взяв гріх на Себе.\nВін є любов, за тебе Він терпів,\nІ на Голгофі Свою кров пролив.', '', '', 'ua', NULL, 0, NULL, NULL),
(1049, 531, 'Горе попереджень не да', 0, 'Куплет 1\nГоре попереджень не дає,\nМногих неготових застає:\nТа коли зір віри в небесах,\nНаше горе заступає Спас.\n\nПриспів: \nЛиш відкривши очі на зорі,\nТи прямуй до Того, Хто вгорі. \nДобре нам навчитись пам’ятать,\nЩоб думки й зір в небо направлять.\n\nКуплет 2\nЗнаєм всі ми осінь і весну,\nРоки забирають всю красу.	\nТа велика радість в небі всім,\nТам ніхто не буде вже старим.\n\nКуплет 3\nСкоро, скоро пил земних доріг,  \nЗ втомлених ми отряхнемо ніг.\nВелич Божу будем оглядать,\nВічно в небі з Богом пробувать.', '', '', 'ua', NULL, 0, NULL, NULL),
(1050, 532, 'Нива вже дозріла', 0, 'Куплет 1\nНива вже дозріла і стоїть,\nЗолотії зерна обсипаються. \nТільки вітер жниво колиха,\nТа ніхто до нього не звертається.\n\nКуплет 2\nСонце теплим променем горить, \nПідбадьорить та зміцнить робочого,\nТа ніхто на ниву не спішить,\nВажко так знайти туди охочого.\n\nКуплет 3\nДе ж женці, де трудівники дня?  \nНа роботу довго щось збираються.\nХолодом вже віє на полях,\nНиви непожаті обсипаються.\n\nКуплет 4\nТож скоріше, поспішім, друззя,\nЩоб зібрать плоди святого діла.\nБо вже день приходить до кінця,\nНива довгожданна вже дозріла,', '', '', 'ua', NULL, 0, NULL, NULL),
(1051, 533, 'За горою стоїть місто', 0, 'Куплет 1\nЗа горою стоїть місто, де побачив я \nВ мерехтінні світил пророчих обітницю Отця.\n\nПриспів: \nЄрусалим, Єрусалим,\nЗ пророчих слів відомо нам,\nЩо східна брама буде відкрита,  \nЄрусалим святий.\n\nКуплет 2\nЧудове місто красою вбране, ти і як колись \nЖдеш Царя, Його приходу, Єрусалим святий.', '', '', 'ua', NULL, 0, NULL, NULL),
(1052, 534, 'Листя осіннєє', 0, 'Куплет 1\nЛистя осіннєє крутиться, падає,\nНемов сірим кличем летить вдалині.\nПрирода вся меркне і завмирає,\nІ провіщає, що скоро зима.\n\nКуплет 2\nЖиття, ніби літо, так швидко проходить,\nНемов човен, що на хвилях пливе.\nЗ кожним днем далі його відносить, \nЧовна, в простори життя-океан.\n\nКуплет 3\nТам я зіллюся з всіма святими,\nВ вічних оселях Бога-Отця.\nТам вже не буде днів рахування,\nТам в Бога вічне життя без кінця,\n\nКуплет 4\nЛистя все крутиться, спокійно падає \nСкоро прийде вже сива зима.\nО, не сумуй, душе, бо життя вічне нам \nДане Спасителем Христом назавжди.', '', '', 'ua', NULL, 0, NULL, NULL),
(1053, 535, 'Ти подивись лиш навкруги', 0, 'Куплет 1\nТи подивись лиш навкруги, \nЯк зеленіють і цвітуть сади, \nПісня пташина в небо летить,  \nВодиця джерельна струмками біжить.\n\nПриспів: \nВ серце Спаситель до нас промовля \nЧерез ті гори, ліси і моря,\nТи своє серце для Нього відкрий.\nІ ти відчуєш, що Він - Бог Живий.\n\nКуплет 2\nСкоро Господь з неба прийде,\nВсіх Своїх вірних в життя поведе,\nТи не спіши у неправді іти,\nАдже ти можеш душу спасти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1054, 536, 'Вірую', 0, 'Куплет 1\nВірую в Єдиного Бога Отця Всемогутнього,\nТворця неба і землі, всього видимого і невидимого. \nЄдиного Господа Ісуса Христа Сина Божого, \nЄдинорідного від Отця родженого,\nНесотвореного перше всіх віків,\n\nКуплет 2\nСвітла від світла, Бога істинного від Бога істинного. \nРодженого, несотвореного,\nОдноістотного з Отцем, через Котрого все сталося. \nВін для нас, людей, і для нашого спасіння\nЗ неба зійшов. І тіло прийняв від Духа Святого,\n\nКуплет 3\nВід Діви Марії і стався людиною \nРозп’ятий був за нас при понтійськім Пилаті, \nСтраждав, помер і був похований.\nІ в третій день воскрес, як було написано,\nІ вознісся на небо і сидить праворуч Отця.\n\nКуплет 4\nІзнову прийде у славі судити живих і мертвих,  \nЙого же Царству не буде кінця. \nІ в Духа Святого, Господа оживляючого,\nЩо від Отця походить.\nЩо Йому з Отцем і Сином однаковий\n\nКуплет 5\nПоклін і однакова слава,\nЩо говорив через пророків.\nВ Єдиную Соборную Апостольськую Церкву. \nВизнаю одне хрещення і відпущення гріхів,\nЧекаю воскресіння мертвих і життя будучого віку. Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(1055, 537, 'О Син Божий Примиритель', 0, 'Куплет 1\nО, Син Божий - Примиритель,\nТи - мій Спас і Відкупитель,\nА я - недостойний, Твій найменший воїн,\nХочу Тобі служити.\n\nКуплет 2\nЯ бажаю в бій вступати,\nБожу правду захищати,\nТа не маю сили, мій Ісусе милий, -\nХочу Тебе просити.\n\nКуплет 3\nПідкріпляй мене слабого,\nЗішли мені Духа Святого,\nІ пошли щит віри і любов без міри,\nІ меча гострого.\n\nКуплет 4\nПрапор Твій завжди хороню, \nЗ ним я ворога здолаю.\nВсім ворожим силам мене не зламати,\nБо Твій прапор - зі мною.\n\nКуплет 5\nПоможи, Ісусе милий, \nВірним бути до могили.\nЗа Правду боротись, йти і не лякатись, - \nПодай мені сили!\n\nКуплет 6\nНе за славу цю земную\nВ бій вступати я бажаю,\nА за рани й муки, за пробиті руки, \nІ за Кров святую.', '', '', 'ua', NULL, 0, NULL, NULL),
(1056, 538, 'Небесний Краю мій', 0, 'Куплет 1\nНебесний Краю мій, до тебе лину я! \nУгору, в дім святий летить душа моя.\n\nПриспів: \nО, краю мій, сердечних мрій!\nДо тебе рвуся я, - Вітчизна там моя!\n\nКуплет 2\nЯ прагну бути там, в Отця на висоті,\nДе славний Божий Храм палає у красі.\n\nКуплет 3\nВже скоро відійду з землі в Небесний Край,\nТам щастя лиш знайду - душі безсмертний рай.\n\nКуплет 4\nТам сліз не буде вже, в Небеснім Краю тім,\nА вічна радість все з Христом в Краю Святім.', '', '', 'ua', NULL, 0, NULL, NULL),
(1057, 539, 'Коли в темряві буревій', 0, 'Куплет 1\nКоли в темряві буревій опівночі завиє,\nСльоза страждань спаде із вій та серденько заниє.\n\nПриспів:\nІди скоріш, - Спаситель твій тебе давно чекає. \nУтре Він сльози із очей, введе тебе до раю.,\n\nКуплет 2\nКоли минуть юначі дні, і тяжко їх забути;\nІ в грудях будять жаль вони за тим, Що Не вернути.\n\nКуплет 3\nКоли життя ти змарнував, і мрії повтікали;\nЙ тепер лиш згадок час настав,  й надії позникали.\n\nКуплет 4\nКоли не можеш йти туди, куди лиш глянуть очі,- \nДо твого Господа іди, тебе спасти Він хоче.\n\nКуплет 5\nКоли втомився ти в борбі, і смерть тебе тривожить; \nНіхто з людей твоїй судьбі дать помочі не може.', '', '', 'ua', NULL, 0, NULL, NULL),
(1058, 540, 'Сину чому пішов в даль', 0, 'Куплет 1\nСину, чому пішов в даль? Вернись! -Господь зове. \nПочуй цей голос милий: Вернись! - Спаситель жде.\n\nПриспів: \nДивну ту зустріч згадай ти, мій сину,\nЯк щиро тоді ти моливсь.\nЯк моливсь! (Сину пригадай) \nЯк моливсь! (Як молився ти). Обітниці твої, молитви.\n\nКуплет 2\nДе ж ти, заблудлий сину, душею заблудивсь? \nЗагинеш ти навіки,- додому знов вернись!\n\nКуплет 3\nГосподь ласкаво кличе тебе вже так, давно.\nДай відповідь сьогодні, вернись до Нього знов!\n\nКуплет 4\nНе буде голос Божий повік тебе шукать.\nТи згубиш день спасіння, Господню благодать.', '', '', 'ua', NULL, 0, NULL, NULL),
(1059, 541, 'Не знаю я ні дня ні ночі', 0, 'Куплет 1\nНе знаю я ні дня, ні ночі,\nКоли Спаситель мій прийде,\nКоли Його побачать мої очі,\nКоли той день прийде.\n\nКуплет 2\nВже чути кроки Господеві,\nНавколо страшний буревій.\nПоправ же світло в свому каганцеві,\nМолись та в вірі стій.\n\nКуплет 3\nЧи буде сонце ще світити,\nЧи, може, В темряві нічній, \nКоли почую, - буду голосити:\n«Гряди, о, Спасе мій!»\n\nКуплет 4\nТепер я бачу Ісуса \nОчима віри на землі,\nА там тоді на Нього подивлюся \nУ ангельській хвалі.\n\nКуплет 5\nПрийде Ісус Христос, я знаю, \nЗберіг я Його Заповіт.\nПрийде той Бог, Якого я чекаю\nУже десятки літ.\n\nКуплет 6\nЯ буду прославляти Бога \nТепер і там у небесах.\nЗа те, що Він спасти мене вподобав \nУ молодих літах.\n\nКуплет 7\nЧого ж ти журишся, мій брате?	\nЧого сумуєш в почуттях?\nРадій, радій, бо хоче тобі дати\nГосподь вінець\n\nКуплет 8\nНе знаю я ні дня, ні ночі,\nТа знаю: Скоро Він прийде!\nТоді Його побачать мої очі,\nЙого вся Церква жде.', '', '', 'ua', NULL, 0, NULL, NULL),
(1060, 542, 'О любов про тебе я співаю', 0, 'Куплет 1\nО, любов, про тебе я співаю,\nСповіщаю всім про Божу вість,\nЯк до нас прийшов Спаситель з неба,\nЩастя й спокій грішникам приніс.\n\nПриспів: \nЙого любов - чудовая!\nЙого любов є дивная!\nВін полюбив мене, на хрест віддав себе. \nЙого любов Є вічная!\n\nКуплет 2\nО, любов, об’явлена в Ісусі,\nЗ тих часів, як Він у світі жив.\nВін - безгрішний, наш Христос Спаситель,\nНа хресті спасіння Він приніс.\n\nКуплет 3\nО, любов, - бальзам на рани серця,\nЩит душі від бурі в світі цім.  \nОпануй цілком моїм Ти серцем, \nНаправляй мене в Небесний Дім,', '', '', 'ua', NULL, 0, NULL, NULL),
(1061, 543, 'Довго в темряві блукав я', 0, 'Куплет 1\nДовго в темряві блукав я на путях гріховних! все.\nУ житті розчарувався: світ обманював мене.\nКликав я: - Хто допоможе? І журбу зніме мою?\nІ почув я тихий голос: “Я люблю тебе давно’\n\nПриспів:\nТак давно, так давно, Я люблю тебе давно.\nЯк солодкий тихий голос: “Я люблю тебе давно”.\n\nКуплет 2\nЗалиши свій шлях гріховний, лиш довірся-Він простить, \nВ вірі глянь на хрест голгофський, і тебе Він оживить. \nЯк покаєшся ти щиро, вірою приймеш Його,\nТо почуєш голос милий: “Я люблю тебе давно”.', '', '', 'ua', NULL, 0, NULL, NULL),
(1062, 544, 'Я знаю край', 0, 'Куплет 1\nЯ знаю край, де горя вже не буде,\nДе більш не буде литись братня кров.\nІ в згоді житимуть щасливі люди,\nБо там панує правда і любов.\n\nКуплет 2\nВ мій рідний Край, туди моя дорога.\nЦей Край святий я змалку полюбив.\nІду туди, у Храм живого Бога,\nЩо Він мені у цім житті відкрив.\n\nКуплет 3\nІдіть туди усі скорботні люди,\nБо там уже не ллється братня кров, \nТам горя, сліз ніколи вже не буде,\nБо там панує правда і любов. 2р.', '', '', 'ua', NULL, 0, NULL, NULL),
(1063, 545, 'Вчуй Спасителю ридання', 0, 'Куплет 1\nВчуй, Спасителю, ридання,\nБачиш, журно й гірко жить.\nДай забути нарікання, \nПоможи Тебе любить.\n\nКуплет 2\nБачиш, слабнуть юні крила,\nРозстелився скрізь туман,\nНадірвалась моя сила, \nВіє вітер ураган.\n\nКуплет 3\nДай, щоб стихло гучне море,\nІ щоб вітер перестав,\nЩоб всміхнулись в небі зорі,\nЩоб Тебе я прославляв.\n\nКуплет 4\nВчуй, Спасителю, благання,\nПоможи Тебе любить,\nЗміни в пісню всі ридання,\nДай для Тебе тільки жить.', '', '', 'ua', NULL, 0, NULL, NULL),
(1064, 546, 'Я скарби маю', 0, 'Куплет 1\nЯ скарби маю не з цього віку,\nВони є скриті на небесах,\nТам є Отець мій, рідня без ліку, \nЖиве там кожний, мов вільний птах.\n\nПриспів: \nХай світ сміється і зневажає \nМене, що бідний я є тепер.\nМій скарб на небі мене чекає, \nЯ є багатший, ніж мільярдер.\n\nКуплет 2\nМоя Країно, моя скарбнице,\nДо тебе лину я усі дні.\nПрийду до тебе, коли скінчиться \nМоя мандрівка на чужині.\n\nКуплет 3\nЗ небес Ісуса я виглядаю,  \nВ Нім вся надія моя й мета.\nКоли ж в Ісуса той скарб я маю,\nХто мені скаже, що бідний я?', '', '', 'ua', NULL, 0, NULL, NULL),
(1065, 547, 'Сад Гефсиманський', 0, 'Куплет 1\nСад Гефсиманський темрявою вкрився,\nМов перед бурею він занімів.\nСлухав уважно, як хтось там молився,\nСльози кривавії лив.\n\nКуплет 2\nСад Гефсиманський впізнав свого Друга,  \nЛюди ж впізнать не хотіли Його.\nДико кричали, ревіли навкруги, \nБога розп’яли свого.\n\nКуплет 3\nО, схаменися, невірний народе,\nЧорні заслони з очей своїх скинь,\nВсі залиши свої смертні походи, \nКров проливати покинь\n\nКуплет 4\nЗнай, що настане нежданна година,\nБог над землею відкриє Свій суд,\nПраведних сльози на тебе полинуть,\nСтрашний спіткаєш осуд.', '', '', 'ua', NULL, 0, NULL, NULL),
(1066, 548, 'В домовині немає Христа', 0, 'Куплет 1\nВ домовині немає Христа!\nВ домовині Христос не лежить!\nБула воля Отцева свята - \nДо життя Його знов воскресить.\n\nПриспів: \nНе шукай (не шукай).(2р.) \nНе шукай там,\nДе мертві лежать (не шукай)!\nНе шукай (не шукай) (2р.)\nБог Христові не дав істлівать.\n\nКуплет 2\nВ домовині Христа не шукай!\nНе шукай там, де мертві лежать!\nБог Христові не дав істлівать. \nБог Христові у владу дав рай.\n\nКуплет 3\nВ домовині немає Христа, - \nЙому служать всі сили небес.\nБула воля Отцева свята,	\nЩоб нетлінним Він з мертвих воскрес.', '', '', 'ua', NULL, 0, NULL, NULL),
(1067, 549, 'Недалеко за рікою', 0, 'Куплет 1\nНедалеко, за рікою - берег вічного життя.\nМи ідем туди з хвалою до Спасителя Христа.\n\nПриспів: \nБудем з вірою ми ждати,\nДоки прийде Христос сам. \nБуде Він нас проводжати \nЧерез річку в Ханаан.,\n\nКуплет 2\nЗа рікою сонце сяє, місто там Єрусалим.\nСпіви радісні лунають, співи дивні, неземні.\n\nКуплет 3\nУже многії святії на той берег перейшли. \nЙдуть хвилини дорогії, - кликнуть нас, щоб ми ішли.\n\nКуплет 4\nНіч холодна над рікою, але далі світ сія.\nКрай Христа - то Край спокою. Там з Христом нове життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1068, 550, 'У Кані весілля', 0, 'Куплет 1\nУ Кані - весілля. Христос там гостем був.\nТам перше чудо сотворив і шлюб благословив\n\nПриспів:\nО, Спасе Пресвятий (2р.) Ти  джерело любві.(2р.) \nДо наших молодих зійди (2р.) і їх благослови!\n\nКуплет 2\nІ в доброті Своїй Сам щастя Їм подай.\nНехай вони хвалять Тебе цілим життям своїм.\n\nКуплет 3\nМи просимо Тебе, Небесного Творця,\nЩоб їх серця в одно злились на ціле їх життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1069, 551, 'Це синє небо до себе тягне', 0, 'Куплет 1\nЦе синє небо до себе тягне.\nЗнаю, що ти мій спаситель Христос.\nТуди я лину, щоб відпочити.\nСкорбот нема там, болю ні сліз\n\nПрипев\nО, синє  небо, красою вкрите,\nДо тебе лине душа моя;\nБажав би мат я крила віри,\nТуди піднятись там горя нема.\n\nКуплет 2\nЦе синє небо, створене Богом,\nМісяць і зорі, і наша Земля.\nМене полонить це все прегарне\nПід час півночі і білого дня.\n\nКуплет 3\nО, синє небо, до тебе лину!\nТут я скиталець, чужий я для всіх.\nТвої батьки мене втішають,\nТам відпочину в оселях Твоїх.', '', '', 'ua', NULL, 0, NULL, NULL),
(1070, 552, 'Тільки Ісус хай у серці царює', 0, 'Куплет 1\nТільки Ісус хай у серці царює!\nБільш не знаю любові ніде.\nВ Нім лиш душа моя радість скоштує.\nВ Нім лиш однім душа спокій знайде.\n\nПрипев\nЛюбий Ісус мені дав перемогу.\nМіцні ворожі кайдани розбив.\nСила любові прогнала тривогу.\nДуха Святого у серце вселив.\n\nКуплет 2\nСкинь всі турботи у тяжку хвилину!\nСпас обіцяв вас ввести в Вічний Дім.\nСам Він сказав, що \"Я вас не покину\".\nБуря не страшна, коли ми є з Ним.\n\nКуплет3\nХоч би я впав у земній катастрофі, -\nЗнаю - Ісус підійме мене знов.\nЄ Джерело, що зпливає з Голгофи, -\nСпасова чиста, невинная кров\n\nКуплет 4\nСкінчу я працю, і в рідні оселі\nСпас із любов\'ю покличе мене.\nВсе залишу тут, і в новому тілі\nВ Отчих обіймах мій дух відпочине.', '', '', 'ua', NULL, 0, NULL, NULL),
(1071, 553, 'Дороги шляхи невідомі', 0, 'Куплет 1\nДороги, шляхи невідомі,\nМільйони стежок на землі.\nА стежку до щастя й любові, -\nТо де ж ви її віднайшли?\n\nПрипев\nВ дорогу, в дорогу, нову, невідому,\nВ сімейну ось двоє ідуть.\nГосподь приведе вас до Отчого Дому,\nДе радість і щастя вас ждуть\n\nКуплет 2\nДороги, шляхи невідомі,\nЛюбов і єднання сердець.\nЗійшлися в молитовнім домі,\nІ стали вони під вінець.\n\nКуплет 3\nДві стежки - юнача й дівоча,\nЗійшлися, щоб злитися в одну.\nХай бачать вас Божії очі\nІ руки ведуть до кінця.\n\nКуплет 4\nДороги ведуть до прощаня.\nМи дякуєм батькам за все.\nІ радість, і вірне кохання\nНавіки хай все збереже!', '', '', 'ua', NULL, 0, NULL, NULL),
(1072, 554, 'Ісус в Твоїм Імені сила є', 0, 'Куплет 1\nІсус, в Твоїм Імені сила є,\nІсус - сліпим прозріння Він дає,\nЛиш ім\'я Ісус наповнене величності,\nІсус є Бог вічності\n\nКуплет 2\nІсус - спасіння в Імені Твоїм, \nІсус - хвала єдиному Тобі, \nО, Ісус - Ти справедливість є одна, \nІсус - вічне Ти життя.\n\nКуплет 3\nІсус - мій Цар, що скоро знов прийде, \nІсус, до Тебе серце лине все.\nТобі, Ісусе, ми співаєм повсякчас, \nІсус - Ти Господь усіх нас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1073, 555, 'На чудовій Україні', 0, 'Куплет 1\nНа чудовій Україні квіти розквітають,\nЯк багато українців Бога ще не знають. \nА сьогодні Батьків голос ніжно так лунає:\nНа весілля Христа-Сина всіх Він закликає.\n\nПриспів: \nУкраїно, Україно! 	\nЩастя й мир тобі дарує Бог.\nВін Єдиний тільки сильний \nЗберегти у світі катастроф.\n\nКуплет 2\nНемов ненька немовлятко Він тебе кохає.\nЗ покаянням йди до Нього, - Він тебе прощає.\nІ серденька свого двері відкрий зсередини.\nДасть Христос тобі спасіння і ще й для родини.\n\nКуплет 3\nХристияни в нашім краю, просимо вас нині:\nЖивіть в мирі та любові, як в одній родині.\nЯк служити будем Богу і Його кохати - \nМальовничий край наш буде Бог благословляти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1074, 556, 'Бажаю тепер сказати Тобі', 0, 'Куплет 1\nБажаю тепер сказати Тобі, Спасителю мій,\nЩо люблю Тебе, бажаю Тебе всім серцем своїм.\n\nПриспів:\nБажаю тепер сказати Тобі всю правду вповні,\nЩо люблю Тебе, бажаю Тебе всім серцем своїм.\n\nКуплет 2\nСпіватиму я, бо маю спокій, заплачу і я, бо щастя знайшов, \nЩо люблю Тебе, бажаю Тебе всім серцем своїм.', '', '', 'ua', NULL, 0, NULL, NULL),
(1075, 557, 'Без Него ничего', 0, 'Куплет 1\nНочь повисла над городом южным,\nСкоро вспыхнет восток голубой;\nНичего на земле мне не нужно,\nЕсли только Спаситель со мной.\n\nПриспів: \nБЕЗ НЕГО НИЧЕГО НЕ МОГУ Я,\nБЕЗ НЕГО НЕ ПРОЖИТЬ НЕ ГРЕША.\nТОЛЬКО С НИМ Я ПОЮ АЛЛИЛУЙЯ,\nТОЛЬКО В НЁМ ОТДЫХАЕТ ДУША.\n\nКуплет 2\nОн нашёл меня в мире суровом,\nСнял с души моей тягостный гнёт.\nПод Его всемогущим покровом\nМоё сердце от счастья поёт.\n\nКуплет 3\nНо бывают минуты иные,\nМир, как море, запенится вдруг;\nИ тогда не боюсь я стихии,\nЕсли рядом со мною Иисус.', '', '', 'ua', NULL, 0, NULL, NULL),
(1076, 558, 'Біблія світло Боже засвітила', 0, 'Куплет 1\nБіблія світло Боже засвітила \nІ освітила нам незнаний світ,\nВсього того вона людей навчила,\nЩо було сховане багато літ.\n\nПриспів: \nГосподи, дай нам знати Святе Слово \nІ Його правду сповіщати всім.\nОсь наступає Царство вже Христове,\nІ день заплати буде для усіх!\n\nКуплет 2\nБіблії слово все майбутнє знає,\nЩо час наступний людям принесе;\nЩо відбулося та що бути має,\nБіблія вчить нас розуміти все.\n\nКуплет 3\nБіблія путь правдиву відкриває,\nВсіх направляє на стежки святі;\nХто вказівки священні забуває,\nТой відійде від вірної путі.\n\nКуплет 4\nО, християни, Біблію читайте,\nПеремагайте її словом гріх;\nБожої правди всіх людей навчайте \nІ їх приводьте до Христових ніг.', '', '', 'ua', NULL, 0, NULL, NULL),
(1077, 559, 'Біля Ісуса радість', 0, 'Куплет 1\nБіля Ісуса радість, біля Нього спокій.\nЯка в душі солодкість, що Він - Спаситель мій! \nБо коли Він зі мною, - далеко ворог мій.\nЙти стежкою земною не тяжко - легко з Ним.\n\nПриспів: \nБіля Ісуса радість, біля Нього спокій. \nЯка в душі солодкість, \nЩо Він - Спаситель мій!\n\nКуплет 2\nДавно я йду тим шляхом, що Спас мій проложив, \nТа часто перед страхом хрест тяжко так давить. \nТоді в мольбі благаю я Спаса у тиші\nІ з вірою чекаю, - поможе Він мені.\n\nКуплет 3\nЩасливі ті хвилини - приходить мій Христос \nЙ бере в тяжкі години тягар той, що я ніс.\nТоді Йому хваління від серця я несу.\nГосподь, в земних блуканнях зі мною будь, прошу.', '', '', 'ua', NULL, 5, '2021-01-22', NULL),
(1078, 560, 'Боже мій Ти серця тайни', 0, 'Куплет 1\nБоже мій, Ти всі тайни серця мого знаєш,\nІ всі болі серця знаєш Ти:\nЯк стріла гріха наносить рани | знаєш Ти (Зр.)\n\nКуплет 2\nЗнаєш Ти, що я часто так вже знемагаю,\nТа я хочу все Тебе любить.\nХочу йти покірно за Тобою ¡ свято жить (Зр.)\n\nКуплет 3\nЗнаю, що Ти омив мене Своєю кров’ю,\nІ мене з безодні вирвав Ти,\nТа коли в знемозі упаду я, | Ти прости (Зр.)\n\nКуплет 4\nНа хресті Ти Себе віддав за нас у жертву \nІ Заступником зробивсь моїм.\nТи, вмираючи, благав з любов’ю | прости їм (Зр.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1079, 561, 'Боже Ти над світом', 0, 'Куплет 1\nБоже, Ти над світом ласки розливаєш, як дощі,\nХай же хоч одна краплина \nЗ цього припаде мені (і мені). (2р.)\n\nКуплет 2\nНе покинь мене, мій Боже, ласк Своїх не відбери,\nЯк Свою дитину, Отче,\nТи до Себе пригорни (пригорни). (2р.)\n\nКуплет 3\nНе покинь мене, мій Боже, а любити вчи мене \nЯк чинити все, що гоже,\nЯк наставити себе (вчи мене). (2р.)\n\nКуплет 4\nДовго я в гріхах валявся, довго я смутив себе \nАж тепер опам’ятався\n0 прости, прости мене! (І мене). (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1080, 562, 'Брате мій милий', 0, 'Куплет 1\nБрате мій милий, чого ти сумуєш?\nВ Тебе на серці велика печаль,\nЯснії очі хмурні, мов та осінь,\nСерце камінне тверде, мов та сталь.\n\nКуплет 2\nГоря зазнав ти на світі багато.\nЗмучив себе ти в тяжкій боротьбі,\nСерце не було любов’ю зігріте,\nЧасто траплялось нещастя тобі.\n\nКуплет 3\nЩастя хоч було, та скоро минуло,\nГак як та квітка, що в полі росте,\nВітер повіяв, краса облетіла \nДе ж і поділось все гарне, святе?\n\nКуплет 4\nСкоро у двері загляне смерть люта,\nВ землю сирую тебе покладуть,\nВік твій скінчиться, загине вся слава,\nТвого багатства тобі не дадуть.\n\nКуплет 5\nБрате мій милий, навчися робити\nВ світі все більше і більше добра,\nВіруй у Бога, люби свого брата, —\nВ тебе на серці засяє зоря.\n\nКуплет 6\nТо зірка ясна, то Божая ласка,\nСерце камінне твоє осія.\nЩастя велике, хто Богові служить, - \nЦарство небесне тому подадуть.', '', '', 'ua', NULL, 0, NULL, NULL),
(1081, 563, 'Бушує життєвеє море', 0, 'Куплет 1\nБушує життєвеє море,\nГріховні потуги киплять,\nНавколо темрява і горе \nГрозою над нами висять.\n\nПриспів: \nХристовий маяк у темряві \nНам сяє, як заклик нічний.\nТуди ми свій човен направим,\nНам видно там берег святий.\n\nКуплет 2\nБушує життєвеє море,\nСтогнанням томиться дух мій.\nА люди снуються, у горю,\nНе знаєш де ворог, де друг.\n\nКуплет 3\nБушує життєвеє море,\nЗагибеллю в пітьмі грозить.\nЗнемоги ми вірою борем,\nМолитва нам духа кріпить;\n\nКуплет 4\nБушує життєвеє море,\nТа вірим, поможе нам Бог.\nВ грозі ми пливем крізь простори \nТуди, де немає тривог.', '', '', 'ua', NULL, 0, NULL, NULL),
(1082, 564, 'Весь в ранах', 0, 'Куплет 1\nВесь в ранах при шляху я довго так лежав,\nТомився, біль терпів і плакав, і страждав.\nІ думав я в собі, в тузі невисловимій:\nО, де ж моя рідня, де близький, де любимий?\n\nКуплет 2\nБагато мимо йшло, але не кожен з них \nБажав мене спасти з болючих ран моїх.\nХтось наче вже й бажав- його ж таємна сила \nМарою марноти від мене в даль манила.\n\nКуплет 3\nА іншого лякав вид ран і стогін мій;\nМене вже огортав смертельний буревій.\nУже вуста мої помітно завмирали,\nВ байдужливих очах вже сльози застигали.\n\nКуплет 4\nЗнайшовся лиш один, котрий не зміг пройти, - \nВін сльози втер мені рукою доброти.\nХоч він мене не знав, та, сповнений любові, \nСвоїх старань доклав до ран моїх і крові.\n\nКуплет 5\nОбмив, перев’язав, вживаючи бальзам,\nПривіз мене у дім, і турбувався сам.\nІ голос я в душі почув неповторимий:\n\"Ось хто рідня тобі, хто близький, хто любимий.\"', '', '', 'ua', NULL, 0, NULL, NULL),
(1083, 565, 'Вже не раз', 0, 'Куплет 1\nВже не раз в молитві щирій я Тебе, Господь, благав - \nТа чому ж, мій Боже милий, відповіді ти не дав?\n\nКуплет 2\nТа чому ж на всі благання Ти мені не відповів? - \nЧи даремно всі моління, що просив я Стільки днів?\n\nКуплет 3\nЧи в мені так віри мало, чи то гріх я затаїв,\nЧи любові вже не стало, чи я брату не простив?\n\nКуплет 4\nО, скажи, мій милий Боже, щоб я ясно зрозумів,\nЩо є в серці що не гоже, - й по Твоїй я волі жив.\n\nКуплет 5\nЗ серця змий гріха провину і душі дай віри зріст,\nІ з нового вже почину будь зі мною, Спасе мій.', '', '', 'ua', NULL, 0, NULL, NULL),
(1084, 566, 'Всі ми браття', 0, 'Куплет 1\nВсі ми, браття, Христові вояки;\nЗа Христа ми до бою йдемо.  \nВід людей нам не треба подяки, — \nНам за працю віддячить Христос.\n\nКуплет 2\nВін дарує нам міцную зброю. \nТая зброя і Тори здвига.\nВін нас Сам поведе за Собою \nІ засвітить, як рання зоря.\n\nКуплет 3\nЗоря та ясна, як сонце, засяє,\nРозігріє і душу і кров.\nТа зоря на весь світ засіяє.\nЗоря та - То Христова любов.\n\nКуплет 4\nВсі ми браття, Христові вояки; \nЗа Христа ми до бою йдемо. \nНе страшні нам загрози ніякі, \nЗа Христа ми життя віддамо', '', '', 'ua', NULL, 0, NULL, NULL),
(1085, 567, 'Вчуй мене мій милий Боже', 0, 'Куплет 1\nВчуй мене, мій милий Боже і на сон благослови. \nТа й у сні будь коло мене, аж до ранку стережи.\n\nКуплет 2\nЦілий день мене беріг Ти, одягав і годував. \nЩиро дякую Тобі я за ті дари, що Ти дав.\n\nКуплет 3\nВибач злі мої учинки і на сон благослови \nЗавтра вранці знов до праці, Спаситель, мене збуди.', '', '', 'ua', NULL, 0, NULL, NULL),
(1086, 568, 'Глибше глибше в любові', 0, 'Куплет 1\nГлибше, глибше, в любові Ісуса,\nХочу йти щодня.\nВ мудру школу хочу йти, щоб більше \nЗнати про Христа.\n\nПриспів:\nО, глибше я молюсь, щодня я більш учусь \nІ більш мудрію в Нім, в Його Слові дорогім.\n\nКуплет 2\nГлибше, глибше вчи мене, мій Боже,\nГлибше з кожним днем:\nДоки вміститься життя в Ісусі,\nЩоб я був, як Він.\n\nКуплет 3\nГлибше, глибше, через тяжкі проби \nПоможи іти,\nВкоренитись у любві щоб міг я.\nЖити в вірності.\n\nКуплет 4\nГлибше, вище, кожний день в Ісусі,\nДоки гріх пройде,\nЩоб від злого я міг уникати, \nВірним бути все.', '', '', 'ua', NULL, 0, NULL, NULL),
(1087, 569, 'Грішнику покайся', 0, 'Куплет 1\nГрішнику, покайся, доки ще є час,\nІ спасіння ласка не лишила нас,\nДоки Боже Слово світлом нашим є,\nСпасові скоріше серце дай своє.\n\nКуплет 2\nСерце дай своє, (2р.)\nСпасові скоріше (2р.)\nСерце дай своє.\n\nКуплет 3\nДруже, не вагайся, світ цей залишай \nНа дорогу правди швидше поспішай.\nДень життя минає, скоро ніч прийде,\nІ для всього людства вічність надійде.\n\nКуплет 4\nВічність надійде. (2р.)\nІ для всього людства (2р.)\nВічність надійде.\n\nКуплет 5\nБог тобі бажає щастя та добра,\nЩоб ти стався сином вічного Царя.\nТож сьогодні, друже, до Христа іди, - \nВін твій гріх обмиє, дасть життя тобі.\n\nКуплет 6\nДасть життя тобі. (2р.)\nВін твій гріх обмиє, (2р.)\nДасть життя тобі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1088, 570, 'Двері ось перед тобою', 0, 'Куплет 1\nДвері ось перед тобою, а за ними два шляхи.\nДруже, з щирою душею вибирай один із них\n\nКуплет 2\nЧерез ті широкі двері шлях широкий бачиш ти, \nА на нім юрба народу, що шукає марноти.\n\nКуплет 3\nНа широкій тій дорозі вічна ніч чекає всіх, \nЩо живуть тепер без Бога і не чують Його слів.\n\nКуплет 4\nНа кінці шляху тісного нас чекає вічний рай. \nІ щасливі будуть люди, що прибудуть у той Край.', '', '', 'ua', NULL, 0, NULL, NULL),
(1089, 571, 'Де Ти чудовая', 0, 'Куплет 1\nДе Ти чудовая, в славі сіяюча, \nВічна, Божественна Вітчизну душі?\nЛину думками я до тебе, рідная,  \nВ тузі духовній піднімаю свій взір.\n\nПриспів: \nТак в час весняний, в синьому небі\nВ край свій вертають ключем журавль. \nВ покликах їхніх радости годос,  \nБо до Вітчизни повернулись вони.\n\nКуплет 2\nТам, в висоті небес, в краю безхмарному \nЖде мене в вічності Пастир Христос.\nКоли ж прибуду я в дивну Країну ту?-\nВсе я питаю себе в серці своїм,\n\nКуплет 3\nЗнаю, Спасителю, скоро прийдеш узять\nВ Царство Небесне Ти і мене.  \nО, дай устояти, Спасе, у вірності \nЩоб незаплямленим в вічність, ввійти.\n\nПриспів: \nО, Краю вічний мій; Чистеє небо,\nБожа Країно, Вітчизна моя!  \nСерце прийми моє серце ще юнеє\nХочу, щоб в ньому володів лиш Христос.', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(1090, 572, 'Дуже часто мені', 0, 'Куплет 1\nДуже часто мені в житті тяжко буває.  \nХто спитає тоді про біль серця мого?\n\nПриспів: \nТільки Ти, Ісус, тільки Ти, Утішитель,\nТільки Ти зрозумій, Боже, серце моє!\n\nКуплет 2\nЯ ж бо знаю, що гріх, і не спить, не дрімає,\nГнітить душу мені серед світу цього!\n\nКуплет 3\nСкільки раз на землі тут приходиться плакать.\nЯ прошу: “Поможи в цій печалі моїй!\"\n\nКуплет 4\nІ я певний в тому, що молитви Ти чуєш \nІ поможеш мені в цьому світі гріха.\n\nКуплет 5\nМоже ще не тепер принесеш нагороду,  \nТа я вірю, що ждеш Ти мене в небесах.', '', '', 'ua', NULL, 0, NULL, NULL),
(1091, 573, 'Застановись ти над своїм життям', 0, 'Куплет 1\nЗастановись ти над своїм життям!\nХай серце плаче, стомившись в грісі.\nЧому так довго легковажиш \nТи своїм життям?\nПрийди до Господа в тиші.\n\nПриспів: \nКоли на серці тяжко є і сил не маєш ти-  \nБог близько є: так близько Він. (2р)\n\nКуплет 2\nЗастановись ти в світі суєти,\nВ сльозах молись, щоб чув Бог плач душі. \nСхились в тиші, хай серце плаче \nВід страждань душі.\nТоді Господь дасть спокій Свій.\n\nКуплет 3\nЧому Ти досі в світі ще живеш?\nЧому в гріхах до Бога не прийдеш?\nТвоє життя вже похилйлось,\nБлижче до кінця.\nНе знаєш ти, куди ти йдеш.', '', '', 'ua', NULL, 0, NULL, NULL),
(1092, 574, 'Ми дякуєм Боже за жнива', 0, 'Куплет 1\nМи дякуєм, Боже, Тобі за ці жнива,\nЩо рясно вродили на-наших полях. \nЗа сонце, за вітер, за дощ літній з неба,\nЗа спокій, що маєм у наших серцях.\n\nКуплет 2\nТи все необхідне для нас посилаєш,\nЗдоров\'я і працю для нас подаєш. \nЗа руку тримаєш, як батько дитину,\nВ Своє Вічне Царство до неба ведеш.\n\nКуплет 3\nНе в силі ми, Боже, Тобі відплатити \nЗа всі добродійства, що Ти нам зробив; \nЗа вічне спасіння від пекла, страждання,\nЯке в Своїм Сині для нас дарував.\n\nКуплет 4\nО, Господи Боже, як легко ми важим \nУсі добродійства, що Ти нам зробив!\nПрости Ти нам, Боже, пошли для нас сили, \nЩоб більше ніхто з нас Тебе не гнівив.', '', '', 'ua', NULL, 0, NULL, NULL),
(1093, 575, 'Наше життя відлітає', 0, 'Куплет 1\nНаше життя відлітає,\nМов птах, що скоро летить.\nВ нашім житті лиш слід залишає,  \nІ знову від нас десь летить.\n\nПриспів:  \nРоки, мов ключ журавлів, десь летять \nЗнаю, ніколи назад не прилетять. (2р.)\n\nКуплет 2\nНаше життя йде так скоро,\nСльози несе нам нераз.\nЗнаєм: назад вернуть ми незможем\nУтрачений нами наш час.\n\nКуплет 3\nЧасто ми час затрачаєм,\nВтіхи з того не знаєм, \nНаше життя земне пригасає,\nМи скоро додому підем.\n\nКуплет 4\nБоже, Тебе ми благаєм,\nЩоб нас почув і простив.\nСкільки в житті даруєш нам жити, -\nЩоб кожен для Тебе лиш жив.', '', '', 'ua', NULL, 0, NULL, NULL),
(1094, 576, 'Колись як я молився', 0, 'Куплет 1\nКолись, як я молився, то Мені Господь послав,—  \nЩедро в серце моє Свого Духа Святого зілляв.\nІ з цієї же хвилини відійшли мої сумніви  \nІ тепер я є щасливий, радісний назавжди вже.\n\nПриспів:\nО любов, любов, любов з’явилась для людей. \nСпасти мене прийшов Ісус Спаситель мій.\nУ любві Себе віддав, за нас Він постраждав.\nІ через ту любов тоді хрестив Духом мене.\n\nКуплет 2\nНіколи не лишаймо глибини любові знайти, \nЩоб гріх світа покинуть і за Господом все йти. \nУповаймо і молімся та пильнуймо ми завжди,\nІ тоді усі побачим, як Духа Святого зіллє.', '', '', 'ua', NULL, 0, NULL, NULL),
(1095, 577, 'Було приємно для вас співати', 0, 'Куплет 1\nБуло приємно для вас співати,\nВід себе хочем вам побажати:\n\nПриспів: \nХай всякі біди вас обминають,\nХай ваші рідні щастя лиш мають, \nХай Божа милість вас не минає, \nЛюбов Христова всіх об\'єднає.\n\nКуплет 2\nЗ\'єднаймо руки, бо нас багато, \nНе зможе ворог нас подолати.\n\nКуплет 3\nЯкщо ви раді нам щось сказати,\nТо просим разом з нами Співати.', '', '', 'ua', NULL, 0, NULL, NULL),
(1096, 578, 'Мене любов Христова', 0, 'Куплет 1\nМене любов Христова знайшла в моїх гріхах. \nЗнов до Отця привела, підтримала в нуждах.\nВелика сила звише на ноги підвела,\nВ мені життя знов дише - за те Христу хвала.\n\nПриспів:\nІ життя моє тепер є солодшим з кожним днем,\nА любов багатше, все сильніше й краще \nТягне до Христа мене.\n\nКуплет 2\nХодив Він по Юдеї віки тому назад.\nЗа Ним, як за Мойсеєм, гуртом ішов народ. \nУсіх калік зціляв Він, дав зір їхнім очам.\nІ дав також мені Він зціляючий бальзам.\n\nКуплет 3\nЛюбов Його привела, щоб Він страждав за нас, \nЩоби спасти від гніву, що мав пожерти нас.\nХай всі святі з хвалою здіймуться в небеса,\nХай вся земля і небо славить Спасителя,', '', '', 'ua', NULL, 0, NULL, NULL),
(1097, 579, 'Над світом морок', 0, 'Куплет 1\nНад світом морок і тривога,\nЗайшло вже сонце за обрій.\nСвіт твердо спить В гріхах, без Бога,\nБез щастя вічного й надій.\n\nПриспів: \nВ останні дні, що йдуть \nНад нашою землею,\nДля мене, Христе, будь \nОпорою моєю.\n\nКуплет 2\nВ душі людського покоління \nЛиш неспокій та буревій...\nА я в Тобі знайшов спасіння\nІ щастя вічного спокій.\n\nКуплет 3\nКоли земля з ділами скоро \nВогнем навіки спалахне,\nІсус Христос, моя опора,\nМене до неба забере.\n\nКуплет 4\nЩасливий я, що вірю в Бога, - \nВін - Пастир добрий для овець,\nВін - світло правди і дорога,\nВін - мій початок і кінець.', '', '', 'ua', NULL, 0, NULL, NULL),
(1098, 580, 'На небі мій Отцівський дім', 0, 'Куплет 1\nНа небі мій Отцівський дім - я хочу до Ісуса!\nНі сліз, ні горя в домі тім - я хочу до Ісуса!\nДо Нього лину кожну мить,\nЯ буду в Ньому вічно жить (2р.) - я хочу до Ісуса!\n\nКуплет 2\nЛюдина мріє мати дім - я хочу до Ісуса!\nВона будує щастя в нім - я Хочу до Ісуса!\nА з часом щастя промине,\nМоє ж насліддя в небі все (2р.) -я хочу До Ісуса\n\nКуплет 3\nДо дому хочу я весь час - я хочу до Ісуса!\nБо Він мене навіки спас - я хочу до,Ісуса!\nПрощай, земля! Я в дім святий\nІду туди, де спокій мій (2р.) - я хочу до Ісуса!', '', '', 'ua', NULL, 0, NULL, NULL),
(1099, 581, 'Ти так близький', 0, 'Куплет 1\nТи так близький, ніби берег морю,\nМилий Ти, як мати для дітей.\nТи прийшов кінець покласти горю,\nТи прийшов простить, обнять людей.\n\nКуплет 2\nБез Тебе й життя мені не треба,\nБез Тебе я навіть не дишу.\nДо Тебе душа, як птах до неба;\nНе лишай мене, - Тебе прошу.\n\nКуплет 3\nДе з землею зустріч буде неба,\nЩоб із рук землі усіх прийнять,\nТам уперше я побачу Тебе \nВіч-на-віч і буду прославлять.\n\nКуплет 4\nА тепер з надією, щасливо \nЯ живу, поки візьмеш туди.\nТи є ближчий, ніж пісок припливу,\nІ дорожчий в спеку від води.', '', '', 'ua', NULL, 4, '2021-03-28', NULL),
(1100, 582, 'Нема Бога більшого', 0, 'Куплет 1\nНема Бога більшого, як наш, нема, нема!\nНема такого Бога, як наш Великий Бог! (2р.)\n\nПриспів: \nНе нашою силою, не нашою мудрістю,\nЛиш тільки Духом Святим - \nА ми все горе переживем (Зр.)\nСилою, Духом Святим.', '', '', 'ua', NULL, 3, '2020-12-04', NULL),
(1101, 583, 'Не одна сльоза', 0, 'Куплет 1\nНе одна сльоза гаряча, не один прийде ще жаль,\nЩе не раз заплачеш гірко, поки будеш в небесах.\n\nПриспів:\nАле потім з уст полине\n(Але потім з уст полине пісня Божої дитини),\nВічна слава без кінця,\nКоли Сам Господь нас стріне,\n(Коли Сам Господь нас тріне, і як тато нас обійме)\nВ славі Божій у Отця.\n\nКуплет 2\nНе один ще біль та кривду мусимо перенести, \nДоки можна буде в славу Царства вічного ввійти.\n\nКуплет 3\nНе одна ще страшна хвиля, не один гіркий ще час Зранять душу до безсилля, поки Прийде любий Спас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1102, 584, 'Не цвітом весняним', 0, 'Куплет 1\nНе цвітом весняним, не шовком-травою - \nКолючками вбраний мій шлях за Тобою.\nДо цілі святої іду за Тобою,\nТобі довіряю, Тебе я держусь,\nМій добрий Спаситель, мій вірний Ісус.\n\nКуплет 2\nСтарію літами, хворію порою,\nІ хмари з громами пливуть наді мною.\nДо цілі святої іду за Тобою,\nВ Тобі молодію, Тебе я держусь,\nМій добрий Спаситель, мій вірний Ісус.\n\nКуплет 3\nТебе я кохаю любов’ю палкою.\nНікого не знаю, живу лиш Тобою.\nДо цілі святої іду за Тобою.\nМій Боже коханий, Тебе я держусь,\nМій добрий Спаситель, мій вірний Ісус.', '', '', 'ua', NULL, 0, NULL, NULL),
(1103, 585, 'Обіцяв Твоє Слово прийняти', 0, 'Куплет 1\nОбіцяв Твоє Слово прийняти \nЙ не піддатись спокусі гріха,\nІ для Тебе себе все віддати, \nБo знайшов я Спасіння й життя.\n\nПриспів: \nО, Отець, що є вічно у небі,\nНа землі і усюди, кругом.\nПодавай з неба хліб нам щоденний \nІ пошли в серце першу любов.\n\nКуплет 2\nЯ негідний був, грішник, я знаю,\nІ далеко від Тебе блудив - \nТвоя ласка і кров гріх мій змила,\nВсі провини мені Ти простив.\n\nКуплет 3\nЯкщо хочеш буть, друже, спасенним \nТа отримати вічне життя,\nТо сьогодні цілком ти віддайся \nДля Спасителя свого Царя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1104, 586, 'О благай Христа мій друже', 0, 'Куплет 1\nО, благай Христа, мій друже, кожним часом дорожи. \nВір, молись, не будь байдужим, до Спасителя спіши.\n\nПриспів:\nВін дає всім серцям тут надію, радість там. (2р.)\n\nКуплет 2\nДо Христа прийди покірно, як дитя Його проси.\nЛюбить Він тебе безмірно, від загибелі спасе.\n\nКуплет 3\nІсус серце утішає, я люблю Ім’я Його.\nВін мене лиш підкріпляє, стереже від зла всього.\n\nКуплет 4\nВірні будуть зустрічати Вічного Царя з небес; \nХриста будуть прославляти як Творця святих чудес.', '', '', 'ua', NULL, 0, NULL, NULL),
(1105, 587, 'Ой куди піду ще я', 0, 'Куплет 1\nОй куди піду ще я, де мені шукать спасіння?\nДе знайде душа моя від недуги ізціління?\n\nКуплет 2\nСкрізь по світі я ходив, серце радості шукало - \nЩастя світ не подарив, в серці сумно й скорбно стало.\n\nКуплет 3\nДо людей я не піду правди, істини шукати - \nБоже мій, до Тебе йду, щоб з Тобою пробувати.\n\nКуплет 4\nЛиш у Тебе одного є утомленим спасіння.\nІ від горя свойого знайду повне утішення.\n\nКуплет 5\nО прийми, прийми мене, Боже правди і любові!\nХай гріховне все мине, дай життя почати нове.', '', '', 'ua', NULL, 0, NULL, NULL),
(1106, 588, 'Ой тяжко тяжко', 0, 'Куплет 1\nОй, тяжко, тяжко в світі серед неправди жить. \nНещасним, безутішним хто радість подарить?\nХристос, тільки Він (Зр.) Тебе утішить назавжди.\n\nКуплет 2\nЯ в горю і печалі, марні мої всі дні.\nХто зітре мої сльози і поміч дасть мені?\nХристос, тільки Він (Зр.) Тебе утішить назавжди.\n\nКуплет 3\nМій гріх мене турбує - яким на суд прийду?\nНе знаю де прощення і захист де знайду?\nВ Христа одного (Зр.),мій друже, спасіння ти знайдеш.', '', '', 'ua', NULL, 0, NULL, NULL),
(1107, 589, 'Під час тривоги', 0, 'Куплет 1\nПід час тривоги, смутку та сумніву \nНе бачу світла я на цій землі.\nДуша болить і томиться в сумнівах.\nСпішу, Христе, в молитві до Тебе.\n\nПриспів: \nЩасливий я, що Друга в світі маю, \nЩасливий я, - Він завжди при мені. \nЖиву я з Ним і в Ньому пробуваю. \nЩасливий я, - Він при мені всі дні.\n\nКуплет 2\nТвій образ дивний, лагідний, смиренний.\nІсусе, Ти живи в мені всі дні,\nІ будь в моєму серці Ти щоденно,\nВпасти не дай під тягарем мені.\n\nКуплет 3\nМені порою важко тут буває,\nЗдається, що Сам Бог лишив мене.\nТоді в душі Слова Твої лунають: \n- Я не покину, Я люблю Тебе!', '', '', 'ua', NULL, 0, NULL, NULL),
(1108, 590, 'О небесний спокій', 0, 'Куплет 1\nО, небесний спокій є в моїй душі.\nВідчуваю я цей спокій тепер,\nБо Ісус Спас простив всі гріхи мої,\nІ вільним я є тепер.\n\nПриспів: \nВін є мій і я Його є\nЗавжди слава все Йому. (2р.)\nВін мені солодкий Свій дав спокій, \nВін повічні віки мій.\n\nКуплет 2\nІ тепер душа вже спочиває в Нім, і \nБо Він дав мені цей дивний спокій.\nВін мене хоронить від зла в світі цім \nІ повіки Він є мій.\n\nКуплет 3\nДарував мені Він радість без кінця - \nВідчуваю я радість цю тепер.\nБуду я служити Йому до кінця \nЙ прославляти Його все.\n\nКуплет 4\nІ любов Божа втішає все мене - \nВідчуваю я цю любов тепер.\nXвилі радості пливуть у душу все,\nІ солодше з кожним днем.', '', '', 'ua', NULL, 0, NULL, NULL),
(1109, 591, 'О потіш моє серце', 0, 'Куплет 1\nО, потіш моє серце, Спасителю мій,\nСловом правди в любові безкраїй.\nВладно море бурхливе кругом успокій,\nЩо слабкий мій човен заливає.\n\nКуплет 2\nДай дістатись щасливо крізь хвилі страшні \nДо святої Країни спокою.\nБудь зі мною, о Спасе, усі мої дні,\nВ бурях зла не лиши самотою.\n\nКуплет 3\nПрагну голос Твій чути в темряві нічній,\nВ цьому грізному темному морі:\nАдже бурі і хвилі у владі Твоїй - \nНакажи, і затихнуть в покорі.\n\nКуплет 4\nСвятим Духом у серці моїм пробувай \nІ не будуть ті хвилі страшними;\nСловом правди й любові над мною сіяй,\nБудь душі моїй в темряві зримим.', '', '', 'ua', NULL, 0, NULL, NULL),
(1110, 593, 'Ось Ісус стіл нарядив', 0, 'Куплет 1\nІсус стіл нарядив, де святих колись кормив;\nВін і нині кличе на обід всіх нас.\nВін нам манну всім дає, постачає для нас все.\nЯк з Христом солодко їсти всякий час!\n\nПриспів: \nНа обід Спаситель кличе усіх- нас,\nМожем їсти при Його столі всяк час. \nНакормив Він множество І зробив з води вино.\nНа обід Він кличе днесь усіх нас.\n\nКуплет 2\nЯк Апостоли колись вчули голос і прийшли,\nБо Спаситель Сам їх кликав на обід.\nЯк до берега прийшли, - рибу й хліб в вогні знайшли. \nВін днесь кличе всіх голодних на обід.\n\nКуплет 3\nСкоро Сам Ісус прийде, від землі своїх візьме \nІ святих всі сонми будуть в небі там.\nТо буде чудовий збір - в білім строю вбрані всі \nІ з Христом будуть кормитись вічно там.', '', '', 'ua', NULL, 0, NULL, NULL),
(1111, 594, 'Одного Боже прагну я', 0, 'Куплет 1\nОдного, Боже, прагну я,\nЩоб мати серце зовсім чисте.\nОбмий мене зовсім з гріха,\nО, Боже мій, обмий мене.\n\nПриспів: \nО, Боже мій, обмий мене,\nА, як потрібно, - чисть вогнем.\nЯк хочеш чисть, щоб тільки гріх \nБільше не був в серці моїм.\n\nКуплет 2\nВід злих думок, гріха і зла,\nХоч уникаю я Щодня,\nТа, як би не старався я, - \nНечистий я, нечистий я.\n\nКуплет 3\nХоч дав би Ти, о Боже мій,\nБагатство, славу і успіх,\nТа серце чисте є важніш \nНад скарби всі, над скарби всі.\n\nКуплет 4\nЯк серце чистеє буде,\nТо вбачу я діла святі, -\nІ в славу Бог мене прийме -\nВ Небесний Дім, в Небесний Дім.', '', '', 'ua', NULL, 0, NULL, NULL),
(1112, 595, 'Перед красними дверима', 0, 'Куплет 1\nПеред красними дверима храму\nЧоловік, кривий від роду, милостині все просив.\nЙшли Петро та Іван на молитву \nТой кривий руку простягнув до них.\n\nПриспів:\nСрібла і золота не маю, що ж маю, те тобі даю - \nВ ім’я Ісуса з Назарету вставай та ходи, \nПрославляючи Христа.\n\nКуплет 2\nПетро взяв його за праву руку \nІ підняв його вгору, і поставив на ноги - \nТой, підскочивши, пішов з ними в храм. \nПоходжаючи, він прославляв Христа.\n\nКуплет 3\nСкільки в світі є кривих душею,\nВсе блукають, не знають про спасіння.\nХто ж протягне їм руку утішення? - \nУмирають без Бога і прощення.', '', '', 'ua', NULL, 0, NULL, NULL),
(1113, 596, 'По скелях летючи', 0, 'Куплет 1\nПо скелях летючи, шумить і вирує,\nВниз воду зливає невпинна ріка:\nІ піняться хвилі, несучи каміння, -\nїх клекіт бурхливий на мить не вмовка.\n\nКуплет 2\nНа гілці, що тут же схилилась над виром,\nЯ пташечку бачу крізь пиль водяну -\nВона над проваллям спокійно літає\nІ пісню під гуркіт співа чарівну.\n\nКуплет 3\nО, Божа пташино, хто дав тобі спокій?\nНавчи нас співати крізь бурі життя.\nСкажи, як в тім реві спокій зберігаєш,\nКрізь гуркіт щебечеш із вдячним чуттям?\n\nКуплет 4\nУ відповідь пташка, свій спів повторивши,\nПіднялась на крильцях у сяючу вись.\nІ вмить стало ясно для серця мойого:\nЯк прагнеш спокою,- у небо стремись.\n\nКуплет 5\nМолитва - це крила, які дані Богом \nНам, людям, страждальцям цієї Землі.\nУчися від пташки нести всі тривоги \nТому, Хто сіяє у вічній хвалі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1114, 597, 'Послухайте цю повість', 0, 'Куплет 1\nПослухайте цю повість про Спасителя Христа,\nЯк Він лишив Небесний Дім, Дім Господа Отця.\nСпитаєш ти, чом Він терпів - Я знаю, що за нас.\nЗа нас Він дав життя Своє, тому, що любить нас.\n\nПриспів: \nВін любить нас. (2р.)\nВін дав Своє життя за нас,\nТому, що любить нас.\n\nКуплет 2\nЯ рад, що мій Спаситель по Галилеї ходив,\nДо всіх звертавсь з любов’ю і святим життям Він жив.\nВін кликав за Собою, і я піду за Ним теж.\nНіколи Він не лишить нас, тому, що любить нас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1115, 598, 'Поки молоді і сильні', 0, 'Куплет 1\nПоки молоді і сильні, серце б’ється у груді - \nДружно всі підем у битву, переможем зло і гріх.\n\nПриспів: \nВ винограднику Христовім \nКожний труд собі знайде,\nІ, коли цей труд закінчимо,\nСонечко нам не зайде.\n\nКуплет 2\nСам Христос тут буде з нами, він поможе в боротьбі. \nТо ж вперед всі, не вагаймось, ждім на поміч з висоти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1116, 599, 'Роде невірний', 0, 'Куплет 1\nРоде невірний та серцем лукавий,\nГоді вже Бога святого гнівить! \nГоді грішити, неправду творити!\nТреба вже Богові вірно служить.\n\nКуплет 2\nСлавити Бога - великеє щастя. \nЗавжди повинні про це ми подбать.\nДушу і тіло на добреє діло,\nСерце повинні Йому ми віддать.\n\nКуплет 3\nНива дозріла, робітників мало,\nПраця велика потрібна кругом.\nЧасу не гайте та з Богом рушайте\nБог вам поможе усяким добром.\n\nКуплет 4\nДяка велика Тобі, наш Владико. \nСлавити будем Тебе усі ми.\nКров Твого Сина гріхи наші змила, \nНас всіх звільнила з тяжкої тюрми', '', '', 'ua', NULL, 0, NULL, NULL),
(1117, 600, 'Руки благодаті', 0, 'Куплет 1\nВсе Христові руки в ранах пресвятих \nВірою я бачу: кров струмує з них.\nО, ту кров спасіння, що сплива з тих рук,  \nСлавить мого серця кожен вдячний стук.\n\nКуплет 2\nСкільки милосердя ви творили всім, \nЗмученим гріхами, хворим і сліпим.\nО, любові руки, світ вам заплатив \nТим, що вас у глумі до хреста прибив.\n\nКуплет 3\nВас, Христові руки, Бог нам розпростер,\nЩоб ніхто душею у гріхах не вмер.\nЩоб могли, омиті ми у їх крові,\nУвійти, спасенні, в Вічний Край хвали.\n\nКуплет 4\nРуки благодаті, серцем бачу вас \nВ світлі над собою скрізь і повсякчас. \nО, святії руки, з тьми гріха і зла \nВаша кров пречиста і мене спасла.', '', '', 'ua', NULL, 0, NULL, NULL),
(1118, 601, 'Світи у куточку', 0, 'Куплет 1\nНе чекай, щоб що великого зробити міг,\nА будь вірним в меншім ділі ти. \nНе чекай, щоби далеко ти світити міг,\nСвіти у куточку, де ти є.\n\nПриспів: \nСвіти у куточку, де ти є! (2р.)\nЩоби ті, що у пітьмі,\nУсі до Господа прийшли - \nСвіти у куточку, де ти є.\n\nКуплет 2\nМногі люди цього світу блудять у пітьмі - \nСвоїм світлом шлях їм освіти.\nПостарайся поміч дати хоч одній душі,\nСвіти у куточку, де ти є.\n\nКуплет 3\nВсіх людей, що у темряві, Ти сам пробуди, \nА голодних хлібом накорми.\nТи раненько при зорі всіх до Христа веди, \nСвіти у куточку, де ти є.', '', '', 'ua', NULL, 0, NULL, NULL),
(1119, 602, 'Святий Боже Всемогутній', 0, 'Куплет 1\nСвятий Боже Всемогутній,\nВчуй нас в цей благальний час.\nМи Тебе від серця просим:\nПрости і помилуй нас.\n\nКуплет 2\nСвятий, кріпкий, недосяжний - \nНас не кинь в непевний час,\nНе відмов нам в благодаті,\nПрости і помилуй нас.\n\nКуплет 3\nБоже, глянь: Ми - Твої діти,\nМолимо Тебе всі враз:\nДай нам сили все здоліти,\nІз гріхів звільни Ти нас.\n\nКуплет 4\nЯк без батька і без неньки \nСиротина все тужить,\nТак без Тебе, милий Боже,\nТяжко і тривожно жить.', '', '', 'ua', NULL, 0, NULL, NULL),
(1120, 603, 'Скажи мені о Боже мій', 0, 'Куплет 1\nСкажи мені, о Боже мій, чому сумує душа моя? \nУсюди лиш темрява нічна. (2р.)\n\nКуплет 2\nСкінчився день, настала ніч і світла не видно навкруги, \nХоч близько Йорданські береги. (2р.)\n\nКуплет 3\nХто хоче з нас ввійти в той Край, де зникне темрява нічна?\nВеде нас туди любов одна. (2р.)\n\nКуплет 4\nЗішли любов, Спаситель мій, і світлом Твоїм Ти засвіти, \nПровини усі мої прости. (2р.)\n\nКуплет 5\nПрости, благаю я Тебе, розглянь моє серце; Спасе, Ти, \nХай вічно з Тобою душа живе!  (2р.)\n\nКуплет 6\nМій Спасе, скеле Ти моя, лиш в Тебе наука є свята-\nЯ хочу учитись лиш в Христа. (2р.)\n\nКуплет 7\nТи мій Спаситель і мій Творець, Ти мій Спаситель і мій Отець, \nЩо дасть мені золотий вінець. (2р.)\n\nКуплет 8\nКоли явишся, Спасе мій, із ангелами в славі Отця,- \nТоді вознесеться Церква жива. (2р.)\n\nКуплет 9\nВсі вірні діти, мов зірки, сіяти будуть на небесах - \nЗакон зберегли святий в серцях. (2 р.)\n\nКуплет 10\nЗате заплату Бог нам дасть, що вірні були тут на землі. \nО, слава Творцеві, так, амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(1121, 604, 'Сказав Христос', 0, 'Куплет 1\nСказав Христос: хто має вуха, нехай почує голос Мій. \nВже скоро прийду в силі Духа і засвічу світильник твій.\n\nПриспів: \nРаджу тобі купити в Мене \nЗолото перечищене,\nЩоб збагатився і звеселився - \nТоді прославиш ти Мене.\n\nКуплет 2\nКупи собі одежу білу, щоб зодягнувся нею ти.\nІ одягни її на тіло, щоби не видно наготи.\n\nКуплет 3\nІ мазі до очей купити Я нині раджу Сам тобі,  \nЩоб очі твої намастити, аби не жив ти у злобі.\n\nКуплет 4\nКого я люблю - докоряю. Будь ревний і покайся.\nСтою ось під дверми й чекаю, - як чуєш, то не гайся.\n\nКуплет 5\nЯ стукаю до серця твого, а ти, як чуєш, відчини.\nХто прийме, то прийду до нього й буду вечеряти Я з ним.\n\nКуплет 6\nХто переможе - дам йому сісти зі Мною на престолі,\nНебесні блага буде їсти зі Мною по Господній волі.\n\nКуплет 7\nЯ переміг і сів навіки з Отцем моїм на небесах.\nІ ви прийміть блаженні ліки - прийду до вас у чудесах.', '', '', 'ua', NULL, 0, NULL, NULL),
(1122, 605, 'Слухай заклик Спаса', 0, 'Куплет 1\nСлухай заклик Спаса, друже!\nОсь Він стука в серце знов.\nНе відкладай, ще сьогодні\nТи прийми Його любов.\n\nПриспів:\nЗахист Він від бурі світа, вірне Сховище від зла.\nВ Нім любов\'ю є відкрита Царства вічного хвала.\n\nКуплет 2\nО, прийми Його - і будеш \nЖити вже життям новим,\nЖиттям віри і любові,\nЩастям сповнений святим.\n\nКуплет 3\nДорожи, упертий друже,\nНапоминанням Христа- \nУ тім стуку милосердя \nВся любов Його свята.\n\nКуплет 4\nВ цьому світі все минає - \nЛюд Христом не дорожить ...\nУ кінці ж Господь за гробом \nЗасуд Свій страшний звершить.\n\nКуплет 5\nМуки совісті страшливі \nТам байдужих огорнуть,\nЩо в житті Христа минали \nІ ганьбили Його путь.\n\nКуплет 6\nО, не гайся відізватись,\nДруже, ти на заклик цей. \nСтук Христа замовкнуть може \nДо глухих твоїх грудей.\n\nКуплет 7\nІ за вічності порогом \nТи почуєш в грізний час: \n\"Пізно вже! Закриті двері,\nВідійдіть, не знаю вас.\"', '', '', 'ua', NULL, 0, NULL, NULL),
(1123, 606, 'Спас за мене постраждав', 0, 'Куплет 1\nСпас за мене постраждав, за мій гріх Він смерть прийняв\nІ за це життя своє віддаю Йому я все.\n\nПриспів:\nО, навчи нас, любий Спасе, як прожить життя своє,\nЩоб померло грішне наше, а зросло святе Твоє.\n\nКуплет 2\nНам Христос любов явив, нас усіх Він поріднив.\nХоче Спас, щоб ти і я з Ним були одна сім’я,\n\nКуплет 3\nСкоро прийде знову Він, нас введе в Небесний Дім:\nВічно будем жити з Ним, з Спасом любим, дорогим.', '', '', 'ua', NULL, 0, NULL, NULL),
(1124, 607, 'Там за обрієм', 0, 'Куплет 1\nТам, за обрієм, славна Країна \nВ ній безмежна завжди краса.\nСкінчиться труд наш, праці година \nТам, за обрієм, на небесах.\n\nКуплет 2\nТам, за обрієм, немає спеки,\nСтрашних морозів, бур і вітрів.\nБудемо жити без небезпеки \nСеред чудових Божих садів.\n\nКуплет 3\nТам, за обрієм, зустріч щаслива \nНастане з тими, що відійшли.\nРозлука в небі вже неможлива \nТим, що спасіння вічне знайшли.', '', '', 'ua', NULL, 0, NULL, NULL),
(1125, 608, 'Певно я знаю що Ісус мій', 0, 'Куплет 1\nПевно я знаю, що Ісус мій,\nБо мене держить в руці Своїй!\nВін моє серце в крові святій \nОбмив і дав теж Дух Свій Святий.\n\nПриспів: \nТепер я славлю Його щодня,\nБо Його ласка мене спасла.\n\nКуплет 2\nГолос любові звучить усе,\nЩо Ісус Кров\'ю звільнив мене.\nЯ є безпечний усюди є з Ним,\nБо Він заслонить щитом Своїм.\n\nКуплет 3\nВін наповняє душу мою \nСвятим спокоєм і любовію.\nЙому служити буду все я,\nБо він для мене придбав життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1126, 609, 'Тобі я прагну все співати', 0, 'Куплет 1\nТобі я прагну все співати,\nМій Боже, за любов Твою.\nСпасінням побажав підняти \nСкорботну душу Ти мою. - \nНіколи я не перестану\nТобі з душі співать \"Осанна!\".\n\nКуплет 2\nЛиш вранці сонце заясніє - \nТобі молитись я люблю.\nВ нічній тиші, як все німіє,\nТебе я піснею хвалю.\nІ щастя більшого не треба,\nЯк йти з хвалінням до Тебе.\n\nКуплет 3\nТебе Святого прославляти \nЯ, Боже, прагну всім життям,\nТвою присутність відчувати \nНа кожнім кроці всім чуттям.\nТобі в душі моїй щасливій \nНе вмовкнуть вдячні славоспіви.', '', '', 'ua', NULL, 0, NULL, NULL),
(1127, 610, 'Ти куди йдеш подорожній', 0, 'Куплет 1\nТи куди йдеш, подорожній, з палицею у руці?\n- Я іду в рідну Країну, там знайду спокій душі.\n\nКуплет 2\nЧерез гори і долини, через степи і ліси,\nЧерез пущі і рівнини я іду у рідний Край.\n\nКуплет 3\n- Що дадуть тобі в тім Краю, що веселий такий йдеш?\n- Там дадуть для мене Славу і життя навіки жде.\n\nКуплет 4\nТам течуть живії води, там є цвіт життя, плоди.\nТам є цвіт життя, плоди - все навіки жде.\n\nКуплет 5\n- Ти самотній не боїшся по дорозі цій іти?\n- Я не сам, зі мною всюди ангели Господні є!\n\nКуплет 6\nІсус завжди є при мені, стереже в кожній хвилині. \nСтереже в кожній хвилині на дорозі цій вузькій.\n\nКуплет 7\n- Візьми мене, подорожній, щоб і я бачив той Край.\n- Дуже радо, любий друже, руку свою мені дай.', '', '', 'ua', NULL, 0, NULL, NULL),
(1128, 611, 'Все в Твоїх руках святий Владико', 0, 'Куплет 1\nВсе в Твоїх руках, святий Владико,\nІ як дивно Ти усе створив.\nТи по милості Своїй великій \nВід гріхів нас Кров\'ю відкупив.\n\nКуплет 2\nТи поніс за нас важкі страждання,\nМуки і насмішки від людей.\nЦе - ціна за наше оправдання \nЙ дороге звання Твоїх дітей.\n\nКуплет 3\nПоможи щохвилі пам\'ятати,\nЩо такого Батька діти ми.\nІ подяку від душі складати,\nЩо Ти вивів нас з недолі й тьми\n\nКуплет 4\nДай Ти нам постійно відчувати \nДуха Твого силу й благодать,  \nЩоб душа могла завжди співати,\nІ Твоє лиш ім\'я прославлять', '', '', 'ua', NULL, 0, NULL, NULL),
(1129, 612, 'В бурях народжене', 0, 'Куплет 1\nВ бурях народжене плем’я Христове,\nЩо йдеш за Ісусом в рішаючий бій,\nВ останні часи ці під стягом любові \nПривіт тобі, юне, привіт наш палкий!\n\nКуплет 2\nБезвір’я навколо повстало стіною,\nСтискає злобою і горем серця, - \nЙому протиставтесь душею одною \nІз полум’ям віри, стійкі до кінця.\n\nКуплет 3\nXристос-переможець іде перед вами,\nХитається зло, де любов Його йде.\nВперед же, в борінні зімкнися рядами,\nКвітуюче плем’я Христа молоде.\n\nКуплет 4\nСьогодні усіх вас Христос обнімає \nНа грудях Своїх, як любимих дітей. \nА завтра, можливо, когось вас спіткає \nСтраждання від злоби осліплих людей.\n\nКуплет 5\nНе бійсь, світлоноснеє плем’я Христове,\nЗміняйте утомлених боєм борців,\nРостіть і квітуйте суцвіттям любові,\nІ зрійте красою Христових плодів!', '', '', 'ua', NULL, 0, NULL, NULL),
(1130, 613, 'У вирій в тузі журавлі', 0, 'Куплет 1\nУ вирій в тузі журавлі відлітають,\nІ вітер свистить в почорнілих лісах - \nВін з гілок останні листочки зриває  \nІ холодом віє в промоклих полях.\n\nКуплет 2\nЯк добре отим журавлям, що прямують \nНа південь, де зелень, де вічне тепло;\nДе в сонці луги незатьмарно квітують,\nДе сніжних заметів повік не було.\n\nКуплет 3\nОсь так, на Христа уповаючим душам,\nВідрадно доходить до вічності днів,\nДе їх не діткне ні страждання, ні стужа,\nДе будуть з Христом вже навіки-віків.\n\nКуплет 4\nО, друже, не тим перейматися маєш, \nЩо осінь холодна листву обрива, \nА тим, яка вічність тебе вже чекає \nЗа гранню життя, що спішить-проплива.\n\nКуплет 5\nВесна ще вернеться і буде ще літо,\nИ лілеї пахучі цвістимуть в тиші;\nАле чи ти, друже, готовий зустріти \nОбіцяне Богом блаженство душі?\n\nКуплет 6\nАдже ти Христа не чекаєш у славі,\nПри трубах архангелів світлих висот, \nЯк, тілом змінившись, полине в прославі \nНазустріч Христові спасенний народ.\n\nКуплет 7\nЗадумайсь над цим, і схились перед Богом \nПоки ще лунає Євангельський зов,\nЩоб потім не вздріти себе за порогом - \nСпіши, доки кличе Христова любов.', '', '', 'ua', NULL, 0, NULL, NULL),
(1131, 614, 'Хай буде воля Боже Твоя', 0, 'Куплет 1\nХай буде воля, Боже, Твоя \nЗавжди моєю - благаю я.\nЯ, як та глина, в Твоїй руці,\nЗ мене, що хочеш, зроби Собі.\n\nКуплет 2\nХай буде воля, Боже, Твоя,\nДивись, чи чиста душа моя.\nКров’ю святою мене обмий,\nЩоб був я здібний на труд святий.\n\nКуплет 3\nХай буде воля, Боже, Твоя —	\nТільки на Тебе надіюсь я,\nТи - моя сила і мій спокій,\nТи - моя радість, Спаситель мій.\n\nКуплет 4\nХай буде воля, Боже, Твоя —\nТи Святим Духом мене сповняй,\nЩоби побачили люди всі,\nЩо Ти, Ісусе, живеш в мені.', '', '', 'ua', NULL, 0, NULL, NULL),
(1132, 615, 'Хочу я з Тобою говорить', 0, 'Куплет 1\nХочу я з Тобою говорить,\nТи найкращим Другом є моїм.\nЧуєш Ти ридання, плач душі, 2р.\nНа мене глянь оком Ти Своїм.\n\nКуплет 2\nГоре я сховаю від людей,\nЛиш Тобі одному розкажу.\nЯ надіюсь, Боже, на Тебе,\nІ від Тебе сил, спокою жду.\n\nКуплет 3\nЧасто йду до Тебе, Боже мій,\nВ час, коли темрява є кругом,\nЩоб на мене глянув Ти з небес,\nСерце освітив моє Ти знов.\n\nКуплет 4\nО, як важко, Боже, в світі жить,\nВ ці часи непевні марноти.\nСили, Боже, Ти мені пошли,\nПоможи шляхом до Тебе йти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1133, 616, 'Христе Ти як те сонце', 0, 'Куплет 1\nХристе, Ти - як те сонце \nЯсне, веселе - Ти є любов. (2р.)\nРадість, о, що за радість\nДаєш Ти, Христе, в моє життя. (2р.)\n\nПриспів: \nА смуток веде ближче до Бога,\nЦей смуток скінчиться скоро вже. \nТісноти на коліна приводять...\nТісноти, коли залишу вас? (2р.)\n\nКуплет 2\nXристе - Ти є надія,\nЩо скоро смутку прийде кінець. (2р.)\nШляхи там золотії,\nТам все сіяє блиском небес. (2р.)\n\nКуплет 3\nХристе, ще поки тут я\nМолю: тримай Сам біля Себе. (2р.)\nСлабий, падаю завжди, -\nВсе ж таки рвуся ближче Тебе. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1134, 617, 'Цар Сіонський', 0, 'Куплет 1\nЦар Сіонський, наш Спаситель,\nПрийде скоро вже до нас.\nСповняється Слово Боже,\nЩо вже близький всьому час.\n\nКуплет 2\nПринесе усім заплату,\nКожному з нас по ділах:\nСправедливим - радість вічну,\nНечестивим - плач, сором.\n\nКуплет 3\nДіти Божі всі зберуться,\nБудуть Спаса прославлять,\nЩо за гріхи всього світу \nНа Голгофі був розп’ят.\n\nКуплет 4\nГopa Сіон буде чиста,\nЯк новий Єрусалим - \nЧистішая від золота,\nНа ній буде Божий Син.\n\nКуплет 5\nПрославлять Його ангели - \nХерувим і серафим.\nПрославляють і прославлять - \nТо ж прославмо Його й ми.\n\nКуплет 6\nЯк прекрасно на Сіоні,\nДе наш Цар, Спаситель, Бог,\nБуде правити народом \nІ не буде вже тривог.\n\nКуплет 7\nНечестивих там не буде\nІ ніякого гріха.\nТільки будуть діти Божі \nПрославлять повік Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1135, 618, 'Цей світ нам каже', 0, 'Куплет 1\nЦей світ нам каже, що користі немає \nСлужить Ісусу, коли ми молоді, - \nАле ми знаєм, ми твердо це знаєм,\nЩо ми нагороду одержим від Христа.\n\nКуплет 2\nЦей світ нам каже, щоб ми йому служили, \nКоли здорові, сильні й молоді,\nАле ми знаєм, і певно це знаєм,\nЩо ми нагороду одержим від Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1136, 619, 'Чи думав ти колись', 0, 'Куплет 1\nЧи думав ти колись, чому сльози течуть \nЗ твоїх очей, коли так тяжко на душі?\nБог потішає нас, коли Він чує плач в тиші: \nБог розуміє сльози людей.\n\nКуплет 2\nКоли недоля ця спіткає нас в житті, \nНадія гасне, слабне віра і любов - \nБог все, Він поведе і сльози Сам утре: \nБог розуміє сльози людей.\n\nКуплет 3\nБог бачить сльози, всі печалі твої.\nВін бачить сльози і чує крик душі.\nБог разом плаче, відчуває біль в тобі:\nБог розуміє сльози людей.', '', '', 'ua', NULL, 0, NULL, NULL),
(1137, 620, 'Чи любиш ти брате Ісуса', 0, 'Куплет 1\nЧи любиш ти, брате, Ісуса,\nЧи знаєш ти, сестро, Його?\nЧи ціниш Його ти страждання,\nЧи слухаєш слів ти Його?\nДень Божого суду вже близько, \nДень радості скоро прийде.\nВже ангели скоро являться \nЙ Ісус в Своїй славі прийде.\n\nКуплет 2\nСвятії з гробів повиходять, \nЖивії пристануть до них - \nУсі утішатися будуть,\nЩо йде вже у славі Жених. \nКайся, люба сестро і брате, \nТримайся Ісуса Христа, - \nНавколо обняла темрява \nНаука у світі людська.\n\nКуплет 3\nПанує скрізь людськая мудрість \nА голос лунає з небес,\nЩо Бог Своїм Духом підійме,\nВсіх вірних від тої землі.\nВже гори від крові розмокли \nІ трупи лежать на полях ...  \nА жаль мені тих, що немає,\nБагато братів споміж нас.\n\nКуплет 4\nІ сестри в далекому краю - \nДля них там зібрання нема ...\nПишіть, браття й сестри, у листах,\nЩо вже почалися жнива.\nКукіль уже Господь збирає,\nІ в’язкам рахунку нема.\nВже скоро збере і пшеницю,\nІ так закінчаться жнива.', '', '', 'ua', NULL, 0, NULL, NULL),
(1138, 621, 'Чи ти чуєш голос Божий', 0, 'Куплет 1\nЧи ти чуєш голос Божий \nУ тиші самотніх стін? - \nПід дверима Перехожий - \nСлухай, що говорить Він.\n\nПриспів: \nНіжно мовить Спас твоїй душі,\nЖде тебе, - до Нього поспіши.\nСерце не вагайсь відкрити - \nВін ввійде, щоб ти міг жити,\nМир затрачений знайти. \nДруже, стань, до Нього йди!\n\nКуплет 2\nКлич любові чи ти чуєш? - \nОсь тебе Він кличе знов.\nВін один тебе врятує,\nДасть спокій тобі й любов.\n\nКуплет 3\nНе дивись, що ти спіткнувся,- \nЗнов до Нього підійди.\nКличе Він, щоб ти вернувся,\nПрагне Він тебе спасти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1139, 622, 'Чи ходив до Спаса ти', 0, 'Куплет 1\nЧи ходив до Спаса ти з своїм гріхом,\nЧи у крові із Агнця ти вмивсь? 	\nЧи щодня ти ходиш услід за Христом,\nЧи у крові із Агнця ти вмивсь?\n\nПриспів: \nВмитий ти у крові,  \nУ пречистій Христа крові, \nЧи одежа біліша над сніг твоя, \nЧи ти вмитий в Христа, крові?\n\nКуплет 2\nЧи довір я маєш до Ісуса ти, \nЧи у крові із Агнця ти вмивсь?\nЧи Його страждання відчуваєш ти,\nЧи у крові із Агнця ти вмивсь?\n\nКуплет 3\nІсус скоро прийде, чи готовий ти,\nЩоб зустрінутись з Спасом твоїм\nЧи готовий ти в Дім Божий увійти,\nЧи у крові із Агнця та вмивсь?\n\nКуплет 4\nГеть відкинь ти нині всі гріхи твої\nЧи у крові із Агнця ти вмивсь?\nБо те джерело тече для грішних всіх.\nЧи у крові із Агнця ти вмивсь?', '', '', 'ua', NULL, 0, NULL, NULL),
(1140, 623, 'Швидко дуже швидко', 0, 'Куплет 1\nШвидко, дуже швидко дні ідуть\nНаче хмари, що у даль пливуть.\nНа висках ось вкралась сивина -\nСтарість вже наближує вона.\n\nПриспів: \nСум огорта; пройшли літа, \nЯ так мало потрудився для Христа.\n\nКуплет 2\nВ юності спасіння я не знав; \nГоспода тоді не прославляв.\nПолюбляв гріховні я стежки, -\nВ звабах світу йшли мої роки.\n\nКуплет 3\nМолодість вже була позаді, \nЯк з Христом зустрівся на путі;\nПізно серце я Йому розкрив:\nСивим вже на шлях Його ступив.\n\nКуплет 4\nЩастям є із юних літ прийнять \nПресвяту Христову благодать:  \nВ тім не будеш каятись, о ні, \nЯк жаліть приходиться Мені!', '', '', 'ua', NULL, 0, NULL, NULL),
(1141, 624, 'О божих слів не забувай', 0, 'Куплет 1\nО, божих слів не забувай!	\nЯскраве світло в них для нас; \nДля Бога серце відкривай,\nСпасенним будь! - це кличе Спас.\n\nПриспів: \nДень завтра може не прийти, \nІ сонце не освітить нас.\nА зараз час (Христа знайти, \nСпасенним будь! - це кличе. Спас.\n\nКуплет 2\nУсюди в світі гріх царить,\nСпокою він тобі не дасть,\nПочни по-християнськи жить, -\nСпасенним будь, - це кличе Спас.\n\nКуплет 3\nХристос до Себе всіх прийняв,\nХто оцінив спасіння час;\nЯкби Його і ти пізнав, - \nСпасенним будь! - це кличе Спас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1142, 625, 'Я вже лишив гріховний шлях', 0, 'Куплет 1\nЯ вже лишив гріховний шлях,\nЯким ще люди йдуть в гріхах.	\nСпитаєш про причину в тім? - \nЯ йду в Небесний, Вічний Дім!\n\nПриспів: \nЦей світ, цей світ не є мій дім. (2р.)  \nЦей світ не є спочинок мій. ...\nЦей світ, цей світ не є мій дім.\n\nКуплет 2\nСпиняють люди тут мене,\nЗмагають знов в цей світ мене; \nТа я не піддаюся їм - \nЯ йду в Небесний, Вічний Дім.\n\nКуплет 3\nО, друже, йди зі мною ти \nВ Небесний Вічний Дім хвали.\nНе стій, скажи причину в тім, \nЧом ти не йдеш в той Вічний Дім?', '', '', 'ua', NULL, 0, NULL, NULL),
(1143, 626, 'Я знаю ріку що тихенько пливе', 0, 'Куплет 1\nЯ знаю ріку, що тихенько пливе\nЗ святої ріки - джерела;\nХвилює, шепоче вода і пливе,\nЧи в душу твою увійшла?\n\nПриспів: \nО, друже, скоріше ходи\nДо джерел живої води. \nЧи чуєш? -Шепоче Вода і пливе, \nТобі спокій вже несе.\n\nКуплет 2\nЯк серце осягне ту воду живу,\nТо радість огорне тоді\nІ ласку пізнаєш велику, святу,\nЗ гріхів увільнишся повік.\n\nКуплет 3\nГлибінь ця прозора, від сонця ясніш,\nПідкріпляє серце слабких,\nВеде їх по вірі до вічних країн\nІз горя і смутків земних.\n\nКуплет 4\nРіка є життя - джерело із скали \nЗ Христових виринає ран.\nЗа тебе, мій друже, за твої гріхи \nСпасіння у Крові Він дав.', '', '', 'ua', NULL, 0, NULL, NULL),
(1144, 627, 'Як Божий спокій', 0, 'Куплет 1\nЯк Божий спокій моє серце сповив -\nНехай мене буря страшить - \nЯ з вірою в Бога безстрашно іду- \nБог від зла мене захистить.\n\nПриспів: \nБог є мій, Бог є мій, я Його —\nЯ душевний спокій в Нім знайшов.\n\nКуплет 2\nГріховні кайдани Він в мене забрав,\nГріхи з мене зняв Він цілком!\nОбмив Він мене у пречистій крові,\nСпасен я могутнім Христом.\n\nКуплет 3\nО, Господи, Боже, Твого приходу я жду,\nЩоб душу узяв Ти з землі.	\nЯ знаю, що в небі для серця знайду \nСпокій я на Твоїй груді', '', '', 'ua', NULL, 0, NULL, NULL),
(1145, 628, 'Як покличе відізвуся', 30, 'Куплет 1\nЯк покличе - відізвуся (Зр.)\nБуду щиро працювати для Христа.\nБуду щиро працювати (Зр.) для Христа (2р.)\n\nКуплет 2\nЧи у горах, чи в долині, (Зр.)  \nСкрізь я буду працювати для Христа.\nСкрізь я буду працювати (Зр.) для Христа. (2р.)\n\nКуплет 3\nВінець слави я дістану, (Зр.)\nКоли буду працювати для Христа.\nКоли буду працювати (Зр.) для Христа (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1146, 629, 'Я тонув у морі зла', 0, 'Куплет 1\nЯ тонув у морі зла, в безмежній глибині\nІ далеко від Христа грозила смерть мені.\nЛиш Ісус почув мене, як плакав я в той час,\nРуку простягнув мені й мене Він спас.\n\nПриспів: \nСпаситель мій, Спаситель мій!\nВід смерті спас мене Спаситель мій!\n\nКуплет 2\nВсе життя тут на землі для Бога я віддав.\nСлавлю завжди я Його - Він спокій мені дав.\nЛаска Божа, як ріка, з серця мого пливе,\nБо Ісус Спаситель Сам в мені живе. -\n\nКуплет 3\nЯкщо томишся в гріхах, - на поміч клич. Христа. \nРуку Він подасть тобі, врятує від гріха.\nМає владу над усім, слухайся лиш Його - \nЛюбить Він тебе над все, іди до Нього.', '', '', 'ua', NULL, 0, NULL, NULL),
(1147, 630, 'Останній ще заклик', 0, 'Куплет 1\nОстанній ще заклик до тебе звучить,\nО друже, чому ти байдуже стоїш?\nСпіши до Icycа спасіння прийнять,\nЩе поки спасає Його благодать.\n\nПриспів: \nОстанній ще заклик до тебе звучить,\nО грішник, не гайся, спасіння прийми,\n\nКуплет 2\nТебе на зібрання Дух Божий привів,\nЩоб ти для душі тут спасіння знайшов.\nІ словом святим Він ще кличе: Прийди!\nЧекає тебе, але ти не спішиш.\n\nКуплет 3\nЗібрання скінчилось, стемніло кругом,\nІ заклик спасіння замовк вже давно, \nТа в серце Спаситель все стукає й жде,\nВідкрий Йому серце - Він скоро ввійде;\n\nКуплет 4\nЯк любиш життя, то весь гріх залиши.\nУ Бога спасіння - до Нього прийди.\nІсуса скоріше прийняти спіши\nI заклик останній ти в серце прийми.', '', '', 'ua', NULL, 0, NULL, NULL),
(1148, 631, 'В долині гріховній земній', 0, 'Куплет 1\nВ долині гріховній земній,\nДо незгоди, нещастя, обман,\nВ рідний Край я іду неземний \nПо скорботних слідах християн.\n\nПриспів: \nВ рідний Край неземний,\nДе нема зла й не ллється вже кров,\nЯ іду і прийду, де царює святая любов.\n\nКуплет 2\nХоч як небезпечно кругом,\nІ важка є мандрівка моя, - \nЯ надіюсь і йду за Христом \nВ рідний Край, де спочину з Ним я.\n\nКуплет 3\nСміливо вперед я іду,\nІ неспокій мені не страшний.\nЯ долину земну перейду, - \nІ ввійду в Дім Небесний святий.', '', '', 'ua', NULL, 0, NULL, NULL),
(1149, 632, 'Чують вістку люди', 0, 'Куплет 1\nЧують вістку люди всього світу:\nВолодар спасенної душі \nВ сяйві слави й в святості великій.\nЙде, щоб взяти Церкву від землі.\n\nПриспів: \nПрийде день і зустріч та настане \nНа долонях білосніжних хмар.\nІ Невіста перед Богом стане,\nЩо любов та вірність зберегла.\n\nКуплет 2\nБуде в небі радісне вінчання \nПри престолі Господа Отця.\nЗаспівають хори величально,\nТам блаженство, щастя без кінця.\n\nКуплет 3\nТож радій, обраниця Христова, - \nЗнак спасіння сяє на тобі !\nВір, молись і завжди будь готова \nГоспода бажанного зустріть.', '', '', 'ua', NULL, 0, NULL, NULL),
(1150, 633, 'Сходить сонце над обрієм', 0, 'Куплет 1\nСходить сонце над обрієм, вже звучать святі слова: \nНаверніть до Бога, люди, зникне хай темрява вся.\n\nПриспів: \nГей, слухай люд: навернись до свого Бога! \nГей, слухай люд: бо то є свята дорога.\n\nКуплет 2\nЯк кохає мати сина, так кохає Спас тебе,\nПрокидайсь, моя Вкраїно, Доки будеш спати ще?\n\nКуплет 3\nВін залічить твої рани, нове серце тобі дасть. \nЖиття радісне настане, - будеш Спасові співать.\n\nПриспів: \nГей, Україно! Навернись до свого Бога!\nГей, Україно! Бо то є свята дорога.\n\nКуплет 4\nВірю, що ніяка сила дивну Божу благодать \nНе зуміє пересилить, - буде Бог людей спасать.', '', '', 'ua', NULL, 0, NULL, NULL),
(1151, 634, 'Без пісні я жити не можу', 0, 'Куплет 1\nБез пісні я жити не можу, вона мені крила дає— \nЗдійматись над хмару ворожу, де радісно серцю стає.\n\nКуплет 2\nТам ясного неба блакиті, чудова Країна свята,\nДе вічно з Христом буду жити в оселях Отця дорогих.\n\nКуплет 3\nПостійно там буду співати, забувши страждання земні, \nСвятую любов величати, незлічені вічності дні.\n\nКуплет 4\nА зараз, хоч важко буває, - я з піснею хочу іти, - \nВона мені сил добавляє, веде до святої мети.', '', '', 'ua', NULL, 0, NULL, NULL),
(1152, 635, 'Нас в тайгу тут закинуто', 0, 'Куплет 1\nНас в тайгу тут закинуто... Вкрита снігом земля.\nНаш брат, тут умираючи, чує крик журавля.\n\nПриспів:\nАх, журавлі, журавлі! З собою візьміть мене \nЗ сибірських страшних зим, де воля, спокій є.\n\nКуплет 2\nЧую, як журавлі летять в рідний теплий мій край.\nСерце плаче від цих страждань, Боже, Ти сили дай!\n\nКуплет 3\nДійсно, вірю, що мій Господь в небі мене там жде. \nВся надія лиш на Нього, - в небо мене Він веде.', '', '', 'ua', NULL, 0, NULL, NULL),
(1153, 637, 'Немає сліз не мучить страх', 0, 'Куплет 1\nНемає сліз, не мучить страх, \nВсіх вище зір на небесах,	\nПрекрасний мир в Краю святім,\nВсіх в небі жде нас Вічний Дім.\n\nПриспів: \nО, Вічний Дім, де радість, спокій, \nО, вічний день душі там моїй! \nГосподь зове, - і ми всі йдім, \nЛюбов веде в Небесний Дім,\n\nКуплет 2\nТам неземний співає хор,\nЖива вода завжди тече.\nТам чистотою сяє все,\nТам нагорода нас чека.\n\nКуплет 3\nПогаслий день зійде світліш,\nДарує Бог хвалу в уста. \nСвою рідню і друзів всіх \nМи там знайдем в ногах Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1154, 638, 'Ти зміцняйся в Божій благодаті що в Христі', 0, 'Куплет 1\nТи зміцняйся в Божій благодаті, що в Христі,\nПрапора любові вище підійми! \nТак, як вірний воїн, догоджай Христу, -\nТоді ти світлом переможеш марноту.\n\nПриспів: \nСпрямуй свій взір ти просто до неба,  \nВорог не зможе тебе здолать.\nТам вже корона тебе чекає,  \nСміло борися й не знемагай! - 2р.\n\nКуплет 2\nТи зміцняйся в Божій благодаті, що в Христі,\nІ зберігай святу науку у житті.  \nЯк мудрець, постійно практикуй знання -\nІ світ побачить Бога із твого життя.\n\nКуплет 3\nТи зміцняйся в Божій благодаті, що в Христі,\nІ розсівай насіння про любов усім.\nМужнім будь, щоб Божу правду голосить!\nЯка темрява зможе світло погасить?', '', '', 'ua', NULL, 0, NULL, NULL),
(1155, 639, 'Жити для Спаса', 0, 'Куплет 1\nЖити для Спаса, з Ним умирать,\nЩо можна в світі краще бажать?\nВарто смирятись, варто боротись,\nВарто життя для Нього віддать.\n\nКуплет 2\nЖити для Спаса, день хоч малий,\nСутінок ночі подих тяжкий. \n«Не знемагати, не нарікати!\nВірно служити!» - клич наш святий.\n\nКуплет 3\nЖити для Спаса - гріх умертвить,\nРізні зневаги вміти терпіть.\nШлях як пройдемо, в небо ввійдемо,\nСлавно й безсмертно будемо жить!', '', '', 'ua', NULL, 0, NULL, NULL),
(1156, 640, 'Мій Бог є скеля', 0, 'Куплет 1\nМій Бог є скеля, в Ньому я \nСпокійний під час бурі.\nМені спокоєм Він сія,\nПокровом під час бурі.\n\nПриспів: \nІсус - джерело у землі сухій,\nВ землі сухій, (2р.)\nІсус - джерело у землі сухій \nІ захист під час бурі,\n\nКуплет 2\nКоли душі нудьга грозить, - \nМене Спаситель захистить.\nЯк гори встануть на путі - \n«Не бійся!»!- чую я тоді.\n\nКуплет 3\nМій Бог - Отець Небесний мій \nІ захист під час бурі.\nНадійний, вічний і святий \nМій захист під час бурі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1157, 641, 'Осанна', 0, 'Куплет 1\nОсанна, осанна, осанна Царю! (2р.) \nІсуса славте, спів хай лине!\nВін з мерлих встав, і з нами нині!\nХваліть Його - Він Цар царів!\nВін - наш Всесильний Бог!\n\nПриспів: \nАлілуя! Тобі, Ісус, хвала!\nАлілуя! Глорія!\nАлілуя! Тобі лиш слава вся!\nАлілуя! Глорія!\n\nКуплет 2\nО, величай Христа хвалою!\nТворцю воскреслому співай!\nО, величай і прославляй -Він достойний похвали! \nО, величай і прославляй Ім\'я Господа завжди!\nОсанна! Осанна! Осанна Царю! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1158, 642, 'Про РіздвоХристове', 0, 'Куплет 1\nПро Різдво-Христове ангел сповістив, \nІ радісну й нову пісню заспівав:\n«Всі люди радійте, дивну радість сійте \nВ День Різдва святий!»\n\nКуплет 2\nЯ лечу від Бога - радість дати вам: \nУ вертепі вбогім Спас родився нам! \nШвидко поспішайте Хлоп’ятко вітайте, — \nНа землі - спокій,\n\nКуплет 3\nПастухи теж знали, де ясна зоря,\nПрийшли, привітали Бога і Царя. \nБогові співали, дар Цареві склали,\nРаділи Христу.\n\nКуплет 4\nЛюди досі жили у гріхах своїх,\nЗ ними до могили переходив гріх.\nНа Різдво Христове дай життя їм нове,\nЩе й радісних днів.', '', '', 'ua', NULL, 0, NULL, NULL),
(1159, 643, 'Хоче всіх людей Ісус благословить', 0, 'Куплет 1\nХоче всіх людей Ісус благословить, \nВістку добру в серце кожного вселить, \nДвері серця, друже, ти Йому відкрий, \nДасть тобі Ісус спокій.\n\nПриспів: \nІсуса ти впусти, (2р.)\nДвері серця, друже, ти Йому відкрий, \nДасть тобі Ісус спокій.\n\nКуплет 2\nВін прийшов за гріх наш на хресті страждать, \nВоскресінням Своїм перемогу дать.\nДвері серця, друже, ти Йому відкрий,\nДасть тобі Ісус спокій.\n\nКуплет 3\nХодиш ти в темряві, хочеш шлях знайти, \nЗнай, таких, як ти Ісус прийшов спасти. \nДвері серця, друже, ти Йому відкрий.\nДасть тобі Ісус спокій.\n\nКуплет 4\nЛиш щасливий той, хто до Христа прийде,\nВічну радість й щастя він собі знайде.\nДруже, двері серця ти Йому відкрий,\nДасть тобі Ісус спокій.', '', '', 'ua', NULL, 0, NULL, NULL),
(1160, 644, 'По високих горах Пастир мій іде', 0, 'Куплет 1\nПо високих горах Пастир мій іде,\nСтежкою вузькою овець Своїх веде.\n\nПриспів: \nА я маленька овечка йду слідом за Ним \nСтежкою вузькою в місто Єрусалим.\n\nКуплет 2\nВін мій Пастир добрий, тихих любить Він,\nТа не любить гордих, всіх, що роблять гріх.\n\nКуплет 3\n«Я є шлях і правда, істина в житті.\nТи іди за Мною», - каже Він мені.', '', '', 'ua', NULL, 0, NULL, NULL),
(1161, 645, 'Хто створив квіточки', 0, 'Куплет 1\nХто створив квіточки,-.квіточки, квіточки,\nХто створив квіточки? - Отець на небесах!\n\nКуплет 2\nХто створив зірочки, зірочки, зірочки,\nХто створив зірочки? - Отець на небесах !\n\nКуплет 3\nХто створив пташечки, пташечки, пташечки,\nХто створив пташечки?- Отець на небесах!\n\nКуплет 4\nХто створив тебе й мене, тебе й мене, тебе й мене, \nХто створив тебе й мене? - Отець на небесах!\n\nКуплет 5\nХто створив квіточки, зірочки, пташечки,\nХто створив тебе й мене? - Отець на небесах.', '', '', 'ua', NULL, 0, NULL, NULL),
(1162, 646, 'Один будує дім', 0, 'Куплет 1\nОдин будує дім свій на піску. (Зр.)\nІ ось пішли дощі.\n\nКуплет 2\nПішли дощі і ріки розлились. (Зр.)\nІ дім цей не встояв.\n\nКуплет 3\nА другий дім будує на скалі. (Зр.),\nІ ось пішли дощі.\n\nКуплет 4\nПішли дощі і ріки розлились. (Зр.) \nІ дім його встояв.\n\nКуплет 5\nЗбудуй свій дім на камені-Христі, (Зр.)\nІ ві встоїть повік.\n\nКуплет 6\nМолись, щоб Бог тебе благословив, (Зр.)\nІ Він благословить!', '', '', 'ua', NULL, 0, NULL, NULL),
(1163, 647, 'Скоро скоро вже', 0, 'Куплет 1\nСкоро, скоро вже ми побачимо Христа (Зр.)\n Алілуя! Алілуя! Побачимо Христа.\n\nПриспів: \nАлілуя, алілуя! (2р.)\nСльози Він зітре, як побачимо Христа. (Зр.) \nАлілуя! Алілуя! Побачимо Христа.\n\nКуплет 2\nРадість буде там — ми побачимо Христа. (Зр.)\nІ Алілуя! Алілуя! Побачимо Христа.\n\nКуплет 3\nСмерті там нема — ми побачимо Христа. (Зр.) \nАлілуя! Алілуя! Побачимо Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1164, 648, 'Чому сумуєш ти', 0, 'Куплет 1\nЧому сумуєш ти, чому в тузі душа?\nХіба не радісно з Христом тобі?\nМи діти Божі всі щасливі й радісні,\nМи найщасливіші на цій землі.\n\nКуплет 2\nВесною ранньою, душою чистою \nЧому не хочеш славити Творця?\nСпівай хвалу Йому за смерть голгофськую,\nЗа кров пролитую - співай Йому !\n\nКуплет 3\nТи мужнім будь в житті, змагайся з бурями!\nПідтримає тебе завжди Христос.\nБo обіцяв Він нам, що не залишить нас,\nЩо Він ніколи не залишить нас.\n\nКуплет 4\nЗустрінеш в небі ти свого Спасителя, \nХто на хресті простив твої гріхи.\nЛаскаво скаже Він - «До раю увійди,\nСлуга ти вірний Мій - Я Пастир твій!»', '', '', 'ua', NULL, 0, NULL, NULL),
(1165, 649, 'Серцем відчуйте', 0, 'Приспів: \nСерцем відчуйте ласку Господа! \nЩасливий, хто пізнав Його! \nПрийдіть і відчуйте ласку Господа! \nЩасливий, хто пізнав Його.\n\nКуплет 1\nВін є добрий Пастир, Який завжди зі мною є. \nСеред неправди і гріха Його рука трима мене.\n\nКуплет 2\nКоли в печаль і у відчай Його дитя вмить упаде, - \nРятує Він його в біді, любов і ласку подає.\n\nКуплет 3\nНе тільки в дні спокою хвалу я буду віддавать.\nКоли через пітьму я йду,- повинен Голос мій звучать!', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(1166, 650, 'Дух Святий прийди до нас', 0, 'Куплет 1\nДух Святий, прийди до нас, серця наші наповняй,\nЗ нами будь на кожний час і Христа нам відкривай.\n\nПриспів:\nО, величний Дух, прийди! Серця наші наповняй, \nВсіх, хто молить, утішай.	\n(Ждем ми), ждем Тебе ми, о прийди!\nДух Святий, до нас прийди! О, прийди, благаєм всі,\nІ Ісуса відкривай, дивно Бога прославляй!\n\nКуплет 2\nВсе Тобі я віддаю - душу, тіло, розум мій.\nВсе життя і волю всю. Хочу буть навіки Твій.\n\nКуплет 3\nЯ Ісусові віддав би найдорожче все, що мав.\nВін за мене умирав, нам віддав життя Своє.', '', '', 'ua', NULL, 0, NULL, NULL),
(1167, 651, 'Отець Небесний із любовю', 0, 'Куплет 1\nОтець Небесний, із любов\'ю \nЗа все ми дякуєм Тобі!	\nМи Сина Твойого омиті кров\'ю,\nПеред Тобою в благоговінні ми стаєм.\n\nПриспів: \nСлава Всемогутньому Богу! - \nВін був, Він є і знов прийде.\nСлава Всемогутньому Богу навіки віків\n\nКуплет 2\nОтець Небесний, із любов\'ю\nЗа все ми славимо Тебе!\nТи Сина Свойого послав на землю,\nБудемо щиро завжди славити Тебе!', '', '', 'ua', NULL, 0, NULL, NULL),
(1168, 652, 'Небо', 0, 'Куплет 1\nНебо! Небо! О, синєє небо (небо)! \nНебо, оспіване в віршах поетів,\nПро тебе складено безліч сонетів:\nЧистий, безмежний, блакитний простір \nВабить, хто в небо підносить свій зір.\n\nКуплет 2\nА християнам небесна блакить \nЗбільшує віру сердець кожну мить;\nТам наш Ісус, наш Спаситель і Бог \nПриготував нам чудовий чертог.\n\nКуплет 3\nДе вже немає ні смутку, ні горя,\nДе нема сліз, де блаженная доля;\nВічно там сяє Христова краса,\nТак туди лине безсмертна душа.\n\nКуплет 4\nО, які любі оселі Твої,\nВ славному небі всі скарби мої!\nТам мій Спаситель, Небесний Жених \nЖде Свою Церкву - всіх любих Своїх.\n\nКуплет 5\nНебо, відкрий свою правду невірним,\nXто у житті був гріхові покірним, \nХто тішив душу у скарбах земних -  \nСпадщини в небі не буде для них.\n\nКуплет 6\nСховану думку, Затаєний гріх, \nНебо відкриє для поглядів всіх;  \nТам непідкупний Суддя-Божий Син,\nЗвіт віддадуть Йому всі, як один.\n\nКуплет 7\nЧасом буваєш ти сховане в хмари, \nБачимо ми не тебе, а примари.\nАле ми знаєм: відкриєшся знов,\nБо до всіх нас Бог являє Любов\n\nКуплет 8\nБожий народе, чекаючим будь, \nСкоро скінчиться земна твоя путь;  \nВ небо Ісус тебе прийме з Отцем  \nІ увінчає нетлінним вінцем.', '', '', 'ua', NULL, 0, NULL, NULL),
(1169, 653, 'Україно моя', 0, 'Куплет 1\nУкраїно моя, батьків моїх земля,\nКрай прекрасний, чудова земля.\nНародився тут я і впізнав я Христа.\nБог призначив прожить тут мені.\n\nПриспів: \nУкраїно моя, батьків моїх земля!\nТут жили і вмирали батьки.\nТа є краща Країна на небі для нас,\nТам живуть наші близькі, нас ждуть.\nТам нас жде Авраам, і Мойсей, і Павло,\nТам чекає; нас всіх Божий син.\nО, Країно свята - Небеса!\n\nКуплет 2\nЯк прекрасні ліси, як прекрасні річки!\nУкраїнські прекрасні поля.\nТа на Небі ще краща, ще краща земля!\nТам спасенні живуть, як сім\'я.', '', '', 'ua', NULL, 0, NULL, NULL),
(1170, 654, 'Сонечко влітку', 0, 'Куплет 1\nСонечко влітку лагідно сяє,\nТеплим промінням радує нас. \nВипробування, так вже буває,\nНебо закриє для нас.\n\nПриспів: \nХай навіть в кошарі овець не стане \nІ виноград не дасть плода, - \nСлавити не перестану Господа Христа.\n\nКуплет 2\nЯкщо мене закружить, буває,\nВ водовороті марнотного дня, - \nВіра із марноти підіймає,\nЗнову співає душа моя.\n\nКуплет 3\nКоли в житті, буває, щось згубим, - \nСлово Ісуса згадаю в той час:\n“Де ваші скарби - там серце буде”.\nЗгуба тоді не тяжка для нас.\n\nКуплет 4\nКоли життєвий вибір настане, - \nЗадля Ісуса і слави Отця \nВсього позбудусь, скарбів не стане.\nЗнову хай пісня лунає моя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1171, 655, 'Моя оселя', 0, 'Куплет 1\nМоя оселя високо в Небі,\nДе радість буде вже без кінця.\nІ друзі, рідні там будуть з нами \nСпівати пісні там у Отця.\n\nКуплет 2\nОселя рідна! Там хочу бути.\nТуди бажаю, щоб відпочить.\nТам буду Бога я вічно славить \nІ в сяйві Неба Христу служить.\n\nКуплет 3\nЯк в бурю з моря моряк прямує \nПриплисти в Гавань, щоб відпочить,\nТак прагну серцем в Оселі Світла,\nДе відпочинок для всіх святих.\n\nКуплет 4\nВідрадно буде в тім Вічнім Домі, \nПобачу Спаса лицем в лице.\nВін на Голгофі страждав за гріх мій, \nЩоб примирити з Отцем мене.', '', '', 'ua', NULL, 0, NULL, NULL),
(1172, 656, 'Як тяжкий був гріховний шлях', 0, 'Куплет 1\nЯк тяжкий був гріховний шлях, яким то я ішов.\nЛишив Спас славу в небесах, - мене спасти прийшов.\n\nПриспів:\nТепер співаю серцем я: Христос - Спаситель мій.  \nХай пісня все звучить моя. Він дав мені спокій.\n\nКуплет 2\nХристос з гріхів мене обмив в святій Крові Своїй. \nНавіки Він мене звільнив і дав душі спокій.\n\nКуплет 3\nВізьме мене з Собою Він в Небесну Вітчизну.\nТам радісно душею я навіки з Ним спічну.\n\nПриспів:\nТоді співати буду я: Христос - Спаситель мій.\nІ пісня зазвучить моя. Він дав мені спокій.', '', '', 'ua', NULL, 0, NULL, NULL),
(1173, 657, 'Нива моя', 0, 'Куплет 1\nЯ в поле вийшов на світанку, коли ще люд спокійно спав, \nНа самоті осіннім ранком своє минуле пригадав.\nВ полоні мрій мені здавалось - я слухав старий передзвін. \nПереді мною свідки встали - діла моїх прожитих днів.\n\nПриспів: \nЯк згадаю восени безтурботні дні весни.\nПоле моє, нива моя! Чим засіяна вона?\n\nКуплет 2\nЖенці зібрати поспішали свій урожай, своє зерно,\nА поруч смужечка лежала та шелестіла бур’яном. \nТак боляче на серці стало, що мимоволі плакав я.\n\"О, Боже мій, - вуста шептали, - Прости! - Це ж\n смужечка моя\".\n\nКуплет 3\nЯ вдячний Богові сердечно, що Він в кінці осінніх днів \nМої гріхи, мою безпечність безмірній милості простив. \nЯ буду ниву засівати зерном добірним, не пустим,\nЩоб день великої відплати мене зненацька не', '', '', 'ua', NULL, 0, NULL, NULL),
(1174, 658, 'Памятай Господні щедроти', 0, 'Куплет 1\nКоли бурі над твоїм життям ревуть,\nБолить серце, скорбні очі сльози ллють, -\nЛаску і любов Господню пригадай,\nСміло йди вперед, надії не втрачай.\n\nПриспів: \nЛаску і любов Господню пригадай, \nСміло йди вперед, надії не втрачай.\nПригадай: Він грішних полюбив. \nДивуватись будеш, що Він нам вчинив.\n\nКуплет 2\nКоли тяжке горе на душі лежить, \nСерце сум сповив глибокий, тяжко жить,- \nЛаску і любов Господню пригадай — \nСерце проясніє, зникне сум, відчай.\n\nКуплет 3\nНа Христа дивися та Його благай.\nПісля сліз та горя ввійдеш в Божий Край. \nЛаску і любов Господню не забудь.\nБурі та страждання наші всі минуть.', '', '', 'ua', NULL, 0, NULL, NULL),
(1175, 659, 'Блудний син', 30, 'Куплет 1\nСтеп широкий розстелився Ген до небокраю.\nПоміж трав посохлих вітер гірко завиває.\nСонце випалило степ, ні води краплини.\nПо степу юнак іде в латаній свитині.\n\nПриспів:\nДоле ж моя, доле, що ж мені діяти?\nЯк прийти до батька в дім? Що йому сказати? \nДоле ж моя, доле, розстелися степом. \nХто ж мене такого знов додому прийме?\n\nКуплет 2\nЛишив батька, лишив дім, лишив рідну Неньку.\nПоміняв на гірку воду матінку стареньку.\nБоже! Що я наробив у ту лиху годину?!\nІ рознісся степом крик блудної дитини.\n\nКуплет 3\nСкільки горя, скільки сліз зазнав на чужині! \nПрости, батьку, тяжкий гріх ти своїй дитині. \nСерце кров’ю облилось у старого батька.\nСльози щастя на очах: - Я ж бо сина бачу!\n\nПриспів: \nСину, рідний сину, ти ж моя дитина!\nКращі шати одягни, скинь стару свитину. \nСину, рідний сину, ти ж моя дитина! \nОбійму міцніше, я забуду провину.', '', '', 'ua', NULL, 0, NULL, NULL),
(1176, 660, 'Як закінчиться мій труд', 0, 'Куплет 1\nЯк закінчиться мій труд на землі,\nСпокій на небі Христос дасть мені.\nВічно там буду я з Ним пробувать \nІ дивну славу Його споглядать.\n\nПриспів: \nВ славу Свою прийме мене, (2р.)\nБуду Христа вічно я споглядать.\nВ славу Свою прийме мене.\n\nКуплет 2\nТам приготовлене в домі Отця  \nМісце для мене любов\'ю Христа.\nЩо то за радість у Нім пробувать \nІ дивну славу Його споглядать!\n\nКуплет 3\nТам, у небесних оселях святих,\nРідних і друзів зустріну своїх..\nРазом там будемо пісню співать .\nІ вічно славу Христа споглядать!', '', '', 'ua', NULL, 0, NULL, NULL),
(1177, 661, 'Щиро вітаємо', 0, 'Куплет 1\nЩиро вітаємо, друзі, вас нині\nІ відкриваємо наші серця.\nВи не чужі нам, ви близькі, ви рідні,\nБо одного всі ми діти Отця.\n\nПриспів: \nВ братній любові вас щиро вітаєм.\nВ наших серцях торжество, торжество.\nБогові нашому славу складаєм \nЗа ці відвідини Церкви Його.\n\nКуплет 2\nНам розкажіть, як з безодні страшної \nВ час небезпечний вас Бог врятував,  \nЯк Він повів вас рукою міцною,\nЯк дивне слово “Спасенний” сказав.\n\nКуплет 3\nНам розкажіть, як в місцевості вашій\nБог дарування Свої вам давав, 	\nЯк доброту ви пили з Його чаші,\nЯк вас любов’ю Христос оживляв.\n\nКуплет 4\nЯк через слово Євангельське чисте \nВін промовляв вам до серця нераз.\nВсі заспіваймо, брати, урочисто.\nТой самий Бог і у вас, і у нас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1178, 662, 'Тємної ночі зорі засяли', 0, 'Куплет 1\nТємної ночі зорі засяли,\nАнгели людям радість звіщали:\nУ Вифлеємі, в стайні на сіні \nХристос родився всім на спасіння.\n\nПриспів: \nХристос родився! (Зр.) Всім на спасіння.\n\nКуплет 2\nЛюди, радійте, Христа вітайте,\nБожому Сину славу віддайте! \nУ Вифлеємі, в стайні на сіні \nХристос родився всім на спасіння.\n\nКуплет 3\nСлава у небі Богу святому,\nНа землі спокій роду людському!\nУ Вифлеємі, в стайні на сіні \nХристос родився всім на спасіння.', '', '', 'ua', NULL, 0, NULL, NULL),
(1179, 663, 'Ой над Вифлеємом тихо зорі сяють', 0, 'Куплет 1\nОй, над Вифлеємом тихо зорі сяють.\nВід кого ж це люди двері зачиняють? (2р.)\n\nКуплет 2\nНе хотять прийняти до своєї хати \nІсусову Мати, щоб поночувати. (2р.)\n\nКуплет 3\nСтомлена Марія вже не має сили,  \nТа іде в стаєнку, мов би до хатинки! (2р.)\n\nКуплет 4\nУ стаєнці бідній Христос ся рождає,\nДо своєї неньки ручки простягає.(2р.)\n\nКуплет 5\nАнгели співають, Спаса величають.\nПастухи вітають, радість нам звіщають. (2р.)\n\nКуплет 6\nТож ми разом нині будемо співати \nІ Христа святого завжди прославляти. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1180, 664, 'Спи Ісусе спи', 0, 'Куплет 1\nСпи, Ісусе, спи, спатоньки ходи.\nБуду Тебе колисати,\nПісеньками присипляти. \nСпи, Ісусе, спи маленький, люлі, люлі.\n\nКуплет 2\nСпи, Ісусе, спи, очка зажмури.\nНе питай, що колись буде,\nЩо зготовлять Тобі люди.\nСпи, Ісусе, спи маленький, люлі; люлі.\n\nКуплет 3\nСпи, Ісусе, спи, головку склони\nТи на рученьки Марії,\nБач, вона Тебе леліє.\nСпи, Ісусе, спи маленький, люлі, люлі.\n\nКуплет 4\nСпи, Ісусе, спи, а серце втворй, \nХай при ньому спочиваю \nТут, на землі, і там, в раю.\nСпи, Ісусе, спи маленький, люлі, люлі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1181, 665, 'Зірка засіяла в небі України', 0, 'Куплет 1\nЗірка засіяла в небі України,\nДовгожданну волю принесла.\nЦе нам подарунок Божої Дитини,\nЦе Господня ласка нам зійшла.\n\nКуплет 2\nВисихають сльози матері-Вкраїни,\nВже не чути стогону землі.\nПоклонімся щиро у Божій Святині,  \nЩо пропала нечисть десь в імлі.\n\nКуплет 3\nНенько-Україно, навернись до Бога!\nСвій народ до нього поведи - \nІ зло не досягне нашого порога,	\nВін заступить Край наш від біди.\n\nКуплет 4\nО, Ісусе милий! - молиться Вкраїна, \nНайщирішу вдячність воздає:\n“О, Дитятко Боже, як Бог і Людина, \nЇй благословіння дай Своє”.', '', '', 'ua', NULL, 0, NULL, NULL),
(1182, 666, 'Про благодатну долю України', 0, 'Куплет 1\nПро благодатну долю України,\nПро щиру єдність, віру та любов,\nПро щастя й спокій кожної родини,\nБоже, звертаємось до Тебе знов.\n\nКуплет 2\nЯскравим світлом Слово Твоє сяє.\nЦим Світлом наш народ Ти просвіти.\nІ наше хай життя відображає \nТвій славний образ миру й доброти.\n\nКуплет 3\nДай, Боже, спокій нашій Батьківщині.\nТвоє дай Царство світле нам в серця,\nЩоб ми жили Твоїм благословінням \nІ вірними лишались до кінця.', '', '', 'ua', NULL, 0, NULL, NULL),
(1183, 667, 'Боже славимо Тебе', 0, 'Куплет 1\nБоже, славимо Тебе і хвалу Тобі приносим.\nМи співаємо Тобі і серця свої підносим!\nВ цей святий молитви час величаєм, Царю наш!\n\nКуплет 2\nДуші праведних святих, сонми сил Твоїх небесних \nСлавлять велич діл Твоїх, діл великих і чудесних. \nСлавлять Бога і Отця - Вседержителя Творця!\n\nКуплет 3\nТвоє Ім\'я на землі Церква щиро прославляє. \nЗаповіти всі Твої і шанує, і сповняє.\nГідний слави, Боже, Ти і любові Повноти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1184, 668, 'Блукав я в далекій чужій стороні', 0, 'Куплет 1\nБлукав я в далекій, чужій стороні,  \nІ сонце сховалось від мене.  \nНебесний Отець не забув за мене, \nЗ висока дивився на мене.\n\nКуплет 2\nІ тіло моє, ненаситне гріха,\nВ світських похотях потопало \nІ чув я чийсь голос, до мене Він звав.\nІ душа моя чогось-то бажала.\n\nКуплет 3\nДо Отця вернутись тепер я не смію.\nІ серце в великій тривозі,\nТому що блудив я в далекій стороні,\nНіколи не думав про Бога.\n\nКуплет 4\nІ, вставши, піду я до свого Отця,\nІ скажу Йому: \"Согрішив я!\nЯ вже недостоєн Твоїм сином зватись,\nТо хоч за наймита прийми мене\".', '', '', 'ua', NULL, 0, NULL, NULL),
(1185, 669, 'Кожний спрагнений іди та пий', 0, 'Куплет 1\nКожний спрагнений, іди та пий !\nІз джерела Води Життя,\nХто любить Сина, хто вірить в Сина,\nТвоє життя цілком обновить Він.\n\nПриспів: \nАлілуя! Тобі хвала! (Зр.)\nАлілуя! Тобі, Ісус, хвала !!\n\nКуплет 2\nЯкщо ти знеміг, нема сил іти,\nВін поміч дасть на шляху земнім —\nТягарі знімає, сили відновляє,\nЗ усіх нещасть Він визволить тебе.\n\nКуплет 3\nТи проси вогню, і Він дасть тобі,\nСтанеш радісний і вперед підеш,\nЛиш Йому довірся, на Христа надійся,\nТвоє життя цілком обновить Він.', '', '', 'ua', NULL, 6, '2020-10-25', NULL),
(1186, 670, 'Ви води озера Генісаретського', 0, 'Куплет 1\nВи, води озера Генісаретського, \nВ хвилях криштальних своїх\nОбраз відбили Христа Назаретського,\nРис Його дивних, святих.\n\nКуплет 2\nНині Він Духом Святим поселяється \nТихо у наших серцях.\nЧом же виразно в них не відбивається.\nТак, як колись у водах?\n\nКуплет 3\nМоже серця вкрились хмарами кволості,\nМоже схвильовані чим?\nАбо нема в наших душах прозорості,\nЩо ми не світимо всім?\n\nКуплет 4\nХай будуть душі й серця наші чистими,\nХай зникне з них марнота!\nВ нас відіб\'ється тоді променистими \nРисами образ Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1187, 671, 'Господи як дивно', 0, 'Куплет 1\nГосподи, як дивно, що я жив, Тебе не знаючи.\nЖив без кохання, без благословення з уст Твоїх.\nА нині я з Тобою, я в сім\'ї Твоїх дітей, -\nЗа це благословляти хочу Бога, хочу прославляти Бога.\n\nПриспів:\nСлав те, слав те Бога! Прославляйте Бога\nВce більше день за днем. Слав те, слав те Бога! Прославляйте Бога. В серці своїм.\n\n\nКуплет 2\nГосподи, як дивно, Ти прийшов- життя змінилось\nВсе засяяло навколо світлом дивним неземним\nІ нині заспіваю я хвалу і поклоніння\nПеред величчю Твоєю і Твоїм лицем\n\nКуплет 3', '', '', 'ua', NULL, 3, '2021-04-01', NULL),
(1188, 672, 'Боже славлю я Тебе', 0, 'Куплет 1\nБоже, славлю я Тебе навік! Славлю я Тебе навік!\nБo Твоє Ім\'я прекрасне в похвалі.\n\nКуплет 2\nВозвеличую Тебе навік! Славлю я Тебе навік!\nБо Твоє Ім\'я прекрасне в похвалі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1189, 674, 'Ісус Імя величне', 0, 'Куплет 1\nІсус - Ім\'я величне!\nДивний Спаситель, славний Господь!\nЕммануїл - Бог вічно з нами!\nНаш Визволитель! Славний Господь', '', '', 'ua', NULL, 0, NULL, NULL),
(1190, 675, 'Ми єдині в любові Христа', 0, 'Куплет 1\nМи єдині в любові Христа, ми єдині в любові Його\nСтав єдиний наш дух з Духом Божим Святим,\nМи єдині в любові Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1191, 677, 'Я благословляю тебе', 0, 'Куплет 1\nЯ благословляю тебе вічним Іменем Ісуса.\nМир, радість і любов від Господа душі твоїй.\nАлілуя, алілуя! Алілуя, алілуя!', '', '', 'ua', NULL, 0, NULL, NULL),
(1192, 678, 'Лиш на Христа надіюсь я', 0, 'Куплет 1\nЛиш на Христа надіюсь я,\nБо джерело моєї слави - Його хрест,\nІ кожний день життя хочу сказати я:\n“Лиш на Христа, лиш на Христа надіюсь я”.', '', '', 'ua', NULL, 0, NULL, NULL),
(1193, 679, 'Ми знову зібрались сюди', 0, 'Куплет 1\nМи знову зібрались сюди та й цю пісню співаєм.\nЦе пісня про нове життя, яке у Христі ми маєм.\n\nПриспів:\nНове життя, чудне нове життя!\nПовне світла, любові і тепла.\nНове життя, зовсім нове життя В Ісусі маєм ти і я.\n\nКуплет 2\nО друже, до Бога прийди! Він любить тебе і чекає.\nВін вічність дарує тобі, з тобою зустрітись бажає.', '', '', 'ua', NULL, 0, NULL, NULL),
(1194, 680, 'За Голгофу за кров', 0, 'Куплет 1\nЗа Голгофу, за кров - дякую Тобі, Господь, \nЗа воскресіння Твоє, за перемогу Твою –\nЯ дякую Тобі, Ісус! (Зр.) За все Тобі я дякую! (Зр.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1195, 681, 'В Тобі моя сила', 0, 'Куплет 1\nВ Тобі моя сила, в Тобі моя радість!\nВ Тобі є надія, в Тобі, мій Господь!\n\nКуплет 2\nВсю славу Тобі віддаю,  Тебе лиш одного хвалю. \nТи - сила моя! Ти - радість моя!\nГосподь, Ти є моє життя', '', '', 'ua', NULL, 0, NULL, NULL),
(1196, 682, 'Шукайте перше Царства Божого', 0, 'Куплет 1\nШукайте перше Царства Божого і правди Його,\nА усе інше буде дано вам. Алілуя! Алілуя!\n\nКуплет 2\nЦарство Небесне - не їжа і пиття,\nА праведність, і мир, і радість у Дусі Святім. \nАлілуя! Алілуя!', '', '', 'ua', NULL, 0, NULL, NULL),
(1197, 683, 'Я просто хочу бути там де Ти', 0, 'Куплет 1\nЯ просто хочу бути там, де Ти,\nМандрувати за Тобою,\nМолитви не з відстані нести.\nВізьми мене туди, де Ти.\n\nКуплет 2 \nХочу бути там, де Ти є,\nНавіки з Тобою поруч.\nВізьми мене туди, де Ти є.\nЯ просто хочу жити там.\n\nКуплет 3\nЯ хочу бути поруч, навіки з Тобою,\nЗа столом сидіти в сяйві Твоєї слави, - \nБіля Тебе, я хочу завжди бути там,\nХочу бути там, хочу бути там, де Ти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1198, 684, 'Мій Бог великий Бог', 0, 'Куплет 1\nМій Бог — великий Бог!\nСлавити хочу Його кожним словом. \nРівних Йому нема в славі,\nІ милість Його не знає кінця.\n\nПриспів:\nЗемля і небеса возвеличують славу Його.\nАнгелів ніжні слова промовляють, що Бог є любов.\nМій Бог — могутність, рятунок й фортеця моя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1199, 685, 'Господь твій Бог', 0, 'Куплет 1\nГосподь твій Бог з тобою є. Могутній, могутній.\nХай славлять всі Його Ім’я \nВ силі, у славі і в радості.\nКерує хай тобою Він навіки і віки. Амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(1200, 686, 'Господеві заспіваймо', 0, 'Куплет 1\nГосподеві заспіваймо, Господу співай, вся земля.(2р.)\nВеликий Бог, достойний слави Він! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1201, 687, 'Хто скажіть кращим є', 0, 'Куплет 1\nХто, скажіть, кращим є? Хто, скажіть, дивом є?\nЦар царів, Божий Син. Чи не Він? Чи не Він?\n\nКуплет 2\nЧи не Він вмер за нас? Вмер за нас чи не Він?\nНа хресті життя віддав чи не Він? Чи не Він?\n\nКуплет 3\nЧи не Він знов воскрес? Знов воскрес чи не Він?\nДав життя, благословив. Чи не Він? Чи не Він?', '', '', 'ua', NULL, 0, NULL, NULL),
(1202, 688, 'Я люблю тебе любов’ю Христа', 0, 'Куплет 1\nЯ люблю тебе любов’ю Христа! (2р.)\nІ в твоїх очах горить любов свята.\nЯ люблю тебе любов’ю Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1203, 689, 'Творець усіх небес', 0, 'Куплет 1\nТворець усіх небес, Який створив весь світ, \nНайбільше чудо Ти звершив мені:\nНебесним Духом Ти зростив в мені Свій плід - \nЛюбов, і нею я служу Тобі.\n\nПриспів:\nТобі, Господь, моя молитва лине\nВ словах сердечних і сльозах.\nТобі, Господь, моя найкраща пісня \nБринить благоговійно на устах.\n\nКуплет 2\nТворець усіх небес, Який створив весь світ,\nЛице Твоє освітить темну ніч,\nЯк я знайшов Тебе і заключив завіт,\nЗ Тобою люблю бути віч-на-віч.', '', '', 'ua', NULL, 0, NULL, NULL),
(1204, 690, 'Ти моя сила у житті', 0, 'Куплет 1\nТи — моя сила у житті, Ти є та ціль, куди я йду,\nТи є для мене все! Ти є той скарб, що я шукав,\nТи є Господь мого життя, Ти є для мене все!\n\nПриспів:\nІсус - мій Господь! Славлю я Тебе! (2р.)\n\nКуплет 2\nТи взяв мій гріх, мій хрест, мій біль,\nЗнову підняв мене, я — Твій! \nТи є для мене все! \nКоли є спека, - Ти є тінь,\nКоли я прагну, - Ти - вода.\nТи є для мене все!\n\nКуплет 3\nТи на Голгофі вмер за нас,\nАле воскрес і людство спас,\nТи для мене - все!\nТи воскресіння і життя,\nІ лиш до Тебе прагну я,\nТи для мене - все!', '', '', 'ua', NULL, 7, '2021-01-13', NULL),
(1205, 691, 'Скеля мого рятунку', 0, 'Куплет 1\nСкеля мого порятунку Ти є, сила мого Ти життя.\nТи благодаттю даєш спасіння,\nДо Тебе молитва моя.\n\nКуплет 2\nВ Тебе вірую, я вірую! Бо Ти любиш так мене. \nДаєш поміч Ти у час важкий.\nВірним залишусь Тобі!', '', '', 'ua', NULL, 0, NULL, NULL),
(1206, 692, 'Богу співайте Алілуя', 0, 'Куплет 1\nБогу співайте \"Алілуя!\" (2р.)\nБогу співайте, (Зр.) \"Алілуя!\"\nСлавте Його в своїх серцях...\nВ Бозі надія Тобі є...\n\nКуплет 2\nВірою всі прийміть Христа...\nРадуйтесь в Господі завжди...\nВін нам дарує благодать...\nВін С шлях, істина й життя...', '', '', 'ua', NULL, 0, NULL, NULL),
(1207, 693, 'Співай Господу вся земля', 0, 'Куплет 1\nСпівай Господу, вся земля!\nПро спасіння Його говори!\nЙoroчудеса і слава сповіщаються по всій землі.\n\nКуплет 2\nВеликий Господь - сильний і могутній!\nРадій, радій! Бо наш Бог царює!', '', '', 'ua', NULL, 0, NULL, NULL),
(1208, 694, 'Моя молитва нехай лине', 0, 'Куплет 1\nМоя молитва нехай лине \nДо Тебе, наче фіміам;\nІ серце лине безупинно \nВ чудовий Твій небесний храм.\n\nПриспів:\nБоже, я молю за Україну,\nБоже, молю Тебе за людей:\nТи їх прости, Ти їх спаси і милість Свою нам яви.\nБоже, я знаю, що Ти будеш з нами \nВ храмі Своєму під небесами,\nРадість і мир Ти дарував, життя за людей віддав,\nВ Книгу Життя нас записав.\n\nКуплет 2\nВ Своєму слові живому \nТи для людей спасіння дав,\nЩоб люди всі молились Тому,\nХто на хресті за них вмирав.', '', '', 'ua', NULL, 0, NULL, NULL),
(1209, 695, 'О який же то Приятель', 0, 'Куплет 1\nО, який же то Приятель Ісус щирий є для нас!\nВін гріхи забрав на Себе наші і увільнив нас.\nЯк же часто без потреби болі й нужду терпимо \nЧерез те, що їх в молитві Богові не несемо.\n\nКуплет 2\nЧи то в спробі, чи в спокусі, чи де клопіт є в житті,\nЩиро Богові в молитві розкажіть нужду свою.\nЧи є вірніший друг, як Спас? Хто б нам в смутку співчував? \nІсус нашу неміч знає і в житті поможе нам.\n\nКуплет 3\nЧи ви хворі, обтяжені, чи журба валить вас з ніг,- \nІсус нашим є притулком. Просіть, щоб Він вам поміг.\nЧи тебе твій друг покинув,-Господу скажи про це!\nІсус другом твоїм буде, й не залишить Бог тебе.', '', '', 'ua', NULL, 0, NULL, NULL),
(1210, 696, 'Хай радіють всі вірні', 0, 'Куплет 1\nХай радіють всі вірні в Христі,\nДана радість усім нам в житті.\nНаш Ісус з мертвих встав, нам із неба послав \nДуха, що потішає в житті.\n\nКуплет 2\nХай співають щасливі серця,\nПісня слави дзвенить без кінця. \nНе сумує нехай, не впадає в відчай \nВірить хто в ласку Бога-Творця.\n\nКуплет 3\nТож довірся Йому, друже, й ти,\nБо провадить Він нас до мети.\nНа шляху до небес, до країни чудес \nЛегко з Ним і приємно іти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1211, 697, 'Коли хвилювання і сум', 0, 'Куплет 1\nКоли хвилювання і сум надійдуть,\nСвій зір підійми в небеса, \nДепресія й страх твою душу гризуть - \nСвій зір підійми в небеса.\n\nПриспів:\nБог є добрий, поміч в Нім,\nСила в могутніх руках.\n\nКуплет 2\nКоли твій розбитий човен сів на міль,\nСвій зір підійми в небеса,\nЗагрожують тілу хвороби і біль - \nСвій зір підійми в небеса.\n\nКуплет 3\nНаповнений страхом перед майбуттям - \nСвій зір підійми в небеса,\nГосподь смерть і тління замінить життям - \nСвій зір підійми в небеса.', '', '', 'ua', NULL, 0, NULL, NULL),
(1212, 698, 'Радісний той день', 0, 'Куплет 1\nРадісний той день, (2р.) що Господь нам дав. (2р.) \nВеселімось всі (2р.) у Ісусі Христі. (2р.)\nРадісний той день, що Господь нам дав.(2р.) \nВеселімось всі (2р.) у Ісусі Христі. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1213, 699, 'Прийди Дух Святий', 0, 'Приспів:\nПрийди, Дух Святий, я чекаю!\nЯ так потребую Тебе!\nПрийди в Твоїй силі і владі.\nПрийди, Дух Святий, я молю!\n\nКуплет 1\nПодай для душі відпочинок,\nПодай Ти для хворих бальзам!\nПрийди, як роса світанкова,\nПрийди у сердечний мій храм!\n\nКуплет 2\nВідкрий джерело нам в пустелі,\nІ спраглим Ти дух оживляй!\nТвоя ізціляюча сила\nХай сповнить мене через край!', '', '', 'ua', NULL, 1, '2021-01-31', NULL),
(1214, 700, 'Я прийду вже Шумні води не', 0, 'Куплет 1\nЯ прийду вже скоро за тобою,\nІ візьму тебе Я в небеса,\nЯ купив тебе ціною крові,\nВірная голубонько Моя!\n\nПриспів:\nШумні води не згасять любові,\nРіки світу не заллють її,\nЯ купив тебе ціною крові \nВ муках і стражданнях на хресті.\n\nКуплет 2\nДень весілля скоро наступає \nВ небі приготовлений тобі,\nТам Єрусалим тебе чекає,\nБудь до смерті вірная Мені!\n\nКуплет 3\nСкоро сурми голос залунає,\nВсі почують надзвичайний крик,\nСуд гряде над грішною землею - \nТи ж готова будь у кожну мить!', '', '', 'ua', NULL, 2, '2020-07-05', NULL),
(1215, 701, 'О як довго Закхей', 0, 'Куплет 1\nО, як довго Закхей щастя в світі шукав,\nТа знайшов лиш тоді, як побачив Христа.\n\nПриспів:\nПропустіте його, пропустіть наперед!\nХоче бачити він Ісуса Христа!\n\nКуплет 2\nДуже швидко Закхей зрозумів ці слова,\nЩо Христос говорив: \"Йду до дому твого\".\n\nПриспів:\nПропустіте мене, пропустіть наперед!\nХочу бачити я Ісуса Христа!\n\nКуплет 3\nЯк з Христом говорив, став Закхей і сказав: \n\"Кому кривду вчинив, - вчетверо я віддам!\"\n\nКуплет 4\nДруже мій, як Закхей, до Христа поспіши,\nВ Ньому радість знайдеш, лиш життя все віддай.\n\nКуплет 5\nІ побачиш Христа, вчуєш голос Його: \n\"Заспокойся, душе, - йду до дому твого!\"', '', '', 'ua', NULL, 0, NULL, NULL),
(1216, 702, 'Чого баришся сину', 0, 'Куплет 1\nЧого баришся, сину, в далекій чужині?\nЧому не йдеш додому, що в рідній стороні?\nТам твій Отець сумує і часто сльози ллє:\n“Чому не видно сина? Чом довго так не йде?”\n\nКуплет 2\nГоре тебе спіткало і щастя вже нема,\nДрузі в біді лишили, в серці тяжка пітьма.\nВ домі Отця є світло, темряви там нема,  \nТам щастя, радість, воля, там вся твоя рідня!\n\nКуплет 3\nХоч тобі є соромно і совість не мовчить,\nЩо вдіяв так недобре,- чи ж можна все простить? \nХоч і тяжке падіння, велика та вина,\nЛюбить тебе Отець твій, в Нім спадщина Твоя!', '', '', 'ua', NULL, 0, NULL, NULL),
(1217, 703, 'Луги й поля квітками вкрились', 0, 'Куплет 1\nЛуги й поля квітками пишно вкрились,\nВесни несеться всюди аромат,\nУся краса природи пробудилась,\nА люди ще в гріхах так міцно сплять. (2р.)\n\nКуплет 2\nУсяка квітка до світла стремиться,\nУсяка травка теж чує тепло,\nА світ з гріха не може пробудитись, \nВесни для них неначе б не було. (2р.)\n\nКуплет 3\nПташки здалека знову повертають,\nКалендаря не мають, знають час.\nНехай вони всім людям пригадають:\nПрийшла весна, - усіх Бог кличе вас. (2р.)\n\nКуплет 4\nПо всіх кінцях вже світить Боже Слово \nІ ніжно гріє всіх Його любов.\nЧому даєте ви життя для злого?\nХристос пролив за вас святую Кров. (2р.)\n\nКуплет 5\nУже давно настало Боже літо.\nДень благодаті нині іще є.\nСпіши до Спаса, щоб ти був одітий\nУ праведність, яку Христос дає. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1218, 704, 'Хоч я бідний нещасний родився', 0, 'Куплет 1\nХоч я бідний, нещасний родився \nІ в цім світі гріха я страждав,\nАле радий став, як зрозумів я,\nЩо з Христом є найкраще життя (2р.)\n\nПриспів:\nО, щоб світ міг пізнати те щастя,\nЩо з Христом є найкраще життя (2р.)\n\nКуплет 2\nЦей загиблий світ нині віддався,\nЩоби йти лиш дорогою зла.\nІ не знає, що скоро вже прийде \nТой великий, страшний день суда.\n\nКуплет 3\nТоді будуть зі страхом стояти \nПеред Божим престолом вони.\nІ почують той вирок прокляття:\nВідійдіть в огонь вічний всі ви!', '', '', 'ua', NULL, 0, NULL, NULL),
(1219, 705, 'Наші дні немов птах', 0, 'Куплет 1\nНаші дні немов птах пролітають так швидко,\nНе вернути тепер їх назад.\nСкільки горя і сліз пережив ти, мій друже,\nБез Ісуса у світі ти йдеш.\n\nПриспів:\nТа Ісус простягнув Свою руку до тебе,\nПоміч дасть Він тобі на земному шляху.\nТи звернися до Нього, мій друже, в молитві,- \nБуде радість і спокій у серці завжди.\n\nКуплет 2\nПодивись на чоло, - воно вкрите лиш терном, \nКраплі крові течуть по лиці.\nСкільки болю й терпінь на горі тій Голгофі,\nЩоб тобі двері раю відкрить.\n\nКуплет 3\nДруже мій, що даси ти за подвиг цей хресний? \nЗа ту кров, що текла за твій гріх?\nТи схилися до Нього в сердечній молитві, - \nСпокій вічний тобі Він приніс.', '', '', 'ua', NULL, 0, NULL, NULL),
(1220, 706, 'Самарянка та не знала', 0, 'Куплет 1\nСамарянка та не знала, що Христос її шукав,\nКоли воду вона брала й пити Він її прохав.\nІ ось Він їй відкриває, як колись вона жила,\nНемов з книги Він читає, ким вона була.\n\nПриспів:\nО, довірся, милий друже, бо Спаситель тебе жде,\nІ не будь такий байдужий, бо ж Він відійде.\n\nКуплет 2\nУ тривозі, мов від дива, від криниці до своїх \nПоспішає - нещасливих сповістити всіх,\nЩо якась свята Людина в самарійський край зайшла, \nЙ що спасіння вже година для них надійшла.\n\nКуплет 3\nІ тепер вода живая ллється в Бога для людей,\nВсім сумним Він витирає сльози з їх очей.\nВ цьому світі Він шукає безталанних, щоб спасти.\nНад криницею чекає, щоб прийшов і ти.', '', '', 'ua', NULL, 0, NULL, NULL),
(1221, 707, 'В далекі часи минулі часи', 0, 'Куплет 1\nВ далекі часи, минулі часи в краю Палестині \nЗ’явилась зоря небесна, вона і сяє донині.\nТо світло для нас приніс любий Спас,\nІ хто хоче взяти - даремно бери,\nТо будеш і ти яскраво палати.\n\nПриспів:\nДо Христа, до Христа поспіши.\nПеред Спасом коліна схили.\nНі дарів, ні скарбів Він не жде.\nСину, серце дай нині своє.\n\nКуплет 2\nВ блуканнях моїх нещасних доріг чимало пройшов я. \nТа щастя не мав, коли пропадав далеко від Бога.\nТа ласка Царя, Ісуса Христа,\nВказала дорогу, щоб міг я прийти,\nСпасіння знайти у Бога Святого.\n\nКуплет 3\nСьогодні ще раз лунає для вас ця вістка чудова, \nБлаженство знайдеш, коли ти прийдеш до Бога Святого.\nТо ж, друже, спіши,\nСкоріше прийми Спасіння Христове.\nСьогодні прийди, одержиш і ти життя зовсім нове.', '', '', 'ua', NULL, 2, '2021-01-06', NULL),
(1222, 708, 'Вечірні тіні скрізь лягають', 0, 'Куплет 1\nВечірні тіні скрізь лягають\nІ закривають світлу путь.\nНа серці сумно, я благаю: \n“Спасителю, зі мною будь!”\n\nКуплет 2\nМій шлях далекий, через гори, \nЗемні страждання мене ждуть.\nІ скажуть люди: \"Люте горе! \nСпасителю, зі мною будь!”\n\nКуплет 3\nЗ Тобою я щасливий всюди,\nЗ Тобою завжди хочу йти.\nНа цій землі нещасні люди, - \n“О, Спасе, будь зі мною Ти!”\n\nКуплет 4\nВечірні тіні скрізь лягають \nТа вірю: світлі дні прийдуть!\nВ годину сліз Тебе благаю: \n“Спасителю, зі мною будь!”', '', '', 'ua', NULL, 0, NULL, NULL),
(1223, 709, 'Коли молюся я до Бога', 0, 'Куплет 1\nКоли молюся я до Бога,\nМолитва тиха, як зоря,\nТо голосна, коли тривога, - \nГорить в мені і не згора.\n\nКуплет 2\nВона, як полум\'я любові,\nХолодну душу зігріва,\nЗніма журбу, тамує болі,\nГріхом залишені бува.\n\nКуплет 3\nМоя молитва - то не відчай \nПеред сльозою самоти,\nВона мене у вічність кличе \nВід справ земних і суєти.\n\nКуплет 4\nКоли буваю я свавільний,\nЧи просто гордий у житті, - \nВона, молитва, неодмінно \nНе дасть зійти мені з путі.\n\nКуплет 5\nМоя молитва в час осінній,\nКоли на скронях сивина, \nЖива надія на спасіння - \nОдним-одна, одним-одна.\n\nКуплет 6\nНехай звучить вона недовго,\nВсього два слова, і не більш,\nТа все одно єднає з Богом,\nПриносить мир душі моїй.', '', '', 'ua', NULL, 0, NULL, NULL),
(1224, 710, 'Ти навчи мене мій Господь', 0, 'Куплет 1\nТи навчи мене, мій Господь, у всім\nВолю виповнять лиш Твою,\nЩоб мені за Словом Твоїм довести,\nЩо Тебе я, Спаситель, люблю.\n\nПриспів:\nТи навчи мене серед тисячі\nГолос чути лиш Твій,\nТи навчи мене за Тобою йти \nВ край бажанний, дорогий.\n\nКуплет 2\nТи навчи мене в грішнім світі жить,\nЩоби світло сіяло в мені,\nБо як місто, що на горі стоїть,\nНе сховається навіть у тьмі.\n\nКуплет 3\nТи навчи мене так життя прожить,\nЩоб в кінці почути Його:\nДобрий, вірний раб, ти скоріш ввійди \nВ радість Пана твойого.', '', '', 'ua', NULL, 0, NULL, NULL),
(1225, 711, 'Ти мене любиш Боже єдиний', 0, 'Куплет 1\nТи мене любиш, Боже єдиний,\nТи мене любиш, - о яке диво!\nЧасто, як сина, ніжно голубиш,\nТи мене любиш, Ти мене любиш.\n\nПриспів:\nО, я щасливий, мить незбагненна,\nДуха Святого дав Ти для мене, \nШлях переможний в хащах туману, \nТо ж, Алілуя, вічна Осанна!\n\nКуплет 2\nМаю від Тебе істини слово,\nВ серці зоріє так світанково.\nЧига на душу світ непривітний,\nРадість даруєш в щирій молитві.\n\nКуплет 3\nЗнаю, нелегко буде до болю,\nАле невпинно я йду за Тобою.\nБачу Голгофу, серцем радію, - \nТи є Спаситель, - людства надія!', '', '', 'ua', NULL, 0, NULL, NULL),
(1226, 712, 'Мій Господь в молитві', 0, 'Куплет 1\nМій Господь, в молитві до Тебе схиляюсь\nІ подяку серця до Тебе несу\nЗа любов, за шлях Твій, Боже, Тебе молю:\nОсвяти, очисти все життя моє!\n\nКуплет 2\nВірний мій Спаситель відкрив мої очі,\nЯ себе побачив у гріховній тьмі, - \nІ в сльозах гарячих впав до ніг пробитих,- \nІ в ту ніч, Ісус мій, я впізнав Тебе.\n\nКуплет 3\nНіжно Ти схилився, Боже, наді мною,\nТи спитав тихенько: “Любиш ти Мене?”\nНе з докором, але з ніжною любов’ю,\nТи тоді навіки врятував мене.\n\nКуплет 4\nВсю красу земную, марноту, невір’я \nПроміняв на щастя, яке дав Христос,\nВ цім житті нічого більш мені не треба,\nЯкщо Ти, Спаситель, все його візьмеш.', '', '', 'ua', NULL, 0, NULL, NULL),
(1227, 713, 'Не вічно буду я блукати', 0, 'Куплет 1\nНе вічно буду я блукати в земній долині зла й гріха.\nЯ - мандрівник в земному краю, в оселі неба прагну я.\n\nКуплет 2\nТобі служити хочу, Боже, мене Ти дорого купив.\nТи - Цар і сильний мій Володар, я весь і вічно буду Твій!\n\nКуплет 3\nТвій мир святий - це насолода безрадній і сумній душі. \nДаруй утіху у час горя і світлий, радісний спокій.\n\nКуплет 4\nДаруй, щоб з вірністю я прагнув сповняти працю все Твою, \nЩоб Твоє світло не погасло в душі покірливій - молю!\n\nКуплет 5\nКоли немає вже натхнення, вогонь любві в молитві згас, \nХай кров Твоя, Твій хрест мучення натхне на подвиг знову нас!', '', '', 'ua', NULL, 0, NULL, NULL),
(1228, 714, 'Вічна Скеле дай мені', 0, 'Куплет 1\nВічна Скеле, дай мені схоронитися в Тобі.\nКров з водою, що за нас з ран Твоїх святих лилась, \nХай буде ліком моїм, о, обмий мене з гріхів.\n\nКуплет 2\nНе ділами власних рук я спасусь від вічних мук.\nХоч би потом я заливсь, хоч би я в сльозах топивсь, \nВсе ніщо, усе марне, - Ти спасаєш Сам, Христе!\n\nКуплет 3\nЯ нічого не несу, - прямо під хрест Твій спішу.\nНагий я - Ти одягни і мене благослови.\nСпасе, я до Тебе йду, обмий мене, бо помру.\n\nКуплет 4\nПоки нині ще живу: прийде час і я помру,\nТа піду у вишній світ здати з діл моїх всіх звіт.\nНічна Скеле, дай мені схоронитися в Тобі!', '', '', 'ua', NULL, 0, NULL, NULL),
(1229, 715, 'Молись в день радості і щастя', 0, 'Куплет 1\nМолись в день радості і щастя,\nВ турботах й боротьбі молись!\nМолись в загрозі від нещастя,\nКоли тривожишся - молись!\n\nКуплет 2\nМолись, коли ти кривду терпиш,\nУ небезпеці ти - молись!\nМолись, коли за милих просиш,\nЗа злого ворога молись!\n\nКуплет 3\nМолись, коли слабіють сили,\nКоли міцнішаєш - молись!\nМолись також біля могили,\nІ за народжених молись.\n\nКуплет 4\nМолись, коли прийде спокуса,\nЯк переміг себе - молись!\nМолись Спасителю Ісусу,\nЩоб Він простив тобі, молись.', '', '', 'ua', NULL, 0, NULL, NULL),
(1230, 716, 'Молись тоді коли ослабне віра', 0, 'Куплет 1\nМолись тоді, коли ослабне віра,\nКоли в дорозі зовсім знемагаєш.\nЗнай, що у Бога ласки є без міри,\nІ знай, що Він про тебе пам’ятає.\nМолись в хвилину горя і недолі,\nКоли ти впав і важко тобі встати.\nКоли ти сам, мов та билина в полі,\nГосподь тобі бажає поміч дати.\n\nПриспів: \nМолись Йому так просто, як ти	вмієш,\nІ Він почує всі твої благання,\nТвою журбу Він, мов туман, розвіє, \nЛише молись, молися без вагання!\n\nКуплет 2\nМолись, коли прийде найбільше горе,\nИ життя твоє, мов море, захвилює,\nКоли погасне сонце ясне й зорі,\nМолись тоді, і Бог тебе почує!\nМолись, молись, бо це одна дорога,\nЩоб спокій серцю втомленому мати.\nМолись Йому - розвіється тривога,\nІ серце буде в радості співати!', '', '', 'ua', NULL, 0, NULL, NULL),
(1231, 717, 'О Боже споглянь на страждання', 0, 'Куплет 1\nО, Боже, споглянь на страждання \nНа світі нещасних людей!\nПочуй всі сердечні зітхання,\nЩо рвуться до Тебе з грудей.\n\nКуплет 2\nСпоглянь на тих сліз океани,\nЩо ллються невпинно з очей;\nХто може загоїть ті рани,\nВсім жертвам темряви ночей.\n\nКуплет 3\nО, визволи душі на волю,\nКайдани гріховні розбий!\nВ народах, мов в чистому полі,\nТи миру насіння посій.\n\nКуплет 4\nЗасяй, Боже, ясним промінням \nНад світом обдертим, сумним,\nЙ правицю Твойого спасіння \nПодай всім страждальцям земним.\n\nКуплет 5\nХай квітками вкриються ниви,\nДе кров та лиш сльози лились,  \nЩоб райські веснянії співи\nПо буйних ланах пронеслись.\n\nКуплет 6\nЩоб там, де гриміли гармати \nІ рвали обличчя землі,\nПрийшли вороги обніматись \nДля вічного братства й хвали.', '', '', 'ua', NULL, 0, NULL, NULL),
(1232, 718, 'Не в словах натхненних молитов', 0, 'Куплет 1\nНе в словах натхненних молитов \nЯ блаженство для душі знайшов;\nВсе найкраще, що є тут в житті, - \nВічне джерело моє в Христі!\n\nКуплет 2\nНе в спокою щастя я зазнав,\nНе кутка я тихого бажав:\nНасолоду маю в боротьбі, - \nВічне джерело моє в Тобі!\n\nКуплет 3\nБачиш Ти, як завжди, в кожну мить \nДо Тебе любов в мені горить:\nНе шукав нічого я собі, - \nВічне джерело моє в Тобі!\n\nКуплет 4\nТи відкрив мені любов Свою;\nЧи щасливий буду я в раю?\nЗ радощів тремтить душа в мені, - \nВічне джерело моє в Тобі!\n\nКуплет 5\nТи для мене захист, Ти - мій щит,\nБез Христа-порожній цілий світ:\nЯ без Тебе вмер би у журбі,\nВічне джерело моє в Тобі!\n\nКуплет 6\nТут навколо хижий ворог мій \nТочить проти мене лютий бій;\nПеремогу Ти даєш мені, - \nВічне джерело моє в Тобі!\n\nКуплет 7\nПісля довгих нещасливих днів\nНа землі одне я зрозумів:\nЩастя вічне лиш в Твоїй красі!\nВ Бозі є джерела мої всі!', '', '', 'ua', NULL, 0, NULL, NULL),
(1233, 719, 'Всюди я з Ісусом', 0, 'Куплет 1\nВсюди я з Ісусом без страху піду,\nВсюди, де веде Він, я Його буду.\nСкрізь мені без Нього радості нема,\nВсюди я з Ісусом без страху піду.\n\nПриспів:\nВсюди з Ним (2р.)\\ Я не пропаду;\nВсюди я з Ісусом без страху піду.\n\nКуплет 2\nВсюди я з Ісусом, слабість чи біда,\nУ спокусі Він надія є тверда.\nВін пройшов спокусу, і я з Ним пройду,\nВсюди я з Ісусом правду віднайду.\n\nКуплет 3\nВсюди я з Ісусом; я не є один,\nХоч мене всі лишать, - Він зі мною все.\nХоч мене веде Він крізь пусті стежки,\nВсюди є з Ісусом мені дім хвали.\n\nКуплет 4\nВсюди я з Ісусом - море чи земля, - \nНе боюсь нічого - в Нім спасенний я.\nЯ готовий йти, як скаже мені Він,\nВсюди, де піду я - провідник Він мій.\n\nКуплет 5\nВсюди я з Ісусом спокійно засну,\nЯк гріховні тіні мене обгорнуть;\nЗнаю я, що смутку мати не буду,\nБо я скрізь з Ісусом дім собі знайду.', '', '', 'ua', NULL, 0, NULL, NULL),
(1234, 720, 'Духом в біді не упадай', 0, 'Куплет 1\nДухом в біді не упадай, - Бог поміч дасть тобі!\nВ Божій любві ти проживай, Бог поміч дасть тобі!\n\nПриспів:\nБог поміч дасть	тобі,\nВсі дні твої, в житті твоїм.\nБог поміч дасть тобі (2р.).\n\nКуплет 2\nЯк серце заболить твоє, - Бог поміч дасть тобі!\nЯк прикре є життя твоє, - Бог поміч дасть тобі!\n\nКуплет 3\nУ всіх твоїх незлих ділах Бог поміч дасть тобі.\nВ щедрих твоїх благаннях всіх Бог поміч дасть тобі\n\nКуплет 4\nНа самоті, як горе є, Бог поміч дасть тобі!\nВ неволі чи в нещасті ти, - Бог поміч дасть тобі!', '', '', 'ua', NULL, 0, NULL, NULL),
(1235, 721, 'Моя надія у Христі', 0, 'Куплет 1\nМоя надія у Христі,\nВ Його крові і чесноті;\nВся людська сила - марнота,\nЯ лиш надіюсь на Христа!\n\nПриспів:\nХристос є скелею людства,\nВесь інший грунт - трясовина!\nЄдина скеля Він моя!\n\nКуплет 2\nЙого посвята, Його кров,\nНа людськім морі мій покров;\nКоли все рветься у житті - \nДуша спасеться у Христі!\n\nКуплет 3\nЯких нас Спас тоді знайде,\nКоли востаннє в світ прийде?\nМоя одежа - чеснота,\nВ ній стану я перед Христа!', '', '', 'ua', NULL, 0, NULL, NULL),
(1236, 722, 'Якщо ти будуєш свій дім', 0, 'Куплет 1\nЯкщо ти будуєш свій дім - будуй ти його на скалі.\nПоллються великії води - і дім устоїть твій тоді.\n\nПриспів:\nХристос є моя скала,\nХристос є моя мета,\nХристос є моє життя,\nЛиш в Нім все моє майбуття!\n\nКуплет 2\nХто Бога шукає завжди і Духа Святого прийняв,-\nОдержить небесний спокій, бо тверду основу він мав.\n\nКуплет 3\nI пісня хвали у тобі поллється тоді від душі,\nXвалити ти будеш Христа, бо в Ньому є радість твоя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1237, 723, 'Ісус є мій притулок', 0, 'Куплет 1\nІсус є мій притулок, Він мій є капітан.\nНе страшні з Ним страждання, на морі ураган.\nВітри мене не зрушать, вітри мене не зб’ють, - \nІсус є мій притулок (2р.), мене Він збереже!\n\nКуплет 2\nІсус мене провадить через земне життя - \nНемов на морі човен, що в хвилях залива.\nХитає моє судно, та гавань бачу я, - \nІсус мене провадить (2р.) до берега життя!\n\nКуплет 3\nІсус є мій приятель поміж всіма людьми -\n Найкращі має ліки на всі хвороби злі.\nІ смерть мені не страшна: мене Він береже.\nІсус є мій приятель (2р.) найкращий понад все!\n\nКуплет 4\nІсус всіх закликає, бо Він є капітан.\nБуть в Його війську хочеш? В ряди скоріше встань \nВін кличе нас до бою, спереду Сам іде.\nХристос ще тебе кличе (2р.), спіши, ще Він зове!', '', '', 'ua', NULL, 0, NULL, NULL),
(1238, 724, 'Господь є пастирем моїм', 0, 'Куплет 1\nГосподь є пастирем моїм, Він дав мені життя,\nІ на зелені пасовиська провадить Він мене,\n\nКуплет 2\nВін підкріпляє душу мою, на тиху воду поведе. \nСтежками праведности веде ради Ймення Свого.\n\nКуплет 3\nКоли б долиною смерті йшов, - не побоюся зла.\nТвоя рука і посох Твій підтримують мене.\n\nКуплет 4\nТи приготував стіл мені при ворогах моїх \nІ намастив голову мою оливою.\n\nКуплет 5\nЛюбов Твоя і Твоє добро супроводять мене,\nПо всі дні мого життя хочу бути в Домі Твоїм.\nАлілуя, алілуя, алілуя, алілуя,\nАлілуя, алілуя, алілуя, амінь.', '', '', 'ua', NULL, 0, NULL, NULL),
(1239, 725, 'Скорбне серце не плач', 0, 'Куплет 1\nСкорбне серце, не плач, не журися \nІ не падай в тяжкій боротьбі!\nТільки в тиші Ісусу молися, - \nВін почує, поможе тобі.\n\nПриспів:\nВ цьому світі нам тяжко і сумно,\nВіє вітер і хмари пливуть,\nТа згадай - нам боротись не довго, - \nВ небі радість і щастя нас ждуть.\n\nКуплет 2\nШлях твій чорнії хмари покрили \nІ любові вогонь погаса.\nПригадай же - і радість, і сила \nЄ для тебе в Ісуса Христа!\n\nКуплет 3\nНе забудь - твій Спаситель з тобою, \nНе покине ніколи тебе,\nІ в вітчизну небесну спокою \nВід страждання і сліз приведе!', '', '', 'ua', NULL, 0, NULL, NULL),
(1240, 726, 'Свої очі я зводжу на гори', 0, 'Куплет 1\nСвої очі я зводжу на гори,\nЗвідки прийде мені допомога.\nМій Господь йтиме всюди зі мною,\nМоя поміч від Господа Бога.\n\nКуплет 2\nІ нічого не вдіють злі люди,\nБо мій Сторож не спить, не дрімає.\nІ коли упаду я в знемозі,\nТо Він поміч мені посилає.\n\nПриспів:\nСам Господь - моя тінь по правиці,\nСкрізь за мною слідять Його очі, \nСеред дня мене сонце не вдарить,\nАні місяць глибокої ночі.\n\nКуплет 3\nХоч і сонце зайде за горою,\nВін мене стерегтиме від злого,\nПроясниться моя путь дорога,\nМоя поміч від Господа Бога.\n\nКуплет 4\nІ нічого не вдіють злі люди,\nБо мене береже Бог Великий,\nВ мене вихід збережений буде\nІ мій вхід від тепер аж навіки.', '', '', 'ua', NULL, 0, NULL, NULL),
(1241, 727, 'В лузі ось косарі', 0, 'Куплет 1\nВ лузі ось косарі розмахалися гострими косами.\nЩо їм Божі квітки? Їм закінчить би працю свою.\nЯ на милість Твою все ж надіюсь, Спасителю Господи\nНа милість, на милість, лиш тільки на милість Твою!\n\nКуплет 2\nЩира віра, Господь, - ось подруга моя завжди вірная, \nВіра в те, що Ти всім управляєш рукою Творця.\nІ я знаю, Господь, що завжди Ти за мене заступишся. \nТи мій Камінь Рятунку, тут спиниться гостра коса.\n\nКуплет 3\nБо ж інакше нащо Ти поїв мене дивними росами,\nІ нащо показав Ти любов та батьківське тепло?\nІ для чого наповнив мене чудо-піснями, Господи?\nНе для того ж, о ні, щоб потрапить під гостру косу.\n\nКуплет 4\nКосарі із лугів повернулися з гострими косами, \nСкільки впало трави, ну а я, як раніше стою, \nПереповнений знову небесними чистими росами \nПрославляю Тебе за любов і за милість Твою.', '', '', 'ua', NULL, 2, '2021-03-19', NULL),
(1242, 728, 'Я йду пустелею безплідною', 0, 'Куплет 1\nЯ йду пустелею безплідною,\nМій шлях тернистий і вузький,\nБо близько вже до краю рідного,\nМене провадить Дух Святий.\n\nКуплет 2\nЯк сонце поза гори схилиться,\nОбіймуть землю тіні тьми,\nГустою млою все покриється, - \nОсвітить шлях мій Дух Святий.\n\nКуплет 3\nЯк вороги юрбою грізною \nМене оточать навкруги,\nІ смерть в лице дихне погрозою, - \nДасть перемогу Дух Святий.\n\nКуплет 4\nЯк на шляху до краю вишнього \nЯ стану рідним, як чужий,\nІ навіть друзі всі позраджують, -\nМене не зрадить Дух Святий.\n\nКуплет 5\nКоли ж усе, що в світі маю я,\nВідніме смерті помах злий,\nІ навіть з тілом розпрощаюся, - \nЗі мною буде Дух Святий.', '', '', 'ua', NULL, 0, NULL, NULL),
(1243, 729, 'Створив Бог небо', 30, 'Куплет 1\nСтворив Бог небо, сонце, місяць, зорі \nІ нашу землю, все, що є на ній, \nПід небом птахів, дивну рибу в морі,\nСади прекрасні, квіти запашні.\n\nКуплет 2\nЗемля, земля, ти голос Божий чула \nІ дала все, що Бог тобі сказав.\nЗемля, земля, яка ти гарна була,\nКоли тебе Творець людині дав.\n\nКуплет 3\nВінцем творіння був Адам і Єва.\nБлагословив їх Бог і щастя дав,\nТа ворог людський вів лукаву мову,\nПривів до смерті, щастя геть забрав.\n\nКуплет 4\n“О, сину мій, - ридала перша мати, - \nЧому мовчиш, мій любий, дорогий? \nНещасна я виною смерті стала.\nО, Боже мій, прости мій гріх важкий!”\n\nКуплет 5\nСебе у жертву дав Христос Спаситель,\nЗа людський гріх Він кров Свою пролив.\nРозбив кайдани смерті Відкупитель,\nУсі гріхи Собою Він покрив.\n\nКуплет 6\nЗемля, земля, яка ти гарна будеш! \nОбновлена від терня й марноти.\nЗемля, земля, ти всіх спасенних приймеш. \nЧи будем там, мій друже, я і ти?\n\nКуплет 7\nНа цій землі обновленій я буду \nЗ Христом Ісусом вічно буду жить,\nДе сльози й горе назавжди забуду,\nТам вічні радість, щастя і спокій.\n\nКуплет 8\nТам також гарне й нове місто буде,\nНазва його - новий Єрусалим.\nУ ньому сонце світити не буде,\nБо вічним світлом є там Божий Син.\n\nКуплет 9\nЗемля, земля, яка ти гарна будеш!\nОбновлена від терня й марноти.\nЗемля, земля, ти всіх спасенних приймеш!\nТам буду я, там будеш, друже, ти!', '', '', 'ua', NULL, 0, NULL, NULL),
(1244, 730, 'Дивлюсь я в небесну блакить', 0, 'Куплет 1\nДивлюсь я в небесну блакить,\nІ рідний свій край уявляю. \nДуша наче пташка летить \nВ простори жаданого Краю.\nТам квітне чарівна весна,\nТам радість безмірна панує,\nТам рідна моя сторона,\nІ серце за нею сумує.\n\nПриспів:\nКрізь бурі земного життя,\nЯк пташка, лечу я до Тебе.\nТам світле моє майбуття,\nТам радість знайду я для себе.\n\nКуплет 2\nНа груди Христові схилюсь,\nЗабуду страждання і горе,\nІ в хори небесні ввіллюсь,\nЯк річка вливається в море.\nА покищо тільки в думках \nЯ лину до рідного Краю \nІ з вірою в серці свій шлях \nПо вузькій стежині звершаю.\n\nКуплет 3\nТа скоро, я вірю, прийде,\nОта довгожданна хвилина,\nІ зірка досвітня зійде,\nЗустріну я Божого Сина.\nДай віри, Ісусе, мені - \nДля Тебе трудитись і жити.\nКоли мої скінчаться дні,\nЩоб зміг Тебе в небі зустріти.\n\nКуплет 4\nЯ знаю - настане той час,\nХвилина бажанної мрії.\nЗустрінуться там в небесах \nЗ Ісусом Христом усі вірні.\nТам пісню Мойсея й Христа \nСпасенні усі заспівають.\nТам радість буде без кінця,\nВсім серцем туди я бажаю.', '', '', 'ua', NULL, 0, NULL, NULL),
(1245, 731, 'В край далекий гуси полетіли', 0, 'Куплет 1\nВ край далекий гуси полетіли \nПо блакитнім небі голубім.\nТа не всі їх птахи розуміли,\nЧому кидають вони свій дім.\n\nКуплет 2\nУ той край нелегка є дорога - \nВітер крила рве у небесах.\nВ серці заховалася тривога,\nА надія світиться в очах.\n\nКуплет 3\nЄ у нас той вічний Край Небесний. \nПереліт - то наше все життя.\nА надія - наш Ісус воскреслий,\nВін веде нас в вічне майбуття.\n\nКуплет 4\nВ край далекий гуси полетіли \nПо блакитнім небі голубім.\nДикі гуси приклад залишили,\nЩо і нам пора в свій рідний дім.', '', '', 'ua', NULL, 0, NULL, NULL),
(1246, 732, 'Як я бажаю до Тебе Боже', 0, 'Куплет 1\nЯк я бажаю до Тебе, Боже,\nЯк я хотів би в небеса!\nТільки з Тобою усе переможу \nТільки з Тобою - у серці роса. (2р.)\n\nКуплет 2\nЖиття тривожне, важко буває,\nТисне на душу грішне буття.\nЛише у Тобі, твердо я знаю,\nМаю надію на радість життя. (2р.)\n\nКуплет 3\nБоже мій, Боже, щиро благаю:\nДай мені сили твердо іти.\nВсім поділюсь я, як я бажаю \nРадісно в вічні оселі ввійти. (2р.)\n\nКуплет 4\nПісню для Тебе, Боже, співаю,\nХочу співати й там в небесах!\nХай же ця пісня повік не стихає,\nХай вона буде завжди на устах! (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1247, 734, 'Чудова голубінь небес', 0, 'Куплет 1\nЧудова голубінь небес - наша спільна завітна мрія, \nСкільки бачу в тобі чудес, мимоволі душа радіє.\n\nКуплет 2\nІ на крилах летить туди, де Спаситель мене чекає,\nДе нема страждань і біди, де Христос, наче сонце, сяє.\n\nПриспів:\nТам закінчиться шлях земний,\nТам спасіння знайду для себе.\nІ прошу, о, Спаситель мій,\nДай ввійти в те чудове небо.\n\nКуплет 3\nСлабну я, але далі йду, моя сила лиш тільки в Бозі.\nВ небі щастя своє знайду, але покищо я в дорозі.\n\nКуплет 4\nХоч страждання терплю не раз, зустрічаю життєві грози, \nАле вірю: настане час, і осушить Спаситель сльози.\n\nКуплет 5\nСинє небо, твоя блакить бідну душу мою леліє.\nІ до тебе вона летить, за тобою тужить, сумує.\n\nКуплет 6\nРозганяючи зло і страх, забуваючи всі турботи,\nУ гарячих своїх сльозах споглядаю в твої висоти.', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(1248, 735, 'Розлуки час настав', 0, 'Куплет 1\nРозлуки час настав для нас,\nІ в час цього призначення \nМи кажем: “До побачення!\nПрощай, щасливо, до побачення!”\n\nКуплет 2\nСвоїх людей Господь веде \nЗавжди рукою сильною \nІ ласкою безмірною.\nПрощай, щасливо, до побачення!\n\nКуплет 3\nОсь чути клич, слова Христа:\n\"Вже скоро, скоро Я прийду,\nДо неба вірних приведу!”\nПрощай, щасливо, до побачення!\n\nКуплет 4\nДруже, відкинь зневіри страх! \nЯкщо у цей нелегкий час \nМи бачимось останній раз - \nТоді побачення - на небесах!', '', '', 'ua', NULL, 0, NULL, NULL),
(1249, 736, 'Коли час розлуки близький', 0, 'Куплет 1\nКоли час розлуки близький, важко розставатись нам.\nСам Господь дає нам сили і веде нас в небеса.\nДалеко ти чи близько, - наші серця б\'ються в унісон. \nБожа ласка нас поріднить, коли ми будемо з Христом. Приспів:\n\nКуплет 2\nБoдрузі є назавжди, коли дружба та в Христі, \nБoдруг такий не зрадить, не відцурається в біді.\nІ коли нарешті прийде час прощання, то нехай \nСпас покаже нам Свій шлях, друзям навік.\n\nКуплет 3\nВipaта любов Господня, і надія в нас живе.\nІ молитва друга щира є важлива над усе.\nДалеко ти чи близько, наші серця б\'ються в унісон. \nБожа ласка нас поріднить, коли ми будемо з Христом.', '', '', 'ua', NULL, 0, NULL, NULL),
(1250, 737, 'Так швидко лине', 0, 'Куплет 1\nТак швидко лине невблаганний час,\nІ сумно, що розлуки час прийшов.\nГосподня милість поєднала нас,\nІ хочеться зустрітись з вами знов.\n\nПриспів:\nГосподь ще подарує зустріч нам,\nЯкщо не на землі, то в небесах, \nЗустрінемося біля ніг Христа,\nДе спокій, мир і радість у серцях.\n\nКуплет 2\nПодяка до небес нехай летить \nЗа зустріч, що Господь нам дарував,\nЗа те, що Він був з нами в кожну мить \nІ кожного із нас оберігав.\n\nКуплет 3\nЯк добре бути, друзі, нам разом,\nМолитися і славити Отця.\nЗа час оцей, проведений з Христом, \nПодяка переповнює серця.\n\nКуплет 4\nНехай Господь в житті нас проведе,\nВід зла й неправди в світі захистить\nІ в небо, в Отчий дім нехай введе,\nДе будемо з Ісусом вічно жить.', '', '', 'ua', NULL, 0, NULL, NULL),
(1251, 738, 'Ми співаємо пісню подяки', 0, 'Куплет 1\nМи співаємо пісню подяки і бажаєм співати Тому, \nХто з\'єднав нас всіх у єдину \nУ велику Христову родину.\n\nПриспів:\nА тепер до побачення,\nЯкщо Бог нам дозволить бачення. \nА як не на землі, то у небі в красі \nМи побачимось знову усі.\n\nКуплет 2\nМи підемо своїми шляхами,\nПам\'ятати будемо цей час,\nЯк було дуже добре нам з вами,\nЯк раділи, співали для вас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1252, 739, 'Приємні хвилини', 0, 'Куплет 1\nПриємні хвилини так швидко минають,\nІ не повернути нам спільності знов.\nІ теплі прощання слова \nСказати прийшла вже пора,\nУ кожного буде дорога своя.\n\nПриспів:\nПрощання та розлуки невід\'ємні є в житті, \nТа надія не згасає: будуть зустрічі нові.\n\nКуплет 2\nХай кожний із вас в похід далі крокує,\nВ любові Ісус захистить, збереже,\nЩоб з Ним було ваше життя\nІ доля Ісуса свята\nДо зустрічі знову колись привела.\n\nКуплет 3\nПриємні хвилини так швидко минають,\nІ не повернути нам спільності мить. \nЯкщо не зустрінемось тут,\nТо вірим: хвилини прийдуть- \nДо неба дороги усіх приведуть.', '', '', 'ua', NULL, 0, NULL, NULL),
(1253, 740, 'Творець Всесильний', 0, 'Куплет 1\nТворець Всесильний, Боже святий, \nТебе величить світ цілий.\nПеред Тобою все тремтить,\nПохвальні пісні голосить.\n\nКуплет 2\nСонце і зорі, небо, земля,\nМоре і ріки, луг, трава- \nСлавить Тебе все, шле свій глас, \nВсе прославляє: Бог свят наш!\n\nКуплет 3\nВсе вихваляє, Боже, Тебе,\nАле говорить і мені,\nЩоб я сердечно Тебе любив,\nВолю Твою святу сповнив.\n\nКуплет 4\nСвіту Владико! Дай же мені \nВірно служити все Тобі,\nЩиро любить Тебе в житті, - \nДуже про це Тебе молю.', '', '', 'ua', NULL, 0, NULL, NULL),
(1254, 741, 'Хочу Я тебе провадить', 0, 'Куплет 1\nХочу Я тебе провадить до прекрасної мети,\nВ час нелегкої години буду Я з тобою йти.\nА як станеш спотикатись і не зможеш далі йти, - \nЯ тебе, моя дитино, на руках буду нести. (2р.)\n\nПриспів:\nІ»о любов Моя велика, і немає їй кінця,\nНе відкинь її, Мій сину, - кров\'ю вилилась вона.\nЯ люблю тебе, дитино, над усе, що в Мене є, \nХочу поруч біля Себе завжди бачити тебе.\n\nКуплет 2\nНе шукай у цьому світі ти скарбниці золоті,\nВо найбільший скарб у небі - жити з Богом усі дні. \nЙди до Мене, не вагайся, руку дай Мені свою,\nЯ прощу усі провини, знай жети любов Мою.(2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1255, 742, 'Віддаймо хвалу', 0, 'Куплет 1\nВіддаймо хвалу Ісусу Христу,\nСпіваймо Йому всі пісню нову!\nМогутній і вічний, і любить Він нас,\nУ велич зодягнений наш любий Спас.\n\nКуплет 2\nНе можна в словах любов описать,\nНе можна в піснях її оспівать;\nУ сонці, у хмарах вона і в дощі,\nУ темряві ночі, в ранковій зорі.\n\nКуплет 3\nГосподня любов безмежна, свята,\nГосподня любов у наших серцях;\nВона нам відкрила джерела добра,\nСпасіння і вічне життя нам дала.', '', '', 'ua', NULL, 0, NULL, NULL),
(1256, 743, 'Хвала Тобі наш Господь', 0, 'Куплет 1\nХвала Тобі наш Господь, хвала, Тобі Бог Святий \nХвала за Ісуса, Сина Твойого.\n\nПриспів:\nТепер слабий скаже: \"Сильний я\",\nБідний скаже: \"Я багач\",\nЗавдячуючи тому, що Бог дав. Хвала!', '', '', 'ua', NULL, 0, NULL, NULL),
(1257, 744, 'Тебе я величаю', 0, 'Куплет 1\nТебе я величаю, о Господь!\nБог Єдиний на небі і на землі! (2р.)\n\nПриспів:\nТи Один достойний всю славу прийнять,\nВоскреслий із мертвих Агнець Господній. \nНародам усім Ти дарував спасіння.\nІ тепер ми приносим славу Тобі.', '', '', 'ua', NULL, 0, NULL, NULL),
(1258, 745, 'Осанна', 0, 'Куплет 1\nОсанна, осанна, осанна Тобі, Цар царів! (2р.)\n\nПриспів:\nМи підносим Тебе серцем повним хвали,\nДухом ми піднесем Тебе. Осанна Тобі, Цар царів!\n\nКуплет 2\nМи любим (Зр.) \nТебе, Цар царів! (2р.)\n\nКуплет 3\nМи славим (Зр.) \nТебе, Цар царів! (2р.).', '', '', 'ua', NULL, 0, NULL, NULL),
(1259, 746, 'Ангели в небі Господа славлять', 0, 'Куплет 1\nАнгели в небі Господа славлять,\nСлаву достойную | Богу несуть. (2р.)\n\nПриспів:\nВічная слава! (Зр.) Слава Христу! (2р.)\nВічная слава! (Зр.) Слава Христу!\n\nКуплет 2\nХочеться з ангельським співом з\'єднатися,\nВ хорі відкуплених, спасенних Господом \nІ серце Господу, Богу Єдиному,\nХристу Спасителю | славу несе. (2р.)\n\nКуплет 3\nТут в низині земній Церква все томиться,\nДух прагне до Христа, до Нареченого.\nО, гряди, Господи, бачиш Невістка жде.\nТобі Єдиному славу несе (2р.)\n\nКуплет 4\nАгнець прославлений, Царствений Божий Син, \nДивний Христос Господь в небі нас жде \nІ серце Господу, Богу Єдиному,\nХристу Спасителю | славу несе. (2р.)', '', '', 'ua', NULL, 3, '2021-03-28', NULL),
(1260, 747, 'Я величаю Царя царів', 0, 'Куплет 1\nЯ величаю Царя царів і Пана над панами!\nТи - мій Господь, благий навік, хвала Тобі, хвала!\n\nПриспів:\nХвала Тобі (Зр.) Одному!\nХвала Тобі (Зр.) навік!\n\nКуплет 2\nЗа те, що Ти створив на землі, за сонце і за небо, \nЗа дощ, за вітер і за сніг - за все Тобі хвала!\n\nКуплет 3\nЗа Сина, що прийшов спасти і кров\'ю відкупити.\nЗа хрест, Голгофу і за смерть - за все Тобі хвала!\n\nКуплет 4\nЗа те, що ми спасенні є, за милість і за спокій, \nНадію, віру і любов - за все Тобі хвала!', '', '', 'ua', NULL, 0, NULL, NULL),
(1261, 748, 'О хвала Ісусу Христу', 0, 'Куплет 1\nО, хвала Ісусу Христу, що у світі цім я живу \nІ надію маю святу. О, хвала Ісусу Христу!\n\nПриспів:\nРадість ніколи не мине,\nКоли наш Спаситель прийде,\nГоре і нещастя пройде.\nО, як там чудово буде!\n\nКуплет 2\nМи спасенні кров\'ю Христа, Він за нас віддав Своє життя. \nЗаспіваймо пісню Йому радісну, щасливу й живу!', '', '', 'ua', NULL, 0, NULL, NULL),
(1262, 749, 'Буду зорю я будити', 0, 'Куплет 1\nБуду зорю я будити співом чудесним хвали, - \nЦе жертва - плід уст моїх, жертва, яку приношу. \nСерце моє так зміцнилось, хочу співати Тобі,\nБо дуже велике Твоє милосердя до нас.\n\nПриспів: \nСлавлю я Тебе - слава на віки і віки,\nСлавлю я Тебе - слава Тобі Господь! \nСлавлю я Тебе - слава на віки і віки, Славлю я Тебе!\n\nКуплет 2\nХочу я бути з Тобою, славити Ім\'я святе,\nЩоб завжди радіти і серцем прийняти Тебе.\nЧасу залишилось мало, скоро Ти прийдеш до нас.\nЯ буду співати, Тебе прославляти, мій Спас!', '', '', 'ua', NULL, 0, NULL, NULL),
(1263, 750, 'Алілуя алілуя ти наш Бог', 0, 'Куплет 1\nАлілуя, алілуя, ти наш Бог! (2р.)\nВ благодаті Ти великий, в милосерді дивний Ти. \nАлілуя, алілуя, ти наш Бог!\n\nКуплет 2\nАлілуя, алілуя, наш Отець! (2р.)\nТи піклуєшся про всіх, не залишиш нас повік. \nАлілуя, алілуя, наш Отець!\n\nКуплет 3\nАлілуя, алілуя, (мій) Ісус! (2р.)\nТвої муки на хресті дали прощення мені.\nАлілуя, алілуя, (мій) Ісус!\n\nКуплет 4\nАлілуя, алілуя, Дух Святий! (2р.)\nЖиття й силу Ти даєш, всіх до неба нас ведеш. \nАлілуя, алілуя, Дух Святий!', '', '', 'ua', NULL, 2, '2021-04-01', NULL),
(1264, 751, 'Господи Тебе я хочу славить', 0, 'Куплет 1\nГосподи, Тебе я хочу славить і Тобі подяку приносить. \nТільки Ти - одна моя надія, - хочу я Тобі служить.\n\nПриспів:\nТобі співаю Алілуя! Тобі співаю Одному.\nЗа те, що Ти страждав невинно,\nТворець мій, я Тебе люблю.\n\nКуплет 2\nІ коли в дорозі знемагаю, бачу руку помочі Твою.\nІ тоді в молитві я схиляюсь, і за все я дякую.\n\nКуплет 3\nГосподи, відкрийся, хто не знає, як Ти милостивий є до всіх,\nЩо завжди в одну мить Ти прощаєш і даруєш в серці мир.', '', '', 'ua', NULL, 0, NULL, NULL),
(1265, 753, 'Хай всіх веде Книга Біблія', 0, 'Куплет 1\nХай всіх веде Книга Біблія,\nХай ця супутниця вічная \nСкрізь і повсюди буде, скрізь буде.\nХай Книга ця всім нагадує,\nХай всім нещасним життя дає.\nВ ній кожен щастя знайде.\n\nПриспів:\nНехай ця Книга наставляє,\nЯк жити людям на землі,\nНехай в любові порадує\nІ в небеса всіх веде.\n\nКуплет 2\nХай ці глаголи чудеснії,\nЯ к відголоски небеснії,\nВ смутку, недолі земній, земній,\nХай в ваше серце вливаються,\nІ небеса проявляються \nЗавжди у вашій душі.\n\nКуплет 3\nВ Ній всі ознаки збуваються,\nВ Ній дар життя здобувається,\nСерцю відрада й душі, душі.\nВ Ній всі народи єднаються,\nЗ Нею слабі утішаються,\nЩастя знаходять в житті.', '', '', 'ua', NULL, 0, NULL, NULL),
(1266, 754, 'Євангеліє', 0, 'Приспів:\nЄвангеліє. Тоді	бери цю книгу	в руки.\nЄвангеліє. В словах діяльних та живих. \nЄвангеліє. Знайдеш розраду від розпуки. \nЄвангеліє. Спасіння ти знайдеш у них.\n\nКуплет 1\nКоли надія в тобі згасне або охопить суєта,\nКоли прийдуть випробування, і за бідою йде біда.\n\nКуплет 2\nВ цій книзі голос відізветься, і заговорить Дух Святий. \nВін над тобою пронесеться: страждай, терпи, люби, живи!\n\nКуплет 3\nТой голос ніжний і ласкавий на душу діє як бальзам. \nСкоріш відкрий для Нього серце, Ісус знайде оселю там.', '', '', 'ua', NULL, 0, NULL, NULL),
(1267, 755, 'Дитя нам Вічний Бог послав', 0, 'Куплет 1\nДитя нам Вічний Бог послав, Син народивсь Його! \nМогутню владу Бог поклав на рамена Його. (2р.)\n\nКуплет 2\nЧудовий, Сильний, Бог-Творець назве Його весь світ, \nПорадник, Вічності Отець, Князь миру з роду в рід. (2р.)\n\nКуплет 3\nВін Царство вічне встановив і мир приніс у світ,\nНавіки правдою зміцнив Престол і Заповіт. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1268, 756, 'Темнесенька нічка', 0, 'Куплет 1\nТемнесенька нічка тьмою світ покрила.\nНа небеснім полі (2р.) зоря засвітила.\n\nКуплет 2\nЛиш одна зіронька понад все сіяє\nІ над Вифлеємом (2р.) проміння зливає.\n\nКуплет 3\nВчули вівчароньки той голос із неба,\nЗібрались на раду, (2р.) куди іти треба.\n\nКуплет 4\nЙшли вони стежкою, тою дорогою,\nТам, де ясність стала (2р.) під тою зорею.\n\nКуплет 5\nI ми підем з ними, поклін Христу даймо \nТа радісну пісню (2р.) разом заспіваймо.\n\nКуплет 6\nНині в Вифлеємі людям Спас родився. \nВеселімся, люди (2р.), Сам Бог воплотився.', '', '', 'ua', NULL, 0, NULL, NULL),
(1269, 757, 'Всесильний Царю світу', 0, 'Куплет 1\nВсесильний Царю світу, Ти ясла вибрав Сам,\n1, згідно з Заповітом, лежав на сіні там.\nРелігії служитель, я людям говорив,\nЩо в яслах був Спаситель, а сам в гріхах ще жив.\n\nКуплет 2\nТа Ти й мені з’явився, і дух мій запалав,\nІ я в Тобі родився, й Твоїм дитям я став. \nЩаслива це хвилина, як в серце Ти ввійшов,\nІ, як мала Дитина, Ти ясла там знайшов.\n\nКуплет 3\nРости ж, свята Дитино, в моєму серці Ти,\nЩоб я також невпинно для Тебе міг рости.\nЩоб “я” моє маліло, а Ти в мені зростав,\nЙ життя як скінчить тіло, я б в небі жити став.', '', '', 'ua', NULL, 0, NULL, NULL),
(1270, 758, 'Радійте люди Спас прийшов', 0, 'Куплет 1\nРадійте, люди, Спас прийшов! Приніс Свою любов!\nПрийміть в серця дар від Отця,\nБо Він приніс життя й гріхів всіх забуття,\nЙ гріхів, гріхів всіх забуття.\n\nКуплет 2\nРадійте, люди, в честь Христа! Бринить хай пісня та!\nНехай наш спів до гір, лісів\nУ світі долетить в оцю блаженну мить,\nВ оцю, оцю блаженну мить!\n\nКуплет 3\nХай щезне смуток і журба, й утихне боротьба!\nРадійте всі, - ви, що в грісі!\nСпасіння бо й для вас приніс на землю Спас, \nПриніс, приніс на землю Спас!\n\nКуплет 3\nНароди всіх країн землі, що в темряві, в імлі! \nСпас кличе всіх до Його ніг!\nЗнайдете всі ви знов святу Його любов;\nСвяту, святу Його любов!', '', '', 'ua', NULL, 0, NULL, NULL),
(1271, 759, 'Вночі з вітанням', 0, 'Куплет 1\nВночі з вітанням Ангел появивсь:\n“Пастирі, встаньте, Спас вам народивсь;\nТож тепер часу не гайте,\nВ Вифлеєм всі поспішайте Богу на поклін!”\n\nКуплет 2\nПрийшли та бачать: в яслах Немовля,\nЯк Ангел Божий з неба промовляв;\nПеред Ним вони смирились,\nЙому щиро поклонились в радості сердець.\n\nКуплет 3\n“Ласкавий Спасе, бажаний здавен,\nУ кожнім часі будь благословен!\nБо Тебе царі й пророки\nТак чекали довгі роки; Ти ж нам об’явивсь!”', '', '', 'ua', NULL, 0, NULL, NULL),
(1272, 760, 'У Вифлеємі нині новина', 0, 'Куплет 1\nУ Вифлеємі нині новина:\nПречиста Діва вродила Сина.\nВ яслах на сіні Його поклала,\nПісню тихенько Йому співала.\n\nКуплет 2\nПастухам ангел вістку звіщає:\n“Радість і спокій Бог посилає;\nДо Вифлеєму всі поспішайте,\nВ бідній Дитині - Спаса вітайте!’\n\nКуплет 3\nТам херувими з неба злітають,\nАнгельські хори Спаса вітають,\nПастух убогий несе, що може,\nЩоб привітати Дитятко Боже.\n\nКуплет 4\nА за зорею далеко, зі Сходу\nЙдуть мудреці зчужого народу\nЗолото щире, ладан та миро, \nНесуть дарунки та серця віру.\n\nКуплет 5\nЛюбий наш Спасе! Ми не багаті, \nДарів коштовних не можем дати,\nТо ж в подарунок несем від себе \nВіру та щиру любов до Тебе!', '', '', 'ua', NULL, 0, NULL, NULL),
(1273, 761, 'Господь Бог предвічний', 0, 'Куплет 1\nГосподь Бог предвічний нині нам родився, \nЗ непорочной Діви в яслах народився.\nХори ангельські співають, народженого вітають.\n\nПриспів:\nСлава! (2р.) Слава во вишніх Богу!\n\nКуплет 2\nПастирям у полі ангел ся являє,\nТам їх до стаєнки мило запрошає,\nЩоб Дитятку честь віддали і весело заспівали.\n\nКуплет 3\nІз небесним хором всі днесь веселімся \nІ Христу-Дитятку низько поклонімся.\nВ Нім надію покладаймо і весело заспіваймо.', '', '', 'ua', NULL, 0, NULL, NULL),
(1274, 762, 'В Вифлеємі днесь Марія', 0, 'Куплет 1\nВ Вифлеємі днесь Марія пречиста \nПородила у стаєнці нам Христа.\n\nПриспів:\nСлава во вишніх Богу (2р.) і мир всім на землі! (2р.)\n\nКуплет 2\nАнгел з неба пастирям ся являє \nІ радісну цю новину звіщає.\n\nКуплет 3\nПрибігають до стаєнки пастирі \nТа вклоняються Ісусу в покорі.\n\nКуплет 4\nА за зіркою зі Сходу йдуть царі:\nТри преславні, прерозумні звіздарі.\n\nКуплет 5\nТам в смиренні Йому поклін віддали,\nПред Ним злато, ливан, миро поклали.\n\nКуплет 6\nМи також Христу поклін свій віддаймо \nІ разом з небесним хором співаймо.', '', '', 'ua', NULL, 0, NULL, NULL),
(1275, 763, 'Воскреслому служу я', 0, 'Куплет 1\nВоскреслому служу я, Він з нами в кожен час. \nСвою любов дарує, Він відродив всіх нас.\nЙого я бачу руку і голос чую теж.\nПролив Він кров і любов явив без меж.\n\nПриспів:\nЖивий, живий! Христос повік живий!\nЗі мною йде вперед, веде, дарує свій спокій.\nЖивий, живий! Спасіння Він звершив!\nЧи знаєш ти, де Він живе? Живе Він і в мені!\n\nКуплет 2\nНавколо себе бачу Господню доброту.\nКоли туга, то плачу і розкажу Христу.\nКрізь бурі і сумніви веде в Небесний Дім.\nА в славний час кожен з нас там буде з Ним.\n\nКуплет 3\nРадійте, християни, свій голос піднесіть!\nВеселими псалмами ви Бога всі хваліть! \nСтраждаючим надія, опора для слабих - \nХоронить нас кожен час Христос Господь.', '', '', 'ua', NULL, 0, NULL, NULL),
(1276, 764, 'Бачу ранком небо молодіє', 0, 'Куплет 1\nБачу, ранком небо молодіє,\nПовстає так світло навкруги,\nІ душа моя не спить, радіє,\nДо його воліє берегів.\n\nКуплет 2\nНині і так легко, як ніколи,\nНе гнітить більш темрява густа.\nЯ прийшов у цій порі ранковій \nДо свого Спасителя Христа.\n\nКуплет 3\nТож відкрию серце для любові \nІ бентежну душу для добра,\nЩоб не знала ні журби, ні болю,\nІ ясніла вічно, як зоря.\n\nКуплет 4\nХоч була неблизька та дорога,\nТа збагнув я у важкій ході:\nЯкщо зараз не прийду до Нього - \nПізно буде каятись тоді!', '', '', 'ua', NULL, 0, NULL, NULL),
(1277, 765, 'Радійте ви завжди', 0, 'Куплет 1\nРадійте ви завжди, бо така воля Божа є (Зр.)\nЩодо вас в Ісусі Христі!\n\nКуплет 2\nМоліться ви завжди, бо така воля Божа є (Зр.) \nЩодо вас в Ісусі Христі!\n\nКуплет 3\nДякуйте за все, бо така воля Божа є (Зр.)\nЩодо вас в Ісусі Христі!\n\nКуплет 4\nДуха не вгашайте, бо така воля Божа є (Зр.) \nЩодо вас в Ісусі Христі!\n\nКуплет 5\nКоли ти приймеш Христа (2р.)\nОчистить серце твоє Він від гріха (2р.)\n\nКуплет 6\nІ як ти прийдеш до Спаса твого,\nВін гріх твій забере \nЧерез віру в Ісуса Христа,\nВін тебе до Себе прийме (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1278, 766, 'Коли в житті негоди', 0, 'Куплет 1\nКоли в житті негоди чи радісне життя,\nЧи вдома, чи в дорозі співаю пісню я.\n\nКуплет 2\nВона іде зі мною, ця пісня неземна,\nМаленькі з нею гори, і ями - рівнина.\n\nКуплет 3\nМелодія любові і пісня про Христа \nВедуть мене до неба, в щасливе майбуття.\n\nКуплет 4\nЗакінчиться надія, і віра теж пройде,\nМелодія любові ніколи не мине.\nМелодія любові і в небі не мине.', '', '', 'ua', NULL, 0, NULL, NULL),
(1279, 767, 'Ми вдячні Богу що знову разом', 0, 'Куплет 1\nМи вдячні Богу, що знову разом \nВ сердець єднанні звучать слова:\n\nКуплет 2\nХто любить Господа (2р.),\nРазом співайте - пісня одна.\n\nКуплет 3\nКолись ми з вами були чужими,\nТепер ми стали Його дітьми.\n\nКуплет 4\nХто любить Господа (2р.),\nВ білих одежах стрінемось ми.\n\nКуплет 5\nНас потішає Господнє Слово,\nIcyс сказав, що знов прийде.\n\nКуплет 6\nХто любить Господа (2р.),\nТого Христос у небо візьме.\n\nКуплет 7\nТам на Голгофі помер Ісус наш,\nЗвільнив Він смертю нас від гріха.\n\nКуплет 8\nХто любить Господа (2р.),\nТой нехай завжди славить Христа.', '', '', 'ua', NULL, 0, NULL, NULL),
(1280, 768, 'Радій радій спасенний', 0, 'Куплет 1\nРадій, радій, спасенний!\nХай буде завжди радістю тобі \nЛаскавий твій Спаситель,\nЩо за твої гріхи вмер на хресті.\n\nПриспів:\nРадій, (радій) спасенний!\nСпівай (співай) про те,\nЩо твій Христос Спаситель \nНавіки спас тебе!\n\nКуплет 2\nРадій, радій, спасенний!\nТи є безпечним під крилом Його!\nВесь світ не є у силі \nЗабрати щастя вічного твого!\n\nКуплет 3\nРадій, радій, спасенний!\nНа небесах дім вічний тебе жде!\nІ при великій славі \nСпаситель твій тебе туди введе!\n\nКуплет 4\nРадій, радій, спасенний!\nСпіши ввійти у зібрання святих!\nІ Богу за спасіння\nХай пісня слави ллється з уст твоїх!', '', '', 'ua', NULL, 0, NULL, NULL),
(1281, 769, 'Боже Вічний Всемогутній', 0, 'Куплет 1\nБоже Вічний, Всемогутній, Всесвіт у Твоїх руках; \nСвітом нашим Ти керуєш і зірками в небесах.\n\nПриспів:\nНам незнаний рік майбутній,\nАле все - в руках Твоїх;\nПоможи нам, Всемогутній,\nЖить з Тобою в кожну мить.\n\nКуплет 2\nТисячі років у Тебе - мов та мить, мов день один. \nТи - Володар землі й неба, вічності, років, годин.\n\nКуплет 3\nНаші дні перед Тобою - наче спалахи зірниць. \nДай, щоб вірою святою всі для Тебе їх прожить.\n\nКуплет 4\nРік цей, Боже, перед нами, але що він принесе? \nТож, Твоїми хай слідами нас рука Твоя веде!', '', '', 'ua', NULL, 0, NULL, NULL),
(1282, 770, 'Сьогодні рік минає', 0, 'Куплет 1\nСьогодні рік минає, ось настає новий,\nТа завжди пробуває тут з нами Бог Святий.\nВін рік увесь минулий усім допомагав,\nБудив серця заснулі, безсилим силу дав.\n\nКуплет 2\nВсе на землі минає: і слава і краса,\nЩо швидко так зникають, мов ранішня роса.\nА небо відкриває лише любов Христа,\nНа нові дні з’єднаєм ми наше з Ним життя.\n\nКуплет 3\nВізьми ж нас, милий Боже, веди в майбутніх днях.\nЗ Тобою переможем спокуси, гріх і страх.\nТвою пошли нам силу, щоб плід ми принесли,\nДні наші рахували і мудро тут жили.', '', '', 'ua', NULL, 0, NULL, NULL),
(1283, 771, 'Хвала Христу за рік минулий', 0, 'Куплет 1\nХвала Христу за рік минулий,\nЩо в цім житті серед біди\nНераз душею ми відчули \nЙoro присутності сліди.\n\nПриспів:\n3 Новим роком (2р.) ми вітаєм друзі вас!\nВ Новім році (2р.) хай Господь провадить вас!\n\nКуплет 2\nНеначе сон, мов дим пролинув,\nНавіки розпрощавшись, рік,\nТа знову час не знає спину - \nСтупає новий на поріг.\n\nКуплет 3\nЗа роком рік життя минає, \nВідходять дні у забуття. \nХристос спасти тебе бажає, - \nВіддай Йому своє життя!', '', '', 'ua', NULL, 0, NULL, NULL),
(1284, 772, 'Сталось чудо із чудес', 0, 'Куплет 1\nСталось чудо із чудес: наш Господь Ісус воскрес! \nРадощам нема кінця, щастям сповнені серця.\nМуки Божий Син терпів, кров святу за нас пролив, \nЩастя сяє нам з небес, бо Спаситель наш воскрес!\n\nКуплет 2\nГріб сторожа стерегла, та безсилою була-\nНаш Христос із мертвих встав, перемогу вірним дав!\nСмерть і пекло подолав, нам надію дарував.\nВін пішов у край небес, повний слави і чудес!\n\nКуплет 3\nМи повірили в Христа - і воскресли для життя!\nТож за Ним услід ходім, Він веде нас в вічний дім! \nБраття й сестри, всі хваліть Спаса в цю чудову мить! \nДень почався, ніч пройшла, Спас воскрес! Йому хвала!', '', '', 'ua', NULL, 0, NULL, NULL),
(1285, 773, 'Настав день воскресіння', 0, 'Куплет 1\nНастав день воскресіння, це свідчить вся земля; \nНадія на спасіння посіяна в серцях.\nТо Пасхи день Господній чудовий нам настав: \nСпаситель наш сьогодні у славі з мертвих встав!\n\nКуплет 2\nХристос обмив нас кров’ю, щоб ми за Ним ішли \nІ, сповнені любов’ю, для Нього лиш жили.\nЙого слова ласкаві ми чуємо в серцях;\nХристос, воскреслий в славі, розвіяв смерті страх.\n\nКуплет 3\nХай небеса радіють, і з ними люди всі:\nХристос воскрес! - співають в гармонії краси. \nНехай хвала з’єднає усіх в акорд новий,\nХай пісню все співає: Спаситель наш живий!', '', '', 'ua', NULL, 0, NULL, NULL),
(1286, 774, 'Сьогодні день радості й щастя', 0, 'Куплет 1\nСьогодні день радості й щастя \nДля вірних Господніх дітей:\nСьогодні Христовою властю \nСпасіння прийшло для людей.\n\nКуплет 2\nВ цей день Бог кайдани неволі \nЗдійняв з наших спутаних ніг,\nІ випустив душі на волю,\nІ смертю Він смерть переміг.\n\nКуплет 3\nВ цей день не ходіть на могили, \nБoтам вже Ісуса нема!\nТам ангели двері відкрили,\nІ світлом вже сяє тюрма.\n\nКуплет 4\nВ цей день хай прокинуться люди,\nХай станеться чудо з чудес:\nХай в кожному думка ця буде:\n“Віднині і я вже воскрес!”', '', '', 'ua', NULL, 0, NULL, NULL),
(1287, 775, 'Христос воскрес Радіє все', 0, 'Куплет 1\nХристос воскрес! Радіє все в природі!\nСвоїм промінням сонце шле з небес\nНа землю радість, і серцям народів \nТеплом своїм звіщає: \"Він воскрес!\"\n\nКуплет 2\n\"Христос воскрес!\" - свідчить трава зелена, \nХоч ще мала, - все ж лине до небес \nВіддати честь Творцю неоціненну \nЗа те, що Божий Син Христос воскрес!\n\nКуплет 3\nХристос воскрес! Воскреслого вітає \nТворіння все, Йому даючи честь.\nМаленька пташка радісно співає\nЧудову пісеньку: \"Христос воскрес!\"\n\nКуплет 4\nХристос воскрес! Я хочу теж співати \nТу дивну пісню Господеві днесь,\nЙого Ім\'я достойно величати \nЗа те, що мій Господь Христос воскрес!\n\nКуплет 5\nХристос воскрес! О люде, не вагайся!\nГpiхам своїм ти поклади кінець! \nЗ народом Божим назавжди з\'єднайся\nІ разом з ним скажи: \"Христос воскрес!\"', '', '', 'ua', NULL, 0, NULL, NULL),
(1288, 776, 'Вся земля так довго', 30, 'Куплет 1\nВся земля так довго на цей день чекала,\nКоли злине з неба теплий чистий дощ,\nКоли сонце правди розжене всі хмари,\nКоли пісню щастя заспіває хтось.\n\nКуплет 2\nІ цей день нарешті до нас увірвався,\nВін приніс нам віру в світле майбуття.\nЧерез Свого Сина Всемогутній Батько \nНам дарує ріки вічного життя.\n\nПриспів:\nІсусу слава! (2р.)\nЛунає пісня над схилами Дніпра.\nІсусу слава! (2р.) \nСпіває вільна Україна.\n\nКуплет 3\nЛюди України, підіймайте руки,\nПрославляйте Сина, Він - Єдиний Бог.\nВін Своєю кров\'ю розірвав кайдани,\nВій достойний слави, наш Ісус Христос.', '', '', 'ua', NULL, 3, '2021-04-04', NULL),
(1289, 777, 'Одного ранку', 0, 'Куплет 1\nОдного ранку, ще до світанку \nЖінки до гробу разом прийшли,\nТа гріб порожній, так, як сказав Він,\nНа третій день Він смерть переміг.\n\nПриспів:\nЯк не воскрес	би Ісус Спаситель,\nТо де ж надія була б моя?\nСмерть подолав Він, воскрес із мертвих\nІ життя вічне нам дарував!\n\nКуплет 2\nЖиву надію Христос подав нам,\nТаку надію хто міг би дать?\nНа третій день Він воскрес із мертвих, \nКайдани смерті Він розірвав!\n\nКуплет 3\nВін обіцяв нам, що скоро прийде \nЗабрати нас до осель Своїх.\nЯк річку смерті ми перейдемо, - \nНа березі нас чекає Він.', '', '', 'ua', NULL, 0, NULL, NULL),
(1290, 778, 'Ісус мій є живий', 0, 'Куплет 1\nІсус мій є живий. (Зр.) Мій Ісус навіки живий!\nІз мертвих Він воскрес, (Зр.) Мій Ісус із мертвих воскрес! \nВін дав мені життя.(Зр.) Мій Ісус мені дав життя!\nВін серце дав нове. (Зр.) Він мені дав серце нове! \nІсусу вірю я. (Зр.) Так, в Ісуса вірую я!\nЖивий, живий, живий! (Зр.) Мій Ісус навіки живий!', '', '', 'ua', NULL, 0, NULL, NULL),
(1291, 779, 'Він воскрес щоб весь світ', 0, 'Куплет 1\nВін воскрес, щоб весь світ оживити.\nВін воскрес, щоб ми з вами жили,\nЩоб покірні словам Його діти \nВ Ньому вічне життя досягли.\n\nКуплет 2\nВін воскрес, щоб гріховне коріння \nСпопелити в тобі назавжди,\nЩоб зросло у серцях те насіння,\nЩо приносить лиш добрі плоди.\n\nПриспів:\nВоскресіння Христа - радість вічна, свята\nНа землі для людей і на небі.\nВоскресіння Христа - то спасіння людства,\nБог любові дарує для тебе.\n\nКуплет 3\nВін воскрес, щоб як поле пшеничне,\nБула вибрана Церква Його,\nВін воскрес, щоб життя дати вічне \nВ небесах для насліддя Свого.\n\nКуплет 4\nВін воскрес і вознісся на небо,\nЩоб нас всіх живить Духом Святим.\nВін зробив це для тебе і мене,\nТож подумаєм, друзі, над тим.', '', '', 'ua', NULL, 1, '2021-04-04', NULL),
(1292, 780, 'Христос воскрес Веселий день', 0, 'Куплет 1\nХристос воскрес! Веселий день,\nСпіває люд, радіє світ.\nНесеться гомін від пісень \nВ широкий світ під небозвід.\n\nКуплет 2\nХристос воскрес! З сердець усіх \nПливе привіт сердечних слів.\nНа лицях всіх блиск щастя втіх,\nНа всіх устах веселий спів.\n\nКуплет 3\nХристос воскрес! Душе радій.\nСкінчився сон і ніч гріха.\nВже з сонця йде проміння рій,\nВіщує день новий життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1293, 781, 'Слухай слухай радісну новину', 0, 'Куплет 1\nСлухай, слухай радісну новину,\nВся земля співає днесь!\nНині сталося велике диво:	(2р.)\nЗ мертвих наш Христос воскрес!\n\nКуплет 2\nЛишень тільки стало розсвітати,\nВже Марія до гробу прийшла,\nАле тіла Господа Ісуса \nВона в ньому не знайшла.  (2р)\n\nКуплет 3\nТихо стала плакати Марія \nТам у Иосифа в саду,\nВ серці тільки думи-мрії:  \n\"Де ж Ісуса я знайду?\"  (2р)\n\nКуплет 4\nОсь з\'явився ангел з неба \nІ сказав їй дивні слова:\n\"Чи живий між мертвими буває?  (2р)\nВін воскрес! Йому хвала!\"', '', '', 'ua', NULL, 0, NULL, NULL),
(1294, 782, 'Вийшла донька ваша заміж', 0, 'Куплет 1\nВийшла донька ваша заміж - буде господиня!\nОй, не плачте, не журіться, - друг в неї надійний.\n\nКуплет 2\nБуде він допомагати, буде поважати,\nТа ніколи він не буде жінку ображати.\n\nКуплет 3\nЗавжди будьте в згоді з Богом, живіть у любові,\nТа не забувайте тільки, що треба служити Богу.\n\nКуплет 4\nЧому ж ти почервоніла на своїм весіллі? \nНіжна, люба й така мила, молода, вродлива!\n\nКуплет 5\nМила, знай, - літа минають, і краса зів’яне.\nАле якщо Бог буде з вами - щастя не обмане!', '', '', 'ua', NULL, 0, NULL, NULL),
(1295, 783, 'Бажаєм тепер сказати для вас', 0, 'Куплет 1\nБажаєм тепер сказати для вас ми щиро усі:\nВітаємо вас, вітаємо вас із шлюбом святим!\n\nКуплет 2\nБажаєм тепер сказати для вас: живіть у любві.\nСвяте ваше “так” хай буде для вас навіки міцним!\n\nКуплет 3\nОдне бажання для вас ми маєм, одне бажання, лиш одне: \nХай Бог в житті вам помагає, старання й мудрість подає!\n\nКуплет 4\nІ чим життя вас тут не зустріне: снігами, вітром чи теплом, \nВи збережіть до смерті віру, святу надію і любов!', '', '', 'ua', NULL, 0, NULL, NULL),
(1296, 784, 'На весільне свято запросили нас', 0, 'Куплет 1\nНа весільне свято запросили нас \nІ гостей багато бачимо в цей час.\nВірим, що присутній тут Творець і Бог,\nБачить Він присутніх, бачить Він вас вдвох.\n\nПриспів:\nїх благаєм, Боже, благослови,\nДай, щоб жили свято, в згоді, в любві.\nДай, щоб виповняли Твої слова і любили Христа.\n\nКуплет 2\nРозкажіть їм, друзі, приклади з життя, \nПоділіться щиро досвідом в цей час.\nЩоб помилок ваших не зробити їм,\nА щоб утішались Господом одним.\n\nКуплет 3\nСпільно величайте Господа в житті,\nДумкою й ділами всі Йому служіть.\nХай сім’ю чудову вам збудує Бог \nІ зміцнить надію, віру і любов', '', '', 'ua', NULL, 0, NULL, NULL),
(1297, 785, 'Ось Боже стали дві душі', 0, 'Куплет 1\nОсь, Боже, стали дві душі з єдиним почуттям: \nНедобре їм у самоті щоденного життя.\n\nПриспів:\nО, Боже наш,	 благослови\nТи душі ці і в них живи,\nПрийми від них Ти молитви,\nУ всьому їх благослови!\n\nКуплет 2\nОдному тяжко в світі жить, змовкає часто спів,\nА на шляху життя лежить все більше труднощів.\n\nКуплет 3\nЩоб легше в світі їм жилось в майбутньому житті, \nБлагослови Ти їх, Христос, у бажаній меті!\n\nКуплет 4\nОдне одного хай вони підтримують завжди,\nА ти до неба висоти їх, Боже, доведи!', '', '', 'ua', NULL, 0, NULL, NULL),
(1298, 786, 'В цей чудовий день весільний', 0, 'Куплет 1\nВ цей чудовий день весільний ми прийшли вам побажать: \nЩастя й радості в дорогу, Господа не забувать.\n\nПриспів:\nНехай щастить	вам навесні,\nУлітку, взимку, восени.\nХай допоможе вам усім Спаситель Сам.\n\nКуплет 2\nЗгода хай між вами буде, милість та любов Христа. \nХай Живе завжди між вами невмираюча весна.', '', '', 'ua', NULL, 0, NULL, NULL),
(1299, 787, 'Будь милосердниймій Христос', 0, 'Куплет 1\nБудь милосердний,мій Христос,\nТобі вину мою приніс.\nДо Тебе я прийшов з гріхом,\nЗ провинами і тяжким злом.\n\nКуплет 2\nГріхам моїм нема числа,\nПровинам і учинкам зла.\nТа більше є Твоя любов, - \nЇх може змити Твоя кров.\n\nКуплет 3\nВід всіх гріхів мене обмий,\nМоїй душі пошли спокій;\nПрости мені, о, Спасе мій,\nЩоб був навіки я вже Твій.\n\nКуплет 4\nНа суд зі мною Ти не йди, - \nЧи ж вийду чистий і святий?\nМені по ласці Ти прости, \nСвоєю кровію обмий.\n\nКуплет 5\nБо грішників Ти кличеш Сам, \nДаєш прощення вічне їм.\nІ я на голос Твій спішу, \nПрощення, Господи, прошу!', '', '', 'ua', NULL, 0, NULL, NULL),
(1300, 788, 'Я Тебе Господь благаю', 0, 'Куплет 1\nЯ Тебе, Господь, благаю, не забудь мене, почуй!\nЯ в глибокому відчаї, Боже любий, порятуй!\nТи любов, в Тебе прощення, грішник я, до Тебе йду, \nЗаспокоєння, спасіння тільки в Тобі я знайду.\n\nКуплет 2\nПрихилися, Боже правди, і мене не залишай,\nЯ стомився в злі, в неправді, мир з Тобою мені дай!\nНе пригадуй, що минуло, все прости, що зле робив,\nБув я в сні гріха заснулий, кращі дні в гріхах прожив.\n\nКуплет 3\nО, Спасителю ласкавий! О, Ісусе, захист мій!\nТи прийми мене, - благаю, спокій дай душі моїй!\nЯ одного лиш бажаю, - щоб навіки був я Твій;\nТи даси спасіння - знаю, простиш гріх, введеш в спокій.', '', '', 'ua', NULL, 0, NULL, NULL),
(1301, 789, 'О Предвічний Боже відколи живу', 0, 'Куплет 1\nО, Предвічний Боже, відколи живу,\nЯ Тебе гнівити не перестаю. (2р.)\nТи свідчиш мені ласки і любов Свою,\nЯ Тобі за теє злобою плачу. (2р.)\n\nКуплет 2\nТи за мене, Спасе, кров Свою проляв,\nЯ, нещасний грішник, ще її топтав. (2р.)\nТи мене все кликав, щоб я не грішив,\nЯ не слухав цього, все безбожно жив. (2р.)\n\nКуплет 3\nЯк же довго, Боже, будеш мені терпів?\nЧи безкарно грішник буде все коїв? (2р.)\nЗ уст Твоїх, Ісусе, добре знаю це,\nЩо безбожних кара певно не мине. (2р.)\n\nКуплет 4\nГрішник там по смерті вчує страшний звук:\nГеть іди, проклятий, в пекло вічних мук! (2р.) \nГеть іди, проклятий, тиМя зневажав!\nТи служив мамоні, а Мене не знав. (2р.)\n\nКуплет 5\nО, не дай, Ісусе, прошу, молю Тя,\nЩоб на мні сповнилась страшна доля та. (2р.)\nЖалую і каюсь за гріхи мої,\nБоже милосердний, о прости мені! (2р.)\n\nКуплет 6\nЯ від нині хочу все Тобі служить,\nА посмерті в небі вічно Тя хвалить. (2р.)', '', '', 'ua', NULL, 0, NULL, NULL),
(1302, 790, 'Спи тихим і спокійним сном', 0, 'Куплет 1\nСпи тихим і спокійним сном \nУ гробі тут, на місці цім,\nВже скоро наш Господь прийде \nІ в вічність Сам тебе введе.\n\nКуплет 2\nБлаженні вірні у Христі,\nЩо свято жили на землі;\nКоли Христос прийде назад,\nТо Він їм життя вічне дасть.\n\nКуплет 3\nВсі вірні в приході Христа \nІз мертвих встануть для життя;\nТоді Христос їх Сам візьме\nІ в Царство вічне уведе.\n\nКуплет 4\nСпочинь спокійно у землі,\nДокіль прийдуть щасливі дні,\nКоли Спаситель і тебе \nУ Вічний Край також візьме.', '', '', 'ua', NULL, 0, NULL, NULL),
(1303, 791, 'Заснув наш брате дорогий', 0, 'Куплет 1\nЗаснув, наш брате дорогий, заснув,\nПокинувши тривогу днів земних,\nНе будеш там ти знову вже страждать, \nСпокійно спи, наш брат!\n\nКуплет 2\nМи любимо і всяк із нас скорбить,\nАле Христос сильніш вміє любить,\nТебе схотів до Себе Він узять,\nСпокійно спи, наш брат!\n\nКуплет 3\nСпокійно, тихо почиваєш ти,\nНе встанеш знову жить для суєти,\nДо тебе бурі зла не долетять,\nСпокійно спи, наш брат!\n\nКуплет 4\nДоки ще зло панує на землі,\nДоки земля дріма в гріховній млі,\nІ сльози на очах людей мигтять, \nСпокійно спи, наш брат!\n\nКуплет 5\nДо дня, коли Создатель воскресить \nУсіх, хто зараз тихо, тихо спить,\nІ прийде Він Своїх від мук узять,\nСпокійно спи, наш брат!\n\nКуплет 6\nДо дня, коли ми з пальмами в руках \nЗустрінем Господа на небесах \nЙ тебе зустрінем коло вічних врат, \nСпокійно спи, наш брат!', '', '', 'ua', NULL, 0, NULL, NULL),
(1304, 793, 'Боже милий я благаю', 0, 'Куплет 1\nБоже милий, я благаю: не забудь мене, згадай!\nВід страждань земного краю мені захист, поміч дай!\n\nПриспів:\nІ я знаю, що з Тобою в цьому світі перейду;\nХоч з тяжкою боротьбою, але в світлий рай ввійду.\n\nКуплет 2\nТемна ніч панує всюди, серце скорбнеє болить;\nІ нема рятунку в людях, Боже, тяжко в світі жить!\n\nКуплет 3\nГрішний в світі я блукаю, в серці радості нема.\nЯ з Тобою жить бажаю, бо без Тебе горе, тьма.\n\nКуплет 4\nБоже, Боже, покладаюсь я на Тебе, Ти спасеш;\nВід гріха, плачу й відчаю. Мене в світлий рай візьмеш.', '', '', 'ua', NULL, 0, NULL, NULL),
(1305, 794, 'Вийшов я дорогою новою', 0, 'Куплет 1\nВийшов я дорогою новою,\nВ темноті тернистий шлях лежить,\nА в Краю небесного спокою \nСвітло правди вічної горить.\n\nКуплет 2\nСвітло правди і життя святого,\nОсвіти мене в дорозі цій,\nПроведи шляхом життя земного, \nПоможи прийти в батьківський дім.\n\nКуплет 3\nЦе життя, як хвилі, що по морю \nСтрашно б\'ють до берега, шумлять.\nЗнаю, що не любить він спокою:\nГрішний світ манить мене назад.\n\nКуплет 4\nЯ назад вже більше не вернуся,\nХоч мій шлях далекий і тяжкий, \nПерешкод ніяких не боюся,\nТільки прагну до мети дійти.\n\nКуплет 4\nЗмарнував я все своє багатство,\nВ Рідний Край вертаюсь знову я,\nВірю, що мене прийме мій батько,\nБо вернувсь, як згублена вівця.', '', '', 'ua', NULL, 0, NULL, NULL),
(1306, 795, 'Підняв Він мене з болота гріха', 0, 'Куплет 1\nПідняв Він мене з болота гріха,\nПоставив Він ноги мої на скалі.\n\nПриспів:\nТому я співаю, Йому вся хвала,\nБо Ісус прийшов і підняв Він мене.\n\nКуплет 2\nОдежу мою, як сніг, убілив,\nПростив всі провини і їх віддалив.\n\nПриспів:\nТепер я спасенний, Йому вся хвала,\nСпасенний я кров\'ю Ісуса Христа.\n\nКуплет 3\nВін вічне життя мені обіцяв,\nСказав: ти зі Мною жить будеш в раю.\n\nПриспів: \nВін дав цю надію, Йому вся хвала,\nВона потішає спасенні серця.\n\nКуплет 4\nСпіватиму я у кожний час,\nАж доки Він прийде у славі Своїй.\n\nПриспів: \nЙого я чекаю, Йому вся хвала,\nГряди Ісусе, жде Церква Твоя!', '', '', 'ua', NULL, 0, NULL, NULL),
(1307, 796, 'Бажаю я щоб весь мій дім', 0, 'Куплет 1\\nБажаю я, щоб весь мій дім \\nТобі, о, Господи, служив;\\nТи ж сили дай, щоб в домі цім \\nЯ сам побожно й свято жив.\\n\\nКуплет 2\\nДопоможи в ділах моїх \\nСлужити прикладом для тих,\\nЗ якими я повинен жить,\\nЯких повинен я любить\\n\\nКуплет 3\\nЄдині мрії маю я,\\nЩоб я і вся моя сім\'я \\nСтворили в душах наших храм \\nТвоїм Божественним словам.\\n\\nКуплет 4\\nТобі я щиро віддаю \\nСебе і всю мою сім\'ю; \\nПочуй, о, Господи, молю,\\nІ ласку прояви Свою.', '[{\"nombre\":\"Куплет 1\",\"veces\":1},{\"nombre\":\"Куплет 2\",\"veces\":2},{\"nombre\":\"Куплет 3\",\"veces\":3},{\"nombre\":\"Куплет 4\",\"veces\":4}]', '', 'ua', '', 0, NULL, '2025-07-24'),
(1308, 797, 'Відкриття молитовного дому', 0, 'Куплет 1\nВідкриття молитовного дому \nХай освятить сьогодні Бог Сам,\nЩоб Христова тут Церква у Ньому \nВсе зростала в духовний теж храм.\nХай євангельську правду Господню \nСповіщають в нім слуги Христа;\nХай тут завжди, ось так, як сьогодні, \nВиявляється віра свята!\n\nКуплет 2\nХай знайдуть в цьому домі спасіння \nВсі ті душі, що блудять в гріхах!\nІ щоб правди святої насіння \nРозсівалося в людських серцях!\nХай молитви святим фіміамом \nТут з відкуплених ллються сердець \nДо небесного Божого храму,\nДе у славі царює Творець!\n\nКуплет 3\nХай бринить в цьому домі хваління \nПолум’яних духовних псалмів!\nЗа дароване Богом спасіння \nХай подяки підноситься спів!\nХай же дім цей навіки посвятить \nСам Отець, Син і Дух Твій Святий!\nХай духовно Бог Церкву збагатить,\nЩоб і дім, і народ був святий!', '', '', 'ua', NULL, 0, NULL, NULL),
(1309, 798, 'О Боже ми в Твоє Імя', 0, 'Куплет 1\nО, Боже, ми в Твоє Ім\'я \nТобі присвячуєм дім цей;\nХай завжди вся Твоя сім\'я \nТут бачить лиш Твоє лице.\n\nКуплет 2\nХай в ньому проповідь свята\n Бринить із Біблії до всіх;\nНехай приходять до Христа \nСюди, кого ще мучить гріх.\n\nКуплет 3\nНе це лиш місце, але й нас,\nЯк Твій правдивий Божий храм, \nБлагословляй Ти кожен час,\nАж ми прийдем до вічних брам.\n\nКуплет 4\nЩоб в серці кожному Ти був,\nЩоб Дух Святий там завжди жив, \nЩоб кожен віруючий чув \nТвою присутність, силу, вплив.', '', '', 'ua', NULL, 0, NULL, NULL),
(1310, 799, 'Кров Христа обмила мене', 0, 'Куплет 1\nКров Христа обмила мене (Зр.), обмила мене. \nКров Христа звільнила мене (Зр.), звільнила мене. \nКров Христа зцілила мене (3 р.),зцілила мене. \nАлілуя! Слава Тобі (Зр.), Алілуя!', '', '', 'ua', NULL, 3, '2020-11-29', NULL),
(1311, 800, 'Я не соромлюсь визнавать', 0, 'Куплет 1\nЯ не соромлюсь визнавать воскреслого Христа, \nЙого веління сповіщать і міць Його хреста.\n\nПриспів:\nУ Христі, у Христі я душею ожив,\nУ Христі навіки я прозрів (я прозрів), \nУ Христі спасіння вічне я придбав, \nВіднині щасливий я вже став.\n\nКуплет 2\nЯ не соромлюсь визнавать в Нім Господа мого, \nХто спас мене, дав благодать, і Духа дав Свого.\n\nКуплет 3\nЯ не соромлюся нести зневагу за Христа; \nБлагаю: Боже, всім прости, то - їхня біднота.\n\nКуплет 4\nНе дасть Він сумніву мені при виді зла всього,\nІ не залишить на землі мене Він одного.', '', '', 'ua', NULL, 0, NULL, NULL),
(1312, 801, 'О Боже Твій вогонь', 0, 'Куплет 1\nО, Боже, Твій вогонь священний,\nТвій вогонь, Твій вогонь нам пошли!\nТебе благаємо смиренно:\nТвій вогонь, Твій вогонь нам пошли!\nМоління наших душ прийми, \nСвятим нас Духом наповни\nІ благодаттю осіни!\nТвій вогонь, Твій вогонь нам пошли!\n\nКуплет 2\nГосподь Іллі, Тебе благаєм:\nТвій вогонь, Твій вогонь нам пошли! \nТобі служити ми бажаєм,\nТвій вогонь, Твій вогонь нам пошли! \nСвітильник віри хай горить,\nЖиттям святим бажаєм жить, \nГріховне все нехай згорить,\nТвій вогонь, Твій вогонь нам пошли!\n\nКуплет 3\nУсім холодним і байдужим \nТвій вогонь, Твій вогонь нам пошли! \nЛюбов’ю щоб палали душі - \nТвій вогонь, Твій вогонь нам пошли!\nУ Тебе ласку щоб знайти,\nВсю силу зла перемогти,\nПрожити свято й відійти, - \nТвій вогонь, Твій вогонь нам пошли!\n\nКуплет 4\nСлужіння з радістю звершати - \nТвій вогонь, Твій вогонь нам пошли!\nІ грішних від гріхів звільняти - \nТвій вогонь, Твій вогонь нам пошли! \nНа вівтар Твій кладем себе,\nВсе наше сильне і слабе,\nБажаєм славить лиш Тебе, - \nТвій вогонь, Твій вогонь нам пошли!', '', '', 'ua', NULL, 0, NULL, NULL),
(1313, 802, 'Тихо в Аравії', 0, 'Куплет 1\nТихо в Аравії, росами ранніми \nТам простягається путь.\nЯків з родиною степом-пустинею \nНа батьківщину ідуть.\n\nКуплет 2\nТихо в Аравії, росами ранніми,\nТільки що сонце зійшло.\nЗдалека воїни, страшно озброєні - \nВійсько Ісава ішло.\n\nКуплет 3\nДвадцять років пройшло, - миру як не було; \nБрат був неначе той звір:\nЗ братом зближається, знищить збирається \nЯкова цілий табір.\n\nКуплет 4\nЯків минулу ніч із Богом мав зустріч,\nСерцем своїм сокрушивсь,\nТяжко зітхаючи, Бога благаючи.\nБог його благословив.\n\nКуплет 5\nТихо в Аравії, росами ранніми,\nПоперед війська Ісав.\nЯків кульгаючи, брата стрічаючи,\nСім раз на землю упав.\n\nКуплет 6\nБраття стрічаючись, раптом щось сталося, - \nПеремінився Ісав:\nМеч свій відкинувши, до брата кинувся, \nНіжно його обіймав.\n\nКуплет 7\nПлакали воїни, військо озброєне,\nПлакали діти й жінки.\nБраття мирилися, перемінилися \nЇхні серця і думки.\n\nКуплет 8\nТихо в Аравії, росами ранніми,\nТам простягається путь.\nЯків з родиною степом-пустинею \nДо Ханаану ідуть.', '', '', 'ua', NULL, 0, NULL, NULL),
(1314, 803, 'Настала на світі нежданна тривога', 0, 'Куплет 1\nНастала на світі нежданна тривога,\nНіхто із людей не схотів.\nВсі люди чекають і плачуть, й ридають, - \nНе знають, що Бог так звелів.\n\nКуплет 2\nПовірте ви, люди, добра вже не буде, - \nНа світі ще гірше буде.\nБо вся ця тривога - вона є від Бога,\nІ Бог світ судити прийде.\n\nКуплет 3\nЖнива же доспіли, пішли женці жати \nВеликі Господні лани, \nПшеницю ізжали, кукіль пов’язали, - \nЗостались самі бур’яни.\n\nКуплет 4\nКукіль Господь спалить вогнем невгасимим, \nПшеницю - на тік забере. \nІ радість велика буде на Сіоні,\nКоли наш Спаситель прийде.\n\nКуплет 5\nЩасливі ті люди на світ народились,\nЩо в радість велику ввійдуть.\nНещасні ті люди, що їх там не буде,\nБо муки великі їх ждуть.\n\nКуплет 6\nО, грішнії люди, сьогодні покайтесь, \nЩоб в вічнім вогні не горіть.\nСьогодні усі ви до Бога зближайтесь \nІ більше в житті не грішіть!\n\nКуплет 7\nСьогодні усіх вас Господь закликає:\n“Усі ви до Мене прийдіть.\nЯ прийму вас в Царство Своє віковічне,\nЗі Мною будете ви жить”.\n\nКуплет 8\nІ ті, що почули, - до Бога звернулись:\n“О, Боже, нас, грішних, прости.\nДо Тебе лицем ми своїм повернулись, \nПрийми нас таких, як ми є!”', '', '', 'ua', NULL, 1, '2021-04-09', NULL),
(1315, 804, 'Дяка Богові від нас', 0, 'Куплет 1\nДяка Богові від нас за осінній добрий час!\nВесь врожай зібрали ми перед приходом зими.\nБог дарів нам не жалів, нас врожаєм наділив.\nДяка Богові від нас за осінній добрий час!\n\nКуплет 2\nБожа нива - кожен край, що приносить урожай.\nАле часом ворог сам куколю насіє нам.\nТоді збіжжя добре те разом з куколем росте.\nБоже, нам принести дай лиш пшеничний урожай!\n\nКуплет 3\nЗнаємо, що любий Спас прийде по врожай до нас; \nТож кукіль Він того дня скаже витяти до пня,\nТа спалити на вогні, щоб і слід пропав по нім.\nЗерно ж Богочоловік позбирає - до засік.\n\nКуплет 4\nПрийди ж, Боже, на лани та й серпом Своїм пожни; \nВсіх спасенних позбирай, освяти та оправдай,\nЩоб в присутності Твоїй спокій мали всі святий. \nЖдуть Твої дочки й сини, щоб прийшов Ти на лани!', '', '', 'ua', NULL, 0, NULL, NULL),
(1316, 805, 'Господь ось ми обрали', 0, 'Куплет 1\nГосподь, ось ми обрали служителів Твоїх.\nПро це Тебе благали - Ти показав нам їх.\n\nКуплет 2\nБлагослови служіння Ти вірних слуг Твоїх,\nДай їм Твоє терпіння, щоб успіх був у них.\n\nКуплет 3\nНавчай Ти їх, як дбати, служити як усім,\nБоротись не вгавати на їх шляху земнім.\n\nКуплет 4\nТи їх зроби взірцями для Божих всіх дітей, \nЩоб словом і ділами світили для людей.\n\nКуплет 5\nУ час тривоги й смутку їх духом підкріпляй,\nСвятим благословенням їх рясно наділяй!', '', '', 'ua', NULL, 0, NULL, NULL),
(1317, 806, 'Яке є щастя', 0, 'Куплет 1\nЯке є щастя, що в земній недолі \nЄ добрий Друг, Якому я в тиші \nЗвертаюся в молитві: Господи, прости;\nЗвертаюся в молитві: Нас помилуй \nІ допоможи іти до Царства, Святим Духом підкріпи!\n\nПриспів:\nМи дякуєм Тобі за все!\nЗа сонце, місяць, зорі ясні.\nІсус, Ти все створив для нас,\nЩо нам дає життя прекрасне.\nМи дякуєм Тобі за хрест,\nЗа вічний дім у небі яснім.\nНехай Тобі звучить хвала,\nІ пісня наша хай не згасне!\n\nКуплет 2\nО, мій Спасе, як в житті чудово \nДякувать за все Тобі завжди.\nДякую за хліб, за хліб насущний,\nДякую за мир в краю моїм,\nДякую за милість, що до мене \nУ свій час Ти проявив.', '', '', 'ua', NULL, 0, NULL, NULL),
(1318, 807, 'Блажен хто серцем нелукавий', 0, 'Куплет 1\nБлажен, хто серцем нелукавий!\nТакому Сам Господь відкрив\nШлях до небес в країну слави,\nЩоб він в оселях Божих жив.\nБлажен, хто всю свою надію \nПоклав на Господа Христа.\nТакому завжди серце гріє \nПромінням Біблія Свята.\n\nКуплет 2\nБлажен, хто у молитві щиро \nУміє з Богом розмовлять;\nЗіллється, як запашне миро,\nНа нього Божа благодать.\nБлажен, хто в дні життя земного \nХристовим шляхом правди йде.\nУ Царстві Божому такого\nВелика нагорода жде.', '', '', 'ua', NULL, 0, NULL, NULL),
(1319, 808, 'Юнаком Ти був на світі', 0, 'Куплет 1\nЮнаком Ти був на світі, веселив серця \nІ ходив у заповіті Свойого Отця.\nНаучи і нас покірно дні земнії провести \nІ служити Богу вірно, світло скрізь нести.\n\nКуплет 2\nМатір Ти любив так ніжно, кривди не чинив;\nВ праці Иосифові, рідним ділом Ти служив.\nО, навчи й нас працювати для людей своїх й чужих, \nПравду Божу розсівати всюди, де панує гріх.\n\nКуплет 3\nТи душею був готовий чин святий звершать, \nСповіщав скрізь вічне Слово, Божу благодать.\nО, Учителю ласкавий, вчи й нас правду сповіщать, \nЩоби грішний світ, лукавий, міг Твою любов пізнать.', '', '', 'ua', NULL, 0, NULL, NULL),
(1320, 809, 'Хоч ми слабі', 0, 'Куплет 1\nХоч ми слабі - ми поможем будувати Божий храм; \nВсі надії покладемо на Христа - Він поміч нам. \nЛегкий труд - Він так сказав, - помагати обіцяв.\n\nПриспів:\nО, осанна, Божий Сину!\nОсь бо Він так любить нас;\nСтерегтимем цю святиню, - \nЗ неба даний нам наказ.\n\nКуплет 2\nДуш багато йдуть в погибель шляхом горя і біди;\nГолос Божий всіх скликає: наверніться всі сюди!\nМи ж з Христом, і тільки з Ним, побудуєм Божий дім.\n\nКуплет 3\nЩоби Швидко та усюди видний був духовний храм,\nЩоб спокій, любов Христова відкривалися серцям, \nБоже наш, хай заклик Твій обіймає світ людський!', '', '', 'ua', NULL, 0, NULL, NULL),
(1321, 810, 'Боже чути Слово', 0, 'Куплет 1\nБоже, чути Слово Ти дозволив знову.\nНам яви Твоє лице, освіти несвітле все!\n\nКуплет 2\nЖдем Тебе з дарами миру поміж нами.\nДай нам Духа благодать, серцем дай Тебе прийнять!\n\nКуплет 3\nВихваляйте знову всі Христа живого.\nВін дає життя вінець, Він наш Пастир і Отець!', '', '', 'ua', NULL, 0, NULL, NULL),
(1322, 811, 'В багряниці Син Божий', 0, 'Куплет 1\nВ багряниці Син Божий, в терновім вінці,\nМіцно зв’язані зморені руки.\nСкільки втоми, страждання на світлім лиці,\nСкільки жалю до всіх, скільки муки...\n\nКуплет 2\nТа не тілом лиш терпить Спаситель за нас,\nХоч ганебні й жахливі знущання.\nСтрашні муки душі - знати в той скорбний час,\nЩо не всі приймуть Боже спасіння.\n\nКуплет 3\nПогляд Сина до грішних любов’ю горів,\nСерце ніжно усіх пригортало.\nТа лиш дехто цю Божу любов зрозумів,\nГрішні люди Ісуса розп’яли.\n\nКуплет 4\nТак томився Спаситель і тяжко терпів,\nБеззаконний світ з Бога сміявся.\nТа за тебе, мій друже, Він вмерти схотів \nВін за тебе на муки віддався.\n\nКуплет 5\nДруже мій, не відкинь ти любові Христа,\nНе забудь Його щире бажання!\nО, прийми ж ти спасіння, яке Він придбав,\nОціни Його муки й страждання!', '', '', 'ua', NULL, 0, NULL, NULL),
(1323, 812, 'Христос розпятий на хресті', 0, 'Куплет 1\nХристос, розп\'ятий на хресті за нас страждав,\nВін, повний ласки й доброти, усім прощав.\n\nКуплет 2\nХристос вмирав, а світ над Ним в той час глумивсь,\nВ нестерпних муках Божий Син за люд моливсь.\n\nКуплет 3\nЛюбов небесного Отця світ не пізнав,\nГріхами лютими серця свої скував.\n\nКуплет 4\nХристос, розп\'ятий на хресті за нас вмирав;\nЩоб від загибелі спасти, Він смерть прийняв.', '', '', 'ua', NULL, 0, NULL, NULL),
(1324, 813, 'Діти в Бога і для вас', 0, 'Куплет 1\nДіти, в Бога і для вас труд є всякий час.\nПотрудіться для Нього,- Він заплату дасть.\n\nПриспів:\nОсь я, мій Спаситель, ти мене пошли!\nДай Твій труд звершити, ближнім помогти!\n\nКуплет 2\nВаші рідні і брати помочі скрізь ждуть.\nПоможіть ви їм пройти земну, тяжку путь!\n\nКуплет 3\nЧасу їм свого вділіть, в праці поможіть!\nНе лінуйтесь, поспішіть поміч принести!', '', '', 'ua', NULL, 0, NULL, NULL),
(1325, 814, 'Боже Отче ми до Тебе', 0, 'Куплет 1\nБоже, Отче, ми до Тебе з вірою йдемо,\nЦю сімейную потребу разом несемо.\n\nПриспів:\nБоже, Боже, ось мале дитя,\nУ свої візьми Ти руки все його життя!\n\nКуплет 2\nЦю, ні в чім невинну душу, Боже, стережи\nІ від зла, гріха й спокуси в світі збережи!\n\nКуплет 3\nТак, як Анна Самуїла, це дитя батьки \nУ любові захотіли принести Тобі.', '', '', 'ua', NULL, 0, NULL, NULL);
INSERT INTO `songs` (`id_song`, `song_number`, `title`, `category`, `song_text`, `arr_esquema`, `tune`, `lang`, `notes`, `count`, `created_at`, `updated_at`) VALUES
(1326, 816, 'В Спаса мого на лоні', 0, 'Куплет 1\nВ Спаса мого на лоні, в любих Його руках,\nПісля турбот і праці спічне моя душа.\nНа небесах є радість, тому що я спасен.\nГам жде мене Отець мій; там Він мене прийме.\n\nПриспів:\nВ Спаса мого на лоні, в любих Його руках\nПісля турбот і праці спічне душа моя.\n\nКуплет 2\nВ Спаса мого на лоні, далеко від журби, - \nТам є спокій, безпека, гріху там не ввійти.\nІ ніщо не розлучить тут мене із Христом.\nЯ все готов страждати і йти Його слідом.\n\nКуплет 3\nСпас є моїм притулком, за мій гріх Він умер.\nНа Нього все надіюсь, Він любить все мене. \nТут я терплю й чекаю, поки ще ніч мине.\nЖду аж діждусь, що вічне сонечко нам зійде!', '', '', 'ua', NULL, 0, NULL, NULL),
(1327, 2, 'Христос є скеля вода з якої ллється', 0, 'Куплет1\nХристос є скеля, вода, з якої ллється,\nВода цілюща, що дасть тобі життя.\nХристос є скеля, вода, з якої ллється,\nВода жива, що дасть тобі життя нове.\n\nПриспів: \nЯкщо хтось прагне -\nХай приходить й з неї п’є,\nОсвіжить душу і все єство своє.\nХристос є скеля, вода з якої льється, Вода жива, що дасть тобі життя нове.\n\nКуплет 2\nХристос - лілея на ланах квітучих,\nТроянда біла, свіжа із саду Сарон.\nХристос - життя й любов понад любов’ю,\nВін— Той, що нам Своє спасіння подає.', '', '', 'ua', NULL, 0, NULL, NULL),
(1328, 3, 'Хай не сумує той хто славить Бога', 0, 'Куплет 1\nХай не сумує той, хто славить Бога,\nХай не сумує той, хто прославля Христа.\n\nПриспів: \nТому я співаю, співаю «Алілуя!»\nХай не сумує той, хто прославляв Христа.\n\nКуплет 2\nХай не сумує той, хто вірить в Бога,\nХай не сумує той, хто вірує в Христа.\n\nКуплет 3\nХай не сумує той, хто любить Бога,\nХай не сумує той, хто полюбив Христа.', '', '', 'ua', NULL, 6, '2021-02-28', NULL),
(1329, 6, 'Встає в синім небі зоря', 0, 'Куплет1\nВстає в синім небі зоря,\nІ ранок тріпоче крильми.\nРосою вже вмилась земля,\nРосинки так схожі з слізьми.\n\nКуплет2\nА я молюсь за Україну,\nЩоб сонце Божої любві \nЗігріло землю мою рідну \nПромінням лагідним своїм.\n\nКуплет3\nСкрізь чути чорнобильський дзвін,\nІ плаче в колисці дитя.\nНас шлях до провалля привів,\nВисить, мов на нитці, життя.\n\nКуплет4\nА я молюся за Україну,\nВсміхалось щоби немовля.\nІ кожну мить, кожну хвилину \nТворця щоб славила земля.\n\nКуплет5\nІсусових ніг тихий крок \nВже чує планета уся,\nБо Він є єдиний твій Бог,\nЄдина надія твоя.\n\nКуплет6\nСхились до Бога, Україно,\nІ за любов прослав Творця. \nПрийди до Нього, ненько рідна, \nТобі Він дасть нове життя.', '', '', 'ua', NULL, 0, NULL, NULL),
(1330, 7, 'Сонце місяць зорі й землю', 30, 'Куплет 1\nСонце, місяць, зорі й землю - Бог усе це сотворив.\nІ життя - дарунок неба також Він нам всім послав.\n\nПриспів: \nБог є любов, (2р.) співаємо разом, \nРазом всі - Бог є любов.\n\nКуплет 2\nЩоб життя було спасенне, з неба Сина Він послав.\nНа горі, горі Голгофі в муках Він за нас вмирав.\n\nКуплет 3\nТому в житті своєму буду вдячний Йому я завжди\nЗа зорі, зорі, зорі ясні й небо, небо голубе.', '', '', 'ua', NULL, 1, '2020-11-01', NULL),
(1331, 8, 'Красота Иисуса светись во мне', 0, 'Куплет 1\nКрасота Иисуса, светись во мне!\nЧистота и любовь, проявись вполне!\nДух любви и огня (и огня)\nОживи и меня (и меня),	2р.\nЧтобы образ Иисуса сиял во мне.\n\nКуплет 2\nПусть увидят во мне красоту Христа,\nВсю Его чистоту и любовь всегда.\nО, Дух Божий, приди (приди),\nВсё во мне измени (измени), -	2р.\nПусть увидят во мне красоту Христа.\n\nКуплет 3\nДух Святой, Утешитель, живи во мне,\nБлагодать и обитель Твоя - во мне.\nЧтоб я плод приносил (приносил)\nИ Тебя я любил (я любил),	2р.\nИ вечерю со мною Ты разделил.', '', '', 'ua', NULL, 0, NULL, NULL),
(1332, 9, 'Иисус о Тебе я пою', 0, 'Куплет 1 \nИисус, о Тебе я пою, \nСветом Ты озарил мою душу \nЯ за все благодарен Тебе \nИ во всем вижу я Твою руку.\n\nПрипев\nЗнаю я, Ты всегда со мной, \nВ обещаньи Своем Ты верен, \nКровь Твоя за меня лилась, \nЧтобы в небо открыть мне двери.\n\nКуплет 2 \nСколько раз Ты меня хранил \nНа крутых поворотах жизни \nТы избрал меня, искупил \nИ наполнил Собой мое сердце.\n\nКуплет 3 \nЯ живу и покоюсь в Тебе, \nТы - надежда моя и радость. \nИисус, счастье только в Тебе,\nВ Тебе жизнь моя и отрада.', '', '', 'ua', NULL, 0, NULL, NULL),
(1333, 10, 'В далекі часи минулі часи в краю Палестині', 11, 'Куплет 1\nВ далекі часи, минулі часи в краю Палестині \nЗ\"явилась зоря небесна, вона і сяє донині.\nТо світло для нас приніс любий Спас,\nІ хто хоче взяти - даремно бери,\nТо будеш і ти яскраво палати.\n\nПриспів:\nДо Христа, до Христа поспіши.\nПеред Спасом коліна схили.\nНі дарів, ні скарбів Він не жде.\nСину, серце дай нині своє.\n\nКуплет2\nВ блуканнях моїх нещасних доріг чимало пройшов я.\nТа щастя не мав, коли пропадав далеко від Бога.\nТа ясна зоря, Ісуса Христа,\nВказала дорогу, щоб міг я прийти,\nСпасіння знайти у Бога Святого.\n\nКуплет3\nСьогодні ще раз лунає для вас ця вістка чудова,\nБлаженство знайдеш, коли ти прийдеш \nдо Бога Святого. То ж, друже, спіши,\nСкоріше прийми Спасіння Христове.\nСьогодні прийди, одержиш і ти життя зовсім нове.', '', 'Ре мажор', 'ua', NULL, 0, NULL, NULL),
(1334, 11, 'Радуйтеся усі люди', 0, 'Куплет 1\nРадуйтеся усі люди,\nРадість з неба вам хай буде.\n\nПрипев\nВеселая вам новина:\nНародила Діва Сина, | Марія! (Зр.)\n\nКуплет 2\nЗійшов до нас з високості \nТой, що всі гріхи нам простить.\n\nКуплет 3\nДо ясел всі поспішаймо,\nСлаву й честь Йому віддаймо.\n\nКуплет 4\nБудьмо щирі та багаті\nНа добро завжди завзяті.', '', '', 'ua', NULL, 0, NULL, NULL),
(1335, 13, 'Ой зійшла зійшла Правда на землю', 0, 'Куплет 1\nОй, зійшла, зійшла Правда на землю\nІ пробуває між людьми.\nВсе сповістила, що треба людям;\nЯк треба жить, як Бог велить.\n\nПриспів: \nДе ж тая Правда, звідки з’явилась,\nДе ж вона нині на світі є?\nТам в Вифлеємі в яслах родилась,\nА тепер в вірних серцях живе.\n\nКуплет2\nІ Дух Святої Правди із неба,\nНині шукає в серцях ясел,\nДо б поселитись, щоби родити\nОвочі правди в життю людей.\n\nКуплет3\nІ в кому знайде місце для себе, \nТам запанує радість життя; \nТому дарує місце на небі,\nЩе й допоможе нести хреста.\n\nКуплет4\nXристос є Правда, Христос є Світло, \nХристос є Хліб Життя для нас.\nО, якби люди з усього світу\nПрийшли до Нього, — Він би їх спас.', '', '', 'ua', NULL, 0, NULL, NULL),
(1336, 14, 'Вот идет Царь царей за невестой Своей', 0, 'Куплет 1\nВот идет Царь царей за невестой Своей\nС высоты лучезарных небес,\nЧтобы взять от земли всех, кто любит и ждет, \nЗа кого пострадал Он и воскрес.\n\nПриспів\nИ на белых облаках, позабыв печаль и страх,\nБудем новую песню мы петь.\nТам, где грусти места нет, где сияет вечный свет,\nГде на каждый вопрос найду я ответ.\n\nКуплет 2\nВот идет Царь царей, чтобы стало теплей,\nНа земле, где мороз царят.\nВсякий жаждущий пей правду жизни святой\nВремя в ногу идти! Друг мой, не стой!', '', '', 'ua', NULL, 0, NULL, NULL),
(1337, 18, 'Господи Ти надія у житті', 30, 'Куплет 1\nГосподи, Ти - надія у житті.\nІ в Тобі всі джерела доброти!\nВ тіні крил Твоїх заспокоюсь я,\nТам душа відпочине моя.\n\nПриспів\nМир і спокій(2р.)\nВ тіні крил Твоїх Святих!\n\nКуплет 2\nСкільки в світі не пускав лукавий стріл,\nЯ сховаюсь у тіні Твоїх крил.\nТам панують любов і мир святий,\nБудь зі мною завжди, Боже мій.', '', '', 'ua', NULL, 4, '2021-03-28', NULL),
(1338, 2, 'Подивися навкруги на красу землі своєї', 30, 'Куплет 1\nПодивися навкруги, на красу землі своєї.\nВсе це Бог наш сотворив силою руки своєї.\nВін один так полюбив, що віддав нам свого Сина.\nМилість Бог свою явив, щоб спаслася Україна.\n\nПриспів:\nМи молим за свій край,\nСпасіння людям дай.\nМи Тебе благаєм.\n\nКуплет 2\nЛюбов свою яви,\nГосподь, благослови\nНашу Україну.\n\nКуплет 3\nБоже єдності нам дай, навчи любити і прощати.\nВ згоді Господа Христа будем разом прославляти.\nТи один так полюбив, що віддав нам свого Сина.\nМилість нам свою явив, щоб спаслася Україна.', '', '', 'ua', NULL, 2, '2021-04-11', NULL),
(1339, 3, 'Эрусалим що сходить з неба', 0, 'Куплет 1\nЄрусалим, що сходить з неба\nВ проміннях ясних свого Царя,\nТам більше сонця вже не потрібно, \nБо Агнець Божий -  рання зоря.\n\nПрипев\nОце оселя свята Бога з людьми,\nДе будем жити із Богом ми.\nТам усі сльози Ісус з очей зітре.\nСмерті не буде, біль промине.\n\nКуплет 2\nЄрусалим! Нове це місто,\nПерлинні брами відкриті в нім.\nХто прагне пити - нехай приходить, -\nДжерельні води течуть у нім.\n\nКуплет3\nЄрусалим! Тебе кохаю.\nВ тобі панує вічна любов.\nСпасенні люди в тобі зійдуться.\nПрославлять Спаса за  Його кров.', '', '', 'ua', NULL, 2, '2020-10-30', NULL),
(1340, 6, 'ты ждешь когда', 30, 'Куплет 1\nТы ждешь, когда я приду к Тебе\nТакой как есть\n\nПрипев\nПечать Твоей любви в сердце моем\nНавеки и навсегда\nКак велика Твоя любовь\nРевность как летящая стрела\n\nКуплет 2\nПриди огнем Своим, Господь,\nСожги мой грех, омой меня\nПриди огнём Своим, Господь,\nИ будем вместе Ты и я\n\nПрипев\nБольше не хочу говорить я\nИ в ночной темноте\nЛишь смотреть на Тебя хочу,\nТолько петь Тебе.', '', '', 'ua', NULL, 1, '2021-04-09', NULL),
(1341, 7, 'Год прошёл', 0, 'Куплет 1\nГод прошёл и снова собрались друзья,\nСнова добрым словом ободрят меня.\nТак за годом год пройдёт, как лёгкий дым,\nВсё пройдёт, и радость, горе вместе с ним.\n\nПрипев:\nИ тогда вернётся снова весна,\nВсе мы соберёмся у ног Христа.\nИ тогда не будем годы считать,\nИ не будем страдать.\n\nКуплет 2\nСколько дней мы будем радости иметь, \nСколько дней мы будем в горе скорбеть?\nМы не знаем, только будь ты со Христом \nИ борись всегда, всегда борись со злом.\n\nКуплет 3\nСколько зла на свете, но ты добрым будь, \nЛюдям приноси добра хотя чуть-чуть. \nРасцветут прекрасны на пути цветы \nИ расскажут нам о радости они.', '', '', 'ua', NULL, 0, NULL, NULL),
(1342, 8, 'Под бичём кровавого удара', 30, 'Куплет 1\nПод бичём кровавого удара,\nНа плечах со взваленным крестом, \nШёл в толпе, тернистый путь свершая, \nЖизнедатель, Пастырь и Господь.\n\nКуплет 2\nПод крестом Он, весь изнемогая \nОт толчков, на землю падал Он,\nПо земле, святую кровь роняя, \nI был поднят бичём, и снова шёл.\n\nКуплет 3\nНо толпа страданьям не внимала,\nТолько Мать, скорбящая душой, \nШла за Ним и слёзы проливала,  \nРоковой подавлена тоской.\n\nКуплет 4\nТак тяжёлый путь свой совершая, \nТяжкий крест Он на Голгофу нёс.\nИ на нём Он умер там, страдая, \nДля того, чтоб грешник был спасен', '', '', 'ua', NULL, 1, '2020-11-15', NULL),
(1343, 11, 'Дивный Спаситель прекрасный', 30, 'Куплет 1\nДивный Спаситель, прекрасный,\nНаш Искупитель и Друг.\nКто мог подумать, что Агнец\nМог искупить нас от мук,\nМог искупить нас от мук?\n\nКуплет 2\nСторож души и Советник,\nДух Твой мы жаждем вдохнуть.\nНовой надеждой Ты светишь,\nЕсли теряем мы путь,\nЕсли теряем мы путь.\n\nПриспів\n// Ты – Тот, Кого прославляем,\nТот, Кого любим всегда.\nДай исцеление и милость\nНашим голодным сердцам,\nНашим голодным сердцам. // - 2р.\n\nКуплет 3\nВечный Отец Всемогущий,\nВерно Ты любишь Своих,\nВ слабости к Трону идущих,\nЧтобы у ног пасть Твоих,\nЧтобы у ног пасть Твоих.', '', '', 'ua', NULL, 0, NULL, NULL),
(1344, 12, 'А нас манят ', 0, 'Verse 1\nМеня манят к себе небеса, от земного хочу оторваться. \nЛишь не легкой бы быть на весах, чтоб навеки во тьме не остаться.\nЖизнь должна добродетельной быть, доброй кроткой смирёной и верной.  \nМы должны всеx прощать и любить, не смотря на гоненья и терни. \n\nПрипев:\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\nА нас манят к себе небеса мы хотим от земли оторваться\nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\n\nVerse 2 куплет:\nКак легко о делах говорить, но а в жизнь воплотить их не просто,\nДай нам Боже для ближнего жить, дай нам сил для духовного роста.\nЗабываем порой небеса, суета завладеет сознаньем.\nО открой нам спаситель глаза, и наполни ты их покаяньем.\n\nПрипев:\nА нас манят к себе небеса мы хотим от земли оторваться \nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\nА нас манят к себе небеса мы хотим от земли оторваться     \nВзвесим жизнь на Христовых весах чтобы в небе с Христом повстречаться\n\nVerse 3 дополнительный\nПоднимите глаза в небеса, в небе дом наш и наша отчизна,\nВ своём сердце Христу дверь открыв, навсегда чтобы Он в нём поселился.\nПтицы стаями в небо летят, доверяясь во всём лишь на жатву.\nНам пример они свой оставляют, доверятся во всём только Богу.', '', '', 'ua', NULL, 0, NULL, NULL),
(1345, 14, 'Дух Святой, дорогой Как глубока Твоя любовь', 0, 'Verse 1\nКак глубока Твоя любовь, и прощение наш покров.\nТы наш свет и наш покой, упование, Бог Святой.\n\nVerse2\nТвоя милость велика, Твоя правда высока,\nТвоя сильная рука нас ведет издалека.\n\nRefrain 1\nДух Святой, дорогой, драгоценный Дух Святой,\nНаполняй сердца славою Отца.\nДух Святой, дорогой, драгоценный Дух Святой,\nОсвящай и веди за Собой.\n\nVerse 1\nО сколько раз я был во мгле но рука Твоя была со мной\nВ долине скорби на земле ничего не боюсь я с Тобой', '', '', 'ua', NULL, 1, '2020-10-23', NULL),
(1346, 15, ' Кров Христа за мене У стражданнях і тузі', 0, 'Verse 1\nУ стражданнях і тузі наш Господь був на хресті,\nВін поніс туди всі болі і гріхи.\nВін – Предвічний і Святий всіх людей так полюбив,\nСвою кров за всіх людей Він проливав.\n\nПриспів:\nЗнаєш Кров Христа за мене теж лилась,\nКров Христа захистить моє  життя!\nКров Христа – омиває від гріха,\nСила, що рятує нас – кров Христа, кров Христа!\n\nVerse 2\nІ немов мале Ягня, став Він жертвою за нас,\nЙого кров з хреста лилася за людей.\nКров змиває всі гріхи і рятує від діл тьми,\nКожен день, в молитві, кличу до Христа!', '', '', 'ua', NULL, 1, '2020-10-25', NULL),
(1347, 16, 'Ісусе Ти Спас мій Богові слава', 0, 'Куплет 1\nІсусе, Ти – Спас мій, немає  такого, як Ти,\nВсі  дні мої тут на землі хочу прославлять Тебе.\nПритулок, твердиня, захист від лиха та зла\nЯ буду співать, Тебе прославлять,\nПоки буду жити на землі.\n\nКуплет 2\nБогові слава! Вся земле, співай,\nЧесть і хвалу ти для Бога віддай,\nВклоняються гори, шумить водопад\nНад іменням дивним Твоїм.\nРадісну пісню співаю Тобі,\nНавіки прославлю, навіки я Твій,\nНемає на світі того, що я маю в Тобі!', '', '', 'ua', NULL, 6, '2021-03-21', NULL),
(1348, 17, 'Я дякую Тобі', 0, 'Verse 1\nЯ дякую Тобі мій Бог за очі,\nЯкими бачу все, що Ти створив.\nЯ знаю тих, для кого дні як ночі,\nХто бачить сонце тільки в хвилях снів.\n\nVerse 2\nЯ дякую тобі мій Бог за руки,\nЯкими можу я тримати хліб,\nВтирать сльозу в печальний час розлуки,\nІ працювати можу на землі.\n\nRefrain 3\nЯ дякую Тобі, я дякую Тобі,\nПрийми Господь подяку,\nЯ радуюсь в Тобі, я радуюсь в Тобі,\nПрийми Господь подяку.\n\nVerse 4\nЯ дякую Тобі, мій Бог, за маму\nЗа мирне небо, світлі почуття,\nНавчи нас Боже щирими устами\nТебе хвалити все своє життя.\n\nVerse 5\nЯ дякую Тобі мій Бог за очі,\nЯкими бачу все, що Ти створив.\nХвалити прагну, дякувати хочу,\nА Ти до мого серця говори.', '', '', 'ua', NULL, 4, '2020-11-08', NULL),
(1349, 18, 'Нехай Бог Благословить  І помилує тебе', 0, 'Verse 1\nНехай Бог Благословить \nТебе і береже\nХай оберне на тебе Господь\nСвітле лице своє\n\nRefrain\nІ помилує тебе\nПоверне Господь лице своє\nНа тебе і дасть тобі\nСвій мир.\n\nVerse 2\nХай благословить, тебе Господь\nІ дасть тобі Свій мир.', '', '', 'ua', NULL, 4, '2021-04-04', NULL);
